# 1.11. Lightweight structural protocols
# -----------------------------------------------------------------------------

@runtime_checkable
class SupportsToDict(Protocol):
    """Object exposing a dictionary representation."""

    def to_dict(self) -> Mapping[str, Any]:
        """Return a mapping representation."""


@runtime_checkable
class SupportsMetadata(Protocol):
    """Object exposing mutable or immutable metadata."""

    @property
    def metadata(self) -> Any:
        """Return metadata associated with the object."""


@runtime_checkable
class SupportsFiles(Protocol):
    """Object exposing generated or associated files."""

    @property
    def files(self) -> Any:
        """Return the file collection."""


@runtime_checkable
class SupportsStatistics(Protocol):
    """Object exposing analysis statistics."""

    @property
    def statistics(self) -> Any:
        """Return statistics associated with the object."""


@runtime_checkable
class SupportsInteractions(Protocol):
    """Object exposing interaction results."""

    @property
    def interactions(self) -> Any:
        """Return interaction results associated with the object."""


@runtime_checkable
class SupportsCancellation(Protocol):
    """Object exposing cooperative cancellation state."""

    def is_cancelled(self) -> bool:
        """Return whether execution has been cancelled."""


@runtime_checkable
class SupportsProgressUpdate(Protocol):
    """Object capable of receiving progress updates."""

    def update(
        self,
        stage: str,
        completed: int,
        total: int,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> Any:
        """Receive one progress update."""


