# 2.15. Stage and family inspection helpers
# -----------------------------------------------------------------------------


def stage_sort_key(value: Any) -> Tuple[int, str]:
    """Return a stable pipeline-order key for one stage name."""

    name = canonicalize_stage_name(value, strict=False)
    return (PIPELINE_STAGE_INDEX.get(name, len(PIPELINE_STAGE_ORDER)), name)


def is_known_stage(value: Any) -> bool:
    """Return whether a value resolves to a known pipeline stage."""

    try:
        return canonicalize_stage_name(value, strict=False) in KNOWN_PIPELINE_STAGES
    except (TypeError, ValueError):
        return False


def is_interaction_stage(value: Any) -> bool:
    """Return whether a stage performs interaction analysis."""

    try:
        return canonicalize_stage_name(value) in INTERACTION_STAGES
    except (TypeError, ValueError):
        return False


def is_output_stage(value: Any) -> bool:
    """Return whether a stage produces an optional output artifact."""

    try:
        return canonicalize_stage_name(value) in OUTPUT_STAGES
    except (TypeError, ValueError):
        return False


def get_stage_dependencies(
    value: Any,
    *,
    include_ordering: bool = False,
) -> Tuple[str, ...]:
    """Return hard dependencies and optional ordering predecessors."""

    name = canonicalize_stage_name(value)
    dependencies = list(STAGE_DEPENDENCIES.get(name, ()))
    if include_ordering:
        dependencies.extend(STAGE_ORDERING_PREDECESSORS.get(name, ()))

    ordered: List[str] = []
    seen: Set[str] = set()
    for dependency in dependencies:
        if dependency == name or dependency in seen:
            continue
        ordered.append(dependency)
        seen.add(dependency)
    ordered.sort(key=stage_sort_key)
    return tuple(ordered)


def get_stage_required_modules(value: Any) -> Tuple[str, ...]:
    """Return internal modules required by one pipeline stage."""

    name = canonicalize_stage_name(value)
    return STAGE_REQUIRED_MODULES.get(name, ())


def interaction_family_to_stage(value: Any) -> str:
    """Return the analysis stage associated with an interaction family."""

    family = canonicalize_interaction_family(value)
    return INTERACTION_FAMILY_TO_STAGE[family]


def interaction_family_to_dock_model_field(value: Any) -> str:
    """Return the DockModel field associated with an interaction family."""

    family = canonicalize_interaction_family(value)
    return DOCK_MODEL_INTERACTION_FIELDS[family]

# 2.16. Convention validation
# -----------------------------------------------------------------------------


def validate_pipeline_conventions(*, raise_on_error: bool = True) -> Tuple[str, ...]:
    """Validate Section 2 constants and return detected issues."""

    issues: List[str] = []

    if len(PIPELINE_STAGE_ORDER) != len(set(PIPELINE_STAGE_ORDER)):
        issues.append("PIPELINE_STAGE_ORDER contains duplicate names.")

    if set(PIPELINE_STAGE_INDEX) != set(PIPELINE_STAGE_ORDER):
        issues.append("PIPELINE_STAGE_INDEX does not match PIPELINE_STAGE_ORDER.")

    if set(STAGE_DEPENDENCIES) != set(PIPELINE_STAGE_ORDER):
        issues.append("STAGE_DEPENDENCIES does not define every pipeline stage.")

    if set(STAGE_REQUIRED_MODULES) != set(PIPELINE_STAGE_ORDER):
        issues.append("STAGE_REQUIRED_MODULES does not define every pipeline stage.")

    for stage, dependencies in STAGE_DEPENDENCIES.items():
        if stage in dependencies:
            issues.append(f"Stage {stage!r} depends on itself.")
        unknown = set(dependencies).difference(KNOWN_PIPELINE_STAGES)
        if unknown:
            issues.append(
                f"Stage {stage!r} has unknown dependencies: {sorted(unknown)!r}."
            )

    for stage, predecessors in STAGE_ORDERING_PREDECESSORS.items():
        if stage not in KNOWN_PIPELINE_STAGES:
            issues.append(f"Unknown ordering stage {stage!r}.")
        unknown = set(predecessors).difference(KNOWN_PIPELINE_STAGES)
        if unknown:
            issues.append(
                f"Stage {stage!r} has unknown ordering predecessors: "
                f"{sorted(unknown)!r}."
            )

    for alias, target in STAGE_ALIASES.items():
        if _normalize_convention_token(alias, field_name="stage alias") != alias:
            issues.append(f"Stage alias {alias!r} is not normalized.")
        if target not in KNOWN_PIPELINE_STAGES:
            issues.append(f"Stage alias {alias!r} targets unknown stage {target!r}.")

    for alias, target in INTERACTION_FAMILY_ALIASES.items():
        if target not in KNOWN_INTERACTION_FAMILIES:
            issues.append(
                f"Interaction alias {alias!r} targets unknown family {target!r}."
            )

    for alias, target in PI_SUBTYPE_ALIASES.items():
        if target not in PI_INTERACTION_SUBTYPES:
            issues.append(
                f"Pi subtype alias {alias!r} targets unknown subtype {target!r}."
            )

    if set(DOCK_MODEL_INTERACTION_FIELDS) != set(INTERACTION_FAMILY_ORDER):
        issues.append(
            "DOCK_MODEL_INTERACTION_FIELDS does not define every interaction family."
        )

    if set(DOCK_MODEL_PI_KEYS) != set(PI_INTERACTION_SUBTYPES):
        issues.append("DOCK_MODEL_PI_KEYS does not define every pi subtype.")

    if len(INTEGRATED_RESULT_KEYS) != len(set(INTEGRATED_RESULT_KEYS)):
        issues.append("INTEGRATED_RESULT_KEYS contains duplicate keys.")

    if len(KNOWN_FILE_KEYS) != len(set(KNOWN_FILE_KEYS)):
        issues.append("KNOWN_FILE_KEYS contains duplicate keys.")

    result = tuple(issues)
    if result and raise_on_error:
        raise RuntimeError("Invalid analysis pipeline conventions: " + " ".join(result))
    return result


