# 3.1. Status and issue enumerations
# -----------------------------------------------------------------------------


class AnalysisStatus(str, Enum):
    """High-level lifecycle state of an analysis run."""

    PENDING = "pending"
    PREPARING = "preparing"
    RUNNING = "running"
    PARTIAL = "partial"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    CANCELLED = "cancelled"
    SKIPPED = "skipped"


class StageStatus(str, Enum):
    """Lifecycle state of one pipeline stage."""

    PENDING = "pending"
    READY = "ready"
    RUNNING = "running"
    PARTIAL = "partial"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    SKIPPED = "skipped"
    BLOCKED = "blocked"
    CANCELLED = "cancelled"


class IssueSeverity(IntEnum):
    """Severity assigned to diagnostics, warnings and errors."""

    DEBUG = 10
    INFO = 20
    WARNING = 30
    ERROR = 40
    CRITICAL = 50


class IssueKind(str, Enum):
    """Canonical category of an analysis issue."""

    MESSAGE = "message"
    WARNING = "warning"
    ERROR = "error"
    CANCELLATION = "cancellation"


class RecoveryAction(str, Enum):
    """Recommended action after an issue is recorded."""

    NONE = "none"
    RETRY = "retry"
    FALLBACK = "fallback"
    SKIP_STAGE = "skip_stage"
    CONTINUE_PARTIAL = "continue_partial"
    ABORT_RUN = "abort_run"


class FailureScope(str, Enum):
    """Smallest execution scope affected by an issue."""

    STAGE = "stage"
    POSE = "pose"
    BATCH_ITEM = "batch_item"
    BATCH = "batch"
    RUN = "run"
    ENVIRONMENT = "environment"


