# 3.3. Exception hierarchy
# -----------------------------------------------------------------------------


class AnalysisError(Exception):
    """Base exception for all orchestration failures."""

    default_code: str = "analysis_error"
    default_recoverable: bool = False
    default_scope: FailureScope = FailureScope.RUN
    default_action: RecoveryAction = RecoveryAction.ABORT_RUN

    def __init__(
        self,
        message: str = "Analysis execution failed.",
        *,
        code: Optional[str] = None,
        stage: Optional[str] = None,
        recoverable: Optional[bool] = None,
        scope: Union[FailureScope, str, None] = None,
        action: Union[RecoveryAction, str, None] = None,
        details: Optional[Mapping[str, Any]] = None,
        cause: Optional[BaseException] = None,
    ) -> None:
        text = str(message).strip() or "Analysis execution failed."
        super().__init__(text)
        self.message = text
        self.code = _normalize_issue_code(code or self.default_code)
        self.stage = _normalize_optional_stage(stage)
        self.recoverable = (
            self.default_recoverable
            if recoverable is None
            else bool(recoverable)
        )
        self.scope = canonicalize_failure_scope(
            self.default_scope if scope is None else scope
        )
        self.action = canonicalize_recovery_action(
            self.default_action if action is None else action
        )
        self.details = dict(details or {})
        self.cause = cause
        if cause is not None:
            self.__cause__ = cause

    def to_issue(
        self,
        *,
        severity: Optional[Union[IssueSeverity, str, int]] = None,
        source: Optional[str] = None,
        include_traceback: bool = False,
    ) -> "AnalysisIssue":
        """Convert the exception into a structured issue."""

        return exception_to_issue(
            self,
            severity=severity,
            source=source,
            include_traceback=include_traceback,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready exception representation."""

        data: Dict[str, Any] = {
            "type": type(self).__name__,
            "message": self.message,
            "code": self.code,
            "stage": self.stage,
            "recoverable": self.recoverable,
            "scope": self.scope.value,
            "action": self.action.value,
            "details": dict(self.details),
        }
        if self.cause is not None:
            data["cause_type"] = type(self.cause).__name__
            data["cause_message"] = str(self.cause)
        return data


