# 3.4. Warning hierarchy
# -----------------------------------------------------------------------------


class AnalysisWarning(UserWarning):
    """Base warning carrying structured orchestration context."""

    default_code: str = "analysis_warning"
    default_recoverable: bool = True

    def __init__(
        self,
        message: str,
        *,
        code: Optional[str] = None,
        stage: Optional[str] = None,
        recoverable: Optional[bool] = None,
        details: Optional[Mapping[str, Any]] = None,
        source: Optional[str] = None,
    ) -> None:
        text = str(message).strip() or "Analysis warning."
        super().__init__(text)
        self.message = text
        self.code = _normalize_issue_code(code or self.default_code)
        self.stage = _normalize_optional_stage(stage)
        self.recoverable = (
            self.default_recoverable
            if recoverable is None
            else bool(recoverable)
        )
        self.details = dict(details or {})
        self.source = _normalize_optional_text(source)

    def to_issue(self) -> "AnalysisIssue":
        """Convert the warning into a structured issue."""

        return AnalysisIssue(
            kind=IssueKind.WARNING,
            severity=IssueSeverity.WARNING,
            code=self.code,
            message=self.message,
            stage=self.stage,
            source=self.source,
            warning_type=type(self).__name__,
            recoverable=self.recoverable,
            action=RecoveryAction.CONTINUE_PARTIAL,
            scope=FailureScope.STAGE if self.stage else FailureScope.RUN,
            details=self.details,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready warning representation."""

        return self.to_issue().to_dict()


