# 3.5. Structured issue representation
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisIssue:
    """Serializable diagnostic, warning, error or cancellation record."""

    kind: Union[IssueKind, str] = IssueKind.MESSAGE
    severity: Union[IssueSeverity, str, int] = IssueSeverity.INFO
    code: str = "analysis_message"
    message: str = ""
    stage: Optional[str] = None
    source: Optional[str] = None
    exception_type: Optional[str] = None
    warning_type: Optional[str] = None
    recoverable: bool = True
    action: Union[RecoveryAction, str] = RecoveryAction.NONE
    scope: Union[FailureScope, str] = FailureScope.RUN
    details: Mapping[str, Any] = field(default_factory=dict)
    traceback_text: Optional[str] = None
    created_at: str = field(default_factory=lambda: _utc_timestamp())

    def __post_init__(self) -> None:
        object.__setattr__(self, "kind", canonicalize_issue_kind(self.kind))
        object.__setattr__(
            self,
            "severity",
            canonicalize_issue_severity(self.severity),
        )
        object.__setattr__(self, "code", _normalize_issue_code(self.code))
        object.__setattr__(self, "message", str(self.message).strip())
        object.__setattr__(self, "stage", _normalize_optional_stage(self.stage))
        object.__setattr__(self, "source", _normalize_optional_text(self.source))
        object.__setattr__(
            self,
            "exception_type",
            _normalize_optional_text(self.exception_type),
        )
        object.__setattr__(
            self,
            "warning_type",
            _normalize_optional_text(self.warning_type),
        )
        object.__setattr__(self, "recoverable", bool(self.recoverable))
        object.__setattr__(
            self,
            "action",
            canonicalize_recovery_action(self.action),
        )
        object.__setattr__(
            self,
            "scope",
            canonicalize_failure_scope(self.scope),
        )
        object.__setattr__(self, "details", MappingProxyType(dict(self.details)))
        object.__setattr__(
            self,
            "traceback_text",
            _truncate_traceback_text(self.traceback_text),
        )
        object.__setattr__(
            self,
            "created_at",
            str(self.created_at).strip() or _utc_timestamp(),
        )

    @property
    def is_error(self) -> bool:
        """Return whether this issue represents an error."""

        return self.kind in {IssueKind.ERROR, IssueKind.CANCELLATION}

    @property
    def is_warning(self) -> bool:
        """Return whether this issue represents a warning."""

        return self.kind is IssueKind.WARNING

    @property
    def is_critical(self) -> bool:
        """Return whether this issue has critical severity."""

        return self.severity >= IssueSeverity.CRITICAL

    def summary(self) -> str:
        """Return a concise human-readable representation."""

        prefix = f"[{self.stage}] " if self.stage else ""
        return f"{prefix}{self.code}: {self.message}".strip()

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready mapping."""

        return {
            "kind": self.kind.value,
            "severity": self.severity.name.lower(),
            "severity_level": int(self.severity),
            "code": self.code,
            "message": self.message,
            "stage": self.stage,
            "source": self.source,
            "exception_type": self.exception_type,
            "warning_type": self.warning_type,
            "recoverable": self.recoverable,
            "action": self.action.value,
            "scope": self.scope.value,
            "details": dict(self.details),
            "traceback": self.traceback_text,
            "created_at": self.created_at,
        }

# 3.6. Normalization helpers
# -----------------------------------------------------------------------------

_ISSUE_CODE_PATTERN: Final[re.Pattern[str]] = re.compile(r"[^a-z0-9_]+")


def _normalize_status_token(value: Any, *, field_name: str) -> str:
    """Normalize a token used by status and issue enumerations."""

    if isinstance(value, Enum):
        value = value.value
    text = str(value).strip().lower()
    text = re.sub(r"[\s\-./]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    if not text:
        raise ValueError(f"{field_name} cannot be empty.")
    return text


def _normalize_issue_code(value: Any) -> str:
    """Return a stable lowercase issue code."""

    text = _normalize_status_token(value, field_name="issue code")
    text = _ISSUE_CODE_PATTERN.sub("_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    if not text:
        raise ValueError("Issue code cannot be empty after normalization.")
    return text[:MAX_IDENTIFIER_LENGTH]


def _normalize_optional_text(value: Any) -> Optional[str]:
    """Return stripped text or ``None`` for an empty value."""

    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _normalize_optional_stage(value: Any) -> Optional[str]:
    """Normalize a stage name while accepting extension stages."""

    text = _normalize_optional_text(value)
    if text is None:
        return None
    try:
        return canonicalize_stage_name(text)
    except ValueError:
        return _normalize_status_token(text, field_name="stage")


def _utc_timestamp() -> str:
    """Return a timezone-aware UTC timestamp."""

    return datetime.now(timezone.utc).isoformat(timespec=DEFAULT_DATETIME_TIMESPEC)


def _truncate_traceback_text(value: Any) -> Optional[str]:
    """Normalize and safely truncate traceback text."""

    text = _normalize_optional_text(value)
    if text is None:
        return None
    if len(text) <= MAX_ERROR_TRACEBACK_CHARACTERS:
        return text
    suffix = "\n... traceback truncated ..."
    keep = max(0, MAX_ERROR_TRACEBACK_CHARACTERS - len(suffix))
    return text[:keep] + suffix


def canonicalize_analysis_status(value: Any) -> AnalysisStatus:
    """Return the canonical analysis status for ``value``."""

    if isinstance(value, AnalysisStatus):
        return value
    token = _normalize_status_token(value, field_name="analysis status")
    try:
        return ANALYSIS_STATUS_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown analysis status: {value!r}.") from exc


def canonicalize_stage_status(value: Any) -> StageStatus:
    """Return the canonical stage status for ``value``."""

    if isinstance(value, StageStatus):
        return value
    token = _normalize_status_token(value, field_name="stage status")
    try:
        return STAGE_STATUS_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown stage status: {value!r}.") from exc


def canonicalize_issue_severity(value: Any) -> IssueSeverity:
    """Return the canonical issue severity for ``value``."""

    if isinstance(value, IssueSeverity):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        try:
            return IssueSeverity(value)
        except ValueError as exc:
            raise ValueError(f"Unknown issue severity level: {value!r}.") from exc
    token = _normalize_status_token(value, field_name="issue severity")
    try:
        return ISSUE_SEVERITY_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown issue severity: {value!r}.") from exc


def canonicalize_issue_kind(value: Any) -> IssueKind:
    """Return the canonical issue kind for ``value``."""

    if isinstance(value, IssueKind):
        return value
    token = _normalize_status_token(value, field_name="issue kind")
    try:
        return ISSUE_KIND_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown issue kind: {value!r}.") from exc


def canonicalize_recovery_action(value: Any) -> RecoveryAction:
    """Return the canonical recovery action for ``value``."""

    if isinstance(value, RecoveryAction):
        return value
    token = _normalize_status_token(value, field_name="recovery action")
    try:
        return RECOVERY_ACTION_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown recovery action: {value!r}.") from exc


def canonicalize_failure_scope(value: Any) -> FailureScope:
    """Return the canonical failure scope for ``value``."""

    if isinstance(value, FailureScope):
        return value
    token = _normalize_status_token(value, field_name="failure scope")
    try:
        return FAILURE_SCOPE_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown failure scope: {value!r}.") from exc

# 3.7. Status inspection and transition helpers
# -----------------------------------------------------------------------------


def is_terminal_analysis_status(value: Any) -> bool:
    """Return whether an analysis status is terminal."""

    return canonicalize_analysis_status(value) in ANALYSIS_TERMINAL_STATUSES


def is_success_analysis_status(value: Any) -> bool:
    """Return whether an analysis status preserves useful results."""

    return canonicalize_analysis_status(value) in ANALYSIS_SUCCESS_STATUSES


def is_failure_analysis_status(value: Any) -> bool:
    """Return whether an analysis status denotes failure or cancellation."""

    return canonicalize_analysis_status(value) in ANALYSIS_FAILURE_STATUSES


def is_terminal_stage_status(value: Any) -> bool:
    """Return whether a stage status is terminal."""

    return canonicalize_stage_status(value) in STAGE_TERMINAL_STATUSES


def is_success_stage_status(value: Any) -> bool:
    """Return whether a stage status preserves useful results."""

    return canonicalize_stage_status(value) in STAGE_SUCCESS_STATUSES


def is_failure_stage_status(value: Any) -> bool:
    """Return whether a stage status denotes failure, blocking or cancellation."""

    return canonicalize_stage_status(value) in STAGE_FAILURE_STATUSES


def can_transition_analysis_status(current: Any, target: Any) -> bool:
    """Return whether an analysis status transition is allowed."""

    current_status = canonicalize_analysis_status(current)
    target_status = canonicalize_analysis_status(target)
    if current_status is target_status:
        return True
    return target_status in ANALYSIS_STATUS_TRANSITIONS[current_status]


def can_transition_stage_status(current: Any, target: Any) -> bool:
    """Return whether a stage status transition is allowed."""

    current_status = canonicalize_stage_status(current)
    target_status = canonicalize_stage_status(target)
    if current_status is target_status:
        return True
    return target_status in STAGE_STATUS_TRANSITIONS[current_status]


def validate_analysis_status_transition(
    current: Any,
    target: Any,
    *,
    raise_on_error: bool = True,
) -> bool:
    """Validate an analysis status transition."""

    current_status = canonicalize_analysis_status(current)
    target_status = canonicalize_analysis_status(target)
    valid = can_transition_analysis_status(current_status, target_status)
    if not valid and raise_on_error:
        raise AnalysisStatusTransitionError(
            (
                "Invalid analysis status transition from "
                f"{current_status.value!r} to {target_status.value!r}."
            ),
            details={
                "current": current_status.value,
                "target": target_status.value,
            },
        )
    return valid


def validate_stage_status_transition(
    current: Any,
    target: Any,
    *,
    stage: Optional[str] = None,
    raise_on_error: bool = True,
) -> bool:
    """Validate a pipeline-stage status transition."""

    current_status = canonicalize_stage_status(current)
    target_status = canonicalize_stage_status(target)
    valid = can_transition_stage_status(current_status, target_status)
    if not valid and raise_on_error:
        raise AnalysisStatusTransitionError(
            (
                "Invalid stage status transition from "
                f"{current_status.value!r} to {target_status.value!r}."
            ),
            stage=stage,
            scope=FailureScope.STAGE,
            details={
                "current": current_status.value,
                "target": target_status.value,
            },
        )
    return valid


def derive_analysis_status(
    stage_statuses: Iterable[Any],
    *,
    cancelled: bool = False,
    allow_empty: bool = False,
) -> AnalysisStatus:
    """Derive a final run status from stage statuses."""

    statuses = tuple(canonicalize_stage_status(item) for item in stage_statuses)
    if cancelled or StageStatus.CANCELLED in statuses:
        return AnalysisStatus.CANCELLED
    if not statuses:
        if allow_empty:
            return AnalysisStatus.SKIPPED
        raise ValueError("Cannot derive analysis status from an empty sequence.")
    if any(status is StageStatus.RUNNING for status in statuses):
        return AnalysisStatus.RUNNING
    if any(status in {StageStatus.PENDING, StageStatus.READY} for status in statuses):
        return AnalysisStatus.PREPARING
    succeeded = sum(status is StageStatus.SUCCEEDED for status in statuses)
    partial = sum(status is StageStatus.PARTIAL for status in statuses)
    failed = sum(
        status in {StageStatus.FAILED, StageStatus.BLOCKED}
        for status in statuses
    )
    skipped = sum(status is StageStatus.SKIPPED for status in statuses)
    useful = succeeded + partial
    if failed and useful:
        return AnalysisStatus.PARTIAL
    if partial:
        return AnalysisStatus.PARTIAL
    if failed:
        return AnalysisStatus.FAILED
    if useful:
        return AnalysisStatus.SUCCEEDED
    if skipped == len(statuses):
        return AnalysisStatus.SKIPPED
    return AnalysisStatus.PARTIAL

# 3.8. Issue and exception conversion helpers
# -----------------------------------------------------------------------------


def infer_issue_severity(error: BaseException) -> IssueSeverity:
    """Infer a diagnostic severity from an exception instance."""

    if isinstance(error, (SystemExit, KeyboardInterrupt, MemoryError)):
        return IssueSeverity.CRITICAL
    if isinstance(error, AnalysisCancelledError):
        return IssueSeverity.WARNING
    if isinstance(error, AnalysisPartialFailureError):
        return IssueSeverity.WARNING
    if isinstance(error, AnalysisWarning):
        return IssueSeverity.WARNING
    if isinstance(error, AnalysisError):
        return IssueSeverity.ERROR
    return IssueSeverity.ERROR


def infer_issue_kind(error: BaseException) -> IssueKind:
    """Infer an issue kind from an exception or warning instance."""

    if isinstance(error, AnalysisCancelledError):
        return IssueKind.CANCELLATION
    if isinstance(error, Warning):
        return IssueKind.WARNING
    return IssueKind.ERROR


def infer_recovery_action(error: BaseException) -> RecoveryAction:
    """Infer a recovery action from an exception instance."""

    if isinstance(error, AnalysisError):
        return error.action
    if isinstance(error, AnalysisDependencyError):
        return RecoveryAction.FALLBACK
    if isinstance(error, (AnalysisOutputError, AnalysisStageError)):
        return RecoveryAction.CONTINUE_PARTIAL
    if isinstance(error, AnalysisCancelledError):
        return RecoveryAction.ABORT_RUN
    return RecoveryAction.ABORT_RUN


def infer_failure_scope(error: BaseException) -> FailureScope:
    """Infer the affected execution scope from an exception instance."""

    if isinstance(error, AnalysisError):
        return error.scope
    if isinstance(error, ImportError):
        return FailureScope.ENVIRONMENT
    return FailureScope.RUN


def is_recoverable_analysis_error(error: BaseException) -> bool:
    """Return whether execution may continue after ``error``."""

    if isinstance(error, AnalysisError):
        return error.recoverable
    if isinstance(error, (SystemExit, KeyboardInterrupt, MemoryError)):
        return False
    return False


def collect_exception_chain(
    error: BaseException,
    *,
    max_depth: int = 16,
) -> Tuple[BaseException, ...]:
    """Return an exception and its explicit or implicit causes."""

    if max_depth < 1:
        raise ValueError("max_depth must be at least 1.")
    chain: List[BaseException] = []
    seen: Set[int] = set()
    current: Optional[BaseException] = error
    while current is not None and len(chain) < max_depth:
        identity = id(current)
        if identity in seen:
            break
        seen.add(identity)
        chain.append(current)
        if current.__cause__ is not None:
            current = current.__cause__
        elif not current.__suppress_context__:
            current = current.__context__
        else:
            current = None
    return tuple(chain)


def format_exception_chain(
    error: BaseException,
    *,
    separator: str = " <- ",
    max_depth: int = 16,
) -> str:
    """Return a concise exception-chain description."""

    parts = [
        f"{type(item).__name__}: {str(item).strip()}"
        for item in collect_exception_chain(error, max_depth=max_depth)
    ]
    return separator.join(parts)


def exception_to_issue(
    error: BaseException,
    *,
    stage: Optional[str] = None,
    code: Optional[str] = None,
    severity: Optional[Union[IssueSeverity, str, int]] = None,
    source: Optional[str] = None,
    recoverable: Optional[bool] = None,
    action: Union[RecoveryAction, str, None] = None,
    scope: Union[FailureScope, str, None] = None,
    details: Optional[Mapping[str, Any]] = None,
    include_traceback: bool = False,
) -> AnalysisIssue:
    """Convert any exception into a structured analysis issue."""

    base_details: Dict[str, Any] = {}
    if isinstance(error, AnalysisError):
        base_details.update(error.details)
    if details:
        base_details.update(details)
    traceback_text: Optional[str] = None
    if include_traceback:
        traceback_text = "".join(
            traceback.format_exception(type(error), error, error.__traceback__)
        )
    resolved_stage = stage
    resolved_code = code
    resolved_recoverable = recoverable
    resolved_action = action
    resolved_scope = scope
    if isinstance(error, AnalysisError):
        resolved_stage = resolved_stage or error.stage
        resolved_code = resolved_code or error.code
        if resolved_recoverable is None:
            resolved_recoverable = error.recoverable
        resolved_action = resolved_action or error.action
        resolved_scope = resolved_scope or error.scope
    resolved_code = resolved_code or _normalize_issue_code(type(error).__name__)
    if resolved_recoverable is None:
        resolved_recoverable = is_recoverable_analysis_error(error)
    return AnalysisIssue(
        kind=infer_issue_kind(error),
        severity=severity or infer_issue_severity(error),
        code=resolved_code,
        message=str(error).strip() or type(error).__name__,
        stage=resolved_stage,
        source=source,
        exception_type=type(error).__name__,
        recoverable=resolved_recoverable,
        action=resolved_action or infer_recovery_action(error),
        scope=resolved_scope or infer_failure_scope(error),
        details=base_details,
        traceback_text=traceback_text,
    )


def warning_to_issue(
    warning: Union[str, Warning],
    *,
    category: Optional[type[Warning]] = None,
    stage: Optional[str] = None,
    code: Optional[str] = None,
    source: Optional[str] = None,
    details: Optional[Mapping[str, Any]] = None,
) -> AnalysisIssue:
    """Convert a warning instance or message into a structured issue."""

    if isinstance(warning, AnalysisWarning):
        issue = warning.to_issue()
        if not any((stage, code, source, details)):
            return issue
        merged_details = dict(issue.details)
        merged_details.update(details or {})
        return AnalysisIssue(
            kind=issue.kind,
            severity=issue.severity,
            code=code or issue.code,
            message=issue.message,
            stage=stage or issue.stage,
            source=source or issue.source,
            warning_type=issue.warning_type,
            recoverable=issue.recoverable,
            action=issue.action,
            scope=issue.scope,
            details=merged_details,
        )
    if isinstance(warning, Warning):
        warning_type = type(warning).__name__
        message = str(warning)
    else:
        warning_type = (category or AnalysisWarning).__name__
        message = str(warning)
    return AnalysisIssue(
        kind=IssueKind.WARNING,
        severity=IssueSeverity.WARNING,
        code=code or _normalize_issue_code(warning_type),
        message=message,
        stage=stage,
        source=source,
        warning_type=warning_type,
        recoverable=True,
        action=RecoveryAction.CONTINUE_PARTIAL,
        scope=FailureScope.STAGE if stage else FailureScope.RUN,
        details=details or {},
    )


def emit_analysis_warning(
    message: str,
    *,
    category: type[AnalysisWarning] = AnalysisWarning,
    code: Optional[str] = None,
    stage: Optional[str] = None,
    recoverable: Optional[bool] = None,
    details: Optional[Mapping[str, Any]] = None,
    source: Optional[str] = None,
    stacklevel: int = 2,
) -> AnalysisIssue:
    """Emit a structured warning and return its issue representation."""

    if not issubclass(category, AnalysisWarning):
        raise TypeError("category must inherit from AnalysisWarning.")
    warning = category(
        message,
        code=code,
        stage=stage,
        recoverable=recoverable,
        details=details,
        source=source,
    )
    warnings.warn(warning, stacklevel=max(1, int(stacklevel)))
    return warning.to_issue()


def wrap_analysis_exception(
    error: BaseException,
    *,
    exception_type: type[AnalysisError] = AnalysisError,
    message: Optional[str] = None,
    code: Optional[str] = None,
    stage: Optional[str] = None,
    recoverable: Optional[bool] = None,
    scope: Union[FailureScope, str, None] = None,
    action: Union[RecoveryAction, str, None] = None,
    details: Optional[Mapping[str, Any]] = None,
) -> AnalysisError:
    """Wrap an arbitrary exception in an analysis-specific exception."""

    if not issubclass(exception_type, AnalysisError):
        raise TypeError("exception_type must inherit from AnalysisError.")
    if isinstance(error, exception_type) and not any(
        (
            message,
            code,
            stage,
            recoverable is not None,
            scope,
            action,
            details,
        )
    ):
        return error
    base_details: Dict[str, Any] = {}
    if isinstance(error, AnalysisError):
        base_details.update(error.details)
    if details:
        base_details.update(details)
    text = message or str(error).strip() or type(error).__name__
    return exception_type(
        text,
        code=code,
        stage=stage,
        recoverable=recoverable,
        scope=scope,
        action=action,
        details=base_details,
        cause=error,
    )


def should_continue_after_error(
    error: BaseException,
    *,
    failure_policy: Any = DEFAULT_FAILURE_POLICY,
) -> bool:
    """Return whether the selected failure policy permits continuation."""

    if isinstance(error, (SystemExit, KeyboardInterrupt, MemoryError)):
        return False
    if isinstance(error, AnalysisCancelledError):
        return False
    policy = canonicalize_failure_policy(failure_policy)
    if policy == FAILURE_POLICY_STRICT:
        return False
    if policy == FAILURE_POLICY_SKIP:
        return True
    if policy in {FAILURE_POLICY_PERMISSIVE, FAILURE_POLICY_PARTIAL}:
        return is_recoverable_analysis_error(error)
    return False

# 3.9. Exception context manager
# -----------------------------------------------------------------------------


@contextmanager
def translate_analysis_errors(
    *,
    exception_type: type[AnalysisError] = AnalysisError,
    message: Optional[str] = None,
    code: Optional[str] = None,
    stage: Optional[str] = None,
    recoverable: Optional[bool] = None,
    scope: Union[FailureScope, str, None] = None,
    action: Union[RecoveryAction, str, None] = None,
    details: Optional[Mapping[str, Any]] = None,
    preserve_analysis_errors: bool = True,
) -> Iterator[None]:
    """Translate exceptions raised by a block into analysis exceptions."""

    try:
        yield
    except AnalysisCancelledError:
        raise
    except AnalysisError as exc:
        if preserve_analysis_errors and isinstance(exc, exception_type):
            raise
        wrapped = wrap_analysis_exception(
            exc,
            exception_type=exception_type,
            message=message,
            code=code,
            stage=stage,
            recoverable=recoverable,
            scope=scope,
            action=action,
            details=details,
        )
        raise wrapped from exc
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        wrapped = wrap_analysis_exception(
            exc,
            exception_type=exception_type,
            message=message,
            code=code,
            stage=stage,
            recoverable=recoverable,
            scope=scope,
            action=action,
            details=details,
        )
        raise wrapped from exc

# 3.10. Convention validation
# -----------------------------------------------------------------------------


def validate_error_status_conventions(
    *,
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate Section 3 exception, warning and status conventions."""

    issues: List[str] = []

    enum_groups: Tuple[type[Enum], ...] = (
        AnalysisStatus,
        StageStatus,
        IssueKind,
        RecoveryAction,
        FailureScope,
    )
    for enum_type in enum_groups:
        values = [member.value for member in enum_type]
        if len(values) != len(set(values)):
            issues.append(f"{enum_type.__name__} contains duplicate values.")

    if set(ANALYSIS_STATUS_TRANSITIONS) != set(AnalysisStatus):
        issues.append("ANALYSIS_STATUS_TRANSITIONS is incomplete.")
    if set(STAGE_STATUS_TRANSITIONS) != set(StageStatus):
        issues.append("STAGE_STATUS_TRANSITIONS is incomplete.")

    for current, targets in ANALYSIS_STATUS_TRANSITIONS.items():
        if current in targets:
            issues.append(
                f"Analysis status {current.value!r} explicitly transitions to itself."
            )
        unknown = set(targets).difference(set(AnalysisStatus))
        if unknown:
            issues.append(
                f"Analysis status {current.value!r} has unknown targets: {unknown!r}."
            )
        if current in ANALYSIS_TERMINAL_STATUSES and targets:
            issues.append(
                f"Terminal analysis status {current.value!r} has outgoing transitions."
            )

    for current, targets in STAGE_STATUS_TRANSITIONS.items():
        if current in targets:
            issues.append(
                f"Stage status {current.value!r} explicitly transitions to itself."
            )
        unknown = set(targets).difference(set(StageStatus))
        if unknown:
            issues.append(
                f"Stage status {current.value!r} has unknown targets: {unknown!r}."
            )
        if current in STAGE_TERMINAL_STATUSES and targets:
            issues.append(
                f"Terminal stage status {current.value!r} has outgoing transitions."
            )

    exception_types: Tuple[type[AnalysisError], ...] = (
        AnalysisConfigurationError,
        AnalysisInputError,
        AnalysisDependencyError,
        AnalysisCapabilityError,
        AnalysisStateError,
        AnalysisStatusTransitionError,
        AnalysisRegistryError,
        AnalysisStageError,
        AnalysisStageDependencyError,
        AnalysisIntegrationError,
        AnalysisConsolidationError,
        AnalysisScoringError,
        AnalysisOutputError,
        AnalysisReportError,
        AnalysisExportError,
        AnalysisVisualizationError,
        AnalysisSerializationError,
        AnalysisValidationError,
        AnalysisConcurrencyError,
        AnalysisCancelledError,
        AnalysisPartialFailureError,
        AnalysisBatchError,
        ChimeraXAnalysisError,
        ChimeraXUnavailableAnalysisError,
    )
    codes = [item.default_code for item in exception_types]
    if len(codes) != len(set(codes)):
        issues.append("Analysis exception classes contain duplicate default codes.")
    for exception_type in exception_types:
        if not issubclass(exception_type, AnalysisError):
            issues.append(
                f"{exception_type.__name__} does not inherit from AnalysisError."
            )
        try:
            instance = exception_type("validation probe")
        except Exception as exc:  # pragma: no cover - defensive validation
            issues.append(
                f"{exception_type.__name__} could not be instantiated: {exc}."
            )
            continue
        if not instance.code:
            issues.append(f"{exception_type.__name__} has an empty issue code.")

    warning_types: Tuple[type[AnalysisWarning], ...] = (
        AnalysisConfigurationWarning,
        AnalysisDependencyWarning,
        AnalysisStageWarning,
        AnalysisIntegrationWarning,
        AnalysisValidationWarning,
        AnalysisCompatibilityWarning,
        AnalysisPerformanceWarning,
        AnalysisFallbackWarning,
        AnalysisPartialResultWarning,
    )
    warning_codes = [item.default_code for item in warning_types]
    if len(warning_codes) != len(set(warning_codes)):
        issues.append("Analysis warning classes contain duplicate default codes.")
    for warning_type in warning_types:
        if not issubclass(warning_type, AnalysisWarning):
            issues.append(
                f"{warning_type.__name__} does not inherit from AnalysisWarning."
            )

    try:
        probe = AnalysisIssue(
            kind="warning",
            severity="warning",
            code="validation probe",
            message="Validation probe.",
            stage="contacts",
            action="continue",
            scope="stage",
        )
        probe_data = probe.to_dict()
        if probe_data["code"] != "validation_probe":
            issues.append("AnalysisIssue code normalization is inconsistent.")
        if probe_data["stage"] != STAGE_CONTACTS:
            issues.append("AnalysisIssue stage normalization is inconsistent.")
    except Exception as exc:  # pragma: no cover - defensive validation
        issues.append(f"AnalysisIssue validation probe failed: {exc}.")

    result = tuple(issues)
    if result and raise_on_error:
        raise RuntimeError(
            "Invalid analysis error and status conventions: " + " ".join(result)
        )
    return result

