# 4.2. Generic configuration helpers
# -----------------------------------------------------------------------------

_TRUE_CONFIG_TOKENS: Final[FrozenSet[str]] = frozenset(
    {"1", "true", "yes", "on", "enabled", "enable", "active"}
)
_FALSE_CONFIG_TOKENS: Final[FrozenSet[str]] = frozenset(
    {"0", "false", "no", "off", "disabled", "disable", "inactive", "none"}
)


def _coerce_config_bool(value: Any, *, field_name: str) -> bool:
    """Coerce a strict boolean configuration value."""

    if isinstance(value, bool):
        return value
    if isinstance(value, int) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        token = _normalize_convention_token(value, field_name=field_name)
        if token in _TRUE_CONFIG_TOKENS:
            return True
        if token in _FALSE_CONFIG_TOKENS:
            return False
    raise AnalysisConfigurationError(
        f"{field_name} must be a boolean value.",
        details={"field": field_name, "value": repr(value)},
    )


def _coerce_config_int(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[int] = None,
    maximum: Optional[int] = None,
) -> int:
    """Coerce and validate an integer configuration value."""

    if isinstance(value, bool):
        raise AnalysisConfigurationError(
            f"{field_name} must be an integer, not a boolean."
        )
    try:
        result = int(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(
            f"{field_name} must be an integer.",
            details={"field": field_name, "value": repr(value)},
        ) from exc
    if isinstance(value, float) and not value.is_integer():
        raise AnalysisConfigurationError(f"{field_name} must be an integer.")
    if minimum is not None and result < minimum:
        raise AnalysisConfigurationError(
            f"{field_name} must be at least {minimum}."
        )
    if maximum is not None and result > maximum:
        raise AnalysisConfigurationError(
            f"{field_name} must not exceed {maximum}."
        )
    return result


def _coerce_config_float(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
    allow_none: bool = False,
) -> Optional[float]:
    """Coerce and validate a finite floating-point configuration value."""

    if value is None and allow_none:
        return None
    if isinstance(value, bool):
        raise AnalysisConfigurationError(
            f"{field_name} must be numeric, not a boolean."
        )
    try:
        result = float(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(
            f"{field_name} must be numeric.",
            details={"field": field_name, "value": repr(value)},
        ) from exc
    if not math.isfinite(result):
        raise AnalysisConfigurationError(f"{field_name} must be finite.")
    if minimum is not None and result < minimum:
        raise AnalysisConfigurationError(
            f"{field_name} must be at least {minimum}."
        )
    if maximum is not None and result > maximum:
        raise AnalysisConfigurationError(
            f"{field_name} must not exceed {maximum}."
        )
    return result


def _coerce_config_text(
    value: Any,
    *,
    field_name: str,
    allow_none: bool = False,
    allow_empty: bool = False,
    maximum_length: int = MAX_IDENTIFIER_LENGTH,
) -> Optional[str]:
    """Coerce one configuration value to normalized text."""

    if value is None:
        if allow_none:
            return None
        raise AnalysisConfigurationError(f"{field_name} cannot be None.")
    text = str(value).strip()
    if not text and not allow_empty:
        raise AnalysisConfigurationError(f"{field_name} cannot be empty.")
    if len(text) > maximum_length:
        raise AnalysisConfigurationError(
            f"{field_name} exceeds the maximum length of {maximum_length}."
        )
    return text


def _coerce_config_sequence(
    value: Any,
    *,
    field_name: str,
    allow_none: bool = True,
) -> Tuple[Any, ...]:
    """Coerce a scalar or iterable configuration value to a tuple."""

    if value is None:
        if allow_none:
            return ()
        raise AnalysisConfigurationError(f"{field_name} cannot be None.")
    if isinstance(value, (str, bytes, bytearray, Enum, Path)):
        return (value,)
    try:
        return tuple(value)
    except TypeError:
        return (value,)


def _freeze_config_value(value: Any, *, depth: int = 0) -> Any:
    """Create an immutable defensive copy of a configuration value."""

    if depth > MAX_METADATA_DEPTH:
        raise AnalysisConfigurationError(
            "Configuration nesting exceeds the supported depth."
        )
    if isinstance(value, Mapping):
        frozen = {
            str(key): _freeze_config_value(item, depth=depth + 1)
            for key, item in value.items()
        }
        return MappingProxyType(frozen)
    if isinstance(value, tuple):
        return tuple(_freeze_config_value(item, depth=depth + 1) for item in value)
    if isinstance(value, list):
        return tuple(_freeze_config_value(item, depth=depth + 1) for item in value)
    if isinstance(value, (set, frozenset)):
        return frozenset(
            _freeze_config_value(item, depth=depth + 1) for item in value
        )
    try:
        return copy.deepcopy(value)
    except Exception:
        return value


def _config_value_to_data(value: Any, *, depth: int = 0) -> Any:
    """Convert a configuration value to a stable serializable representation."""

    if depth > MAX_SERIALIZATION_DEPTH:
        return "<maximum-depth>"
    if value is None or isinstance(value, (str, int, bool)):
        return value
    if isinstance(value, float):
        if math.isnan(value):
            return "nan"
        if math.isinf(value):
            return "infinity" if value > 0 else "-infinity"
        return value
    if isinstance(value, Enum):
        return _config_value_to_data(value.value, depth=depth + 1)
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Mapping):
        return {
            str(key): _config_value_to_data(item, depth=depth + 1)
            for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))
        }
    if isinstance(value, (tuple, list)):
        return [
            _config_value_to_data(item, depth=depth + 1) for item in value
        ]
    if isinstance(value, (set, frozenset)):
        converted = [
            _config_value_to_data(item, depth=depth + 1) for item in value
        ]
        return sorted(converted, key=lambda item: repr(item))
    if hasattr(value, "to_dict") and callable(value.to_dict):
        try:
            return _config_value_to_data(value.to_dict(), depth=depth + 1)
        except Exception:
            pass
    if is_dataclass(value) and not isinstance(value, type):
        try:
            return _config_value_to_data(asdict(value), depth=depth + 1)
        except Exception:
            pass
    if callable(value):
        module_name = getattr(value, "__module__", "")
        qualified_name = getattr(value, "__qualname__", repr(value))
        return f"{module_name}.{qualified_name}".strip(".")
    return repr(value)


def _canonicalize_config_mapping(
    values: Mapping[str, Any],
    *,
    aliases: Mapping[str, str],
    field_name: str,
    allowed_fields: Iterable[str],
    strict: bool = True,
) -> Dict[str, Any]:
    """Normalize mapping keys using a field alias table."""

    if not isinstance(values, Mapping):
        raise AnalysisConfigurationError(f"{field_name} must be a mapping.")

    allowed = frozenset(allowed_fields)
    result: Dict[str, Any] = {}
    for raw_key, value in values.items():
        token = _normalize_convention_token(raw_key, field_name=f"{field_name} key")
        canonical = aliases.get(token, token)
        if canonical not in allowed:
            if strict:
                supported = ", ".join(sorted(allowed))
                raise AnalysisConfigurationError(
                    f"Unknown {field_name} field {raw_key!r}. "
                    f"Supported fields: {supported}."
                )
            continue
        if canonical in result:
            raise AnalysisConfigurationError(
                f"Duplicate {field_name} field after alias resolution: "
                f"{canonical!r}."
            )
        result[canonical] = value
    return result


def _merge_config_mappings(
    base: Mapping[str, Any],
    updates: Mapping[str, Any],
) -> Dict[str, Any]:
    """Recursively merge two configuration mappings."""

    merged: Dict[str, Any] = {
        str(key): copy.deepcopy(value) for key, value in base.items()
    }
    for key, value in updates.items():
        text_key = str(key)
        current = merged.get(text_key)
        if isinstance(current, Mapping) and isinstance(value, Mapping):
            merged[text_key] = _merge_config_mappings(current, value)
        else:
            merged[text_key] = copy.deepcopy(value)
    return merged


def _canonicalize_output_formats(
    values: Any,
    *,
    field_name: str,
    default: Sequence[str],
) -> Tuple[str, ...]:
    """Normalize an ordered output-format collection."""

    raw_values = _coerce_config_sequence(values, field_name=field_name)
    if not raw_values:
        raw_values = tuple(default)
    result: List[str] = []
    seen: Set[str] = set()
    for raw_value in raw_values:
        token = _normalize_convention_token(raw_value, field_name=field_name)
        if token not in seen:
            result.append(token)
            seen.add(token)
    return tuple(result)


def _normalize_module_config_name(value: Any) -> str:
    """Return a supported canonical module-configuration name."""

    token = _normalize_convention_token(value, field_name="module name")
    aliases = {
        "contact": "contacts",
        "hbond": "hbonds",
        "hydrogen_bond": "hbonds",
        "hydrogen_bonds": "hbonds",
        "hydrophobe": "hydrophobic",
        "salt_bridge": "saltbridge",
        "salt_bridges": "saltbridge",
        "score": "scoring",
        "reporting": "report",
        "visualisation": "visualization",
        "visualise": "visualization",
        "visualize": "visualization",
    }
    canonical = aliases.get(token, token)
    if canonical not in CONFIGURATION_MODULE_NAMES:
        supported = ", ".join(CONFIGURATION_MODULE_NAMES)
        raise AnalysisConfigurationError(
            f"Unknown module configuration {value!r}. Supported modules: "
            f"{supported}."
        )
    return canonical

# 4.3. Interaction selection
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class InteractionSelection:
    """Select interaction families and pi-interaction subtypes."""

    contacts: bool = True
    hbonds: bool = True
    hydrophobic: bool = True
    pi: bool = True
    saltbridge: bool = True
    pi_subtypes: Tuple[str, ...] = PI_INTERACTION_SUBTYPES

    def __post_init__(self) -> None:
        for field_name in INTERACTION_SELECTION_FIELDS:
            object.__setattr__(
                self,
                field_name,
                _coerce_config_bool(
                    getattr(self, field_name),
                    field_name=f"interactions.{field_name}",
                ),
            )

        raw_subtypes = _coerce_config_sequence(
            self.pi_subtypes,
            field_name="interactions.pi_subtypes",
        )
        subtypes: List[str] = []
        seen: Set[str] = set()
        for value in raw_subtypes:
            subtype = canonicalize_pi_subtype(value)
            if subtype not in seen:
                subtypes.append(subtype)
                seen.add(subtype)
        object.__setattr__(self, "pi_subtypes", tuple(subtypes))

    @classmethod
    def all(cls) -> "InteractionSelection":
        """Return a selection containing every interaction family."""

        return cls()

    @classmethod
    def none(cls) -> "InteractionSelection":
        """Return a selection with every interaction family disabled."""

        return cls(
            contacts=False,
            hbonds=False,
            hydrophobic=False,
            pi=False,
            saltbridge=False,
            pi_subtypes=(),
        )

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "InteractionSelection":
        """Create an interaction selection from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Interaction selection must be a mapping."
            )

        fields_allowed = (*INTERACTION_SELECTION_FIELDS, "pi_subtypes")
        normalized: Dict[str, Any] = {}
        for raw_key, value in values.items():
            token = _normalize_convention_token(
                raw_key,
                field_name="interaction selection key",
            )
            if token in {"pi_subtype", "pi_types", "pi_type"}:
                canonical = "pi_subtypes"
            else:
                canonical = INTERACTION_SELECTION_ALIASES.get(token, token)
            if canonical not in fields_allowed:
                if strict:
                    supported = ", ".join(fields_allowed)
                    raise AnalysisConfigurationError(
                        f"Unknown interaction-selection field {raw_key!r}. "
                        f"Supported fields: {supported}."
                    )
                continue
            if canonical in normalized:
                raise AnalysisConfigurationError(
                    "Duplicate interaction-selection field after alias "
                    f"resolution: {canonical!r}."
                )
            normalized[canonical] = value
        return cls(**normalized)

    @property
    def enabled_families(self) -> Tuple[str, ...]:
        """Return enabled interaction families in canonical order."""

        return tuple(
            family
            for family in INTERACTION_FAMILY_ORDER
            if bool(getattr(self, family))
        )

    @property
    def disabled_families(self) -> Tuple[str, ...]:
        """Return disabled interaction families in canonical order."""

        enabled = frozenset(self.enabled_families)
        return tuple(
            family for family in INTERACTION_FAMILY_ORDER if family not in enabled
        )

    @property
    def enabled_stages(self) -> Tuple[str, ...]:
        """Return pipeline stages associated with enabled families."""

        return tuple(
            interaction_family_to_stage(family)
            for family in self.enabled_families
        )

    @property
    def any_enabled(self) -> bool:
        """Return whether at least one family is enabled."""

        return bool(self.enabled_families)

    @property
    def all_enabled(self) -> bool:
        """Return whether every family is enabled."""

        return len(self.enabled_families) == len(INTERACTION_FAMILY_ORDER)

    def is_enabled(self, family: Any) -> bool:
        """Return whether one interaction family is enabled."""

        canonical = canonicalize_interaction_family(family)
        return bool(getattr(self, canonical))

    def with_family(self, family: Any, enabled: bool = True) -> "InteractionSelection":
        """Return a copy with one interaction family changed."""

        canonical = canonicalize_interaction_family(family)
        return replace(
            self,
            **{
                canonical: _coerce_config_bool(
                    enabled,
                    field_name=f"interactions.{canonical}",
                )
            },
        )

    def with_pi_subtypes(self, values: Any) -> "InteractionSelection":
        """Return a copy with a new pi-subtype selection."""

        return replace(self, pi_subtypes=values)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable interaction-selection mapping."""

        return {
            **{
                family: bool(getattr(self, family))
                for family in INTERACTION_FAMILY_ORDER
            },
            "pi_subtypes": list(self.pi_subtypes),
        }

# 4.4. Per-stage configuration
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class AnalysisStageConfig:
    """Control execution behavior and parameters for one pipeline stage."""

    enabled: bool = True
    required: bool = DEFAULT_STAGE_REQUIRED
    attach_results: bool = DEFAULT_ATTACH_RESULTS
    validate_result: bool = DEFAULT_VALIDATE_RESULTS
    reuse_result: bool = DEFAULT_REUSE_RESULTS
    cache_enabled: bool = DEFAULT_STAGE_CACHE_ENABLED
    timeout_seconds: Optional[float] = None
    max_attempts: int = DEFAULT_STAGE_MAX_ATTEMPTS
    parameters: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        for field_name in (
            "enabled",
            "required",
            "attach_results",
            "validate_result",
            "reuse_result",
            "cache_enabled",
        ):
            object.__setattr__(
                self,
                field_name,
                _coerce_config_bool(
                    getattr(self, field_name),
                    field_name=f"stage_config.{field_name}",
                ),
            )

        object.__setattr__(
            self,
            "timeout_seconds",
            _coerce_config_float(
                self.timeout_seconds,
                field_name="stage_config.timeout_seconds",
                minimum=0.0,
                allow_none=True,
            ),
        )
        object.__setattr__(
            self,
            "max_attempts",
            _coerce_config_int(
                self.max_attempts,
                field_name="stage_config.max_attempts",
                minimum=1,
                maximum=1000,
            ),
        )
        if not isinstance(self.parameters, Mapping):
            raise AnalysisConfigurationError(
                "stage_config.parameters must be a mapping."
            )
        if not isinstance(self.metadata, Mapping):
            raise AnalysisConfigurationError(
                "stage_config.metadata must be a mapping."
            )
        object.__setattr__(
            self,
            "parameters",
            _freeze_config_value(self.parameters),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_config_value(self.metadata),
        )

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "AnalysisStageConfig":
        """Create a stage configuration from a mapping."""

        normalized = _canonicalize_config_mapping(
            values,
            aliases=STAGE_CONFIG_FIELD_ALIASES,
            field_name="stage configuration",
            allowed_fields=(item.name for item in fields(cls)),
            strict=strict,
        )
        return cls(**normalized)

    def merged(self, updates: Mapping[str, Any]) -> "AnalysisStageConfig":
        """Return a stage configuration with mapping updates applied."""

        current = self.to_dict()
        merged = _merge_config_mappings(current, updates)
        return type(self).from_mapping(merged)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable stage-configuration mapping."""

        return {
            "enabled": self.enabled,
            "required": self.required,
            "attach_results": self.attach_results,
            "validate_result": self.validate_result,
            "reuse_result": self.reuse_result,
            "cache_enabled": self.cache_enabled,
            "timeout_seconds": self.timeout_seconds,
            "max_attempts": self.max_attempts,
            "parameters": _config_value_to_data(self.parameters),
            "metadata": _config_value_to_data(self.metadata),
        }

# 4.5. Runtime configuration
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class AnalysisRuntimeConfig:
    """Control execution policy, limits and diagnostic collection."""

    analysis_mode: str = DEFAULT_ANALYSIS_MODE
    failure_policy: str = DEFAULT_FAILURE_POLICY
    attachment_policy: str = DEFAULT_ATTACHMENT_POLICY
    execution_mode: str = DEFAULT_EXECUTION_MODE
    max_workers: int = DEFAULT_MAX_WORKERS
    attach_results: bool = DEFAULT_ATTACH_RESULTS
    reuse_results: bool = DEFAULT_REUSE_RESULTS
    validate_inputs: bool = True
    validate_results: bool = DEFAULT_VALIDATE_RESULTS
    collect_timings: bool = DEFAULT_COLLECT_TIMINGS
    collect_provenance: bool = DEFAULT_COLLECT_PROVENANCE
    collect_diagnostics: bool = DEFAULT_COLLECT_DIAGNOSTICS
    allow_partial_results: bool = DEFAULT_ALLOW_PARTIAL_RESULTS
    record_history: bool = DEFAULT_RECORD_HISTORY
    max_history: int = MAX_ANALYSIS_HISTORY
    dry_run: bool = DEFAULT_DRY_RUN
    allow_chimerax_threads: bool = False
    default_stage_timeout_seconds: Optional[float] = None
    progress_interval: int = DEFAULT_PROGRESS_INTERVAL
    max_batch_items: int = MAX_BATCH_ITEMS
    max_multipose_items: int = MAX_MULTIPOSE_ITEMS
    environment: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        try:
            object.__setattr__(
                self,
                "analysis_mode",
                canonicalize_analysis_mode(self.analysis_mode),
            )
            object.__setattr__(
                self,
                "failure_policy",
                canonicalize_failure_policy(self.failure_policy),
            )
            object.__setattr__(
                self,
                "attachment_policy",
                canonicalize_attachment_policy(self.attachment_policy),
            )
            object.__setattr__(
                self,
                "execution_mode",
                canonicalize_execution_mode(self.execution_mode),
            )
        except (TypeError, ValueError) as exc:
            raise AnalysisConfigurationError(str(exc)) from exc

        for field_name in (
            "attach_results",
            "reuse_results",
            "validate_inputs",
            "validate_results",
            "collect_timings",
            "collect_provenance",
            "collect_diagnostics",
            "allow_partial_results",
            "record_history",
            "dry_run",
            "allow_chimerax_threads",
        ):
            object.__setattr__(
                self,
                field_name,
                _coerce_config_bool(
                    getattr(self, field_name),
                    field_name=f"runtime.{field_name}",
                ),
            )

        object.__setattr__(
            self,
            "max_workers",
            _coerce_config_int(
                self.max_workers,
                field_name="runtime.max_workers",
                minimum=1,
                maximum=1024,
            ),
        )
        object.__setattr__(
            self,
            "max_history",
            _coerce_config_int(
                self.max_history,
                field_name="runtime.max_history",
                minimum=0,
                maximum=100_000,
            ),
        )
        object.__setattr__(
            self,
            "default_stage_timeout_seconds",
            _coerce_config_float(
                self.default_stage_timeout_seconds,
                field_name="runtime.default_stage_timeout_seconds",
                minimum=0.0,
                allow_none=True,
            ),
        )
        object.__setattr__(
            self,
            "progress_interval",
            _coerce_config_int(
                self.progress_interval,
                field_name="runtime.progress_interval",
                minimum=1,
                maximum=1_000_000,
            ),
        )
        object.__setattr__(
            self,
            "max_batch_items",
            _coerce_config_int(
                self.max_batch_items,
                field_name="runtime.max_batch_items",
                minimum=1,
                maximum=MAX_BATCH_ITEMS,
            ),
        )
        object.__setattr__(
            self,
            "max_multipose_items",
            _coerce_config_int(
                self.max_multipose_items,
                field_name="runtime.max_multipose_items",
                minimum=1,
                maximum=MAX_MULTIPOSE_ITEMS,
            ),
        )
        if not isinstance(self.environment, Mapping):
            raise AnalysisConfigurationError("runtime.environment must be a mapping.")
        object.__setattr__(
            self,
            "environment",
            _freeze_config_value(self.environment),
        )

        if self.failure_policy == FAILURE_POLICY_STRICT and self.allow_partial_results:
            object.__setattr__(self, "allow_partial_results", False)
        if self.attachment_policy == ATTACHMENT_POLICY_NONE and self.attach_results:
            object.__setattr__(self, "attach_results", False)
        if self.execution_mode == EXECUTION_MODE_SEQUENTIAL and self.max_workers != 1:
            object.__setattr__(self, "max_workers", 1)

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "AnalysisRuntimeConfig":
        """Create runtime configuration from a mapping."""

        normalized = _canonicalize_config_mapping(
            values,
            aliases=RUNTIME_CONFIG_FIELD_ALIASES,
            field_name="runtime configuration",
            allowed_fields=(item.name for item in fields(cls)),
            strict=strict,
        )
        return cls(**normalized)

    @property
    def is_strict(self) -> bool:
        """Return whether strict failure handling is enabled."""

        return self.failure_policy == FAILURE_POLICY_STRICT

    @property
    def is_permissive(self) -> bool:
        """Return whether permissive failure handling is enabled."""

        return self.failure_policy == FAILURE_POLICY_PERMISSIVE

    @property
    def threaded(self) -> bool:
        """Return whether threaded execution is explicitly enabled."""

        return self.execution_mode == EXECUTION_MODE_THREADED

    def effective_execution_mode(self, *, in_chimerax: bool = False) -> str:
        """Return the execution mode after environment safety rules."""

        mode = self.execution_mode
        if mode == EXECUTION_MODE_AUTOMATIC:
            mode = (
                EXECUTION_MODE_SEQUENTIAL
                if in_chimerax
                else EXECUTION_MODE_THREADED
            )
        if in_chimerax and mode == EXECUTION_MODE_THREADED:
            if not self.allow_chimerax_threads:
                return EXECUTION_MODE_SEQUENTIAL
        return mode

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable runtime-configuration mapping."""

        return {
            item.name: _config_value_to_data(getattr(self, item.name))
            for item in fields(self)
        }

