# 5.1. Core result constants
# -----------------------------------------------------------------------------

RESULT_TYPE_STAGE: Final[str] = "stage_result"
RESULT_TYPE_INTERACTIONS: Final[str] = "interaction_bundle"
RESULT_TYPE_POSE: Final[str] = "pose_result"
RESULT_TYPE_MULTIPOSE: Final[str] = "multipose_result"
RESULT_TYPE_BATCH_ITEM: Final[str] = "batch_item"
RESULT_TYPE_BATCH: Final[str] = "batch_result"
RESULT_TYPE_RUN: Final[str] = "analysis_run"

CORE_RESULT_TYPES: Final[Tuple[str, ...]] = (
    RESULT_TYPE_STAGE,
    RESULT_TYPE_INTERACTIONS,
    RESULT_TYPE_POSE,
    RESULT_TYPE_MULTIPOSE,
    RESULT_TYPE_BATCH_ITEM,
    RESULT_TYPE_BATCH,
    RESULT_TYPE_RUN,
)

DEFAULT_RESULT_NAME: Final[str] = "analysis"
DEFAULT_POSE_RESULT_NAME: Final[str] = "pose"
DEFAULT_BATCH_ITEM_NAME: Final[str] = "batch_item"
DEFAULT_CONTEXT_PROGRESS_TOTAL: Final[int] = 0
MAX_CORE_RESULT_ITEMS: Final[int] = MAX_BATCH_ITEMS
MAX_CORE_RESULT_DEPTH: Final[int] = MAX_SERIALIZATION_DEPTH

_RESULT_IDENTIFIER_PATTERN: Final[re.Pattern[str]] = re.compile(
    r"[^A-Za-z0-9_.:-]+"
)

# 5.2. Core normalization and serialization helpers
# -----------------------------------------------------------------------------


def _new_result_identifier(prefix: str) -> str:
    """Return a compact identifier suitable for requests and results."""

    canonical_prefix = _normalize_result_identifier(
        prefix,
        fallback=ANALYSIS_ID_PREFIX,
    )
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    entropy = sha256(
        f"{timestamp}:{time.perf_counter_ns()}:{threading.get_ident()}".encode(
            ANALYSIS_ENCODING
        )
    ).hexdigest()[:12]
    return f"{canonical_prefix}-{timestamp}-{entropy}"


def _normalize_result_identifier(
    value: Any,
    *,
    fallback: str,
) -> str:
    """Normalize a request, run, pose or batch identifier."""

    text = str(value).strip() if value is not None else ""
    if not text:
        text = str(fallback).strip() or ANALYSIS_ID_PREFIX
    text = _RESULT_IDENTIFIER_PATTERN.sub("_", text)
    text = re.sub(r"_+", "_", text).strip("_.:-")
    if not text:
        text = ANALYSIS_ID_PREFIX
    return text[:MAX_IDENTIFIER_LENGTH]


def _normalize_result_name(value: Any, *, fallback: str) -> str:
    """Return a non-empty human-readable result name."""

    text = str(value).strip() if value is not None else ""
    return (text or fallback)[:MAX_IDENTIFIER_LENGTH]


def _normalize_timestamp(value: Any, *, allow_none: bool = False) -> Optional[str]:
    """Normalize a timestamp to an ISO-formatted string."""

    if value is None:
        return None if allow_none else _utc_timestamp()
    if isinstance(value, datetime):
        current = value
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        return current.astimezone(timezone.utc).isoformat(
            timespec=DEFAULT_DATETIME_TIMESPEC
        )
    if isinstance(value, date):
        current = datetime.combine(value, datetime.min.time(), tzinfo=timezone.utc)
        return current.isoformat(timespec=DEFAULT_DATETIME_TIMESPEC)
    text = str(value).strip()
    if not text:
        return None if allow_none else _utc_timestamp()
    return text


def _normalize_duration(value: Any) -> Optional[float]:
    """Return a finite non-negative duration or ``None``."""

    if value is None:
        return None
    try:
        duration = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("Duration must be numeric or None.") from exc
    if not math.isfinite(duration) or duration < 0.0:
        raise ValueError("Duration must be finite and non-negative.")
    return duration


def _normalize_message_sequence(value: Any) -> List[str]:
    """Normalize one message or an iterable of messages."""

    if value is None:
        return []
    if isinstance(value, str):
        values = [value]
    else:
        try:
            values = list(value)
        except TypeError:
            values = [value]
    messages: List[str] = []
    for item in values:
        text = str(item).strip()
        if text:
            messages.append(text)
    return messages[:MAX_DIAGNOSTIC_MESSAGES]


def _coerce_analysis_issue(value: Any) -> AnalysisIssue:
    """Coerce an issue-like object into :class:`AnalysisIssue`."""

    if isinstance(value, AnalysisIssue):
        return value
    if isinstance(value, AnalysisWarning):
        return value.to_issue()
    if isinstance(value, Warning):
        return warning_to_issue(value)
    if isinstance(value, BaseException):
        return exception_to_issue(value)
    if isinstance(value, Mapping):
        data = dict(value)
        traceback_text = data.pop("traceback", data.pop("traceback_text", None))
        return AnalysisIssue(
            kind=data.pop("kind", IssueKind.MESSAGE),
            severity=data.pop("severity", IssueSeverity.INFO),
            code=data.pop("code", "analysis_message"),
            message=data.pop("message", ""),
            stage=data.pop("stage", None),
            source=data.pop("source", None),
            exception_type=data.pop("exception_type", None),
            warning_type=data.pop("warning_type", None),
            recoverable=data.pop("recoverable", True),
            action=data.pop("action", RecoveryAction.NONE),
            scope=data.pop("scope", FailureScope.RUN),
            details=data.pop("details", data),
            traceback_text=traceback_text,
            created_at=data.pop("created_at", _utc_timestamp()),
        )
    return AnalysisIssue(
        kind=IssueKind.MESSAGE,
        severity=IssueSeverity.INFO,
        code="analysis_message",
        message=str(value),
    )


def _coerce_analysis_issues(value: Any) -> List[AnalysisIssue]:
    """Normalize an issue or issue collection."""

    if value is None:
        return []
    if isinstance(
        value,
        (AnalysisIssue, AnalysisWarning, Warning, BaseException, Mapping, str),
    ):
        values = [value]
    else:
        try:
            values = list(value)
        except TypeError:
            values = [value]
    return [
        _coerce_analysis_issue(item)
        for item in values[:MAX_DIAGNOSTIC_MESSAGES]
    ]


@lru_cache(maxsize=256)
def _cached_dataclass_field_names(data_type: type) -> Tuple[str, ...]:
    """Return cached dataclass field names for one type."""

    return tuple(data_field.name for data_field in fields(data_type))


@lru_cache(maxsize=512)
def _cached_hashable_signature(callable_object: Any) -> inspect.Signature:
    """Return a cached signature for a hashable callable."""

    return inspect.signature(callable_object)


def _cached_callable_signature(callable_object: Any) -> inspect.Signature:
    """Return a signature while supporting unhashable callable objects."""

    try:
        return _cached_hashable_signature(callable_object)
    except TypeError:
        return inspect.signature(callable_object)


def _result_value_to_data(
    value: Any,
    *,
    include_objects: bool = False,
    depth: int = 0,
    seen: Optional[Set[int]] = None,
) -> Any:
    """Convert core result content into inspection-safe Python data.

    Specialized interaction and molecular objects are preserved by the runtime
    dataclasses. Their dictionary representations omit or summarize opaque
    objects unless ``include_objects`` is true. The export module remains the
    authoritative layer for durable scientific serialization.
    """

    if depth > MAX_CORE_RESULT_DEPTH:
        return "<maximum-depth>"
    if value is None or isinstance(value, (str, int, bool)):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else str(value)
    if isinstance(value, Enum):
        return value.value
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, os.PathLike):
        return os.fspath(value)
    if isinstance(value, (datetime, date)):
        return _normalize_timestamp(value)
    if isinstance(value, AnalysisIssue):
        return value.to_dict()
    if isinstance(value, AnalysisConfig):
        return value.to_dict()

    object_id = id(value)
    if seen is None:
        seen = set()
    if object_id in seen:
        return "<recursive-reference>"

    if isinstance(value, Mapping):
        seen.add(object_id)
        converted = {
            str(key): _result_value_to_data(
                item,
                include_objects=include_objects,
                depth=depth + 1,
                seen=seen,
            )
            for key, item in list(value.items())[:MAX_CORE_RESULT_ITEMS]
        }
        seen.discard(object_id)
        return converted

    if isinstance(value, (list, tuple, set, frozenset, deque)):
        seen.add(object_id)
        converted = [
            _result_value_to_data(
                item,
                include_objects=include_objects,
                depth=depth + 1,
                seen=seen,
            )
            for item in list(value)[:MAX_CORE_RESULT_ITEMS]
        ]
        seen.discard(object_id)
        return converted

    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        seen.add(object_id)
        try:
            converted_value = to_dict()
        except Exception:
            converted_value = None
        seen.discard(object_id)
        if converted_value is not None:
            return _result_value_to_data(
                converted_value,
                include_objects=include_objects,
                depth=depth + 1,
                seen=seen,
            )

    if is_dataclass(value) and not isinstance(value, type):
        seen.add(object_id)
        converted = {}
        for field_name in _cached_dataclass_field_names(type(value)):
            try:
                item = getattr(value, field_name)
            except Exception:
                continue
            converted[field_name] = _result_value_to_data(
                item,
                include_objects=include_objects,
                depth=depth + 1,
                seen=seen,
            )
        seen.discard(object_id)
        return converted

    if include_objects:
        return value

    object_name = getattr(value, "name", None)
    summary: Dict[str, Any] = {
        "type": type(value).__name__,
        "module": type(value).__module__,
    }
    if object_name is not None:
        summary["name"] = str(object_name)
    object_id_value = getattr(value, "id_string", None)
    if object_id_value is None:
        object_id_value = getattr(value, "id", None)
    if object_id_value is not None and not callable(object_id_value):
        summary["id"] = str(object_id_value)
    return summary


def _result_mapping(value: Any) -> Dict[str, Any]:
    """Return a mutable string-keyed mapping."""

    if value is None:
        return {}
    if not isinstance(value, Mapping):
        raise TypeError("Expected a mapping value.")
    return {str(key): item for key, item in value.items()}


def _result_files(value: Any) -> Dict[str, Any]:
    """Normalize generated-file mappings without requiring file existence."""

    data = _result_mapping(value)
    return {
        str(key): item
        for key, item in data.items()
        if str(key).strip()
    }


def _result_sequence(value: Any) -> List[Any]:
    """Normalize a scalar or iterable as a bounded mutable list."""

    if value is None:
        return []
    if isinstance(value, (str, bytes, bytearray, Mapping)):
        return [value]
    try:
        items = list(value)
    except TypeError:
        items = [value]
    return items[:MAX_CORE_RESULT_ITEMS]


def _object_display_name(value: Any, *, fallback: str) -> str:
    """Return a stable display name for an arbitrary object."""

    if value is None:
        return fallback
    for attribute in ("name", "display_name", "id_string", "id"):
        try:
            candidate = getattr(value, attribute)
        except Exception:
            continue
        if candidate is not None and not callable(candidate):
            text = str(candidate).strip()
            if text:
                return text[:MAX_IDENTIFIER_LENGTH]
    return fallback


def _count_result_items(value: Any) -> int:
    """Return a conservative count for an interaction collection."""

    if value is None:
        return 0
    if isinstance(value, Mapping):
        return sum(_count_result_items(item) for item in value.values())
    if isinstance(value, (str, bytes, bytearray)):
        return 1
    try:
        return len(value)
    except (TypeError, AttributeError):
        return 1


# 5.3. Analysis request
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisRequest:
    """Immutable normalized request submitted to the analysis pipeline."""

    input_data: Any = None
    config: AnalysisConfig = field(default_factory=AnalysisConfig)
    request_id: str = field(
        default_factory=lambda: _new_result_identifier("request")
    )
    name: str = DEFAULT_RESULT_NAME
    mode: Union[AnalysisModeName, str] = ANALYSIS_MODE_AUTO
    receptor: Any = None
    poses: Sequence[Any] = field(default_factory=tuple)
    dock_models: Sequence[Any] = field(default_factory=tuple)
    session: Any = None
    requested_stages: Sequence[str] = field(default_factory=tuple)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=_utc_timestamp)

    def __post_init__(self) -> None:
        normalized_config = coerce_analysis_config(self.config)
        normalized_mode = canonicalize_analysis_mode(self.mode)
        if normalized_mode == ANALYSIS_MODE_AUTO:
            configured_mode = normalized_config.runtime.analysis_mode
            if configured_mode != ANALYSIS_MODE_AUTO:
                normalized_mode = configured_mode

        requested_stage_values = _result_sequence(self.requested_stages)
        stages = (
            canonicalize_stage_sequence(requested_stage_values)
            if requested_stage_values
            else normalized_config.desired_stages()
        )
        object.__setattr__(self, "config", normalized_config)
        object.__setattr__(
            self,
            "request_id",
            _normalize_result_identifier(self.request_id, fallback="request"),
        )
        object.__setattr__(
            self,
            "name",
            _normalize_result_name(self.name, fallback=DEFAULT_RESULT_NAME),
        )
        object.__setattr__(self, "mode", normalized_mode)
        object.__setattr__(self, "poses", tuple(_result_sequence(self.poses)))
        object.__setattr__(
            self,
            "dock_models",
            tuple(_result_sequence(self.dock_models)),
        )
        object.__setattr__(self, "requested_stages", tuple(stages))
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(_result_mapping(self.metadata)),
        )
        object.__setattr__(
            self,
            "created_at",
            _normalize_timestamp(self.created_at) or _utc_timestamp(),
        )

    @property
    def pose_count(self) -> int:
        """Return the number of explicit pose inputs."""

        return len(self.poses)

    @property
    def model_count(self) -> int:
        """Return the number of explicit DockModel-like inputs."""

        return len(self.dock_models)

    @property
    def item_count(self) -> int:
        """Return the largest explicit molecular input count."""

        return max(
            self.pose_count,
            self.model_count,
            1 if self.input_data is not None else 0,
        )

    @property
    def is_single_pose(self) -> bool:
        """Return whether the request explicitly selects single-pose mode."""

        return self.mode == ANALYSIS_MODE_SINGLE_POSE

    @property
    def is_multipose(self) -> bool:
        """Return whether the request explicitly selects multipose mode."""

        return self.mode == ANALYSIS_MODE_MULTIPOSE

    @property
    def is_batch(self) -> bool:
        """Return whether the request explicitly selects batch mode."""

        return self.mode == ANALYSIS_MODE_BATCH

    @property
    def is_session(self) -> bool:
        """Return whether the request explicitly selects session mode."""

        return self.mode == ANALYSIS_MODE_SESSION

    def with_config(self, value: AnalysisConfigLike) -> "AnalysisRequest":
        """Return a copy with a replacement configuration."""

        return replace(self, config=coerce_analysis_config(value))

    def with_mode(self, value: Any) -> "AnalysisRequest":
        """Return a copy with a replacement analysis mode."""

        return replace(self, mode=canonicalize_analysis_mode(value))

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe request representation."""

        return {
            "request_id": self.request_id,
            "name": self.name,
            "mode": self.mode,
            "created_at": self.created_at,
            "requested_stages": list(self.requested_stages),
            "config": self.config.to_dict(),
            "input": _result_value_to_data(
                self.input_data,
                include_objects=include_objects,
            ),
            "receptor": _result_value_to_data(
                self.receptor,
                include_objects=include_objects,
            ),
            "poses": _result_value_to_data(
                self.poses,
                include_objects=include_objects,
            ),
            "dock_models": _result_value_to_data(
                self.dock_models,
                include_objects=include_objects,
            ),
            "session": _result_value_to_data(
                self.session,
                include_objects=include_objects,
            ),
            "metadata": _result_value_to_data(self.metadata),
        }


# 5.4. Runtime analysis context
# -----------------------------------------------------------------------------


@dataclass
class AnalysisContext:
    """Mutable runtime state shared by pipeline stages."""

    request: AnalysisRequest
    run_id: str = field(default_factory=lambda: _new_result_identifier("run"))
    config: Optional[AnalysisConfig] = None
    mode: Optional[Union[AnalysisModeName, str]] = None
    status: Union[AnalysisStatus, str] = AnalysisStatus.PENDING
    session: Any = None
    receptor: Any = None
    poses: List[Any] = field(default_factory=list)
    dock_models: List[Any] = field(default_factory=list)
    current_pose_index: Optional[int] = None
    current_stage: Optional[str] = None
    stage_data: Dict[str, Any] = field(default_factory=dict)
    shared_data: Dict[str, Any] = field(default_factory=dict)
    statistics: Dict[str, Any] = field(default_factory=dict)
    files: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    started_at: Optional[str] = None
    progress_callback: Optional[ProgressCallback] = None
    stage_callback: Optional[StageCallback] = None
    cancellation_callback: Optional[CancellationCallback] = None
    _cancel_event: threading.Event = field(
        default_factory=threading.Event,
        repr=False,
        compare=False,
    )
    _lock: threading.RLock = field(
        default_factory=threading.RLock,
        repr=False,
        compare=False,
    )

    def __post_init__(self) -> None:
        if not isinstance(self.request, AnalysisRequest):
            self.request = coerce_analysis_request(self.request)
        self.run_id = _normalize_result_identifier(self.run_id, fallback="run")
        self.config = coerce_analysis_config(self.config or self.request.config)
        selected_mode = self.mode or self.request.mode
        self.mode = canonicalize_analysis_mode(selected_mode)
        self.status = canonicalize_analysis_status(self.status)
        self.session = self.session if self.session is not None else self.request.session
        self.receptor = (
            self.receptor if self.receptor is not None else self.request.receptor
        )
        normalized_poses = _result_sequence(self.poses)
        self.poses = (
            normalized_poses
            if normalized_poses
            else _result_sequence(self.request.poses)
        )
        normalized_models = _result_sequence(self.dock_models)
        self.dock_models = (
            normalized_models
            if normalized_models
            else _result_sequence(self.request.dock_models)
        )
        self.stage_data = _result_mapping(self.stage_data)
        self.shared_data = _result_mapping(self.shared_data)
        self.statistics = _result_mapping(self.statistics)
        self.files = _result_files(self.files)
        base_metadata = dict(self.request.metadata)
        base_metadata.update(_result_mapping(self.metadata))
        self.metadata = base_metadata
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        if self.current_stage is not None:
            self.current_stage = _normalize_optional_stage(self.current_stage)
        if self.current_pose_index is not None:
            self.set_current_pose(self.current_pose_index)

    @property
    def request_id(self) -> str:
        """Return the originating request identifier."""

        return self.request.request_id

    @property
    def pose_count(self) -> int:
        """Return the number of resolved poses or DockModel objects."""

        return max(len(self.poses), len(self.dock_models))

    @property
    def current_pose(self) -> Any:
        """Return the currently selected pose, when available."""

        if self.current_pose_index is None:
            return None
        if 0 <= self.current_pose_index < len(self.poses):
            return self.poses[self.current_pose_index]
        return None

    @property
    def current_dock_model(self) -> Any:
        """Return the currently selected DockModel, when available."""

        if self.current_pose_index is None:
            return None
        if 0 <= self.current_pose_index < len(self.dock_models):
            return self.dock_models[self.current_pose_index]
        return None

    def start(self) -> None:
        """Mark the context as actively running."""

        with self._lock:
            if self.status == AnalysisStatus.PENDING:
                self.status = AnalysisStatus.PREPARING
            if self.status == AnalysisStatus.PREPARING:
                self.status = AnalysisStatus.RUNNING
            elif self.status != AnalysisStatus.RUNNING:
                raise AnalysisStateError(
                    f"Cannot start context from status {self.status.value!r}."
                )
            if self.started_at is None:
                self.started_at = _utc_timestamp()

    def set_status(self, value: Any, *, force: bool = False) -> AnalysisStatus:
        """Update the run status and validate its lifecycle transition."""

        target = canonicalize_analysis_status(value)
        with self._lock:
            if not force:
                validate_analysis_status_transition(self.status, target)
            self.status = target
        return target

    def set_current_pose(self, index: Optional[int]) -> None:
        """Select the active pose index."""

        if index is None:
            self.current_pose_index = None
            return
        normalized = int(index)
        if normalized < 0:
            raise IndexError("Current pose index cannot be negative.")
        if self.pose_count and normalized >= self.pose_count:
            raise IndexError(
                f"Current pose index {normalized} exceeds {self.pose_count} items."
            )
        self.current_pose_index = normalized

    def set_current_stage(self, stage: Optional[Any]) -> None:
        """Select or clear the active pipeline stage."""

        self.current_stage = _normalize_optional_stage(stage)

    def set_stage_data(self, stage: Any, value: Any) -> None:
        """Store runtime data associated with one stage."""

        key = _normalize_optional_stage(stage)
        if key is None:
            raise ValueError("Stage data requires a stage name.")
        with self._lock:
            self.stage_data[key] = value

    def get_stage_data(self, stage: Any, default: Any = None) -> Any:
        """Return runtime data associated with one stage."""

        key = _normalize_optional_stage(stage)
        return self.stage_data.get(key, default) if key else default

    def set_shared(self, key: Any, value: Any) -> None:
        """Store shared runtime data."""

        normalized = str(key).strip()
        if not normalized:
            raise ValueError("Shared-data key cannot be empty.")
        with self._lock:
            self.shared_data[normalized] = value

    def get_shared(self, key: Any, default: Any = None) -> Any:
        """Return shared runtime data."""

        return self.shared_data.get(str(key).strip(), default)

    def cancel(self) -> None:
        """Request cooperative cancellation."""

        self._cancel_event.set()

    def is_cancelled(self) -> bool:
        """Return whether cancellation was requested."""

        if self._cancel_event.is_set():
            return True
        callback = self.cancellation_callback
        if callback is None:
            return False
        try:
            return bool(callback())
        except Exception as exc:
            raise AnalysisConcurrencyError(
                "The cancellation callback failed.",
                cause=exc,
            ) from exc

    def raise_if_cancelled(self, *, stage: Optional[str] = None) -> None:
        """Raise :class:`AnalysisCancelledError` after cancellation."""

        if self.is_cancelled():
            raise AnalysisCancelledError(
                "Analysis execution was cancelled.",
                stage=stage or self.current_stage,
            )

    def update_progress(
        self,
        stage: Any,
        completed: int,
        total: int,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        """Send one normalized progress update."""

        callback = self.progress_callback
        if callback is None:
            return
        stage_name = _normalize_optional_stage(stage) or STAGE_FINALIZATION
        completed_value = max(0, int(completed))
        total_value = max(0, int(total))
        if total_value and completed_value > total_value:
            completed_value = total_value
        callback(stage_name, completed_value, total_value, dict(metadata or {}))

    def notify_stage(self, result: "AnalysisStageResult") -> None:
        """Send a completed stage result to the stage callback."""

        if self.stage_callback is not None:
            self.stage_callback(result.stage, result)

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe runtime context representation."""

        return {
            "run_id": self.run_id,
            "request_id": self.request_id,
            "mode": self.mode,
            "status": self.status.value,
            "current_stage": self.current_stage,
            "current_pose_index": self.current_pose_index,
            "pose_count": self.pose_count,
            "started_at": self.started_at,
            "cancelled": self.is_cancelled(),
            "config": self.config.to_dict() if self.config else None,
            "session": _result_value_to_data(
                self.session,
                include_objects=include_objects,
            ),
            "receptor": _result_value_to_data(
                self.receptor,
                include_objects=include_objects,
            ),
            "poses": _result_value_to_data(
                self.poses,
                include_objects=include_objects,
            ),
            "dock_models": _result_value_to_data(
                self.dock_models,
                include_objects=include_objects,
            ),
            "stage_data": _result_value_to_data(self.stage_data),
            "shared_data": _result_value_to_data(self.shared_data),
            "statistics": _result_value_to_data(self.statistics),
            "files": _result_value_to_data(self.files),
            "metadata": _result_value_to_data(self.metadata),
        }


# 5.5. Structured diagnostics collection
# -----------------------------------------------------------------------------


@dataclass
class AnalysisDiagnostics:
    """Mutable collection of analysis messages, warnings and errors."""

    issues: List[AnalysisIssue] = field(default_factory=list)
    messages: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.issues = _coerce_analysis_issues(self.issues)
        self.messages = _normalize_message_sequence(self.messages)
        self.metadata = _result_mapping(self.metadata)

    @property
    def errors(self) -> Tuple[AnalysisIssue, ...]:
        """Return error and cancellation issues."""

        return tuple(issue for issue in self.issues if issue.is_error)

    @property
    def warnings(self) -> Tuple[AnalysisIssue, ...]:
        """Return warning issues."""

        return tuple(issue for issue in self.issues if issue.is_warning)

    @property
    def notices(self) -> Tuple[AnalysisIssue, ...]:
        """Return informational diagnostic issues."""

        return tuple(
            issue
            for issue in self.issues
            if not issue.is_error and not issue.is_warning
        )

    @property
    def has_errors(self) -> bool:
        """Return whether at least one error is recorded."""

        return bool(self.errors)

    @property
    def has_warnings(self) -> bool:
        """Return whether at least one warning is recorded."""

        return bool(self.warnings)

    @property
    def highest_severity(self) -> IssueSeverity:
        """Return the highest recorded issue severity."""

        if not self.issues:
            return IssueSeverity.INFO
        return max(issue.severity for issue in self.issues)

    def add_issue(self, value: Any) -> AnalysisIssue:
        """Normalize and append one issue."""

        issue = _coerce_analysis_issue(value)
        if len(self.issues) < MAX_DIAGNOSTIC_MESSAGES:
            self.issues.append(issue)
        return issue

    def add_message(self, message: Any) -> Optional[str]:
        """Append one non-empty informational message."""

        text = str(message).strip()
        if not text:
            return None
        if len(self.messages) < MAX_DIAGNOSTIC_MESSAGES:
            self.messages.append(text)
        return text

    def add_error(
        self,
        error: Any,
        *,
        stage: Optional[str] = None,
        include_traceback: bool = False,
    ) -> AnalysisIssue:
        """Append an error issue."""

        if isinstance(error, BaseException):
            issue = exception_to_issue(
                error,
                stage=stage,
                include_traceback=include_traceback,
            )
        else:
            issue = AnalysisIssue(
                kind=IssueKind.ERROR,
                severity=IssueSeverity.ERROR,
                code="analysis_error",
                message=str(error),
                stage=stage,
                recoverable=False,
                action=RecoveryAction.ABORT_RUN,
            )
        return self.add_issue(issue)

    def add_warning(
        self,
        warning: Any,
        *,
        stage: Optional[str] = None,
    ) -> AnalysisIssue:
        """Append a warning issue."""

        if isinstance(warning, Warning):
            issue = warning_to_issue(warning, stage=stage)
        else:
            issue = AnalysisIssue(
                kind=IssueKind.WARNING,
                severity=IssueSeverity.WARNING,
                code="analysis_warning",
                message=str(warning),
                stage=stage,
                recoverable=True,
                action=RecoveryAction.CONTINUE_PARTIAL,
                scope=FailureScope.STAGE if stage else FailureScope.RUN,
            )
        return self.add_issue(issue)

    def extend(self, value: Any) -> None:
        """Append issues and messages from another diagnostics object."""

        if value is None:
            return
        if isinstance(value, AnalysisDiagnostics):
            for issue in value.issues:
                self.add_issue(issue)
            for message in value.messages:
                self.add_message(message)
            self.metadata.update(value.metadata)
            return
        if isinstance(value, Mapping):
            for issue in _coerce_analysis_issues(value.get("issues")):
                self.add_issue(issue)
            for issue in _coerce_analysis_issues(value.get("warnings")):
                self.add_issue(issue)
            for issue in _coerce_analysis_issues(value.get("errors")):
                self.add_issue(issue)
            for message in _normalize_message_sequence(value.get("messages")):
                self.add_message(message)
            metadata = value.get("metadata")
            if isinstance(metadata, Mapping):
                self.metadata.update(metadata)
            return
        for issue in _coerce_analysis_issues(value):
            self.add_issue(issue)

    def for_stage(self, stage: Any) -> Tuple[AnalysisIssue, ...]:
        """Return issues associated with one stage."""

        normalized = _normalize_optional_stage(stage)
        return tuple(issue for issue in self.issues if issue.stage == normalized)

    def counts(self) -> Dict[str, int]:
        """Return issue and message counts."""

        return {
            "issues": len(self.issues),
            "errors": len(self.errors),
            "warnings": len(self.warnings),
            "notices": len(self.notices),
            "messages": len(self.messages),
        }

    def summary(self) -> str:
        """Return a concise diagnostic summary."""

        counts = self.counts()
        return (
            f"{counts['errors']} errors, {counts['warnings']} warnings, "
            f"{counts['notices']} notices and {counts['messages']} messages"
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready diagnostics representation."""

        return {
            "summary": self.summary(),
            "counts": self.counts(),
            "highest_severity": self.highest_severity.name.lower(),
            "messages": list(self.messages),
            "issues": [issue.to_dict() for issue in self.issues],
            "warnings": [issue.to_dict() for issue in self.warnings],
            "errors": [issue.to_dict() for issue in self.errors],
            "metadata": _result_value_to_data(self.metadata),
        }


# 5.6. Per-stage result
# -----------------------------------------------------------------------------


@dataclass
class AnalysisStageResult:
    """Result and lifecycle information produced by one pipeline stage."""

    stage: str
    status: Union[StageStatus, str] = StageStatus.PENDING
    value: Any = None
    result_type: str = RESULT_TYPE_STAGE
    attempt: int = 1
    required: bool = False
    cached: bool = False
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    skipped_reason: Optional[str] = None
    messages: List[str] = field(default_factory=list)
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    statistics: Dict[str, Any] = field(default_factory=dict)
    files: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    input_summary: Dict[str, Any] = field(default_factory=dict)
    output_summary: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        normalized_stage = _normalize_optional_stage(self.stage)
        if normalized_stage is None:
            raise ValueError("Stage result requires a stage name.")
        self.stage = normalized_stage
        self.status = canonicalize_stage_status(self.status)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_STAGE,
        )
        self.attempt = max(1, int(self.attempt))
        self.required = bool(self.required)
        self.cached = bool(self.cached)
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.skipped_reason = _normalize_optional_text(self.skipped_reason)
        self.messages = _normalize_message_sequence(self.messages)
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.statistics = _result_mapping(self.statistics)
        self.files = _result_files(self.files)
        self.metadata = _result_mapping(self.metadata)
        self.input_summary = _result_mapping(self.input_summary)
        self.output_summary = _result_mapping(self.output_summary)
        if self.finished_at and self.duration_seconds is None and self.started_at:
            self.duration_seconds = self._calculate_duration()

    @property
    def is_terminal(self) -> bool:
        """Return whether the stage reached a terminal status."""

        return is_terminal_stage_status(self.status)

    @property
    def succeeded(self) -> bool:
        """Return whether the stage produced an accepted result."""

        return is_success_stage_status(self.status)

    @property
    def failed(self) -> bool:
        """Return whether the stage failed, blocked or was cancelled."""

        return is_failure_stage_status(self.status)

    @property
    def issues(self) -> Tuple[AnalysisIssue, ...]:
        """Return all stage diagnostic issues."""

        return tuple(self.diagnostics.issues)

    @property
    def warnings(self) -> Tuple[AnalysisIssue, ...]:
        """Return stage warning issues."""

        return self.diagnostics.warnings

    @property
    def errors(self) -> Tuple[AnalysisIssue, ...]:
        """Return stage error issues."""

        return self.diagnostics.errors

    def _calculate_duration(self) -> Optional[float]:
        """Calculate duration from ISO timestamps when possible."""

        if not self.started_at or not self.finished_at:
            return None
        try:
            started = datetime.fromisoformat(self.started_at)
            finished = datetime.fromisoformat(self.finished_at)
        except (TypeError, ValueError):
            return None
        return max(0.0, (finished - started).total_seconds())

    def _prepare_running_transition(self) -> None:
        """Move a pending or ready result to the running state."""

        if self.status == StageStatus.PENDING:
            self.set_status(StageStatus.RUNNING)
        elif self.status == StageStatus.READY:
            self.set_status(StageStatus.RUNNING)

    def set_status(self, value: Any, *, force: bool = False) -> StageStatus:
        """Update and validate the stage status."""

        target = canonicalize_stage_status(value)
        if target == self.status:
            return target
        if not force:
            validate_stage_status_transition(self.status, target)
        self.status = target
        return target

    def mark_ready(self) -> "AnalysisStageResult":
        """Mark the stage as ready for execution."""

        self.set_status(StageStatus.READY)
        return self

    def start(self) -> "AnalysisStageResult":
        """Mark the stage as running."""

        self._prepare_running_transition()
        if self.status != StageStatus.RUNNING:
            raise AnalysisStateError(
                f"Cannot start stage {self.stage!r} from {self.status.value!r}."
            )
        if self.started_at is None:
            self.started_at = _utc_timestamp()
        self.finished_at = None
        self.duration_seconds = None
        return self

    def finish(
        self,
        status: Any,
        *,
        value: Any = None,
        message: Optional[str] = None,
    ) -> "AnalysisStageResult":
        """Finalize the stage with a terminal status."""

        target = canonicalize_stage_status(status)
        if target not in STAGE_TERMINAL_STATUSES:
            raise ValueError("Stage finish status must be terminal.")
        if self.status in {StageStatus.PENDING, StageStatus.READY}:
            self.start()
        self.set_status(target)
        self.value = value
        if message:
            self.add_message(message)
        self.finished_at = _utc_timestamp()
        self.duration_seconds = self._calculate_duration()
        return self

    def succeed(
        self,
        value: Any = None,
        *,
        message: Optional[str] = None,
    ) -> "AnalysisStageResult":
        """Finalize the stage successfully."""

        return self.finish(StageStatus.SUCCEEDED, value=value, message=message)

    def partial(
        self,
        value: Any = None,
        *,
        issue: Any = None,
        message: Optional[str] = None,
    ) -> "AnalysisStageResult":
        """Finalize the stage with a useful partial result."""

        if issue is not None:
            self.add_issue(issue)
        return self.finish(StageStatus.PARTIAL, value=value, message=message)

    def fail(
        self,
        error: Any,
        *,
        include_traceback: bool = False,
    ) -> "AnalysisStageResult":
        """Finalize the stage as failed and record an error."""

        self.diagnostics.add_error(
            error,
            stage=self.stage,
            include_traceback=include_traceback,
        )
        return self.finish(StageStatus.FAILED, value=None)

    def skip(self, reason: Any = "Stage was not requested.") -> "AnalysisStageResult":
        """Finalize the stage as skipped."""

        self.skipped_reason = str(reason).strip() or "Stage was skipped."
        if self.status == StageStatus.PENDING:
            self.set_status(StageStatus.SKIPPED)
        elif self.status == StageStatus.READY:
            self.set_status(StageStatus.SKIPPED)
        else:
            self.set_status(StageStatus.SKIPPED)
        self.finished_at = _utc_timestamp()
        if self.started_at:
            self.duration_seconds = self._calculate_duration()
        return self

    def block(self, reason: Any) -> "AnalysisStageResult":
        """Finalize the stage as blocked by a dependency or capability."""

        message = str(reason).strip() or "Stage was blocked."
        self.add_issue(
            AnalysisIssue(
                kind=IssueKind.ERROR,
                severity=IssueSeverity.ERROR,
                code="analysis_stage_blocked",
                message=message,
                stage=self.stage,
                recoverable=True,
                action=RecoveryAction.SKIP_STAGE,
                scope=FailureScope.STAGE,
            )
        )
        self.set_status(StageStatus.BLOCKED)
        self.finished_at = _utc_timestamp()
        return self

    def cancel(self, reason: Any = "Stage execution was cancelled.") -> "AnalysisStageResult":
        """Finalize the stage as cancelled."""

        self.add_issue(
            AnalysisIssue(
                kind=IssueKind.CANCELLATION,
                severity=IssueSeverity.ERROR,
                code="analysis_stage_cancelled",
                message=str(reason),
                stage=self.stage,
                recoverable=False,
                action=RecoveryAction.ABORT_RUN,
                scope=FailureScope.STAGE,
            )
        )
        self.set_status(StageStatus.CANCELLED)
        self.finished_at = _utc_timestamp()
        return self

    def add_issue(self, issue: Any) -> AnalysisIssue:
        """Append one stage-scoped issue."""

        normalized = _coerce_analysis_issue(issue)
        if normalized.stage is None:
            normalized = replace(normalized, stage=self.stage)
        return self.diagnostics.add_issue(normalized)

    def add_message(self, message: Any) -> Optional[str]:
        """Append one stage message."""

        text = self.diagnostics.add_message(message)
        if text and len(self.messages) < MAX_DIAGNOSTIC_MESSAGES:
            self.messages.append(text)
        return text

    def to_dict(self, *, include_value: bool = True) -> Dict[str, Any]:
        """Return an inspection-safe stage result representation."""

        data = {
            RESULT_KEY_TYPE: self.result_type,
            "stage": self.stage,
            RESULT_KEY_STATUS: self.status.value,
            "attempt": self.attempt,
            "required": self.required,
            "cached": self.cached,
            RESULT_KEY_STARTED_AT: self.started_at,
            RESULT_KEY_FINISHED_AT: self.finished_at,
            RESULT_KEY_DURATION_SECONDS: self.duration_seconds,
            "skipped_reason": self.skipped_reason,
            "messages": list(self.messages),
            RESULT_KEY_DIAGNOSTICS: self.diagnostics.to_dict(),
            RESULT_KEY_STATISTICS: _result_value_to_data(self.statistics),
            RESULT_KEY_FILES: _result_value_to_data(self.files),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
            "input_summary": _result_value_to_data(self.input_summary),
            "output_summary": _result_value_to_data(self.output_summary),
        }
        if include_value:
            data["value"] = _result_value_to_data(self.value)
        return data


# 5.7. Integrated interaction bundle
# -----------------------------------------------------------------------------


@dataclass
class InteractionAnalysisBundle:
    """Integrated view of all interaction families for one pose."""

    contacts: List[Any] = field(default_factory=list)
    hbonds: List[Any] = field(default_factory=list)
    hydrophobic: List[Any] = field(default_factory=list)
    pi: Dict[str, List[Any]] = field(default_factory=dict)
    saltbridge: List[Any] = field(default_factory=list)
    hotspots: List[Any] = field(default_factory=list)
    residues: List[Any] = field(default_factory=list)
    statistics: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = RESULT_TYPE_INTERACTIONS

    def __post_init__(self) -> None:
        self.contacts = _result_sequence(self.contacts)
        self.hbonds = _result_sequence(self.hbonds)
        self.hydrophobic = _result_sequence(self.hydrophobic)
        self.saltbridge = _result_sequence(self.saltbridge)
        self.hotspots = _result_sequence(self.hotspots)
        self.residues = _result_sequence(self.residues)
        self.statistics = _result_mapping(self.statistics)
        self.metadata = _result_mapping(self.metadata)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_INTERACTIONS,
        )

        normalized_pi: Dict[str, List[Any]] = {}
        if isinstance(self.pi, Mapping):
            for key, value in self.pi.items():
                try:
                    subtype = canonicalize_pi_subtype(key)
                except ValueError:
                    subtype = _normalize_status_token(key, field_name="pi subtype")
                normalized_pi.setdefault(subtype, []).extend(_result_sequence(value))
        elif self.pi is not None:
            normalized_pi[PI_SUBTYPE_STACKING] = _result_sequence(self.pi)
        self.pi = normalized_pi

    @property
    def families(self) -> Tuple[str, ...]:
        """Return interaction families containing at least one result."""

        return tuple(
            family
            for family in INTERACTION_FAMILY_ORDER
            if self.count(family) > 0
        )

    @property
    def total_count(self) -> int:
        """Return the total number of integrated interactions."""

        return sum(self.count(family) for family in INTERACTION_FAMILY_ORDER)

    @property
    def is_empty(self) -> bool:
        """Return whether no interaction result is stored."""

        return self.total_count == 0

    def get(self, family: Any, default: Any = None) -> Any:
        """Return one canonical interaction-family collection."""

        try:
            canonical = canonicalize_interaction_family(family)
        except ValueError:
            return default
        if canonical == INTERACTION_FAMILY_CONTACTS:
            return self.contacts
        if canonical == INTERACTION_FAMILY_HBONDS:
            return self.hbonds
        if canonical == INTERACTION_FAMILY_HYDROPHOBIC:
            return self.hydrophobic
        if canonical == INTERACTION_FAMILY_PI:
            return self.pi
        if canonical == INTERACTION_FAMILY_SALTBRIDGE:
            return self.saltbridge
        return default

    def set(self, family: Any, value: Any) -> None:
        """Replace one canonical interaction-family collection."""

        canonical = canonicalize_interaction_family(family)
        if canonical == INTERACTION_FAMILY_CONTACTS:
            self.contacts = _result_sequence(value)
        elif canonical == INTERACTION_FAMILY_HBONDS:
            self.hbonds = _result_sequence(value)
        elif canonical == INTERACTION_FAMILY_HYDROPHOBIC:
            self.hydrophobic = _result_sequence(value)
        elif canonical == INTERACTION_FAMILY_PI:
            replacement = InteractionAnalysisBundle(pi=value)
            self.pi = replacement.pi
        elif canonical == INTERACTION_FAMILY_SALTBRIDGE:
            self.saltbridge = _result_sequence(value)

    def add(self, family: Any, value: Any, *, subtype: Optional[Any] = None) -> None:
        """Append one interaction or collection to a family."""

        canonical = canonicalize_interaction_family(family)
        items = _result_sequence(value)
        if canonical == INTERACTION_FAMILY_PI:
            pi_subtype = canonicalize_pi_subtype(subtype or PI_SUBTYPE_STACKING)
            self.pi.setdefault(pi_subtype, []).extend(items)
            return
        collection = self.get(canonical)
        if collection is None:
            self.set(canonical, items)
        else:
            collection.extend(items)

    def count(self, family: Any) -> int:
        """Return the number of interactions in one family."""

        value = self.get(family, [])
        return _count_result_items(value)

    def counts(self) -> Dict[str, int]:
        """Return counts for every canonical interaction family."""

        counts = {
            family: self.count(family)
            for family in INTERACTION_FAMILY_ORDER
        }
        counts["total"] = sum(counts.values())
        return counts

    def pi_counts(self) -> Dict[str, int]:
        """Return counts for each pi-interaction subtype."""

        return {
            subtype: _count_result_items(values)
            for subtype, values in sorted(self.pi.items())
        }

    def flatten(
        self,
        *,
        include_family: bool = False,
        include_pi_subtype: bool = False,
    ) -> List[Any]:
        """Return a flat list of all integrated interactions."""

        flattened: List[Any] = []
        for family in INTERACTION_FAMILY_ORDER:
            values = self.get(family, [])
            if family == INTERACTION_FAMILY_PI:
                for subtype, subtype_values in values.items():
                    for interaction in subtype_values:
                        if include_family or include_pi_subtype:
                            flattened.append(
                                {
                                    "family": family,
                                    "subtype": subtype,
                                    "interaction": interaction,
                                }
                            )
                        else:
                            flattened.append(interaction)
            else:
                for interaction in values:
                    if include_family:
                        flattened.append(
                            {"family": family, "interaction": interaction}
                        )
                    else:
                        flattened.append(interaction)
        return flattened

    def merge(
        self,
        other: Any,
        *,
        deduplicate_identity: bool = False,
    ) -> "InteractionAnalysisBundle":
        """Merge another bundle into this bundle."""

        incoming = coerce_interaction_bundle(other)
        for family in INTERACTION_FAMILY_ORDER:
            if family == INTERACTION_FAMILY_PI:
                for subtype, values in incoming.pi.items():
                    self.pi.setdefault(subtype, []).extend(values)
            else:
                current = self.get(family)
                current.extend(incoming.get(family, []))
        self.hotspots.extend(incoming.hotspots)
        self.residues.extend(incoming.residues)
        self.statistics.update(incoming.statistics)
        self.metadata.update(incoming.metadata)

        if deduplicate_identity:
            self._deduplicate_by_identity()
        return self

    def _deduplicate_by_identity(self) -> None:
        """Remove repeated references without chemical equivalence claims."""

        def unique_identity(values: List[Any]) -> List[Any]:
            seen_ids: Set[int] = set()
            unique: List[Any] = []
            for item in values:
                marker = id(item)
                if marker not in seen_ids:
                    unique.append(item)
                    seen_ids.add(marker)
            return unique

        self.contacts = unique_identity(self.contacts)
        self.hbonds = unique_identity(self.hbonds)
        self.hydrophobic = unique_identity(self.hydrophobic)
        self.saltbridge = unique_identity(self.saltbridge)
        self.hotspots = unique_identity(self.hotspots)
        self.residues = unique_identity(self.residues)
        self.pi = {
            subtype: unique_identity(values)
            for subtype, values in self.pi.items()
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe interaction representation."""

        return {
            RESULT_KEY_TYPE: self.result_type,
            "counts": self.counts(),
            "pi_counts": self.pi_counts(),
            "families": list(self.families),
            INTERACTION_FAMILY_CONTACTS: _result_value_to_data(
                self.contacts,
                include_objects=include_objects,
            ),
            INTERACTION_FAMILY_HBONDS: _result_value_to_data(
                self.hbonds,
                include_objects=include_objects,
            ),
            INTERACTION_FAMILY_HYDROPHOBIC: _result_value_to_data(
                self.hydrophobic,
                include_objects=include_objects,
            ),
            INTERACTION_FAMILY_PI: _result_value_to_data(
                self.pi,
                include_objects=include_objects,
            ),
            INTERACTION_FAMILY_SALTBRIDGE: _result_value_to_data(
                self.saltbridge,
                include_objects=include_objects,
            ),
            "hotspots": _result_value_to_data(
                self.hotspots,
                include_objects=include_objects,
            ),
            "residues": _result_value_to_data(
                self.residues,
                include_objects=include_objects,
            ),
            RESULT_KEY_STATISTICS: _result_value_to_data(self.statistics),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
        }


# 5.8. Shared result mixin helpers
# -----------------------------------------------------------------------------


def _coerce_stage_result(value: Any, *, stage: Optional[str] = None) -> AnalysisStageResult:
    """Coerce a stage-result-like value."""

    if isinstance(value, AnalysisStageResult):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        value_stage = data.pop("stage", stage)
        if value_stage is None:
            raise ValueError("Stage-result mapping requires a stage name.")
        diagnostics = data.pop("diagnostics", AnalysisDiagnostics())
        return AnalysisStageResult(
            stage=value_stage,
            status=data.pop("status", StageStatus.PENDING),
            value=data.pop("value", None),
            result_type=data.pop("result_type", data.pop("type", RESULT_TYPE_STAGE)),
            attempt=data.pop("attempt", 1),
            required=data.pop("required", False),
            cached=data.pop("cached", False),
            started_at=data.pop("started_at", None),
            finished_at=data.pop("finished_at", None),
            duration_seconds=data.pop("duration_seconds", None),
            skipped_reason=data.pop("skipped_reason", None),
            messages=data.pop("messages", []),
            diagnostics=diagnostics,
            statistics=data.pop("statistics", {}),
            files=data.pop("files", {}),
            metadata=data.pop("metadata", data),
            input_summary=data.pop("input_summary", {}),
            output_summary=data.pop("output_summary", {}),
        )
    if stage is None:
        raise TypeError("A stage name is required for a raw stage value.")
    return AnalysisStageResult(
        stage=stage,
        status=StageStatus.SUCCEEDED,
        value=value,
        started_at=_utc_timestamp(),
        finished_at=_utc_timestamp(),
        duration_seconds=0.0,
    )


def _coerce_stage_result_map(value: Any) -> "OrderedDict[str, AnalysisStageResult]":
    """Normalize a stage result mapping or sequence."""

    results: "OrderedDict[str, AnalysisStageResult]" = OrderedDict()
    if value is None:
        return results
    if isinstance(value, Mapping):
        iterator = value.items()
    else:
        items = _result_sequence(value)
        iterator = ((getattr(item, "stage", None), item) for item in items)
    for stage, item in iterator:
        result = _coerce_stage_result(item, stage=stage)
        results[result.stage] = result
    return OrderedDict(
        sorted(results.items(), key=lambda item: stage_sort_key(item[0]))
    )


def _derive_result_duration(
    started_at: Optional[str],
    finished_at: Optional[str],
) -> Optional[float]:
    """Calculate a non-negative duration from result timestamps."""

    if not started_at or not finished_at:
        return None
    try:
        started = datetime.fromisoformat(started_at)
        finished = datetime.fromisoformat(finished_at)
    except (TypeError, ValueError):
        return None
    return max(0.0, (finished - started).total_seconds())


def _derive_status_from_pose_results(
    results: Sequence["PoseAnalysisResult"],
) -> AnalysisStatus:
    """Derive an aggregate status from pose results."""

    if not results:
        return AnalysisStatus.SKIPPED
    statuses = [result.status for result in results]
    if all(status == AnalysisStatus.SUCCEEDED for status in statuses):
        return AnalysisStatus.SUCCEEDED
    if all(status == AnalysisStatus.CANCELLED for status in statuses):
        return AnalysisStatus.CANCELLED
    if all(status == AnalysisStatus.FAILED for status in statuses):
        return AnalysisStatus.FAILED
    if any(status in ANALYSIS_SUCCESS_STATUSES for status in statuses):
        return AnalysisStatus.PARTIAL
    if any(status == AnalysisStatus.CANCELLED for status in statuses):
        return AnalysisStatus.CANCELLED
    return AnalysisStatus.FAILED


def _finalize_result_timing(result: Any) -> None:
    """Set missing finish time and duration on a result object."""

    if getattr(result, "started_at", None) is None:
        result.started_at = _utc_timestamp()
    if getattr(result, "finished_at", None) is None:
        result.finished_at = _utc_timestamp()
    if getattr(result, "duration_seconds", None) is None:
        result.duration_seconds = _derive_result_duration(
            result.started_at,
            result.finished_at,
        )


# 5.9. Single-pose result
# -----------------------------------------------------------------------------


@dataclass
class PoseAnalysisResult:
    """Integrated result for one receptor-ligand pose."""

    pose_id: str = field(default_factory=lambda: _new_result_identifier("pose"))
    name: str = DEFAULT_POSE_RESULT_NAME
    status: Union[AnalysisStatus, str] = AnalysisStatus.PENDING
    dock_model: Any = None
    receptor: Any = None
    ligand: Any = None
    pose: Any = None
    interactions: InteractionAnalysisBundle = field(
        default_factory=InteractionAnalysisBundle
    )
    stage_results: MutableMapping[str, AnalysisStageResult] = field(
        default_factory=OrderedDict
    )
    scoring: Any = None
    reports: Dict[str, Any] = field(default_factory=dict)
    exports: Dict[str, Any] = field(default_factory=dict)
    visualizations: Dict[str, Any] = field(default_factory=dict)
    statistics: Dict[str, Any] = field(default_factory=dict)
    files: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    provenance: Dict[str, Any] = field(default_factory=dict)
    timings: Dict[str, Any] = field(default_factory=dict)
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    result_type: str = RESULT_TYPE_POSE

    def __post_init__(self) -> None:
        self.pose_id = _normalize_result_identifier(self.pose_id, fallback="pose")
        inferred_name = _object_display_name(
            self.dock_model or self.pose,
            fallback=DEFAULT_POSE_RESULT_NAME,
        )
        selected_name = (
            inferred_name
            if self.name in {None, "", DEFAULT_POSE_RESULT_NAME}
            else self.name
        )
        self.name = _normalize_result_name(selected_name, fallback=inferred_name)
        self.status = canonicalize_analysis_status(self.status)
        if not isinstance(self.interactions, InteractionAnalysisBundle):
            self.interactions = coerce_interaction_bundle(self.interactions)
        self.stage_results = _coerce_stage_result_map(self.stage_results)
        self.reports = _result_mapping(self.reports)
        self.exports = _result_mapping(self.exports)
        self.visualizations = _result_mapping(self.visualizations)
        self.statistics = _result_mapping(self.statistics)
        self.files = _result_files(self.files)
        self.metadata = _result_mapping(self.metadata)
        self.provenance = _result_mapping(self.provenance)
        self.timings = _result_mapping(self.timings)
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_POSE,
        )
        if self.finished_at and self.duration_seconds is None:
            self.duration_seconds = _derive_result_duration(
                self.started_at,
                self.finished_at,
            )

    @property
    def succeeded(self) -> bool:
        """Return whether the pose result is accepted as successful."""

        return is_success_analysis_status(self.status)

    @property
    def failed(self) -> bool:
        """Return whether the pose result failed or was cancelled."""

        return is_failure_analysis_status(self.status)

    @property
    def interaction_count(self) -> int:
        """Return the integrated interaction count."""

        return self.interactions.total_count

    @property
    def completed_stages(self) -> Tuple[str, ...]:
        """Return stages with successful terminal states."""

        return tuple(
            stage
            for stage, result in self.stage_results.items()
            if result.succeeded
        )

    @property
    def failed_stages(self) -> Tuple[str, ...]:
        """Return stages with failure terminal states."""

        return tuple(
            stage
            for stage, result in self.stage_results.items()
            if result.failed
        )

    def add_stage_result(self, value: Any, *, stage: Optional[str] = None) -> AnalysisStageResult:
        """Add or replace one stage result."""

        result = _coerce_stage_result(value, stage=stage)
        self.stage_results[result.stage] = result
        self.stage_results = OrderedDict(
            sorted(
                self.stage_results.items(),
                key=lambda item: stage_sort_key(item[0]),
            )
        )
        self.diagnostics.extend(result.diagnostics)
        if result.duration_seconds is not None:
            self.timings[result.stage] = result.duration_seconds
        self.files.update(result.files)
        return result

    def get_stage_result(self, stage: Any) -> Optional[AnalysisStageResult]:
        """Return one stage result."""

        normalized = _normalize_optional_stage(stage)
        return self.stage_results.get(normalized) if normalized else None

    def derive_status(self) -> AnalysisStatus:
        """Derive pose status from its stage results and diagnostics."""

        if self.stage_results:
            stage_statuses = [result.status for result in self.stage_results.values()]
            derived = derive_analysis_status(stage_statuses)
            if (
                derived == AnalysisStatus.SKIPPED
                and (self.interaction_count > 0 or self.scoring is not None)
            ):
                return AnalysisStatus.SUCCEEDED
            return derived
        if self.diagnostics.has_errors:
            return AnalysisStatus.FAILED
        if self.interaction_count > 0 or self.scoring is not None:
            return AnalysisStatus.SUCCEEDED
        return self.status

    def finalize(self, status: Optional[Any] = None) -> "PoseAnalysisResult":
        """Finalize timing, statistics and status."""

        self.status = (
            canonicalize_analysis_status(status)
            if status is not None
            else self.derive_status()
        )
        _finalize_result_timing(self)
        self.statistics.setdefault(
            STATISTICS_KEY_TOTAL_INTERACTIONS,
            self.interaction_count,
        )
        self.statistics.setdefault(
            STATISTICS_KEY_COMPLETED_STAGES,
            list(self.completed_stages),
        )
        self.statistics.setdefault(
            STATISTICS_KEY_FAILED_STAGES,
            list(self.failed_stages),
        )
        return self

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe pose result representation."""

        return {
            RESULT_KEY_SCHEMA: ANALYSIS_SCHEMA_NAME,
            RESULT_KEY_VERSION: ANALYSIS_SCHEMA_VERSION,
            RESULT_KEY_TYPE: self.result_type,
            "pose_id": self.pose_id,
            "name": self.name,
            RESULT_KEY_STATUS: self.status.value,
            "dock_model": _result_value_to_data(
                self.dock_model,
                include_objects=include_objects,
            ),
            "receptor": _result_value_to_data(
                self.receptor,
                include_objects=include_objects,
            ),
            "ligand": _result_value_to_data(
                self.ligand,
                include_objects=include_objects,
            ),
            "pose": _result_value_to_data(
                self.pose,
                include_objects=include_objects,
            ),
            RESULT_KEY_INTERACTIONS: self.interactions.to_dict(
                include_objects=include_objects
            ),
            RESULT_KEY_STAGES: {
                stage: result.to_dict()
                for stage, result in self.stage_results.items()
            },
            RESULT_KEY_SCORING: _result_value_to_data(self.scoring),
            RESULT_KEY_REPORTS: _result_value_to_data(self.reports),
            RESULT_KEY_EXPORTS: _result_value_to_data(self.exports),
            RESULT_KEY_VISUALIZATIONS: _result_value_to_data(self.visualizations),
            RESULT_KEY_STATISTICS: _result_value_to_data(self.statistics),
            RESULT_KEY_FILES: _result_value_to_data(self.files),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
            RESULT_KEY_PROVENANCE: _result_value_to_data(self.provenance),
            RESULT_KEY_TIMINGS: _result_value_to_data(self.timings),
            RESULT_KEY_DIAGNOSTICS: self.diagnostics.to_dict(),
            RESULT_KEY_WARNINGS: [
                issue.to_dict() for issue in self.diagnostics.warnings
            ],
            RESULT_KEY_ERRORS: [
                issue.to_dict() for issue in self.diagnostics.errors
            ],
            RESULT_KEY_STARTED_AT: self.started_at,
            RESULT_KEY_FINISHED_AT: self.finished_at,
            RESULT_KEY_DURATION_SECONDS: self.duration_seconds,
        }


# 5.10. Multipose result
# -----------------------------------------------------------------------------


@dataclass
class MultiPoseAnalysisResult:
    """Integrated result for multiple poses sharing an analysis context."""

    run_id: str = field(default_factory=lambda: _new_result_identifier("multipose"))
    request_id: Optional[str] = None
    name: str = "multipose_analysis"
    status: Union[AnalysisStatus, str] = AnalysisStatus.PENDING
    pose_results: List[PoseAnalysisResult] = field(default_factory=list)
    stage_results: MutableMapping[str, AnalysisStageResult] = field(
        default_factory=OrderedDict
    )
    ranking: List[Any] = field(default_factory=list)
    consensus: Any = None
    persistence: Any = None
    diversity: Any = None
    complementarity: Any = None
    statistics: Dict[str, Any] = field(default_factory=dict)
    files: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    provenance: Dict[str, Any] = field(default_factory=dict)
    timings: Dict[str, Any] = field(default_factory=dict)
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    result_type: str = RESULT_TYPE_MULTIPOSE

    def __post_init__(self) -> None:
        self.run_id = _normalize_result_identifier(self.run_id, fallback="multipose")
        self.request_id = (
            _normalize_result_identifier(self.request_id, fallback="request")
            if self.request_id
            else None
        )
        self.name = _normalize_result_name(self.name, fallback="multipose_analysis")
        self.status = canonicalize_analysis_status(self.status)
        self.pose_results = [
            coerce_pose_analysis_result(item)
            for item in _result_sequence(self.pose_results)
        ]
        self.stage_results = _coerce_stage_result_map(self.stage_results)
        self.ranking = _result_sequence(self.ranking)
        self.statistics = _result_mapping(self.statistics)
        self.files = _result_files(self.files)
        self.metadata = _result_mapping(self.metadata)
        self.provenance = _result_mapping(self.provenance)
        self.timings = _result_mapping(self.timings)
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_MULTIPOSE,
        )

    @property
    def pose_count(self) -> int:
        """Return the number of pose results."""

        return len(self.pose_results)

    @property
    def successful_pose_results(self) -> Tuple[PoseAnalysisResult, ...]:
        """Return pose results with accepted statuses."""

        return tuple(result for result in self.pose_results if result.succeeded)

    @property
    def failed_pose_results(self) -> Tuple[PoseAnalysisResult, ...]:
        """Return pose results with failure statuses."""

        return tuple(result for result in self.pose_results if result.failed)

    @property
    def best_pose(self) -> Optional[PoseAnalysisResult]:
        """Return the first ranked pose or the highest numeric score."""

        if not self.pose_results:
            return None
        if self.ranking:
            first = self.ranking[0]
            if isinstance(first, PoseAnalysisResult):
                return first
            identifier = None
            if isinstance(first, Mapping):
                identifier = first.get("pose_id") or first.get("id") or first.get("name")
            else:
                identifier = first
            if identifier is not None:
                for result in self.pose_results:
                    if str(identifier) in {result.pose_id, result.name}:
                        return result

        def numeric_score(result: PoseAnalysisResult) -> float:
            value = result.scoring
            if isinstance(value, Real):
                return float(value)
            for attribute in ("total_score", "normalized_score", "score"):
                candidate = getattr(value, attribute, None)
                if isinstance(candidate, Real):
                    return float(candidate)
            if isinstance(value, Mapping):
                for key in ("total_score", "normalized_score", "score"):
                    candidate = value.get(key)
                    if isinstance(candidate, Real):
                        return float(candidate)
            return float("-inf")

        return max(self.pose_results, key=numeric_score)

    def add_pose_result(self, value: Any) -> PoseAnalysisResult:
        """Append one pose result and merge its diagnostics."""

        result = coerce_pose_analysis_result(value)
        self.pose_results.append(result)
        self.diagnostics.extend(result.diagnostics)
        return result

    def add_stage_result(self, value: Any, *, stage: Optional[str] = None) -> AnalysisStageResult:
        """Add or replace one multipose-level stage result."""

        result = _coerce_stage_result(value, stage=stage)
        self.stage_results[result.stage] = result
        self.stage_results = OrderedDict(
            sorted(
                self.stage_results.items(),
                key=lambda item: stage_sort_key(item[0]),
            )
        )
        self.diagnostics.extend(result.diagnostics)
        return result

    def derive_status(self) -> AnalysisStatus:
        """Derive aggregate status from pose and global stage results."""

        pose_status = _derive_status_from_pose_results(self.pose_results)
        if not self.stage_results:
            return pose_status
        stage_status = derive_analysis_status(
            [result.status for result in self.stage_results.values()]
        )
        if (
            stage_status == AnalysisStatus.SKIPPED
            and self.successful_pose_results
        ):
            stage_status = AnalysisStatus.SUCCEEDED
        if pose_status == AnalysisStatus.SUCCEEDED and stage_status == AnalysisStatus.SUCCEEDED:
            return AnalysisStatus.SUCCEEDED
        if pose_status in ANALYSIS_SUCCESS_STATUSES or stage_status in ANALYSIS_SUCCESS_STATUSES:
            return AnalysisStatus.PARTIAL
        if pose_status == AnalysisStatus.CANCELLED or stage_status == AnalysisStatus.CANCELLED:
            return AnalysisStatus.CANCELLED
        return AnalysisStatus.FAILED

    def finalize(self, status: Optional[Any] = None) -> "MultiPoseAnalysisResult":
        """Finalize aggregate status, timing and statistics."""

        self.status = (
            canonicalize_analysis_status(status)
            if status is not None
            else self.derive_status()
        )
        _finalize_result_timing(self)
        self.statistics.setdefault("pose_count", self.pose_count)
        self.statistics.setdefault(
            "successful_pose_count",
            len(self.successful_pose_results),
        )
        self.statistics.setdefault(
            "failed_pose_count",
            len(self.failed_pose_results),
        )
        self.statistics.setdefault(
            STATISTICS_KEY_TOTAL_INTERACTIONS,
            sum(result.interaction_count for result in self.pose_results),
        )
        return self

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe multipose representation."""

        best = self.best_pose
        return {
            RESULT_KEY_SCHEMA: ANALYSIS_SCHEMA_NAME,
            RESULT_KEY_VERSION: ANALYSIS_SCHEMA_VERSION,
            RESULT_KEY_TYPE: self.result_type,
            RESULT_KEY_RUN_ID: self.run_id,
            RESULT_KEY_REQUEST_ID: self.request_id,
            "name": self.name,
            RESULT_KEY_MODE: ANALYSIS_MODE_MULTIPOSE,
            RESULT_KEY_STATUS: self.status.value,
            "pose_count": self.pose_count,
            "successful_pose_count": len(self.successful_pose_results),
            "failed_pose_count": len(self.failed_pose_results),
            "best_pose_id": best.pose_id if best else None,
            "pose_results": [
                result.to_dict(include_objects=include_objects)
                for result in self.pose_results
            ],
            RESULT_KEY_STAGES: {
                stage: result.to_dict()
                for stage, result in self.stage_results.items()
            },
            "ranking": _result_value_to_data(self.ranking),
            RESULT_KEY_CONSENSUS: _result_value_to_data(self.consensus),
            "persistence": _result_value_to_data(self.persistence),
            "diversity": _result_value_to_data(self.diversity),
            "complementarity": _result_value_to_data(self.complementarity),
            RESULT_KEY_STATISTICS: _result_value_to_data(self.statistics),
            RESULT_KEY_FILES: _result_value_to_data(self.files),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
            RESULT_KEY_PROVENANCE: _result_value_to_data(self.provenance),
            RESULT_KEY_TIMINGS: _result_value_to_data(self.timings),
            RESULT_KEY_DIAGNOSTICS: self.diagnostics.to_dict(),
            RESULT_KEY_WARNINGS: [
                issue.to_dict() for issue in self.diagnostics.warnings
            ],
            RESULT_KEY_ERRORS: [
                issue.to_dict() for issue in self.diagnostics.errors
            ],
            RESULT_KEY_STARTED_AT: self.started_at,
            RESULT_KEY_FINISHED_AT: self.finished_at,
            RESULT_KEY_DURATION_SECONDS: self.duration_seconds,
        }


# 5.11. Batch item and batch result
# -----------------------------------------------------------------------------


@dataclass
class BatchAnalysisItem:
    """One request and result pair within an independent analysis batch."""

    request: AnalysisRequest
    item_id: str = field(default_factory=lambda: _new_result_identifier("item"))
    name: str = DEFAULT_BATCH_ITEM_NAME
    status: Union[AnalysisStatus, str] = AnalysisStatus.PENDING
    result: Any = None
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    metadata: Dict[str, Any] = field(default_factory=dict)
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    result_type: str = RESULT_TYPE_BATCH_ITEM

    def __post_init__(self) -> None:
        if not isinstance(self.request, AnalysisRequest):
            self.request = coerce_analysis_request(self.request)
        self.item_id = _normalize_result_identifier(self.item_id, fallback="item")
        self.name = _normalize_result_name(
            self.name,
            fallback=self.request.name or DEFAULT_BATCH_ITEM_NAME,
        )
        self.status = canonicalize_analysis_status(self.status)
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.metadata = _result_mapping(self.metadata)
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_BATCH_ITEM,
        )

    @property
    def succeeded(self) -> bool:
        """Return whether this batch item has an accepted status."""

        return is_success_analysis_status(self.status)

    @property
    def failed(self) -> bool:
        """Return whether this batch item failed or was cancelled."""

        return is_failure_analysis_status(self.status)

    def start(self) -> "BatchAnalysisItem":
        """Mark this batch item as running."""

        if self.status == AnalysisStatus.PENDING:
            self.status = AnalysisStatus.RUNNING
        elif self.status != AnalysisStatus.RUNNING:
            raise AnalysisStateError(
                f"Cannot start batch item from {self.status.value!r}."
            )
        if self.started_at is None:
            self.started_at = _utc_timestamp()
        return self

    def finish(
        self,
        result: Any,
        *,
        status: Optional[Any] = None,
    ) -> "BatchAnalysisItem":
        """Finalize this item with an analysis result."""

        self.result = result
        inferred = status
        if inferred is None:
            inferred = getattr(result, "status", AnalysisStatus.SUCCEEDED)
        self.status = canonicalize_analysis_status(inferred)
        if hasattr(result, "diagnostics"):
            self.diagnostics.extend(result.diagnostics)
        _finalize_result_timing(self)
        return self

    def fail(self, error: Any) -> "BatchAnalysisItem":
        """Finalize this item as failed."""

        self.diagnostics.add_error(error)
        self.status = AnalysisStatus.FAILED
        _finalize_result_timing(self)
        return self

    def cancel(self, reason: Any = "Batch item was cancelled.") -> "BatchAnalysisItem":
        """Finalize this item as cancelled."""

        self.diagnostics.add_issue(
            AnalysisIssue(
                kind=IssueKind.CANCELLATION,
                severity=IssueSeverity.ERROR,
                code="batch_item_cancelled",
                message=str(reason),
                recoverable=False,
                action=RecoveryAction.ABORT_RUN,
                scope=FailureScope.BATCH_ITEM,
            )
        )
        self.status = AnalysisStatus.CANCELLED
        _finalize_result_timing(self)
        return self

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe batch-item representation."""

        if hasattr(self.result, "to_dict") and callable(self.result.to_dict):
            try:
                result_data = self.result.to_dict(include_objects=include_objects)
            except TypeError:
                result_data = self.result.to_dict()
        else:
            result_data = _result_value_to_data(
                self.result,
                include_objects=include_objects,
            )
        return {
            RESULT_KEY_TYPE: self.result_type,
            "item_id": self.item_id,
            "name": self.name,
            RESULT_KEY_STATUS: self.status.value,
            "request": self.request.to_dict(include_objects=include_objects),
            "result": result_data,
            RESULT_KEY_DIAGNOSTICS: self.diagnostics.to_dict(),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
            RESULT_KEY_STARTED_AT: self.started_at,
            RESULT_KEY_FINISHED_AT: self.finished_at,
            RESULT_KEY_DURATION_SECONDS: self.duration_seconds,
        }


@dataclass
class BatchAnalysisResult:
    """Aggregate result for independent analysis requests."""

    batch_id: str = field(default_factory=lambda: _new_result_identifier("batch"))
    name: str = "batch_analysis"
    status: Union[AnalysisStatus, str] = AnalysisStatus.PENDING
    items: List[BatchAnalysisItem] = field(default_factory=list)
    statistics: Dict[str, Any] = field(default_factory=dict)
    files: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    provenance: Dict[str, Any] = field(default_factory=dict)
    timings: Dict[str, Any] = field(default_factory=dict)
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    result_type: str = RESULT_TYPE_BATCH

    def __post_init__(self) -> None:
        self.batch_id = _normalize_result_identifier(self.batch_id, fallback="batch")
        self.name = _normalize_result_name(self.name, fallback="batch_analysis")
        self.status = canonicalize_analysis_status(self.status)
        self.items = [
            item if isinstance(item, BatchAnalysisItem) else coerce_batch_analysis_item(item)
            for item in _result_sequence(self.items)
        ]
        self.statistics = _result_mapping(self.statistics)
        self.files = _result_files(self.files)
        self.metadata = _result_mapping(self.metadata)
        self.provenance = _result_mapping(self.provenance)
        self.timings = _result_mapping(self.timings)
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_BATCH,
        )

    @property
    def item_count(self) -> int:
        """Return the number of batch items."""

        return len(self.items)

    @property
    def successful_items(self) -> Tuple[BatchAnalysisItem, ...]:
        """Return accepted batch items."""

        return tuple(item for item in self.items if item.succeeded)

    @property
    def failed_items(self) -> Tuple[BatchAnalysisItem, ...]:
        """Return failed or cancelled batch items."""

        return tuple(item for item in self.items if item.failed)

    def add_item(self, value: Any) -> BatchAnalysisItem:
        """Append one batch item."""

        item = (
            value
            if isinstance(value, BatchAnalysisItem)
            else coerce_batch_analysis_item(value)
        )
        if len(self.items) >= MAX_BATCH_ITEMS:
            raise AnalysisBatchError(
                f"Batch item limit of {MAX_BATCH_ITEMS} was exceeded."
            )
        self.items.append(item)
        self.diagnostics.extend(item.diagnostics)
        return item

    def derive_status(self) -> AnalysisStatus:
        """Derive aggregate status from batch item statuses."""

        if not self.items:
            return AnalysisStatus.SKIPPED
        statuses = [item.status for item in self.items]
        if all(status == AnalysisStatus.SUCCEEDED for status in statuses):
            return AnalysisStatus.SUCCEEDED
        if all(status == AnalysisStatus.CANCELLED for status in statuses):
            return AnalysisStatus.CANCELLED
        if all(status == AnalysisStatus.FAILED for status in statuses):
            return AnalysisStatus.FAILED
        if any(status in ANALYSIS_SUCCESS_STATUSES for status in statuses):
            return AnalysisStatus.PARTIAL
        if any(status == AnalysisStatus.CANCELLED for status in statuses):
            return AnalysisStatus.CANCELLED
        return AnalysisStatus.FAILED

    def finalize(self, status: Optional[Any] = None) -> "BatchAnalysisResult":
        """Finalize status, timing and batch statistics."""

        self.status = (
            canonicalize_analysis_status(status)
            if status is not None
            else self.derive_status()
        )
        _finalize_result_timing(self)
        self.statistics.setdefault("item_count", self.item_count)
        self.statistics.setdefault("successful_item_count", len(self.successful_items))
        self.statistics.setdefault("failed_item_count", len(self.failed_items))
        return self

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe batch representation."""

        return {
            RESULT_KEY_SCHEMA: ANALYSIS_SCHEMA_NAME,
            RESULT_KEY_VERSION: ANALYSIS_SCHEMA_VERSION,
            RESULT_KEY_TYPE: self.result_type,
            "batch_id": self.batch_id,
            "name": self.name,
            RESULT_KEY_MODE: ANALYSIS_MODE_BATCH,
            RESULT_KEY_STATUS: self.status.value,
            "item_count": self.item_count,
            "successful_item_count": len(self.successful_items),
            "failed_item_count": len(self.failed_items),
            "items": [
                item.to_dict(include_objects=include_objects)
                for item in self.items
            ],
            RESULT_KEY_STATISTICS: _result_value_to_data(self.statistics),
            RESULT_KEY_FILES: _result_value_to_data(self.files),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
            RESULT_KEY_PROVENANCE: _result_value_to_data(self.provenance),
            RESULT_KEY_TIMINGS: _result_value_to_data(self.timings),
            RESULT_KEY_DIAGNOSTICS: self.diagnostics.to_dict(),
            RESULT_KEY_WARNINGS: [
                issue.to_dict() for issue in self.diagnostics.warnings
            ],
            RESULT_KEY_ERRORS: [
                issue.to_dict() for issue in self.diagnostics.errors
            ],
            RESULT_KEY_STARTED_AT: self.started_at,
            RESULT_KEY_FINISHED_AT: self.finished_at,
            RESULT_KEY_DURATION_SECONDS: self.duration_seconds,
        }


# 5.12. Top-level run result
# -----------------------------------------------------------------------------


@dataclass
class AnalysisRunResult:
    """Top-level result returned by the public orchestration interface."""

    run_id: str = field(default_factory=lambda: _new_result_identifier("run"))
    request_id: Optional[str] = None
    name: str = DEFAULT_RESULT_NAME
    mode: Union[AnalysisModeName, str] = ANALYSIS_MODE_AUTO
    status: Union[AnalysisStatus, str] = AnalysisStatus.PENDING
    request: Optional[AnalysisRequest] = None
    context: Optional[AnalysisContext] = None
    result: Any = None
    pose_result: Optional[PoseAnalysisResult] = None
    multipose_result: Optional[MultiPoseAnalysisResult] = None
    batch_result: Optional[BatchAnalysisResult] = None
    stage_results: MutableMapping[str, AnalysisStageResult] = field(
        default_factory=OrderedDict
    )
    statistics: Dict[str, Any] = field(default_factory=dict)
    files: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    provenance: Dict[str, Any] = field(default_factory=dict)
    timings: Dict[str, Any] = field(default_factory=dict)
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    result_type: str = RESULT_TYPE_RUN

    def __post_init__(self) -> None:
        self.run_id = _normalize_result_identifier(self.run_id, fallback="run")
        if self.request is not None and not isinstance(self.request, AnalysisRequest):
            self.request = coerce_analysis_request(self.request)
        if self.context is not None and not isinstance(self.context, AnalysisContext):
            raise TypeError("Run context must be an AnalysisContext instance.")
        inferred_request_id = self.request.request_id if self.request else None
        self.request_id = (
            _normalize_result_identifier(
                self.request_id or inferred_request_id,
                fallback="request",
            )
            if self.request_id or inferred_request_id
            else None
        )
        self.name = _normalize_result_name(self.name, fallback=DEFAULT_RESULT_NAME)
        self.mode = canonicalize_analysis_mode(self.mode)
        self.status = canonicalize_analysis_status(self.status)
        if self.pose_result is not None and not isinstance(
            self.pose_result,
            PoseAnalysisResult,
        ):
            self.pose_result = coerce_pose_analysis_result(self.pose_result)
        if self.multipose_result is not None and not isinstance(
            self.multipose_result,
            MultiPoseAnalysisResult,
        ):
            self.multipose_result = coerce_multipose_analysis_result(
                self.multipose_result
            )
        if self.batch_result is not None and not isinstance(
            self.batch_result,
            BatchAnalysisResult,
        ):
            self.batch_result = coerce_batch_analysis_result(self.batch_result)
        self.stage_results = _coerce_stage_result_map(self.stage_results)
        self.statistics = _result_mapping(self.statistics)
        self.files = _result_files(self.files)
        self.metadata = _result_mapping(self.metadata)
        self.provenance = _result_mapping(self.provenance)
        self.timings = _result_mapping(self.timings)
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.result_type = _normalize_result_name(
            self.result_type,
            fallback=RESULT_TYPE_RUN,
        )
        self._synchronize_payload()

    @property
    def payload(self) -> Any:
        """Return the mode-specific primary result."""

        if self.pose_result is not None:
            return self.pose_result
        if self.multipose_result is not None:
            return self.multipose_result
        if self.batch_result is not None:
            return self.batch_result
        return self.result

    @property
    def succeeded(self) -> bool:
        """Return whether the run has an accepted terminal status."""

        return is_success_analysis_status(self.status)

    @property
    def failed(self) -> bool:
        """Return whether the run failed or was cancelled."""

        return is_failure_analysis_status(self.status)

    def _synchronize_payload(self) -> None:
        """Infer mode-specific fields from the generic result payload."""

        if isinstance(self.result, PoseAnalysisResult) and self.pose_result is None:
            self.pose_result = self.result
        elif (
            isinstance(self.result, MultiPoseAnalysisResult)
            and self.multipose_result is None
        ):
            self.multipose_result = self.result
        elif isinstance(self.result, BatchAnalysisResult) and self.batch_result is None:
            self.batch_result = self.result

        selected = [
            item
            for item in (
                self.pose_result,
                self.multipose_result,
                self.batch_result,
            )
            if item is not None
        ]
        if len(selected) > 1:
            raise AnalysisValidationError(
                "A run result cannot contain multiple primary result types."
            )
        if selected:
            self.result = selected[0]
            if isinstance(self.result, PoseAnalysisResult):
                self.mode = ANALYSIS_MODE_SINGLE_POSE
            elif isinstance(self.result, MultiPoseAnalysisResult):
                self.mode = ANALYSIS_MODE_MULTIPOSE
            elif isinstance(self.result, BatchAnalysisResult):
                self.mode = ANALYSIS_MODE_BATCH

    def add_stage_result(self, value: Any, *, stage: Optional[str] = None) -> AnalysisStageResult:
        """Add or replace one run-level stage result."""

        stage_result = _coerce_stage_result(value, stage=stage)
        self.stage_results[stage_result.stage] = stage_result
        self.stage_results = OrderedDict(
            sorted(
                self.stage_results.items(),
                key=lambda item: stage_sort_key(item[0]),
            )
        )
        self.diagnostics.extend(stage_result.diagnostics)
        self.files.update(stage_result.files)
        if stage_result.duration_seconds is not None:
            self.timings[stage_result.stage] = stage_result.duration_seconds
        return stage_result

    def set_payload(self, value: Any) -> Any:
        """Set and classify the mode-specific result payload."""

        self.result = value
        self.pose_result = value if isinstance(value, PoseAnalysisResult) else None
        self.multipose_result = (
            value if isinstance(value, MultiPoseAnalysisResult) else None
        )
        self.batch_result = value if isinstance(value, BatchAnalysisResult) else None
        self._synchronize_payload()
        return value

    def derive_status(self) -> AnalysisStatus:
        """Derive run status from its payload and stage results."""

        payload = self.payload
        payload_status = getattr(payload, "status", None)
        if payload_status is not None:
            payload_status = canonicalize_analysis_status(payload_status)
        if self.stage_results:
            stage_status = derive_analysis_status(
                [result.status for result in self.stage_results.values()]
            )
            if stage_status == AnalysisStatus.SKIPPED and payload is not None:
                stage_status = AnalysisStatus.SUCCEEDED
            if payload_status is None:
                return stage_status
            if (
                payload_status == AnalysisStatus.SUCCEEDED
                and stage_status == AnalysisStatus.SUCCEEDED
            ):
                return AnalysisStatus.SUCCEEDED
            if (
                payload_status in ANALYSIS_SUCCESS_STATUSES
                or stage_status in ANALYSIS_SUCCESS_STATUSES
            ):
                return AnalysisStatus.PARTIAL
            if (
                payload_status == AnalysisStatus.CANCELLED
                or stage_status == AnalysisStatus.CANCELLED
            ):
                return AnalysisStatus.CANCELLED
            return AnalysisStatus.FAILED
        if payload_status is not None:
            return payload_status
        if self.diagnostics.has_errors:
            return AnalysisStatus.FAILED
        return self.status

    def finalize(self, status: Optional[Any] = None) -> "AnalysisRunResult":
        """Finalize the run and synchronize aggregate metadata."""

        payload = self.payload
        if payload is not None and hasattr(payload, "finalize"):
            payload.finalize()
            self.diagnostics.extend(getattr(payload, "diagnostics", None))
            self.files.update(getattr(payload, "files", {}) or {})
        self.status = (
            canonicalize_analysis_status(status)
            if status is not None
            else self.derive_status()
        )
        _finalize_result_timing(self)
        self.statistics.setdefault("stage_count", len(self.stage_results))
        self.statistics.setdefault(
            STATISTICS_KEY_COMPLETED_STAGES,
            [
                stage
                for stage, result in self.stage_results.items()
                if result.succeeded
            ],
        )
        self.statistics.setdefault(
            STATISTICS_KEY_FAILED_STAGES,
            [
                stage
                for stage, result in self.stage_results.items()
                if result.failed
            ],
        )
        return self

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe top-level result representation."""

        payload = self.payload
        if hasattr(payload, "to_dict") and callable(payload.to_dict):
            try:
                payload_data = payload.to_dict(include_objects=include_objects)
            except TypeError:
                payload_data = payload.to_dict()
        else:
            payload_data = _result_value_to_data(
                payload,
                include_objects=include_objects,
            )
        return {
            RESULT_KEY_SCHEMA: ANALYSIS_SCHEMA_NAME,
            RESULT_KEY_VERSION: ANALYSIS_SCHEMA_VERSION,
            RESULT_KEY_TYPE: self.result_type,
            RESULT_KEY_RUN_ID: self.run_id,
            RESULT_KEY_REQUEST_ID: self.request_id,
            "name": self.name,
            RESULT_KEY_MODE: self.mode,
            RESULT_KEY_STATUS: self.status.value,
            "request": (
                self.request.to_dict(include_objects=include_objects)
                if self.request
                else None
            ),
            RESULT_KEY_CONTEXT: (
                self.context.to_dict(include_objects=include_objects)
                if self.context
                else None
            ),
            "result": payload_data,
            RESULT_KEY_STAGES: {
                stage: result.to_dict()
                for stage, result in self.stage_results.items()
            },
            RESULT_KEY_STATISTICS: _result_value_to_data(self.statistics),
            RESULT_KEY_FILES: _result_value_to_data(self.files),
            RESULT_KEY_METADATA: _result_value_to_data(self.metadata),
            RESULT_KEY_PROVENANCE: _result_value_to_data(self.provenance),
            RESULT_KEY_TIMINGS: _result_value_to_data(self.timings),
            RESULT_KEY_DIAGNOSTICS: self.diagnostics.to_dict(),
            RESULT_KEY_WARNINGS: [
                issue.to_dict() for issue in self.diagnostics.warnings
            ],
            RESULT_KEY_ERRORS: [
                issue.to_dict() for issue in self.diagnostics.errors
            ],
            RESULT_KEY_STARTED_AT: self.started_at,
            RESULT_KEY_FINISHED_AT: self.finished_at,
            RESULT_KEY_DURATION_SECONDS: self.duration_seconds,
        }


# 5.13. Coercion and construction helpers
# -----------------------------------------------------------------------------


def coerce_analysis_request(value: Any, **overrides: Any) -> AnalysisRequest:
    """Coerce a request-like object into :class:`AnalysisRequest`."""

    if isinstance(value, AnalysisRequest):
        if not overrides:
            return value
        return replace(value, **overrides)
    if isinstance(value, Mapping):
        data = dict(value)
        data.update(overrides)
        known_fields = {item.name for item in fields(AnalysisRequest)}
        request_data = {
            key: item
            for key, item in data.items()
            if key in known_fields
        }
        extra = {
            key: item
            for key, item in data.items()
            if key not in known_fields
        }
        metadata = dict(request_data.get("metadata") or {})
        metadata.update(extra)
        request_data["metadata"] = metadata
        return AnalysisRequest(**request_data)
    return AnalysisRequest(input_data=value, **overrides)


def create_analysis_request(
    input_data: Any = None,
    *,
    config: AnalysisConfigLike = None,
    **kwargs: Any,
) -> AnalysisRequest:
    """Create a normalized analysis request."""

    return AnalysisRequest(
        input_data=input_data,
        config=coerce_analysis_config(config),
        **kwargs,
    )


def create_analysis_context(
    request: AnalysisRequestLike,
    **kwargs: Any,
) -> AnalysisContext:
    """Create a runtime context from a request-like value."""

    return AnalysisContext(request=coerce_analysis_request(request), **kwargs)


def coerce_interaction_bundle(value: Any) -> InteractionAnalysisBundle:
    """Coerce an interaction-bundle-like value."""

    if isinstance(value, InteractionAnalysisBundle):
        return value
    if value is None:
        return InteractionAnalysisBundle()
    if isinstance(value, Mapping):
        data = dict(value)
        known = {item.name for item in fields(InteractionAnalysisBundle)}
        bundle_data = {key: item for key, item in data.items() if key in known}
        extra = {key: item for key, item in data.items() if key not in known}
        metadata = dict(bundle_data.get("metadata") or {})
        metadata.update(extra)
        bundle_data["metadata"] = metadata
        return InteractionAnalysisBundle(**bundle_data)

    extracted: Dict[str, Any] = {}
    for family in INTERACTION_FAMILY_ORDER:
        attribute = interaction_family_to_dock_model_field(family)
        if hasattr(value, attribute):
            extracted[family] = getattr(value, attribute)
    if hasattr(value, "metadata"):
        extracted["metadata"] = getattr(value, "metadata")
    if hasattr(value, "statistics"):
        extracted["statistics"] = getattr(value, "statistics")
    if extracted:
        return InteractionAnalysisBundle(**extracted)
    raise TypeError("Cannot coerce value into InteractionAnalysisBundle.")


def coerce_pose_analysis_result(value: Any) -> PoseAnalysisResult:
    """Coerce a pose-result-like value."""

    if isinstance(value, PoseAnalysisResult):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        known = {item.name for item in fields(PoseAnalysisResult)}
        pose_data = {key: item for key, item in data.items() if key in known}
        if "result_type" not in pose_data and "type" in data:
            pose_data["result_type"] = data["type"]
        extra = {key: item for key, item in data.items() if key not in known}
        metadata = dict(pose_data.get("metadata") or {})
        metadata.update(extra)
        pose_data["metadata"] = metadata
        return PoseAnalysisResult(**pose_data)
    if isinstance(value, DockModel):
        return PoseAnalysisResult(
            name=value.name,
            dock_model=value,
            receptor=value.receptor,
            ligand=value.ligand,
            pose=value.pose,
            interactions=coerce_interaction_bundle(value),
            scoring=value.score,
            statistics=value.statistics,
            files=value.files,
            metadata=value.metadata,
        )
    raise TypeError("Cannot coerce value into PoseAnalysisResult.")


def coerce_multipose_analysis_result(value: Any) -> MultiPoseAnalysisResult:
    """Coerce a multipose-result-like value."""

    if isinstance(value, MultiPoseAnalysisResult):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        known = {item.name for item in fields(MultiPoseAnalysisResult)}
        result_data = {key: item for key, item in data.items() if key in known}
        if "pose_results" not in result_data:
            result_data["pose_results"] = data.get("poses", [])
        if "result_type" not in result_data and "type" in data:
            result_data["result_type"] = data["type"]
        extra = {key: item for key, item in data.items() if key not in known}
        metadata = dict(result_data.get("metadata") or {})
        metadata.update(extra)
        result_data["metadata"] = metadata
        return MultiPoseAnalysisResult(**result_data)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return MultiPoseAnalysisResult(pose_results=list(value))
    raise TypeError("Cannot coerce value into MultiPoseAnalysisResult.")


def coerce_batch_analysis_item(value: Any) -> BatchAnalysisItem:
    """Coerce a batch-item-like value."""

    if isinstance(value, BatchAnalysisItem):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        if "request" not in data:
            data = {"request": data}
        known = {item.name for item in fields(BatchAnalysisItem)}
        item_data = {key: item for key, item in data.items() if key in known}
        extra = {key: item for key, item in data.items() if key not in known}
        metadata = dict(item_data.get("metadata") or {})
        metadata.update(extra)
        item_data["metadata"] = metadata
        return BatchAnalysisItem(**item_data)
    return BatchAnalysisItem(request=coerce_analysis_request(value))


def coerce_batch_analysis_result(value: Any) -> BatchAnalysisResult:
    """Coerce a batch-result-like value."""

    if isinstance(value, BatchAnalysisResult):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        known = {item.name for item in fields(BatchAnalysisResult)}
        result_data = {key: item for key, item in data.items() if key in known}
        if "result_type" not in result_data and "type" in data:
            result_data["result_type"] = data["type"]
        extra = {key: item for key, item in data.items() if key not in known}
        metadata = dict(result_data.get("metadata") or {})
        metadata.update(extra)
        result_data["metadata"] = metadata
        return BatchAnalysisResult(**result_data)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return BatchAnalysisResult(items=list(value))
    raise TypeError("Cannot coerce value into BatchAnalysisResult.")


def create_analysis_run_result(
    request: Optional[AnalysisRequestLike] = None,
    *,
    context: Optional[AnalysisContext] = None,
    result: Any = None,
    **kwargs: Any,
) -> AnalysisRunResult:
    """Create a top-level run result."""

    normalized_request = (
        coerce_analysis_request(request)
        if request is not None
        else None
    )
    if context is None and normalized_request is not None:
        context = create_analysis_context(normalized_request)
    return AnalysisRunResult(
        request=normalized_request,
        context=context,
        result=result,
        request_id=(normalized_request.request_id if normalized_request else None),
        mode=(normalized_request.mode if normalized_request else ANALYSIS_MODE_AUTO),
        **kwargs,
    )


def result_to_dict(
    value: Any,
    *,
    include_objects: bool = False,
) -> Dict[str, Any]:
    """Return a mapping for any core result object."""

    if hasattr(value, "to_dict") and callable(value.to_dict):
        try:
            data = value.to_dict(include_objects=include_objects)
        except TypeError:
            data = value.to_dict()
        if isinstance(data, Mapping):
            return dict(data)
    converted = _result_value_to_data(value, include_objects=include_objects)
    if isinstance(converted, Mapping):
        return dict(converted)
    return {"value": converted}


def result_to_json(
    value: Any,
    *,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
    sort_keys: bool = True,
) -> str:
    """Return a JSON representation of a core result object."""

    try:
        return json.dumps(
            result_to_dict(value),
            indent=indent,
            sort_keys=sort_keys,
            ensure_ascii=False,
        )
    except (TypeError, ValueError) as exc:
        raise AnalysisSerializationError(
            "Core result could not be encoded as JSON.",
            cause=exc,
        ) from exc


def summarize_core_result(value: Any) -> Dict[str, Any]:
    """Return a compact summary for a core request or result object."""

    if isinstance(value, AnalysisRequest):
        return {
            "type": "analysis_request",
            "request_id": value.request_id,
            "name": value.name,
            "mode": value.mode,
            "pose_count": value.pose_count,
            "model_count": value.model_count,
            "stage_count": len(value.requested_stages),
        }
    if isinstance(value, AnalysisStageResult):
        return {
            "type": value.result_type,
            "stage": value.stage,
            "status": value.status.value,
            "duration_seconds": value.duration_seconds,
            "issue_count": len(value.issues),
        }
    if isinstance(value, InteractionAnalysisBundle):
        return {
            "type": value.result_type,
            "families": list(value.families),
            "counts": value.counts(),
        }
    if isinstance(value, PoseAnalysisResult):
        return {
            "type": value.result_type,
            "pose_id": value.pose_id,
            "name": value.name,
            "status": value.status.value,
            "interaction_count": value.interaction_count,
            "stage_count": len(value.stage_results),
        }
    if isinstance(value, MultiPoseAnalysisResult):
        return {
            "type": value.result_type,
            "run_id": value.run_id,
            "status": value.status.value,
            "pose_count": value.pose_count,
            "successful_pose_count": len(value.successful_pose_results),
        }
    if isinstance(value, BatchAnalysisItem):
        return {
            "type": value.result_type,
            "item_id": value.item_id,
            "status": value.status.value,
            "request_id": value.request.request_id,
        }
    if isinstance(value, BatchAnalysisResult):
        return {
            "type": value.result_type,
            "batch_id": value.batch_id,
            "status": value.status.value,
            "item_count": value.item_count,
            "successful_item_count": len(value.successful_items),
        }
    if isinstance(value, AnalysisRunResult):
        return {
            "type": value.result_type,
            "run_id": value.run_id,
            "request_id": value.request_id,
            "mode": value.mode,
            "status": value.status.value,
            "stage_count": len(value.stage_results),
            "payload_type": (
                type(value.payload).__name__ if value.payload is not None else None
            ),
        }
    if isinstance(value, AnalysisDiagnostics):
        return {
            "type": "analysis_diagnostics",
            **value.counts(),
            "highest_severity": value.highest_severity.name.lower(),
        }
    return {"type": type(value).__name__}


# 5.14. Core result validation
# -----------------------------------------------------------------------------


def validate_core_result(
    value: Any,
    *,
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate one core request, context or result object."""

    issues: List[str] = []

    if isinstance(value, AnalysisRequest):
        if not value.request_id:
            issues.append("AnalysisRequest has an empty request identifier.")
        issues.extend(validate_analysis_config(value.config, raise_on_error=False))
        unknown = set(value.requested_stages).difference(KNOWN_PIPELINE_STAGES)
        if unknown:
            issues.append(f"AnalysisRequest contains unknown stages: {sorted(unknown)!r}.")

    elif isinstance(value, AnalysisContext):
        if value.config is None:
            issues.append("AnalysisContext has no configuration.")
        if value.current_pose_index is not None and value.current_pose_index < 0:
            issues.append("AnalysisContext has a negative pose index.")
        if value.pose_count and value.current_pose_index is not None:
            if value.current_pose_index >= value.pose_count:
                issues.append("AnalysisContext pose index exceeds resolved items.")

    elif isinstance(value, AnalysisStageResult):
        if not value.stage:
            issues.append("AnalysisStageResult has no stage name.")
        if value.is_terminal and value.finished_at is None:
            issues.append("Terminal AnalysisStageResult has no finish time.")
        if value.status == StageStatus.SUCCEEDED and value.errors:
            issues.append("Successful AnalysisStageResult contains error issues.")

    elif isinstance(value, InteractionAnalysisBundle):
        counts = value.counts()
        if counts["total"] < 0:
            issues.append("InteractionAnalysisBundle has a negative count.")
        if set(counts).difference(set(INTERACTION_FAMILY_ORDER) | {"total"}):
            issues.append("InteractionAnalysisBundle contains invalid count keys.")

    elif isinstance(value, PoseAnalysisResult):
        if not value.pose_id:
            issues.append("PoseAnalysisResult has no pose identifier.")
        for result in value.stage_results.values():
            issues.extend(validate_core_result(result, raise_on_error=False))
        if value.status == AnalysisStatus.SUCCEEDED and value.diagnostics.has_errors:
            issues.append("Successful PoseAnalysisResult contains error issues.")

    elif isinstance(value, MultiPoseAnalysisResult):
        identifiers = [result.pose_id for result in value.pose_results]
        if len(identifiers) != len(set(identifiers)):
            issues.append("MultiPoseAnalysisResult has duplicate pose identifiers.")
        for result in value.pose_results:
            issues.extend(validate_core_result(result, raise_on_error=False))

    elif isinstance(value, BatchAnalysisItem):
        issues.extend(validate_core_result(value.request, raise_on_error=False))
        if value.status == AnalysisStatus.SUCCEEDED and value.result is None:
            issues.append("Successful BatchAnalysisItem has no result.")

    elif isinstance(value, BatchAnalysisResult):
        identifiers = [item.item_id for item in value.items]
        if len(identifiers) != len(set(identifiers)):
            issues.append("BatchAnalysisResult has duplicate item identifiers.")
        for item in value.items:
            issues.extend(validate_core_result(item, raise_on_error=False))

    elif isinstance(value, AnalysisRunResult):
        primary_count = sum(
            item is not None
            for item in (
                value.pose_result,
                value.multipose_result,
                value.batch_result,
            )
        )
        if primary_count > 1:
            issues.append("AnalysisRunResult contains multiple primary payloads.")
        if value.request and value.request_id != value.request.request_id:
            issues.append("AnalysisRunResult request identifiers are inconsistent.")
        if value.status == AnalysisStatus.SUCCEEDED and value.diagnostics.has_errors:
            issues.append("Successful AnalysisRunResult contains error issues.")

    elif isinstance(value, AnalysisDiagnostics):
        if len(value.issues) > MAX_DIAGNOSTIC_MESSAGES:
            issues.append("AnalysisDiagnostics exceeds the issue limit.")
        if len(value.messages) > MAX_DIAGNOSTIC_MESSAGES:
            issues.append("AnalysisDiagnostics exceeds the message limit.")

    else:
        issues.append(f"Unsupported core result type: {type(value).__name__}.")

    result = tuple(issues)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Invalid core analysis result: " + " ".join(result),
            details={"issues": list(result)},
        )
    return result


def validate_core_result_conventions(
    *,
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate Section 5 dataclasses and helper conventions."""

    issues: List[str] = []

    if len(CORE_RESULT_TYPES) != len(set(CORE_RESULT_TYPES)):
        issues.append("CORE_RESULT_TYPES contains duplicate values.")
    if RESULT_TYPE_RUN != ANALYSIS_RESULT_TYPE:
        issues.append("Run result type differs from ANALYSIS_RESULT_TYPE.")

    try:
        request = create_analysis_request(
            {"probe": True},
            config={"mode": "single_pose", "interactions": {"contacts": True}},
            name="probe",
        )
        context = create_analysis_context(request)
        context.start()
        context.set_current_stage(STAGE_CONTACTS)
        context.set_stage_data(STAGE_CONTACTS, {"ready": True})
        if context.get_stage_data(STAGE_CONTACTS) != {"ready": True}:
            issues.append("AnalysisContext stage-data round trip failed.")

        stage = AnalysisStageResult(stage=STAGE_CONTACTS)
        stage.start().succeed([{"distance": 3.5}])
        validate_core_result(stage)

        bundle = InteractionAnalysisBundle(
            contacts=[object()],
            pi={"stacking": [object()], "cation_pi": [object()]},
        )
        if bundle.total_count != 3:
            issues.append("InteractionAnalysisBundle counting failed.")
        if bundle.pi_counts().get(PI_SUBTYPE_STACKING) != 1:
            issues.append("Pi subtype canonicalization failed.")

        pose = PoseAnalysisResult(
            name="pose_1",
            interactions=bundle,
            stage_results={STAGE_CONTACTS: stage},
            scoring=1.0,
            started_at=_utc_timestamp(),
        ).finalize()
        if pose.status != AnalysisStatus.SUCCEEDED:
            issues.append("PoseAnalysisResult status derivation failed.")
        validate_core_result(pose)

        multipose = MultiPoseAnalysisResult(
            pose_results=[pose],
            started_at=_utc_timestamp(),
        ).finalize()
        if multipose.status != AnalysisStatus.SUCCEEDED:
            issues.append("MultiPoseAnalysisResult status derivation failed.")

        batch_item = BatchAnalysisItem(request=request).start().finish(pose)
        batch = BatchAnalysisResult(
            items=[batch_item],
            started_at=_utc_timestamp(),
        ).finalize()
        if batch.status != AnalysisStatus.SUCCEEDED:
            issues.append("BatchAnalysisResult status derivation failed.")

        run = create_analysis_run_result(
            request,
            result=pose,
            started_at=_utc_timestamp(),
        )
        run.add_stage_result(stage)
        run.finalize()
        if run.mode != ANALYSIS_MODE_SINGLE_POSE:
            issues.append("AnalysisRunResult payload classification failed.")
        if run.status != AnalysisStatus.SUCCEEDED:
            issues.append("AnalysisRunResult status derivation failed.")

        encoded = result_to_json(run)
        decoded = json.loads(encoded)
        if decoded.get(RESULT_KEY_RUN_ID) != run.run_id:
            issues.append("Core result JSON conversion failed.")

        for candidate in (
            request,
            context,
            stage,
            bundle,
            pose,
            multipose,
            batch_item,
            batch,
            run,
            run.diagnostics,
        ):
            validate_core_result(candidate)
            summary = summarize_core_result(candidate)
            if not summary.get("type"):
                issues.append(
                    f"Core result summary failed for {type(candidate).__name__}."
                )
    except Exception as exc:
        issues.append(f"Core result convention probe failed: {exc}")

    result = tuple(issues)
    if result and raise_on_error:
        raise RuntimeError(
            "Invalid core result conventions: " + " ".join(result)
        )
    return result


