# 6.1. Capability states and categories
# -----------------------------------------------------------------------------


class CapabilityState(str, Enum):
    """Availability state reported for a module, dependency or feature."""

    UNKNOWN = "unknown"
    AVAILABLE = "available"
    DEGRADED = "degraded"
    UNAVAILABLE = "unavailable"
    DISABLED = "disabled"


class CapabilityKind(str, Enum):
    """Canonical kind of a discovered capability."""

    MODULE = "module"
    DEPENDENCY = "dependency"
    FEATURE = "feature"
    RUNTIME = "runtime"
    STAGE = "stage"


CAPABILITY_AVAILABLE_STATES: Final[FrozenSet[CapabilityState]] = frozenset(
    {CapabilityState.AVAILABLE, CapabilityState.DEGRADED}
)

CAPABILITY_UNAVAILABLE_STATES: Final[FrozenSet[CapabilityState]] = frozenset(
    {CapabilityState.UNAVAILABLE, CapabilityState.DISABLED}
)


# 6.2. Module and dependency conventions
# -----------------------------------------------------------------------------

