# 6.3. Normalization helpers
# -----------------------------------------------------------------------------


def _normalize_capability_token(value: Any) -> str:
    """Return a stable lowercase capability token."""

    text = str(value).strip().lower()
    text = re.sub(r"[^a-z0-9]+", "_", text).strip("_")
    if not text:
        raise AnalysisConfigurationError("A capability name cannot be empty.")
    return text


def _normalize_symbol_names(values: Iterable[Any]) -> Tuple[str, ...]:
    """Return unique non-empty Python symbol names in declaration order."""

    result: List[str] = []
    seen: Set[str] = set()
    for value in values:
        name = str(value).strip()
        if not name or name in seen:
            continue
        if not name.isidentifier():
            raise AnalysisConfigurationError(
                f"Invalid Python symbol name: {name!r}."
            )
        result.append(name)
        seen.add(name)
    return tuple(result)


def canonicalize_analysis_module_name(value: Any) -> str:
    """Return the canonical name of a DockAnalyzer module."""

    token = _normalize_capability_token(value)
    canonical = MODULE_ALIASES.get(token, token)
    if canonical not in KNOWN_ANALYSIS_MODULES:
        raise AnalysisConfigurationError(
            f"Unknown DockAnalyzer module: {value!r}."
        )
    return canonical


def canonicalize_dependency_name(value: Any) -> str:
    """Return the canonical name of an external dependency."""

    raw = str(value).strip()
    token = raw if raw == "PIL" else _normalize_capability_token(raw)
    canonical = DEPENDENCY_ALIASES.get(token, token)
    if canonical == "pil":
        canonical = "PIL"
    if canonical not in KNOWN_RUNTIME_DEPENDENCIES:
        raise AnalysisConfigurationError(
            f"Unknown runtime dependency: {value!r}."
        )
    return canonical


def canonicalize_feature_name(value: Any) -> str:
    """Return the canonical name of a registered high-level feature."""

    token = _normalize_capability_token(value)
    aliases = {
        "contacts": "contact_analysis",
        "contact": "contact_analysis",
        "hbonds": "hydrogen_bond_analysis",
        "hbond": "hydrogen_bond_analysis",
        "hydrophobic": "hydrophobic_analysis",
        "pi": "pi_analysis",
        "saltbridge": "salt_bridge_analysis",
        "salt_bridges": "salt_bridge_analysis",
        "report": "reporting",
        "reports": "reporting",
        "visualization": "visualization_planning",
        "visualisation": "visualization_planning",
        "chimerax": "chimerax_execution",
        "excel": "excel_export",
        "images": "image_output",
    }
    canonical = aliases.get(token, token)
    if canonical not in FEATURE_REQUIREMENTS:
        raise AnalysisConfigurationError(
            f"Unknown analysis feature: {value!r}."
        )
    return canonical


def canonicalize_capability_state(value: Any) -> CapabilityState:
    """Return a capability state from an enum or common alias."""

    if isinstance(value, CapabilityState):
        return value
    token = _normalize_capability_token(value)
    aliases = {
        "ok": CapabilityState.AVAILABLE,
        "present": CapabilityState.AVAILABLE,
        "installed": CapabilityState.AVAILABLE,
        "partial": CapabilityState.DEGRADED,
        "limited": CapabilityState.DEGRADED,
        "missing": CapabilityState.UNAVAILABLE,
        "absent": CapabilityState.UNAVAILABLE,
        "off": CapabilityState.DISABLED,
    }
    if token in aliases:
        return aliases[token]
    try:
        return CapabilityState(token)
    except ValueError as exc:
        raise AnalysisConfigurationError(
            f"Unknown capability state: {value!r}."
        ) from exc


# 6.4. Requirement dataclasses
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ModuleRequirement:
    """Expected interface and role of one DockAnalyzer module."""

    name: str
    role: str
    stages: Tuple[str, ...] = ()
    required_symbols: Tuple[str, ...] = ()
    optional_symbols: Tuple[str, ...] = ()
    globally_required: bool = False
    description: str = ""

    def __post_init__(self) -> None:
        canonical_name = canonicalize_analysis_module_name(self.name)
        object.__setattr__(self, "name", canonical_name)
        object.__setattr__(self, "role", _normalize_capability_token(self.role))
        object.__setattr__(
            self,
            "stages",
            tuple(canonicalize_stage_name(stage) for stage in self.stages),
        )
        object.__setattr__(
            self,
            "required_symbols",
            _normalize_symbol_names(self.required_symbols),
        )
        object.__setattr__(
            self,
            "optional_symbols",
            _normalize_symbol_names(self.optional_symbols),
        )
        object.__setattr__(self, "description", str(self.description).strip())

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready requirement representation."""

        return {
            "name": self.name,
            "role": self.role,
            "stages": list(self.stages),
            "required_symbols": list(self.required_symbols),
            "optional_symbols": list(self.optional_symbols),
            "globally_required": self.globally_required,
            "description": self.description,
        }


@dataclass(frozen=True)
class DependencyRequirement:
    """Import and distribution requirements for one external dependency."""

    name: str
    import_name: str
    distribution_name: Optional[str] = None
    required: bool = False
    purpose: str = ""

    def __post_init__(self) -> None:
        canonical_name = canonicalize_dependency_name(self.name)
        import_name = str(self.import_name).strip()
        if not import_name:
            raise AnalysisConfigurationError(
                "A dependency import name cannot be empty."
            )
        distribution_name = (
            None
            if self.distribution_name is None
            else str(self.distribution_name).strip() or None
        )
        object.__setattr__(self, "name", canonical_name)
        object.__setattr__(self, "import_name", import_name)
        object.__setattr__(self, "distribution_name", distribution_name)
        object.__setattr__(self, "purpose", str(self.purpose).strip())

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready requirement representation."""

        return {
            "name": self.name,
            "import_name": self.import_name,
            "distribution_name": self.distribution_name,
            "required": self.required,
            "purpose": self.purpose,
        }


@dataclass(frozen=True)
class FeatureRequirement:
    """Modules and dependencies needed to expose one high-level feature."""

    name: str
    modules: Tuple[str, ...] = ()
    dependencies: Tuple[str, ...] = ()
    any_dependencies: Tuple[str, ...] = ()
    stages: Tuple[str, ...] = ()
    description: str = ""

    def __post_init__(self) -> None:
        object.__setattr__(self, "name", _normalize_capability_token(self.name))
        object.__setattr__(
            self,
            "modules",
            tuple(canonicalize_analysis_module_name(item) for item in self.modules),
        )
        object.__setattr__(
            self,
            "dependencies",
            tuple(canonicalize_dependency_name(item) for item in self.dependencies),
        )
        object.__setattr__(
            self,
            "any_dependencies",
            tuple(
                canonicalize_dependency_name(item)
                for item in self.any_dependencies
            ),
        )
        object.__setattr__(
            self,
            "stages",
            tuple(canonicalize_stage_name(stage) for stage in self.stages),
        )
        object.__setattr__(self, "description", str(self.description).strip())

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready requirement representation."""

        return {
            "name": self.name,
            "modules": list(self.modules),
            "dependencies": list(self.dependencies),
            "any_dependencies": list(self.any_dependencies),
            "stages": list(self.stages),
            "description": self.description,
        }


