# 6.6. Capability result dataclasses
# -----------------------------------------------------------------------------


@dataclass
class DependencyCapability:
    """Observed availability of one external dependency."""

    name: str
    import_name: str
    state: CapabilityState = CapabilityState.UNKNOWN
    required: bool = False
    loaded: bool = False
    version: Optional[str] = None
    path: Optional[str] = None
    reason: Optional[str] = None
    error_type: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def available(self) -> bool:
        """Return whether the dependency can support its feature."""

        return self.state in CAPABILITY_AVAILABLE_STATES

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready capability representation."""

        return {
            "name": self.name,
            "import_name": self.import_name,
            "state": self.state.value,
            "available": self.available,
            "required": self.required,
            "loaded": self.loaded,
            "version": self.version,
            "path": self.path,
            "reason": self.reason,
            "error_type": self.error_type,
            "metadata": dict(self.metadata),
        }


@dataclass
class ModuleCapability:
    """Observed availability and interface state of one internal module."""

    name: str
    state: CapabilityState = CapabilityState.UNKNOWN
    import_name: Optional[str] = None
    loaded: bool = False
    interface_validated: bool = False
    version: Optional[str] = None
    path: Optional[str] = None
    public_names: Tuple[str, ...] = ()
    missing_required_symbols: Tuple[str, ...] = ()
    available_optional_symbols: Tuple[str, ...] = ()
    reason: Optional[str] = None
    error_type: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def available(self) -> bool:
        """Return whether the module can support its registered stages."""

        return (
            self.state in CAPABILITY_AVAILABLE_STATES
            and not self.missing_required_symbols
        )

    @property
    def requirement(self) -> ModuleRequirement:
        """Return the registered requirement for this module."""

        return MODULE_REQUIREMENTS[self.name]

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready capability representation."""

        return {
            "name": self.name,
            "state": self.state.value,
            "available": self.available,
            "import_name": self.import_name,
            "loaded": self.loaded,
            "interface_validated": self.interface_validated,
            "version": self.version,
            "path": self.path,
            "public_names": list(self.public_names),
            "missing_required_symbols": list(self.missing_required_symbols),
            "available_optional_symbols": list(self.available_optional_symbols),
            "reason": self.reason,
            "error_type": self.error_type,
            "metadata": dict(self.metadata),
            "requirement": self.requirement.to_dict(),
        }


@dataclass
class FeatureCapability:
    """Resolved availability of one high-level DockAnalyzer feature."""

    name: str
    state: CapabilityState
    missing_modules: Tuple[str, ...] = ()
    missing_dependencies: Tuple[str, ...] = ()
    satisfied_optional_dependencies: Tuple[str, ...] = ()
    reason: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def available(self) -> bool:
        """Return whether the feature is usable."""

        return self.state in CAPABILITY_AVAILABLE_STATES

    @property
    def requirement(self) -> FeatureRequirement:
        """Return the registered requirement for this feature."""

        return FEATURE_REQUIREMENTS[self.name]

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready capability representation."""

        return {
            "name": self.name,
            "state": self.state.value,
            "available": self.available,
            "missing_modules": list(self.missing_modules),
            "missing_dependencies": list(self.missing_dependencies),
            "satisfied_optional_dependencies": list(
                self.satisfied_optional_dependencies
            ),
            "reason": self.reason,
            "metadata": dict(self.metadata),
            "requirement": self.requirement.to_dict(),
        }


@dataclass
class AnalysisCapabilities:
    """Complete capability snapshot for the current Python environment."""

    modules: Dict[str, ModuleCapability] = field(default_factory=dict)
    dependencies: Dict[str, DependencyCapability] = field(default_factory=dict)
    features: Dict[str, FeatureCapability] = field(default_factory=dict)
    runtime: Dict[str, Any] = field(default_factory=dict)
    inspected_at: str = field(default_factory=lambda: _utc_timestamp())
    package: Optional[str] = None
    loaded_modules: bool = False

    def supports_module(self, name: Any) -> bool:
        """Return whether an internal module is available."""

        canonical = canonicalize_analysis_module_name(name)
        capability = self.modules.get(canonical)
        return bool(capability and capability.available)

    def supports_dependency(self, name: Any) -> bool:
        """Return whether an external dependency is available."""

        canonical = canonicalize_dependency_name(name)
        capability = self.dependencies.get(canonical)
        return bool(capability and capability.available)

    def supports_feature(self, name: Any) -> bool:
        """Return whether a registered high-level feature is available."""

        canonical = canonicalize_feature_name(name)
        capability = self.features.get(canonical)
        return bool(capability and capability.available)

    def supports_stage(self, stage: Any) -> bool:
        """Return whether all requirements of one pipeline stage are met."""

        canonical = canonicalize_stage_name(stage)
        required_modules = STAGE_REQUIRED_MODULES.get(canonical, ())
        required_features = STAGE_FEATURES.get(canonical, ())
        return all(self.supports_module(name) for name in required_modules) and all(
            self.supports_feature(name) for name in required_features
        )

    def available_modules(self) -> Tuple[str, ...]:
        """Return available module names in canonical order."""

        return tuple(
            name for name in KNOWN_ANALYSIS_MODULES if self.supports_module(name)
        )

    def unavailable_modules(self) -> Tuple[str, ...]:
        """Return unavailable module names in canonical order."""

        return tuple(
            name
            for name in KNOWN_ANALYSIS_MODULES
            if not self.supports_module(name)
        )

    def available_features(self) -> Tuple[str, ...]:
        """Return available feature names in registry order."""

        return tuple(
            name for name in FEATURE_REQUIREMENTS if self.supports_feature(name)
        )

    def available_stages(self) -> Tuple[str, ...]:
        """Return pipeline stages supported by this snapshot."""

        return tuple(
            stage for stage in PIPELINE_STAGE_ORDER if self.supports_stage(stage)
        )

    def missing_required_items(self) -> Tuple[str, ...]:
        """Return globally required modules and dependencies that are missing."""

        missing: List[str] = []
        for name, requirement in MODULE_REQUIREMENTS.items():
            if requirement.globally_required and not self.supports_module(name):
                missing.append(f"module:{name}")
        for name, requirement in DEPENDENCY_REQUIREMENTS.items():
            if requirement.required and not self.supports_dependency(name):
                missing.append(f"dependency:{name}")
        return tuple(missing)

    @property
    def ready(self) -> bool:
        """Return whether all globally required capabilities are available."""

        return not self.missing_required_items()

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready capability snapshot."""

        return {
            "inspected_at": self.inspected_at,
            "package": self.package,
            "loaded_modules": self.loaded_modules,
            "ready": self.ready,
            "missing_required_items": list(self.missing_required_items()),
            "available_stages": list(self.available_stages()),
            "modules": {
                name: capability.to_dict()
                for name, capability in self.modules.items()
            },
            "dependencies": {
                name: capability.to_dict()
                for name, capability in self.dependencies.items()
            },
            "features": {
                name: capability.to_dict()
                for name, capability in self.features.items()
            },
            "runtime": dict(self.runtime),
        }

    def summary(self) -> Dict[str, Any]:
        """Return a compact capability summary."""

        return {
            "ready": self.ready,
            "module_count": len(self.modules),
            "available_module_count": len(self.available_modules()),
            "dependency_count": len(self.dependencies),
            "available_dependency_count": sum(
                item.available for item in self.dependencies.values()
            ),
            "feature_count": len(self.features),
            "available_feature_count": len(self.available_features()),
            "available_stages": list(self.available_stages()),
            "missing_required_items": list(self.missing_required_items()),
            "chimerax_available": self.supports_dependency("chimerax"),
        }


# 6.7. Module discovery and lazy loading
# -----------------------------------------------------------------------------

_ANALYSIS_MODULE_CACHE: Dict[str, ModuleType] = {}
_ANALYSIS_MODULE_CACHE_LOCK = threading.RLock()
_CAPABILITY_CACHE: Dict[
    Tuple[Optional[str], bool, bool, bool], AnalysisCapabilities
] = {}
_CAPABILITY_CACHE_LOCK = threading.RLock()


def get_analysis_package_name(package: Optional[str] = None) -> Optional[str]:
    """Resolve the package used for relative DockAnalyzer imports."""

    if package is not None:
        normalized = str(package).strip().strip(".")
        return normalized or None
    current = str(__package__ or "").strip().strip(".")
    return current or None


def module_import_candidates(
    name: Any,
    *,
    package: Optional[str] = None,
) -> Tuple[str, ...]:
    """Return package and direct import candidates for one internal module."""

    canonical = canonicalize_analysis_module_name(name)
    package_name = get_analysis_package_name(package)
    candidates: List[str] = []
    if package_name:
        candidates.append(f"{package_name}.{canonical}")
    candidates.append(canonical)
    return tuple(dict.fromkeys(candidates))


def _module_not_found_matches_candidate(
    error: ModuleNotFoundError,
    import_name: str,
) -> bool:
    """Return whether an import failure refers to the requested module."""

    missing_name = str(error.name or "").strip()
    candidate = str(import_name).strip()
    return bool(
        missing_name
        and candidate
        and (missing_name == candidate or candidate.startswith(f"{missing_name}."))
    )


def _find_module_spec(import_name: str) -> Any:
    """Return an import specification without importing the target module."""

    try:
        util = importlib.import_module("importlib.util")
        return util.find_spec(import_name)
    except ModuleNotFoundError as exc:
        if not _module_not_found_matches_candidate(exc, import_name):
            raise
        return None
    except (AttributeError, ValueError):
        return None


def find_analysis_module_spec(
    name: Any,
    *,
    package: Optional[str] = None,
) -> Tuple[Optional[str], Any]:
    """Find the first importable specification for an internal module."""

    for import_name in module_import_candidates(name, package=package):
        spec = _find_module_spec(import_name)
        if spec is not None:
            return import_name, spec
    return None, None


def get_loaded_analysis_module(
    name: Any,
    *,
    package: Optional[str] = None,
) -> Optional[ModuleType]:
    """Return an already loaded internal module without importing it."""

    canonical = canonicalize_analysis_module_name(name)
    with _ANALYSIS_MODULE_CACHE_LOCK:
        cached = _ANALYSIS_MODULE_CACHE.get(canonical)
        if cached is not None:
            return cached
    if canonical == "config":
        return config
    if canonical == "utils":
        return sys.modules.get(DockModel.__module__)
    for import_name in module_import_candidates(canonical, package=package):
        loaded = sys.modules.get(import_name)
        if isinstance(loaded, ModuleType):
            return loaded
    return None


def load_analysis_module(
    name: Any,
    *,
    package: Optional[str] = None,
    required: bool = True,
    reload: bool = False,
) -> Optional[ModuleType]:
    """Load one DockAnalyzer module using package-first resolution."""

    canonical = canonicalize_analysis_module_name(name)
    with _ANALYSIS_MODULE_CACHE_LOCK:
        cached = _ANALYSIS_MODULE_CACHE.get(canonical)
        if cached is not None and not reload:
            return cached

    if canonical == "config" and not reload:
        module = config
    elif canonical == "utils" and not reload:
        module = sys.modules.get(DockModel.__module__)
        if module is None:
            module = importlib.import_module(DockModel.__module__)
    else:
        module = None

    errors: List[BaseException] = []
    if module is None:
        for import_name in module_import_candidates(canonical, package=package):
            try:
                module = importlib.import_module(import_name)
                if reload:
                    module = importlib.reload(module)
                break
            except ModuleNotFoundError as exc:
                if not _module_not_found_matches_candidate(exc, import_name):
                    raise
                errors.append(exc)

    if module is None:
        if not required:
            return None
        details = {
            "module": canonical,
            "candidates": list(
                module_import_candidates(canonical, package=package)
            ),
            "errors": [str(error) for error in errors],
        }
        raise AnalysisDependencyError(
            f"DockAnalyzer module {canonical!r} is unavailable.",
            code="analysis_module_unavailable",
            details=details,
            cause=errors[-1] if errors else None,
        )

    with _ANALYSIS_MODULE_CACHE_LOCK:
        _ANALYSIS_MODULE_CACHE[canonical] = module
    return module


def clear_analysis_module_cache(*, clear_capabilities: bool = True) -> None:
    """Clear lazy module references retained by this orchestration module."""

    with _ANALYSIS_MODULE_CACHE_LOCK:
        _ANALYSIS_MODULE_CACHE.clear()
    if clear_capabilities:
        clear_capability_cache()


def clear_capability_cache() -> None:
    """Clear cached environment capability snapshots."""

    with _CAPABILITY_CACHE_LOCK:
        _CAPABILITY_CACHE.clear()


# 6.8. Public interface inspection
# -----------------------------------------------------------------------------


def get_module_public_names(module: ModuleType) -> Tuple[str, ...]:
    """Return explicit or inferred public names from a loaded module."""

    explicit = getattr(module, "__all__", None)
    if isinstance(explicit, (list, tuple, set, frozenset)):
        names = [str(name) for name in explicit if str(name).strip()]
    else:
        names = [name for name in vars(module) if not name.startswith("_")]
    return tuple(dict.fromkeys(sorted(names)))


def inspect_module_interface(
    module: ModuleType,
    requirement: ModuleRequirement,
) -> Tuple[Tuple[str, ...], Tuple[str, ...], Tuple[str, ...]]:
    """Return public names, missing required and present optional symbols."""

    public_names = get_module_public_names(module)
    missing = tuple(
        name for name in requirement.required_symbols if not hasattr(module, name)
    )
    optional = tuple(
        name for name in requirement.optional_symbols if hasattr(module, name)
    )
    return public_names, missing, optional


def validate_analysis_module_interface(
    name: Any,
    module: Optional[ModuleType] = None,
    *,
    package: Optional[str] = None,
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate the minimum public interface expected from one module."""

    canonical = canonicalize_analysis_module_name(name)
    requirement = MODULE_REQUIREMENTS[canonical]
    resolved = module or load_analysis_module(
        canonical,
        package=package,
        required=raise_on_error,
    )
    if resolved is None:
        return requirement.required_symbols
    _, missing, _ = inspect_module_interface(resolved, requirement)
    if missing and raise_on_error:
        raise AnalysisCapabilityError(
            f"Module {canonical!r} is missing required public symbols: "
            + ", ".join(missing),
            code="analysis_module_interface_invalid",
            details={"module": canonical, "missing_symbols": list(missing)},
        )
    return missing


def get_module_version(module: Optional[ModuleType]) -> Optional[str]:
    """Return a normalized module version when one is exposed."""

    if module is None:
        return None
    value = getattr(module, "__version__", None)
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def get_module_path(module: Optional[ModuleType], spec: Any = None) -> Optional[str]:
    """Return the best available source path for a module."""

    path = getattr(module, "__file__", None) if module is not None else None
    if not path and spec is not None:
        path = getattr(spec, "origin", None)
    if not path or path in {"built-in", "frozen"}:
        return None
    return str(path)


# 6.9. Dependency inspection
# -----------------------------------------------------------------------------


def _dependency_version(
    requirement: DependencyRequirement,
    module: Optional[ModuleType],
) -> Optional[str]:
    """Return a dependency version without requiring package metadata."""

    if module is not None:
        value = getattr(module, "__version__", None)
        if value is not None and str(value).strip():
            return str(value).strip()
    if requirement.distribution_name:
        try:
            metadata_module = importlib.import_module("importlib.metadata")
            return str(metadata_module.version(requirement.distribution_name))
        except Exception:
            return None
    return None


def inspect_dependency_capability(
    name: Any,
    *,
    load: bool = False,
) -> DependencyCapability:
    """Inspect one external dependency with optional import validation."""

    canonical = canonicalize_dependency_name(name)
    requirement = DEPENDENCY_REQUIREMENTS[canonical]
    import_name = requirement.import_name
    module: Optional[ModuleType] = None

    if canonical == "numpy" and NUMPY_AVAILABLE:
        module = np
    elif canonical == "chimerax" and CHIMERAX_AVAILABLE:
        module = _chimerax
    else:
        loaded = sys.modules.get(import_name)
        if isinstance(loaded, ModuleType):
            module = loaded

    spec = _find_module_spec(import_name)
    if module is None and spec is None:
        return DependencyCapability(
            name=canonical,
            import_name=import_name,
            state=CapabilityState.UNAVAILABLE,
            required=requirement.required,
            reason=f"Dependency {import_name!r} was not found.",
        )

    if module is None and load:
        try:
            module = importlib.import_module(import_name)
        except Exception as exc:
            return DependencyCapability(
                name=canonical,
                import_name=import_name,
                state=CapabilityState.UNAVAILABLE,
                required=requirement.required,
                reason=str(exc),
                error_type=type(exc).__name__,
            )

    return DependencyCapability(
        name=canonical,
        import_name=import_name,
        state=CapabilityState.AVAILABLE,
        required=requirement.required,
        loaded=module is not None,
        version=_dependency_version(requirement, module),
        path=get_module_path(module, spec),
        metadata={"purpose": requirement.purpose},
    )


# 6.10. Internal module inspection
# -----------------------------------------------------------------------------


def inspect_module_capability(
    name: Any,
    *,
    package: Optional[str] = None,
    load: bool = False,
    validate_interface: bool = True,
) -> ModuleCapability:
    """Inspect one DockAnalyzer module and optionally validate its interface."""

    canonical = canonicalize_analysis_module_name(name)
    requirement = MODULE_REQUIREMENTS[canonical]
    loaded_module = get_loaded_analysis_module(canonical, package=package)
    import_name, spec = find_analysis_module_spec(canonical, package=package)

    if loaded_module is None and import_name is None:
        return ModuleCapability(
            name=canonical,
            state=CapabilityState.UNAVAILABLE,
            reason=f"DockAnalyzer module {canonical!r} was not found.",
        )

    module = loaded_module
    error: Optional[BaseException] = None
    if module is None and load:
        try:
            module = load_analysis_module(
                canonical,
                package=package,
                required=True,
            )
            import_name = module.__name__
        except BaseException as exc:
            error = exc

    if error is not None:
        return ModuleCapability(
            name=canonical,
            state=CapabilityState.UNAVAILABLE,
            import_name=import_name,
            loaded=False,
            path=get_module_path(None, spec),
            reason=str(error),
            error_type=type(error).__name__,
        )

    public_names: Tuple[str, ...] = ()
    missing: Tuple[str, ...] = ()
    optional: Tuple[str, ...] = ()
    interface_validated = False
    state = CapabilityState.AVAILABLE
    reason = None

    if module is not None and validate_interface:
        public_names, missing, optional = inspect_module_interface(
            module,
            requirement,
        )
        interface_validated = True
        if missing:
            state = CapabilityState.DEGRADED
            reason = "Missing required public symbols: " + ", ".join(missing)

    return ModuleCapability(
        name=canonical,
        state=state,
        import_name=(module.__name__ if module is not None else import_name),
        loaded=module is not None,
        interface_validated=interface_validated,
        version=get_module_version(module),
        path=get_module_path(module, spec),
        public_names=public_names,
        missing_required_symbols=missing,
        available_optional_symbols=optional,
        reason=reason,
        metadata={
            "role": requirement.role,
            "stages": list(requirement.stages),
            "globally_required": requirement.globally_required,
        },
    )


# 6.11. Feature resolution
# -----------------------------------------------------------------------------


def resolve_feature_capability(
    requirement: FeatureRequirement,
    *,
    modules: Mapping[str, ModuleCapability],
    dependencies: Mapping[str, DependencyCapability],
) -> FeatureCapability:
    """Resolve a feature from previously inspected module capabilities."""

    missing_modules = tuple(
        name
        for name in requirement.modules
        if name not in modules or not modules[name].available
    )
    missing_dependencies = tuple(
        name
        for name in requirement.dependencies
        if name not in dependencies or not dependencies[name].available
    )
    satisfied_optional = tuple(
        name
        for name in requirement.any_dependencies
        if name in dependencies and dependencies[name].available
    )

    if requirement.any_dependencies and not satisfied_optional:
        missing_dependencies = tuple(
            dict.fromkeys((*missing_dependencies, *requirement.any_dependencies))
        )

    if missing_modules or missing_dependencies:
        reason_parts: List[str] = []
        if missing_modules:
            reason_parts.append("missing modules: " + ", ".join(missing_modules))
        if missing_dependencies:
            reason_parts.append(
                "missing dependencies: " + ", ".join(missing_dependencies)
            )
        return FeatureCapability(
            name=requirement.name,
            state=CapabilityState.UNAVAILABLE,
            missing_modules=missing_modules,
            missing_dependencies=missing_dependencies,
            satisfied_optional_dependencies=satisfied_optional,
            reason="; ".join(reason_parts),
        )

    degraded_modules = tuple(
        name
        for name in requirement.modules
        if modules[name].state == CapabilityState.DEGRADED
    )
    state = (
        CapabilityState.DEGRADED
        if degraded_modules
        else CapabilityState.AVAILABLE
    )
    reason = (
        "Modules with limited interfaces: " + ", ".join(degraded_modules)
        if degraded_modules
        else None
    )
    return FeatureCapability(
        name=requirement.name,
        state=state,
        satisfied_optional_dependencies=satisfied_optional,
        reason=reason,
    )


def inspect_runtime_environment() -> Dict[str, Any]:
    """Return stable runtime information relevant to orchestration."""

    return {
        "python_version": platform.python_version(),
        "python_implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "system": platform.system(),
        "machine": platform.machine(),
        "optimization_level": int(not __debug__),
        "module_name": __name__,
        "package": get_analysis_package_name(),
        "numpy_available": NUMPY_AVAILABLE,
        "chimerax_available": CHIMERAX_AVAILABLE,
        "thread_name": threading.current_thread().name,
    }


def inspect_analysis_capabilities(
    *,
    package: Optional[str] = None,
    load_modules: bool = False,
    load_dependencies: bool = False,
    validate_interfaces: bool = True,
    refresh: bool = False,
) -> AnalysisCapabilities:
    """Inspect the current environment and return a capability snapshot."""

    package_name = get_analysis_package_name(package)
    cache_key = (
        package_name,
        bool(load_modules),
        bool(load_dependencies),
        bool(validate_interfaces),
    )
    if not refresh:
        with _CAPABILITY_CACHE_LOCK:
            cached = _CAPABILITY_CACHE.get(cache_key)
            if cached is not None:
                return copy.deepcopy(cached)

    dependencies = {
        name: inspect_dependency_capability(name, load=load_dependencies)
        for name in DEPENDENCY_REQUIREMENTS
    }
    modules = {
        name: inspect_module_capability(
            name,
            package=package_name,
            load=load_modules,
            validate_interface=validate_interfaces,
        )
        for name in MODULE_REQUIREMENTS
    }
    features = {
        name: resolve_feature_capability(
            requirement,
            modules=modules,
            dependencies=dependencies,
        )
        for name, requirement in FEATURE_REQUIREMENTS.items()
    }
    snapshot = AnalysisCapabilities(
        modules=modules,
        dependencies=dependencies,
        features=features,
        runtime=inspect_runtime_environment(),
        package=package_name,
        loaded_modules=load_modules,
    )
    with _CAPABILITY_CACHE_LOCK:
        _CAPABILITY_CACHE[cache_key] = copy.deepcopy(snapshot)
    return snapshot


# 6.12. Capability queries and requirements
# -----------------------------------------------------------------------------


def available_analysis_modules(
    capabilities: Optional[AnalysisCapabilities] = None,
    **inspection_options: Any,
) -> Tuple[str, ...]:
    """Return internal modules available in the current environment."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    return snapshot.available_modules()


def unavailable_analysis_modules(
    capabilities: Optional[AnalysisCapabilities] = None,
    **inspection_options: Any,
) -> Tuple[str, ...]:
    """Return unavailable internal modules in canonical order."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    return snapshot.unavailable_modules()


def available_analysis_stages(
    capabilities: Optional[AnalysisCapabilities] = None,
    **inspection_options: Any,
) -> Tuple[str, ...]:
    """Return pipeline stages supported by the current environment."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    return snapshot.available_stages()


def unavailable_analysis_stages(
    capabilities: Optional[AnalysisCapabilities] = None,
    **inspection_options: Any,
) -> Tuple[str, ...]:
    """Return pipeline stages not supported by the current environment."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    available = set(snapshot.available_stages())
    return tuple(stage for stage in PIPELINE_STAGE_ORDER if stage not in available)


def supports_analysis_stage(
    stage: Any,
    capabilities: Optional[AnalysisCapabilities] = None,
    **inspection_options: Any,
) -> bool:
    """Return whether one pipeline stage is supported."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    return snapshot.supports_stage(stage)


def require_analysis_module(
    name: Any,
    *,
    capabilities: Optional[AnalysisCapabilities] = None,
    package: Optional[str] = None,
    load: bool = True,
) -> ModuleType:
    """Return a usable module or raise a structured dependency error."""

    canonical = canonicalize_analysis_module_name(name)
    if capabilities is not None and not capabilities.supports_module(canonical):
        capability = capabilities.modules.get(canonical)
        raise AnalysisCapabilityError(
            f"Required DockAnalyzer module {canonical!r} is unavailable.",
            code="required_analysis_module_unavailable",
            details={
                "module": canonical,
                "capability": capability.to_dict() if capability else None,
            },
        )
    module = load_analysis_module(
        canonical,
        package=package,
        required=True,
    )
    assert module is not None
    if load:
        validate_analysis_module_interface(
            canonical,
            module,
            package=package,
            raise_on_error=True,
        )
    return module


def require_runtime_dependency(
    name: Any,
    *,
    load: bool = True,
) -> ModuleType:
    """Import and return an external dependency or raise a capability error."""

    canonical = canonicalize_dependency_name(name)
    capability = inspect_dependency_capability(canonical, load=load)
    if not capability.available:
        raise AnalysisCapabilityError(
            f"Required runtime dependency {canonical!r} is unavailable.",
            code="required_runtime_dependency_unavailable",
            details={"dependency": canonical, "capability": capability.to_dict()},
        )
    import_name = DEPENDENCY_REQUIREMENTS[canonical].import_name
    module = sys.modules.get(import_name)
    if isinstance(module, ModuleType):
        return module
    return importlib.import_module(import_name)


def require_analysis_feature(
    name: Any,
    *,
    capabilities: Optional[AnalysisCapabilities] = None,
    package: Optional[str] = None,
    load_modules: bool = True,
) -> FeatureCapability:
    """Require one high-level feature and return its capability record."""

    canonical = canonicalize_feature_name(name)
    snapshot = capabilities or inspect_analysis_capabilities(
        package=package,
        load_modules=load_modules,
        load_dependencies=load_modules,
        refresh=load_modules,
    )
    capability = snapshot.features[canonical]
    if not capability.available:
        raise AnalysisCapabilityError(
            f"Analysis feature {canonical!r} is unavailable.",
            code="analysis_feature_unavailable",
            details={"feature": canonical, "capability": capability.to_dict()},
        )
    return capability


def require_analysis_stage(
    stage: Any,
    *,
    capabilities: Optional[AnalysisCapabilities] = None,
    package: Optional[str] = None,
    load_modules: bool = True,
) -> str:
    """Require all capabilities needed by one pipeline stage."""

    canonical = canonicalize_stage_name(stage)
    snapshot = capabilities or inspect_analysis_capabilities(
        package=package,
        load_modules=load_modules,
        load_dependencies=load_modules,
        refresh=load_modules,
    )
    if not snapshot.supports_stage(canonical):
        missing_modules = [
            name
            for name in STAGE_REQUIRED_MODULES.get(canonical, ())
            if not snapshot.supports_module(name)
        ]
        missing_features = [
            name
            for name in STAGE_FEATURES.get(canonical, ())
            if not snapshot.supports_feature(name)
        ]
        raise AnalysisStageDependencyError(
            f"Pipeline stage {canonical!r} is unavailable.",
            stage=canonical,
            details={
                "missing_modules": missing_modules,
                "missing_features": missing_features,
            },
        )
    return canonical


# 6.13. Capability reporting and warnings
# -----------------------------------------------------------------------------


def summarize_analysis_capabilities(
    capabilities: Optional[AnalysisCapabilities] = None,
    **inspection_options: Any,
) -> Dict[str, Any]:
    """Return a compact environment capability summary."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    return snapshot.summary()


def analysis_capabilities_to_json(
    capabilities: Optional[AnalysisCapabilities] = None,
    *,
    indent: Optional[int] = 2,
    **inspection_options: Any,
) -> str:
    """Serialize a capability snapshot as JSON."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    return json.dumps(snapshot.to_dict(), indent=indent, sort_keys=True)


def warn_unavailable_capabilities(
    capabilities: Optional[AnalysisCapabilities] = None,
    *,
    include_optional: bool = False,
    stacklevel: int = 2,
    **inspection_options: Any,
) -> Tuple[str, ...]:
    """Emit structured warnings for unavailable required capabilities."""

    snapshot = capabilities or inspect_analysis_capabilities(**inspection_options)
    messages: List[str] = []
    for item in snapshot.missing_required_items():
        messages.append(f"Required analysis capability is unavailable: {item}.")
    if include_optional:
        for name, capability in snapshot.dependencies.items():
            requirement = DEPENDENCY_REQUIREMENTS[name]
            if not requirement.required and not capability.available:
                messages.append(
                    f"Optional dependency {name!r} is unavailable; "
                    f"{requirement.purpose.lower()} may be limited."
                )
        for name, capability in snapshot.modules.items():
            requirement = MODULE_REQUIREMENTS[name]
            if not requirement.globally_required and not capability.available:
                messages.append(
                    f"Optional analysis module {name!r} is unavailable."
                )
    for message in messages:
        warnings.warn(
            AnalysisDependencyWarning(message),
            stacklevel=stacklevel,
        )
    return tuple(messages)


# 6.14. Capability validation
# -----------------------------------------------------------------------------


def validate_analysis_capabilities(
    capabilities: AnalysisCapabilities,
    *,
    require_core: bool = True,
    required_stages: Iterable[Any] = (),
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate a capability snapshot against core and stage requirements."""

    if not isinstance(capabilities, AnalysisCapabilities):
        raise AnalysisValidationError(
            "Expected an AnalysisCapabilities instance."
        )
    issues: List[str] = []
    if require_core:
        issues.extend(
            f"Missing required capability: {item}."
            for item in capabilities.missing_required_items()
        )
    for stage in required_stages:
        canonical = canonicalize_stage_name(stage)
        if not capabilities.supports_stage(canonical):
            issues.append(f"Unsupported required stage: {canonical}.")
    for name in MODULE_REQUIREMENTS:
        if name not in capabilities.modules:
            issues.append(f"Missing module capability record: {name}.")
    for name in DEPENDENCY_REQUIREMENTS:
        if name not in capabilities.dependencies:
            issues.append(f"Missing dependency capability record: {name}.")
    for name in FEATURE_REQUIREMENTS:
        if name not in capabilities.features:
            issues.append(f"Missing feature capability record: {name}.")
    result = tuple(issues)
    if result and raise_on_error:
        raise AnalysisCapabilityError(
            "Invalid analysis capability snapshot: " + " ".join(result),
            code="analysis_capability_snapshot_invalid",
            details={"issues": list(result)},
        )
    return result


def validate_dependency_capability_conventions(
    *,
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate registries, discovery helpers and lightweight snapshots."""

    issues: List[str] = []
    try:
        if tuple(MODULE_REQUIREMENTS) != KNOWN_ANALYSIS_MODULES:
            issues.append("Module requirement order does not match conventions.")
        if tuple(DEPENDENCY_REQUIREMENTS) != KNOWN_RUNTIME_DEPENDENCIES:
            issues.append(
                "Dependency requirement order does not match conventions."
            )
        for stage, modules in STAGE_REQUIRED_MODULES.items():
            for name in modules:
                if name not in MODULE_REQUIREMENTS:
                    issues.append(
                        f"Stage {stage!r} references unknown module {name!r}."
                    )
        for stage, features in STAGE_FEATURES.items():
            for name in features:
                if name not in FEATURE_REQUIREMENTS:
                    issues.append(
                        f"Stage {stage!r} references unknown feature {name!r}."
                    )
        for name, requirement in FEATURE_REQUIREMENTS.items():
            for module_name in requirement.modules:
                if module_name not in MODULE_REQUIREMENTS:
                    issues.append(
                        f"Feature {name!r} references unknown module "
                        f"{module_name!r}."
                    )
            for dependency_name in (
                *requirement.dependencies,
                *requirement.any_dependencies,
            ):
                if dependency_name not in DEPENDENCY_REQUIREMENTS:
                    issues.append(
                        f"Feature {name!r} references unknown dependency "
                        f"{dependency_name!r}."
                    )

        snapshot = inspect_analysis_capabilities(
            load_modules=False,
            load_dependencies=False,
            validate_interfaces=False,
            refresh=True,
        )
        validate_analysis_capabilities(
            snapshot,
            require_core=False,
            raise_on_error=True,
        )
        encoded = analysis_capabilities_to_json(snapshot, indent=None)
        decoded = json.loads(encoded)
        if "modules" not in decoded or "dependencies" not in decoded:
            issues.append("Capability JSON representation is incomplete.")
        if canonicalize_analysis_module_name("hbond") != "hbonds":
            issues.append("Module alias normalization failed.")
        if canonicalize_dependency_name("pillow") != "PIL":
            issues.append("Dependency alias normalization failed.")
        if canonicalize_feature_name("contacts") != "contact_analysis":
            issues.append("Feature alias normalization failed.")
    except Exception as exc:
        issues.append(f"Capability convention probe failed: {exc}")

    result = tuple(issues)
    if result and raise_on_error:
        raise RuntimeError(
            "Invalid dependency and capability conventions: " + " ".join(result)
        )
    return result


