# =============================================================================
# Section 7 — Generic object access and normalization
# =============================================================================

# This section defines chemistry-independent access and normalization helpers.
# Later sections use these functions to accept DockModel instances, ChimeraX
# objects, dataclasses, mappings and lightweight synthetic test objects through
# one predictable interface.


# 7.1. Access conventions and sentinels
# -----------------------------------------------------------------------------

class MissingValue:
    """Singleton-style marker used when a value is absent rather than null."""

    __slots__ = ()

    def __repr__(self) -> str:
        return "MISSING_VALUE"

    def __bool__(self) -> bool:
        return False


MISSING_VALUE: Final[MissingValue] = MissingValue()

MAX_OBJECT_ACCESS_DEPTH: Final[int] = 24
MAX_OBJECT_ACCESS_ITEMS: Final[int] = 100_000
MAX_OBJECT_TEXT_LENGTH: Final[int] = 100_000
