# 7.2. Structured access and identity records
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class ObjectAccessResult:
    """Describe one safe object-access attempt."""

    found: bool
    value: Any = MISSING_VALUE
    requested: Optional[str] = None
    resolved: Optional[str] = None
    source: Optional[str] = None
    error: Optional[str] = None

    def unwrap(self, default: Any = None) -> Any:
        """Return the value when found, otherwise ``default``."""

        return self.value if self.found else default

    def to_dict(self, *, include_value: bool = True) -> Dict[str, Any]:
        """Return an inspection-safe dictionary representation."""

        data: Dict[str, Any] = {
            "found": self.found,
            "requested": self.requested,
            "resolved": self.resolved,
            "source": self.source,
            "error": self.error,
        }
        if include_value:
            data["value"] = (
                _result_value_to_data(self.value)
                if self.found
                else None
            )
        return data


@dataclass(frozen=True)
class ObjectIdentity:
    """Stable descriptive identity for an arbitrary input object."""

    name: str
    identifier: Optional[str] = None
    type_name: str = "object"
    module_name: str = "builtins"
    kind: Optional[str] = None
    fingerprint: Optional[str] = None

    @property
    def qualified_type(self) -> str:
        """Return the fully qualified runtime type name."""

        if self.module_name in {"", "builtins"}:
            return self.type_name
        return f"{self.module_name}.{self.type_name}"

    @property
    def display(self) -> str:
        """Return a concise display string."""

        if self.identifier and self.identifier != self.name:
            return f"{self.name} [{self.identifier}]"
        return self.name

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable representation."""

        return {
            "name": self.name,
            "identifier": self.identifier,
            "type": self.type_name,
            "module": self.module_name,
            "qualified_type": self.qualified_type,
            "kind": self.kind,
            "fingerprint": self.fingerprint,
        }


# 7.3. Type and shape inspection
# -----------------------------------------------------------------------------

def is_missing_value(value: Any) -> bool:
    """Return whether ``value`` is the missing-value sentinel."""

    return value is MISSING_VALUE or isinstance(value, MissingValue)


def is_mapping_like(value: Any) -> bool:
    """Return whether ``value`` exposes mapping semantics."""

    return isinstance(value, Mapping)


def is_mutable_mapping_like(value: Any) -> bool:
    """Return whether ``value`` exposes mutable mapping semantics."""

    return isinstance(value, MutableMapping)


def is_nonstring_iterable(value: Any) -> bool:
    """Return whether ``value`` is iterable but not scalar text or a mapping."""

    if value is None or isinstance(value, (str, bytes, bytearray, Mapping)):
        return False
    try:
        iter(value)
    except TypeError:
        return False
    return True


def is_sequence_like(value: Any) -> bool:
    """Return whether ``value`` should be treated as an ordered collection."""

    if isinstance(value, (str, bytes, bytearray, Mapping)):
        return False
    return isinstance(value, Sequence) or is_nonstring_iterable(value)


def is_scalar_like(value: Any) -> bool:
    """Return whether ``value`` is naturally represented as one scalar."""

    return value is None or isinstance(
        value,
        (str, bytes, bytearray, bool, int, float, complex, Enum, Path),
    )


def is_dataclass_instance(value: Any) -> bool:
    """Return whether ``value`` is a dataclass instance rather than a class."""

    return is_dataclass(value) and not isinstance(value, type)


def is_path_like(value: Any) -> bool:
    """Return whether ``value`` can represent a filesystem path."""

    return isinstance(value, (str, os.PathLike, Path))


def is_dock_model_like(value: Any) -> bool:
    """Return whether ``value`` has the minimum structural DockModel shape."""

    if isinstance(value, DockModel):
        return True
    if value is None:
        return False
    has_name = has_object_value(value, "name", include_aliases=True)
    has_pose = has_object_value(value, "pose", include_aliases=True)
    has_result_storage = any(
        has_object_value(value, field_name, include_aliases=True)
        for field_name in ("contacts", "hbonds", "hydrophobic", "pi", "statistics")
    )
    return has_name and (has_pose or has_result_storage)


# 7.4. Canonical field names and aliases
# -----------------------------------------------------------------------------

def _normalize_access_token(value: Any) -> str:
    """Normalize a field token for case- and separator-insensitive matching."""

    text = str(value).strip().lower()
    return _ACCESS_TOKEN_PATTERN.sub("", text)


def _build_object_field_alias_indexes(
) -> Tuple[Mapping[str, str], Mapping[str, Tuple[str, ...]]]:
    """Build immutable token and candidate indexes for object fields."""

    canonical_by_token: Dict[str, str] = {}
    candidates_by_canonical: Dict[str, Tuple[str, ...]] = {}
    for canonical, aliases in OBJECT_FIELD_ALIASES.items():
        ordered_items: List[str] = []
        seen_items: Set[str] = set()
        for candidate in (canonical, *aliases):
            if candidate not in seen_items:
                ordered_items.append(candidate)
                seen_items.add(candidate)
        ordered = tuple(ordered_items)
        candidates_by_canonical[canonical] = ordered
        for alias in ordered:
            token = _normalize_access_token(alias)
            if token:
                canonical_by_token.setdefault(token, canonical)
    return (
        MappingProxyType(canonical_by_token),
        MappingProxyType(candidates_by_canonical),
    )


_OBJECT_FIELD_CANONICAL_BY_TOKEN, _OBJECT_FIELD_CANDIDATES = (
    _build_object_field_alias_indexes()
)


def canonicalize_object_field_name(value: Any) -> str:
    """Return the canonical field name for an object-access token."""

    raw_name = str(value).strip()
    token = _normalize_access_token(raw_name)
    if not token:
        raise ValueError("Object field name cannot be empty.")
    return _OBJECT_FIELD_CANONICAL_BY_TOKEN.get(token, raw_name)


def get_object_field_aliases(
    field_name: Any,
    *,
    extra_aliases: Iterable[Any] = (),
    include_canonical: bool = True,
) -> Tuple[str, ...]:
    """Return unique access candidates for one canonical or custom field."""

    raw_name = str(field_name).strip()
    if not raw_name:
        raise ValueError("Object field name cannot be empty.")
    canonical = canonicalize_object_field_name(raw_name)
    base = _OBJECT_FIELD_CANDIDATES.get(canonical, (raw_name,))
    candidates: List[str] = list(base if include_canonical else base[1:])
    if raw_name not in candidates:
        candidates.insert(0, raw_name)
    candidates.extend(str(alias).strip() for alias in extra_aliases)
    return tuple(unique_preserving_order(candidate for candidate in candidates if candidate))


# 7.5. Safe attribute and item access
# -----------------------------------------------------------------------------

def safe_getattr(
    obj: Any,
    name: str,
    default: Any = None,
    *,
    call: bool = False,
    allow_private: bool = False,
    raise_errors: bool = False,
) -> Any:
    """Read an attribute without leaking ordinary descriptor failures."""

    if obj is None:
        return default
    attribute_name = str(name).strip()
    if not attribute_name:
        return default
    if attribute_name.startswith("_") and not allow_private:
        return default
    try:
        value = getattr(obj, attribute_name)
        if call and callable(value):
            value = value()
        return value
    except Exception:
        if raise_errors:
            raise
        return default


def safe_getitem(
    obj: Any,
    key: Any,
    default: Any = None,
    *,
    raise_errors: bool = False,
) -> Any:
    """Read a mapping or index value without leaking ordinary access failures."""

    if obj is None:
        return default
    try:
        return obj[key]
    except Exception:
        if raise_errors:
            raise
        return default


def _mapping_key_index(mapping: Mapping[Any, Any]) -> Dict[str, Any]:
    """Build a normalized-key index while preserving the first matching key."""

    index: Dict[str, Any] = {}
    for key in list(mapping.keys())[:MAX_OBJECT_ACCESS_ITEMS]:
        token = _normalize_access_token(key)
        if token and token not in index:
            index[token] = key
    return index


def _attribute_name_index(obj: Any) -> Dict[str, str]:
    """Build a normalized public-attribute index for an arbitrary object."""

    try:
        names = dir(obj)
    except Exception:
        return {}
    index: Dict[str, str] = {}
    for name in names[:MAX_OBJECT_ACCESS_ITEMS]:
        if not isinstance(name, str) or name.startswith("_"):
            continue
        token = _normalize_access_token(name)
        if token and token not in index:
            index[token] = name
    return index


def access_object_value(
    obj: Any,
    field_name: Any,
    *,
    aliases: Iterable[Any] = (),
    include_aliases: bool = True,
    call: bool = False,
    skip_none: bool = False,
    allow_private: bool = False,
    normalized_match: bool = True,
) -> ObjectAccessResult:
    """Resolve one value from a mapping or object with structured diagnostics."""

    requested = str(field_name).strip()
    if not requested:
        return ObjectAccessResult(
            found=False,
            requested=requested,
            error="Object field name cannot be empty.",
        )
    try:
        candidates = (
            get_object_field_aliases(
                requested,
                extra_aliases=aliases,
                include_canonical=True,
            )
            if include_aliases
            else tuple(
                unique_preserving_order(
                    [requested, *(str(alias).strip() for alias in aliases)]
                )
            )
        )
    except Exception as exc:
        return ObjectAccessResult(
            found=False,
            requested=requested,
            error=str(exc),
        )

    if isinstance(obj, Mapping):
        for candidate in candidates:
            if candidate in obj:
                try:
                    value = obj[candidate]
                    if call and callable(value):
                        value = value()
                except Exception as exc:
                    return ObjectAccessResult(
                        found=False,
                        requested=requested,
                        resolved=candidate,
                        source="mapping",
                        error=str(exc),
                    )
                if skip_none and value is None:
                    continue
                return ObjectAccessResult(
                    found=True,
                    value=value,
                    requested=requested,
                    resolved=str(candidate),
                    source="mapping",
                )
        if normalized_match:
            key_index = _mapping_key_index(obj)
            for candidate in candidates:
                matched_key = key_index.get(_normalize_access_token(candidate))
                if matched_key is None:
                    continue
                try:
                    value = obj[matched_key]
                    if call and callable(value):
                        value = value()
                except Exception as exc:
                    return ObjectAccessResult(
                        found=False,
                        requested=requested,
                        resolved=str(matched_key),
                        source="mapping",
                        error=str(exc),
                    )
                if skip_none and value is None:
                    continue
                return ObjectAccessResult(
                    found=True,
                    value=value,
                    requested=requested,
                    resolved=str(matched_key),
                    source="mapping",
                )

    if obj is not None:
        for candidate in candidates:
            if candidate.startswith("_") and not allow_private:
                continue
            marker = MISSING_VALUE
            try:
                value = getattr(obj, candidate, marker)
                if value is marker:
                    continue
                if call and callable(value):
                    value = value()
            except Exception as exc:
                return ObjectAccessResult(
                    found=False,
                    requested=requested,
                    resolved=candidate,
                    source="attribute",
                    error=str(exc),
                )
            if skip_none and value is None:
                continue
            return ObjectAccessResult(
                found=True,
                value=value,
                requested=requested,
                resolved=candidate,
                source="attribute",
            )
        if normalized_match:
            attribute_index = _attribute_name_index(obj)
            for candidate in candidates:
                matched_name = attribute_index.get(_normalize_access_token(candidate))
                if matched_name is None:
                    continue
                marker = MISSING_VALUE
                try:
                    value = getattr(obj, matched_name, marker)
                    if value is marker:
                        continue
                    if call and callable(value):
                        value = value()
                except Exception as exc:
                    return ObjectAccessResult(
                        found=False,
                        requested=requested,
                        resolved=matched_name,
                        source="attribute",
                        error=str(exc),
                    )
                if skip_none and value is None:
                    continue
                return ObjectAccessResult(
                    found=True,
                    value=value,
                    requested=requested,
                    resolved=matched_name,
                    source="attribute",
                )

    return ObjectAccessResult(found=False, requested=requested)


def get_object_value(
    obj: Any,
    field_name: Any,
    default: Any = None,
    *,
    aliases: Iterable[Any] = (),
    include_aliases: bool = True,
    call: bool = False,
    skip_none: bool = False,
    allow_private: bool = False,
    normalized_match: bool = True,
) -> Any:
    """Return one mapping item or attribute through canonical field aliases."""

    result = access_object_value(
        obj,
        field_name,
        aliases=aliases,
        include_aliases=include_aliases,
        call=call,
        skip_none=skip_none,
        allow_private=allow_private,
        normalized_match=normalized_match,
    )
    return result.value if result.found else default


def get_first_object_value(
    obj: Any,
    field_names: Iterable[Any],
    default: Any = None,
    *,
    call: bool = False,
    skip_none: bool = True,
) -> Any:
    """Return the first available value among several field names."""

    for field_name in field_names:
        result = access_object_value(
            obj,
            field_name,
            call=call,
            skip_none=skip_none,
        )
        if result.found:
            return result.value
    return default


def has_object_value(
    obj: Any,
    field_name: Any,
    *,
    aliases: Iterable[Any] = (),
    include_aliases: bool = True,
    require_non_none: bool = False,
) -> bool:
    """Return whether one canonical field can be resolved."""

    result = access_object_value(
        obj,
        field_name,
        aliases=aliases,
        include_aliases=include_aliases,
        skip_none=require_non_none,
    )
    return result.found


def set_object_value(
    obj: Any,
    field_name: Any,
    value: Any,
    *,
    aliases: Iterable[Any] = (),
    include_aliases: bool = True,
    prefer_existing: bool = True,
    allow_private: bool = False,
    strict: bool = True,
) -> bool:
    """Set a mutable mapping item or writable object attribute."""

    if obj is None:
        if strict:
            raise TypeError("Cannot set a value on None.")
        return False
    candidates = (
        get_object_field_aliases(field_name, extra_aliases=aliases)
        if include_aliases
        else tuple(
            unique_preserving_order(
                [str(field_name).strip(), *(str(alias).strip() for alias in aliases)]
            )
        )
    )
    candidates = tuple(
        candidate
        for candidate in candidates
        if candidate and (allow_private or not candidate.startswith("_"))
    )
    if not candidates:
        if strict:
            raise ValueError("No writable field name was provided.")
        return False

    if isinstance(obj, MutableMapping):
        target_key: Any = candidates[0]
        if prefer_existing:
            for candidate in candidates:
                if candidate in obj:
                    target_key = candidate
                    break
            else:
                key_index = _mapping_key_index(obj)
                for candidate in candidates:
                    matched = key_index.get(_normalize_access_token(candidate))
                    if matched is not None:
                        target_key = matched
                        break
        try:
            obj[target_key] = value
            return True
        except Exception:
            if strict:
                raise
            return False

    target_attribute = candidates[0]
    if prefer_existing:
        for candidate in candidates:
            try:
                inspect.getattr_static(obj, candidate)
            except (AttributeError, TypeError):
                continue
            target_attribute = candidate
            break
        else:
            attribute_index = _attribute_name_index(obj)
            for candidate in candidates:
                matched = attribute_index.get(_normalize_access_token(candidate))
                if matched is not None:
                    target_attribute = matched
                    break
    try:
        setattr(obj, target_attribute, value)
        return True
    except Exception:
        if strict:
            raise
        return False


def delete_object_value(
    obj: Any,
    field_name: Any,
    *,
    aliases: Iterable[Any] = (),
    include_aliases: bool = True,
    strict: bool = False,
) -> bool:
    """Delete an existing mapping item or writable object attribute."""

    result = access_object_value(
        obj,
        field_name,
        aliases=aliases,
        include_aliases=include_aliases,
    )
    if not result.found or result.resolved is None:
        if strict:
            raise KeyError(str(field_name))
        return False
    try:
        if result.source == "mapping" and isinstance(obj, MutableMapping):
            del obj[result.resolved]
        else:
            delattr(obj, result.resolved)
        return True
    except Exception:
        if strict:
            raise
        return False


# 7.6. Nested paths
# -----------------------------------------------------------------------------

def normalize_access_path(path: Any) -> Tuple[Any, ...]:
    """Normalize a dotted string or component sequence into an access path."""

    if isinstance(path, str):
        text = path.strip()
        if not text:
            return ()
        components: List[Any] = []
        for component in text.split("."):
            token = component.strip()
            if not token:
                continue
            if re.fullmatch(r"-?\d+", token):
                components.append(int(token))
            else:
                components.append(token)
        return tuple(components)
    if isinstance(path, Sequence) and not isinstance(path, (bytes, bytearray)):
        return tuple(path)
    return (path,)


def get_nested_value(
    obj: Any,
    path: Any,
    default: Any = None,
    *,
    include_aliases: bool = True,
    skip_none: bool = False,
) -> Any:
    """Read a nested object, mapping or sequence path safely."""

    components = normalize_access_path(path)
    if not components:
        return obj
    current = obj
    for component in components[:MAX_OBJECT_ACCESS_DEPTH]:
        if isinstance(component, int):
            marker = MISSING_VALUE
            current = safe_getitem(current, component, marker)
            if current is marker:
                return default
        else:
            result = access_object_value(
                current,
                component,
                include_aliases=include_aliases,
                skip_none=skip_none,
            )
            if not result.found:
                return default
            current = result.value
    if len(components) > MAX_OBJECT_ACCESS_DEPTH:
        return default
    return current


def set_nested_value(
    obj: Any,
    path: Any,
    value: Any,
    *,
    create_missing: bool = False,
    include_aliases: bool = True,
    strict: bool = True,
) -> bool:
    """Set a value at a nested object or mapping path."""

    components = normalize_access_path(path)
    if not components:
        if strict:
            raise ValueError("Nested access path cannot be empty.")
        return False
    if len(components) > MAX_OBJECT_ACCESS_DEPTH:
        if strict:
            raise ValueError("Nested access path exceeds the safety limit.")
        return False
    current = obj
    for component in components[:-1]:
        if isinstance(component, int):
            marker = MISSING_VALUE
            child = safe_getitem(current, component, marker)
            if child is marker:
                if strict:
                    raise IndexError(component)
                return False
            current = child
            continue
        result = access_object_value(
            current,
            component,
            include_aliases=include_aliases,
        )
        if result.found:
            current = result.value
            continue
        if not create_missing:
            if strict:
                raise KeyError(str(component))
            return False
        child = {}
        if not set_object_value(
            current,
            component,
            child,
            include_aliases=include_aliases,
            strict=strict,
        ):
            return False
        current = child

    final_component = components[-1]
    if isinstance(final_component, int):
        try:
            current[final_component] = value
            return True
        except Exception:
            if strict:
                raise
            return False
    return set_object_value(
        current,
        final_component,
        value,
        include_aliases=include_aliases,
        strict=strict,
    )


# 7.7. Generic object-to-mapping conversion
# -----------------------------------------------------------------------------

def iter_object_items(
    obj: Any,
    *,
    include_private: bool = False,
    include_properties: bool = False,
    fields_only: Optional[Iterable[str]] = None,
) -> Iterator[Tuple[str, Any]]:
    """Yield safe public key-value pairs from mappings, dataclasses or objects."""

    if obj is None:
        return
    selected = (
        tuple(str(name).strip() for name in fields_only if str(name).strip())
        if fields_only is not None
        else None
    )
    if isinstance(obj, Mapping):
        count = 0
        for key, value in obj.items():
            name = str(key)
            if not include_private and name.startswith("_"):
                continue
            if selected is not None and name not in selected:
                continue
            yield name, value
            count += 1
            if count >= MAX_OBJECT_ACCESS_ITEMS:
                break
        return
    if is_dataclass_instance(obj):
        count = 0
        for name in _cached_dataclass_field_names(type(obj)):
            if not include_private and name.startswith("_"):
                continue
            if selected is not None and name not in selected:
                continue
            marker = MISSING_VALUE
            value = safe_getattr(
                obj,
                name,
                marker,
                allow_private=include_private,
            )
            if value is marker:
                continue
            yield name, value
            count += 1
            if count >= MAX_OBJECT_ACCESS_ITEMS:
                break
        return
    if selected is not None:
        for name in selected[:MAX_OBJECT_ACCESS_ITEMS]:
            marker = MISSING_VALUE
            value = safe_getattr(
                obj,
                name,
                marker,
                allow_private=include_private,
            )
            if value is not marker:
                yield name, value
        return
    try:
        instance_data = vars(obj)
    except (TypeError, AttributeError):
        instance_data = {}
    count = 0
    for name, value in instance_data.items():
        if not include_private and str(name).startswith("_"):
            continue
        yield str(name), value
        count += 1
        if count >= MAX_OBJECT_ACCESS_ITEMS:
            return
    if not include_properties:
        return
    known = set(instance_data)
    for name, descriptor in inspect.getmembers(type(obj)):
        if name in known or (not include_private and name.startswith("_")):
            continue
        if not isinstance(descriptor, property):
            continue
        marker = MISSING_VALUE
        value = safe_getattr(
            obj,
            name,
            marker,
            allow_private=include_private,
        )
        if value is marker:
            continue
        yield name, value
        count += 1
        if count >= MAX_OBJECT_ACCESS_ITEMS:
            return


def object_to_mapping(
    obj: Any,
    *,
    fields_only: Optional[Iterable[str]] = None,
    include_private: bool = False,
    include_properties: bool = False,
    use_to_dict: bool = True,
    copy_values: bool = False,
) -> Dict[str, Any]:
    """Return a mutable string-keyed mapping from an arbitrary object."""

    if obj is None:
        return {}
    if use_to_dict and not isinstance(obj, Mapping):
        to_dict = safe_getattr(obj, "to_dict", None)
        if callable(to_dict):
            try:
                converted = to_dict()
            except Exception:
                converted = None
            if isinstance(converted, Mapping):
                data = {str(key): value for key, value in converted.items()}
                if fields_only is not None:
                    selected = {str(name) for name in fields_only}
                    data = {key: value for key, value in data.items() if key in selected}
                return copy.deepcopy(data) if copy_values else data
    data = dict(
        iter_object_items(
            obj,
            include_private=include_private,
            include_properties=include_properties,
            fields_only=fields_only,
        )
    )
    return copy.deepcopy(data) if copy_values else data


def ensure_mutable_mapping(
    value: Any,
    *,
    allow_none: bool = True,
    allow_object: bool = True,
    copy_values: bool = False,
) -> Dict[str, Any]:
    """Normalize a mapping-like value into a mutable dictionary."""

    if value is None:
        if allow_none:
            return {}
        raise TypeError("A mapping value is required.")
    if isinstance(value, Mapping):
        data = {str(key): item for key, item in value.items()}
    elif allow_object:
        data = object_to_mapping(value)
        if not data and not hasattr(value, "__dict__") and not is_dataclass_instance(value):
            raise TypeError("Value cannot be converted into a mapping.")
    else:
        raise TypeError("Expected a mapping value.")
    return copy.deepcopy(data) if copy_values else data


def merge_object_mappings(
    *values: Any,
    deep: bool = True,
    overwrite: bool = True,
    skip_none: bool = False,
) -> Dict[str, Any]:
    """Merge mappings or object representations in declaration order."""

    merged: Dict[str, Any] = {}
    for value in values:
        current = ensure_mutable_mapping(value, allow_none=True)
        for key, item in current.items():
            if skip_none and item is None:
                continue
            if (
                deep
                and key in merged
                and isinstance(merged[key], Mapping)
                and isinstance(item, Mapping)
            ):
                merged[key] = merge_object_mappings(
                    merged[key],
                    item,
                    deep=True,
                    overwrite=overwrite,
                    skip_none=skip_none,
                )
            elif overwrite or key not in merged:
                merged[key] = item
    return merged


# 7.8. Text, identifiers and scalar normalization
# -----------------------------------------------------------------------------

def normalize_text(
    value: Any,
    *,
    default: str = "",
    strip: bool = True,
    collapse_whitespace: bool = False,
    maximum_length: Optional[int] = MAX_OBJECT_TEXT_LENGTH,
) -> str:
    """Normalize arbitrary content into bounded text."""

    if value is None or is_missing_value(value):
        text = default
    elif isinstance(value, bytes):
        text = value.decode("utf-8", errors="replace")
    elif isinstance(value, bytearray):
        text = bytes(value).decode("utf-8", errors="replace")
    else:
        text = str(value)
    if strip:
        text = text.strip()
    if collapse_whitespace:
        text = " ".join(text.split())
    if maximum_length is not None:
        if maximum_length < 0:
            raise ValueError("maximum_length must be non-negative or None.")
        text = text[:maximum_length]
    return text


def normalize_optional_text(
    value: Any,
    *,
    collapse_whitespace: bool = False,
    maximum_length: Optional[int] = MAX_OBJECT_TEXT_LENGTH,
) -> Optional[str]:
    """Return normalized text or ``None`` for blank input."""

    text = normalize_text(
        value,
        collapse_whitespace=collapse_whitespace,
        maximum_length=maximum_length,
    )
    return text or None


def normalize_identifier(
    value: Any,
    *,
    default: str = DEFAULT_OBJECT_NAME,
    separator: str = DEFAULT_IDENTIFIER_SEPARATOR,
    lowercase: bool = False,
    maximum_length: int = MAX_IDENTIFIER_LENGTH,
    allow_empty: bool = False,
) -> str:
    """Normalize a stable human-readable identifier."""

    if not separator or len(separator) != 1:
        raise ValueError("Identifier separator must contain exactly one character.")
    text = normalize_text(
        value,
        default=default,
        collapse_whitespace=True,
        maximum_length=MAX_OBJECT_TEXT_LENGTH,
    )
    text = _IDENTIFIER_INVALID_PATTERN.sub(separator, text)
    text = _IDENTIFIER_SEPARATOR_PATTERN.sub(separator, text)
    text = text.strip("._-")
    if lowercase:
        text = text.lower()
    if not text and not allow_empty:
        fallback = normalize_text(default, collapse_whitespace=True)
        fallback = _IDENTIFIER_INVALID_PATTERN.sub(separator, fallback)
        fallback = _IDENTIFIER_SEPARATOR_PATTERN.sub(separator, fallback)
        text = fallback.strip("._-") or DEFAULT_OBJECT_NAME
    return text[:maximum_length]


def normalize_optional_identifier(
    value: Any,
    *,
    separator: str = DEFAULT_IDENTIFIER_SEPARATOR,
    lowercase: bool = False,
    maximum_length: int = MAX_IDENTIFIER_LENGTH,
) -> Optional[str]:
    """Return a normalized identifier or ``None`` for absent input."""

    text = normalize_optional_text(value, collapse_whitespace=True)
    if text is None:
        return None
    return normalize_identifier(
        text,
        default="",
        separator=separator,
        lowercase=lowercase,
        maximum_length=maximum_length,
        allow_empty=True,
    ) or None


def normalize_boolean(
    value: Any,
    *,
    default: Optional[bool] = None,
    strict: bool = True,
) -> Optional[bool]:
    """Normalize common boolean values."""

    if value is None or is_missing_value(value):
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        token = value.strip().lower()
        if token in _TRUE_CONFIG_TOKENS:
            return True
        if token in _FALSE_CONFIG_TOKENS:
            return False
    if strict:
        raise ValueError(f"Cannot interpret {value!r} as a boolean.")
    return default


def normalize_integer(
    value: Any,
    *,
    default: Optional[int] = None,
    minimum: Optional[int] = None,
    maximum: Optional[int] = None,
    strict: bool = True,
) -> Optional[int]:
    """Normalize an integer with optional bounds."""

    if value is None or is_missing_value(value):
        return default
    if isinstance(value, bool):
        if strict:
            raise ValueError("Boolean values are not accepted as integers.")
        return default
    try:
        result = int(value)
    except (TypeError, ValueError, OverflowError):
        if strict:
            raise ValueError(f"Cannot interpret {value!r} as an integer.")
        return default
    if isinstance(value, float) and not value.is_integer():
        if strict:
            raise ValueError(f"Cannot interpret {value!r} as an integer.")
        return default
    if minimum is not None and result < minimum:
        if strict:
            raise ValueError(f"Integer value must be at least {minimum}.")
        return default
    if maximum is not None and result > maximum:
        if strict:
            raise ValueError(f"Integer value must not exceed {maximum}.")
        return default
    return result


def normalize_float(
    value: Any,
    *,
    default: Optional[float] = None,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
    finite: bool = True,
    strict: bool = True,
) -> Optional[float]:
    """Normalize a floating-point value with optional bounds."""

    if value is None or is_missing_value(value):
        return default
    if isinstance(value, bool):
        if strict:
            raise ValueError("Boolean values are not accepted as numbers.")
        return default
    try:
        result = float(value)
    except (TypeError, ValueError, OverflowError):
        if strict:
            raise ValueError(f"Cannot interpret {value!r} as a number.")
        return default
    if finite and not math.isfinite(result):
        if strict:
            raise ValueError("Numeric value must be finite.")
        return default
    if minimum is not None and result < minimum:
        if strict:
            raise ValueError(f"Numeric value must be at least {minimum}.")
        return default
    if maximum is not None and result > maximum:
        if strict:
            raise ValueError(f"Numeric value must not exceed {maximum}.")
        return default
    return result


def normalize_path(
    value: Any,
    *,
    default: Optional[PathLike] = None,
    expand_user: bool = True,
    resolve: bool = False,
    strict: bool = True,
) -> Optional[Path]:
    """Normalize a path-like value without requiring it to exist."""

    selected = default if value is None or is_missing_value(value) else value
    if selected is None:
        return None
    try:
        path = Path(os.fspath(selected))
        if expand_user:
            path = path.expanduser()
        if resolve:
            path = path.resolve(strict=False)
        return path
    except (TypeError, ValueError, OSError):
        if strict:
            raise ValueError(f"Cannot interpret {selected!r} as a filesystem path.")
        return None


# 7.9. Collection normalization
# -----------------------------------------------------------------------------

def normalize_object_sequence(
    value: Any,
    *,
    allow_none: bool = True,
    treat_mapping_as_scalar: bool = True,
    maximum_items: int = MAX_OBJECT_ACCESS_ITEMS,
) -> List[Any]:
    """Normalize a scalar or iterable into a bounded mutable list."""

    if maximum_items < 0:
        raise ValueError("maximum_items must be non-negative.")
    if value is None or is_missing_value(value):
        if allow_none:
            return []
        raise TypeError("A collection value is required.")
    if isinstance(value, (str, bytes, bytearray)):
        return [value]
    if treat_mapping_as_scalar and isinstance(value, Mapping):
        return [value]
    try:
        iterator = iter(value)
    except TypeError:
        return [value]
    items: List[Any] = []
    for item in iterator:
        items.append(item)
        if len(items) >= maximum_items:
            break
    return items


def normalize_string_sequence(
    value: Any,
    *,
    lowercase: bool = False,
    unique: bool = True,
    skip_blank: bool = True,
    maximum_items: int = MAX_OBJECT_ACCESS_ITEMS,
) -> List[str]:
    """Normalize one or more values into bounded text entries."""

    values = normalize_object_sequence(value, maximum_items=maximum_items)
    result: List[str] = []
    for item in values:
        text = normalize_text(item)
        if lowercase:
            text = text.lower()
        if skip_blank and not text:
            continue
        result.append(text)
    if unique:
        result = list(unique_preserving_order(result))
    return result[:maximum_items]


def unique_preserving_order(
    values: Iterable[T],
    *,
    key: Optional[Callable[[T], Hashable]] = None,
) -> List[T]:
    """Return unique values while preserving first occurrence order."""

    result: List[T] = []
    seen_hashable: Set[Hashable] = set()
    seen_unhashable: Set[int] = set()
    for value in values:
        marker: Any
        if key is not None:
            marker = key(value)
        else:
            marker = value
        try:
            if marker in seen_hashable:
                continue
            seen_hashable.add(marker)
        except TypeError:
            object_id = id(marker)
            if object_id in seen_unhashable:
                continue
            seen_unhashable.add(object_id)
        result.append(value)
    return result


def flatten_object_sequence(
    value: Any,
    *,
    depth: int = 1,
    maximum_items: int = MAX_OBJECT_ACCESS_ITEMS,
) -> List[Any]:
    """Flatten nested non-string iterables to a controlled depth."""

    if depth < 0:
        raise ValueError("Flattening depth must be non-negative.")
    result: List[Any] = []

    def visit(item: Any, remaining: int) -> None:
        if len(result) >= maximum_items:
            return
        if remaining > 0 and is_nonstring_iterable(item):
            for child in item:
                visit(child, remaining - 1)
                if len(result) >= maximum_items:
                    return
        else:
            result.append(item)

    visit(value, depth)
    return result


def index_objects_by(
    values: Iterable[T],
    field_name: Any = "identifier",
    *,
    aliases: Iterable[Any] = (),
    fallback_to_name: bool = True,
    allow_duplicates: bool = False,
) -> Dict[str, T]:
    """Index objects by a canonical field with deterministic fallback keys."""

    result: Dict[str, T] = {}
    for position, value in enumerate(values):
        key_value = get_object_value(
            value,
            field_name,
            None,
            aliases=aliases,
            skip_none=True,
        )
        if key_value is None and fallback_to_name:
            key_value = get_object_value(value, "name", None, skip_none=True)
        key = normalize_optional_identifier(key_value)
        if key is None:
            key = f"item_{position + 1}"
        if key in result and not allow_duplicates:
            suffix = 2
            candidate = f"{key}_{suffix}"
            while candidate in result:
                suffix += 1
                candidate = f"{key}_{suffix}"
            key = candidate
        result[key] = value
    return result


# 7.10. Metadata, statistics and file normalization
# -----------------------------------------------------------------------------

def normalize_metadata_mapping(
    value: Any,
    *,
    copy_values: bool = False,
    skip_none: bool = False,
) -> Dict[str, Any]:
    """Normalize arbitrary metadata into a mutable string-keyed mapping."""

    data = ensure_mutable_mapping(
        value,
        allow_none=True,
        allow_object=True,
        copy_values=copy_values,
    )
    return {
        normalize_text(key): item
        for key, item in data.items()
        if normalize_text(key) and (not skip_none or item is not None)
    }


def normalize_statistics_mapping(
    value: Any,
    *,
    copy_values: bool = False,
    skip_none: bool = False,
) -> Dict[str, Any]:
    """Normalize statistics while preserving nested scientific values."""

    return normalize_metadata_mapping(
        value,
        copy_values=copy_values,
        skip_none=skip_none,
    )


def normalize_file_mapping(
    value: Any,
    *,
    convert_paths: bool = True,
    drop_empty: bool = False,
) -> Dict[str, Any]:
    """Normalize generated-file records without requiring file existence."""

    data = ensure_mutable_mapping(value, allow_none=True, allow_object=True)
    result: Dict[str, Any] = {}
    for key, item in data.items():
        normalized_key = normalize_identifier(
            key,
            default="file",
            lowercase=True,
        )
        if item in (None, ""):
            if not drop_empty:
                result[normalized_key] = None
            continue
        if convert_paths and is_path_like(item):
            normalized_path = normalize_path(item, strict=False)
            result[normalized_key] = normalized_path if normalized_path is not None else item
        else:
            result[normalized_key] = item
    return result


def merge_metadata_mappings(
    *values: Any,
    deep: bool = True,
    overwrite: bool = True,
    skip_none: bool = False,
) -> Dict[str, Any]:
    """Merge metadata mappings through the generic object converter."""

    normalized = [normalize_metadata_mapping(value) for value in values]
    return merge_object_mappings(
        *normalized,
        deep=deep,
        overwrite=overwrite,
        skip_none=skip_none,
    )


# 7.11. Object naming, identity and fingerprints
# -----------------------------------------------------------------------------

def resolve_object_name(
    obj: Any,
    *,
    default: str = DEFAULT_OBJECT_NAME,
    normalize: bool = False,
) -> str:
    """Resolve a human-readable object name through common aliases."""

    value = get_first_object_value(obj, IDENTITY_NAME_FIELDS, None, skip_none=True)
    if value is None and isinstance(obj, (str, Path)):
        value = Path(str(obj)).stem if str(obj).strip() else None
    text = normalize_text(
        value,
        default=default,
        collapse_whitespace=True,
        maximum_length=MAX_IDENTIFIER_LENGTH,
    )
    if not text:
        text = default
    return normalize_identifier(text, default=default) if normalize else text


def resolve_object_identifier(
    obj: Any,
    *,
    default: Optional[str] = None,
    fallback_to_name: bool = True,
) -> Optional[str]:
    """Resolve a stable identifier from common model and pose fields."""

    value = get_first_object_value(obj, IDENTITY_ID_FIELDS, None, skip_none=True)
    if value is None and fallback_to_name:
        value = get_first_object_value(obj, IDENTITY_NAME_FIELDS, None, skip_none=True)
    if value is None:
        value = default
    if isinstance(value, (list, tuple)):
        value = ".".join(normalize_text(item) for item in value)
    return normalize_optional_identifier(value)


def infer_object_kind(obj: Any) -> str:
    """Infer a conservative semantic kind from structure and runtime type."""

    if obj is None:
        return "none"
    if isinstance(obj, DockModel) or is_dock_model_like(obj):
        return "dock_model"
    type_token = _normalize_access_token(type(obj).__name__)
    if "session" in type_token:
        return "session"
    if "residue" in type_token:
        return "residue"
    if "atom" in type_token and "atomicstructure" not in type_token:
        return "atom"
    if any(token in type_token for token in ("structure", "model", "molecule")):
        return "model"
    if isinstance(obj, Mapping):
        return "mapping"
    if is_sequence_like(obj):
        return "collection"
    return "object"


def _object_fingerprint_from_components(
    obj: Any,
    *,
    name: str,
    identifier: Optional[str],
    kind: str,
    include_metadata: bool = False,
    metadata_keys: Iterable[str] = (),
) -> str:
    """Hash object identity components without resolving them repeatedly."""

    payload: Dict[str, Any] = {
        "type": type(obj).__name__ if obj is not None else "NoneType",
        "module": type(obj).__module__ if obj is not None else "builtins",
        "name": name,
        "identifier": identifier,
        "kind": kind,
    }
    if include_metadata:
        metadata = get_object_value(obj, "metadata", {}, skip_none=True)
        normalized = normalize_metadata_mapping(metadata)
        selected_keys = normalize_string_sequence(metadata_keys)
        if selected_keys:
            normalized = {
                key: normalized[key]
                for key in selected_keys
                if key in normalized
            }
        payload["metadata"] = _result_value_to_data(normalized)
    encoded = json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        default=str,
    ).encode("utf-8")
    return sha256(encoded).hexdigest()


def stable_object_fingerprint(
    obj: Any,
    *,
    include_metadata: bool = False,
    metadata_keys: Iterable[str] = (),
) -> str:
    """Return a deterministic descriptive fingerprint for orchestration caches."""

    return _object_fingerprint_from_components(
        obj,
        name=resolve_object_name(obj),
        identifier=resolve_object_identifier(obj),
        kind=infer_object_kind(obj),
        include_metadata=include_metadata,
        metadata_keys=metadata_keys,
    )


def describe_object(obj: Any) -> ObjectIdentity:
    """Return a stable structured identity for any supported input object."""

    type_name = type(obj).__name__ if obj is not None else "NoneType"
    module_name = type(obj).__module__ if obj is not None else "builtins"
    name = resolve_object_name(obj)
    identifier = resolve_object_identifier(obj)
    kind = infer_object_kind(obj)
    return ObjectIdentity(
        name=name,
        identifier=identifier,
        type_name=type_name,
        module_name=module_name,
        kind=kind,
        fingerprint=_object_fingerprint_from_components(
            obj,
            name=name,
            identifier=identifier,
            kind=kind,
        ),
    )


# 7.12. Safe generic data conversion and copying
# -----------------------------------------------------------------------------

def to_json_compatible(
    value: Any,
    *,
    include_objects: bool = False,
    maximum_depth: int = MAX_OBJECT_ACCESS_DEPTH,
) -> Any:
    """Convert arbitrary orchestration data into JSON-compatible content."""

    if maximum_depth < 0:
        raise ValueError("maximum_depth must be non-negative.")

    def convert(item: Any, depth: int, seen: Set[int]) -> Any:
        if depth > maximum_depth:
            return "<maximum-depth>"
        if is_missing_value(item):
            return None
        if item is None or isinstance(item, (str, int, bool)):
            return item
        if isinstance(item, float):
            return item if math.isfinite(item) else str(item)
        if isinstance(item, Enum):
            return convert(item.value, depth + 1, seen)
        if isinstance(item, (Path, os.PathLike)):
            return os.fspath(item)
        if isinstance(item, (datetime, date)):
            return _normalize_timestamp(item)
        if isinstance(item, bytes):
            return item.decode("utf-8", errors="replace")
        if isinstance(item, bytearray):
            return bytes(item).decode("utf-8", errors="replace")

        object_id = id(item)
        if object_id in seen:
            return "<recursive-reference>"

        if isinstance(item, Mapping):
            seen.add(object_id)
            converted = {
                str(key): convert(child, depth + 1, seen)
                for key, child in list(item.items())[:MAX_OBJECT_ACCESS_ITEMS]
            }
            seen.discard(object_id)
            return converted
        if is_nonstring_iterable(item):
            seen.add(object_id)
            converted = [
                convert(child, depth + 1, seen)
                for child in normalize_object_sequence(
                    item,
                    maximum_items=MAX_OBJECT_ACCESS_ITEMS,
                )
            ]
            seen.discard(object_id)
            return converted

        to_dict = safe_getattr(item, "to_dict", None)
        if callable(to_dict):
            try:
                converted_value = to_dict()
            except Exception:
                converted_value = MISSING_VALUE
            if not is_missing_value(converted_value):
                seen.add(object_id)
                converted = convert(converted_value, depth + 1, seen)
                seen.discard(object_id)
                return converted
        if is_dataclass_instance(item):
            seen.add(object_id)
            converted = convert(object_to_mapping(item), depth + 1, seen)
            seen.discard(object_id)
            return converted
        if include_objects:
            return item
        return describe_object(item).to_dict()

    return convert(value, 0, set())


def safe_copy_object(
    value: T,
    *,
    deep: bool = True,
    fallback_to_original: bool = True,
) -> T:
    """Copy an object while allowing opaque ChimeraX objects to remain shared."""

    try:
        return copy.deepcopy(value) if deep else copy.copy(value)
    except Exception:
        if fallback_to_original:
            return value
        raise


# 7.13. Object-access validation
# -----------------------------------------------------------------------------

def validate_generic_object_access_conventions() -> Dict[str, Any]:
    """Validate the generic access and normalization layer."""

    failures: List[str] = []

    mapping = {
        "displayName": "Pose Alpha",
        "modelId": "#2.1",
        "metaData": {"source": "synthetic"},
        "nested": {"items": [{"value": 7}]},
    }
    namespace = SimpleNamespace(
        name="Pose Beta",
        id_string="#3.2",
        metadata={"source": "namespace"},
    )

    if get_object_value(mapping, "name") != "Pose Alpha":
        failures.append("Mapping aliases did not resolve the object name.")
    if get_object_value(namespace, "identifier") != "#3.2":
        failures.append("Attribute aliases did not resolve the identifier.")
    if get_nested_value(mapping, "nested.items.0.value") != 7:
        failures.append("Nested access did not resolve a mixed mapping/list path.")

    mutable: Dict[str, Any] = {}
    if not set_nested_value(mutable, "analysis.metadata.status", "ready", create_missing=True):
        failures.append("Nested mapping creation failed.")
    if get_nested_value(mutable, "analysis.metadata.status") != "ready":
        failures.append("Nested mapping assignment produced an unexpected value.")

    normalized_identifier = normalize_identifier(" Pose Alpha / #2 ")
    if normalized_identifier != "Pose_Alpha_2":
        failures.append("Identifier normalization produced an unexpected value.")
    if normalize_boolean("enabled") is not True:
        failures.append("Boolean normalization did not recognize an enabled token.")
    if normalize_integer("4", minimum=1) != 4:
        failures.append("Integer normalization produced an unexpected value.")
    if normalize_float("2.5", minimum=0.0) != 2.5:
        failures.append("Float normalization produced an unexpected value.")

    sequence = normalize_object_sequence((1, 2, 3))
    if sequence != [1, 2, 3]:
        failures.append("Sequence normalization did not preserve values.")
    if unique_preserving_order(["a", "b", "a"]) != ["a", "b"]:
        failures.append("Ordered deduplication produced an unexpected result.")

    identity = describe_object(namespace)
    if identity.name != "Pose Beta" or identity.identifier != "3_2":
        failures.append("Object identity resolution produced unexpected fields.")
    if len(identity.fingerprint or "") != 64:
        failures.append("Object fingerprint must be a SHA-256 hexadecimal digest.")

    recursive: Dict[str, Any] = {}
    recursive["self"] = recursive
    converted = to_json_compatible(recursive)
    if converted.get("self") != "<recursive-reference>":
        failures.append("Recursive-reference protection did not activate.")

    public_aliases = get_object_field_aliases("hydrogen_bonds")
    if "hbonds" not in public_aliases:
        failures.append("Canonical object aliases do not include hbonds.")

    if failures:
        raise RuntimeError(
            "Generic object-access convention validation failed: "
            + " ".join(failures)
        )

    return {
        "valid": True,
        "field_groups": len(OBJECT_FIELD_ALIASES),
        "validated_cases": 15,
        "maximum_depth": MAX_OBJECT_ACCESS_DEPTH,
        "maximum_items": MAX_OBJECT_ACCESS_ITEMS,
    }


