# 8.2. Input and model-discovery enums
# -----------------------------------------------------------------------------

class InputSourceKind(str, Enum):
    """Canonical category assigned to one analysis input source."""

    UNKNOWN = INPUT_SOURCE_UNKNOWN
    REQUEST = INPUT_SOURCE_REQUEST
    CONTEXT = INPUT_SOURCE_CONTEXT
    DOCK_MODEL = INPUT_SOURCE_DOCK_MODEL
    DOCK_MODELS = INPUT_SOURCE_DOCK_MODELS
    SESSION = INPUT_SOURCE_SESSION
    MODEL = INPUT_SOURCE_MODEL
    MODELS = INPUT_SOURCE_MODELS
    RECEPTOR_POSES = INPUT_SOURCE_RECEPTOR_POSES
    BATCH = INPUT_SOURCE_BATCH
    MAPPING = INPUT_SOURCE_MAPPING


class ModelRole(str, Enum):
    """Role assigned to a model during discovery."""

    RECEPTOR = MODEL_ROLE_RECEPTOR
    POSE = MODEL_ROLE_POSE
    LIGAND = MODEL_ROLE_LIGAND
    UNKNOWN = MODEL_ROLE_UNKNOWN
    IGNORED = MODEL_ROLE_IGNORED


class DiscoveryConfidence(str, Enum):
    """Confidence associated with a discovered role assignment."""

    EXPLICIT = DISCOVERY_CONFIDENCE_EXPLICIT
    HIGH = DISCOVERY_CONFIDENCE_HIGH
    MODERATE = DISCOVERY_CONFIDENCE_MODERATE
    LOW = DISCOVERY_CONFIDENCE_LOW
    UNKNOWN = DISCOVERY_CONFIDENCE_UNKNOWN


# 8.3. Canonicalization helpers
# -----------------------------------------------------------------------------

def canonicalize_input_source_kind(value: Any) -> InputSourceKind:
    """Return a canonical input-source category."""

    if isinstance(value, InputSourceKind):
        return value
    token = _normalize_convention_token(value, field_name="input source kind")
    aliases = {
        "unknown": InputSourceKind.UNKNOWN,
        "request": InputSourceKind.REQUEST,
        "analysis_request": InputSourceKind.REQUEST,
        "context": InputSourceKind.CONTEXT,
        "analysis_context": InputSourceKind.CONTEXT,
        "dock_model": InputSourceKind.DOCK_MODEL,
        "dockmodel": InputSourceKind.DOCK_MODEL,
        "dock_models": InputSourceKind.DOCK_MODELS,
        "dockmodels": InputSourceKind.DOCK_MODELS,
        "session": InputSourceKind.SESSION,
        "chimerax": InputSourceKind.SESSION,
        "chimerax_session": InputSourceKind.SESSION,
        "model": InputSourceKind.MODEL,
        "models": InputSourceKind.MODELS,
        "model_collection": InputSourceKind.MODELS,
        "receptor_poses": InputSourceKind.RECEPTOR_POSES,
        "receptor_pose": InputSourceKind.RECEPTOR_POSES,
        "batch": InputSourceKind.BATCH,
        "requests": InputSourceKind.BATCH,
        "mapping": InputSourceKind.MAPPING,
    }
    try:
        return aliases[token]
    except KeyError as exc:
        supported = ", ".join(INPUT_SOURCE_KINDS)
        raise ValueError(
            f"Unknown input source kind {value!r}. Supported values: {supported}."
        ) from exc


def canonicalize_model_role(value: Any) -> ModelRole:
    """Return a canonical discovered-model role."""

    if isinstance(value, ModelRole):
        return value
    token = _normalize_convention_token(value, field_name="model role")
    aliases = {
        "receptor": ModelRole.RECEPTOR,
        "protein": ModelRole.RECEPTOR,
        "target": ModelRole.RECEPTOR,
        "pose": ModelRole.POSE,
        "dock_pose": ModelRole.POSE,
        "ligand_pose": ModelRole.POSE,
        "ligand": ModelRole.LIGAND,
        "compound": ModelRole.LIGAND,
        "unknown": ModelRole.UNKNOWN,
        "unclassified": ModelRole.UNKNOWN,
        "ignored": ModelRole.IGNORED,
        "excluded": ModelRole.IGNORED,
    }
    try:
        return aliases[token]
    except KeyError as exc:
        supported = ", ".join(MODEL_ROLES)
        raise ValueError(
            f"Unknown model role {value!r}. Supported values: {supported}."
        ) from exc


def canonicalize_discovery_confidence(value: Any) -> DiscoveryConfidence:
    """Return a canonical discovery-confidence level."""

    if isinstance(value, DiscoveryConfidence):
        return value
    token = _normalize_convention_token(value, field_name="discovery confidence")
    aliases = {
        "explicit": DiscoveryConfidence.EXPLICIT,
        "certain": DiscoveryConfidence.EXPLICIT,
        "high": DiscoveryConfidence.HIGH,
        "moderate": DiscoveryConfidence.MODERATE,
        "medium": DiscoveryConfidence.MODERATE,
        "low": DiscoveryConfidence.LOW,
        "unknown": DiscoveryConfidence.UNKNOWN,
    }
    try:
        return aliases[token]
    except KeyError as exc:
        supported = ", ".join(DISCOVERY_CONFIDENCE_LEVELS)
        raise ValueError(
            f"Unknown discovery confidence {value!r}. Supported values: {supported}."
        ) from exc


def get_input_mapping_value(
    mapping: Mapping[str, Any],
    field_name: Any,
    default: Any = MISSING_VALUE,
) -> Any:
    """Return one input-mapping field using its canonical aliases."""

    canonical = str(field_name).strip()
    aliases = INPUT_MAPPING_ALIASES.get(canonical, (canonical,))
    normalized_keys = {
        _normalize_access_token(key): key
        for key in mapping
        if str(key).strip()
    }
    for alias in aliases:
        source_key = normalized_keys.get(_normalize_access_token(alias))
        if source_key is not None:
            return mapping[source_key]
    return default


# 8.4. Discovery records
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class ModelDiscoveryRecord:
    """Describe one model inspected during input discovery."""

    model: Any
    role: Union[ModelRole, str] = ModelRole.UNKNOWN
    confidence: Union[DiscoveryConfidence, str] = DiscoveryConfidence.UNKNOWN
    index: int = 0
    name: Optional[str] = None
    identifier: Optional[str] = None
    atomspec: Optional[str] = None
    classification: Optional[str] = None
    atom_count: Optional[int] = None
    residue_count: Optional[int] = None
    protein_residue_count: Optional[int] = None
    ligand: Any = None
    source: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "role", canonicalize_model_role(self.role))
        object.__setattr__(
            self,
            "confidence",
            canonicalize_discovery_confidence(self.confidence),
        )
        object.__setattr__(self, "index", max(0, int(self.index)))
        identity = describe_object(self.model)
        object.__setattr__(
            self,
            "name",
            normalize_text(self.name, default=identity.name),
        )
        object.__setattr__(
            self,
            "identifier",
            normalize_optional_identifier(
                self.identifier if self.identifier is not None else identity.identifier
            ),
        )
        object.__setattr__(
            self,
            "atomspec",
            normalize_optional_text(self.atomspec),
        )
        object.__setattr__(
            self,
            "classification",
            normalize_optional_text(self.classification),
        )
        for field_name in (
            "atom_count",
            "residue_count",
            "protein_residue_count",
        ):
            value = getattr(self, field_name)
            if value is not None:
                object.__setattr__(
                    self,
                    field_name,
                    normalize_integer(value, minimum=0),
                )
        object.__setattr__(
            self,
            "source",
            normalize_optional_text(self.source),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )

    @property
    def display_name(self) -> str:
        """Return a concise display label."""

        if self.identifier:
            return f"{self.name} [{self.identifier}]"
        return self.name or DEFAULT_MODEL_NAME

    @property
    def is_receptor(self) -> bool:
        """Return whether the model is assigned as receptor."""

        return self.role is ModelRole.RECEPTOR

    @property
    def is_pose(self) -> bool:
        """Return whether the model is assigned as docking pose."""

        return self.role is ModelRole.POSE

    def to_dict(self, *, include_object: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe representation."""

        data: Dict[str, Any] = {
            "index": self.index,
            "name": self.name,
            "identifier": self.identifier,
            "atomspec": self.atomspec,
            "role": self.role.value,
            "confidence": self.confidence.value,
            "classification": self.classification,
            "atom_count": self.atom_count,
            "residue_count": self.residue_count,
            "protein_residue_count": self.protein_residue_count,
            "source": self.source,
            "has_ligand": self.ligand is not None,
            "metadata": to_json_compatible(self.metadata),
        }
        if include_object:
            data["model"] = self.model
            data["ligand"] = self.ligand
        else:
            data["model"] = describe_object(self.model).to_dict()
            data["ligand"] = (
                describe_object(self.ligand).to_dict()
                if self.ligand is not None
                else None
            )
        return data


@dataclass
class ModelDiscoveryResult:
    """Collect model-discovery inputs, assignments and diagnostics."""

    source: Any = None
    source_kind: Union[InputSourceKind, str] = InputSourceKind.UNKNOWN
    session: Any = None
    models: List[Any] = field(default_factory=list)
    records: List[ModelDiscoveryRecord] = field(default_factory=list)
    receptor: Any = None
    poses: List[Any] = field(default_factory=list)
    ligands: List[Any] = field(default_factory=list)
    dock_models: List[Any] = field(default_factory=list)
    batch_requests: List[AnalysisRequest] = field(default_factory=list)
    mode: str = ANALYSIS_MODE_AUTO
    warnings: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.source_kind = canonicalize_input_source_kind(self.source_kind)
        self.models = unique_preserving_order(
            normalize_object_sequence(self.models, maximum_items=MAX_DISCOVERY_MODELS),
            key=id,
        )
        normalized_records: List[ModelDiscoveryRecord] = []
        for index, record in enumerate(self.records):
            if isinstance(record, ModelDiscoveryRecord):
                normalized_records.append(record)
            elif isinstance(record, Mapping):
                normalized_records.append(ModelDiscoveryRecord(**dict(record)))
            else:
                normalized_records.append(
                    ModelDiscoveryRecord(model=record, index=index)
                )
        self.records = normalized_records
        self.poses = unique_preserving_order(
            normalize_object_sequence(self.poses, maximum_items=MAX_DISCOVERY_MODELS),
            key=id,
        )
        self.ligands = normalize_object_sequence(
            self.ligands,
            maximum_items=MAX_DISCOVERY_MODELS,
        )
        self.dock_models = unique_preserving_order(
            normalize_object_sequence(
                self.dock_models,
                maximum_items=MAX_DISCOVERY_MODELS,
            ),
            key=id,
        )
        normalized_requests: List[AnalysisRequest] = []
        for request in normalize_object_sequence(
            self.batch_requests,
            maximum_items=MAX_BATCH_REQUESTS,
        ):
            normalized_requests.append(coerce_analysis_request(request))
        self.batch_requests = normalized_requests
        self.mode = canonicalize_analysis_mode(self.mode)
        self.warnings = normalize_string_sequence(self.warnings)
        self.metadata = normalize_metadata_mapping(self.metadata)

    @property
    def model_count(self) -> int:
        """Return the number of inspected molecular models."""

        return len(self.models)

    @property
    def pose_count(self) -> int:
        """Return the number of resolved poses or prepared models."""

        return max(len(self.poses), len(self.dock_models))

    @property
    def batch_count(self) -> int:
        """Return the number of resolved batch requests."""

        return len(self.batch_requests)

    @property
    def has_molecular_input(self) -> bool:
        """Return whether molecular input was resolved."""

        return bool(self.receptor is not None or self.poses or self.dock_models)

    @property
    def is_complete(self) -> bool:
        """Return whether the result is sufficient for the inferred mode."""

        if self.mode == ANALYSIS_MODE_BATCH:
            return bool(self.batch_requests)
        if self.dock_models:
            return True
        return self.receptor is not None and bool(self.poses)

    def records_for_role(self, role: Any) -> Tuple[ModelDiscoveryRecord, ...]:
        """Return discovery records assigned to one role."""

        canonical = canonicalize_model_role(role)
        return tuple(record for record in self.records if record.role is canonical)

    def record_for_model(self, model: Any) -> Optional[ModelDiscoveryRecord]:
        """Return the record associated with a model by identity."""

        for record in self.records:
            if record.model is model:
                return record
        return None

    def summary(self) -> Dict[str, Any]:
        """Return compact discovery statistics."""

        role_counts = Counter(record.role.value for record in self.records)
        return {
            "source_kind": self.source_kind.value,
            "mode": self.mode,
            "model_count": self.model_count,
            "record_count": len(self.records),
            "pose_count": self.pose_count,
            "dock_model_count": len(self.dock_models),
            "ligand_count": len(self.ligands),
            "batch_count": self.batch_count,
            "receptor_resolved": self.receptor is not None,
            "complete": self.is_complete,
            "role_counts": dict(role_counts),
            "warning_count": len(self.warnings),
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe dictionary representation."""

        def encode(value: Any) -> Any:
            if include_objects:
                return value
            if isinstance(value, Sequence) and not isinstance(
                value,
                (str, bytes, bytearray),
            ):
                return [describe_object(item).to_dict() for item in value]
            return describe_object(value).to_dict() if value is not None else None

        return {
            "source_kind": self.source_kind.value,
            "mode": self.mode,
            "session": encode(self.session),
            "receptor": encode(self.receptor),
            "models": encode(self.models),
            "poses": encode(self.poses),
            "ligands": encode(self.ligands),
            "dock_models": encode(self.dock_models),
            "batch_requests": [
                request.to_dict(include_objects=include_objects)
                for request in self.batch_requests
            ],
            "records": [
                record.to_dict(include_object=include_objects)
                for record in self.records
            ],
            "warnings": list(self.warnings),
            "metadata": to_json_compatible(self.metadata),
            "summary": self.summary(),
        }


@dataclass(frozen=True)
class ResolvedAnalysisInput:
    """Normalized input passed from discovery to model preparation."""

    request: AnalysisRequest
    source_kind: Union[InputSourceKind, str]
    mode: str
    session: Any = None
    receptor: Any = None
    poses: Sequence[Any] = field(default_factory=tuple)
    ligands: Sequence[Any] = field(default_factory=tuple)
    dock_models: Sequence[Any] = field(default_factory=tuple)
    batch_requests: Sequence[AnalysisRequest] = field(default_factory=tuple)
    discovery: Optional[ModelDiscoveryResult] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "source_kind",
            canonicalize_input_source_kind(self.source_kind),
        )
        object.__setattr__(self, "mode", canonicalize_analysis_mode(self.mode))
        object.__setattr__(
            self,
            "poses",
            tuple(
                unique_preserving_order(
                    normalize_object_sequence(
                        self.poses,
                        maximum_items=MAX_DISCOVERY_MODELS,
                    ),
                    key=id,
                )
            ),
        )
        object.__setattr__(
            self,
            "ligands",
            tuple(
                normalize_object_sequence(
                    self.ligands,
                    maximum_items=MAX_DISCOVERY_MODELS,
                )
            ),
        )
        object.__setattr__(
            self,
            "dock_models",
            tuple(
                unique_preserving_order(
                    normalize_object_sequence(
                        self.dock_models,
                        maximum_items=MAX_DISCOVERY_MODELS,
                    ),
                    key=id,
                )
            ),
        )
        object.__setattr__(
            self,
            "batch_requests",
            tuple(coerce_analysis_request(item) for item in self.batch_requests),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )

    @property
    def pose_count(self) -> int:
        """Return the resolved pose count."""

        return max(len(self.poses), len(self.dock_models))

    @property
    def item_count(self) -> int:
        """Return the primary work-item count."""

        if self.mode == ANALYSIS_MODE_BATCH:
            return len(self.batch_requests)
        return self.pose_count

    @property
    def ready_for_preparation(self) -> bool:
        """Return whether model preparation can proceed."""

        if self.mode == ANALYSIS_MODE_BATCH:
            return bool(self.batch_requests)
        if self.dock_models:
            return True
        return self.receptor is not None and bool(self.poses)

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe representation."""

        def encode_many(values: Sequence[Any]) -> Any:
            if include_objects:
                return list(values)
            return [describe_object(item).to_dict() for item in values]

        return {
            "request_id": self.request.request_id,
            "source_kind": self.source_kind.value,
            "mode": self.mode,
            "session": (
                self.session
                if include_objects
                else (
                    describe_object(self.session).to_dict()
                    if self.session is not None
                    else None
                )
            ),
            "receptor": (
                self.receptor
                if include_objects
                else (
                    describe_object(self.receptor).to_dict()
                    if self.receptor is not None
                    else None
                )
            ),
            "poses": encode_many(self.poses),
            "ligands": encode_many(self.ligands),
            "dock_models": encode_many(self.dock_models),
            "batch_requests": [
                request.to_dict(include_objects=include_objects)
                for request in self.batch_requests
            ],
            "ready_for_preparation": self.ready_for_preparation,
            "metadata": to_json_compatible(self.metadata),
            "discovery": (
                self.discovery.to_dict(include_objects=include_objects)
                if self.discovery is not None
                else None
            ),
        }


# 8.5. Input-shape inspection
# -----------------------------------------------------------------------------

def is_analysis_request_like(value: Any) -> bool:
    """Return whether a value can represent one analysis request."""

    if isinstance(value, AnalysisRequest):
        return True
    if isinstance(value, AnalysisContext):
        return True
    if not isinstance(value, Mapping):
        return False
    request_value = get_input_mapping_value(value, "request")
    if request_value is not MISSING_VALUE:
        return True
    meaningful_fields = (
        "input_data",
        "session",
        "receptor",
        "poses",
        "pose",
        "dock_models",
        "models",
        "mode",
    )
    return any(
        get_input_mapping_value(value, field_name) is not MISSING_VALUE
        for field_name in meaningful_fields
    )


def is_session_like(value: Any) -> bool:
    """Return whether a value exposes ChimeraX-like session model access."""

    if value is None or isinstance(value, (Mapping, DockModel, AnalysisRequest)):
        return False
    models = getattr(value, "models", None)
    if models is None:
        return False
    return bool(
        callable(getattr(models, "list", None))
        or callable(getattr(models, "list_models", None))
        or is_nonstring_iterable(models)
    )


def is_atomic_model_like(value: Any) -> bool:
    """Return whether a value resembles an atomic molecular model."""

    if value is None or is_dock_model_like(value):
        return False
    utils_module = load_analysis_module("utils", required=False)
    predicate = getattr(utils_module, "is_atomic_model", None) if utils_module else None
    if callable(predicate):
        try:
            return bool(predicate(value))
        except Exception:
            pass
    atoms = get_object_value(value, "atoms", default=MISSING_VALUE)
    residues = get_object_value(value, "residues", default=MISSING_VALUE)
    return atoms is not MISSING_VALUE or residues is not MISSING_VALUE


def is_model_collection_like(value: Any) -> bool:
    """Return whether a value is a collection of molecular models."""

    if not is_sequence_like(value):
        return False
    items = normalize_object_sequence(value, maximum_items=16)
    if not items:
        return False
    return all(is_atomic_model_like(item) for item in items)


def is_dock_model_collection_like(value: Any) -> bool:
    """Return whether a value is a non-empty DockModel-like collection."""

    if not is_sequence_like(value):
        return False
    items = normalize_object_sequence(value, maximum_items=16)
    return bool(items) and all(is_dock_model_like(item) for item in items)


def is_batch_request_collection(value: Any) -> bool:
    """Return whether a value is a collection of independent requests."""

    if not is_sequence_like(value):
        return False
    items = normalize_object_sequence(value, maximum_items=16)
    if len(items) < 2:
        return False
    return all(
        isinstance(item, (AnalysisRequest, AnalysisContext))
        or (isinstance(item, Mapping) and is_analysis_request_like(item))
        for item in items
    )


def classify_analysis_input(value: Any) -> InputSourceKind:
    """Classify an arbitrary top-level analysis input."""

    if value is None:
        return InputSourceKind.UNKNOWN
    if isinstance(value, AnalysisContext):
        return InputSourceKind.CONTEXT
    if isinstance(value, AnalysisRequest):
        return InputSourceKind.REQUEST
    if is_dock_model_like(value):
        return InputSourceKind.DOCK_MODEL
    if is_session_like(value):
        return InputSourceKind.SESSION
    if isinstance(value, Mapping):
        batch = get_input_mapping_value(value, "batch")
        if batch is not MISSING_VALUE:
            return InputSourceKind.BATCH
        return InputSourceKind.MAPPING
    if is_dock_model_collection_like(value):
        return InputSourceKind.DOCK_MODELS
    if is_batch_request_collection(value):
        return InputSourceKind.BATCH
    if is_model_collection_like(value):
        return InputSourceKind.MODELS
    if is_atomic_model_like(value):
        return InputSourceKind.MODEL
    if is_sequence_like(value):
        items = normalize_object_sequence(value, maximum_items=3)
        if len(items) == 2 and is_atomic_model_like(items[0]):
            return InputSourceKind.RECEPTOR_POSES
    return InputSourceKind.UNKNOWN


# 8.6. Model-source extraction
# -----------------------------------------------------------------------------

def get_discovery_options(config: AnalysisConfigLike = None) -> Dict[str, Any]:
    """Return normalized input-discovery options from analysis configuration."""

    normalized = coerce_analysis_config(config)
    stage_config = normalized.stage_config(STAGE_INPUT_RESOLUTION)
    parameters = dict(stage_config.parameters)
    return {
        "strict": normalize_boolean(
            parameters.get(
                "strict_model_discovery",
                normalized.runtime.is_strict,
            ),
            default=DEFAULT_STRICT_MODEL_DISCOVERY,
        ),
        "include_unknown_poses": normalize_boolean(
            parameters.get(
                "include_unknown_poses",
                DEFAULT_INCLUDE_UNKNOWN_POSES,
            ),
            default=DEFAULT_INCLUDE_UNKNOWN_POSES,
        ),
        "allow_empty": normalize_boolean(
            parameters.get("allow_empty_input", DEFAULT_ALLOW_EMPTY_INPUT),
            default=DEFAULT_ALLOW_EMPTY_INPUT,
        ),
        "resolve_references": normalize_boolean(
            parameters.get(
                "resolve_model_references",
                DEFAULT_RESOLVE_MODEL_REFERENCES,
            ),
            default=DEFAULT_RESOLVE_MODEL_REFERENCES,
        ),
        "discover_ligands": normalize_boolean(
            parameters.get("discover_ligands", DEFAULT_DISCOVER_LIGANDS),
            default=DEFAULT_DISCOVER_LIGANDS,
        ),
    }


def get_session_models(
    session: Any,
    *,
    atomic_only: bool = True,
    strict: bool = True,
) -> List[Any]:
    """Return bounded models from a ChimeraX-like session."""

    if session is None:
        if strict:
            raise AnalysisInputError(
                "A session is required for session model discovery.",
                stage=STAGE_INPUT_RESOLUTION,
            )
        return []

    utils_module = load_analysis_module("utils", required=False)
    if atomic_only and utils_module is not None:
        getter = getattr(utils_module, "get_atomic_models", None)
        if callable(getter):
            try:
                models = list(getter(session))
                return unique_preserving_order(
                    models[:MAX_DISCOVERY_MODELS],
                    key=id,
                )
            except Exception as exc:
                if strict:
                    raise AnalysisInputError(
                        "Atomic models could not be read from the session.",
                        stage=STAGE_INPUT_RESOLUTION,
                        cause=exc,
                    ) from exc

    manager = getattr(session, "models", None)
    raw_models: Any = ()
    if manager is not None:
        for method_name in ("list", "list_models"):
            method = getattr(manager, method_name, None)
            if callable(method):
                try:
                    raw_models = method()
                    break
                except TypeError:
                    continue
        else:
            raw_models = manager

    models = normalize_object_sequence(raw_models, maximum_items=MAX_DISCOVERY_MODELS)
    if atomic_only:
        models = [model for model in models if is_atomic_model_like(model)]
    if not models and strict:
        raise AnalysisInputError(
            "No compatible molecular models were found in the session.",
            stage=STAGE_INPUT_RESOLUTION,
        )
    return unique_preserving_order(models, key=id)


def normalize_model_collection(
    value: Any,
    *,
    atomic_only: bool = True,
    maximum: int = MAX_DISCOVERY_MODELS,
) -> List[Any]:
    """Return a bounded, identity-deduplicated model list."""

    models = normalize_object_sequence(value, maximum_items=maximum)
    if atomic_only:
        models = [model for model in models if is_atomic_model_like(model)]
    return unique_preserving_order(models, key=id)


def resolve_model_reference(
    models: Sequence[Any],
    reference: Any,
    *,
    strict: bool = True,
) -> Any:
    """Resolve an explicit model reference against a model collection."""

    if reference is None:
        return None
    if any(reference is model for model in models):
        return reference
    utils_module = load_analysis_module("utils", required=False)
    resolver = getattr(utils_module, "resolve_model_reference", None) if utils_module else None
    if callable(resolver):
        try:
            resolved = resolver(list(models), reference)
            if resolved is not None:
                return resolved
        except Exception as exc:
            if strict:
                raise AnalysisInputError(
                    f"Model reference {reference!r} could not be resolved.",
                    stage=STAGE_INPUT_RESOLUTION,
                    cause=exc,
                ) from exc
            return None
    if isinstance(reference, (str, int, tuple)):
        target = str(reference).strip().lstrip("#")
        for model in models:
            identity = describe_object(model)
            candidates = {
                identity.name,
                identity.identifier or "",
                str(get_object_value(model, "atomspec", default="")).lstrip("#"),
            }
            if target in candidates:
                return model
    if strict:
        raise AnalysisInputError(
            f"Model reference {reference!r} did not match an available model.",
            stage=STAGE_INPUT_RESOLUTION,
        )
    return None


def resolve_model_references(
    models: Sequence[Any],
    references: Any,
    *,
    strict: bool = True,
) -> List[Any]:
    """Resolve multiple model references while preserving order."""

    resolved: List[Any] = []
    for reference in normalize_object_sequence(
        references,
        maximum_items=MAX_DISCOVERY_MODELS,
    ):
        model = resolve_model_reference(models, reference, strict=strict)
        if model is not None:
            resolved.append(model)
    return unique_preserving_order(resolved, key=id)


# 8.7. Model description and role assignment
# -----------------------------------------------------------------------------

def describe_discovered_model(
    model: Any,
    *,
    index: int = 0,
    role: Any = ModelRole.UNKNOWN,
    confidence: Any = DiscoveryConfidence.UNKNOWN,
    ligand: Any = None,
    source: Optional[str] = None,
) -> ModelDiscoveryRecord:
    """Build one record using the authoritative utilities when available."""

    utils_module = load_analysis_module("utils", required=False)
    description: Dict[str, Any] = {}
    if utils_module is not None:
        descriptor = getattr(utils_module, "describe_model", None)
        if callable(descriptor):
            try:
                raw = descriptor(model)
                if isinstance(raw, Mapping):
                    description.update(raw)
            except Exception:
                pass

    identity = describe_object(model)
    atom_count = description.get("atom_count")
    residue_count = description.get("residue_count")
    protein_residue_count = description.get("protein_residue_count")
    classification = description.get("classification")
    atomspec = description.get("atomspec")

    return ModelDiscoveryRecord(
        model=model,
        role=role,
        confidence=confidence,
        index=index,
        name=description.get("name") or identity.name,
        identifier=description.get("id") or identity.identifier,
        atomspec=atomspec,
        classification=classification,
        atom_count=atom_count,
        residue_count=residue_count,
        protein_residue_count=protein_residue_count,
        ligand=ligand,
        source=source,
        metadata={
            "qualified_type": identity.qualified_type,
            "fingerprint": identity.fingerprint,
        },
    )


def discover_ligand_from_pose(pose: Any, *, strict: bool = False) -> Any:
    """Return the ligand representation exposed by a pose model."""

    if pose is None:
        return None
    direct = get_object_value(pose, "ligand", default=MISSING_VALUE)
    if direct is not MISSING_VALUE and direct is not None:
        return direct
    utils_module = load_analysis_module("utils", required=False)
    getter = getattr(utils_module, "get_ligand_from_pose", None) if utils_module else None
    if not callable(getter) and utils_module is not None:
        getter = getattr(utils_module, "get_ligand", None)
    if callable(getter):
        try:
            return getter(pose)
        except Exception as exc:
            if strict:
                raise AnalysisInputError(
                    f"Ligand discovery failed for {resolve_object_name(pose)!r}.",
                    stage=STAGE_INPUT_RESOLUTION,
                    cause=exc,
                ) from exc
    return None


def discover_models(
    models: Any,
    *,
    receptor: Any = None,
    poses: Any = None,
    session: Any = None,
    strict: bool = True,
    include_unknown_poses: bool = False,
    resolve_references: bool = True,
    discover_ligands: bool = True,
    source_kind: Any = InputSourceKind.MODELS,
) -> ModelDiscoveryResult:
    """Identify receptor, poses and ligands from molecular models."""

    normalized_models = normalize_model_collection(models)
    if not normalized_models:
        if strict:
            raise AnalysisInputError(
                "Model discovery requires at least one atomic model.",
                stage=STAGE_INPUT_RESOLUTION,
            )
        return ModelDiscoveryResult(
            source=models,
            source_kind=source_kind,
            session=session,
        )

    utils_module = load_analysis_module("utils", required=True)
    explicit_receptor = receptor
    explicit_poses = poses
    if resolve_references and receptor is not None:
        explicit_receptor = resolve_model_reference(
            normalized_models,
            receptor,
            strict=strict,
        )
    if resolve_references and poses is not None:
        explicit_poses = resolve_model_references(
            normalized_models,
            poses,
            strict=strict,
        )

    receptor_model = explicit_receptor
    identifier = getattr(utils_module, "identify_receptor", None)
    if receptor_model is None and callable(identifier):
        try:
            receptor_model = identifier(
                models=list(normalized_models),
                receptor=None,
                strict=strict,
            )
        except Exception as exc:
            if strict:
                raise AnalysisInputError(
                    "A receptor could not be identified from the available models.",
                    stage=STAGE_INPUT_RESOLUTION,
                    cause=exc,
                ) from exc

    pose_models: List[Any] = []
    pose_identifier = getattr(utils_module, "identify_pose_models", None)
    if explicit_poses is not None:
        # Explicit pose selections are authoritative and must not depend on
        # optional discovery helpers returning the same objects again.
        pose_models = normalize_model_collection(explicit_poses)
    elif callable(pose_identifier) and receptor_model is not None:
        try:
            pose_models = list(
                pose_identifier(
                    models=list(normalized_models),
                    receptor=receptor_model,
                    poses=None,
                    include_unknown=include_unknown_poses,
                )
            )
        except Exception as exc:
            if strict:
                raise AnalysisInputError(
                    "Docking poses could not be identified from the available models.",
                    stage=STAGE_INPUT_RESOLUTION,
                    cause=exc,
                ) from exc

    pose_models = unique_preserving_order(pose_models, key=id)
    ligand_values: List[Any] = []
    if discover_ligands:
        ligand_values = [
            discover_ligand_from_pose(pose, strict=False)
            for pose in pose_models
        ]

    records: List[ModelDiscoveryRecord] = []
    pose_ids = {id(pose) for pose in pose_models}
    for index, model in enumerate(normalized_models):
        if model is receptor_model:
            role = ModelRole.RECEPTOR
            confidence = (
                DiscoveryConfidence.EXPLICIT
                if explicit_receptor is not None
                else DiscoveryConfidence.HIGH
            )
            ligand = None
        elif id(model) in pose_ids:
            role = ModelRole.POSE
            confidence = (
                DiscoveryConfidence.EXPLICIT
                if explicit_poses is not None
                else DiscoveryConfidence.HIGH
            )
            pose_index = pose_models.index(model)
            ligand = (
                ligand_values[pose_index]
                if pose_index < len(ligand_values)
                else None
            )
        else:
            role = ModelRole.UNKNOWN
            confidence = DiscoveryConfidence.LOW
            ligand = None
        records.append(
            describe_discovered_model(
                model,
                index=index,
                role=role,
                confidence=confidence,
                ligand=ligand,
                source="model_discovery",
            )
        )

    mode = infer_analysis_mode(
        session=session,
        receptor=receptor_model,
        poses=pose_models,
    )
    warnings_list: List[str] = []
    if receptor_model is None:
        warnings_list.append("No receptor model was resolved.")
    if not pose_models:
        warnings_list.append("No docking-pose models were resolved.")
    if ligand_values and any(value is None for value in ligand_values):
        warnings_list.append("One or more pose ligands could not be resolved.")

    return ModelDiscoveryResult(
        source=models,
        source_kind=source_kind,
        session=session,
        models=normalized_models,
        records=records,
        receptor=receptor_model,
        poses=pose_models,
        ligands=ligand_values,
        mode=mode,
        warnings=warnings_list,
        metadata={
            "explicit_receptor": receptor is not None,
            "explicit_poses": poses is not None,
            "include_unknown_poses": include_unknown_poses,
            "resolve_references": resolve_references,
        },
    )


# 8.8. Prepared DockModel extraction
# -----------------------------------------------------------------------------

def extract_dock_model_components(
    dock_models: Any,
) -> Tuple[List[Any], Any, List[Any], List[Any]]:
    """Return normalized models, receptor, poses and ligands."""

    models = unique_preserving_order(
        [
            item
            for item in normalize_object_sequence(
                dock_models,
                maximum_items=MAX_DISCOVERY_MODELS,
            )
            if is_dock_model_like(item)
        ],
        key=id,
    )
    receptor = None
    poses: List[Any] = []
    ligands: List[Any] = []
    for model in models:
        candidate_receptor = get_object_value(model, "receptor", default=None)
        if receptor is None and candidate_receptor is not None:
            receptor = candidate_receptor
        pose = get_object_value(model, "pose", default=None)
        if pose is not None:
            poses.append(pose)
        ligand = get_object_value(model, "ligand", default=None)
        ligands.append(ligand)
    return models, receptor, unique_preserving_order(poses, key=id), ligands


def discovery_from_dock_models(
    dock_models: Any,
    *,
    receptor: Any = None,
    session: Any = None,
) -> ModelDiscoveryResult:
    """Build discovery output from existing DockModel-like objects."""

    models, inferred_receptor, poses, ligands = extract_dock_model_components(
        dock_models
    )
    receptor_value = receptor if receptor is not None else inferred_receptor
    records = [
        describe_discovered_model(
            pose if pose is not None else model,
            index=index,
            role=ModelRole.POSE,
            confidence=DiscoveryConfidence.EXPLICIT,
            ligand=ligands[index] if index < len(ligands) else None,
            source="dock_model",
        )
        for index, (model, pose) in enumerate(
            zip(models, [get_object_value(item, "pose", default=None) for item in models])
        )
    ]
    source_kind = (
        InputSourceKind.DOCK_MODEL
        if len(models) == 1
        else InputSourceKind.DOCK_MODELS
    )
    return ModelDiscoveryResult(
        source=dock_models,
        source_kind=source_kind,
        session=session,
        records=records,
        receptor=receptor_value,
        poses=poses,
        ligands=ligands,
        dock_models=models,
        mode=infer_analysis_mode(
            session=session,
            receptor=receptor_value,
            poses=poses,
            dock_models=models,
        ),
    )


# 8.9. Batch request resolution
# -----------------------------------------------------------------------------

def coerce_batch_requests(
    value: Any,
    *,
    default_config: AnalysisConfigLike = None,
    maximum: int = MAX_BATCH_REQUESTS,
) -> List[AnalysisRequest]:
    """Normalize independent batch items as analysis requests."""

    config_value = coerce_analysis_config(default_config)
    items = normalize_object_sequence(value, maximum_items=maximum)
    requests: List[AnalysisRequest] = []
    for index, item in enumerate(items):
        if isinstance(item, AnalysisContext):
            requests.append(item.request)
        elif isinstance(item, AnalysisRequest):
            requests.append(item)
        elif isinstance(item, Mapping):
            request_value = get_input_mapping_value(item, "request")
            if request_value is not MISSING_VALUE:
                requests.append(coerce_analysis_request(request_value))
            else:
                requests.append(
                    create_analysis_request(
                        item,
                        config=config_value,
                        mode=ANALYSIS_MODE_AUTO,
                        name=f"batch_item_{index + 1}",
                    )
                )
        else:
            requests.append(
                create_analysis_request(
                    item,
                    config=config_value,
                    mode=ANALYSIS_MODE_AUTO,
                    name=f"batch_item_{index + 1}",
                )
            )
    if len(requests) > maximum:
        raise AnalysisInputError(
            f"Batch request count exceeds the configured limit of {maximum}.",
            stage=STAGE_INPUT_RESOLUTION,
        )
    return requests


# 8.10. Analysis-mode inference
# -----------------------------------------------------------------------------

def infer_analysis_mode(
    *,
    explicit_mode: Any = ANALYSIS_MODE_AUTO,
    session: Any = None,
    receptor: Any = None,
    poses: Any = None,
    dock_models: Any = None,
    batch_requests: Any = None,
) -> str:
    """Infer execution mode from normalized input cardinality."""

    requested = canonicalize_analysis_mode(explicit_mode)
    if requested != ANALYSIS_MODE_AUTO:
        return requested
    batch_count = len(normalize_object_sequence(batch_requests))
    if batch_count:
        return ANALYSIS_MODE_BATCH
    if session is not None:
        return ANALYSIS_MODE_SESSION
    pose_count = max(
        len(normalize_object_sequence(poses)),
        len(normalize_object_sequence(dock_models)),
    )
    if pose_count > 1:
        return ANALYSIS_MODE_MULTIPOSE
    if pose_count == 1:
        return ANALYSIS_MODE_SINGLE_POSE
    if receptor is not None:
        return ANALYSIS_MODE_SINGLE_POSE
    return ANALYSIS_MODE_AUTO


# 8.11. Mapping and generic-input resolution
# -----------------------------------------------------------------------------

def _resolve_mapping_input(
    mapping: Mapping[str, Any],
    *,
    request: AnalysisRequest,
    options: Mapping[str, Any],
) -> ModelDiscoveryResult:
    """Resolve a structured mapping input."""

    nested_context = get_input_mapping_value(mapping, "context")
    if isinstance(nested_context, AnalysisContext):
        return resolve_analysis_input(nested_context.request).discovery or ModelDiscoveryResult()

    nested_request = get_input_mapping_value(mapping, "request")
    if nested_request is not MISSING_VALUE:
        nested = coerce_analysis_request(nested_request)
        return resolve_analysis_input(nested).discovery or ModelDiscoveryResult()

    batch_value = get_input_mapping_value(mapping, "batch")
    if batch_value is not MISSING_VALUE:
        batch_requests = coerce_batch_requests(
            batch_value,
            default_config=request.config,
            maximum=request.config.runtime.max_batch_items,
        )
        return ModelDiscoveryResult(
            source=mapping,
            source_kind=InputSourceKind.BATCH,
            batch_requests=batch_requests,
            mode=ANALYSIS_MODE_BATCH,
            metadata=normalize_metadata_mapping(
                get_input_mapping_value(mapping, "metadata", default={})
            ),
        )

    session = get_input_mapping_value(mapping, "session", default=request.session)
    receptor = get_input_mapping_value(
        mapping,
        "receptor",
        default=request.receptor,
    )
    poses = get_input_mapping_value(mapping, "poses")
    if poses is MISSING_VALUE:
        pose = get_input_mapping_value(mapping, "pose")
        poses = () if pose is MISSING_VALUE else (pose,)
    dock_models = get_input_mapping_value(
        mapping,
        "dock_models",
        default=request.dock_models,
    )
    if dock_models is not MISSING_VALUE and normalize_object_sequence(dock_models):
        result = discovery_from_dock_models(
            dock_models,
            receptor=receptor if receptor is not MISSING_VALUE else None,
            session=session if session is not MISSING_VALUE else None,
        )
        result.source_kind = InputSourceKind.MAPPING
        return result

    models = get_input_mapping_value(mapping, "models")
    if models is MISSING_VALUE and session is not MISSING_VALUE and session is not None:
        models = get_session_models(
            session,
            strict=bool(options["strict"]),
        )
    if models is not MISSING_VALUE and normalize_object_sequence(models):
        return discover_models(
            models,
            receptor=None if receptor is MISSING_VALUE else receptor,
            poses=None if poses is MISSING_VALUE else poses,
            session=None if session is MISSING_VALUE else session,
            strict=bool(options["strict"]),
            include_unknown_poses=bool(options["include_unknown_poses"]),
            resolve_references=bool(options["resolve_references"]),
            discover_ligands=bool(options["discover_ligands"]),
            source_kind=InputSourceKind.MAPPING,
        )

    explicit_poses = normalize_object_sequence(
        () if poses is MISSING_VALUE else poses,
        maximum_items=MAX_DISCOVERY_MODELS,
    )
    if receptor is not MISSING_VALUE and receptor is not None and explicit_poses:
        ligands = [
            discover_ligand_from_pose(pose, strict=False)
            for pose in explicit_poses
        ]
        return ModelDiscoveryResult(
            source=mapping,
            source_kind=InputSourceKind.RECEPTOR_POSES,
            session=None if session is MISSING_VALUE else session,
            receptor=receptor,
            poses=explicit_poses,
            ligands=ligands,
            records=[
                describe_discovered_model(
                    receptor,
                    index=0,
                    role=ModelRole.RECEPTOR,
                    confidence=DiscoveryConfidence.EXPLICIT,
                    source="mapping",
                ),
                *[
                    describe_discovered_model(
                        pose,
                        index=index + 1,
                        role=ModelRole.POSE,
                        confidence=DiscoveryConfidence.EXPLICIT,
                        ligand=ligands[index],
                        source="mapping",
                    )
                    for index, pose in enumerate(explicit_poses)
                ],
            ],
            mode=infer_analysis_mode(
                explicit_mode=get_input_mapping_value(
                    mapping,
                    "mode",
                    default=request.mode,
                ),
                session=None if session is MISSING_VALUE else session,
                receptor=receptor,
                poses=explicit_poses,
            ),
        )

    nested_input = get_input_mapping_value(mapping, "input_data")
    if nested_input is not MISSING_VALUE and nested_input is not mapping:
        nested_request = replace(request, input_data=nested_input)
        resolved = resolve_analysis_input(nested_request)
        if resolved.discovery is not None:
            return resolved.discovery

    return ModelDiscoveryResult(
        source=mapping,
        source_kind=InputSourceKind.MAPPING,
        session=None if session is MISSING_VALUE else session,
        receptor=None if receptor is MISSING_VALUE else receptor,
        poses=explicit_poses,
        mode=infer_analysis_mode(
            explicit_mode=request.mode,
            session=None if session is MISSING_VALUE else session,
            receptor=None if receptor is MISSING_VALUE else receptor,
            poses=explicit_poses,
        ),
        warnings=["The mapping did not contain a complete molecular input."],
    )


def _resolve_generic_input(
    value: Any,
    *,
    request: AnalysisRequest,
    options: Mapping[str, Any],
) -> ModelDiscoveryResult:
    """Resolve one arbitrary non-request input object."""

    source_kind = classify_analysis_input(value)
    if source_kind is InputSourceKind.CONTEXT:
        context = value
        return ModelDiscoveryResult(
            source=context,
            source_kind=source_kind,
            session=context.session,
            receptor=context.receptor,
            poses=context.poses,
            dock_models=context.dock_models,
            mode=infer_analysis_mode(
                explicit_mode=context.mode,
                session=context.session,
                receptor=context.receptor,
                poses=context.poses,
                dock_models=context.dock_models,
            ),
        )
    if source_kind is InputSourceKind.REQUEST:
        return resolve_analysis_input(value).discovery or ModelDiscoveryResult()
    if source_kind is InputSourceKind.MAPPING:
        return _resolve_mapping_input(value, request=request, options=options)
    if source_kind is InputSourceKind.BATCH:
        return ModelDiscoveryResult(
            source=value,
            source_kind=source_kind,
            batch_requests=coerce_batch_requests(
                value,
                default_config=request.config,
                maximum=request.config.runtime.max_batch_items,
            ),
            mode=ANALYSIS_MODE_BATCH,
        )
    if source_kind in {InputSourceKind.DOCK_MODEL, InputSourceKind.DOCK_MODELS}:
        return discovery_from_dock_models(
            value,
            receptor=request.receptor,
            session=request.session,
        )
    if source_kind is InputSourceKind.SESSION:
        models = get_session_models(
            value,
            strict=bool(options["strict"]),
        )
        return discover_models(
            models,
            receptor=request.receptor,
            poses=request.poses or None,
            session=value,
            strict=bool(options["strict"]),
            include_unknown_poses=bool(options["include_unknown_poses"]),
            resolve_references=bool(options["resolve_references"]),
            discover_ligands=bool(options["discover_ligands"]),
            source_kind=source_kind,
        )
    if source_kind in {InputSourceKind.MODEL, InputSourceKind.MODELS}:
        models = [value] if source_kind is InputSourceKind.MODEL else value
        return discover_models(
            models,
            receptor=request.receptor,
            poses=request.poses or None,
            session=request.session,
            strict=bool(options["strict"]),
            include_unknown_poses=bool(options["include_unknown_poses"]),
            resolve_references=bool(options["resolve_references"]),
            discover_ligands=bool(options["discover_ligands"]),
            source_kind=source_kind,
        )
    if source_kind is InputSourceKind.RECEPTOR_POSES:
        items = normalize_object_sequence(value, maximum_items=2)
        receptor = items[0]
        poses = normalize_object_sequence(items[1], maximum_items=MAX_DISCOVERY_MODELS)
        if not poses and is_atomic_model_like(items[1]):
            poses = [items[1]]
        ligands = [discover_ligand_from_pose(pose) for pose in poses]
        return ModelDiscoveryResult(
            source=value,
            source_kind=source_kind,
            receptor=receptor,
            poses=poses,
            ligands=ligands,
            records=[
                describe_discovered_model(
                    receptor,
                    index=0,
                    role=ModelRole.RECEPTOR,
                    confidence=DiscoveryConfidence.EXPLICIT,
                    source="tuple",
                ),
                *[
                    describe_discovered_model(
                        pose,
                        index=index + 1,
                        role=ModelRole.POSE,
                        confidence=DiscoveryConfidence.EXPLICIT,
                        ligand=ligands[index],
                        source="tuple",
                    )
                    for index, pose in enumerate(poses)
                ],
            ],
            mode=infer_analysis_mode(receptor=receptor, poses=poses),
        )

    return ModelDiscoveryResult(
        source=value,
        source_kind=source_kind,
        mode=ANALYSIS_MODE_AUTO,
        warnings=["The analysis input type could not be resolved."],
    )


# 8.12. Public input-resolution workflow
# -----------------------------------------------------------------------------

def resolve_analysis_input(
    value: Any,
    *,
    config: AnalysisConfigLike = None,
    strict: Optional[bool] = None,
    allow_empty: Optional[bool] = None,
) -> ResolvedAnalysisInput:
    """Resolve a request, context or raw input into canonical components."""

    if isinstance(value, AnalysisContext):
        request = value.request
        context = value
    elif isinstance(value, AnalysisRequest):
        request = value
        context = None
    else:
        request = create_analysis_request(value, config=config)
        context = None

    options = get_discovery_options(request.config)
    if strict is not None:
        options["strict"] = bool(strict)
    if allow_empty is not None:
        options["allow_empty"] = bool(allow_empty)

    if context is not None:
        source = context
    elif request.input_data is not None:
        source = request.input_data
    elif request.dock_models:
        source = request.dock_models
    elif request.session is not None:
        source = request.session
    elif request.receptor is not None or request.poses:
        source = {
            "receptor": request.receptor,
            "poses": request.poses,
            "session": request.session,
            "dock_models": request.dock_models,
            "mode": request.mode,
        }
    else:
        source = None

    discovery = _resolve_generic_input(
        source,
        request=request,
        options=options,
    )

    explicit_mode = request.mode
    mode = infer_analysis_mode(
        explicit_mode=explicit_mode,
        session=discovery.session,
        receptor=discovery.receptor,
        poses=discovery.poses,
        dock_models=discovery.dock_models,
        batch_requests=discovery.batch_requests,
    )
    discovery.mode = mode

    resolved = ResolvedAnalysisInput(
        request=request,
        source_kind=discovery.source_kind,
        mode=mode,
        session=discovery.session,
        receptor=discovery.receptor,
        poses=tuple(discovery.poses),
        ligands=tuple(discovery.ligands),
        dock_models=tuple(discovery.dock_models),
        batch_requests=tuple(discovery.batch_requests),
        discovery=discovery,
        metadata={
            "input_fingerprint": stable_object_fingerprint(
                request.input_data if request.input_data is not None else source
            ),
            "discovery_options": dict(options),
        },
    )

    validation = validate_resolved_analysis_input(
        resolved,
        strict=False,
        allow_empty=bool(options["allow_empty"]),
    )
    if validation["errors"] and bool(options["strict"]):
        raise AnalysisInputError(
            "Analysis input resolution failed: " + " ".join(validation["errors"]),
            stage=STAGE_INPUT_RESOLUTION,
            details=validation,
        )
    return resolved


def apply_resolved_input_to_context(
    context: AnalysisContext,
    resolved: ResolvedAnalysisInput,
    *,
    replace_existing: bool = True,
) -> AnalysisContext:
    """Apply resolved input components to a runtime context."""

    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance.")
    if not isinstance(resolved, ResolvedAnalysisInput):
        raise TypeError("resolved must be a ResolvedAnalysisInput instance.")

    if replace_existing or context.session is None:
        context.session = resolved.session
    if replace_existing or context.receptor is None:
        context.receptor = resolved.receptor
    if replace_existing or not context.poses:
        context.poses = list(resolved.poses)
    if replace_existing or not context.dock_models:
        context.dock_models = list(resolved.dock_models)
    context.mode = resolved.mode
    context.set_stage_data(STAGE_INPUT_RESOLUTION, resolved)
    context.set_shared("resolved_input", resolved)
    context.metadata.update(
        {
            "input_source_kind": resolved.source_kind.value,
            "input_mode": resolved.mode,
            "input_item_count": resolved.item_count,
            "input_fingerprint": resolved.metadata.get("input_fingerprint"),
        }
    )
    return context


def resolve_context_input(
    context: AnalysisContext,
    *,
    strict: Optional[bool] = None,
    allow_empty: Optional[bool] = None,
) -> ResolvedAnalysisInput:
    """Resolve and attach the molecular input of an existing context."""

    resolved = resolve_analysis_input(
        context,
        strict=strict,
        allow_empty=allow_empty,
    )
    apply_resolved_input_to_context(context, resolved)
    return resolved


# 8.13. Validation and summaries
# -----------------------------------------------------------------------------

def validate_model_discovery_result(
    value: ModelDiscoveryResult,
    *,
    strict: bool = False,
) -> Dict[str, Any]:
    """Validate one model-discovery result without mutating it."""

    if not isinstance(value, ModelDiscoveryResult):
        raise TypeError("value must be a ModelDiscoveryResult instance.")
    errors: List[str] = []
    warnings_list = list(value.warnings)

    if value.mode == ANALYSIS_MODE_BATCH:
        if not value.batch_requests:
            errors.append("Batch mode requires at least one analysis request.")
    else:
        if value.dock_models:
            invalid = [
                index
                for index, model in enumerate(value.dock_models)
                if not is_dock_model_like(model)
            ]
            if invalid:
                errors.append(
                    "Invalid DockModel-like entries were found at indices: "
                    + ", ".join(map(str, invalid))
                    + "."
                )
        elif value.poses and value.receptor is None:
            errors.append("Resolved poses require a receptor model.")
        elif value.receptor is not None and not value.poses:
            warnings_list.append("A receptor was resolved without docking poses.")

    model_ids = [id(model) for model in value.models]
    if len(model_ids) != len(set(model_ids)):
        errors.append("The discovered model collection contains duplicates.")
    pose_ids = [id(model) for model in value.poses]
    if len(pose_ids) != len(set(pose_ids)):
        errors.append("The resolved pose collection contains duplicates.")
    if value.receptor is not None and id(value.receptor) in set(pose_ids):
        errors.append("The receptor cannot also be assigned as a docking pose.")

    result = {
        "valid": not errors,
        "errors": errors,
        "warnings": unique_preserving_order(warnings_list),
        "summary": value.summary(),
    }
    if strict and errors:
        raise AnalysisInputError(
            "Model discovery validation failed: " + " ".join(errors),
            stage=STAGE_INPUT_RESOLUTION,
            details=result,
        )
    return result


def validate_resolved_analysis_input(
    value: ResolvedAnalysisInput,
    *,
    strict: bool = False,
    allow_empty: bool = False,
) -> Dict[str, Any]:
    """Validate canonical input before model preparation."""

    if not isinstance(value, ResolvedAnalysisInput):
        raise TypeError("value must be a ResolvedAnalysisInput instance.")
    errors: List[str] = []
    warnings_list: List[str] = []

    if value.mode == ANALYSIS_MODE_BATCH:
        if not value.batch_requests and not allow_empty:
            errors.append("Batch input does not contain analysis requests.")
    elif not value.ready_for_preparation:
        if allow_empty:
            warnings_list.append("Molecular input is incomplete but empty input is allowed.")
        elif value.receptor is None and not value.dock_models:
            errors.append("No receptor or prepared DockModel was resolved.")
        elif not value.poses and not value.dock_models:
            errors.append("No docking poses or prepared DockModel objects were resolved.")

    if value.mode == ANALYSIS_MODE_SINGLE_POSE and value.pose_count > 1:
        errors.append("Single-pose mode resolved more than one pose.")
    if value.mode == ANALYSIS_MODE_MULTIPOSE and value.pose_count < 2:
        warnings_list.append("Multipose mode resolved fewer than two poses.")
    if value.mode == ANALYSIS_MODE_SESSION and value.session is None:
        errors.append("Session mode requires a session object.")
    if len(value.batch_requests) > value.request.config.runtime.max_batch_items:
        errors.append("Resolved batch size exceeds the configured limit.")
    if value.pose_count > value.request.config.runtime.max_multipose_items:
        errors.append("Resolved pose count exceeds the configured limit.")

    discovery_validation = (
        validate_model_discovery_result(value.discovery)
        if value.discovery is not None
        else {"valid": True, "errors": [], "warnings": [], "summary": {}}
    )
    errors.extend(discovery_validation["errors"])
    warnings_list.extend(discovery_validation["warnings"])

    result = {
        "valid": not errors,
        "errors": unique_preserving_order(errors),
        "warnings": unique_preserving_order(warnings_list),
        "source_kind": value.source_kind.value,
        "mode": value.mode,
        "pose_count": value.pose_count,
        "batch_count": len(value.batch_requests),
        "ready_for_preparation": value.ready_for_preparation,
        "discovery": discovery_validation,
    }
    if strict and result["errors"]:
        raise AnalysisInputError(
            "Resolved input validation failed: " + " ".join(result["errors"]),
            stage=STAGE_INPUT_RESOLUTION,
            details=result,
        )
    return result


def summarize_resolved_analysis_input(value: ResolvedAnalysisInput) -> str:
    """Return a concise human-readable input summary."""

    validation = validate_resolved_analysis_input(value, allow_empty=True)
    lines = [
        "DockAnalyzer Input Resolution",
        f"Source: {value.source_kind.value}",
        f"Mode: {value.mode}",
        f"Receptor: {resolve_object_name(value.receptor) if value.receptor is not None else 'not resolved'}",
        f"Poses: {value.pose_count}",
        f"Batch requests: {len(value.batch_requests)}",
        f"Ready for preparation: {'yes' if value.ready_for_preparation else 'no'}",
        f"Validation: {'valid' if validation['valid'] else 'invalid'}",
    ]
    if validation["warnings"]:
        lines.append("Warnings: " + "; ".join(validation["warnings"]))
    if validation["errors"]:
        lines.append("Errors: " + "; ".join(validation["errors"]))
    return "\n".join(lines)


# 8.14. Internal convention validation
# -----------------------------------------------------------------------------

def validate_input_resolution_conventions() -> Dict[str, Any]:
    """Validate Section 8 constants, records and synthetic workflows."""

    failures: List[str] = []
    if len(INPUT_SOURCE_KINDS) != len(set(INPUT_SOURCE_KINDS)):
        failures.append("Input source kinds contain duplicates.")
    if len(MODEL_ROLES) != len(set(MODEL_ROLES)):
        failures.append("Model roles contain duplicates.")
    if canonicalize_input_source_kind("dockmodels") is not InputSourceKind.DOCK_MODELS:
        failures.append("DockModel source aliases are inconsistent.")
    if canonicalize_model_role("protein") is not ModelRole.RECEPTOR:
        failures.append("Receptor role aliases are inconsistent.")

    receptor = SimpleNamespace(
        name="Synthetic Receptor",
        id_string="1",
        atoms=(1, 2, 3),
        residues=(1, 2),
    )
    ligand = SimpleNamespace(name="Synthetic Ligand")
    pose = SimpleNamespace(
        name="Synthetic Pose",
        id_string="2",
        atoms=(1, 2),
        residues=(1,),
        ligand=ligand,
    )
    request = create_analysis_request(
        {"receptor": receptor, "poses": [pose]},
        config={
            "runtime": {"failure_policy": "permissive"},
            "stage_configs": {
                STAGE_INPUT_RESOLUTION: {
                    "parameters": {"allow_empty_input": False}
                }
            },
        },
    )
    resolved = resolve_analysis_input(request, strict=False)
    if resolved.receptor is not receptor or resolved.poses != (pose,):
        failures.append("Explicit receptor-pose resolution produced unexpected objects.")
    if resolved.mode != ANALYSIS_MODE_SINGLE_POSE:
        failures.append("Single-pose mode inference produced an unexpected value.")
    if not resolved.ready_for_preparation:
        failures.append("Resolved explicit input should be ready for preparation.")

    dock_model = DockModel(
        name="synthetic_pose",
        pose=pose,
        receptor=receptor,
        ligand=ligand,
    )
    dock_resolved = resolve_analysis_input(dock_model, strict=False)
    if dock_resolved.dock_models != (dock_model,):
        failures.append("DockModel resolution did not preserve the input object.")

    batch = coerce_batch_requests(
        [
            {"receptor": receptor, "poses": [pose]},
            dock_model,
        ],
        default_config={"runtime": {"failure_policy": "permissive"}},
    )
    if len(batch) != 2:
        failures.append("Batch request coercion produced an unexpected count.")

    context = create_analysis_context(request)
    apply_resolved_input_to_context(context, resolved)
    if context.receptor is not receptor or context.poses != [pose]:
        failures.append("Resolved input was not applied to the context correctly.")
    if context.get_shared("resolved_input") is not resolved:
        failures.append("Resolved input was not retained in shared context data.")

    validation = validate_resolved_analysis_input(resolved)
    if not validation["valid"]:
        failures.append("Synthetic resolved input failed validation.")
    if "Source: receptor_poses" not in summarize_resolved_analysis_input(resolved):
        failures.append("Resolved-input summary omitted the source category.")

    if failures:
        raise RuntimeError(
            "Input-resolution convention validation failed: " + " ".join(failures)
        )

    return {
        "valid": True,
        "input_source_kinds": len(INPUT_SOURCE_KINDS),
        "model_roles": len(MODEL_ROLES),
        "validated_cases": 14,
        "maximum_models": MAX_DISCOVERY_MODELS,
        "maximum_batch_requests": MAX_BATCH_REQUESTS,
    }


