# 9.1. Preparation conventions
# -----------------------------------------------------------------------------

PREPARATION_ACTION_PRESERVE: Final[str] = "preserve"
PREPARATION_ACTION_COPY: Final[str] = "copy"
PREPARATION_ACTION_COERCE: Final[str] = "coerce"
PREPARATION_ACTION_CREATE: Final[str] = "create"
PREPARATION_ACTION_REPAIR: Final[str] = "repair"
PREPARATION_ACTION_SKIP: Final[str] = "skip"

PREPARATION_ACTIONS: Final[Tuple[str, ...]] = (
    PREPARATION_ACTION_PRESERVE,
    PREPARATION_ACTION_COPY,
    PREPARATION_ACTION_COERCE,
    PREPARATION_ACTION_CREATE,
    PREPARATION_ACTION_REPAIR,
    PREPARATION_ACTION_SKIP,
)

PREPARATION_STATE_PENDING: Final[str] = "pending"
PREPARATION_STATE_READY: Final[str] = "ready"
PREPARATION_STATE_PARTIAL: Final[str] = "partial"
PREPARATION_STATE_INVALID: Final[str] = "invalid"
PREPARATION_STATE_SKIPPED: Final[str] = "skipped"

PREPARATION_STATES: Final[Tuple[str, ...]] = (
    PREPARATION_STATE_PENDING,
    PREPARATION_STATE_READY,
    PREPARATION_STATE_PARTIAL,
    PREPARATION_STATE_INVALID,
    PREPARATION_STATE_SKIPPED,
)

PREPARATION_METADATA_KEY: Final[str] = "dockanalyzer_preparation"
PREPARATION_VERSION_KEY: Final[str] = "schema_version"
PREPARATION_SCHEMA_VERSION: Final[str] = ANALYSIS_SCHEMA_VERSION
PREPARATION_HISTORY_KEY: Final[str] = "preparation_history"
