# 9.2. Preparation enums
# -----------------------------------------------------------------------------

class ModelPreparationAction(str, Enum):
    """Describe how one prepared DockModel was obtained."""

    PRESERVE = PREPARATION_ACTION_PRESERVE
    COPY = PREPARATION_ACTION_COPY
    COERCE = PREPARATION_ACTION_COERCE
    CREATE = PREPARATION_ACTION_CREATE
    REPAIR = PREPARATION_ACTION_REPAIR
    SKIP = PREPARATION_ACTION_SKIP


class ModelPreparationState(str, Enum):
    """Describe the usability of one prepared model record."""

    PENDING = PREPARATION_STATE_PENDING
    READY = PREPARATION_STATE_READY
    PARTIAL = PREPARATION_STATE_PARTIAL
    INVALID = PREPARATION_STATE_INVALID
    SKIPPED = PREPARATION_STATE_SKIPPED


def canonicalize_model_preparation_action(value: Any) -> ModelPreparationAction:
    """Return a canonical model-preparation action."""

    if isinstance(value, ModelPreparationAction):
        return value
    token = _normalize_convention_token(
        value,
        field_name="model preparation action",
    )
    aliases = {
        "preserve": ModelPreparationAction.PRESERVE,
        "reuse": ModelPreparationAction.PRESERVE,
        "keep": ModelPreparationAction.PRESERVE,
        "copy": ModelPreparationAction.COPY,
        "clone": ModelPreparationAction.COPY,
        "coerce": ModelPreparationAction.COERCE,
        "convert": ModelPreparationAction.COERCE,
        "create": ModelPreparationAction.CREATE,
        "new": ModelPreparationAction.CREATE,
        "repair": ModelPreparationAction.REPAIR,
        "normalize": ModelPreparationAction.REPAIR,
        "normalise": ModelPreparationAction.REPAIR,
        "skip": ModelPreparationAction.SKIP,
        "ignored": ModelPreparationAction.SKIP,
    }
    try:
        return aliases[token]
    except KeyError as exc:
        raise ValueError(
            f"Unknown model preparation action {value!r}."
        ) from exc


def canonicalize_model_preparation_state(value: Any) -> ModelPreparationState:
    """Return a canonical model-preparation state."""

    if isinstance(value, ModelPreparationState):
        return value
    token = _normalize_convention_token(
        value,
        field_name="model preparation state",
    )
    aliases = {
        "pending": ModelPreparationState.PENDING,
        "ready": ModelPreparationState.READY,
        "valid": ModelPreparationState.READY,
        "succeeded": ModelPreparationState.READY,
        "partial": ModelPreparationState.PARTIAL,
        "incomplete": ModelPreparationState.PARTIAL,
        "invalid": ModelPreparationState.INVALID,
        "failed": ModelPreparationState.INVALID,
        "skipped": ModelPreparationState.SKIPPED,
        "skip": ModelPreparationState.SKIPPED,
    }
    try:
        return aliases[token]
    except KeyError as exc:
        raise ValueError(
            f"Unknown model preparation state {value!r}."
        ) from exc


# 9.3. Preparation options
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class ModelPreparationOptions:
    """Control DockModel creation, repair and validation."""

    preserve_existing: bool = DEFAULT_PRESERVE_EXISTING_DOCK_MODELS
    copy_existing: bool = DEFAULT_COPY_EXISTING_DOCK_MODELS
    repair_missing_fields: bool = DEFAULT_REPAIR_DOCK_MODELS
    discover_ligand: bool = DEFAULT_DISCOVER_PREPARATION_LIGANDS
    allow_empty_pose: bool = DEFAULT_ALLOW_EMPTY_POSES
    allow_missing_receptor: bool = DEFAULT_ALLOW_MISSING_RECEPTOR
    reject_duplicate_poses: bool = DEFAULT_REJECT_DUPLICATE_POSES
    reject_receptor_as_pose: bool = DEFAULT_REJECT_RECEPTOR_AS_POSE
    attach_receptor: bool = DEFAULT_ATTACH_PREPARATION_RECEPTOR
    attach_ligand: bool = DEFAULT_ATTACH_PREPARATION_LIGAND
    store_preparation_metadata: bool = DEFAULT_STORE_PREPARATION_METADATA
    inspect_existing_results: bool = DEFAULT_INSPECT_EXISTING_RESULTS
    validate_models: bool = DEFAULT_VALIDATE_PREPARED_MODELS
    strict: bool = DEFAULT_PREPARATION_STRICT
    name_prefix: str = DEFAULT_DOCK_MODEL_NAME_PREFIX
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        for field_name in (
            "preserve_existing",
            "copy_existing",
            "repair_missing_fields",
            "discover_ligand",
            "allow_empty_pose",
            "allow_missing_receptor",
            "reject_duplicate_poses",
            "reject_receptor_as_pose",
            "attach_receptor",
            "attach_ligand",
            "store_preparation_metadata",
            "inspect_existing_results",
            "validate_models",
            "strict",
        ):
            object.__setattr__(
                self,
                field_name,
                normalize_boolean(getattr(self, field_name)),
            )
        name_prefix = normalize_text(
            self.name_prefix,
            default=DEFAULT_DOCK_MODEL_NAME_PREFIX,
        )
        object.__setattr__(self, "name_prefix", name_prefix)
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )
        if self.copy_existing and not self.preserve_existing:
            object.__setattr__(self, "preserve_existing", True)

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "ModelPreparationOptions":
        """Create options from canonical or aliased mapping keys."""

        if not isinstance(values, Mapping):
            raise TypeError("Model preparation options must be a mapping.")
        allowed = frozenset(item.name for item in fields(cls))
        normalized: Dict[str, Any] = {}
        for raw_key, raw_value in values.items():
            token = _normalize_convention_token(
                raw_key,
                field_name="model preparation option",
            )
            field_name = MODEL_PREPARATION_CONFIG_ALIASES.get(token, token)
            if field_name not in allowed:
                if strict:
                    raise AnalysisConfigurationError(
                        f"Unknown model preparation option {raw_key!r}."
                    )
                continue
            if field_name in normalized:
                raise AnalysisConfigurationError(
                    "Duplicate model preparation option after alias resolution: "
                    f"{field_name!r}."
                )
            normalized[field_name] = raw_value
        return cls(**normalized)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable option mapping."""

        return {
            item.name: _config_value_to_data(getattr(self, item.name))
            for item in fields(self)
        }


# 9.4. Prepared model records
# -----------------------------------------------------------------------------

@dataclass
class PreparedDockModelRecord:
    """Describe construction and readiness of one DockModel."""

    dock_model: Any
    index: int
    action: Union[ModelPreparationAction, str]
    state: Union[ModelPreparationState, str] = ModelPreparationState.PENDING
    receptor: Any = None
    pose: Any = None
    ligand: Any = None
    name: Optional[str] = None
    receptor_identifier: Optional[str] = None
    pose_identifier: Optional[str] = None
    ligand_identifier: Optional[str] = None
    atom_count: Optional[int] = None
    residue_count: Optional[int] = None
    existing_result_fields: Sequence[str] = field(default_factory=tuple)
    repaired_fields: Sequence[str] = field(default_factory=tuple)
    warnings: Sequence[str] = field(default_factory=tuple)
    errors: Sequence[str] = field(default_factory=tuple)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.index = max(0, int(self.index))
        self.action = canonicalize_model_preparation_action(self.action)
        self.state = canonicalize_model_preparation_state(self.state)
        self.name = normalize_text(
            self.name,
            default=resolve_object_name(
                self.dock_model,
                default=f"{DEFAULT_DOCK_MODEL_NAME_PREFIX}_{self.index + 1:03d}",
            ),
        )
        self.receptor_identifier = normalize_optional_identifier(
            self.receptor_identifier
        )
        self.pose_identifier = normalize_optional_identifier(self.pose_identifier)
        self.ligand_identifier = normalize_optional_identifier(
            self.ligand_identifier
        )
        if self.atom_count is not None:
            self.atom_count = normalize_integer(self.atom_count, minimum=0)
        if self.residue_count is not None:
            self.residue_count = normalize_integer(self.residue_count, minimum=0)
        self.existing_result_fields = tuple(
            unique_preserving_order(
                normalize_string_sequence(self.existing_result_fields)
            )
        )
        self.repaired_fields = tuple(
            unique_preserving_order(normalize_string_sequence(self.repaired_fields))
        )
        self.warnings = tuple(
            normalize_string_sequence(
                self.warnings,
                maximum_items=MAX_PREPARATION_WARNINGS,
            )
        )
        self.errors = tuple(
            normalize_string_sequence(
                self.errors,
                maximum_items=MAX_PREPARATION_ERRORS,
            )
        )
        self.metadata = MappingProxyType(normalize_metadata_mapping(self.metadata))

    @property
    def ready(self) -> bool:
        """Return whether the record can enter interaction analysis."""

        return self.state in {
            ModelPreparationState.READY,
            ModelPreparationState.PARTIAL,
        } and not self.errors

    @property
    def has_existing_results(self) -> bool:
        """Return whether pre-existing analysis values were detected."""

        return bool(self.existing_result_fields)

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe record representation."""

        def encode(value: Any) -> Any:
            if include_objects:
                return value
            return describe_object(value).to_dict() if value is not None else None

        return {
            "index": self.index,
            "name": self.name,
            "action": self.action.value,
            "state": self.state.value,
            "ready": self.ready,
            "dock_model": encode(self.dock_model),
            "receptor": encode(self.receptor),
            "pose": encode(self.pose),
            "ligand": encode(self.ligand),
            "receptor_identifier": self.receptor_identifier,
            "pose_identifier": self.pose_identifier,
            "ligand_identifier": self.ligand_identifier,
            "atom_count": self.atom_count,
            "residue_count": self.residue_count,
            "existing_result_fields": list(self.existing_result_fields),
            "repaired_fields": list(self.repaired_fields),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(self.metadata),
        }


@dataclass
class ModelPreparationResult:
    """Collect DockModel preparation output and diagnostics."""

    resolved_input: ResolvedAnalysisInput
    options: ModelPreparationOptions
    dock_models: List[Any] = field(default_factory=list)
    records: List[PreparedDockModelRecord] = field(default_factory=list)
    receptor: Any = None
    poses: List[Any] = field(default_factory=list)
    ligands: List[Any] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not isinstance(self.resolved_input, ResolvedAnalysisInput):
            raise TypeError("resolved_input must be a ResolvedAnalysisInput instance.")
        if not isinstance(self.options, ModelPreparationOptions):
            if isinstance(self.options, Mapping):
                self.options = ModelPreparationOptions.from_mapping(self.options)
            else:
                raise TypeError("options must be ModelPreparationOptions or a mapping.")
        self.dock_models = unique_preserving_order(
            normalize_object_sequence(self.dock_models),
            key=id,
        )
        normalized_records: List[PreparedDockModelRecord] = []
        for index, record in enumerate(self.records):
            if isinstance(record, PreparedDockModelRecord):
                normalized_records.append(record)
            elif isinstance(record, Mapping):
                normalized_records.append(
                    PreparedDockModelRecord(index=index, **dict(record))
                )
            else:
                raise TypeError(
                    "Model preparation records must be PreparedDockModelRecord "
                    "instances or mappings."
                )
        self.records = normalized_records
        self.poses = normalize_object_sequence(self.poses)
        self.ligands = normalize_object_sequence(self.ligands)
        self.warnings = normalize_string_sequence(
            self.warnings,
            maximum_items=MAX_PREPARATION_WARNINGS,
        )
        self.errors = normalize_string_sequence(
            self.errors,
            maximum_items=MAX_PREPARATION_ERRORS,
        )
        self.metadata = normalize_metadata_mapping(self.metadata)

    @property
    def prepared_count(self) -> int:
        """Return the number of prepared DockModel objects."""

        return len(self.dock_models)

    @property
    def ready_count(self) -> int:
        """Return the number of ready preparation records."""

        return sum(record.ready for record in self.records)

    @property
    def invalid_count(self) -> int:
        """Return the number of invalid preparation records."""

        return sum(
            record.state is ModelPreparationState.INVALID
            for record in self.records
        )

    @property
    def has_partial_results(self) -> bool:
        """Return whether useful output exists alongside warnings or errors."""

        return bool(self.dock_models) and bool(
            self.errors
            or self.warnings
            or any(record.state is ModelPreparationState.PARTIAL for record in self.records)
        )

    @property
    def ready(self) -> bool:
        """Return whether downstream interaction analysis can proceed."""

        return bool(self.dock_models) and not self.errors

    def record_for_model(self, model: Any) -> Optional[PreparedDockModelRecord]:
        """Return the record associated with a DockModel by identity."""

        for record in self.records:
            if record.dock_model is model:
                return record
        return None

    def summary(self) -> Dict[str, Any]:
        """Return compact preparation statistics."""

        action_counts = Counter(record.action.value for record in self.records)
        state_counts = Counter(record.state.value for record in self.records)
        existing_counts = Counter(
            field_name
            for record in self.records
            for field_name in record.existing_result_fields
        )
        return {
            "prepared_count": self.prepared_count,
            "ready_count": self.ready_count,
            "invalid_count": self.invalid_count,
            "pose_count": len(self.poses),
            "ligand_count": len(self.ligands),
            "warning_count": len(self.warnings),
            "error_count": len(self.errors),
            "ready": self.ready,
            "partial": self.has_partial_results,
            "action_counts": dict(action_counts),
            "state_counts": dict(state_counts),
            "existing_result_counts": dict(existing_counts),
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe preparation representation."""

        def encode_many(values: Sequence[Any]) -> Any:
            if include_objects:
                return list(values)
            return [describe_object(value).to_dict() for value in values]

        return {
            "resolved_input": self.resolved_input.to_dict(
                include_objects=include_objects
            ),
            "options": self.options.to_dict(),
            "receptor": (
                self.receptor
                if include_objects
                else (
                    describe_object(self.receptor).to_dict()
                    if self.receptor is not None
                    else None
                )
            ),
            "dock_models": encode_many(self.dock_models),
            "poses": encode_many(self.poses),
            "ligands": encode_many(self.ligands),
            "records": [
                record.to_dict(include_objects=include_objects)
                for record in self.records
            ],
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(self.metadata),
            "summary": self.summary(),
        }


# 9.5. Option resolution
# -----------------------------------------------------------------------------

def _extract_model_preparation_config(config: AnalysisConfig) -> Dict[str, Any]:
    """Return model-preparation overrides embedded in analysis configuration."""

    merged: Dict[str, Any] = {}
    for module_name in ("analyze", "model_preparation", "preparation"):
        try:
            value = config.module_config(module_name)
        except (TypeError, ValueError):
            continue
        if not isinstance(value, Mapping):
            continue
        if module_name == "analyze":
            nested = get_first_object_value(
                value,
                ("model_preparation", "preparation", "models"),
                default=None,
            )
            if isinstance(nested, Mapping):
                merged.update(dict(nested))
        else:
            merged.update(dict(value))
    return merged


def get_model_preparation_options(
    config: AnalysisConfigLike = None,
    *,
    strict: Optional[bool] = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> ModelPreparationOptions:
    """Resolve preparation options from analysis configuration and overrides."""

    analysis_config = coerce_analysis_config(config)
    values = _extract_model_preparation_config(analysis_config)
    values.setdefault("strict", analysis_config.runtime.is_strict)
    values.setdefault(
        "preserve_existing",
        analysis_config.runtime.reuse_results,
    )
    if overrides:
        values.update(dict(overrides))
    if strict is not None:
        values["strict"] = bool(strict)
    return ModelPreparationOptions.from_mapping(values, strict=False)


# 9.6. Utility-module adapters
# -----------------------------------------------------------------------------

def _model_preparation_utils_module() -> ModuleType:
    """Return the loaded utilities module used by model preparation."""

    module = load_analysis_module("utils", required=True)
    if module is None:  # pragma: no cover - guarded by required=True
        raise AnalysisDependencyError(
            "The DockAnalyzer utilities module is unavailable.",
            stage=STAGE_MODEL_PREPARATION,
        )
    return module


def _utils_callable(name: str) -> Optional[Callable[..., Any]]:
    """Return one callable utility symbol when available."""

    module = _model_preparation_utils_module()
    value = getattr(module, name, None)
    return value if callable(value) else None


def _call_utils(
    name: str,
    *args: Any,
    default: Any = None,
    **kwargs: Any,
) -> Any:
    """Call one optional utility function with a deterministic fallback."""

    function = _utils_callable(name)
    if function is None:
        return default
    try:
        return function(*args, **kwargs)
    except (AttributeError, KeyError, TypeError, ValueError, IndexError):
        return default


def get_preparation_model_atom_count(model: Any) -> Optional[int]:
    """Return a non-negative atom count when it can be determined."""

    if model is None:
        return None
    value = _call_utils("get_atom_count", model, default=None)
    if value is None:
        atoms = get_first_object_value(
            model,
            ("atoms", "atom_collection", "atom_list"),
            default=MISSING_VALUE,
        )
        if not is_missing_value(atoms):
            try:
                value = len(atoms)
            except (TypeError, AttributeError):
                value = None
    if value is None:
        return None
    try:
        return normalize_integer(value, minimum=0)
    except (TypeError, ValueError):
        return None


def get_preparation_model_residue_count(model: Any) -> Optional[int]:
    """Return a non-negative residue count when it can be determined."""

    if model is None:
        return None
    value = _call_utils("get_residue_count", model, default=None)
    if value is None:
        residues = get_first_object_value(
            model,
            ("residues", "residue_collection", "residue_list"),
            default=MISSING_VALUE,
        )
        if not is_missing_value(residues):
            try:
                value = len(residues)
            except (TypeError, AttributeError):
                value = None
    if value is None:
        return None
    try:
        return normalize_integer(value, minimum=0)
    except (TypeError, ValueError):
        return None


def get_preparation_model_identifier(model: Any) -> Optional[str]:
    """Return a stable model identifier when available."""

    if model is None:
        return None
    for utility_name in ("get_model_atomspec", "get_model_id"):
        value = _call_utils(utility_name, model, default=None)
        identifier = normalize_optional_identifier(value)
        if identifier:
            return identifier
    return resolve_object_identifier(model)


def get_preparation_model_name(model: Any, *, default: str = "model") -> str:
    """Return a human-readable molecular-model name."""

    value = _call_utils("get_model_name", model, default=None)
    if value is None:
        return resolve_object_name(model, default=default)
    return normalize_text(value, default=default)


def discover_preparation_ligand(pose: Any) -> Any:
    """Extract the ligand representation from a pose without chemistry analysis."""

    if pose is None:
        return None
    function = _utils_callable("get_ligand_from_pose")
    if function is not None:
        try:
            return function(pose)
        except (TypeError, ValueError, AttributeError, IndexError):
            pass
    return discover_ligand_from_pose(pose)


# 9.7. Names, fingerprints and metadata
# -----------------------------------------------------------------------------

def sanitize_dock_model_name(
    value: Any,
    *,
    fallback: str = DEFAULT_DOCK_MODEL_NAME_PREFIX,
) -> str:
    """Return a stable DockModel name with filesystem-safe separators."""

    text = normalize_text(value, default=fallback)
    text = re.sub(r"\s+", "_", text.strip())
    text = re.sub(r"[^A-Za-z0-9_.-]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_.-")
    if not text:
        text = fallback
    return text[:MAX_DOCK_MODEL_NAME_LENGTH]


def generate_prepared_dock_model_name(
    pose: Any,
    index: int,
    *,
    prefix: str = DEFAULT_DOCK_MODEL_NAME_PREFIX,
) -> str:
    """Generate a deterministic name for one prepared pose."""

    function = _utils_callable("generate_dock_model_name")
    if function is not None:
        try:
            value = function(pose, index + 1)
        except (TypeError, ValueError, AttributeError):
            value = None
        if value:
            return sanitize_dock_model_name(value, fallback=prefix)
    pose_name = get_preparation_model_name(pose, default=prefix)
    identifier = get_preparation_model_identifier(pose)
    suffix = identifier or f"{index + 1:03d}"
    return sanitize_dock_model_name(
        f"{pose_name}_{suffix}",
        fallback=f"{prefix}_{index + 1:03d}",
    )


def build_model_preparation_fingerprint(
    receptor: Any,
    pose: Any,
    ligand: Any,
    *,
    index: int,
    options: ModelPreparationOptions,
) -> str:
    """Return a stable preparation fingerprint without serializing molecular data."""

    payload = {
        "schema_version": PREPARATION_SCHEMA_VERSION,
        "index": index,
        "receptor": stable_object_fingerprint(receptor),
        "pose": stable_object_fingerprint(pose),
        "ligand": stable_object_fingerprint(ligand),
        "options": options.to_dict(),
    }
    return sha256(
        json.dumps(
            to_json_compatible(payload),
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def build_dock_model_preparation_metadata(
    receptor: Any,
    pose: Any,
    ligand: Any,
    *,
    index: int,
    name: str,
    options: ModelPreparationOptions,
    action: Any,
) -> Dict[str, Any]:
    """Build non-chemical metadata describing model preparation."""

    pose_identifier = get_preparation_model_identifier(pose)
    receptor_identifier = get_preparation_model_identifier(receptor)
    ligand_identifier = get_preparation_model_identifier(ligand)
    atom_count = get_preparation_model_atom_count(pose)
    residue_count = get_preparation_model_residue_count(pose)
    return {
        PREPARATION_VERSION_KEY: PREPARATION_SCHEMA_VERSION,
        "prepared_at": _utc_timestamp(),
        "action": canonicalize_model_preparation_action(action).value,
        "name": name,
        PREPARATION_POSE_INDEX_KEY: index + 1,
        PREPARATION_POSE_IDENTIFIER_KEY: pose_identifier,
        PREPARATION_RECEPTOR_IDENTIFIER_KEY: receptor_identifier,
        PREPARATION_LIGAND_IDENTIFIER_KEY: ligand_identifier,
        PREPARATION_ATOM_COUNT_KEY: atom_count,
        PREPARATION_RESIDUE_COUNT_KEY: residue_count,
        PREPARATION_FINGERPRINT_KEY: build_model_preparation_fingerprint(
            receptor,
            pose,
            ligand,
            index=index,
            options=options,
        ),
        "receptor_name": get_preparation_model_name(
            receptor,
            default="receptor",
        ) if receptor is not None else None,
        "pose_name": get_preparation_model_name(pose, default=name),
        "ligand_name": get_preparation_model_name(
            ligand,
            default="ligand",
        ) if ligand is not None else None,
    }


# 9.8. Existing result inspection
# -----------------------------------------------------------------------------

def _value_contains_result(value: Any, *, field_name: str) -> bool:
    """Return whether one DockModel field contains a meaningful result."""

    if value is None or is_missing_value(value):
        return False
    if field_name == DOCK_MODEL_FIELD_SCORE:
        return True
    if isinstance(value, Mapping):
        return any(_value_contains_result(item, field_name=field_name) for item in value.values())
    if isinstance(value, (str, bytes, bytearray)):
        return bool(value)
    try:
        return len(value) > 0
    except (TypeError, AttributeError):
        return bool(value)


def inspect_dock_model_existing_results(model: Any) -> Tuple[str, ...]:
    """Return result fields already populated on a DockModel-like object."""

    detected: List[str] = []
    for field_name in PREPARATION_RESULT_FIELDS:
        value = get_object_value(model, field_name, default=MISSING_VALUE)
        if _value_contains_result(value, field_name=field_name):
            detected.append(field_name)
    return tuple(detected)


def has_existing_dock_model_results(model: Any) -> bool:
    """Return whether a DockModel-like object contains analysis results."""

    return bool(inspect_dock_model_existing_results(model))


# 9.9. DockModel copying and coercion
# -----------------------------------------------------------------------------

def _copy_dock_model(model: DockModel) -> DockModel:
    """Create a shallow molecular copy with independent mutable containers."""

    copied = DockModel(
        name=model.name,
        pose=model.pose,
        receptor=model.receptor,
        ligand=model.ligand,
        contacts=list(model.contacts),
        hbonds=list(model.hbonds),
        hydrophobic=list(model.hydrophobic),
        pi={key: list(values) for key, values in model.pi.items()},
        score=model.score,
        statistics=copy.deepcopy(model.statistics),
        files=dict(model.files),
        metadata=copy.deepcopy(model.metadata),
    )
    saltbridge = get_object_value(
        model,
        DOCK_MODEL_FIELD_SALTBRIDGE,
        default=MISSING_VALUE,
    )
    if not is_missing_value(saltbridge):
        try:
            setattr(copied, DOCK_MODEL_FIELD_SALTBRIDGE, list(saltbridge or []))
        except TypeError:
            setattr(copied, DOCK_MODEL_FIELD_SALTBRIDGE, saltbridge)
    return copied


def coerce_dock_model(
    value: Any,
    *,
    receptor: Any = None,
    pose: Any = None,
    ligand: Any = None,
    index: int = 0,
    name: Optional[str] = None,
    copy_existing: bool = False,
) -> Tuple[DockModel, ModelPreparationAction]:
    """Convert a DockModel-like value into the canonical DockModel class."""

    if isinstance(value, DockModel):
        if copy_existing:
            return _copy_dock_model(value), ModelPreparationAction.COPY
        return value, ModelPreparationAction.PRESERVE

    source = object_to_mapping(value, include_private=False)
    resolved_pose = pose if pose is not None else source.get(DOCK_MODEL_FIELD_POSE)
    resolved_receptor = (
        receptor
        if receptor is not None
        else source.get(DOCK_MODEL_FIELD_RECEPTOR)
    )
    resolved_ligand = (
        ligand
        if ligand is not None
        else source.get(DOCK_MODEL_FIELD_LIGAND)
    )
    resolved_name = name or source.get(DOCK_MODEL_FIELD_NAME)
    if not resolved_name:
        resolved_name = generate_prepared_dock_model_name(
            resolved_pose,
            index,
        )

    pi_value = source.get(DOCK_MODEL_FIELD_PI)
    if not isinstance(pi_value, Mapping):
        pi_value = {"stacking": [], "cation": []}
    model = DockModel(
        name=sanitize_dock_model_name(resolved_name),
        pose=resolved_pose,
        receptor=resolved_receptor,
        ligand=resolved_ligand,
        contacts=source.get(DOCK_MODEL_FIELD_CONTACTS, []),
        hbonds=source.get(DOCK_MODEL_FIELD_HBONDS, []),
        hydrophobic=source.get(DOCK_MODEL_FIELD_HYDROPHOBIC, []),
        pi=pi_value,
        score=source.get(DOCK_MODEL_FIELD_SCORE),
        statistics=source.get(DOCK_MODEL_FIELD_STATISTICS, {}),
        files=source.get(DOCK_MODEL_FIELD_FILES, {}),
        metadata=source.get(DOCK_MODEL_FIELD_METADATA, {}),
    )
    saltbridge = source.get(DOCK_MODEL_FIELD_SALTBRIDGE, MISSING_VALUE)
    if not is_missing_value(saltbridge):
        setattr(
            model,
            DOCK_MODEL_FIELD_SALTBRIDGE,
            normalize_object_sequence(saltbridge),
        )
    return model, ModelPreparationAction.COERCE


def create_dock_model_from_pose(
    receptor: Any,
    pose: Any,
    *,
    ligand: Any = None,
    index: int = 0,
    name: Optional[str] = None,
    options: Optional[ModelPreparationOptions] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> DockModel:
    """Create one canonical DockModel from resolved molecular components."""

    resolved_options = options or ModelPreparationOptions()
    resolved_ligand = ligand
    if resolved_ligand is None and resolved_options.discover_ligand:
        resolved_ligand = discover_preparation_ligand(pose)
    resolved_name = name or generate_prepared_dock_model_name(
        pose,
        index,
        prefix=resolved_options.name_prefix,
    )
    base_metadata = normalize_metadata_mapping(metadata)
    if resolved_options.store_preparation_metadata:
        base_metadata[PREPARATION_METADATA_KEY] = (
            build_dock_model_preparation_metadata(
                receptor,
                pose,
                resolved_ligand,
                index=index,
                name=resolved_name,
                options=resolved_options,
                action=ModelPreparationAction.CREATE,
            )
        )
    return DockModel(
        name=resolved_name,
        pose=pose,
        receptor=receptor if resolved_options.attach_receptor else None,
        ligand=resolved_ligand if resolved_options.attach_ligand else None,
        metadata=base_metadata,
    )


# 9.10. DockModel repair and normalization
# -----------------------------------------------------------------------------

def _set_dock_model_field(
    model: Any,
    field_name: str,
    value: Any,
) -> bool:
    """Set one DockModel field and report whether the value changed."""

    current = get_object_value(model, field_name, default=MISSING_VALUE)
    if not is_missing_value(current) and current is value:
        return False
    if not is_missing_value(current) and current == value:
        return False
    set_object_value(model, field_name, value)
    return True


def repair_dock_model(
    model: DockModel,
    *,
    receptor: Any = None,
    pose: Any = None,
    ligand: Any = None,
    index: int = 0,
    options: Optional[ModelPreparationOptions] = None,
) -> Tuple[DockModel, Tuple[str, ...]]:
    """Fill missing structural DockModel fields without clearing results."""

    resolved_options = options or ModelPreparationOptions()
    repaired: List[str] = []

    if pose is not None and (
        get_object_value(model, DOCK_MODEL_FIELD_POSE, default=None) is None
    ):
        if _set_dock_model_field(model, DOCK_MODEL_FIELD_POSE, pose):
            repaired.append(DOCK_MODEL_FIELD_POSE)

    effective_pose = get_object_value(
        model,
        DOCK_MODEL_FIELD_POSE,
        default=pose,
    )
    if resolved_options.attach_receptor and receptor is not None and (
        get_object_value(model, DOCK_MODEL_FIELD_RECEPTOR, default=None) is None
    ):
        if _set_dock_model_field(model, DOCK_MODEL_FIELD_RECEPTOR, receptor):
            repaired.append(DOCK_MODEL_FIELD_RECEPTOR)

    effective_ligand = get_object_value(
        model,
        DOCK_MODEL_FIELD_LIGAND,
        default=None,
    )
    if effective_ligand is None:
        effective_ligand = ligand
    if effective_ligand is None and resolved_options.discover_ligand:
        effective_ligand = discover_preparation_ligand(effective_pose)
    if resolved_options.attach_ligand and effective_ligand is not None and (
        get_object_value(model, DOCK_MODEL_FIELD_LIGAND, default=None) is None
    ):
        if _set_dock_model_field(model, DOCK_MODEL_FIELD_LIGAND, effective_ligand):
            repaired.append(DOCK_MODEL_FIELD_LIGAND)

    current_name = get_object_value(model, DOCK_MODEL_FIELD_NAME, default=None)
    if not normalize_optional_text(current_name):
        generated = generate_prepared_dock_model_name(
            effective_pose,
            index,
            prefix=resolved_options.name_prefix,
        )
        if _set_dock_model_field(model, DOCK_MODEL_FIELD_NAME, generated):
            repaired.append(DOCK_MODEL_FIELD_NAME)

    for collection_field in (
        DOCK_MODEL_FIELD_CONTACTS,
        DOCK_MODEL_FIELD_HBONDS,
        DOCK_MODEL_FIELD_HYDROPHOBIC,
    ):
        current = get_object_value(model, collection_field, default=MISSING_VALUE)
        if is_missing_value(current) or current is None:
            if _set_dock_model_field(model, collection_field, []):
                repaired.append(collection_field)

    pi_value = get_object_value(model, DOCK_MODEL_FIELD_PI, default=MISSING_VALUE)
    if is_missing_value(pi_value) or pi_value is None:
        if _set_dock_model_field(
            model,
            DOCK_MODEL_FIELD_PI,
            {"stacking": [], "cation": []},
        ):
            repaired.append(DOCK_MODEL_FIELD_PI)

    for mapping_field in (
        DOCK_MODEL_FIELD_STATISTICS,
        DOCK_MODEL_FIELD_FILES,
        DOCK_MODEL_FIELD_METADATA,
    ):
        current = get_object_value(model, mapping_field, default=MISSING_VALUE)
        if is_missing_value(current) or current is None:
            if _set_dock_model_field(model, mapping_field, {}):
                repaired.append(mapping_field)

    return model, tuple(unique_preserving_order(repaired))


def update_dock_model_preparation_metadata(
    model: Any,
    *,
    receptor: Any,
    pose: Any,
    ligand: Any,
    index: int,
    options: ModelPreparationOptions,
    action: Any,
    existing_result_fields: Sequence[str] = (),
    repaired_fields: Sequence[str] = (),
) -> None:
    """Attach preparation metadata while preserving user-provided metadata."""

    if not options.store_preparation_metadata:
        return
    metadata = normalize_metadata_mapping(
        get_object_value(model, DOCK_MODEL_FIELD_METADATA, default={})
    )
    name = normalize_text(
        get_object_value(model, DOCK_MODEL_FIELD_NAME, default=None),
        default=generate_prepared_dock_model_name(
            pose,
            index,
            prefix=options.name_prefix,
        ),
    )
    preparation = build_dock_model_preparation_metadata(
        receptor,
        pose,
        ligand,
        index=index,
        name=name,
        options=options,
        action=action,
    )
    preparation[PREPARATION_EXISTING_RESULTS_KEY] = list(existing_result_fields)
    preparation["repaired_fields"] = list(repaired_fields)
    previous = metadata.get(PREPARATION_METADATA_KEY)
    if isinstance(previous, Mapping):
        history = normalize_object_sequence(
            metadata.get(PREPARATION_HISTORY_KEY, ())
        )
        history.append(dict(previous))
        metadata[PREPARATION_HISTORY_KEY] = history[-MAX_ANALYSIS_HISTORY:]
    metadata[PREPARATION_METADATA_KEY] = preparation
    set_object_value(model, DOCK_MODEL_FIELD_METADATA, metadata)


# 9.11. Structural validation
# -----------------------------------------------------------------------------

def validate_prepared_dock_model(
    model: Any,
    *,
    options: Optional[ModelPreparationOptions] = None,
    expected_receptor: Any = None,
    expected_pose: Any = None,
    strict: bool = False,
) -> Dict[str, Any]:
    """Validate a prepared DockModel without invoking chemical perception."""

    resolved_options = options or ModelPreparationOptions()
    errors: List[str] = []
    warnings_list: List[str] = []

    if not is_dock_model_like(model):
        errors.append("The prepared value is not DockModel-like.")

    name = normalize_optional_text(
        get_object_value(model, DOCK_MODEL_FIELD_NAME, default=None)
    )
    if not name:
        errors.append("The prepared DockModel does not have a valid name.")

    receptor = get_object_value(
        model,
        DOCK_MODEL_FIELD_RECEPTOR,
        default=None,
    )
    pose = get_object_value(model, DOCK_MODEL_FIELD_POSE, default=None)
    ligand = get_object_value(model, DOCK_MODEL_FIELD_LIGAND, default=None)

    if pose is None:
        errors.append("The prepared DockModel does not contain a pose.")
    if receptor is None and not resolved_options.allow_missing_receptor:
        errors.append("The prepared DockModel does not contain a receptor.")
    if receptor is not None and pose is receptor and resolved_options.reject_receptor_as_pose:
        errors.append("The receptor cannot also be used as the docking pose.")
    if expected_pose is not None and pose is not expected_pose:
        warnings_list.append(
            "The prepared DockModel pose differs from the resolved pose object."
        )
    if expected_receptor is not None and receptor is not expected_receptor:
        warnings_list.append(
            "The prepared DockModel receptor differs from the resolved receptor."
        )

    atom_count = get_preparation_model_atom_count(pose)
    residue_count = get_preparation_model_residue_count(pose)
    if atom_count == 0 and not resolved_options.allow_empty_pose:
        errors.append("The docking pose does not contain atoms.")
    elif atom_count is None:
        warnings_list.append("The docking-pose atom count could not be determined.")
    if residue_count == 0 and atom_count not in (None, 0):
        warnings_list.append("The docking pose has atoms but no resolved residues.")
    if ligand is None:
        warnings_list.append("No explicit ligand object is attached to the DockModel.")

    for field_name in (
        DOCK_MODEL_FIELD_CONTACTS,
        DOCK_MODEL_FIELD_HBONDS,
        DOCK_MODEL_FIELD_HYDROPHOBIC,
    ):
        value = get_object_value(model, field_name, default=MISSING_VALUE)
        if is_missing_value(value):
            errors.append(f"The DockModel is missing the {field_name!r} field.")
        elif isinstance(value, Mapping):
            warnings_list.append(
                f"DockModel.{field_name} is a mapping rather than a sequence."
            )

    pi_value = get_object_value(model, DOCK_MODEL_FIELD_PI, default=MISSING_VALUE)
    if is_missing_value(pi_value):
        errors.append("The DockModel is missing the 'pi' field.")
    elif not isinstance(pi_value, Mapping):
        errors.append("DockModel.pi must be a mapping.")

    for field_name in (
        DOCK_MODEL_FIELD_STATISTICS,
        DOCK_MODEL_FIELD_FILES,
        DOCK_MODEL_FIELD_METADATA,
    ):
        value = get_object_value(model, field_name, default=MISSING_VALUE)
        if is_missing_value(value):
            errors.append(f"The DockModel is missing the {field_name!r} field.")
        elif not isinstance(value, Mapping):
            errors.append(f"DockModel.{field_name} must be a mapping.")

    result = {
        "valid": not errors,
        "errors": unique_preserving_order(errors),
        "warnings": unique_preserving_order(warnings_list),
        "name": name,
        "receptor_resolved": receptor is not None,
        "pose_resolved": pose is not None,
        "ligand_resolved": ligand is not None,
        "atom_count": atom_count,
        "residue_count": residue_count,
        "existing_result_fields": list(
            inspect_dock_model_existing_results(model)
        ),
    }
    if strict and errors:
        raise AnalysisValidationError(
            "Prepared DockModel validation failed: " + " ".join(errors),
            stage=STAGE_MODEL_PREPARATION,
            details=result,
        )
    return result


# 9.12. Single-record preparation
# -----------------------------------------------------------------------------

def prepare_dock_model_record(
    *,
    index: int,
    receptor: Any,
    pose: Any = None,
    ligand: Any = None,
    dock_model: Any = None,
    options: Optional[ModelPreparationOptions] = None,
) -> PreparedDockModelRecord:
    """Prepare one DockModel and return a complete preparation record."""

    resolved_options = options or ModelPreparationOptions()
    warnings_list: List[str] = []
    errors: List[str] = []
    repaired_fields: Tuple[str, ...] = ()

    if dock_model is not None:
        try:
            model, action = coerce_dock_model(
                dock_model,
                receptor=receptor,
                pose=pose,
                ligand=ligand,
                index=index,
                copy_existing=resolved_options.copy_existing,
            )
        except Exception as exc:
            raise AnalysisIntegrationError(
                "A DockModel-like input could not be coerced.",
                stage=STAGE_MODEL_PREPARATION,
                details={"index": index},
                cause=exc,
            ) from exc
        if pose is None:
            pose = get_object_value(model, DOCK_MODEL_FIELD_POSE, default=None)
        model_receptor = get_object_value(
            model,
            DOCK_MODEL_FIELD_RECEPTOR,
            default=None,
        )
        if receptor is None:
            receptor = model_receptor
        if ligand is None:
            ligand = get_object_value(
                model,
                DOCK_MODEL_FIELD_LIGAND,
                default=None,
            )
    else:
        model = create_dock_model_from_pose(
            receptor,
            pose,
            ligand=ligand,
            index=index,
            options=resolved_options,
        )
        action = ModelPreparationAction.CREATE
        ligand = get_object_value(
            model,
            DOCK_MODEL_FIELD_LIGAND,
            default=ligand,
        )

    if resolved_options.repair_missing_fields:
        model, repaired_fields = repair_dock_model(
            model,
            receptor=receptor,
            pose=pose,
            ligand=ligand,
            index=index,
            options=resolved_options,
        )
        if repaired_fields and action is ModelPreparationAction.PRESERVE:
            action = ModelPreparationAction.REPAIR

    receptor = get_object_value(
        model,
        DOCK_MODEL_FIELD_RECEPTOR,
        default=receptor,
    )
    pose = get_object_value(model, DOCK_MODEL_FIELD_POSE, default=pose)
    ligand = get_object_value(
        model,
        DOCK_MODEL_FIELD_LIGAND,
        default=ligand,
    )

    existing_result_fields = (
        inspect_dock_model_existing_results(model)
        if resolved_options.inspect_existing_results
        else ()
    )
    if existing_result_fields:
        warnings_list.append(
            "Existing analysis results were preserved for fields: "
            + ", ".join(existing_result_fields)
            + "."
        )

    validation = validate_prepared_dock_model(
        model,
        options=resolved_options,
        expected_receptor=receptor,
        expected_pose=pose,
        strict=False,
    ) if resolved_options.validate_models else {
        "valid": True,
        "errors": [],
        "warnings": [],
        "atom_count": get_preparation_model_atom_count(pose),
        "residue_count": get_preparation_model_residue_count(pose),
    }
    warnings_list.extend(validation.get("warnings", ()))
    errors.extend(validation.get("errors", ()))

    if errors:
        state = ModelPreparationState.INVALID
    elif warnings_list:
        state = ModelPreparationState.PARTIAL
    else:
        state = ModelPreparationState.READY

    update_dock_model_preparation_metadata(
        model,
        receptor=receptor,
        pose=pose,
        ligand=ligand,
        index=index,
        options=resolved_options,
        action=action,
        existing_result_fields=existing_result_fields,
        repaired_fields=repaired_fields,
    )

    return PreparedDockModelRecord(
        dock_model=model,
        index=index,
        action=action,
        state=state,
        receptor=receptor,
        pose=pose,
        ligand=ligand,
        name=get_object_value(model, DOCK_MODEL_FIELD_NAME, default=None),
        receptor_identifier=get_preparation_model_identifier(receptor),
        pose_identifier=get_preparation_model_identifier(pose),
        ligand_identifier=get_preparation_model_identifier(ligand),
        atom_count=validation.get("atom_count"),
        residue_count=validation.get("residue_count"),
        existing_result_fields=existing_result_fields,
        repaired_fields=repaired_fields,
        warnings=warnings_list,
        errors=errors,
        metadata={
            "validation_performed": resolved_options.validate_models,
            "preparation_fingerprint": build_model_preparation_fingerprint(
                receptor,
                pose,
                ligand,
                index=index,
                options=resolved_options,
            ),
        },
    )


# 9.13. Multi-model preparation workflow
# -----------------------------------------------------------------------------

def _aligned_ligand(
    ligands: Sequence[Any],
    index: int,
    pose: Any,
    *,
    discover: bool,
) -> Any:
    """Return an explicitly aligned or discovered ligand."""

    if index < len(ligands) and ligands[index] is not None:
        return ligands[index]
    return discover_preparation_ligand(pose) if discover else None


def _validate_preparation_input_duplicates(
    resolved: ResolvedAnalysisInput,
    options: ModelPreparationOptions,
) -> List[str]:
    """Return duplicate and receptor-role input errors."""

    errors: List[str] = []
    if resolved.dock_models:
        poses = [
            get_object_value(model, DOCK_MODEL_FIELD_POSE, default=None)
            for model in resolved.dock_models
        ]
        poses = [pose for pose in poses if pose is not None]
    else:
        poses = list(resolved.poses)
    pose_ids = [id(pose) for pose in poses]
    if options.reject_duplicate_poses and len(pose_ids) != len(set(pose_ids)):
        errors.append("The preparation input contains duplicate pose objects.")
    if (
        options.reject_receptor_as_pose
        and resolved.receptor is not None
        and any(pose is resolved.receptor for pose in poses)
    ):
        errors.append("The resolved receptor is also present as a docking pose.")
    return errors


def prepare_resolved_dock_models(
    resolved: ResolvedAnalysisInput,
    *,
    options: Optional[ModelPreparationOptions] = None,
    config: AnalysisConfigLike = None,
) -> ModelPreparationResult:
    """Prepare all DockModel objects represented by resolved analysis input."""

    if not isinstance(resolved, ResolvedAnalysisInput):
        raise TypeError("resolved must be a ResolvedAnalysisInput instance.")
    resolved_options = options or get_model_preparation_options(
        config or resolved.request.config
    )
    result = ModelPreparationResult(
        resolved_input=resolved,
        options=resolved_options,
        receptor=resolved.receptor,
        metadata={
            "source_kind": resolved.source_kind.value,
            "mode": resolved.mode,
            "request_id": resolved.request.request_id,
            "started_at": _utc_timestamp(),
        },
    )

    if resolved.mode == ANALYSIS_MODE_BATCH:
        message = (
            "Batch requests must be resolved and prepared independently by the "
            "batch orchestration layer."
        )
        result.warnings.append(message)
        result.metadata["deferred_batch_count"] = len(resolved.batch_requests)
        return result

    input_errors = _validate_preparation_input_duplicates(
        resolved,
        resolved_options,
    )
    if input_errors:
        result.errors.extend(input_errors)
        if resolved_options.strict:
            raise AnalysisInputError(
                "DockModel preparation input validation failed: "
                + " ".join(input_errors),
                stage=STAGE_MODEL_PREPARATION,
                details={"errors": input_errors},
            )

    source_models = list(resolved.dock_models)
    source_poses = list(resolved.poses)
    source_ligands = list(resolved.ligands)

    if not source_models and not source_poses:
        message = "No DockModel objects or docking poses are available for preparation."
        result.errors.append(message)
        if resolved_options.strict:
            raise AnalysisInputError(
                message,
                stage=STAGE_MODEL_PREPARATION,
            )
        return result

    item_count = len(source_models) if source_models else len(source_poses)
    if item_count > resolved.request.config.runtime.max_multipose_items:
        message = "The number of models exceeds the configured multipose limit."
        result.errors.append(message)
        if resolved_options.strict:
            raise AnalysisInputError(
                message,
                stage=STAGE_MODEL_PREPARATION,
                details={
                    "count": item_count,
                    "limit": resolved.request.config.runtime.max_multipose_items,
                },
            )
        item_count = resolved.request.config.runtime.max_multipose_items

    for index in range(item_count):
        if source_models:
            source_model = source_models[index]
            pose = get_object_value(
                source_model,
                DOCK_MODEL_FIELD_POSE,
                default=(source_poses[index] if index < len(source_poses) else None),
            )
            receptor = get_object_value(
                source_model,
                DOCK_MODEL_FIELD_RECEPTOR,
                default=resolved.receptor,
            )
            ligand = get_object_value(
                source_model,
                DOCK_MODEL_FIELD_LIGAND,
                default=None,
            )
            if ligand is None:
                ligand = _aligned_ligand(
                    source_ligands,
                    index,
                    pose,
                    discover=resolved_options.discover_ligand,
                )
        else:
            source_model = None
            pose = source_poses[index]
            receptor = resolved.receptor
            ligand = _aligned_ligand(
                source_ligands,
                index,
                pose,
                discover=resolved_options.discover_ligand,
            )

        try:
            record = prepare_dock_model_record(
                index=index,
                receptor=receptor,
                pose=pose,
                ligand=ligand,
                dock_model=source_model,
                options=resolved_options,
            )
        except AnalysisError as exc:
            message = f"DockModel preparation failed at index {index}: {exc}"
            result.errors.append(message)
            if resolved_options.strict:
                raise
            continue
        except Exception as exc:
            wrapped = AnalysisIntegrationError(
                f"DockModel preparation failed at index {index}.",
                stage=STAGE_MODEL_PREPARATION,
                details={"index": index},
                cause=exc,
            )
            result.errors.append(str(wrapped))
            if resolved_options.strict:
                raise wrapped from exc
            continue

        result.records.append(record)
        result.warnings.extend(record.warnings)
        result.errors.extend(record.errors)
        if record.ready:
            result.dock_models.append(record.dock_model)
            result.poses.append(record.pose)
            result.ligands.append(record.ligand)
        elif resolved_options.strict:
            raise AnalysisValidationError(
                f"Prepared DockModel {record.name!r} is invalid: "
                + " ".join(record.errors),
                stage=STAGE_MODEL_PREPARATION,
                details=record.to_dict(),
            )

    result.dock_models = unique_preserving_order(result.dock_models, key=id)
    result.warnings = unique_preserving_order(result.warnings)
    result.errors = unique_preserving_order(result.errors)
    result.metadata.update(
        {
            "finished_at": _utc_timestamp(),
            "prepared_count": result.prepared_count,
            "ready_count": result.ready_count,
            "input_item_count": item_count,
            "preparation_options": resolved_options.to_dict(),
        }
    )
    return result


# 9.14. Context integration
# -----------------------------------------------------------------------------

def apply_model_preparation_to_context(
    context: AnalysisContext,
    result: ModelPreparationResult,
    *,
    replace_existing: bool = True,
) -> AnalysisContext:
    """Attach prepared DockModel objects and metadata to a runtime context."""

    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance.")
    if not isinstance(result, ModelPreparationResult):
        raise TypeError("result must be a ModelPreparationResult instance.")

    if replace_existing or not context.dock_models:
        context.dock_models = list(result.dock_models)
    else:
        context.dock_models = unique_preserving_order(
            [*context.dock_models, *result.dock_models],
            key=id,
        )
    if replace_existing or not context.poses:
        context.poses = list(result.poses)
    if replace_existing or context.receptor is None:
        context.receptor = result.receptor

    context.set_stage_data(STAGE_MODEL_PREPARATION, result)
    context.set_shared("model_preparation", result)
    context.set_shared("prepared_dock_models", tuple(result.dock_models))
    context.metadata.update(
        {
            "prepared_dock_model_count": result.prepared_count,
            "prepared_model_ready_count": result.ready_count,
            "model_preparation_warning_count": len(result.warnings),
            "model_preparation_error_count": len(result.errors),
        }
    )
    return context


def prepare_context_models(
    context: AnalysisContext,
    *,
    options: Optional[ModelPreparationOptions] = None,
    resolve_input: bool = True,
) -> ModelPreparationResult:
    """Resolve and prepare all molecular models associated with a context."""

    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance.")
    context.raise_if_cancelled(stage=STAGE_MODEL_PREPARATION)
    resolved = context.get_shared("resolved_input")
    if not isinstance(resolved, ResolvedAnalysisInput):
        if not resolve_input:
            raise AnalysisStateError(
                "The analysis context does not contain resolved input.",
                stage=STAGE_MODEL_PREPARATION,
            )
        resolved = resolve_context_input(
            context,
            strict=context.config.runtime.is_strict,
        )
    preparation = prepare_resolved_dock_models(
        resolved,
        options=options,
        config=context.config,
    )
    apply_model_preparation_to_context(context, preparation)
    return preparation


def create_model_preparation_stage_result(
    preparation: ModelPreparationResult,
) -> AnalysisStageResult:
    """Adapt model preparation into the common stage-result structure."""

    if not isinstance(preparation, ModelPreparationResult):
        raise TypeError("preparation must be a ModelPreparationResult instance.")
    stage_result = AnalysisStageResult(
        stage=STAGE_MODEL_PREPARATION,
        required=True,
        input_summary={
            "source_kind": preparation.resolved_input.source_kind.value,
            "mode": preparation.resolved_input.mode,
            "item_count": preparation.resolved_input.item_count,
        },
        output_summary=preparation.summary(),
        statistics=preparation.summary(),
        metadata=dict(preparation.metadata),
    )
    stage_result.start()
    for message in preparation.warnings:
        stage_result.add_issue(
            AnalysisIssue(
                kind=IssueKind.WARNING,
                severity=IssueSeverity.WARNING,
                code="model_preparation_warning",
                message=message,
                stage=STAGE_MODEL_PREPARATION,
                recoverable=True,
                action=RecoveryAction.CONTINUE_PARTIAL,
                scope=FailureScope.STAGE,
            )
        )
    for message in preparation.errors:
        stage_result.add_issue(
            AnalysisIssue(
                kind=IssueKind.ERROR,
                severity=IssueSeverity.ERROR,
                code="model_preparation_error",
                message=message,
                stage=STAGE_MODEL_PREPARATION,
                recoverable=bool(preparation.dock_models),
                action=(
                    RecoveryAction.CONTINUE_PARTIAL
                    if preparation.dock_models
                    else RecoveryAction.ABORT_RUN
                ),
                scope=FailureScope.STAGE,
            )
        )
    if preparation.errors and not preparation.dock_models:
        stage_result.finish(StageStatus.FAILED, value=preparation)
    elif preparation.errors or preparation.has_partial_results:
        stage_result.partial(preparation)
    else:
        stage_result.succeed(preparation)
    return stage_result


# 9.15. Result validation and summaries
# -----------------------------------------------------------------------------

def validate_model_preparation_result(
    value: ModelPreparationResult,
    *,
    strict: bool = False,
) -> Dict[str, Any]:
    """Validate consistency of a complete model-preparation result."""

    if not isinstance(value, ModelPreparationResult):
        raise TypeError("value must be a ModelPreparationResult instance.")
    errors: List[str] = list(value.errors)
    warnings_list: List[str] = list(value.warnings)

    if len(value.dock_models) != len(value.poses):
        errors.append(
            "The prepared DockModel and pose collections have different lengths."
        )
    if value.ligands and len(value.ligands) != len(value.dock_models):
        errors.append(
            "The prepared ligand collection does not align with DockModel objects."
        )
    if len(value.records) < len(value.dock_models):
        errors.append(
            "The preparation record collection is shorter than the DockModel collection."
        )
    if len({id(model) for model in value.dock_models}) != len(value.dock_models):
        errors.append("The prepared DockModel collection contains duplicate objects.")
    if len({id(pose) for pose in value.poses}) != len(value.poses):
        errors.append("The prepared pose collection contains duplicate objects.")

    for record in value.records:
        if record.ready and record.dock_model not in value.dock_models:
            errors.append(
                f"Ready record {record.name!r} is absent from the DockModel collection."
            )
        if record.state is ModelPreparationState.INVALID and not record.errors:
            errors.append(
                f"Invalid record {record.name!r} does not describe its errors."
            )

    result = {
        "valid": not errors,
        "errors": unique_preserving_order(errors),
        "warnings": unique_preserving_order(warnings_list),
        "summary": value.summary(),
    }
    if strict and errors:
        raise AnalysisValidationError(
            "Model preparation result validation failed: " + " ".join(errors),
            stage=STAGE_MODEL_PREPARATION,
            details=result,
        )
    return result


def summarize_model_preparation(value: ModelPreparationResult) -> str:
    """Return a concise human-readable model-preparation summary."""

    validation = validate_model_preparation_result(value, strict=False)
    summary = value.summary()
    lines = [
        "DockModel preparation",
        f"Prepared models: {summary['prepared_count']}",
        f"Ready records: {summary['ready_count']}",
        f"Invalid records: {summary['invalid_count']}",
        f"Warnings: {summary['warning_count']}",
        f"Errors: {summary['error_count']}",
        f"Valid: {'yes' if validation['valid'] else 'no'}",
    ]
    return "\n".join(lines)


# 9.16. Internal convention validation
# -----------------------------------------------------------------------------

def validate_model_preparation_conventions() -> Dict[str, Any]:
    """Validate model-preparation constants, helpers and synthetic workflows."""

    failures: List[str] = []
    if tuple(item.value for item in ModelPreparationAction) != PREPARATION_ACTIONS:
        failures.append("ModelPreparationAction does not match PREPARATION_ACTIONS.")
    if tuple(item.value for item in ModelPreparationState) != PREPARATION_STATES:
        failures.append("ModelPreparationState does not match PREPARATION_STATES.")
    if canonicalize_model_preparation_action("reuse") is not ModelPreparationAction.PRESERVE:
        failures.append("The preparation action alias 'reuse' was not resolved.")
    if canonicalize_model_preparation_state("valid") is not ModelPreparationState.READY:
        failures.append("The preparation state alias 'valid' was not resolved.")

    options = ModelPreparationOptions.from_mapping(
        {
            "preserve_existing_dock_models": True,
            "discover_ligands": True,
            "allow_empty_poses": False,
            "strict": False,
        }
    )
    if not options.preserve_existing or not options.discover_ligand:
        failures.append("Aliased preparation options were not resolved correctly.")

    class _SyntheticResidue:
        def __init__(self, name: str) -> None:
            self.name = name

    class _SyntheticModel:
        def __init__(self, name: str, identifier: str, atom_count: int) -> None:
            self.name = name
            self.id_string = identifier
            self.atoms = [SimpleNamespace(name=f"A{index}") for index in range(atom_count)]
            self.residues = [_SyntheticResidue(name)] if atom_count else []

    receptor = _SyntheticModel("receptor", "1", 5)
    pose = _SyntheticModel("ligand_pose", "2", 3)
    request = create_analysis_request(
        {
            "receptor": receptor,
            "poses": [pose],
        },
        config={
            "runtime": {
                "failure_policy": "permissive",
                "max_multipose_items": 4,
            }
        },
    )
    resolved = resolve_analysis_input(request, strict=False)
    prepared = prepare_resolved_dock_models(
        resolved,
        options=replace(options, allow_missing_receptor=False),
    )
    if prepared.prepared_count != 1:
        failures.append("Synthetic preparation did not produce one DockModel.")
    elif prepared.dock_models[0].pose is not pose:
        failures.append("Synthetic preparation did not preserve the pose object.")
    elif prepared.dock_models[0].receptor is not receptor:
        failures.append("Synthetic preparation did not attach the receptor object.")
    elif PREPARATION_METADATA_KEY not in prepared.dock_models[0].metadata:
        failures.append("Synthetic preparation metadata was not attached.")

    validation = validate_model_preparation_result(prepared)
    if not validation["valid"]:
        failures.append("Synthetic model preparation failed result validation.")

    stage_result = create_model_preparation_stage_result(prepared)
    if not stage_result.succeeded:
        failures.append("Synthetic preparation did not produce a successful stage result.")

    existing = DockModel(
        name="existing_pose",
        receptor=receptor,
        pose=pose,
        ligand=pose.residues[0],
        contacts=[{"distance": 3.5}],
    )
    existing_resolved = ResolvedAnalysisInput(
        request=request,
        source_kind=InputSourceKind.DOCK_MODEL,
        mode=ANALYSIS_MODE_SINGLE_POSE,
        receptor=receptor,
        poses=(pose,),
        dock_models=(existing,),
    )
    existing_prepared = prepare_resolved_dock_models(
        existing_resolved,
        options=replace(options, inspect_existing_results=True),
    )
    if existing_prepared.dock_models[0] is not existing:
        failures.append("Existing DockModel identity was not preserved.")
    record = existing_prepared.records[0]
    if DOCK_MODEL_FIELD_CONTACTS not in record.existing_result_fields:
        failures.append("Existing contact results were not detected.")

    mapping_model = {
        "name": "mapping_pose",
        "receptor": receptor,
        "pose": pose,
        "ligand": pose.residues[0],
        "metadata": {"source": "mapping"},
    }
    coerced, action = coerce_dock_model(mapping_model, index=0)
    if not isinstance(coerced, DockModel) or action is not ModelPreparationAction.COERCE:
        failures.append("Mapping-based DockModel coercion failed.")

    if failures:
        raise RuntimeError(
            "Model-preparation convention validation failed: "
            + " ".join(failures)
        )

    return {
        "valid": True,
        "preparation_actions": len(PREPARATION_ACTIONS),
        "preparation_states": len(PREPARATION_STATES),
        "validated_cases": 16,
        "prepared_models": prepared.prepared_count,
    }


