# 10.2. Registry normalization and callable inspection
# -----------------------------------------------------------------------------


def canonicalize_registry_stage_name(
    value: Any,
    *,
    allow_custom: bool = DEFAULT_PLAN_ALLOW_CUSTOM_STAGES,
) -> str:
    """Return a canonical known or custom registry stage name."""

    try:
        return canonicalize_stage_name(value)
    except (TypeError, ValueError):
        if not allow_custom:
            raise

    token = _normalize_convention_token(value, field_name="registry stage name")
    if not token:
        raise AnalysisRegistryError("Registry stage names cannot be empty.")
    if len(token) > MAX_CUSTOM_STAGE_NAME_LENGTH:
        raise AnalysisRegistryError(
            "Registry stage names cannot exceed "
            f"{MAX_CUSTOM_STAGE_NAME_LENGTH} characters.",
            details={"stage": token},
        )
    if not re.fullmatch(r"[a-z][a-z0-9_]*", token):
        raise AnalysisRegistryError(
            f"Invalid custom stage name {token!r}.",
            details={"stage": token},
        )
    return token


def canonicalize_registry_stage_sequence(
    values: Any,
    *,
    allow_custom: bool = DEFAULT_PLAN_ALLOW_CUSTOM_STAGES,
    unique: bool = True,
    sort: bool = False,
) -> Tuple[str, ...]:
    """Return canonical stage names for registry and plan operations."""

    if values is None:
        return ()
    if isinstance(values, str):
        raw_values: Iterable[Any] = (values,)
    else:
        try:
            raw_values = tuple(values)
        except TypeError as exc:
            raise AnalysisRegistryError(
                "Stage names must be a string or iterable of strings."
            ) from exc

    result: List[str] = []
    seen: Set[str] = set()
    for raw_value in raw_values:
        stage = canonicalize_registry_stage_name(
            raw_value,
            allow_custom=allow_custom,
        )
        if unique and stage in seen:
            continue
        result.append(stage)
        seen.add(stage)

    if sort:
        result.sort(key=_registry_stage_sort_key)
    return tuple(result)


def _callable_identity(value: Optional[Callable[..., Any]]) -> Optional[str]:
    """Return a stable display identity for a callable."""

    if value is None:
        return None
    module_name = getattr(value, "__module__", None)
    qualified_name = getattr(value, "__qualname__", None)
    if module_name and qualified_name:
        return f"{module_name}.{qualified_name}"
    name = getattr(value, "__name__", None)
    if name:
        return str(name)
    return type(value).__qualname__


def _validate_optional_callable(
    value: Optional[Callable[..., Any]],
    *,
    field_name: str,
) -> Optional[Callable[..., Any]]:
    """Validate an optional callable field."""

    if value is not None and not callable(value):
        raise AnalysisRegistryError(f"{field_name} must be callable or None.")
    return value


def _registry_stage_sort_key(
    value: Any,
    *,
    registry_order: Optional[Mapping[str, int]] = None,
) -> Tuple[int, int, str]:
    """Return a deterministic order key for known and custom stages."""

    name = canonicalize_registry_stage_name(value)
    if name in PIPELINE_STAGE_INDEX:
        return (0, PIPELINE_STAGE_INDEX[name], name)
    if registry_order is not None and name in registry_order:
        return (1, registry_order[name], name)
    return (2, MAX_STAGE_REGISTRY_SIZE, name)


def _freeze_stage_metadata(value: Optional[Mapping[str, Any]]) -> Mapping[str, Any]:
    """Return immutable shallow-copied stage metadata."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        raise AnalysisRegistryError("Stage metadata must be a mapping.")
    return MappingProxyType(copy.deepcopy(dict(value)))


# 10.3. Stage definitions
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisStageDefinition:
    """Declarative definition of one stage in the analysis pipeline."""

    name: str
    executor: Optional[StageExecutor] = None
    dependencies: Tuple[str, ...] = ()
    ordering_predecessors: Tuple[str, ...] = ()
    required_modules: Tuple[str, ...] = ()
    predicate: Optional[StagePredicate] = None
    result_adapter: Optional[StageResultAdapter] = None
    validator: Optional[StageValidator] = None
    description: str = ""
    optional: bool = False
    internal: bool = False
    interaction: bool = False
    output: bool = False
    mutates_dock_model: bool = False
    requires_chimerax: bool = False
    supports_standalone: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        name = canonicalize_registry_stage_name(self.name)
        dependencies = canonicalize_registry_stage_sequence(self.dependencies)
        predecessors = canonicalize_registry_stage_sequence(
            self.ordering_predecessors
        )
        if name in dependencies:
            raise AnalysisRegistryError(
                f"Stage {name!r} cannot depend on itself.",
                stage=name,
            )
        if name in predecessors:
            raise AnalysisRegistryError(
                f"Stage {name!r} cannot be its own ordering predecessor.",
                stage=name,
            )

        modules: List[str] = []
        for raw_module in self.required_modules:
            try:
                module_name = canonicalize_analysis_module_name(raw_module)
            except Exception:
                module_name = _normalize_convention_token(
                    raw_module,
                    field_name="required module name",
                )
            if module_name not in modules:
                modules.append(module_name)

        executor = _validate_optional_callable(
            self.executor,
            field_name=f"Stage {name!r} executor",
        )
        predicate = _validate_optional_callable(
            self.predicate,
            field_name=f"Stage {name!r} predicate",
        )
        result_adapter = _validate_optional_callable(
            self.result_adapter,
            field_name=f"Stage {name!r} result adapter",
        )
        validator = _validate_optional_callable(
            self.validator,
            field_name=f"Stage {name!r} validator",
        )

        description = str(self.description or "").strip()
        if len(description) > MAX_STAGE_DESCRIPTION_LENGTH:
            raise AnalysisRegistryError(
                f"Stage {name!r} description is too long.",
                stage=name,
            )

        requires_chimerax = bool(self.requires_chimerax)
        supports_standalone = bool(self.supports_standalone)
        if requires_chimerax:
            supports_standalone = False

        object.__setattr__(self, "name", name)
        object.__setattr__(self, "executor", executor)
        object.__setattr__(self, "dependencies", dependencies)
        object.__setattr__(self, "ordering_predecessors", predecessors)
        object.__setattr__(self, "required_modules", tuple(modules))
        object.__setattr__(self, "predicate", predicate)
        object.__setattr__(self, "result_adapter", result_adapter)
        object.__setattr__(self, "validator", validator)
        object.__setattr__(self, "description", description)
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "internal", bool(self.internal))
        object.__setattr__(self, "interaction", bool(self.interaction))
        object.__setattr__(self, "output", bool(self.output))
        object.__setattr__(self, "mutates_dock_model", bool(self.mutates_dock_model))
        object.__setattr__(self, "requires_chimerax", requires_chimerax)
        object.__setattr__(self, "supports_standalone", supports_standalone)
        object.__setattr__(self, "metadata", _freeze_stage_metadata(self.metadata))

    @property
    def executor_registered(self) -> bool:
        """Return whether this definition has an executor."""

        return self.executor is not None

    @property
    def known_pipeline_stage(self) -> bool:
        """Return whether this is a built-in canonical pipeline stage."""

        return self.name in KNOWN_PIPELINE_STAGES

    def with_executor(
        self,
        executor: Optional[StageExecutor],
        *,
        result_adapter: Optional[StageResultAdapter] = None,
        validator: Optional[StageValidator] = None,
    ) -> "AnalysisStageDefinition":
        """Return a copy with execution callables replaced."""

        updates: Dict[str, Any] = {"executor": executor}
        if result_adapter is not None:
            updates["result_adapter"] = result_adapter
        if validator is not None:
            updates["validator"] = validator
        return replace(self, **updates)

    def to_dict(self, *, include_metadata: bool = True) -> Dict[str, Any]:
        """Return a serialization-ready stage definition."""

        result: Dict[str, Any] = {
            "name": self.name,
            "description": self.description,
            "dependencies": list(self.dependencies),
            "ordering_predecessors": list(self.ordering_predecessors),
            "required_modules": list(self.required_modules),
            "optional": self.optional,
            "internal": self.internal,
            "interaction": self.interaction,
            "output": self.output,
            "mutates_dock_model": self.mutates_dock_model,
            "requires_chimerax": self.requires_chimerax,
            "supports_standalone": self.supports_standalone,
            "executor_registered": self.executor_registered,
            "executor": _callable_identity(self.executor),
            "predicate": _callable_identity(self.predicate),
            "result_adapter": _callable_identity(self.result_adapter),
            "validator": _callable_identity(self.validator),
        }
        if include_metadata:
            result["metadata"] = to_json_compatible(dict(self.metadata))
        return result


# 10.4. Registry snapshots
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class StageRegistrySnapshot:
    """Immutable point-in-time snapshot of a stage registry."""

    definitions: Mapping[str, AnalysisStageDefinition]
    generation: int
    fingerprint: str
    created_at: str = field(default_factory=lambda: _utc_timestamp())

    def __post_init__(self) -> None:
        normalized: "OrderedDict[str, AnalysisStageDefinition]" = OrderedDict()
        for name, definition in self.definitions.items():
            canonical = canonicalize_registry_stage_name(name)
            if not isinstance(definition, AnalysisStageDefinition):
                raise AnalysisRegistryError(
                    "Registry snapshots require AnalysisStageDefinition values."
                )
            if canonical != definition.name:
                raise AnalysisRegistryError(
                    "Registry snapshot key does not match its stage definition.",
                    details={"key": canonical, "definition": definition.name},
                )
            normalized[canonical] = definition
        object.__setattr__(self, "definitions", MappingProxyType(normalized))
        object.__setattr__(self, "generation", max(0, int(self.generation)))
        object.__setattr__(self, "fingerprint", str(self.fingerprint))

    @property
    def names(self) -> Tuple[str, ...]:
        """Return stage names in snapshot registration order."""

        return tuple(self.definitions)

    def get(self, stage: Any) -> Optional[AnalysisStageDefinition]:
        """Return one stage definition or None."""

        return self.definitions.get(canonicalize_registry_stage_name(stage))

    def require(self, stage: Any) -> AnalysisStageDefinition:
        """Return one stage definition or raise a registry error."""

        canonical = canonicalize_registry_stage_name(stage)
        definition = self.definitions.get(canonical)
        if definition is None:
            raise AnalysisRegistryError(
                f"Stage {canonical!r} is not registered.",
                stage=canonical,
            )
        return definition

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready registry snapshot."""

        return {
            "schema": STAGE_REGISTRY_SCHEMA_NAME,
            "schema_version": STAGE_REGISTRY_SCHEMA_VERSION,
            "generation": self.generation,
            "fingerprint": self.fingerprint,
            "created_at": self.created_at,
            "stages": [
                definition.to_dict()
                for definition in self.definitions.values()
            ],
        }


# 10.5. Mutable stage registry
# -----------------------------------------------------------------------------


class AnalysisStageRegistry:
    """Thread-safe ordered registry of analysis stage definitions."""

    def __init__(
        self,
        definitions: Optional[Iterable[AnalysisStageDefinition]] = None,
    ) -> None:
        self._lock = threading.RLock()
        self._definitions: "OrderedDict[str, AnalysisStageDefinition]" = OrderedDict()
        self._generation = 0
        if definitions is not None:
            for definition in definitions:
                self.register(definition)

    def __len__(self) -> int:
        with self._lock:
            return len(self._definitions)

    def __iter__(self) -> Iterator[str]:
        return iter(self.names())

    def __contains__(self, stage: object) -> bool:
        try:
            canonical = canonicalize_registry_stage_name(stage)
        except Exception:
            return False
        with self._lock:
            return canonical in self._definitions

    @property
    def generation(self) -> int:
        """Return the registry mutation generation."""

        with self._lock:
            return self._generation

    def names(self) -> Tuple[str, ...]:
        """Return registered stage names in insertion order."""

        with self._lock:
            return tuple(self._definitions)

    def definitions(self) -> Tuple[AnalysisStageDefinition, ...]:
        """Return registered definitions in insertion order."""

        with self._lock:
            return tuple(self._definitions.values())

    def get(
        self,
        stage: Any,
        default: Optional[AnalysisStageDefinition] = None,
    ) -> Optional[AnalysisStageDefinition]:
        """Return one registered definition or a default value."""

        canonical = canonicalize_registry_stage_name(stage)
        with self._lock:
            return self._definitions.get(canonical, default)

    def require(self, stage: Any) -> AnalysisStageDefinition:
        """Return one registered definition or raise a registry error."""

        canonical = canonicalize_registry_stage_name(stage)
        with self._lock:
            definition = self._definitions.get(canonical)
        if definition is None:
            raise AnalysisRegistryError(
                f"Stage {canonical!r} is not registered.",
                stage=canonical,
                details={"registered_stages": list(self.names())},
            )
        return definition

    def register(
        self,
        definition: AnalysisStageDefinition,
        *,
        replace_existing: bool = False,
    ) -> AnalysisStageDefinition:
        """Register a stage definition and return the stored value."""

        if not isinstance(definition, AnalysisStageDefinition):
            raise AnalysisRegistryError(
                "Only AnalysisStageDefinition instances can be registered."
            )
        with self._lock:
            if len(self._definitions) >= MAX_STAGE_REGISTRY_SIZE:
                if definition.name not in self._definitions:
                    raise AnalysisRegistryError(
                        f"Stage registry cannot exceed {MAX_STAGE_REGISTRY_SIZE} entries."
                    )
            if definition.name in self._definitions and not replace_existing:
                raise AnalysisRegistryError(
                    f"Stage {definition.name!r} is already registered.",
                    stage=definition.name,
                )
            self._definitions[definition.name] = definition
            self._generation += 1
        return definition

    def replace(self, definition: AnalysisStageDefinition) -> AnalysisStageDefinition:
        """Replace an existing stage definition."""

        canonical = canonicalize_registry_stage_name(definition.name)
        with self._lock:
            if canonical not in self._definitions:
                raise AnalysisRegistryError(
                    f"Stage {canonical!r} is not registered.",
                    stage=canonical,
                )
        return self.register(definition, replace_existing=True)

    def unregister(
        self,
        stage: Any,
        *,
        missing_ok: bool = False,
    ) -> Optional[AnalysisStageDefinition]:
        """Remove one stage definition."""

        canonical = canonicalize_registry_stage_name(stage)
        with self._lock:
            definition = self._definitions.get(canonical)
            if definition is None:
                if missing_ok:
                    return None
                raise AnalysisRegistryError(
                    f"Stage {canonical!r} is not registered.",
                    stage=canonical,
                )
            del self._definitions[canonical]
            self._generation += 1
            return definition

    def clear(self) -> None:
        """Remove all stage definitions."""

        with self._lock:
            if self._definitions:
                self._definitions.clear()
                self._generation += 1

    def set_executor(
        self,
        stage: Any,
        executor: Optional[StageExecutor],
        *,
        result_adapter: Optional[StageResultAdapter] = None,
        validator: Optional[StageValidator] = None,
    ) -> AnalysisStageDefinition:
        """Replace execution callables for one registered stage."""

        definition = self.require(stage)
        updated = definition.with_executor(
            executor,
            result_adapter=result_adapter,
            validator=validator,
        )
        return self.replace(updated)

    def snapshot(self) -> StageRegistrySnapshot:
        """Return an immutable registry snapshot."""

        with self._lock:
            definitions = OrderedDict(self._definitions)
            generation = self._generation
        fingerprint = stage_registry_fingerprint(definitions.values())
        return StageRegistrySnapshot(
            definitions=definitions,
            generation=generation,
            fingerprint=fingerprint,
        )

    def clone(self) -> "AnalysisStageRegistry":
        """Return an independent registry with the same definitions."""

        with self._lock:
            definitions = tuple(self._definitions.values())
        clone = type(self)(definitions)
        clone._generation = self.generation
        return clone

    def validate(self, *, raise_on_error: bool = True) -> Tuple[str, ...]:
        """Validate the registry and return detected issues."""

        return validate_stage_registry(self, raise_on_error=raise_on_error)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready registry representation."""

        return self.snapshot().to_dict()


# 10.6. Default registry construction
# -----------------------------------------------------------------------------


def build_default_stage_definitions() -> Tuple[AnalysisStageDefinition, ...]:
    """Build definitions for every canonical pipeline stage."""

    definitions: List[AnalysisStageDefinition] = []
    for stage in PIPELINE_STAGE_ORDER:
        definitions.append(
            AnalysisStageDefinition(
                name=stage,
                dependencies=STAGE_DEPENDENCIES.get(stage, ()),
                ordering_predecessors=STAGE_ORDERING_PREDECESSORS.get(stage, ()),
                required_modules=STAGE_REQUIRED_MODULES.get(stage, ()),
                description=STAGE_DESCRIPTIONS.get(stage, ""),
                optional=stage in OPTIONAL_STAGES,
                internal=stage in INTERNAL_STAGES,
                interaction=stage in INTERACTION_STAGES,
                output=stage in OUTPUT_STAGES,
                mutates_dock_model=stage in STAGES_MUTATING_DOCK_MODEL,
                requires_chimerax=stage in STAGES_REQUIRING_CHIMERAX,
                supports_standalone=stage not in STAGES_REQUIRING_CHIMERAX,
                metadata={
                    "canonical_index": PIPELINE_STAGE_INDEX[stage],
                    "built_in": True,
                },
            )
        )
    return tuple(definitions)


def create_default_stage_registry() -> AnalysisStageRegistry:
    """Create a new registry containing all canonical stages."""

    return AnalysisStageRegistry(build_default_stage_definitions())


_DEFAULT_STAGE_REGISTRY_LOCK: Final[threading.RLock] = threading.RLock()
_DEFAULT_STAGE_REGISTRY: AnalysisStageRegistry = create_default_stage_registry()


def get_default_stage_registry(
    *,
    copy_registry: bool = False,
) -> AnalysisStageRegistry:
    """Return the process-wide default stage registry or an independent copy."""

    with _DEFAULT_STAGE_REGISTRY_LOCK:
        return (
            _DEFAULT_STAGE_REGISTRY.clone()
            if copy_registry
            else _DEFAULT_STAGE_REGISTRY
        )


def reset_default_stage_registry() -> AnalysisStageRegistry:
    """Reset and return the process-wide default stage registry."""

    global _DEFAULT_STAGE_REGISTRY
    with _DEFAULT_STAGE_REGISTRY_LOCK:
        _DEFAULT_STAGE_REGISTRY = create_default_stage_registry()
        return _DEFAULT_STAGE_REGISTRY


def register_analysis_stage(
    definition: AnalysisStageDefinition,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
    replace_existing: bool = False,
) -> AnalysisStageDefinition:
    """Register one stage in the selected or default registry."""

    target = registry or get_default_stage_registry()
    return target.register(definition, replace_existing=replace_existing)


def unregister_analysis_stage(
    stage: Any,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
    missing_ok: bool = False,
) -> Optional[AnalysisStageDefinition]:
    """Remove one stage from the selected or default registry."""

    target = registry or get_default_stage_registry()
    return target.unregister(stage, missing_ok=missing_ok)


def get_analysis_stage_definition(
    stage: Any,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Return one registered stage definition."""

    target = registry or get_default_stage_registry()
    return target.require(stage)


def registered_analysis_stages(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> Tuple[str, ...]:
    """Return stage names registered in the selected registry."""

    target = registry or get_default_stage_registry()
    return target.names()


def stage_registry_fingerprint(
    definitions: Optional[Iterable[AnalysisStageDefinition]] = None,
) -> str:
    """Return a deterministic fingerprint of stage definitions."""

    source = definitions
    if source is None:
        source = get_default_stage_registry().definitions()
    data = [
        definition.to_dict(include_metadata=True)
        for definition in source
    ]
    payload = json.dumps(
        data,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode(ANALYSIS_ENCODING)
    return sha256(payload).hexdigest()


# 10.7. Registry validation and dependency-cycle detection
# -----------------------------------------------------------------------------


def build_registry_dependency_graph(
    registry: Optional[AnalysisStageRegistry] = None,
    *,
    include_ordering: bool = False,
) -> Dict[str, Tuple[str, ...]]:
    """Return the registered dependency graph as stage-to-predecessors."""

    target = registry or get_default_stage_registry()
    names = set(target.names())
    graph: Dict[str, Tuple[str, ...]] = {}
    for definition in target.definitions():
        predecessors = list(definition.dependencies)
        if include_ordering:
            predecessors.extend(definition.ordering_predecessors)
        graph[definition.name] = tuple(
            dict.fromkeys(
                predecessor
                for predecessor in predecessors
                if predecessor in names
            )
        )
    return graph


def find_stage_dependency_cycles(
    graph: Mapping[str, Sequence[str]],
) -> Tuple[Tuple[str, ...], ...]:
    """Return unique directed cycles from a stage dependency graph."""

    normalized_graph: Dict[str, Tuple[str, ...]] = {
        canonicalize_registry_stage_name(stage): canonicalize_registry_stage_sequence(
            dependencies
        )
        for stage, dependencies in graph.items()
    }
    cycles: List[Tuple[str, ...]] = []
    seen_cycles: Set[Tuple[str, ...]] = set()
    state: Dict[str, int] = {}
    stack: List[str] = []
    positions: Dict[str, int] = {}

    def canonical_cycle(values: Sequence[str]) -> Tuple[str, ...]:
        core = list(values)
        if core and core[0] == core[-1]:
            core.pop()
        if not core:
            return ()
        rotations = [
            tuple(core[index:] + core[:index])
            for index in range(len(core))
        ]
        best = min(rotations)
        return (*best, best[0])

    def visit(node: str) -> None:
        state[node] = 1
        positions[node] = len(stack)
        stack.append(node)
        for dependency in normalized_graph.get(node, ()):
            if dependency not in normalized_graph:
                continue
            dependency_state = state.get(dependency, 0)
            if dependency_state == 0:
                visit(dependency)
            elif dependency_state == 1:
                start = positions[dependency]
                cycle = canonical_cycle((*stack[start:], dependency))
                if cycle and cycle not in seen_cycles:
                    seen_cycles.add(cycle)
                    cycles.append(cycle)
        stack.pop()
        positions.pop(node, None)
        state[node] = 2

    for stage in normalized_graph:
        if state.get(stage, 0) == 0:
            visit(stage)
    return tuple(sorted(cycles))


def validate_stage_registry(
    registry: Optional[AnalysisStageRegistry] = None,
    *,
    raise_on_error: bool = True,
) -> Tuple[str, ...]:
    """Validate a stage registry and return detected issues."""

    target = registry or get_default_stage_registry()
    definitions = target.definitions()
    names = target.names()
    name_set = set(names)
    issues: List[str] = []

    if len(names) != len(name_set):
        issues.append("The stage registry contains duplicate names.")
    if len(names) > MAX_STAGE_REGISTRY_SIZE:
        issues.append("The stage registry exceeds its maximum size.")

    for definition in definitions:
        if definition.name not in name_set:
            issues.append(
                f"Stage definition {definition.name!r} is not indexed by the registry."
            )
        missing_dependencies = set(definition.dependencies).difference(name_set)
        if missing_dependencies:
            issues.append(
                f"Stage {definition.name!r} has unregistered dependencies: "
                f"{sorted(missing_dependencies)!r}."
            )
        missing_predecessors = set(definition.ordering_predecessors).difference(name_set)
        if missing_predecessors:
            issues.append(
                f"Stage {definition.name!r} has unregistered ordering predecessors: "
                f"{sorted(missing_predecessors)!r}."
            )
        if definition.requires_chimerax and definition.supports_standalone:
            issues.append(
                f"Stage {definition.name!r} cannot require ChimeraX and support "
                "standalone execution simultaneously."
            )

    cycles = find_stage_dependency_cycles(
        build_registry_dependency_graph(target, include_ordering=False)
    )
    if cycles:
        issues.append(f"The stage registry contains dependency cycles: {cycles!r}.")

    if raise_on_error and issues:
        raise AnalysisRegistryError(" ".join(issues), details={"issues": issues})
    return tuple(issues)


# 10.8. Execution-plan entry and plan result
# -----------------------------------------------------------------------------


class PlanEntryDisposition(str, Enum):
    """Disposition assigned to one resolved execution-plan entry."""

    READY = PLAN_DISPOSITION_READY
    UNAVAILABLE = PLAN_DISPOSITION_UNAVAILABLE
    BLOCKED = PLAN_DISPOSITION_BLOCKED
    OMITTED = PLAN_DISPOSITION_OMITTED


@dataclass(frozen=True)
class StagePlanEntry:
    """Resolved execution information for one pipeline stage."""

    stage: str
    definition: AnalysisStageDefinition
    stage_config: AnalysisStageConfig
    position: int
    wave: int
    dependencies: Tuple[str, ...] = ()
    ordering_predecessors: Tuple[str, ...] = ()
    requested: bool = False
    dependency_included: bool = False
    required: bool = False
    available: bool = True
    blocked_by: Tuple[str, ...] = ()
    disposition: PlanEntryDisposition = PlanEntryDisposition.READY
    reason: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        stage = canonicalize_registry_stage_name(self.stage)
        if not isinstance(self.definition, AnalysisStageDefinition):
            raise AnalysisRegistryError(
                "StagePlanEntry.definition must be AnalysisStageDefinition."
            )
        if self.definition.name != stage:
            raise AnalysisRegistryError(
                "Stage-plan entry name does not match its definition.",
                stage=stage,
            )
        if not isinstance(self.stage_config, AnalysisStageConfig):
            raise AnalysisRegistryError(
                "StagePlanEntry.stage_config must be AnalysisStageConfig."
            )

        dependencies = canonicalize_registry_stage_sequence(self.dependencies)
        predecessors = canonicalize_registry_stage_sequence(
            self.ordering_predecessors
        )
        blocked_by = canonicalize_registry_stage_sequence(self.blocked_by)
        disposition = (
            self.disposition
            if isinstance(self.disposition, PlanEntryDisposition)
            else PlanEntryDisposition(str(self.disposition))
        )
        available = bool(self.available)
        if blocked_by and disposition is PlanEntryDisposition.READY:
            disposition = PlanEntryDisposition.BLOCKED
        if not available and disposition is PlanEntryDisposition.READY:
            disposition = PlanEntryDisposition.UNAVAILABLE

        object.__setattr__(self, "stage", stage)
        object.__setattr__(self, "position", max(0, int(self.position)))
        object.__setattr__(self, "wave", max(0, int(self.wave)))
        object.__setattr__(self, "dependencies", dependencies)
        object.__setattr__(self, "ordering_predecessors", predecessors)
        object.__setattr__(self, "requested", bool(self.requested))
        object.__setattr__(self, "dependency_included", bool(self.dependency_included))
        object.__setattr__(self, "required", bool(self.required))
        object.__setattr__(self, "available", available)
        object.__setattr__(self, "blocked_by", blocked_by)
        object.__setattr__(self, "disposition", disposition)
        object.__setattr__(
            self,
            "reason",
            None if self.reason is None else str(self.reason).strip() or None,
        )
        object.__setattr__(self, "metadata", _freeze_stage_metadata(self.metadata))

    @property
    def executable(self) -> bool:
        """Return whether the stage is structurally ready for execution."""

        return (
            self.disposition is PlanEntryDisposition.READY
            and self.available
            and not self.blocked_by
            and self.stage_config.enabled
        )

    @property
    def executor_registered(self) -> bool:
        """Return whether the stage currently has an executor."""

        return self.definition.executor_registered

    @property
    def ready_for_execution(self) -> bool:
        """Return whether the entry is executable and has an executor."""

        return self.executable and self.executor_registered

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready plan entry."""

        return {
            "stage": self.stage,
            "position": self.position,
            "wave": self.wave,
            "requested": self.requested,
            "dependency_included": self.dependency_included,
            "required": self.required,
            "available": self.available,
            "executable": self.executable,
            "executor_registered": self.executor_registered,
            "ready_for_execution": self.ready_for_execution,
            "disposition": self.disposition.value,
            "reason": self.reason,
            "dependencies": list(self.dependencies),
            "ordering_predecessors": list(self.ordering_predecessors),
            "blocked_by": list(self.blocked_by),
            "stage_config": self.stage_config.to_dict(),
            "definition": self.definition.to_dict(),
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass(frozen=True)
class AnalysisExecutionPlan:
    """Deterministic dependency-resolved analysis execution plan."""

    entries: Tuple[StagePlanEntry, ...]
    requested_stages: Tuple[str, ...]
    dependency_included_stages: Tuple[str, ...]
    omitted_stages: Tuple[str, ...]
    analysis_mode: str
    registry_generation: int
    registry_fingerprint: str
    config_fingerprint: str
    plan_id: str
    warnings: Tuple[str, ...] = ()
    created_at: str = field(default_factory=lambda: _utc_timestamp())
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        entries = tuple(self.entries)
        if len(entries) > MAX_EXECUTION_PLAN_STAGES:
            raise AnalysisRegistryError(
                f"Execution plans cannot exceed {MAX_EXECUTION_PLAN_STAGES} stages."
            )
        if any(not isinstance(entry, StagePlanEntry) for entry in entries):
            raise AnalysisRegistryError(
                "Execution plans require StagePlanEntry values."
            )
        names = tuple(entry.stage for entry in entries)
        if len(names) != len(set(names)):
            raise AnalysisRegistryError("Execution plans cannot contain duplicate stages.")

        requested = canonicalize_registry_stage_sequence(self.requested_stages)
        dependency_included = canonicalize_registry_stage_sequence(
            self.dependency_included_stages
        )
        omitted = canonicalize_registry_stage_sequence(self.omitted_stages)
        warnings_value = tuple(
            str(message).strip()
            for message in self.warnings
            if str(message).strip()
        )[:MAX_EXECUTION_PLAN_WARNINGS]

        object.__setattr__(self, "entries", entries)
        object.__setattr__(self, "requested_stages", requested)
        object.__setattr__(
            self,
            "dependency_included_stages",
            dependency_included,
        )
        object.__setattr__(self, "omitted_stages", omitted)
        object.__setattr__(
            self,
            "analysis_mode",
            canonicalize_analysis_mode(self.analysis_mode),
        )
        object.__setattr__(self, "registry_generation", max(0, int(self.registry_generation)))
        object.__setattr__(self, "registry_fingerprint", str(self.registry_fingerprint))
        object.__setattr__(self, "config_fingerprint", str(self.config_fingerprint))
        object.__setattr__(self, "plan_id", str(self.plan_id).strip())
        object.__setattr__(self, "warnings", warnings_value)
        object.__setattr__(self, "metadata", _freeze_stage_metadata(self.metadata))

    @property
    def stages(self) -> Tuple[str, ...]:
        """Return every retained stage in execution order."""

        return tuple(entry.stage for entry in self.entries)

    @property
    def executable_stages(self) -> Tuple[str, ...]:
        """Return structurally executable stages in order."""

        return tuple(entry.stage for entry in self.entries if entry.executable)

    @property
    def ready_stages(self) -> Tuple[str, ...]:
        """Return stages with registered executors in execution order."""

        return tuple(entry.stage for entry in self.entries if entry.ready_for_execution)

    @property
    def unavailable_stages(self) -> Tuple[str, ...]:
        """Return unavailable retained stages."""

        return tuple(
            entry.stage
            for entry in self.entries
            if entry.disposition is PlanEntryDisposition.UNAVAILABLE
        )

    @property
    def blocked_stages(self) -> Tuple[str, ...]:
        """Return stages blocked by unavailable dependencies."""

        return tuple(
            entry.stage
            for entry in self.entries
            if entry.disposition is PlanEntryDisposition.BLOCKED
        )

    @property
    def stages_without_executors(self) -> Tuple[str, ...]:
        """Return executable stages without a registered executor."""

        return tuple(
            entry.stage
            for entry in self.entries
            if entry.executable and not entry.executor_registered
        )

    @property
    def waves(self) -> Tuple[Tuple[str, ...], ...]:
        """Return execution waves grouped by dependency level."""

        groups: Dict[int, List[str]] = defaultdict(list)
        for entry in self.entries:
            groups[entry.wave].append(entry.stage)
        return tuple(tuple(groups[index]) for index in sorted(groups))

    @property
    def structurally_ready(self) -> bool:
        """Return whether no retained stage is unavailable or blocked."""

        return not self.unavailable_stages and not self.blocked_stages

    @property
    def ready_for_execution(self) -> bool:
        """Return whether every executable stage has an executor."""

        return self.structurally_ready and not self.stages_without_executors

    @property
    def requires_chimerax(self) -> bool:
        """Return whether any retained stage requires ChimeraX."""

        return any(entry.definition.requires_chimerax for entry in self.entries)

    def contains(self, stage: Any) -> bool:
        """Return whether a stage is retained in this plan."""

        canonical = canonicalize_registry_stage_name(stage)
        return canonical in set(self.stages)

    def entry(self, stage: Any) -> StagePlanEntry:
        """Return one stage-plan entry."""

        canonical = canonicalize_registry_stage_name(stage)
        for entry in self.entries:
            if entry.stage == canonical:
                return entry
        raise AnalysisRegistryError(
            f"Stage {canonical!r} is not part of execution plan {self.plan_id!r}.",
            stage=canonical,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready execution plan."""

        return {
            "schema": EXECUTION_PLAN_SCHEMA_NAME,
            "schema_version": EXECUTION_PLAN_SCHEMA_VERSION,
            "plan_id": self.plan_id,
            "created_at": self.created_at,
            "analysis_mode": self.analysis_mode,
            "registry_generation": self.registry_generation,
            "registry_fingerprint": self.registry_fingerprint,
            "config_fingerprint": self.config_fingerprint,
            "requested_stages": list(self.requested_stages),
            "dependency_included_stages": list(self.dependency_included_stages),
            "omitted_stages": list(self.omitted_stages),
            "stages": list(self.stages),
            "executable_stages": list(self.executable_stages),
            "ready_stages": list(self.ready_stages),
            "unavailable_stages": list(self.unavailable_stages),
            "blocked_stages": list(self.blocked_stages),
            "stages_without_executors": list(self.stages_without_executors),
            "waves": [list(wave) for wave in self.waves],
            "structurally_ready": self.structurally_ready,
            "ready_for_execution": self.ready_for_execution,
            "requires_chimerax": self.requires_chimerax,
            "warnings": list(self.warnings),
            "entries": [entry.to_dict() for entry in self.entries],
            "metadata": to_json_compatible(dict(self.metadata)),
        }

    def to_json(
        self,
        *,
        indent: Optional[int] = DEFAULT_JSON_INDENT,
        sort_keys: bool = True,
    ) -> str:
        """Serialize this execution plan to JSON."""

        return json.dumps(
            self.to_dict(),
            indent=indent,
            sort_keys=sort_keys,
            ensure_ascii=False,
        )

    def summary(self) -> Dict[str, Any]:
        """Return a concise execution-plan summary."""

        return {
            "plan_id": self.plan_id,
            "analysis_mode": self.analysis_mode,
            "stage_count": len(self.entries),
            "requested_stage_count": len(self.requested_stages),
            "dependency_stage_count": len(self.dependency_included_stages),
            "executable_stage_count": len(self.executable_stages),
            "ready_stage_count": len(self.ready_stages),
            "unavailable_stages": list(self.unavailable_stages),
            "blocked_stages": list(self.blocked_stages),
            "omitted_stages": list(self.omitted_stages),
            "wave_count": len(self.waves),
            "structurally_ready": self.structurally_ready,
            "ready_for_execution": self.ready_for_execution,
            "warnings": list(self.warnings),
        }


# 10.9. Dependency closure and graph construction
# -----------------------------------------------------------------------------


def collect_stage_dependency_closure(
    stages: Any,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
    include_dependencies: bool = DEFAULT_INCLUDE_HARD_DEPENDENCIES,
    maximum_depth: int = MAX_STAGE_DEPENDENCY_DEPTH,
) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    """Return selected stages and stages added as hard dependencies."""

    target = registry or get_default_stage_registry()
    requested = canonicalize_registry_stage_sequence(stages)
    if not include_dependencies:
        for stage in requested:
            target.require(stage)
        return requested, ()

    maximum_depth = max(1, int(maximum_depth))
    selected: "OrderedDict[str, None]" = OrderedDict((stage, None) for stage in requested)
    dependency_added: "OrderedDict[str, None]" = OrderedDict()
    visiting: List[Tuple[str, int]] = [(stage, 0) for stage in requested]

    while visiting:
        stage, depth = visiting.pop()
        if depth > maximum_depth:
            raise AnalysisRegistryError(
                "Stage dependency resolution exceeded the maximum depth.",
                stage=stage,
                details={"maximum_depth": maximum_depth},
            )
        definition = target.require(stage)
        for dependency in reversed(definition.dependencies):
            target.require(dependency)
            if dependency not in selected:
                selected[dependency] = None
                dependency_added[dependency] = None
                visiting.append((dependency, depth + 1))

    return tuple(selected), tuple(dependency_added)


def build_stage_execution_graph(
    stages: Any,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
    include_ordering_predecessors: bool = DEFAULT_INCLUDE_ORDERING_PREDECESSORS,
) -> Dict[str, Tuple[str, ...]]:
    """Build a stage-to-predecessors graph for selected stages."""

    target = registry or get_default_stage_registry()
    selected = canonicalize_registry_stage_sequence(stages)
    selected_set = set(selected)
    graph: Dict[str, Tuple[str, ...]] = {}
    for stage in selected:
        definition = target.require(stage)
        predecessors: List[str] = [
            dependency
            for dependency in definition.dependencies
            if dependency in selected_set
        ]
        if include_ordering_predecessors:
            predecessors.extend(
                predecessor
                for predecessor in definition.ordering_predecessors
                if predecessor in selected_set
            )
        graph[stage] = tuple(dict.fromkeys(predecessors))
    return graph


def topologically_sort_stages(
    graph: Mapping[str, Sequence[str]],
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> Tuple[str, ...]:
    """Return a stable topological ordering of a stage graph."""

    target = registry or get_default_stage_registry()
    normalized: Dict[str, Tuple[str, ...]] = {
        canonicalize_registry_stage_name(stage): canonicalize_registry_stage_sequence(
            dependencies
        )
        for stage, dependencies in graph.items()
    }
    nodes = set(normalized)
    for stage, dependencies in normalized.items():
        missing = set(dependencies).difference(nodes)
        if missing:
            raise AnalysisRegistryError(
                f"Execution graph stage {stage!r} references missing nodes: "
                f"{sorted(missing)!r}.",
                stage=stage,
            )

    cycles = find_stage_dependency_cycles(normalized)
    if cycles:
        raise AnalysisRegistryError(
            f"Execution graph contains dependency cycles: {cycles!r}.",
            details={"cycles": cycles},
        )

    registration_order = {
        stage: index for index, stage in enumerate(target.names())
    }
    indegree = {stage: len(dependencies) for stage, dependencies in normalized.items()}
    dependents: Dict[str, List[str]] = defaultdict(list)
    for stage, dependencies in normalized.items():
        for dependency in dependencies:
            dependents[dependency].append(stage)

    ready = [stage for stage, degree in indegree.items() if degree == 0]
    ready.sort(key=lambda stage: _registry_stage_sort_key(stage, registry_order=registration_order))
    ordered: List[str] = []

    while ready:
        stage = ready.pop(0)
        ordered.append(stage)
        for dependent in sorted(
            dependents.get(stage, ()),
            key=lambda item: _registry_stage_sort_key(
                item,
                registry_order=registration_order,
            ),
        ):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                ready.append(dependent)
                ready.sort(
                    key=lambda item: _registry_stage_sort_key(
                        item,
                        registry_order=registration_order,
                    )
                )

    if len(ordered) != len(normalized):
        raise AnalysisRegistryError(
            "Topological sorting did not resolve every execution stage."
        )
    return tuple(ordered)


def build_stage_execution_waves(
    graph: Mapping[str, Sequence[str]],
    *,
    order: Optional[Sequence[str]] = None,
    registry: Optional[AnalysisStageRegistry] = None,
) -> Tuple[Tuple[str, ...], ...]:
    """Group stages into dependency-safe execution waves."""

    ordered = tuple(order) if order is not None else topologically_sort_stages(
        graph,
        registry=registry,
    )
    levels: Dict[str, int] = {}
    for stage in ordered:
        dependencies = tuple(graph.get(stage, ()))
        levels[stage] = (
            0
            if not dependencies
            else max(levels[dependency] for dependency in dependencies) + 1
        )
    groups: Dict[int, List[str]] = defaultdict(list)
    for stage in ordered:
        groups[levels[stage]].append(stage)
    return tuple(tuple(groups[level]) for level in sorted(groups))


# 10.10. Stage selection and availability helpers
# -----------------------------------------------------------------------------


def resolve_requested_plan_stages(
    config: Optional[AnalysisConfigLike] = None,
    *,
    requested_stages: Any = None,
    analysis_mode: Optional[Any] = None,
) -> Tuple[str, ...]:
    """Resolve the initial requested stages for an execution plan."""

    config_value = coerce_analysis_config(config)
    if requested_stages is None:
        return canonicalize_registry_stage_sequence(
            config_value.desired_stages(mode=analysis_mode)
        )
    return canonicalize_registry_stage_sequence(requested_stages)


def _effective_plan_stage_config(
    config: AnalysisConfig,
    stage: str,
) -> AnalysisStageConfig:
    """Return an effective stage configuration for known or custom stages."""

    if stage in KNOWN_PIPELINE_STAGES:
        return config.stage_config(stage)
    configured = config.stage_configs.get(stage)
    if configured is not None:
        return configured
    return AnalysisStageConfig(
        enabled=True,
        required=False,
        attach_results=config.runtime.attach_results,
        validate_result=config.runtime.validate_results,
        reuse_result=config.runtime.reuse_results,
        timeout_seconds=config.runtime.default_stage_timeout_seconds,
    )


def _stage_availability(
    definition: AnalysisStageDefinition,
    *,
    capabilities: Optional[AnalysisCapabilities],
) -> Tuple[bool, Optional[str]]:
    """Resolve availability of one stage definition."""

    if capabilities is None:
        if definition.requires_chimerax and not CHIMERAX_AVAILABLE:
            return False, "ChimeraX is not available."
        return True, None

    if definition.name in KNOWN_PIPELINE_STAGES:
        if not capabilities.supports_stage(definition.name):
            return False, "Registered stage capabilities are unavailable."
    else:
        missing_modules = [
            module_name
            for module_name in definition.required_modules
            if module_name in capabilities.modules
            and not capabilities.supports_module(module_name)
        ]
        if missing_modules:
            return False, "Missing modules: " + ", ".join(missing_modules)

    if definition.requires_chimerax and not capabilities.supports_dependency("chimerax"):
        return False, "ChimeraX is not available."
    return True, None


def _build_execution_plan_id(
    *,
    config_fingerprint: str,
    registry_fingerprint: str,
    stages: Sequence[str],
    analysis_mode: str,
) -> str:
    """Return a deterministic compact execution-plan identifier."""

    payload = json.dumps(
        {
            "config": config_fingerprint,
            "registry": registry_fingerprint,
            "stages": list(stages),
            "mode": analysis_mode,
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode(ANALYSIS_ENCODING)
    return f"plan-{sha256(payload).hexdigest()[:16]}"


# 10.11. Execution-plan construction
# -----------------------------------------------------------------------------


def build_analysis_execution_plan(
    config: Optional[AnalysisConfigLike] = None,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    requested_stages: Any = None,
    analysis_mode: Optional[Any] = None,
    include_dependencies: Optional[bool] = None,
    include_ordering_predecessors: bool = DEFAULT_INCLUDE_ORDERING_PREDECESSORS,
    inspect_capabilities: bool = DEFAULT_INSPECT_PLAN_CAPABILITIES,
    load_capabilities: bool = DEFAULT_LOAD_PLAN_CAPABILITIES,
    drop_unavailable_optional_stages: bool = DEFAULT_DROP_UNAVAILABLE_OPTIONAL_STAGES,
    require_registered_executors: bool = DEFAULT_REQUIRE_REGISTERED_EXECUTORS,
    strict: bool = DEFAULT_PLAN_STRICT,
) -> AnalysisExecutionPlan:
    """Build a validated deterministic execution plan."""

    config_value = coerce_analysis_config(config)
    target = registry or get_default_stage_registry()
    validate_stage_registry(target, raise_on_error=True)
    snapshot = target.snapshot()
    mode = canonicalize_analysis_mode(
        config_value.runtime.analysis_mode
        if analysis_mode is None
        else analysis_mode
    )
    requested = resolve_requested_plan_stages(
        config_value,
        requested_stages=requested_stages,
        analysis_mode=mode,
    )
    for stage in requested:
        target.require(stage)

    include_hard = (
        config_value.include_stage_dependencies
        if include_dependencies is None
        else bool(include_dependencies)
    )

    warnings_list: List[str] = []
    omitted: List[str] = []
    enabled_requested: List[str] = []
    for stage in requested:
        stage_config = _effective_plan_stage_config(config_value, stage)
        if stage_config.enabled:
            enabled_requested.append(stage)
        else:
            omitted.append(stage)
            warnings_list.append(
                f"Stage {stage!r} was requested but disabled by configuration."
            )

    selected, dependency_added = collect_stage_dependency_closure(
        enabled_requested,
        registry=target,
        include_dependencies=include_hard,
    )

    selected_list = list(selected)
    selected_set = set(selected_list)
    dependency_added_set = set(dependency_added)

    for stage in tuple(selected_list):
        stage_config = _effective_plan_stage_config(config_value, stage)
        if not stage_config.enabled:
            if stage in dependency_added_set:
                message = (
                    f"Dependency stage {stage!r} is disabled by configuration."
                )
                if strict:
                    raise AnalysisStageDependencyError(
                        message,
                        stage=stage,
                        details={"requested_stages": enabled_requested},
                    )
                warnings_list.append(message)
            selected_list.remove(stage)
            selected_set.discard(stage)
            omitted.append(stage)

    capability_snapshot = capabilities
    if capability_snapshot is None and inspect_capabilities:
        capability_snapshot = inspect_analysis_capabilities(
            load_modules=load_capabilities,
            load_dependencies=load_capabilities,
            validate_interfaces=load_capabilities,
        )

    availability: Dict[str, bool] = {}
    availability_reasons: Dict[str, Optional[str]] = {}
    required_flags: Dict[str, bool] = {}

    for stage in tuple(selected_list):
        definition = target.require(stage)
        stage_config = _effective_plan_stage_config(config_value, stage)
        required = bool(stage_config.required or not definition.optional)
        available, reason = _stage_availability(
            definition,
            capabilities=capability_snapshot,
        )
        availability[stage] = available
        availability_reasons[stage] = reason
        required_flags[stage] = required

        if not available and definition.optional and drop_unavailable_optional_stages:
            selected_list.remove(stage)
            selected_set.discard(stage)
            omitted.append(stage)
            warnings_list.append(
                f"Optional stage {stage!r} was omitted because it is unavailable"
                + (f": {reason}" if reason else ".")
            )
        elif not available and required and strict:
            raise AnalysisStageDependencyError(
                f"Required stage {stage!r} is unavailable"
                + (f": {reason}" if reason else "."),
                stage=stage,
                details={
                    "reason": reason,
                    "required_modules": list(definition.required_modules),
                },
            )

    graph = build_stage_execution_graph(
        selected_list,
        registry=target,
        include_ordering_predecessors=include_ordering_predecessors,
    )
    order = topologically_sort_stages(graph, registry=target)
    waves = build_stage_execution_waves(graph, order=order, registry=target)
    wave_map = {
        stage: wave_index
        for wave_index, wave in enumerate(waves)
        for stage in wave
    }

    blocked_by: Dict[str, Tuple[str, ...]] = {}
    for stage in order:
        definition = target.require(stage)
        blocked: List[str] = []
        for dependency in definition.dependencies:
            if dependency not in selected_set:
                blocked.append(dependency)
            elif not availability.get(dependency, True):
                blocked.append(dependency)
            elif blocked_by.get(dependency):
                blocked.append(dependency)
        blocked_by[stage] = tuple(dict.fromkeys(blocked))

    entries: List[StagePlanEntry] = []
    for position, stage in enumerate(order):
        definition = target.require(stage)
        stage_config = _effective_plan_stage_config(config_value, stage)
        available = availability.get(stage, True)
        blocked = blocked_by.get(stage, ())
        if blocked:
            disposition = PlanEntryDisposition.BLOCKED
            reason = "Blocked by dependencies: " + ", ".join(blocked)
        elif not available:
            disposition = PlanEntryDisposition.UNAVAILABLE
            reason = availability_reasons.get(stage)
        else:
            disposition = PlanEntryDisposition.READY
            reason = None

        entry = StagePlanEntry(
            stage=stage,
            definition=definition,
            stage_config=stage_config,
            position=position,
            wave=wave_map[stage],
            dependencies=tuple(
                dependency
                for dependency in definition.dependencies
                if dependency in selected_set
            ),
            ordering_predecessors=tuple(
                predecessor
                for predecessor in definition.ordering_predecessors
                if predecessor in selected_set
            ),
            requested=stage in enabled_requested,
            dependency_included=stage in dependency_added_set,
            required=required_flags.get(stage, not definition.optional),
            available=available,
            blocked_by=blocked,
            disposition=disposition,
            reason=reason,
        )
        entries.append(entry)

    missing_executors = [
        entry.stage
        for entry in entries
        if entry.executable and not entry.executor_registered
    ]
    if missing_executors:
        message = (
            "No executor is registered for stages: "
            + ", ".join(missing_executors)
            + "."
        )
        if require_registered_executors:
            raise AnalysisRegistryError(message, details={"stages": missing_executors})
        warnings_list.append(message)

    config_fingerprint = config_value.fingerprint()
    plan_id = _build_execution_plan_id(
        config_fingerprint=config_fingerprint,
        registry_fingerprint=snapshot.fingerprint,
        stages=order,
        analysis_mode=mode,
    )
    plan = AnalysisExecutionPlan(
        entries=tuple(entries),
        requested_stages=tuple(enabled_requested),
        dependency_included_stages=tuple(
            stage for stage in order if stage in dependency_added_set
        ),
        omitted_stages=tuple(dict.fromkeys(omitted)),
        analysis_mode=mode,
        registry_generation=snapshot.generation,
        registry_fingerprint=snapshot.fingerprint,
        config_fingerprint=config_fingerprint,
        plan_id=plan_id,
        warnings=tuple(warnings_list),
        metadata={
            "include_dependencies": include_hard,
            "include_ordering_predecessors": bool(include_ordering_predecessors),
            "capabilities_inspected": capability_snapshot is not None,
            "capabilities_loaded": bool(
                capability_snapshot and capability_snapshot.loaded_modules
            ),
            "drop_unavailable_optional_stages": bool(
                drop_unavailable_optional_stages
            ),
            "require_registered_executors": bool(require_registered_executors),
        },
    )
    validate_analysis_execution_plan(
        plan,
        registry=target,
        raise_on_error=True,
        require_registered_executors=require_registered_executors,
    )
    return plan


# 10.12. Plan validation, summaries and conversion
# -----------------------------------------------------------------------------


def validate_analysis_execution_plan(
    plan: AnalysisExecutionPlan,
    *,
    registry: Optional[AnalysisStageRegistry] = None,
    raise_on_error: bool = True,
    require_registered_executors: bool = False,
) -> Tuple[str, ...]:
    """Validate an execution plan and return detected issues."""

    if not isinstance(plan, AnalysisExecutionPlan):
        issues = ("Expected an AnalysisExecutionPlan instance.",)
        if raise_on_error:
            raise AnalysisRegistryError(issues[0])
        return issues

    target = registry or get_default_stage_registry()
    issues_list: List[str] = []
    stages = plan.stages
    stage_set = set(stages)
    positions = {stage: index for index, stage in enumerate(stages)}

    if tuple(entry.position for entry in plan.entries) != tuple(range(len(plan.entries))):
        issues_list.append("Plan entry positions are not contiguous.")

    for entry in plan.entries:
        definition = target.get(entry.stage)
        if definition is None:
            issues_list.append(f"Plan stage {entry.stage!r} is not registered.")
            continue
        if definition != entry.definition:
            issues_list.append(
                f"Plan stage {entry.stage!r} does not match the current registry definition."
            )
        for dependency in entry.dependencies:
            if dependency not in stage_set:
                issues_list.append(
                    f"Plan stage {entry.stage!r} is missing dependency {dependency!r}."
                )
            elif positions[dependency] >= positions[entry.stage]:
                issues_list.append(
                    f"Dependency {dependency!r} does not precede stage {entry.stage!r}."
                )
        for predecessor in entry.ordering_predecessors:
            if predecessor in stage_set and positions[predecessor] >= positions[entry.stage]:
                issues_list.append(
                    f"Ordering predecessor {predecessor!r} does not precede "
                    f"stage {entry.stage!r}."
                )
        if entry.disposition is PlanEntryDisposition.READY and entry.blocked_by:
            issues_list.append(
                f"Ready stage {entry.stage!r} contains blocking dependencies."
            )
        if entry.disposition is PlanEntryDisposition.UNAVAILABLE and entry.available:
            issues_list.append(
                f"Unavailable stage {entry.stage!r} is marked available."
            )
        if entry.disposition is PlanEntryDisposition.BLOCKED and not entry.blocked_by:
            issues_list.append(
                f"Blocked stage {entry.stage!r} does not identify blockers."
            )
        if require_registered_executors and entry.executable and not entry.executor_registered:
            issues_list.append(
                f"Executable stage {entry.stage!r} has no registered executor."
            )

    omitted_overlap = set(plan.omitted_stages).intersection(stage_set)
    if omitted_overlap:
        issues_list.append(
            f"Omitted stages remain in the plan: {sorted(omitted_overlap)!r}."
        )

    graph = {
        entry.stage: tuple(
            dict.fromkeys((*entry.dependencies, *entry.ordering_predecessors))
        )
        for entry in plan.entries
    }
    cycles = find_stage_dependency_cycles(graph)
    if cycles:
        issues_list.append(f"Execution plan contains cycles: {cycles!r}.")

    for wave_index, wave in enumerate(plan.waves):
        for stage in wave:
            entry = plan.entry(stage)
            if entry.wave != wave_index:
                issues_list.append(
                    f"Stage {stage!r} has an inconsistent execution wave."
                )

    issues = tuple(dict.fromkeys(issues_list))
    if raise_on_error and issues:
        raise AnalysisRegistryError(
            " ".join(issues),
            details={"plan_id": plan.plan_id, "issues": list(issues)},
        )
    return issues


def execution_plan_to_dict(plan: AnalysisExecutionPlan) -> Dict[str, Any]:
    """Return a serialization-ready execution plan."""

    if not isinstance(plan, AnalysisExecutionPlan):
        raise AnalysisRegistryError("Expected an AnalysisExecutionPlan instance.")
    return plan.to_dict()


def execution_plan_to_json(
    plan: AnalysisExecutionPlan,
    *,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
    sort_keys: bool = True,
) -> str:
    """Serialize an execution plan to JSON."""

    return plan.to_json(indent=indent, sort_keys=sort_keys)


def summarize_analysis_execution_plan(
    plan: AnalysisExecutionPlan,
) -> Dict[str, Any]:
    """Return a concise execution-plan summary."""

    if not isinstance(plan, AnalysisExecutionPlan):
        raise AnalysisRegistryError("Expected an AnalysisExecutionPlan instance.")
    return plan.summary()


def get_plan_stage_dependencies(
    plan: AnalysisExecutionPlan,
    stage: Any,
    *,
    include_ordering: bool = False,
) -> Tuple[str, ...]:
    """Return dependencies retained for one plan stage."""

    entry = plan.entry(stage)
    if include_ordering:
        return tuple(
            dict.fromkeys((*entry.dependencies, *entry.ordering_predecessors))
        )
    return entry.dependencies


def get_plan_stage_dependents(
    plan: AnalysisExecutionPlan,
    stage: Any,
    *,
    include_ordering: bool = False,
) -> Tuple[str, ...]:
    """Return stages depending on one stage in plan order."""

    canonical = canonicalize_registry_stage_name(stage)
    result: List[str] = []
    for entry in plan.entries:
        dependencies = list(entry.dependencies)
        if include_ordering:
            dependencies.extend(entry.ordering_predecessors)
        if canonical in dependencies:
            result.append(entry.stage)
    return tuple(result)


def execution_plan_fingerprint(plan: AnalysisExecutionPlan) -> str:
    """Return a deterministic fingerprint of one execution plan."""

    data = plan.to_dict()
    data.pop("created_at", None)
    data.pop("plan_id", None)
    payload = json.dumps(
        data,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode(ANALYSIS_ENCODING)
    return sha256(payload).hexdigest()


# 10.13. Internal convention validation
# -----------------------------------------------------------------------------


def validate_stage_registry_and_plan_conventions() -> Dict[str, Any]:
    """Validate Section 10 registry and execution-plan conventions."""

    failures: List[str] = []
    registry = create_default_stage_registry()

    if registry.names() != PIPELINE_STAGE_ORDER:
        failures.append("Default registry order does not match the pipeline order.")
    if validate_stage_registry(registry, raise_on_error=False):
        failures.append("Default registry validation reported issues.")
    if len(registry) != len(PIPELINE_STAGE_ORDER):
        failures.append("Default registry has an unexpected stage count.")

    snapshot = registry.snapshot()
    if snapshot.names != PIPELINE_STAGE_ORDER:
        failures.append("Registry snapshot lost stage order.")
    if not snapshot.fingerprint:
        failures.append("Registry fingerprint is empty.")

    test_config = AnalysisConfig(
        requested_stages=(STAGE_CONTACTS, STAGE_SCORING),
        include_internal_stages=False,
        include_stage_dependencies=True,
    )
    plan = build_analysis_execution_plan(
        test_config,
        registry=registry,
        inspect_capabilities=False,
        require_registered_executors=False,
    )
    expected_stages = (
        STAGE_INPUT_RESOLUTION,
        STAGE_MODEL_PREPARATION,
        STAGE_CONTACTS,
        STAGE_CONSOLIDATION,
        STAGE_SCORING,
    )
    if plan.stages != expected_stages:
        failures.append(
            "Dependency planning produced an unexpected stage order: "
            f"{plan.stages!r}."
        )
    if STAGE_MODEL_PREPARATION not in plan.dependency_included_stages:
        failures.append("Dependency-added stages were not recorded.")
    if validate_analysis_execution_plan(
        plan,
        registry=registry,
        raise_on_error=False,
    ):
        failures.append("Generated execution plan did not validate.")
    if json.loads(plan.to_json())["plan_id"] != plan.plan_id:
        failures.append("Execution-plan JSON round-trip failed.")

    custom_definition = AnalysisStageDefinition(
        name="custom_postprocess",
        dependencies=(STAGE_SCORING,),
        description="Synthetic postprocessing stage.",
        optional=True,
    )
    registry.register(custom_definition)
    custom_plan = build_analysis_execution_plan(
        test_config,
        registry=registry,
        requested_stages=(STAGE_CONTACTS, "custom_postprocess"),
        inspect_capabilities=False,
    )
    if custom_plan.stages[-1] != "custom_postprocess":
        failures.append("Custom stage was not topologically ordered after scoring.")
    if registry.clone().snapshot().fingerprint != registry.snapshot().fingerprint:
        failures.append("Registry cloning changed its fingerprint.")

    duplicate_failed = False
    try:
        registry.register(custom_definition)
    except AnalysisRegistryError:
        duplicate_failed = True
    if not duplicate_failed:
        failures.append("Duplicate stage registration was not rejected.")

    cycle_graph = {
        "cycle_a": ("cycle_b",),
        "cycle_b": ("cycle_a",),
    }
    cycles = find_stage_dependency_cycles(cycle_graph)
    if not cycles:
        failures.append("Dependency-cycle detection failed.")

    if execution_plan_fingerprint(plan) != execution_plan_fingerprint(plan):
        failures.append("Execution-plan fingerprint is not deterministic.")

    if failures:
        raise RuntimeError(
            "Stage-registry and plan convention validation failed: "
            + " ".join(failures)
        )

    return {
        "valid": True,
        "registered_stages": len(registry),
        "canonical_stages": len(PIPELINE_STAGE_ORDER),
        "planned_stages": len(plan.entries),
        "execution_waves": len(plan.waves),
        "validated_cases": 15,
    }


