# 11.2. Contact-adapter configuration
# -----------------------------------------------------------------------------


def canonicalize_contact_residue_side(value: Any) -> str:
    """Return the canonical residue side used by ``contacts.py``."""

    token = normalize_identifier(
        value,
        default=CONTACTS_DEFAULT_RESIDUE_SIDE,
        maximum_length=64,
    )
    canonical = CONTACT_RESIDUE_SIDE_ALIASES.get(token)
    if canonical is None:
        supported = ", ".join(sorted(CONTACT_RESIDUE_SIDE_ALIASES))
        raise AnalysisConfigurationError(
            f"Unsupported contact residue side {value!r}. Supported values: "
            f"{supported}."
        )
    return canonical


def _normalize_contact_parameter_name(value: Any) -> str:
    """Normalize one contact-adapter parameter name."""

    token = normalize_identifier(value, maximum_length=128)
    return CONTACT_PARAMETER_ALIASES.get(token, token)


def _contact_optional_float(value: Any, *, field_name: str) -> Optional[float]:
    """Normalize a positive optional floating-point parameter."""

    if value is None:
        return None
    try:
        normalized = normalize_float(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(f"{field_name} must be a finite number.") from exc
    if normalized is None:
        return None
    if normalized <= 0.0:
        raise AnalysisConfigurationError(f"{field_name} must be greater than zero.")
    return normalized


def _contact_optional_integer(value: Any, *, field_name: str) -> Optional[int]:
    """Normalize a positive optional integer parameter."""

    if value is None:
        return None
    try:
        normalized = normalize_integer(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(f"{field_name} must be an integer.") from exc
    if normalized is None:
        return None
    if normalized <= 0:
        raise AnalysisConfigurationError(f"{field_name} must be greater than zero.")
    return normalized


def _contact_metadata(value: Any) -> Mapping[str, Any]:
    """Return immutable contact-analysis metadata."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        raise AnalysisConfigurationError("contacts.metadata must be a mapping.")
    if len(value) > MAX_CONTACT_ADAPTER_METADATA_ITEMS:
        raise AnalysisConfigurationError(
            "contacts.metadata exceeds the supported item limit."
        )
    return MappingProxyType(copy.deepcopy(dict(value)))


@dataclass(frozen=True)
class ContactAdapterConfig:
    """Resolved configuration passed to ``contacts.analyze_contacts``."""

    cutoff: Optional[float] = None
    heavy_only: bool = True
    exclude_solvent: bool = True
    exclude_ions: bool = True
    exclude_same_residue: bool = True
    classify: bool = True
    clash_overlap: Optional[float] = None
    close_tolerance: Optional[float] = None
    vdw_tolerance: Optional[float] = None
    default_vdw_radius: Optional[float] = None
    block_size: Optional[int] = None
    maximum_matrix_elements: Optional[int] = None
    maximum_contacts: Optional[int] = None
    residue_side: str = CONTACTS_DEFAULT_RESIDUE_SIDE
    attach: bool = True
    attach_to_pose: bool = True
    overwrite: bool = True
    analysis_attribute: str = CONTACTS_DEFAULT_ANALYSIS_ATTRIBUTE
    metadata: Mapping[str, Any] = field(default_factory=dict)
    scene: bool = True

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "cutoff",
            _contact_optional_float(self.cutoff, field_name="contacts.cutoff"),
        )
        for field_name in (
            "heavy_only",
            "exclude_solvent",
            "exclude_ions",
            "exclude_same_residue",
            "classify",
            "attach",
            "attach_to_pose",
            "overwrite",
            "scene",
        ):
            object.__setattr__(
                self,
                field_name,
                normalize_boolean(
                    getattr(self, field_name),
                ),
            )
        for field_name in (
            "clash_overlap",
            "close_tolerance",
            "vdw_tolerance",
            "default_vdw_radius",
        ):
            object.__setattr__(
                self,
                field_name,
                _contact_optional_float(
                    getattr(self, field_name),
                    field_name=f"contacts.{field_name}",
                ),
            )
        for field_name in (
            "block_size",
            "maximum_matrix_elements",
            "maximum_contacts",
        ):
            object.__setattr__(
                self,
                field_name,
                _contact_optional_integer(
                    getattr(self, field_name),
                    field_name=f"contacts.{field_name}",
                ),
            )
        object.__setattr__(
            self,
            "residue_side",
            canonicalize_contact_residue_side(self.residue_side),
        )
        object.__setattr__(
            self,
            "analysis_attribute",
            normalize_identifier(
                self.analysis_attribute,
                default=CONTACTS_DEFAULT_ANALYSIS_ATTRIBUTE,
                maximum_length=128,
            ),
        )
        object.__setattr__(self, "metadata", _contact_metadata(self.metadata))

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "ContactAdapterConfig":
        """Create contact-adapter configuration from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Contact adapter configuration must be a mapping."
            )
        normalized: Dict[str, Any] = {}
        unknown: List[str] = []
        for raw_name, raw_value in values.items():
            name = _normalize_contact_parameter_name(raw_name)
            if name not in CONTACT_ADAPTER_FIELDS:
                unknown.append(str(raw_name))
                continue
            if name in normalized:
                raise AnalysisConfigurationError(
                    f"Duplicate contact adapter parameter after alias resolution: "
                    f"{name!r}."
                )
            normalized[name] = raw_value
        if strict and unknown:
            supported = ", ".join(sorted(CONTACT_ADAPTER_FIELDS))
            raise AnalysisConfigurationError(
                "Unknown contact adapter parameters: "
                f"{', '.join(unknown)}. Supported parameters: {supported}."
            )
        return cls(**normalized)

    def with_metadata(self, values: Optional[Mapping[str, Any]]) -> "ContactAdapterConfig":
        """Return a copy with merged analysis metadata."""

        merged = dict(self.metadata)
        if values:
            merged.update(dict(values))
        return replace(self, metadata=merged)

    def to_call_kwargs(
        self,
        *,
        receptor: Any = None,
        pose: Any = None,
        pose_index: Optional[int] = None,
    ) -> Dict[str, Any]:
        """Return keyword arguments accepted by ``analyze_contacts``."""

        result = {
            "receptor": receptor,
            "pose": pose,
            "pose_index": pose_index,
            "cutoff": self.cutoff,
            "heavy_only": self.heavy_only,
            "exclude_solvent": self.exclude_solvent,
            "exclude_ions": self.exclude_ions,
            "exclude_same_residue": self.exclude_same_residue,
            "classify": self.classify,
            "clash_overlap": self.clash_overlap,
            "close_tolerance": self.close_tolerance,
            "vdw_tolerance": self.vdw_tolerance,
            "default_vdw_radius": self.default_vdw_radius,
            "block_size": self.block_size,
            "maximum_matrix_elements": self.maximum_matrix_elements,
            "maximum_contacts": self.maximum_contacts,
            "residue_side": self.residue_side,
            "attach": self.attach,
            "attach_to_pose": self.attach_to_pose,
            "overwrite": self.overwrite,
            "analysis_attribute": self.analysis_attribute,
            "metadata": dict(self.metadata),
            "scene": self.scene,
        }
        return result

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready contact-adapter configuration."""

        return {
            "cutoff": self.cutoff,
            "heavy_only": self.heavy_only,
            "exclude_solvent": self.exclude_solvent,
            "exclude_ions": self.exclude_ions,
            "exclude_same_residue": self.exclude_same_residue,
            "classify": self.classify,
            "clash_overlap": self.clash_overlap,
            "close_tolerance": self.close_tolerance,
            "vdw_tolerance": self.vdw_tolerance,
            "default_vdw_radius": self.default_vdw_radius,
            "block_size": self.block_size,
            "maximum_matrix_elements": self.maximum_matrix_elements,
            "maximum_contacts": self.maximum_contacts,
            "residue_side": self.residue_side,
            "attach": self.attach,
            "attach_to_pose": self.attach_to_pose,
            "overwrite": self.overwrite,
            "analysis_attribute": self.analysis_attribute,
            "metadata": to_json_compatible(dict(self.metadata)),
            "scene": self.scene,
        }


def _contact_mapping_from_config_object(value: Any) -> Dict[str, Any]:
    """Convert a module-specific configuration object to a mapping."""

    if value is None:
        return {}
    if isinstance(value, ContactAdapterConfig):
        return value.to_dict()
    if isinstance(value, Mapping):
        return dict(value)
    to_dict_method = getattr(value, "to_dict", None)
    if callable(to_dict_method):
        converted = to_dict_method()
        if isinstance(converted, Mapping):
            return dict(converted)
    if is_dataclass(value) and not isinstance(value, type):
        return asdict(value)
    raise AnalysisConfigurationError(
        "The contacts module configuration must be a mapping, dataclass or "
        "ContactAdapterConfig."
    )


def resolve_contact_adapter_config(
    config: Optional[AnalysisConfigLike] = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    strict: bool = True,
) -> ContactAdapterConfig:
    """Resolve effective contact parameters from integrated configuration."""

    integrated = coerce_analysis_config(config)
    stage_config = integrated.stage_config(STAGE_CONTACTS)
    module_config = integrated.module_config(CONTACTS_MODULE_NAME, {})

    merged: Dict[str, Any] = {}
    merged.update(_contact_mapping_from_config_object(module_config))
    merged.update(dict(stage_config.parameters))
    if overrides:
        merged.update(dict(overrides))

    attachment_policy = integrated.runtime.attachment_policy
    attach_enabled = bool(
        integrated.runtime.attach_results
        and stage_config.attach_results
        and attachment_policy != ATTACHMENT_POLICY_NONE
    )
    merged.setdefault("attach", attach_enabled)
    merged.setdefault("attach_to_pose", attach_enabled)
    merged.setdefault(
        "overwrite",
        attachment_policy in {ATTACHMENT_POLICY_REPLACE, ATTACHMENT_POLICY_MERGE},
    )

    resolved = ContactAdapterConfig.from_mapping(merged, strict=strict)
    if metadata:
        resolved = resolved.with_metadata(metadata)
    return resolved


# 11.3. Stage target resolution
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ContactStageTarget:
    """Resolved molecular inputs for one contact-analysis stage."""

    dock_model: Any
    receptor: Any
    pose: Any
    pose_index: Optional[int]
    dock_model_identifier: str
    pose_identifier: str

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe target representation."""

        result: Dict[str, Any] = {
            "dock_model_identifier": self.dock_model_identifier,
            "pose_identifier": self.pose_identifier,
            "pose_index": self.pose_index,
        }
        if include_objects:
            result.update(
                {
                    "dock_model": self.dock_model,
                    "receptor": self.receptor,
                    "pose": self.pose,
                }
            )
        else:
            result.update(
                {
                    "dock_model": describe_object(self.dock_model).to_dict(),
                    "receptor": describe_object(self.receptor).to_dict(),
                    "pose": describe_object(self.pose).to_dict(),
                }
            )
        return result


def _require_contacts_module(module: Optional[ModuleType] = None) -> ModuleType:
    """Return a validated contacts module."""

    resolved = module or require_analysis_module(CONTACTS_MODULE_NAME, load=True)
    missing = tuple(
        name for name in CONTACTS_REQUIRED_SYMBOLS if not hasattr(resolved, name)
    )
    if missing:
        raise AnalysisDependencyError(
            "The contacts module does not expose the required adapter interface.",
            stage=STAGE_CONTACTS,
            details={"missing_symbols": list(missing)},
        )
    return resolved


def _resolve_stage_context_target(
    context: Optional[AnalysisContext],
    *,
    dock_model: Any,
    receptor: Any,
    pose: Any,
    pose_index: Optional[int],
) -> Tuple[Any, Any, Any, Optional[int]]:
    """Fill missing stage-target components from an analysis context."""

    if context is None:
        return dock_model, receptor, pose, pose_index
    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance or None.")

    resolved_index = context.current_pose_index if pose_index is None else pose_index
    resolved_model = dock_model
    if resolved_model is None:
        if resolved_index is not None and 0 <= resolved_index < len(context.dock_models):
            resolved_model = context.dock_models[resolved_index]
        elif context.current_dock_model is not None:
            resolved_model = context.current_dock_model
        elif len(context.dock_models) == 1:
            resolved_model = context.dock_models[0]

    resolved_receptor = receptor if receptor is not None else context.receptor
    resolved_pose = pose
    if resolved_pose is None:
        if resolved_index is not None and 0 <= resolved_index < len(context.poses):
            resolved_pose = context.poses[resolved_index]
        elif context.current_pose is not None:
            resolved_pose = context.current_pose
        elif len(context.poses) == 1:
            resolved_pose = context.poses[0]

    return resolved_model, resolved_receptor, resolved_pose, resolved_index


def _contact_context_target(
    context: Optional[AnalysisContext],
    *,
    dock_model: Any,
    receptor: Any,
    pose: Any,
    pose_index: Optional[int],
) -> Tuple[Any, Any, Any, Optional[int]]:
    """Resolve contact-stage target components from a context."""

    return _resolve_stage_context_target(
        context,
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=pose_index,
    )


def resolve_contact_stage_target(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    receptor: Any = None,
    pose: Any = None,
    pose_index: Optional[int] = None,
    contacts_module: Optional[ModuleType] = None,
) -> ContactStageTarget:
    """Resolve one DockModel, receptor and pose for general-contact analysis."""

    module = _require_contacts_module(contacts_module)
    dock_model, receptor, pose, pose_index = _contact_context_target(
        context,
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=pose_index,
    )
    if dock_model is None:
        raise AnalysisInputError(
            "General-contact analysis requires a prepared DockModel.",
            stage=STAGE_CONTACTS,
        )

    if receptor is None:
        receptor = module.get_dock_model_receptor(dock_model, default=None)
    if receptor is None:
        raise AnalysisInputError(
            "General-contact analysis could not resolve a receptor.",
            stage=STAGE_CONTACTS,
        )

    if pose is None:
        pose = module.get_dock_model_pose(
            dock_model,
            pose_index=pose_index,
            default=None,
        )
    if pose is None:
        pose = get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_LIGAND,
            default=None,
            aliases=OBJECT_FIELD_ALIASES.get(DOCK_MODEL_FIELD_LIGAND, ()),
            skip_none=True,
        )
    if pose is None:
        raise AnalysisInputError(
            "General-contact analysis could not resolve a ligand pose.",
            stage=STAGE_CONTACTS,
        )

    normalized_index = None if pose_index is None else int(pose_index)
    if normalized_index is not None and normalized_index < 0:
        raise AnalysisInputError(
            "Contact-analysis pose_index cannot be negative.",
            stage=STAGE_CONTACTS,
        )

    dock_identifier = normalize_identifier(
        module.get_dock_model_identifier(dock_model),
        default="dock_model",
        maximum_length=256,
    )
    pose_identifier = normalize_identifier(
        module.get_pose_identifier(pose, pose_index=normalized_index),
        default=(
            f"pose_{normalized_index + 1}"
            if normalized_index is not None
            else "pose"
        ),
        maximum_length=256,
    )
    return ContactStageTarget(
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=normalized_index,
        dock_model_identifier=dock_identifier,
        pose_identifier=pose_identifier,
    )


# 11.4. Specialized result inspection and validation
# -----------------------------------------------------------------------------


def is_contact_analysis_result(
    value: Any,
    *,
    contacts_module: Optional[ModuleType] = None,
) -> bool:
    """Return whether a value is a native or structurally compatible result."""

    if value is None:
        return False
    module = contacts_module
    if module is not None:
        result_class = getattr(module, CONTACTS_RESULT_CLASS_NAME, None)
        if isinstance(result_class, type) and isinstance(value, result_class):
            return True
    return all(hasattr(value, name) for name in CONTACT_RESULT_REQUIRED_ATTRIBUTES)


def contact_result_contacts(value: Any) -> Tuple[Any, ...]:
    """Return atom-level contacts from a specialized result."""

    contacts_value = get_object_value(value, "contacts", default=(), skip_none=True)
    return tuple(normalize_object_sequence(contacts_value))


def contact_result_residue_contacts(value: Any) -> Tuple[Any, ...]:
    """Return residue-grouped contacts from a specialized result."""

    grouped = get_object_value(
        value,
        "residue_contacts",
        default=(),
        skip_none=True,
    )
    return tuple(normalize_object_sequence(grouped))


def contact_result_statistics(value: Any) -> Dict[str, Any]:
    """Return normalized contact statistics."""

    statistics = get_object_value(value, "statistics", default={}, skip_none=True)
    return normalize_statistics_mapping(statistics)


def contact_result_metadata(value: Any) -> Dict[str, Any]:
    """Return normalized contact metadata."""

    metadata = get_object_value(value, "metadata", default={}, skip_none=True)
    return normalize_metadata_mapping(metadata)


def _contact_count_from_result(value: Any) -> int:
    """Return contact count from properties, statistics or collection length."""

    direct = get_object_value(value, "contact_count", default=None, call=True)
    if direct is not None:
        try:
            return max(0, int(direct))
        except (TypeError, ValueError, OverflowError):
            pass
    statistics = contact_result_statistics(value)
    count = statistics.get("contact_count")
    if count is not None:
        try:
            return max(0, int(count))
        except (TypeError, ValueError, OverflowError):
            pass
    return len(contact_result_contacts(value))


def validate_contact_analysis_result(
    value: Any,
    *,
    contacts_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one specialized contact-analysis result."""

    errors: List[str] = []
    if not is_contact_analysis_result(value, contacts_module=contacts_module):
        errors.append(
            "Value is not a native or structurally compatible contact-analysis result."
        )
    else:
        try:
            contacts_value = contact_result_contacts(value)
        except Exception as exc:
            errors.append(f"Contact collection cannot be normalized: {exc}")
            contacts_value = ()
        try:
            grouped_value = contact_result_residue_contacts(value)
        except Exception as exc:
            errors.append(f"Residue-contact collection cannot be normalized: {exc}")
            grouped_value = ()
        try:
            statistics = contact_result_statistics(value)
        except Exception as exc:
            errors.append(f"Contact statistics cannot be normalized: {exc}")
            statistics = {}
        try:
            contact_count = _contact_count_from_result(value)
        except Exception as exc:
            errors.append(f"Contact count cannot be resolved: {exc}")
            contact_count = len(contacts_value)
        if contact_count != len(contacts_value):
            errors.append(
                "Contact count is inconsistent with the atom-contact collection."
            )
        residue_count = statistics.get("residue_count")
        if residue_count is None and isinstance(statistics.get("residues"), Mapping):
            residue_count = statistics["residues"].get("residue_count")
        if residue_count is not None:
            try:
                if int(residue_count) != len(grouped_value):
                    errors.append(
                        "Residue count is inconsistent with grouped residue contacts."
                    )
            except (TypeError, ValueError, OverflowError):
                errors.append("Contact residue count is not an integer.")

    result = tuple(errors[:MAX_CONTACT_ADAPTER_ERROR_DETAILS])
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Contact-analysis result validation failed.",
            stage=STAGE_CONTACTS,
            details={"errors": list(result)},
        )
    return result


# 11.5. Normalized contact result summaries
# -----------------------------------------------------------------------------


def _contact_distance_statistics(statistics: Mapping[str, Any]) -> Mapping[str, Any]:
    """Return a normalized distance-statistics mapping."""

    value = statistics.get("distance", {})
    return value if isinstance(value, Mapping) else {}


def _contact_classification_counts(
    statistics: Mapping[str, Any],
) -> Dict[str, int]:
    """Return normalized classification counts."""

    raw = statistics.get("classification_counts", {})
    if not isinstance(raw, Mapping):
        return {}
    result: Dict[str, int] = {}
    for key, value in raw.items():
        try:
            count = max(0, int(value))
        except (TypeError, ValueError, OverflowError):
            continue
        result[normalize_identifier(key, default="unknown")] = count
    return result


@dataclass(frozen=True)
class ContactResultSummary:
    """Compact normalized summary of a general-contact result."""

    contact_count: int
    residue_count: int
    ligand_atom_count: int
    receptor_atom_count: int
    cutoff: Optional[float]
    minimum_distance: Optional[float]
    maximum_distance: Optional[float]
    mean_distance: Optional[float]
    classification_counts: Mapping[str, int] = field(default_factory=dict)
    pose_identifier: Optional[str] = None
    dock_model_identifier: Optional[str] = None
    scene_coordinates: Optional[bool] = None

    def __post_init__(self) -> None:
        for field_name in (
            "contact_count",
            "residue_count",
            "ligand_atom_count",
            "receptor_atom_count",
        ):
            object.__setattr__(self, field_name, max(0, int(getattr(self, field_name))))
        for field_name in (
            "cutoff",
            "minimum_distance",
            "maximum_distance",
            "mean_distance",
        ):
            value = getattr(self, field_name)
            if value is not None:
                object.__setattr__(self, field_name, float(value))
        object.__setattr__(
            self,
            "classification_counts",
            MappingProxyType(dict(self.classification_counts)),
        )
        object.__setattr__(
            self,
            "pose_identifier",
            normalize_optional_identifier(self.pose_identifier),
        )
        object.__setattr__(
            self,
            "dock_model_identifier",
            normalize_optional_identifier(self.dock_model_identifier),
        )
        if self.scene_coordinates is not None:
            object.__setattr__(
                self,
                "scene_coordinates",
                normalize_boolean(
                    self.scene_coordinates,
                ),
            )

    @property
    def has_contacts(self) -> bool:
        """Return whether at least one contact was detected."""

        return self.contact_count > 0

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready contact summary."""

        return {
            "contact_count": self.contact_count,
            "has_contacts": self.has_contacts,
            "residue_count": self.residue_count,
            "ligand_atom_count": self.ligand_atom_count,
            "receptor_atom_count": self.receptor_atom_count,
            "cutoff": self.cutoff,
            "minimum_distance": self.minimum_distance,
            "maximum_distance": self.maximum_distance,
            "mean_distance": self.mean_distance,
            "classification_counts": dict(self.classification_counts),
            "pose_identifier": self.pose_identifier,
            "dock_model_identifier": self.dock_model_identifier,
            "scene_coordinates": self.scene_coordinates,
        }


def summarize_contact_analysis_result(value: Any) -> ContactResultSummary:
    """Create a normalized summary from a specialized result."""

    statistics = contact_result_statistics(value)
    metadata = contact_result_metadata(value)
    contacts_value = contact_result_contacts(value)
    grouped_value = contact_result_residue_contacts(value)
    distance = _contact_distance_statistics(statistics)

    cutoff = get_object_value(value, "cutoff", default=None, skip_none=True)
    if cutoff is not None:
        try:
            cutoff = float(cutoff)
        except (TypeError, ValueError, OverflowError):
            cutoff = None

    def optional_float(raw: Any) -> Optional[float]:
        if raw is None:
            return None
        try:
            number = float(raw)
        except (TypeError, ValueError, OverflowError):
            return None
        return number if math.isfinite(number) else None

    return ContactResultSummary(
        contact_count=_contact_count_from_result(value),
        residue_count=len(grouped_value),
        ligand_atom_count=len(
            normalize_object_sequence(
                get_object_value(value, "ligand_atoms", default=()),
                            )
        ),
        receptor_atom_count=len(
            normalize_object_sequence(
                get_object_value(value, "receptor_atoms", default=()),
                            )
        ),
        cutoff=cutoff,
        minimum_distance=optional_float(distance.get("minimum")),
        maximum_distance=optional_float(distance.get("maximum")),
        mean_distance=optional_float(distance.get("mean")),
        classification_counts=_contact_classification_counts(statistics),
        pose_identifier=(
            statistics.get("pose_identifier") or metadata.get("pose_identifier")
        ),
        dock_model_identifier=(
            statistics.get("dock_model_identifier")
            or metadata.get("dock_model_identifier")
        ),
        scene_coordinates=(
            statistics.get("scene_coordinates")
            if "scene_coordinates" in statistics
            else metadata.get("scene_coordinates")
        ),
    )


@dataclass(frozen=True)
class ContactStageOutput:
    """Integrated output produced by the general-contact stage adapter."""

    analysis: Any
    dock_model: Any
    receptor: Any
    pose: Any
    pose_index: Optional[int]
    contacts: Tuple[Any, ...]
    residue_contacts: Tuple[Any, ...]
    statistics: Mapping[str, Any]
    metadata: Mapping[str, Any]
    summary: ContactResultSummary
    attached: bool = False
    reused: bool = False
    module_name: str = CONTACTS_MODULE_NAME
    module_version: Optional[str] = None
    result_type: str = CONTACTS_RESULT_TYPE

    def __post_init__(self) -> None:
        object.__setattr__(self, "contacts", tuple(self.contacts))
        object.__setattr__(self, "residue_contacts", tuple(self.residue_contacts))
        object.__setattr__(
            self,
            "statistics",
            MappingProxyType(copy.deepcopy(dict(self.statistics))),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(copy.deepcopy(dict(self.metadata))),
        )
        object.__setattr__(self, "attached", bool(self.attached))
        object.__setattr__(self, "reused", bool(self.reused))
        object.__setattr__(
            self,
            "module_name",
            normalize_identifier(self.module_name, default=CONTACTS_MODULE_NAME),
        )
        object.__setattr__(
            self,
            "module_version",
            normalize_optional_text(self.module_version),
        )

    @property
    def contact_count(self) -> int:
        """Return the number of atom-level contacts."""

        return len(self.contacts)

    @property
    def residue_count(self) -> int:
        """Return the number of contacted receptor residues."""

        return len(self.residue_contacts)

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe integrated result representation."""

        result: Dict[str, Any] = {
            "schema": CONTACT_ADAPTER_SCHEMA_NAME,
            "schema_version": CONTACT_ADAPTER_SCHEMA_VERSION,
            "result_type": self.result_type,
            "pose_index": self.pose_index,
            "summary": self.summary.to_dict(),
            "statistics": to_json_compatible(dict(self.statistics)),
            "metadata": to_json_compatible(dict(self.metadata)),
            "attached": self.attached,
            "reused": self.reused,
            "module_name": self.module_name,
            "module_version": self.module_version,
        }
        if include_objects:
            result.update(
                {
                    "analysis": self.analysis,
                    "dock_model": self.dock_model,
                    "receptor": self.receptor,
                    "pose": self.pose,
                    "contacts": list(self.contacts),
                    "residue_contacts": list(self.residue_contacts),
                }
            )
        else:
            result.update(
                {
                    "analysis": to_json_compatible(self.analysis),
                    "dock_model": describe_object(self.dock_model).to_dict(),
                    "receptor": describe_object(self.receptor).to_dict(),
                    "pose": describe_object(self.pose).to_dict(),
                    "contacts": [to_json_compatible(item) for item in self.contacts],
                    "residue_contacts": [
                        to_json_compatible(item) for item in self.residue_contacts
                    ],
                }
            )
        return result


def adapt_contact_analysis_result(
    value: Any,
    *,
    target: Optional[ContactStageTarget] = None,
    attached: bool = False,
    reused: bool = False,
    contacts_module: Optional[ModuleType] = None,
) -> ContactStageOutput:
    """Adapt a specialized result to the integrated contact-stage output."""

    if isinstance(value, ContactStageOutput):
        return value
    module = _require_contacts_module(contacts_module)
    validate_contact_analysis_result(
        value,
        contacts_module=module,
        raise_on_error=True,
    )
    summary = summarize_contact_analysis_result(value)
    metadata = contact_result_metadata(value)
    metadata.setdefault("adapter_schema", CONTACT_ADAPTER_SCHEMA_NAME)
    metadata.setdefault("adapter_schema_version", CONTACT_ADAPTER_SCHEMA_VERSION)
    return ContactStageOutput(
        analysis=value,
        dock_model=target.dock_model if target else None,
        receptor=target.receptor if target else None,
        pose=target.pose if target else None,
        pose_index=target.pose_index if target else None,
        contacts=contact_result_contacts(value),
        residue_contacts=contact_result_residue_contacts(value),
        statistics=contact_result_statistics(value),
        metadata=metadata,
        summary=summary,
        attached=attached,
        reused=reused,
        module_name=getattr(module, "__name__", CONTACTS_MODULE_NAME),
        module_version=get_module_version(module),
    )


def validate_contact_stage_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate an integrated contact-stage output."""

    errors: List[str] = []
    if not isinstance(value, ContactStageOutput):
        errors.append("Value is not a ContactStageOutput instance.")
    else:
        if value.contact_count != value.summary.contact_count:
            errors.append("Integrated contact count does not match its summary.")
        if value.residue_count != value.summary.residue_count:
            errors.append("Integrated residue count does not match its summary.")
        specialized_errors = validate_contact_analysis_result(value.analysis)
        errors.extend(specialized_errors)
    result = tuple(errors[:MAX_CONTACT_ADAPTER_ERROR_DETAILS])
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Integrated contact-stage output validation failed.",
            stage=STAGE_CONTACTS,
            details={"errors": list(result)},
        )
    return result


# 11.6. Attachment reuse and execution helpers
# -----------------------------------------------------------------------------


def get_reusable_contact_analysis(
    target: ContactStageTarget,
    config: ContactAdapterConfig,
    *,
    contacts_module: Optional[ModuleType] = None,
) -> Any:
    """Return a valid previously attached contact analysis, when available."""

    module = _require_contacts_module(contacts_module)
    value = module.get_attached_contact_analysis(
        target.dock_model,
        pose_identifier=target.pose_identifier,
        attribute_name=config.analysis_attribute,
        default=None,
    )
    if value is None:
        return None
    return value if not validate_contact_analysis_result(value, contacts_module=module) else None


def _contact_execution_metadata(
    context: Optional[AnalysisContext],
    target: ContactStageTarget,
    config: ContactAdapterConfig,
) -> Dict[str, Any]:
    """Build provenance metadata passed to the specialized analyzer."""

    metadata = dict(config.metadata)
    metadata.setdefault("adapter", CONTACT_ADAPTER_SCHEMA_NAME)
    metadata.setdefault("adapter_version", CONTACT_ADAPTER_SCHEMA_VERSION)
    metadata.setdefault("stage", STAGE_CONTACTS)
    metadata.setdefault("dock_model_identifier", target.dock_model_identifier)
    metadata.setdefault("pose_identifier", target.pose_identifier)
    metadata.setdefault("pose_index", target.pose_index)
    if context is not None:
        metadata.setdefault("run_id", context.run_id)
        metadata.setdefault("request_id", context.request_id)
        metadata.setdefault("analysis_mode", context.mode)
    return metadata


def run_contact_analysis_adapter(
    target: ContactStageTarget,
    config: ContactAdapterConfig,
    *,
    context: Optional[AnalysisContext] = None,
    reuse_result: bool = False,
    contacts_module: Optional[ModuleType] = None,
) -> ContactStageOutput:
    """Run or reuse one general-contact analysis and adapt its result."""

    module = _require_contacts_module(contacts_module)
    if reuse_result:
        reusable = get_reusable_contact_analysis(
            target,
            config,
            contacts_module=module,
        )
        if reusable is not None:
            return adapt_contact_analysis_result(
                reusable,
                target=target,
                attached=True,
                reused=True,
                contacts_module=module,
            )

    metadata = _contact_execution_metadata(context, target, config)
    effective_config = config.with_metadata(metadata)
    kwargs = effective_config.to_call_kwargs(
        receptor=target.receptor,
        pose=target.pose,
        pose_index=target.pose_index,
    )
    analyzer = getattr(module, CONTACTS_ANALYSIS_FUNCTION)
    result = analyzer(target.dock_model, **kwargs)

    attached = False
    if effective_config.attach:
        attached_value = module.get_attached_contact_analysis(
            target.dock_model,
            pose_identifier=target.pose_identifier,
            attribute_name=effective_config.analysis_attribute,
            default=None,
        )
        attached = attached_value is result or attached_value == result

    return adapt_contact_analysis_result(
        result,
        target=target,
        attached=attached,
        reused=False,
        contacts_module=module,
    )


def _stage_failure_should_raise(
    context: Optional[AnalysisContext],
    raise_on_error: Optional[bool],
) -> bool:
    """Resolve whether one adapter failure should be raised."""

    if raise_on_error is not None:
        return bool(raise_on_error)
    if context is None:
        return True
    return context.config.runtime.failure_policy == FAILURE_POLICY_STRICT


def _contact_stage_failure_should_raise(
    context: Optional[AnalysisContext],
    raise_on_error: Optional[bool],
) -> bool:
    """Resolve whether contact-adapter failures should be raised."""

    return _stage_failure_should_raise(context, raise_on_error)


def _record_contact_stage_context(
    context: AnalysisContext,
    stage_result: AnalysisStageResult,
) -> None:
    """Store contact-stage output and statistics in the runtime context."""

    context.set_stage_data(CONTACTS_STAGE_DATA_KEY, stage_result)
    if isinstance(stage_result.value, ContactStageOutput):
        summary = stage_result.value.summary.to_dict()
        context.statistics[CONTACTS_STAGE_STATISTICS_KEY] = summary
        context.metadata[CONTACTS_STAGE_METADATA_KEY] = {
            "pose_identifier": stage_result.value.summary.pose_identifier,
            "dock_model_identifier": (
                stage_result.value.summary.dock_model_identifier
            ),
            "module_version": stage_result.value.module_version,
            "reused": stage_result.value.reused,
        }


def execute_contacts_stage(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    receptor: Any = None,
    pose: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    contacts_module: Optional[ModuleType] = None,
    raise_on_error: Optional[bool] = None,
) -> AnalysisStageResult:
    """Execute the registered general-contact pipeline stage."""

    integrated_config = (
        context.config if context is not None and config is None else coerce_analysis_config(config)
    )
    stage_config = integrated_config.stage_config(STAGE_CONTACTS)
    stage_result = AnalysisStageResult(
        stage=STAGE_CONTACTS,
        required=stage_config.required,
    )
    if not stage_config.enabled:
        stage_result.skip("General-contact analysis is disabled by configuration.")
        if context is not None:
            _record_contact_stage_context(context, stage_result)
        return stage_result

    stage_result.start()
    module: Optional[ModuleType] = None
    try:
        if context is not None:
            context.raise_if_cancelled(stage=STAGE_CONTACTS)
            context.set_current_stage(STAGE_CONTACTS)
        module = _require_contacts_module(contacts_module)
        target = resolve_contact_stage_target(
            context,
            dock_model=dock_model,
            receptor=receptor,
            pose=pose,
            pose_index=pose_index,
            contacts_module=module,
        )
        adapter_config = resolve_contact_adapter_config(
            integrated_config,
            overrides=overrides,
            metadata={
                "dock_model_identifier": target.dock_model_identifier,
                "pose_identifier": target.pose_identifier,
            },
        )
        stage_result.input_summary = target.to_dict(include_objects=False)
        stage_result.metadata.update(
            {
                "adapter_schema": CONTACT_ADAPTER_SCHEMA_NAME,
                "adapter_schema_version": CONTACT_ADAPTER_SCHEMA_VERSION,
                "module_name": getattr(module, "__name__", CONTACTS_MODULE_NAME),
                "module_version": get_module_version(module),
                "configuration": adapter_config.to_dict(),
            }
        )
        output = run_contact_analysis_adapter(
            target,
            adapter_config,
            context=context,
            reuse_result=stage_config.reuse_result,
            contacts_module=module,
        )
        if stage_config.validate_result:
            validate_contact_stage_output(output, raise_on_error=True)
        stage_result.cached = output.reused
        stage_result.statistics = dict(output.statistics)
        stage_result.output_summary = output.summary.to_dict()
        stage_result.succeed(
            output,
            message=(
                "Reused an attached general-contact analysis."
                if output.reused
                else "General-contact analysis completed successfully."
            ),
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisStageError(
                "General-contact analysis failed.",
                stage=STAGE_CONTACTS,
                cause=exc,
                details={"exception_type": type(exc).__name__},
            )
        stage_result.fail(
            wrapped,
            include_traceback=(
                context is not None and context.config.runtime.collect_diagnostics
            ),
        )
        if _contact_stage_failure_should_raise(context, raise_on_error):
            raise wrapped from exc
    finally:
        if context is not None:
            _record_contact_stage_context(context, stage_result)
            context.set_current_stage(None)

    return stage_result


# 11.7. Convenience adapters for one or multiple prepared models
# -----------------------------------------------------------------------------


def analyze_dock_model_contacts(
    dock_model: Any,
    *,
    receptor: Any = None,
    pose: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    contacts_module: Optional[ModuleType] = None,
) -> ContactStageOutput:
    """Analyze contacts for one prepared DockModel and return integrated output."""

    stage_result = execute_contacts_stage(
        None,
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=pose_index,
        config=config,
        overrides=overrides,
        contacts_module=contacts_module,
        raise_on_error=True,
    )
    if not isinstance(stage_result.value, ContactStageOutput):
        raise AnalysisIntegrationError(
            "The contact stage did not produce a ContactStageOutput.",
            stage=STAGE_CONTACTS,
        )
    return stage_result.value


def analyze_prepared_dock_models_contacts(
    dock_models: Iterable[Any],
    *,
    receptor: Any = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    contacts_module: Optional[ModuleType] = None,
    continue_on_error: bool = False,
) -> Tuple[AnalysisStageResult, ...]:
    """Run the contact adapter sequentially for prepared DockModel objects."""

    models = tuple(normalize_object_sequence(dock_models))
    if not models:
        return ()
    results: List[AnalysisStageResult] = []
    for index, model in enumerate(models):
        try:
            result = execute_contacts_stage(
                None,
                dock_model=model,
                receptor=receptor,
                pose_index=index,
                config=config,
                overrides=overrides,
                contacts_module=contacts_module,
                raise_on_error=not continue_on_error,
            )
        except Exception as exc:
            if not continue_on_error:
                raise
            result = AnalysisStageResult(stage=STAGE_CONTACTS)
            result.start().fail(exc)
        results.append(result)
    return tuple(results)


# 11.8. Stage registry integration
# -----------------------------------------------------------------------------


def contact_stage_result_adapter(value: Any, **kwargs: Any) -> ContactStageOutput:
    """Registry-compatible adapter for specialized contact results."""

    return adapt_contact_analysis_result(value, **kwargs)


def contact_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible validator for contact-stage values."""

    if isinstance(value, AnalysisStageResult):
        if value.value is None:
            return () if value.status == StageStatus.SKIPPED else (
                "Contact stage result does not contain a value.",
            )
        value = value.value
    if isinstance(value, ContactStageOutput):
        return validate_contact_stage_output(value)
    return validate_contact_analysis_result(value)


def register_contact_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the general-contact executor, adapter and validator."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_CONTACTS)
    updated_metadata = dict(definition.metadata)
    updated_metadata.update(
        {
            "adapter_schema": CONTACT_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": CONTACT_ADAPTER_SCHEMA_VERSION,
            "analysis_function": CONTACTS_ANALYSIS_FUNCTION,
            "result_type": CONTACTS_RESULT_TYPE,
        }
    )
    updated = replace(
        definition,
        executor=execute_contacts_stage,
        result_adapter=contact_stage_result_adapter,
        validator=contact_stage_validator,
        metadata=updated_metadata,
    )
    target_registry.replace(updated)
    return updated


def contact_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the default contacts stage uses this adapter."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_CONTACTS)
    return bool(
        definition is not None
        and definition.executor is execute_contacts_stage
        and definition.result_adapter is contact_stage_result_adapter
        and definition.validator is contact_stage_validator
    )


# 11.9. Adapter diagnostics and validation
# -----------------------------------------------------------------------------


def summarize_contact_stage_result(value: Any) -> Dict[str, Any]:
    """Return a compact summary of a contact-stage result or output."""

    if isinstance(value, AnalysisStageResult):
        result: Dict[str, Any] = {
            "stage": value.stage,
            "status": value.status.value,
            "cached": value.cached,
            "duration_seconds": value.duration_seconds,
            "message_count": len(value.messages),
            "warning_count": len(value.warnings),
            "error_count": len(value.errors),
        }
        if isinstance(value.value, ContactStageOutput):
            result.update(value.value.summary.to_dict())
        return result
    if isinstance(value, ContactStageOutput):
        result = value.summary.to_dict()
        result.update(
            {
                "attached": value.attached,
                "reused": value.reused,
                "module_version": value.module_version,
            }
        )
        return result
    if is_contact_analysis_result(value):
        return summarize_contact_analysis_result(value).to_dict()
    raise TypeError(
        "value must be an AnalysisStageResult, ContactStageOutput or "
        "contact-analysis result."
    )


def validate_contact_adapter_conventions() -> Dict[str, Any]:
    """Validate Section 11 adapter conventions and registry integration."""

    failures: List[str] = []

    if canonicalize_contact_residue_side("protein") != "receptor":
        failures.append("Receptor-side alias resolution failed.")
    if canonicalize_contact_residue_side("pose") != "ligand":
        failures.append("Ligand-side alias resolution failed.")

    config = ContactAdapterConfig.from_mapping(
        {
            "distance_cutoff": 4.5,
            "heavy": True,
            "ignore_solvent": True,
            "max_contacts": 25,
            "side": "protein",
            "attribute": "contact_results",
            "scene_coordinates": False,
        }
    )
    if config.cutoff != 4.5 or config.maximum_contacts != 25:
        failures.append("Contact adapter configuration aliases failed.")
    if config.residue_side != "receptor":
        failures.append("Contact residue side was not canonicalized.")
    if config.analysis_attribute != "contact_results":
        failures.append("Contact analysis attribute was not preserved.")
    if config.scene:
        failures.append("Contact scene-coordinate flag was not preserved.")

    class FakeContactResult:
        def __init__(self) -> None:
            self.contacts = (SimpleNamespace(classification="contact"),)
            self.residue_contacts = (SimpleNamespace(),)
            self.ligand_atoms = (SimpleNamespace(),)
            self.receptor_atoms = (SimpleNamespace(), SimpleNamespace())
            self.cutoff = 4.5
            self.statistics = {
                "contact_count": 1,
                "classification_counts": {"unknown": 1},
                "distance": {"minimum": 3.0, "maximum": 3.0, "mean": 3.0},
                "pose_identifier": "pose_1",
                "dock_model_identifier": "dock_1",
                "scene_coordinates": False,
                "residues": {"residue_count": 1},
            }
            self.metadata = {
                "pose_identifier": "pose_1",
                "dock_model_identifier": "dock_1",
            }

    class FakeContactModule(ModuleType):
        pass

    fake_module = FakeContactModule("contacts")
    fake_module.__version__ = "test"
    fake_module.ContactAnalysisResult = FakeContactResult
    fake_module.get_dock_model_receptor = lambda model, default=None: getattr(
        model, "receptor", default
    )
    fake_module.get_dock_model_pose = (
        lambda model, pose_index=None, default=None: getattr(model, "pose", default)
    )
    fake_module.get_dock_model_identifier = lambda model: getattr(model, "name", "dock")
    fake_module.get_pose_identifier = (
        lambda pose, pose_index=None: f"pose_{(pose_index or 0) + 1}"
    )

    attached_store: Dict[str, Any] = {}

    def fake_get_attached(
        dock_model: Any,
        *,
        pose_identifier: Optional[str] = None,
        attribute_name: str = CONTACTS_DEFAULT_ANALYSIS_ATTRIBUTE,
        default: Any = None,
    ) -> Any:
        return attached_store.get(pose_identifier, default)

    def fake_attach(
        dock_model: Any,
        result: Any,
        *,
        pose: Any = None,
        pose_identifier: Optional[str] = None,
        attribute_name: str = CONTACTS_DEFAULT_ANALYSIS_ATTRIBUTE,
        attach_to_pose: bool = True,
        overwrite: bool = True,
    ) -> bool:
        if overwrite or pose_identifier not in attached_store:
            attached_store[str(pose_identifier)] = result
        return True

    def fake_analyze(dock_model: Any, **kwargs: Any) -> Any:
        result = FakeContactResult()
        if kwargs.get("attach"):
            fake_attach(
                dock_model,
                result,
                pose=kwargs.get("pose"),
                pose_identifier=fake_module.get_pose_identifier(
                    kwargs.get("pose"), kwargs.get("pose_index")
                ),
                attribute_name=kwargs.get(
                    "analysis_attribute", CONTACTS_DEFAULT_ANALYSIS_ATTRIBUTE
                ),
                attach_to_pose=kwargs.get("attach_to_pose", True),
                overwrite=kwargs.get("overwrite", True),
            )
        return result

    fake_module.get_attached_contact_analysis = fake_get_attached
    fake_module.attach_contact_analysis = fake_attach
    fake_module.analyze_contacts = fake_analyze
    fake_module.analyze_all_pose_contacts = lambda *args, **kwargs: ()

    receptor = SimpleNamespace(name="receptor")
    pose = SimpleNamespace(name="pose")
    dock_model = SimpleNamespace(name="dock_1", receptor=receptor, pose=pose, ligand=pose)
    target = resolve_contact_stage_target(
        None,
        dock_model=dock_model,
        pose_index=0,
        contacts_module=fake_module,
    )
    output = run_contact_analysis_adapter(
        target,
        config,
        contacts_module=fake_module,
    )
    if output.contact_count != 1 or output.residue_count != 1:
        failures.append("Contact result adaptation produced incorrect counts.")
    if validate_contact_stage_output(output):
        failures.append("A valid contact-stage output did not validate.")
    if json.loads(json.dumps(output.to_dict()))["summary"]["contact_count"] != 1:
        failures.append("Contact-stage output JSON conversion failed.")

    integrated = AnalysisConfig(
        stage_configs={
            STAGE_CONTACTS: AnalysisStageConfig(
                enabled=True,
                attach_results=True,
                validate_result=True,
                reuse_result=True,
                parameters={"cutoff": 4.5, "scene": False},
            )
        },
        runtime=AnalysisRuntimeConfig(
            failure_policy=FAILURE_POLICY_STRICT,
            attach_results=True,
            reuse_results=True,
        ),
    )
    request = AnalysisRequest(
        dock_models=(dock_model,),
        receptor=receptor,
        poses=(pose,),
        config=integrated,
    )
    context = AnalysisContext(
        request=request,
        dock_models=[dock_model],
        receptor=receptor,
        poses=[pose],
        current_pose_index=0,
    )
    stage_result = execute_contacts_stage(
        context,
        contacts_module=fake_module,
        raise_on_error=True,
    )
    if not stage_result.succeeded:
        failures.append("Contact-stage executor did not succeed.")
    if not isinstance(stage_result.value, ContactStageOutput):
        failures.append("Contact-stage executor returned an unexpected value.")
    if context.get_stage_data(STAGE_CONTACTS) is not stage_result:
        failures.append("Contact-stage result was not stored in the context.")
    if STAGE_CONTACTS not in context.statistics:
        failures.append("Contact-stage statistics were not stored in the context.")

    registry = create_default_stage_registry()
    register_contact_stage_adapter(registry=registry)
    if not contact_stage_adapter_registered(registry=registry):
        failures.append("Contact-stage adapter was not registered correctly.")
    definition = registry.require(STAGE_CONTACTS)
    if definition.executor is not execute_contacts_stage:
        failures.append("Contact-stage executor registration failed.")

    real_module = _require_contacts_module()
    missing_interface = tuple(
        name for name in CONTACTS_REQUIRED_SYMBOLS if not hasattr(real_module, name)
    )
    if missing_interface:
        failures.append(
            "The repository contacts module is missing required symbols: "
            + ", ".join(missing_interface)
        )

    if failures:
        raise RuntimeError(
            "Contact-adapter convention validation failed: " + " ".join(failures)
        )

    return {
        "valid": True,
        "schema": CONTACT_ADAPTER_SCHEMA_NAME,
        "schema_version": CONTACT_ADAPTER_SCHEMA_VERSION,
        "required_symbols": len(CONTACTS_REQUIRED_SYMBOLS),
        "supported_parameters": len(CONTACT_ADAPTER_FIELDS),
        "validated_cases": 18,
    }


