# 12.2. Hydrogen-bond adapter configuration
# -----------------------------------------------------------------------------


def canonicalize_hbond_mode(value: Any) -> str:
    """Return a canonical hydrogen-bond analysis mode."""

    token = normalize_identifier(
        value,
        default=HBONDS_DEFAULT_MODE,
        maximum_length=64,
    )
    canonical = HBOND_MODE_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported hydrogen-bond mode {value!r}. Supported values: "
            f"{', '.join(sorted(HBOND_MODES))}."
        )
    return canonical


def canonicalize_hbond_residue_side(value: Any) -> str:
    """Return the canonical residue grouping side used by ``hbonds.py``."""

    token = normalize_identifier(
        value,
        default=HBONDS_DEFAULT_RESIDUE_SIDE,
        maximum_length=64,
    )
    canonical = HBOND_RESIDUE_SIDE_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported hydrogen-bond residue side {value!r}. Supported "
            f"values: {', '.join(sorted(HBOND_RESIDUE_SIDES))}."
        )
    return canonical


def canonicalize_hbond_vector_method(value: Any) -> str:
    """Return a canonical inferred-vector method."""

    token = normalize_identifier(
        value,
        default=HBONDS_DEFAULT_VECTOR_METHOD,
        maximum_length=64,
    )
    canonical = HBOND_VECTOR_METHOD_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported hydrogen-bond vector method {value!r}. Supported "
            f"values: {', '.join(sorted(HBOND_VECTOR_METHODS))}."
        )
    return canonical


def _normalize_hbond_parameter_name(value: Any) -> str:
    """Normalize one hydrogen-bond adapter parameter name."""

    token = normalize_identifier(value, maximum_length=128)
    return HBOND_PARAMETER_ALIASES.get(token, token)


def _hbond_optional_float(
    value: Any,
    *,
    field_name: str,
    minimum: float = 0.0,
    allow_zero: bool = False,
) -> Optional[float]:
    """Normalize one finite optional floating-point parameter."""

    if value is None:
        return None
    try:
        normalized = normalize_float(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(
            f"{field_name} must be a finite number."
        ) from exc
    if normalized is None:
        return None
    invalid = normalized < minimum if allow_zero else normalized <= minimum
    if invalid:
        comparator = "at least" if allow_zero else "greater than"
        raise AnalysisConfigurationError(
            f"{field_name} must be {comparator} {minimum}."
        )
    return normalized


def _hbond_optional_integer(value: Any, *, field_name: str) -> Optional[int]:
    """Normalize one positive optional integer parameter."""

    if value is None:
        return None
    try:
        normalized = normalize_integer(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(f"{field_name} must be an integer.") from exc
    if normalized is None:
        return None
    if normalized <= 0:
        raise AnalysisConfigurationError(f"{field_name} must be greater than zero.")
    return normalized


def _hbond_metadata(value: Any) -> Mapping[str, Any]:
    """Return immutable hydrogen-bond analysis metadata."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        raise AnalysisConfigurationError("hbonds.metadata must be a mapping.")
    if len(value) > MAX_HBOND_ADAPTER_METADATA_ITEMS:
        raise AnalysisConfigurationError(
            "hbonds.metadata exceeds the supported item limit."
        )
    return MappingProxyType(copy.deepcopy(dict(value)))


def _hbond_classification_mapping(value: Any) -> Mapping[str, Any]:
    """Return immutable classification configuration values."""

    if value is None:
        return MappingProxyType({})
    if isinstance(value, Mapping):
        converted = dict(value)
    else:
        to_dict_method = getattr(value, "to_dict", None)
        if callable(to_dict_method):
            candidate = to_dict_method()
            if not isinstance(candidate, Mapping):
                raise AnalysisConfigurationError(
                    "Hydrogen-bond classification to_dict() must return a mapping."
                )
            converted = dict(candidate)
        elif is_dataclass(value) and not isinstance(value, type):
            converted = asdict(value)
        else:
            raise AnalysisConfigurationError(
                "Hydrogen-bond classification configuration must be a mapping "
                "or dataclass-like object."
            )
    if len(converted) > MAX_HBOND_ADAPTER_CLASSIFICATION_ITEMS:
        raise AnalysisConfigurationError(
            "Hydrogen-bond classification configuration is too large."
        )
    return MappingProxyType(copy.deepcopy(converted))


@dataclass(frozen=True)
class HydrogenBondAdapterConfig:
    """Resolved configuration passed to the hydrogen-bond analyzer."""

    mode: str = HBONDS_DEFAULT_MODE
    analyze_ligand_as_donor: bool = True
    analyze_receptor_as_donor: bool = True
    allow_inferred_fallback: bool = True
    donor_acceptor_cutoff: Optional[float] = None
    hydrogen_acceptor_cutoff: Optional[float] = None
    minimum_dha_angle: Optional[float] = None
    minimum_inferred_angle: Optional[float] = None
    distance_tolerance: Optional[float] = None
    angle_tolerance: Optional[float] = None
    require_inferred_donor_angle: bool = True
    require_acceptor_angle: bool = False
    donor_vector_method: str = HBONDS_DEFAULT_VECTOR_METHOD
    acceptor_vector_method: str = HBONDS_DEFAULT_VECTOR_METHOD
    allow_distance_hydrogen_assignment: bool = True
    include_ambiguous_assignments: bool = True
    deduplicate: bool = True
    maximum_hydrogen_bonds: Optional[int] = None
    residue_side: str = HBONDS_DEFAULT_RESIDUE_SIDE
    classification_parameters: Mapping[str, Any] = field(default_factory=dict)
    include_rejected: bool = False
    sort_by_strength: bool = True
    calculate_statistics: bool = True
    store_result: bool = True
    store_active_result: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "mode", canonicalize_hbond_mode(self.mode))
        object.__setattr__(
            self,
            "residue_side",
            canonicalize_hbond_residue_side(self.residue_side),
        )
        object.__setattr__(
            self,
            "donor_vector_method",
            canonicalize_hbond_vector_method(self.donor_vector_method),
        )
        object.__setattr__(
            self,
            "acceptor_vector_method",
            canonicalize_hbond_vector_method(self.acceptor_vector_method),
        )
        for field_name in (
            "analyze_ligand_as_donor",
            "analyze_receptor_as_donor",
            "allow_inferred_fallback",
            "require_inferred_donor_angle",
            "require_acceptor_angle",
            "allow_distance_hydrogen_assignment",
            "include_ambiguous_assignments",
            "deduplicate",
            "include_rejected",
            "sort_by_strength",
            "calculate_statistics",
            "store_result",
            "store_active_result",
        ):
            object.__setattr__(
                self,
                field_name,
                normalize_boolean(getattr(self, field_name)),
            )
        for field_name in (
            "donor_acceptor_cutoff",
            "hydrogen_acceptor_cutoff",
            "minimum_dha_angle",
            "minimum_inferred_angle",
        ):
            object.__setattr__(
                self,
                field_name,
                _hbond_optional_float(
                    getattr(self, field_name),
                    field_name=f"hbonds.{field_name}",
                ),
            )
        for field_name in ("distance_tolerance", "angle_tolerance"):
            object.__setattr__(
                self,
                field_name,
                _hbond_optional_float(
                    getattr(self, field_name),
                    field_name=f"hbonds.{field_name}",
                    minimum=0.0,
                    allow_zero=True,
                ),
            )
        for angle_field in ("minimum_dha_angle", "minimum_inferred_angle"):
            angle = getattr(self, angle_field)
            if angle is not None and angle > 180.0:
                raise AnalysisConfigurationError(
                    f"hbonds.{angle_field} cannot exceed 180 degrees."
                )
        object.__setattr__(
            self,
            "maximum_hydrogen_bonds",
            _hbond_optional_integer(
                self.maximum_hydrogen_bonds,
                field_name="hbonds.maximum_hydrogen_bonds",
            ),
        )
        if not (self.analyze_ligand_as_donor or self.analyze_receptor_as_donor):
            raise AnalysisConfigurationError(
                "At least one hydrogen-bond donor direction must be enabled."
            )
        object.__setattr__(
            self,
            "classification_parameters",
            _hbond_classification_mapping(self.classification_parameters),
        )
        object.__setattr__(self, "metadata", _hbond_metadata(self.metadata))

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "HydrogenBondAdapterConfig":
        """Create adapter configuration from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Hydrogen-bond adapter configuration must be a mapping."
            )
        normalized: Dict[str, Any] = {}
        unknown: List[str] = []
        for raw_name, raw_value in values.items():
            name = _normalize_hbond_parameter_name(raw_name)
            if name not in HBOND_ADAPTER_FIELDS:
                unknown.append(str(raw_name))
                continue
            if name in normalized:
                raise AnalysisConfigurationError(
                    "Duplicate hydrogen-bond adapter parameter after alias "
                    f"resolution: {name!r}."
                )
            normalized[name] = raw_value
        if strict and unknown:
            raise AnalysisConfigurationError(
                "Unknown hydrogen-bond adapter parameters: "
                f"{', '.join(unknown)}. Supported parameters: "
                f"{', '.join(sorted(HBOND_ADAPTER_FIELDS))}."
            )
        return cls(**normalized)

    def with_metadata(
        self,
        values: Optional[Mapping[str, Any]],
    ) -> "HydrogenBondAdapterConfig":
        """Return a copy with merged provenance metadata."""

        merged = dict(self.metadata)
        if values:
            merged.update(dict(values))
        return replace(self, metadata=merged)

    def classification_config(self, hbonds_module: ModuleType) -> Any:
        """Build the native classification configuration object."""

        config_class = getattr(
            hbonds_module,
            HBONDS_CLASSIFICATION_CONFIG_CLASS_NAME,
        )
        if not self.classification_parameters:
            default_value = getattr(
                hbonds_module,
                "DEFAULT_HBOND_CLASSIFICATION_CONFIG",
                None,
            )
            return default_value if default_value is not None else config_class()
        try:
            return config_class(**dict(self.classification_parameters))
        except Exception as exc:
            raise AnalysisConfigurationError(
                "Invalid hydrogen-bond classification configuration."
            ) from exc

    def analysis_kwargs(self) -> Dict[str, Any]:
        """Return parameters forwarded to hydrogen-bond detection."""

        return {
            "mode": self.mode,
            "analyze_ligand_as_donor": self.analyze_ligand_as_donor,
            "analyze_receptor_as_donor": self.analyze_receptor_as_donor,
            "allow_inferred_fallback": self.allow_inferred_fallback,
            "donor_acceptor_cutoff": self.donor_acceptor_cutoff,
            "hydrogen_acceptor_cutoff": self.hydrogen_acceptor_cutoff,
            "minimum_dha_angle": self.minimum_dha_angle,
            "minimum_inferred_angle": self.minimum_inferred_angle,
            "distance_tolerance": self.distance_tolerance,
            "angle_tolerance": self.angle_tolerance,
            "require_inferred_donor_angle": self.require_inferred_donor_angle,
            "require_acceptor_angle": self.require_acceptor_angle,
            "donor_vector_method": self.donor_vector_method,
            "acceptor_vector_method": self.acceptor_vector_method,
            "allow_distance_hydrogen_assignment": (
                self.allow_distance_hydrogen_assignment
            ),
            "include_ambiguous_assignments": self.include_ambiguous_assignments,
            "deduplicate": self.deduplicate,
            "maximum_hydrogen_bonds": self.maximum_hydrogen_bonds,
            "metadata": dict(self.metadata),
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready adapter configuration."""

        return {
            "mode": self.mode,
            "analyze_ligand_as_donor": self.analyze_ligand_as_donor,
            "analyze_receptor_as_donor": self.analyze_receptor_as_donor,
            "allow_inferred_fallback": self.allow_inferred_fallback,
            "donor_acceptor_cutoff": self.donor_acceptor_cutoff,
            "hydrogen_acceptor_cutoff": self.hydrogen_acceptor_cutoff,
            "minimum_dha_angle": self.minimum_dha_angle,
            "minimum_inferred_angle": self.minimum_inferred_angle,
            "distance_tolerance": self.distance_tolerance,
            "angle_tolerance": self.angle_tolerance,
            "require_inferred_donor_angle": self.require_inferred_donor_angle,
            "require_acceptor_angle": self.require_acceptor_angle,
            "donor_vector_method": self.donor_vector_method,
            "acceptor_vector_method": self.acceptor_vector_method,
            "allow_distance_hydrogen_assignment": (
                self.allow_distance_hydrogen_assignment
            ),
            "include_ambiguous_assignments": self.include_ambiguous_assignments,
            "deduplicate": self.deduplicate,
            "maximum_hydrogen_bonds": self.maximum_hydrogen_bonds,
            "residue_side": self.residue_side,
            "classification_parameters": to_json_compatible(
                dict(self.classification_parameters)
            ),
            "include_rejected": self.include_rejected,
            "sort_by_strength": self.sort_by_strength,
            "calculate_statistics": self.calculate_statistics,
            "store_result": self.store_result,
            "store_active_result": self.store_active_result,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


def _hbond_mapping_from_config_object(value: Any) -> Dict[str, Any]:
    """Convert a module-specific configuration object to a mapping."""

    if value is None:
        return {}
    if isinstance(value, HydrogenBondAdapterConfig):
        return value.to_dict()
    if isinstance(value, Mapping):
        return dict(value)
    to_dict_method = getattr(value, "to_dict", None)
    if callable(to_dict_method):
        converted = to_dict_method()
        if isinstance(converted, Mapping):
            return dict(converted)
    if is_dataclass(value) and not isinstance(value, type):
        return asdict(value)
    raise AnalysisConfigurationError(
        "The hbonds module configuration must be a mapping, dataclass or "
        "HydrogenBondAdapterConfig."
    )


def resolve_hbond_adapter_config(
    config: Optional[AnalysisConfigLike] = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    strict: bool = True,
) -> HydrogenBondAdapterConfig:
    """Resolve effective hydrogen-bond parameters."""

    integrated = coerce_analysis_config(config)
    stage_config = integrated.stage_config(STAGE_HBONDS)
    module_config = integrated.module_config(HBONDS_MODULE_NAME, {})
    merged: Dict[str, Any] = {}
    merged.update(_hbond_mapping_from_config_object(module_config))
    merged.update(dict(stage_config.parameters))
    if overrides:
        merged.update(dict(overrides))

    attachment_policy = integrated.runtime.attachment_policy
    store_enabled = bool(
        integrated.runtime.attach_results
        and stage_config.attach_results
        and attachment_policy != ATTACHMENT_POLICY_NONE
    )
    merged.setdefault("store_result", store_enabled)
    resolved = HydrogenBondAdapterConfig.from_mapping(merged, strict=strict)
    if metadata:
        resolved = resolved.with_metadata(metadata)
    return resolved


# 12.3. Stage target resolution
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class HydrogenBondStageTarget:
    """Resolved molecular inputs for one hydrogen-bond stage."""

    dock_model: Any
    receptor: Any
    pose: Any
    pose_index: Optional[int]
    dock_model_identifier: str
    pose_identifier: str

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe target representation."""

        result: Dict[str, Any] = {
            "dock_model_identifier": self.dock_model_identifier,
            "pose_identifier": self.pose_identifier,
            "pose_index": self.pose_index,
        }
        if include_objects:
            result.update(
                {
                    "dock_model": self.dock_model,
                    "receptor": self.receptor,
                    "pose": self.pose,
                }
            )
        else:
            result.update(
                {
                    "dock_model": describe_object(self.dock_model).to_dict(),
                    "receptor": describe_object(self.receptor).to_dict(),
                    "pose": describe_object(self.pose).to_dict(),
                }
            )
        return result


def _require_hbonds_module(module: Optional[ModuleType] = None) -> ModuleType:
    """Return a validated hydrogen-bond module."""

    resolved = module or require_analysis_module(HBONDS_MODULE_NAME, load=True)
    missing = tuple(
        name for name in HBONDS_REQUIRED_SYMBOLS if not hasattr(resolved, name)
    )
    if missing:
        raise AnalysisDependencyError(
            "The hbonds module does not expose the required adapter interface.",
            stage=STAGE_HBONDS,
            details={"missing_symbols": list(missing)},
        )
    return resolved


def _hbond_context_target(
    context: Optional[AnalysisContext],
    *,
    dock_model: Any,
    receptor: Any,
    pose: Any,
    pose_index: Optional[int],
) -> Tuple[Any, Any, Any, Optional[int]]:
    """Resolve hydrogen-bond target components from a context."""

    return _resolve_stage_context_target(
        context,
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=pose_index,
    )


def _hbond_model_identifier(dock_model: Any) -> str:
    """Return a stable human-readable DockModel identifier."""

    candidate = get_object_value(
        dock_model,
        "name",
        default=None,
        aliases=("identifier", "id", "model_id"),
        skip_none=True,
    )
    if candidate is None:
        candidate = describe_object(dock_model).identifier
    return normalize_identifier(
        candidate,
        default="dock_model",
        maximum_length=256,
    )


def _hbond_pose_identifier(
    pose: Any,
    pose_index: Optional[int],
    *,
    dock_model: Any,
    hbonds_module: ModuleType,
) -> str:
    """Return the storage key for a ligand pose."""

    if pose is not None:
        try:
            pose_key, _ = hbonds_module.get_dockmodel_pose(dock_model, pose)
            if str(pose_key).strip():
                return normalize_identifier(
                    pose_key,
                    default="pose",
                    maximum_length=256,
                )
        except Exception:
            pass
    candidate = get_object_value(
        pose,
        "name",
        default=None,
        aliases=("identifier", "id", "pose_id"),
        skip_none=True,
    )
    if candidate is None and pose_index is not None:
        candidate = f"pose_{pose_index + 1}"
    if candidate is None:
        candidate = "pose"
    return normalize_identifier(candidate, default="pose", maximum_length=256)


def resolve_hbond_stage_target(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    receptor: Any = None,
    pose: Any = None,
    pose_index: Optional[int] = None,
    hbonds_module: Optional[ModuleType] = None,
) -> HydrogenBondStageTarget:
    """Resolve one DockModel, receptor and pose for hydrogen-bond analysis."""

    module = _require_hbonds_module(hbonds_module)
    dock_model, receptor, pose, pose_index = _hbond_context_target(
        context,
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=pose_index,
    )
    if dock_model is None:
        raise AnalysisInputError(
            "Hydrogen-bond analysis requires a prepared DockModel.",
            stage=STAGE_HBONDS,
        )

    if receptor is None:
        receptor = module.get_dockmodel_receptor(dock_model)
    if receptor is None:
        raise AnalysisInputError(
            "Hydrogen-bond analysis could not resolve a receptor.",
            stage=STAGE_HBONDS,
        )

    if pose is None and pose_index is not None:
        try:
            _, pose = module.get_dockmodel_pose(dock_model, pose_index)
        except Exception as exc:
            raise AnalysisInputError(
                "Hydrogen-bond analysis could not resolve the requested pose.",
                stage=STAGE_HBONDS,
                cause=exc,
            ) from exc
    if pose is None:
        pose = module.get_dockmodel_active_ligand(dock_model)
    if pose is None:
        pose = get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_LIGAND,
            default=None,
            aliases=OBJECT_FIELD_ALIASES.get(DOCK_MODEL_FIELD_LIGAND, ()),
            skip_none=True,
        )
    if pose is None:
        raise AnalysisInputError(
            "Hydrogen-bond analysis could not resolve a ligand pose.",
            stage=STAGE_HBONDS,
        )

    normalized_index = None if pose_index is None else int(pose_index)
    if normalized_index is not None and normalized_index < 0:
        raise AnalysisInputError(
            "Hydrogen-bond pose_index cannot be negative.",
            stage=STAGE_HBONDS,
        )
    return HydrogenBondStageTarget(
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=normalized_index,
        dock_model_identifier=_hbond_model_identifier(dock_model),
        pose_identifier=_hbond_pose_identifier(
            pose,
            normalized_index,
            dock_model=dock_model,
            hbonds_module=module,
        ),
    )


# 12.4. Specialized result inspection and validation
# -----------------------------------------------------------------------------


def is_hydrogen_bond_analysis_result(
    value: Any,
    *,
    hbonds_module: Optional[ModuleType] = None,
) -> bool:
    """Return whether a value is a native or structurally compatible result."""

    if value is None:
        return False
    if hbonds_module is not None:
        result_class = getattr(hbonds_module, HBONDS_RESULT_CLASS_NAME, None)
        if isinstance(result_class, type) and isinstance(value, result_class):
            return True
    return all(hasattr(value, name) for name in HBOND_RESULT_REQUIRED_ATTRIBUTES)


def hbond_result_bonds(value: Any) -> Tuple[Any, ...]:
    """Return atom-level hydrogen bonds from a specialized result."""

    bonds = get_object_value(
        value,
        "hydrogen_bonds",
        default=(),
        skip_none=True,
    )
    return tuple(normalize_object_sequence(bonds))


def hbond_result_residue_groups(value: Any) -> Tuple[Any, ...]:
    """Return residue-grouped hydrogen bonds."""

    groups = get_object_value(
        value,
        "residue_hydrogen_bonds",
        default=(),
        skip_none=True,
    )
    return tuple(normalize_object_sequence(groups))


def hbond_result_statistics(value: Any) -> Dict[str, Any]:
    """Return normalized hydrogen-bond statistics."""

    statistics = get_object_value(value, "statistics", default={}, skip_none=True)
    return normalize_statistics_mapping(statistics)


def hbond_result_metadata(value: Any) -> Dict[str, Any]:
    """Return normalized hydrogen-bond metadata."""

    metadata = get_object_value(value, "metadata", default={}, skip_none=True)
    return normalize_metadata_mapping(metadata)


def _hbond_classification_counts(value: Any) -> Dict[str, int]:
    """Return classification counts from properties, records or statistics."""

    statistics = hbond_result_statistics(value)
    candidates = (
        statistics.get("classification_counts"),
        statistics.get("classifications"),
        statistics.get("by_classification"),
    )
    for candidate in candidates:
        if isinstance(candidate, Mapping):
            return {
                str(name): int(count)
                for name, count in candidate.items()
                if isinstance(count, Real) and not isinstance(count, bool)
            }
    counts: Counter[str] = Counter()
    for bond in hbond_result_bonds(value):
        classification = get_object_value(
            bond,
            "classification",
            default="unknown",
            skip_none=True,
        )
        counts[str(classification or "unknown")] += 1
    return dict(counts)


def _hbond_mode_counts(value: Any) -> Dict[str, int]:
    """Return explicit and inferred interaction counts."""

    counts: Counter[str] = Counter()
    for bond in hbond_result_bonds(value):
        mode = get_object_value(bond, "mode", default="unknown", skip_none=True)
        counts[str(mode or "unknown")] += 1
    return dict(counts)


def _hbond_direction_counts(value: Any) -> Dict[str, int]:
    """Return ligand- and receptor-donor counts."""

    counts: Counter[str] = Counter()
    for bond in hbond_result_bonds(value):
        direction = get_object_value(
            bond,
            "direction",
            default="unknown",
            skip_none=True,
        )
        counts[str(direction or "unknown")] += 1
    return dict(counts)


def validate_hydrogen_bond_analysis_result(
    value: Any,
    *,
    hbonds_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate a specialized hydrogen-bond analysis result."""

    errors: List[str] = []
    if not is_hydrogen_bond_analysis_result(value, hbonds_module=hbonds_module):
        errors.append(
            "Value is not a HydrogenBondAnalysisResult-compatible object."
        )
    else:
        bonds = hbond_result_bonds(value)
        groups = hbond_result_residue_groups(value)
        for index, bond in enumerate(bonds):
            donor = get_object_value(bond, "donor", default=None, skip_none=True)
            acceptor = get_object_value(
                bond,
                "acceptor",
                default=None,
                skip_none=True,
            )
            geometry = get_object_value(
                bond,
                "geometry",
                default=None,
                skip_none=True,
            )
            if donor is None:
                errors.append(f"Hydrogen bond {index} does not contain a donor.")
            if acceptor is None:
                errors.append(f"Hydrogen bond {index} does not contain an acceptor.")
            if geometry is None:
                errors.append(f"Hydrogen bond {index} does not contain geometry.")
            if len(errors) >= MAX_HBOND_ADAPTER_ERROR_DETAILS:
                break
        for index, group in enumerate(groups):
            grouped = get_object_value(
                group,
                "hydrogen_bonds",
                default=(),
                skip_none=True,
            )
            if not isinstance(grouped, Iterable):
                errors.append(
                    f"Residue hydrogen-bond group {index} is not iterable."
                )
                break
        ligand_atoms = get_object_value(
            value,
            "ligand_atoms",
            default=(),
            skip_none=True,
        )
        receptor_atoms = get_object_value(
            value,
            "receptor_atoms",
            default=(),
            skip_none=True,
        )
        if ligand_atoms is None:
            errors.append("Hydrogen-bond result ligand_atoms cannot be None.")
        if receptor_atoms is None:
            errors.append("Hydrogen-bond result receptor_atoms cannot be None.")
    result = tuple(errors[:MAX_HBOND_ADAPTER_ERROR_DETAILS])
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Hydrogen-bond analysis result validation failed.",
            stage=STAGE_HBONDS,
            details={"errors": list(result)},
        )
    return result


@dataclass(frozen=True)
class HydrogenBondResultSummary:
    """Compact summary of one hydrogen-bond analysis result."""

    hydrogen_bond_count: int = 0
    residue_count: int = 0
    ligand_atom_count: int = 0
    receptor_atom_count: int = 0
    explicit_count: int = 0
    inferred_count: int = 0
    strong_count: int = 0
    moderate_count: int = 0
    weak_count: int = 0
    unknown_count: int = 0
    ligand_donor_count: int = 0
    receptor_donor_count: int = 0
    minimum_distance: Optional[float] = None
    mean_distance: Optional[float] = None
    classification_counts: Mapping[str, int] = field(default_factory=dict)
    mode_counts: Mapping[str, int] = field(default_factory=dict)
    direction_counts: Mapping[str, int] = field(default_factory=dict)
    pose_identifier: str = "pose"
    dock_model_identifier: str = "dock_model"

    def __post_init__(self) -> None:
        for field_name in (
            "hydrogen_bond_count",
            "residue_count",
            "ligand_atom_count",
            "receptor_atom_count",
            "explicit_count",
            "inferred_count",
            "strong_count",
            "moderate_count",
            "weak_count",
            "unknown_count",
            "ligand_donor_count",
            "receptor_donor_count",
        ):
            object.__setattr__(
                self,
                field_name,
                max(0, int(getattr(self, field_name))),
            )
        for field_name in ("minimum_distance", "mean_distance"):
            value = getattr(self, field_name)
            object.__setattr__(
                self,
                field_name,
                None if value is None else float(value),
            )
        for field_name in (
            "classification_counts",
            "mode_counts",
            "direction_counts",
        ):
            normalized = {
                str(name): max(0, int(count))
                for name, count in dict(getattr(self, field_name)).items()
            }
            object.__setattr__(self, field_name, MappingProxyType(normalized))
        object.__setattr__(
            self,
            "pose_identifier",
            normalize_identifier(self.pose_identifier, default="pose", maximum_length=256),
        )
        object.__setattr__(
            self,
            "dock_model_identifier",
            normalize_identifier(
                self.dock_model_identifier,
                default="dock_model",
                maximum_length=256,
            ),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready summary."""

        return {
            "hydrogen_bond_count": self.hydrogen_bond_count,
            "residue_count": self.residue_count,
            "ligand_atom_count": self.ligand_atom_count,
            "receptor_atom_count": self.receptor_atom_count,
            "explicit_count": self.explicit_count,
            "inferred_count": self.inferred_count,
            "strong_count": self.strong_count,
            "moderate_count": self.moderate_count,
            "weak_count": self.weak_count,
            "unknown_count": self.unknown_count,
            "ligand_donor_count": self.ligand_donor_count,
            "receptor_donor_count": self.receptor_donor_count,
            "minimum_distance": self.minimum_distance,
            "mean_distance": self.mean_distance,
            "classification_counts": dict(self.classification_counts),
            "mode_counts": dict(self.mode_counts),
            "direction_counts": dict(self.direction_counts),
            "pose_identifier": self.pose_identifier,
            "dock_model_identifier": self.dock_model_identifier,
        }


def _hbond_optional_result_number(value: Any) -> Optional[float]:
    """Return a finite optional number from result data."""

    if value is None:
        return None
    try:
        number = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return number if math.isfinite(number) else None


def summarize_hydrogen_bond_analysis_result(
    value: Any,
    *,
    target: Optional[HydrogenBondStageTarget] = None,
) -> HydrogenBondResultSummary:
    """Build a compact summary from a specialized result."""

    validate_hydrogen_bond_analysis_result(value, raise_on_error=True)
    bonds = hbond_result_bonds(value)
    groups = hbond_result_residue_groups(value)
    classifications = _hbond_classification_counts(value)
    modes = _hbond_mode_counts(value)
    directions = _hbond_direction_counts(value)
    ligand_atoms = tuple(
        normalize_object_sequence(
            get_object_value(value, "ligand_atoms", default=(), skip_none=True)
        )
    )
    receptor_atoms = tuple(
        normalize_object_sequence(
            get_object_value(value, "receptor_atoms", default=(), skip_none=True)
        )
    )
    statistics = hbond_result_statistics(value)
    minimum_distance = get_object_value(
        value,
        "minimum_distance",
        default=statistics.get("minimum_distance"),
        skip_none=True,
    )
    mean_distance = get_object_value(
        value,
        "mean_distance",
        default=statistics.get("mean_distance"),
        skip_none=True,
    )
    return HydrogenBondResultSummary(
        hydrogen_bond_count=len(bonds),
        residue_count=len(groups),
        ligand_atom_count=len(ligand_atoms),
        receptor_atom_count=len(receptor_atoms),
        explicit_count=modes.get("explicit", 0),
        inferred_count=modes.get("inferred", 0),
        strong_count=classifications.get("strong", 0),
        moderate_count=classifications.get("moderate", 0),
        weak_count=classifications.get("weak", 0),
        unknown_count=classifications.get("unknown", 0),
        ligand_donor_count=directions.get("ligand_donor", 0),
        receptor_donor_count=directions.get("receptor_donor", 0),
        minimum_distance=_hbond_optional_result_number(minimum_distance),
        mean_distance=_hbond_optional_result_number(mean_distance),
        classification_counts=classifications,
        mode_counts=modes,
        direction_counts=directions,
        pose_identifier=(target.pose_identifier if target else "pose"),
        dock_model_identifier=(
            target.dock_model_identifier if target else "dock_model"
        ),
    )


@dataclass(frozen=True)
class HydrogenBondStageOutput:
    """Integrated output produced by one hydrogen-bond stage execution."""

    analysis: Any
    summary: HydrogenBondResultSummary
    statistics: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    attached: bool = False
    reused: bool = False
    module_version: Optional[str] = None
    result_type: str = HBONDS_RESULT_TYPE

    def __post_init__(self) -> None:
        if not isinstance(self.summary, HydrogenBondResultSummary):
            raise TypeError("summary must be a HydrogenBondResultSummary.")
        object.__setattr__(
            self,
            "statistics",
            MappingProxyType(normalize_statistics_mapping(self.statistics)),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )
        object.__setattr__(self, "attached", bool(self.attached))
        object.__setattr__(self, "reused", bool(self.reused))
        object.__setattr__(
            self,
            "module_version",
            None if self.module_version is None else str(self.module_version),
        )
        object.__setattr__(
            self,
            "result_type",
            normalize_identifier(
                self.result_type,
                default=HBONDS_RESULT_TYPE,
                maximum_length=128,
            ),
        )

    @property
    def hydrogen_bonds(self) -> Tuple[Any, ...]:
        """Return atom-level hydrogen bonds."""

        return hbond_result_bonds(self.analysis)

    @property
    def residue_hydrogen_bonds(self) -> Tuple[Any, ...]:
        """Return residue-grouped hydrogen bonds."""

        return hbond_result_residue_groups(self.analysis)

    @property
    def hydrogen_bond_count(self) -> int:
        """Return the number of detected hydrogen bonds."""

        return self.summary.hydrogen_bond_count

    @property
    def residue_count(self) -> int:
        """Return the number of grouped residues."""

        return self.summary.residue_count

    def to_dict(self, *, include_analysis: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready integrated output."""

        result: Dict[str, Any] = {
            "result_type": self.result_type,
            "summary": self.summary.to_dict(),
            "statistics": to_json_compatible(dict(self.statistics)),
            "metadata": to_json_compatible(dict(self.metadata)),
            "attached": self.attached,
            "reused": self.reused,
            "module_version": self.module_version,
        }
        if include_analysis:
            to_dict_method = getattr(self.analysis, "to_dict", None)
            result["analysis"] = (
                to_json_compatible(to_dict_method())
                if callable(to_dict_method)
                else to_json_compatible(self.analysis)
            )
        return result


def adapt_hydrogen_bond_analysis_result(
    value: Any,
    *,
    target: Optional[HydrogenBondStageTarget] = None,
    attached: bool = False,
    reused: bool = False,
    hbonds_module: Optional[ModuleType] = None,
) -> HydrogenBondStageOutput:
    """Convert a native hydrogen-bond result to integrated stage output."""

    module = _require_hbonds_module(hbonds_module)
    validate_hydrogen_bond_analysis_result(
        value,
        hbonds_module=module,
        raise_on_error=True,
    )
    summary = summarize_hydrogen_bond_analysis_result(value, target=target)
    metadata = hbond_result_metadata(value)
    metadata.setdefault("adapter", HBOND_ADAPTER_SCHEMA_NAME)
    metadata.setdefault("adapter_version", HBOND_ADAPTER_SCHEMA_VERSION)
    return HydrogenBondStageOutput(
        analysis=value,
        summary=summary,
        statistics=hbond_result_statistics(value),
        metadata=metadata,
        attached=attached,
        reused=reused,
        module_version=get_module_version(module),
    )


def validate_hydrogen_bond_stage_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate integrated hydrogen-bond stage output."""

    errors: List[str] = []
    if not isinstance(value, HydrogenBondStageOutput):
        errors.append("Value is not a HydrogenBondStageOutput.")
    else:
        if value.hydrogen_bond_count != len(value.hydrogen_bonds):
            errors.append(
                "Integrated hydrogen-bond count does not match its summary."
            )
        if value.residue_count != len(value.residue_hydrogen_bonds):
            errors.append(
                "Integrated residue count does not match its summary."
            )
        errors.extend(validate_hydrogen_bond_analysis_result(value.analysis))
    result = tuple(errors[:MAX_HBOND_ADAPTER_ERROR_DETAILS])
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Integrated hydrogen-bond stage output validation failed.",
            stage=STAGE_HBONDS,
            details={"errors": list(result)},
        )
    return result


# 12.5. Reuse, execution and context integration
# -----------------------------------------------------------------------------


def get_reusable_hydrogen_bond_analysis(
    target: HydrogenBondStageTarget,
    *,
    hbonds_module: Optional[ModuleType] = None,
) -> Any:
    """Return a valid previously stored result, when available."""

    module = _require_hbonds_module(hbonds_module)
    value = module.get_stored_dockmodel_hydrogen_bond_result(
        target.dock_model,
        pose_key=target.pose_identifier,
        default=None,
    )
    if value is None:
        value = module.get_stored_dockmodel_hydrogen_bond_result(
            target.dock_model,
            default=None,
        )
    if value is None:
        return None
    errors = validate_hydrogen_bond_analysis_result(value, hbonds_module=module)
    return value if not errors else None


def _hbond_execution_metadata(
    context: Optional[AnalysisContext],
    target: HydrogenBondStageTarget,
    config: HydrogenBondAdapterConfig,
) -> Dict[str, Any]:
    """Build provenance metadata for the specialized analyzer."""

    metadata = dict(config.metadata)
    metadata.setdefault("adapter", HBOND_ADAPTER_SCHEMA_NAME)
    metadata.setdefault("adapter_version", HBOND_ADAPTER_SCHEMA_VERSION)
    metadata.setdefault("stage", STAGE_HBONDS)
    metadata.setdefault("dock_model_identifier", target.dock_model_identifier)
    metadata.setdefault("pose_identifier", target.pose_identifier)
    metadata.setdefault("pose_index", target.pose_index)
    if context is not None:
        metadata.setdefault("run_id", context.run_id)
        metadata.setdefault("request_id", context.request_id)
        metadata.setdefault("analysis_mode", context.mode)
    return metadata


def _store_hbond_output(
    module: ModuleType,
    target: HydrogenBondStageTarget,
    result: Any,
    config: HydrogenBondAdapterConfig,
) -> bool:
    """Store a specialized result using the native DockModel API."""

    if not config.store_result:
        return False
    stored = bool(
        module.store_dockmodel_hydrogen_bond_result(
            target.dock_model,
            result,
            pose_key=target.pose_identifier,
        )
    )
    if config.store_active_result:
        stored = bool(
            module.store_dockmodel_hydrogen_bond_result(
                target.dock_model,
                result,
                pose_key=None,
            )
        ) or stored
    return stored


def run_hydrogen_bond_analysis_adapter(
    target: HydrogenBondStageTarget,
    config: HydrogenBondAdapterConfig,
    *,
    context: Optional[AnalysisContext] = None,
    reuse_result: bool = False,
    hbonds_module: Optional[ModuleType] = None,
) -> HydrogenBondStageOutput:
    """Run or reuse one hydrogen-bond analysis and adapt its result."""

    module = _require_hbonds_module(hbonds_module)
    if reuse_result:
        reusable = get_reusable_hydrogen_bond_analysis(
            target,
            hbonds_module=module,
        )
        if reusable is not None:
            return adapt_hydrogen_bond_analysis_result(
                reusable,
                target=target,
                attached=True,
                reused=True,
                hbonds_module=module,
            )

    metadata = _hbond_execution_metadata(context, target, config)
    effective_config = config.with_metadata(metadata)
    analyzer = getattr(module, HBONDS_ANALYSIS_FUNCTION)
    result = analyzer(
        target.dock_model,
        ligand=target.pose,
        receptor=target.receptor,
        store_result=False,
        residue_side=effective_config.residue_side,
        classification_config=effective_config.classification_config(module),
        include_rejected=effective_config.include_rejected,
        sort_by_strength=effective_config.sort_by_strength,
        calculate_statistics=effective_config.calculate_statistics,
        **effective_config.analysis_kwargs(),
    )
    attached = _store_hbond_output(module, target, result, effective_config)
    return adapt_hydrogen_bond_analysis_result(
        result,
        target=target,
        attached=attached,
        reused=False,
        hbonds_module=module,
    )


def _hbond_stage_failure_should_raise(
    context: Optional[AnalysisContext],
    raise_on_error: Optional[bool],
) -> bool:
    """Resolve whether hydrogen-bond adapter failures should be raised."""

    if raise_on_error is not None:
        return bool(raise_on_error)
    if context is None:
        return True
    return context.config.runtime.failure_policy == FAILURE_POLICY_STRICT


def _record_hbond_stage_context(
    context: AnalysisContext,
    stage_result: AnalysisStageResult,
) -> None:
    """Store hydrogen-bond output and statistics in the runtime context."""

    context.set_stage_data(HBONDS_STAGE_DATA_KEY, stage_result)
    if isinstance(stage_result.value, HydrogenBondStageOutput):
        summary = stage_result.value.summary.to_dict()
        context.statistics[HBONDS_STAGE_STATISTICS_KEY] = summary
        context.metadata[HBONDS_STAGE_METADATA_KEY] = {
            "pose_identifier": stage_result.value.summary.pose_identifier,
            "dock_model_identifier": (
                stage_result.value.summary.dock_model_identifier
            ),
            "module_version": stage_result.value.module_version,
            "reused": stage_result.value.reused,
            "attached": stage_result.value.attached,
        }


def execute_hbonds_stage(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    receptor: Any = None,
    pose: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    hbonds_module: Optional[ModuleType] = None,
    raise_on_error: Optional[bool] = None,
) -> AnalysisStageResult:
    """Execute the registered hydrogen-bond pipeline stage."""

    integrated_config = (
        context.config
        if context is not None and config is None
        else coerce_analysis_config(config)
    )
    stage_config = integrated_config.stage_config(STAGE_HBONDS)
    stage_result = AnalysisStageResult(
        stage=STAGE_HBONDS,
        required=stage_config.required,
    )
    if not stage_config.enabled:
        stage_result.skip("Hydrogen-bond analysis is disabled by configuration.")
        if context is not None:
            _record_hbond_stage_context(context, stage_result)
        return stage_result

    stage_result.start()
    try:
        if context is not None:
            context.raise_if_cancelled(stage=STAGE_HBONDS)
            context.set_current_stage(STAGE_HBONDS)
        module = _require_hbonds_module(hbonds_module)
        target = resolve_hbond_stage_target(
            context,
            dock_model=dock_model,
            receptor=receptor,
            pose=pose,
            pose_index=pose_index,
            hbonds_module=module,
        )
        adapter_config = resolve_hbond_adapter_config(
            integrated_config,
            overrides=overrides,
            metadata={
                "dock_model_identifier": target.dock_model_identifier,
                "pose_identifier": target.pose_identifier,
            },
        )
        stage_result.input_summary = target.to_dict(include_objects=False)
        stage_result.metadata.update(
            {
                "adapter_schema": HBOND_ADAPTER_SCHEMA_NAME,
                "adapter_schema_version": HBOND_ADAPTER_SCHEMA_VERSION,
                "module_name": getattr(module, "__name__", HBONDS_MODULE_NAME),
                "module_version": get_module_version(module),
                "configuration": adapter_config.to_dict(),
            }
        )
        output = run_hydrogen_bond_analysis_adapter(
            target,
            adapter_config,
            context=context,
            reuse_result=stage_config.reuse_result,
            hbonds_module=module,
        )
        if stage_config.validate_result:
            validate_hydrogen_bond_stage_output(output, raise_on_error=True)
        stage_result.cached = output.reused
        stage_result.statistics = dict(output.statistics)
        stage_result.output_summary = output.summary.to_dict()
        stage_result.succeed(
            output,
            message=(
                "Reused a stored hydrogen-bond analysis."
                if output.reused
                else "Hydrogen-bond analysis completed successfully."
            ),
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisStageError(
                "Hydrogen-bond analysis failed.",
                stage=STAGE_HBONDS,
                cause=exc,
                details={"exception_type": type(exc).__name__},
            )
        stage_result.fail(
            wrapped,
            include_traceback=(
                context is not None and context.config.runtime.collect_diagnostics
            ),
        )
        if _hbond_stage_failure_should_raise(context, raise_on_error):
            raise wrapped from exc
    finally:
        if context is not None:
            _record_hbond_stage_context(context, stage_result)
            context.set_current_stage(None)
    return stage_result


# 12.6. Convenience adapters for prepared models
# -----------------------------------------------------------------------------


def analyze_dock_model_hydrogen_bonds(
    dock_model: Any,
    *,
    receptor: Any = None,
    pose: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    hbonds_module: Optional[ModuleType] = None,
) -> HydrogenBondStageOutput:
    """Analyze hydrogen bonds for one prepared DockModel."""

    stage_result = execute_hbonds_stage(
        None,
        dock_model=dock_model,
        receptor=receptor,
        pose=pose,
        pose_index=pose_index,
        config=config,
        overrides=overrides,
        hbonds_module=hbonds_module,
        raise_on_error=True,
    )
    if not isinstance(stage_result.value, HydrogenBondStageOutput):
        raise AnalysisIntegrationError(
            "The hydrogen-bond stage did not produce a HydrogenBondStageOutput.",
            stage=STAGE_HBONDS,
        )
    return stage_result.value


def analyze_prepared_dock_models_hydrogen_bonds(
    dock_models: Iterable[Any],
    *,
    receptor: Any = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    hbonds_module: Optional[ModuleType] = None,
    continue_on_error: bool = False,
) -> Tuple[AnalysisStageResult, ...]:
    """Run the adapter sequentially for prepared DockModel objects."""

    models = tuple(normalize_object_sequence(dock_models))
    if not models:
        return ()
    results: List[AnalysisStageResult] = []
    for index, model in enumerate(models):
        try:
            result = execute_hbonds_stage(
                None,
                dock_model=model,
                receptor=receptor,
                pose_index=index,
                config=config,
                overrides=overrides,
                hbonds_module=hbonds_module,
                raise_on_error=not continue_on_error,
            )
        except Exception as exc:
            if not continue_on_error:
                raise
            result = AnalysisStageResult(stage=STAGE_HBONDS)
            result.start().fail(exc)
        results.append(result)
    return tuple(results)


def analyze_all_dock_model_pose_hydrogen_bonds(
    dock_model: Any,
    *,
    receptor: Any = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    hbonds_module: Optional[ModuleType] = None,
    continue_on_error: bool = True,
) -> Tuple[AnalysisStageResult, ...]:
    """Analyze every pose exposed by one DockModel through the adapter."""

    module = _require_hbonds_module(hbonds_module)
    try:
        poses = tuple(module.get_dockmodel_poses(dock_model))
    except Exception as exc:
        raise AnalysisInputError(
            "Could not enumerate DockModel poses for hydrogen-bond analysis.",
            stage=STAGE_HBONDS,
            cause=exc,
        ) from exc
    results: List[AnalysisStageResult] = []
    for index, (_, pose) in enumerate(poses):
        try:
            result = execute_hbonds_stage(
                None,
                dock_model=dock_model,
                receptor=receptor,
                pose=pose,
                pose_index=index,
                config=config,
                overrides=overrides,
                hbonds_module=module,
                raise_on_error=not continue_on_error,
            )
        except Exception as exc:
            if not continue_on_error:
                raise
            result = AnalysisStageResult(stage=STAGE_HBONDS)
            result.start().fail(exc)
        results.append(result)
    return tuple(results)


# 12.7. Stage registry integration
# -----------------------------------------------------------------------------


def hbond_stage_result_adapter(value: Any, **kwargs: Any) -> HydrogenBondStageOutput:
    """Registry-compatible adapter for specialized hydrogen-bond results."""

    return adapt_hydrogen_bond_analysis_result(value, **kwargs)


def hbond_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible validator for hydrogen-bond stage values."""

    if isinstance(value, AnalysisStageResult):
        if value.value is None:
            return () if value.status == StageStatus.SKIPPED else (
                "Hydrogen-bond stage result does not contain a value.",
            )
        value = value.value
    if isinstance(value, HydrogenBondStageOutput):
        return validate_hydrogen_bond_stage_output(value)
    return validate_hydrogen_bond_analysis_result(value)


def register_hbond_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the hydrogen-bond executor, adapter and validator."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_HBONDS)
    updated_metadata = dict(definition.metadata)
    updated_metadata.update(
        {
            "adapter_schema": HBOND_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": HBOND_ADAPTER_SCHEMA_VERSION,
            "analysis_function": HBONDS_ANALYSIS_FUNCTION,
            "multipose_function": HBONDS_MULTIPOSE_FUNCTION,
            "result_type": HBONDS_RESULT_TYPE,
        }
    )
    updated = replace(
        definition,
        executor=execute_hbonds_stage,
        result_adapter=hbond_stage_result_adapter,
        validator=hbond_stage_validator,
        metadata=updated_metadata,
    )
    target_registry.replace(updated)
    return updated


def hbond_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the hydrogen-bond stage adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_HBONDS)
    return bool(
        definition is not None
        and definition.executor is execute_hbonds_stage
        and definition.result_adapter is hbond_stage_result_adapter
        and definition.validator is hbond_stage_validator
    )


# 12.8. Summaries and convention validation
# -----------------------------------------------------------------------------


def summarize_hbond_stage_result(value: Any) -> Dict[str, Any]:
    """Return a compact summary for stage or adapter output."""

    if isinstance(value, AnalysisStageResult):
        result: Dict[str, Any] = {
            "stage": value.stage,
            "status": value.status.value,
            "cached": value.cached,
            "duration_seconds": value.duration_seconds,
        }
        if isinstance(value.value, HydrogenBondStageOutput):
            result.update(value.value.summary.to_dict())
        return result
    if isinstance(value, HydrogenBondStageOutput):
        result = value.summary.to_dict()
        result.update(
            {
                "attached": value.attached,
                "reused": value.reused,
                "module_version": value.module_version,
            }
        )
        return result
    if is_hydrogen_bond_analysis_result(value):
        return summarize_hydrogen_bond_analysis_result(value).to_dict()
    raise TypeError(
        "value must be an AnalysisStageResult, HydrogenBondStageOutput or "
        "hydrogen-bond result."
    )


def validate_hbond_adapter_conventions() -> Dict[str, Any]:
    """Validate hydrogen-bond adapter constants, data and registration."""

    failures: List[str] = []
    if canonicalize_hbond_mode("hydrogens") != "explicit":
        failures.append("Explicit mode alias resolution failed.")
    if canonicalize_hbond_mode("heavy_atoms") != "inferred":
        failures.append("Inferred mode alias resolution failed.")
    if canonicalize_hbond_residue_side("protein") != "receptor":
        failures.append("Receptor residue-side alias resolution failed.")
    if canonicalize_hbond_vector_method("nearest") != "nearest_neighbor":
        failures.append("Vector-method alias resolution failed.")

    config = HydrogenBondAdapterConfig.from_mapping(
        {
            "hbond_mode": "explicit",
            "da_cutoff": 3.6,
            "ha_cutoff": 2.6,
            "minimum_angle": 115.0,
            "max_hbonds": 25,
            "side": "protein",
            "classification": {"strong_score_threshold": 0.8},
            "store": True,
        }
    )
    if config.mode != "explicit" or config.donor_acceptor_cutoff != 3.6:
        failures.append("Hydrogen-bond adapter aliases failed.")
    if config.maximum_hydrogen_bonds != 25:
        failures.append("Maximum hydrogen-bond count was not preserved.")
    if config.residue_side != "receptor":
        failures.append("Hydrogen-bond residue side was not canonicalized.")

    class FakeGeometry:
        donor_acceptor_distance = 3.0

    class FakeBond:
        donor = object()
        acceptor = object()
        geometry = FakeGeometry()
        mode = "explicit"
        direction = "ligand_donor"
        classification = "strong"

    class FakeResult:
        def __init__(self) -> None:
            self.hydrogen_bonds = (FakeBond(),)
            self.residue_hydrogen_bonds = (
                SimpleNamespace(hydrogen_bonds=(self.hydrogen_bonds[0],)),
            )
            self.ligand_atoms = (object(),)
            self.receptor_atoms = (object(), object())
            self.statistics = {}
            self.metadata = {}
            self.minimum_distance = 3.0
            self.mean_distance = 3.0

        def to_dict(self) -> Dict[str, Any]:
            return {"hydrogen_bond_count": 1}

    class FakeClassificationConfig:
        def __init__(self, **kwargs: Any) -> None:
            self.values = kwargs

    class FakeHbondModule(ModuleType):
        pass

    fake_module = FakeHbondModule("hbonds")
    fake_module.__version__ = "test"
    fake_module.HydrogenBondAnalysisResult = FakeResult
    fake_module.DockModelHydrogenBondResults = SimpleNamespace
    fake_module.HydrogenBondClassificationConfig = FakeClassificationConfig
    fake_module.DEFAULT_HBOND_CLASSIFICATION_CONFIG = FakeClassificationConfig()
    fake_module.get_dockmodel_receptor = lambda model: getattr(model, "receptor", None)
    fake_module.get_dockmodel_active_ligand = lambda model: getattr(model, "ligand", None)
    fake_module.get_dockmodel_pose = lambda model, pose: (
        f"pose_{int(pose) + 1}" if isinstance(pose, int) else "pose_1",
        getattr(model, "ligand", pose),
    )
    fake_module.get_dockmodel_poses = lambda model: (("pose_1", model.ligand),)

    storage: Dict[str, Any] = {}

    def fake_store(model: Any, result: Any, *, pose_key: Optional[str] = None) -> bool:
        storage["active" if pose_key is None else str(pose_key)] = result
        return True

    def fake_get(
        model: Any,
        *,
        pose_key: Optional[str] = None,
        default: Any = None,
    ) -> Any:
        return storage.get("active" if pose_key is None else str(pose_key), default)

    def fake_analyze(model: Any, **kwargs: Any) -> Any:
        return FakeResult()

    fake_module.store_dockmodel_hydrogen_bond_result = fake_store
    fake_module.get_stored_dockmodel_hydrogen_bond_result = fake_get
    fake_module.analyze_dockmodel_hydrogen_bonds = fake_analyze
    fake_module.analyze_all_dockmodel_pose_hydrogen_bonds = lambda *args, **kwargs: (
        SimpleNamespace(results={}, pose_order=(), failed_poses={}, metadata={})
    )

    receptor = SimpleNamespace(name="receptor")
    pose = SimpleNamespace(name="pose")
    dock_model = SimpleNamespace(
        name="dock_1",
        receptor=receptor,
        ligand=pose,
        poses=(pose,),
    )
    target = resolve_hbond_stage_target(
        None,
        dock_model=dock_model,
        pose_index=0,
        hbonds_module=fake_module,
    )
    output = run_hydrogen_bond_analysis_adapter(
        target,
        config,
        hbonds_module=fake_module,
    )
    if output.hydrogen_bond_count != 1 or output.residue_count != 1:
        failures.append("Hydrogen-bond result adaptation produced wrong counts.")
    if validate_hydrogen_bond_stage_output(output):
        failures.append("A valid hydrogen-bond output did not validate.")
    if not output.attached:
        failures.append("Hydrogen-bond result was not stored.")
    if json.loads(json.dumps(output.to_dict()))["summary"]["strong_count"] != 1:
        failures.append("Hydrogen-bond output JSON conversion failed.")

    integrated = AnalysisConfig(
        stage_configs={
            STAGE_HBONDS: AnalysisStageConfig(
                enabled=True,
                attach_results=True,
                validate_result=True,
                reuse_result=False,
                parameters={"mode": "explicit", "store_result": True},
            )
        },
        runtime=AnalysisRuntimeConfig(
            failure_policy=FAILURE_POLICY_STRICT,
            attach_results=True,
            reuse_results=True,
        ),
    )
    request = AnalysisRequest(
        dock_models=(dock_model,),
        receptor=receptor,
        poses=(pose,),
        config=integrated,
    )
    context = AnalysisContext(
        request=request,
        dock_models=[dock_model],
        receptor=receptor,
        poses=[pose],
        current_pose_index=0,
    )
    storage.clear()
    stage_result = execute_hbonds_stage(
        context,
        hbonds_module=fake_module,
        raise_on_error=True,
    )
    if not stage_result.succeeded:
        failures.append("Hydrogen-bond stage executor did not succeed.")
    if not isinstance(stage_result.value, HydrogenBondStageOutput):
        failures.append("Hydrogen-bond executor returned an unexpected value.")
    if context.get_stage_data(STAGE_HBONDS) is not stage_result:
        failures.append("Hydrogen-bond result was not stored in the context.")
    if STAGE_HBONDS not in context.statistics:
        failures.append("Hydrogen-bond statistics were not stored in the context.")

    registry = create_default_stage_registry()
    register_hbond_stage_adapter(registry=registry)
    if not hbond_stage_adapter_registered(registry=registry):
        failures.append("Hydrogen-bond adapter was not registered correctly.")
    definition = registry.require(STAGE_HBONDS)
    if definition.executor is not execute_hbonds_stage:
        failures.append("Hydrogen-bond executor registration failed.")

    real_module = _require_hbonds_module()
    missing_interface = tuple(
        name for name in HBONDS_REQUIRED_SYMBOLS if not hasattr(real_module, name)
    )
    if missing_interface:
        failures.append(
            "The repository hbonds module is missing required symbols: "
            + ", ".join(missing_interface)
        )
    try:
        native_config = config.classification_config(real_module)
        native_class = getattr(real_module, HBONDS_CLASSIFICATION_CONFIG_CLASS_NAME)
        if not isinstance(native_config, native_class):
            failures.append("Native classification configuration creation failed.")
    except Exception as exc:
        failures.append(
            "Native classification configuration could not be created: "
            f"{type(exc).__name__}."
        )

    if failures:
        raise RuntimeError(
            "Hydrogen-bond adapter convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": HBOND_ADAPTER_SCHEMA_NAME,
        "schema_version": HBOND_ADAPTER_SCHEMA_VERSION,
        "required_symbols": len(HBONDS_REQUIRED_SYMBOLS),
        "supported_parameters": len(HBOND_ADAPTER_FIELDS),
        "validated_cases": 23,
    }


