PI_REQUIRED_SYMBOLS: Final[Tuple[str, ...]] = (
    PI_DIRECT_ANALYSIS_FUNCTION,
    PI_DOCK_MODEL_ANALYSIS_FUNCTION,
    PI_MULTIPOSE_FUNCTION,
    PI_ATTACHMENT_FUNCTION,
    PI_SUMMARY_FUNCTION,
    PI_DEFAULT_CONFIG_FUNCTION,
    PI_DEFAULT_INTEGRATION_CONFIG_FUNCTION,
    PI_RESULT_CLASS_NAME,
    PI_MULTIPOSE_RESULT_CLASS_NAME,
    PI_INTEGRATION_CONFIG_CLASS_NAME,
    PI_INTEGRATION_RESULT_CLASS_NAME,
    PI_MULTIPOSE_INTEGRATION_RESULT_CLASS_NAME,
    "resolve_dock_model_structure",
    "resolve_dock_model_pose_id",
    "get_dock_model_pi_interactions",
)
PI_RESULT_REQUIRED_ATTRIBUTES: Final[Tuple[str, ...]] = (
    "analysis_id",
    "analysis_mode",
    "recognized_features",
    "detected_interactions",
    "interactions",
    "success",
    "completed_stage",
    "warnings",
    "errors",
    "metadata",
)
MAX_PI_ADAPTER_MAPPING_ITEMS: Final[int] = 4096
MAX_PI_ADAPTER_IDENTIFIER_LENGTH: Final[int] = 512
MAX_PI_ADAPTER_INTERACTIONS: Final[int] = 5_000_000


# 14.2. Pi adapter configuration
# -----------------------------------------------------------------------------


def _normalize_pi_adapter_parameter_name(value: Any) -> str:
    """Normalize one pi-adapter parameter name."""

    token = normalize_identifier(value, maximum_length=128)
    return PI_PARAMETER_ALIASES.get(token, token)


def canonicalize_pi_attachment_mode(value: Any) -> str:
    """Return a canonical pi-result attachment mode."""

    token = normalize_identifier(value, default="replace", maximum_length=64)
    canonical = PI_ATTACHMENT_MODE_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported pi attachment mode {value!r}. Supported values: "
            f"{', '.join(sorted(PI_ATTACHMENT_MODES))}."
        )
    return canonical


def canonicalize_pi_score_mode(value: Any) -> str:
    """Return a canonical native pi-score mode."""

    token = normalize_identifier(
        value,
        default=PI_DEFAULT_SCORE_MODE,
        maximum_length=64,
    )
    if token not in PI_SCORE_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported pi score mode {value!r}. Supported values: "
            f"{', '.join(sorted(PI_SCORE_MODES))}."
        )
    return token


def canonicalize_pi_score_update_mode(value: Any) -> str:
    """Return a canonical DockModel score-update mode."""

    token = normalize_identifier(
        value,
        default=PI_DEFAULT_SCORE_UPDATE_MODE,
        maximum_length=64,
    )
    if token not in PI_SCORE_UPDATE_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported pi score-update mode {value!r}. Supported values: "
            f"{', '.join(sorted(PI_SCORE_UPDATE_MODES))}."
        )
    return token


def _pi_adapter_sequence(value: Any) -> Tuple[Any, ...]:
    """Normalize one optional pi-adapter collection."""

    if value is None:
        return ()
    return tuple(normalize_object_sequence(value))


def _pi_adapter_mapping(value: Any, *, field_name: str) -> Mapping[str, Any]:
    """Normalize and freeze one adapter mapping."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        to_dict_method = getattr(value, "to_dict", None)
        if callable(to_dict_method):
            value = to_dict_method()
        elif is_dataclass(value) and not isinstance(value, type):
            value = {
                item.name: getattr(value, item.name)
                for item in fields(value)
            }
    if not isinstance(value, Mapping):
        raise AnalysisConfigurationError(f"{field_name} must be a mapping.")
    if len(value) > MAX_PI_ADAPTER_MAPPING_ITEMS:
        raise AnalysisConfigurationError(
            f"{field_name} exceeds {MAX_PI_ADAPTER_MAPPING_ITEMS} entries."
        )
    return MappingProxyType(copy.deepcopy(dict(value)))


def _pi_config_object_mapping(value: Any) -> Dict[str, Any]:
    """Convert one integrated module configuration to a mapping."""

    if value is None:
        return {}
    if isinstance(value, PiAdapterConfig):
        return value.to_dict(include_feature_objects=True)
    if isinstance(value, Mapping):
        return dict(value)
    to_dict_method = getattr(value, "to_dict", None)
    if callable(to_dict_method):
        converted = to_dict_method()
        if isinstance(converted, Mapping):
            return dict(converted)
    if is_dataclass(value) and not isinstance(value, type):
        return {item.name: getattr(value, item.name) for item in fields(value)}
    raise AnalysisConfigurationError(
        "The pi module configuration must be a mapping, dataclass or "
        "PiAdapterConfig."
    )


def _pi_runtime_attachment_mode(config: AnalysisConfig) -> str:
    """Map the integrated attachment policy to the pi adapter policy."""

    policy = config.runtime.attachment_policy
    if policy == ATTACHMENT_POLICY_REPLACE:
        return "replace"
    if policy == ATTACHMENT_POLICY_PRESERVE:
        return "preserve"
    if policy == ATTACHMENT_POLICY_MERGE:
        return "append"
    return "replace"


@dataclass(frozen=True)
class PiAdapterConfig:
    """Effective configuration for one pi-interaction stage."""

    enabled: bool = True
    enable_pi_pi: bool = True
    enable_cation_pi: bool = True
    enable_anion_pi: bool = True
    enable_amide_pi: bool = True
    normalize_input: bool = True
    recognize_aromatic_systems: bool = True
    recognize_charged_groups: bool = True
    recognize_amide_groups: bool = True
    calculate_geometries: bool = True
    run_scoring: bool = True
    run_grouping: bool = True
    run_statistics: bool = True
    strict: bool = False
    preserve_intermediate_results: bool = True
    preserve_empty_categories: bool = True
    pi_pi_config: Any = None
    cation_pi_config: Any = None
    anion_pi_config: Any = None
    amide_pi_config: Any = None
    scoring_config: Any = None
    grouping_config: Any = None
    statistics_config: Any = None
    normalizer: Optional[Callable[..., Any]] = None
    aromatic_recognizer: Optional[Callable[..., Iterable[Any]]] = None
    positive_group_recognizer: Optional[Callable[..., Iterable[Any]]] = None
    negative_group_recognizer: Optional[Callable[..., Iterable[Any]]] = None
    amide_group_recognizer: Optional[Callable[..., Iterable[Any]]] = None
    aromatic_systems: Tuple[Any, ...] = ()
    positive_groups: Tuple[Any, ...] = ()
    negative_groups: Tuple[Any, ...] = ()
    amide_groups: Tuple[Any, ...] = ()
    attach: bool = True
    attachment_mode: str = "replace"
    preferred_pi_attribute: str = PI_DEFAULT_PREFERRED_ATTRIBUTE
    fallback_pi_attributes: Tuple[str, ...] = ("pi_interactions",)
    create_missing_pi_attribute: bool = True
    preserve_previous_results: bool = True
    append_new_interactions: bool = False
    deduplicate_when_appending: bool = True
    store_analysis_result: bool = True
    analysis_result_attribute: str = PI_DEFAULT_ANALYSIS_RESULT_ATTRIBUTE
    store_grouping_result: bool = True
    grouping_result_attribute: str = PI_DEFAULT_GROUPING_RESULT_ATTRIBUTE
    store_statistics_report: bool = True
    statistics_attribute: str = PI_DEFAULT_STATISTICS_ATTRIBUTE
    update_global_statistics: bool = True
    update_global_score: bool = True
    score_mode: str = PI_DEFAULT_SCORE_MODE
    score_update_mode: str = PI_DEFAULT_SCORE_UPDATE_MODE
    preserve_previous_score: bool = True
    preserve_previous_statistics: bool = True
    store_serializable_summary: bool = True
    serializable_summary_attribute: str = PI_DEFAULT_SUMMARY_ATTRIBUTE
    pose_id_attribute_candidates: Tuple[str, ...] = (
        "pose_id",
        "model_id",
        "state_id",
        "pose",
        "index",
        "id",
    )
    analysis_id: Optional[str] = None
    pose_id: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        boolean_fields = (
            "enabled",
            "enable_pi_pi",
            "enable_cation_pi",
            "enable_anion_pi",
            "enable_amide_pi",
            "normalize_input",
            "recognize_aromatic_systems",
            "recognize_charged_groups",
            "recognize_amide_groups",
            "calculate_geometries",
            "run_scoring",
            "run_grouping",
            "run_statistics",
            "strict",
            "preserve_intermediate_results",
            "preserve_empty_categories",
            "attach",
            "create_missing_pi_attribute",
            "preserve_previous_results",
            "append_new_interactions",
            "deduplicate_when_appending",
            "store_analysis_result",
            "store_grouping_result",
            "store_statistics_report",
            "update_global_statistics",
            "update_global_score",
            "preserve_previous_score",
            "preserve_previous_statistics",
            "store_serializable_summary",
        )
        for name in boolean_fields:
            object.__setattr__(self, name, bool(getattr(self, name)))
        object.__setattr__(
            self,
            "attachment_mode",
            canonicalize_pi_attachment_mode(self.attachment_mode),
        )
        object.__setattr__(self, "score_mode", canonicalize_pi_score_mode(self.score_mode))
        object.__setattr__(
            self,
            "score_update_mode",
            canonicalize_pi_score_update_mode(self.score_update_mode),
        )
        for name in (
            "preferred_pi_attribute",
            "analysis_result_attribute",
            "grouping_result_attribute",
            "statistics_attribute",
            "serializable_summary_attribute",
        ):
            normalized = normalize_text(
                getattr(self, name),
                default="",
                maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
            ).strip()
            if not normalized:
                raise AnalysisConfigurationError(f"{name} cannot be empty.")
            object.__setattr__(self, name, normalized)
        object.__setattr__(
            self,
            "fallback_pi_attributes",
            tuple(
                str(item).strip()
                for item in self.fallback_pi_attributes
                if str(item).strip()
            ),
        )
        object.__setattr__(
            self,
            "pose_id_attribute_candidates",
            tuple(
                str(item).strip()
                for item in self.pose_id_attribute_candidates
                if str(item).strip()
            ),
        )
        for name in (
            "normalizer",
            "aromatic_recognizer",
            "positive_group_recognizer",
            "negative_group_recognizer",
            "amide_group_recognizer",
        ):
            callback = getattr(self, name)
            if callback is not None and not callable(callback):
                raise AnalysisConfigurationError(
                    f"{name} must be callable or None."
                )
        for name in (
            "aromatic_systems",
            "positive_groups",
            "negative_groups",
            "amide_groups",
        ):
            object.__setattr__(self, name, _pi_adapter_sequence(getattr(self, name)))
        object.__setattr__(self, "metadata", _pi_adapter_mapping(self.metadata, field_name="metadata"))
        if self.analysis_id is not None:
            object.__setattr__(
                self,
                "analysis_id",
                normalize_text(
                    self.analysis_id,
                    maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
                ),
            )
        if self.pose_id is not None:
            object.__setattr__(
                self,
                "pose_id",
                normalize_text(
                    self.pose_id,
                    maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
                ),
            )
        if not self.enabled_subtypes and self.enabled:
            object.__setattr__(self, "enabled", False)
        if self.attachment_mode == "append":
            object.__setattr__(self, "preserve_previous_results", True)
            object.__setattr__(self, "append_new_interactions", True)
        elif self.attachment_mode == "preserve":
            object.__setattr__(self, "preserve_previous_results", True)
            object.__setattr__(self, "append_new_interactions", False)
        else:
            object.__setattr__(self, "preserve_previous_results", False)
            object.__setattr__(self, "append_new_interactions", False)

    @property
    def enabled_subtypes(self) -> Tuple[str, ...]:
        """Return enabled pi-interaction subtypes in canonical order."""

        return tuple(
            subtype
            for subtype in PI_INTERACTION_SUBTYPES
            if bool(getattr(self, PI_NATIVE_SUBTYPE_FIELDS[subtype]))
        )

    @classmethod
    def from_mapping(
        cls,
        values: Optional[Mapping[str, Any]] = None,
        *,
        strict: bool = True,
    ) -> "PiAdapterConfig":
        """Create an adapter configuration from a mapping."""

        if values is None:
            return cls()
        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Pi adapter configuration must be a mapping."
            )
        normalized: Dict[str, Any] = {}
        for raw_name, value in values.items():
            name = _normalize_pi_adapter_parameter_name(raw_name)
            if name not in PI_ADAPTER_FIELDS:
                if strict:
                    raise AnalysisConfigurationError(
                        f"Unknown pi adapter parameter {raw_name!r}."
                    )
                continue
            if name in normalized:
                raise AnalysisConfigurationError(
                    f"Duplicate pi adapter parameter after alias resolution: {name!r}."
                )
            normalized[name] = value
        return cls(**normalized)

    def with_metadata(self, values: Mapping[str, Any]) -> "PiAdapterConfig":
        """Return a copy with merged provenance metadata."""

        merged = dict(self.metadata)
        merged.update(dict(values))
        return replace(self, metadata=merged)

    def native_analysis_config(self, module: ModuleType) -> Any:
        """Build the native ``PiAnalysisConfig`` object."""

        config_class = getattr(module, "PiAnalysisConfig")
        defaults = getattr(module, PI_DEFAULT_CONFIG_FUNCTION)()
        kwargs = {
            "enabled": self.enabled,
            "enable_pi_pi": self.enable_pi_pi,
            "enable_cation_pi": self.enable_cation_pi,
            "enable_anion_pi": self.enable_anion_pi,
            "enable_amide_pi": self.enable_amide_pi,
            "normalize_input": self.normalize_input,
            "recognize_aromatic_systems": self.recognize_aromatic_systems,
            "recognize_charged_groups": self.recognize_charged_groups,
            "recognize_amide_groups": self.recognize_amide_groups,
            "calculate_geometries": self.calculate_geometries,
            "run_scoring": self.run_scoring,
            "run_grouping": self.run_grouping,
            "run_statistics": self.run_statistics,
            "strict": self.strict,
            "preserve_intermediate_results": self.preserve_intermediate_results,
            "preserve_empty_categories": self.preserve_empty_categories,
            "pi_pi_config": self.pi_pi_config or getattr(defaults, "pi_pi_config", None),
            "cation_pi_config": self.cation_pi_config or getattr(defaults, "cation_pi_config", None),
            "anion_pi_config": self.anion_pi_config or getattr(defaults, "anion_pi_config", None),
            "amide_pi_config": self.amide_pi_config or getattr(defaults, "amide_pi_config", None),
            "scoring_config": self.scoring_config or getattr(defaults, "scoring_config", None),
            "grouping_config": self.grouping_config or getattr(defaults, "grouping_config", None),
            "statistics_config": self.statistics_config or getattr(defaults, "statistics_config", None),
            "normalizer": self.normalizer,
            "aromatic_recognizer": self.aromatic_recognizer,
            "positive_group_recognizer": self.positive_group_recognizer,
            "negative_group_recognizer": self.negative_group_recognizer,
            "amide_group_recognizer": self.amide_group_recognizer,
            "analysis_id": self.analysis_id,
            "pose_id": self.pose_id,
        }
        return config_class(**kwargs)

    def native_integration_config(self, module: ModuleType) -> Any:
        """Build the native ``DockModelPiIntegrationConfig`` object."""

        config_class = getattr(module, PI_INTEGRATION_CONFIG_CLASS_NAME)
        return config_class(
            enabled=self.attach,
            preferred_pi_attribute=self.preferred_pi_attribute,
            fallback_pi_attributes=self.fallback_pi_attributes,
            create_missing_pi_attribute=self.create_missing_pi_attribute,
            preserve_previous_results=self.preserve_previous_results,
            append_new_interactions=self.append_new_interactions,
            deduplicate_when_appending=self.deduplicate_when_appending,
            store_analysis_result=self.store_analysis_result,
            analysis_result_attribute=self.analysis_result_attribute,
            store_grouping_result=self.store_grouping_result,
            grouping_result_attribute=self.grouping_result_attribute,
            store_statistics_report=self.store_statistics_report,
            statistics_attribute=self.statistics_attribute,
            update_global_statistics=self.update_global_statistics,
            update_global_score=self.update_global_score,
            score_mode=self.score_mode,
            score_update_mode=self.score_update_mode,
            preserve_previous_score=self.preserve_previous_score,
            preserve_previous_statistics=self.preserve_previous_statistics,
            store_serializable_summary=self.store_serializable_summary,
            serializable_summary_attribute=self.serializable_summary_attribute,
            pose_id_attribute_candidates=self.pose_id_attribute_candidates,
            strict=self.strict,
        )

    def feature_kwargs(self) -> Dict[str, Any]:
        """Return optional pre-recognized feature collections."""

        return {
            "aromatic_systems": self.aromatic_systems or None,
            "positive_groups": self.positive_groups or None,
            "negative_groups": self.negative_groups or None,
            "amide_groups": self.amide_groups or None,
        }

    def to_dict(self, *, include_feature_objects: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready configuration representation."""

        result: Dict[str, Any] = {
            "enabled": self.enabled,
            "enabled_subtypes": list(self.enabled_subtypes),
            "enable_pi_pi": self.enable_pi_pi,
            "enable_cation_pi": self.enable_cation_pi,
            "enable_anion_pi": self.enable_anion_pi,
            "enable_amide_pi": self.enable_amide_pi,
            "normalize_input": self.normalize_input,
            "recognize_aromatic_systems": self.recognize_aromatic_systems,
            "recognize_charged_groups": self.recognize_charged_groups,
            "recognize_amide_groups": self.recognize_amide_groups,
            "calculate_geometries": self.calculate_geometries,
            "run_scoring": self.run_scoring,
            "run_grouping": self.run_grouping,
            "run_statistics": self.run_statistics,
            "strict": self.strict,
            "preserve_intermediate_results": self.preserve_intermediate_results,
            "preserve_empty_categories": self.preserve_empty_categories,
            "attach": self.attach,
            "attachment_mode": self.attachment_mode,
            "preferred_pi_attribute": self.preferred_pi_attribute,
            "fallback_pi_attributes": list(self.fallback_pi_attributes),
            "create_missing_pi_attribute": self.create_missing_pi_attribute,
            "preserve_previous_results": self.preserve_previous_results,
            "append_new_interactions": self.append_new_interactions,
            "deduplicate_when_appending": self.deduplicate_when_appending,
            "store_analysis_result": self.store_analysis_result,
            "analysis_result_attribute": self.analysis_result_attribute,
            "store_grouping_result": self.store_grouping_result,
            "grouping_result_attribute": self.grouping_result_attribute,
            "store_statistics_report": self.store_statistics_report,
            "statistics_attribute": self.statistics_attribute,
            "update_global_statistics": self.update_global_statistics,
            "update_global_score": self.update_global_score,
            "score_mode": self.score_mode,
            "score_update_mode": self.score_update_mode,
            "preserve_previous_score": self.preserve_previous_score,
            "preserve_previous_statistics": self.preserve_previous_statistics,
            "store_serializable_summary": self.store_serializable_summary,
            "serializable_summary_attribute": self.serializable_summary_attribute,
            "pose_id_attribute_candidates": list(self.pose_id_attribute_candidates),
            "analysis_id": self.analysis_id,
            "pose_id": self.pose_id,
            "metadata": to_json_compatible(dict(self.metadata)),
        }
        if include_feature_objects:
            result.update(
                {
                    "aromatic_systems": self.aromatic_systems,
                    "positive_groups": self.positive_groups,
                    "negative_groups": self.negative_groups,
                    "amide_groups": self.amide_groups,
                    "pi_pi_config": self.pi_pi_config,
                    "cation_pi_config": self.cation_pi_config,
                    "anion_pi_config": self.anion_pi_config,
                    "amide_pi_config": self.amide_pi_config,
                    "scoring_config": self.scoring_config,
                    "grouping_config": self.grouping_config,
                    "statistics_config": self.statistics_config,
                    "normalizer": self.normalizer,
                    "aromatic_recognizer": self.aromatic_recognizer,
                    "positive_group_recognizer": self.positive_group_recognizer,
                    "negative_group_recognizer": self.negative_group_recognizer,
                    "amide_group_recognizer": self.amide_group_recognizer,
                }
            )
        else:
            result["feature_counts"] = {
                "aromatic_systems": len(self.aromatic_systems),
                "positive_groups": len(self.positive_groups),
                "negative_groups": len(self.negative_groups),
                "amide_groups": len(self.amide_groups),
            }
        return result


def resolve_pi_adapter_config(
    config: Optional[AnalysisConfigLike] = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    strict: bool = True,
) -> PiAdapterConfig:
    """Resolve effective pi-analysis and DockModel-integration settings."""

    integrated = coerce_analysis_config(config)
    stage_config = integrated.stage_config(STAGE_PI)
    module_config = integrated.module_config(PI_MODULE_NAME, {})
    merged = _pi_config_object_mapping(module_config)
    merged.update(dict(stage_config.parameters))
    if overrides:
        merged.update(dict(overrides))

    selection = integrated.interactions
    selected_subtypes = frozenset(selection.pi_subtypes)
    merged.setdefault("enabled", selection.pi)
    for subtype, field_name in PI_NATIVE_SUBTYPE_FIELDS.items():
        merged.setdefault(field_name, subtype in selected_subtypes)

    attach_enabled = bool(
        integrated.runtime.attach_results
        and stage_config.attach_results
        and integrated.runtime.attachment_policy != ATTACHMENT_POLICY_NONE
    )
    merged.setdefault("attach", attach_enabled)
    merged.setdefault("attachment_mode", _pi_runtime_attachment_mode(integrated))
    merged.setdefault("strict", integrated.runtime.failure_policy == FAILURE_POLICY_STRICT)
    resolved = PiAdapterConfig.from_mapping(merged, strict=strict)
    if metadata:
        resolved = resolved.with_metadata(metadata)
    return resolved


