@dataclass(frozen=True)
class PiStageTarget:
    """Resolved molecular input for one pi-analysis stage."""

    dock_model: Any
    structure: Any
    receptor: Any
    ligand: Any
    pose_index: Optional[int]
    dock_model_identifier: str
    pose_identifier: str

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe target representation."""

        result: Dict[str, Any] = {
            "dock_model_identifier": self.dock_model_identifier,
            "pose_identifier": self.pose_identifier,
            "pose_index": self.pose_index,
        }
        if include_objects:
            result.update(
                {
                    "dock_model": self.dock_model,
                    "structure": self.structure,
                    "receptor": self.receptor,
                    "ligand": self.ligand,
                }
            )
        else:
            result.update(
                {
                    "dock_model": describe_object(self.dock_model).to_dict(),
                    "structure": describe_object(self.structure).to_dict(),
                    "receptor": describe_object(self.receptor).to_dict(),
                    "ligand": describe_object(self.ligand).to_dict(),
                }
            )
        return result


@dataclass(frozen=True)
class PiResultSummary:
    """Compact orchestration summary of one native pi-analysis result."""

    dock_model_identifier: str
    pose_identifier: str
    analysis_identifier: str
    success: bool
    completed_stage: str
    interaction_count: int = 0
    subtype_counts: Mapping[str, int] = field(default_factory=dict)
    aromatic_system_count: int = 0
    positive_group_count: int = 0
    negative_group_count: int = 0
    amide_group_count: int = 0
    group_count: int = 0
    hotspot_count: int = 0
    total_score: float = 0.0
    normalized_score: float = 0.0
    warning_count: int = 0
    error_count: int = 0

    def __post_init__(self) -> None:
        count_fields = (
            "interaction_count",
            "aromatic_system_count",
            "positive_group_count",
            "negative_group_count",
            "amide_group_count",
            "group_count",
            "hotspot_count",
            "warning_count",
            "error_count",
        )
        for name in count_fields:
            value = int(getattr(self, name))
            if value < 0:
                raise ValueError(f"{name} cannot be negative.")
            object.__setattr__(self, name, value)
        for name in ("total_score", "normalized_score"):
            value = float(getattr(self, name))
            if not math.isfinite(value):
                value = 0.0
            object.__setattr__(self, name, value)
        object.__setattr__(self, "success", bool(self.success))
        object.__setattr__(
            self,
            "subtype_counts",
            MappingProxyType(
                {
                    canonicalize_pi_subtype(name): max(0, int(count))
                    for name, count in dict(self.subtype_counts).items()
                }
            ),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready result summary."""

        return {
            "dock_model_identifier": self.dock_model_identifier,
            "pose_identifier": self.pose_identifier,
            "analysis_identifier": self.analysis_identifier,
            "success": self.success,
            "completed_stage": self.completed_stage,
            "interaction_count": self.interaction_count,
            "subtype_counts": dict(self.subtype_counts),
            "aromatic_system_count": self.aromatic_system_count,
            "positive_group_count": self.positive_group_count,
            "negative_group_count": self.negative_group_count,
            "amide_group_count": self.amide_group_count,
            "group_count": self.group_count,
            "hotspot_count": self.hotspot_count,
            "total_score": self.total_score,
            "normalized_score": self.normalized_score,
            "warning_count": self.warning_count,
            "error_count": self.error_count,
        }


@dataclass(frozen=True)
class PiStageOutput:
    """Integrated output produced by one pi-analysis stage execution."""

    result: Any
    summary: PiResultSummary
    interactions: Tuple[Any, ...] = ()
    interactions_by_subtype: Mapping[str, Tuple[Any, ...]] = field(default_factory=dict)
    recognized_features: Any = None
    grouping_result: Any = None
    statistics_report: Any = None
    statistics: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    integration_result: Any = None
    attached: bool = False
    reused: bool = False
    module_name: str = PI_MODULE_NAME
    module_version: Optional[str] = None
    result_type: str = PI_RESULT_TYPE

    def __post_init__(self) -> None:
        if self.result is None:
            raise ValueError("PiStageOutput.result cannot be None.")
        if not isinstance(self.summary, PiResultSummary):
            raise TypeError("PiStageOutput.summary must be a PiResultSummary.")
        object.__setattr__(self, "interactions", tuple(self.interactions))
        normalized_subtypes = {
            canonicalize_pi_subtype(name): tuple(values)
            for name, values in dict(self.interactions_by_subtype).items()
        }
        object.__setattr__(
            self,
            "interactions_by_subtype",
            MappingProxyType(normalized_subtypes),
        )
        object.__setattr__(
            self,
            "statistics",
            MappingProxyType(copy.deepcopy(dict(self.statistics))),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(copy.deepcopy(dict(self.metadata))),
        )
        object.__setattr__(self, "attached", bool(self.attached))
        object.__setattr__(self, "reused", bool(self.reused))

    @property
    def interaction_count(self) -> int:
        """Return the total number of pi interactions."""

        return self.summary.interaction_count

    @property
    def enabled_subtypes(self) -> Tuple[str, ...]:
        """Return subtypes represented by the native result."""

        return tuple(
            subtype
            for subtype in PI_INTERACTION_SUBTYPES
            if subtype in self.interactions_by_subtype
        )

    def to_dict(
        self,
        *,
        include_native_result: bool = False,
        include_interactions: bool = False,
    ) -> Dict[str, Any]:
        """Return an inspection-safe output representation."""

        result: Dict[str, Any] = {
            "result_type": self.result_type,
            "summary": self.summary.to_dict(),
            "statistics": to_json_compatible(dict(self.statistics)),
            "metadata": to_json_compatible(dict(self.metadata)),
            "attached": self.attached,
            "reused": self.reused,
            "module_name": self.module_name,
            "module_version": self.module_version,
            "integration_result": to_json_compatible(self.integration_result),
            "interaction_count": len(self.interactions),
            "subtype_counts": {
                name: len(values)
                for name, values in self.interactions_by_subtype.items()
            },
        }
        if include_interactions:
            result["interactions"] = to_json_compatible(self.interactions)
            result["interactions_by_subtype"] = to_json_compatible(
                dict(self.interactions_by_subtype)
            )
            result["recognized_features"] = to_json_compatible(
                self.recognized_features
            )
            result["grouping_result"] = to_json_compatible(self.grouping_result)
            result["statistics_report"] = to_json_compatible(
                self.statistics_report
            )
        if include_native_result:
            result["result"] = to_json_compatible(self.result)
        return result


# 14.4. Target resolution and native result inspection
# -----------------------------------------------------------------------------


def _require_pi_module(module: Optional[ModuleType] = None) -> ModuleType:
    """Return a validated pi-analysis module."""

    resolved = module or require_analysis_module(PI_MODULE_NAME, load=True)
    missing = tuple(name for name in PI_REQUIRED_SYMBOLS if not hasattr(resolved, name))
    if missing:
        raise AnalysisDependencyError(
            "The pi module does not expose the required adapter interface.",
            stage=STAGE_PI,
            details={"missing_symbols": list(missing)},
        )
    return resolved


def _pi_context_target(
    context: Optional[AnalysisContext],
    *,
    dock_model: Any,
    receptor: Any,
    ligand: Any,
    pose_index: Optional[int],
) -> Tuple[Any, Any, Any, Optional[int]]:
    """Fill missing pi-stage target components from a context."""

    if context is None:
        return dock_model, receptor, ligand, pose_index
    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance or None.")
    resolved_index = context.current_pose_index if pose_index is None else pose_index
    resolved_model = dock_model
    if resolved_model is None:
        if resolved_index is not None and 0 <= resolved_index < len(context.dock_models):
            resolved_model = context.dock_models[resolved_index]
        elif context.current_dock_model is not None:
            resolved_model = context.current_dock_model
        elif len(context.dock_models) == 1:
            resolved_model = context.dock_models[0]
    resolved_receptor = receptor if receptor is not None else context.receptor
    resolved_ligand = ligand
    if resolved_ligand is None:
        if resolved_index is not None and 0 <= resolved_index < len(context.poses):
            resolved_ligand = context.poses[resolved_index]
        elif context.current_pose is not None:
            resolved_ligand = context.current_pose
        elif len(context.poses) == 1:
            resolved_ligand = context.poses[0]
    return resolved_model, resolved_receptor, resolved_ligand, resolved_index


def _pi_model_identifier(dock_model: Any) -> str:
    """Return a stable human-readable DockModel identifier."""

    candidate = get_object_value(
        dock_model,
        "name",
        default=None,
        aliases=("identifier", "id", "model_id"),
        skip_none=True,
    )
    if candidate is None:
        candidate = describe_object(dock_model).identifier
    return normalize_identifier(
        candidate,
        default="dock_model",
        maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
    )


def _pi_pose_identifier(
    dock_model: Any,
    ligand: Any,
    pose_index: Optional[int],
    *,
    pi_module: ModuleType,
    adapter_config: Optional[PiAdapterConfig] = None,
) -> str:
    """Return the canonical pose identifier for pi analysis."""

    native_config = None
    if adapter_config is not None:
        native_config = adapter_config.native_integration_config(pi_module)
    try:
        native = pi_module.resolve_dock_model_pose_id(
            dock_model,
            config=native_config,
            fallback=None,
        )
    except Exception:
        native = None
    candidate = native
    if candidate is None:
        candidate = get_object_value(
            ligand,
            "name",
            default=None,
            aliases=("identifier", "id", "pose_id"),
            skip_none=True,
        )
    if candidate is None and pose_index is not None:
        candidate = f"pose_{pose_index + 1}"
    return normalize_identifier(
        candidate,
        default="pose",
        maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
    )


def resolve_pi_stage_target(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    receptor: Any = None,
    ligand: Any = None,
    pose_index: Optional[int] = None,
    adapter_config: Optional[PiAdapterConfig] = None,
    pi_module: Optional[ModuleType] = None,
) -> PiStageTarget:
    """Resolve one DockModel and molecular structure for pi analysis."""

    module = _require_pi_module(pi_module)
    dock_model, receptor, ligand, pose_index = _pi_context_target(
        context,
        dock_model=dock_model,
        receptor=receptor,
        ligand=ligand,
        pose_index=pose_index,
    )
    if dock_model is None:
        raise AnalysisInputError(
            "Pi-interaction analysis requires a prepared DockModel.",
            stage=STAGE_PI,
        )
    try:
        structure = module.resolve_dock_model_structure(dock_model)
    except Exception as exc:
        raise AnalysisInputError(
            "Pi-interaction analysis could not resolve a molecular structure.",
            stage=STAGE_PI,
            cause=exc,
        ) from exc
    if structure is None:
        raise AnalysisInputError(
            "Pi-interaction analysis resolved an empty molecular structure.",
            stage=STAGE_PI,
        )
    normalized_index = None if pose_index is None else int(pose_index)
    if normalized_index is not None and normalized_index < 0:
        raise AnalysisInputError(
            "Pi-interaction pose_index cannot be negative.",
            stage=STAGE_PI,
        )
    return PiStageTarget(
        dock_model=dock_model,
        structure=structure,
        receptor=receptor,
        ligand=ligand,
        pose_index=normalized_index,
        dock_model_identifier=_pi_model_identifier(dock_model),
        pose_identifier=_pi_pose_identifier(
            dock_model,
            ligand,
            normalized_index,
            pi_module=module,
            adapter_config=adapter_config,
        ),
    )


def is_pi_analysis_result(
    value: Any,
    *,
    pi_module: Optional[ModuleType] = None,
) -> bool:
    """Return whether a value is a native or compatible pi result."""

    if value is None:
        return False
    if pi_module is not None:
        result_class = getattr(pi_module, PI_RESULT_CLASS_NAME, None)
        if isinstance(result_class, type) and isinstance(value, result_class):
            return True
    return all(hasattr(value, name) for name in PI_RESULT_REQUIRED_ATTRIBUTES)


def _pi_object_mapping(value: Any) -> Dict[str, Any]:
    """Convert one native pi object to a plain mapping."""

    if value is None:
        return {}
    if isinstance(value, Mapping):
        return dict(value)
    to_dict_method = getattr(value, "to_dict", None)
    if callable(to_dict_method):
        for kwargs in ({}, {"include_objects": False}):
            try:
                converted = to_dict_method(**kwargs)
            except TypeError:
                continue
            except Exception:
                break
            if isinstance(converted, Mapping):
                return dict(converted)
    if is_dataclass(value) and not isinstance(value, type):
        return {item.name: getattr(value, item.name) for item in fields(value)}
    if hasattr(value, "__dict__"):
        return {
            str(name): item
            for name, item in vars(value).items()
            if not str(name).startswith("_")
        }
    return {}


def pi_result_interactions(value: Any) -> Tuple[Any, ...]:
    """Return all native pi interactions."""

    interactions = get_object_value(value, "interactions", default=(), skip_none=True)
    result = tuple(normalize_object_sequence(interactions))
    if len(result) > MAX_PI_ADAPTER_INTERACTIONS:
        raise AnalysisValidationError(
            "Pi result exceeds the supported interaction limit.",
            stage=STAGE_PI,
            details={"interaction_count": len(result)},
        )
    return result


def canonicalize_pi_result_subtype(value: Any) -> str:
    """Canonicalize a subtype reported by the native pi module."""

    token = normalize_identifier(value, default=PI_SUBTYPE_STACKING, maximum_length=128)
    token = PI_INTERACTION_TYPE_ALIASES.get(token, token)
    return canonicalize_pi_subtype(token)


def pi_result_interactions_by_subtype(value: Any) -> Dict[str, Tuple[Any, ...]]:
    """Return native interactions grouped by canonical subtype."""

    detected = get_object_value(
        value,
        "detected_interactions",
        default=None,
        skip_none=True,
    )
    grouped: Dict[str, List[Any]] = {
        subtype: [] for subtype in PI_INTERACTION_SUBTYPES
    }
    if detected is not None:
        for subtype, field_name in PI_NATIVE_INTERACTION_COLLECTIONS.items():
            collection = get_object_value(
                detected,
                field_name,
                default=(),
                skip_none=True,
            )
            grouped[subtype].extend(normalize_object_sequence(collection))
    if not any(grouped.values()):
        for interaction in pi_result_interactions(value):
            raw_type = get_object_value(
                interaction,
                "interaction_type",
                default=PI_SUBTYPE_STACKING,
                aliases=("type", "subtype"),
                skip_none=True,
            )
            try:
                subtype = canonicalize_pi_result_subtype(raw_type)
            except Exception:
                subtype = PI_SUBTYPE_STACKING
            grouped[subtype].append(interaction)
    return {name: tuple(values) for name, values in grouped.items()}


def pi_result_recognized_features(value: Any) -> Any:
    """Return the native recognized-feature bundle."""

    return get_object_value(value, "recognized_features", default=None, skip_none=True)


def pi_result_grouping(value: Any) -> Any:
    """Return the native grouping result."""

    return get_object_value(value, "grouping_result", default=None, skip_none=True)


def pi_result_statistics_report(value: Any) -> Any:
    """Return the native statistics report."""

    return get_object_value(value, "statistics_report", default=None, skip_none=True)


def pi_result_metadata(value: Any) -> Dict[str, Any]:
    """Return normalized native pi metadata."""

    metadata = get_object_value(value, "metadata", default={}, skip_none=True)
    return normalize_metadata_mapping(_pi_object_mapping(metadata))


def _pi_feature_count(features: Any, name: str) -> int:
    """Return the size of one recognized-feature collection."""

    value = get_object_value(features, name, default=(), skip_none=True)
    return len(normalize_object_sequence(value))


def _pi_group_count(grouping_result: Any) -> int:
    """Return the number of native interaction groups."""

    for name in ("groups", "interaction_groups", "grouped_interactions"):
        value = get_object_value(grouping_result, name, default=None, skip_none=True)
        if value is not None:
            return len(normalize_object_sequence(value))
    return 0


def _pi_hotspot_count(grouping_result: Any) -> int:
    """Return the number of native pi hotspots."""

    for name in ("hotspots", "pi_hotspots", "hotspot_groups"):
        value = get_object_value(grouping_result, name, default=None, skip_none=True)
        if value is not None:
            return len(normalize_object_sequence(value))
    return 0


def _pi_result_score(value: Any, name: str) -> float:
    """Resolve one finite score from result or statistics."""

    direct = get_object_value(value, name, default=None, skip_none=True)
    if direct is None:
        statistics = pi_result_statistics_report(value)
        direct = get_object_value(statistics, name, default=0.0, skip_none=True)
    try:
        converted = float(direct)
    except (TypeError, ValueError, OverflowError):
        return 0.0
    return converted if math.isfinite(converted) else 0.0


def validate_pi_analysis_result(
    value: Any,
    *,
    pi_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one native pi-analysis result."""

    issues: List[str] = []
    if not is_pi_analysis_result(value, pi_module=pi_module):
        issues.append("Value is not a compatible pi-analysis result.")
    else:
        interactions = pi_result_interactions(value)
        grouped = pi_result_interactions_by_subtype(value)
        grouped_count = sum(len(items) for items in grouped.values())
        if grouped_count != len(interactions):
            issues.append(
                "Pi subtype collections do not match the complete interaction collection."
            )
        success = bool(get_object_value(value, "success", default=False))
        errors = normalize_object_sequence(
            get_object_value(value, "errors", default=(), skip_none=True)
        )
        if success and errors:
            issues.append("Successful pi result contains native errors.")
    result = tuple(issues)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Pi-analysis result validation failed.",
            stage=STAGE_PI,
            details={"issues": list(result)},
        )
    return result


def summarize_pi_analysis_result_adapter(
    value: Any,
    *,
    target: Optional[PiStageTarget] = None,
    pi_module: Optional[ModuleType] = None,
) -> PiResultSummary:
    """Create a stable summary from one native pi result."""

    module = _require_pi_module(pi_module)
    validate_pi_analysis_result(value, pi_module=module, raise_on_error=True)
    grouped = pi_result_interactions_by_subtype(value)
    features = pi_result_recognized_features(value)
    grouping = pi_result_grouping(value)
    dock_identifier = target.dock_model_identifier if target else "dock_model"
    pose_identifier = target.pose_identifier if target else normalize_identifier(
        get_object_value(value, "pose_id", default="pose", skip_none=True),
        default="pose",
        maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
    )
    analysis_identifier = normalize_identifier(
        get_object_value(value, "analysis_id", default="pi_analysis", skip_none=True),
        default="pi_analysis",
        maximum_length=MAX_PI_ADAPTER_IDENTIFIER_LENGTH,
    )
    return PiResultSummary(
        dock_model_identifier=dock_identifier,
        pose_identifier=pose_identifier,
        analysis_identifier=analysis_identifier,
        success=bool(get_object_value(value, "success", default=False)),
        completed_stage=str(
            get_object_value(value, "completed_stage", default="unknown", skip_none=True)
        ),
        interaction_count=len(pi_result_interactions(value)),
        subtype_counts={name: len(items) for name, items in grouped.items()},
        aromatic_system_count=_pi_feature_count(features, "aromatic_systems"),
        positive_group_count=_pi_feature_count(features, "positive_groups"),
        negative_group_count=_pi_feature_count(features, "negative_groups"),
        amide_group_count=_pi_feature_count(features, "amide_groups"),
        group_count=_pi_group_count(grouping),
        hotspot_count=_pi_hotspot_count(grouping),
        total_score=_pi_result_score(value, "total_score"),
        normalized_score=_pi_result_score(value, "normalized_score"),
        warning_count=len(
            normalize_object_sequence(
                get_object_value(value, "warnings", default=(), skip_none=True)
            )
        ),
        error_count=len(
            normalize_object_sequence(
                get_object_value(value, "errors", default=(), skip_none=True)
            )
        ),
    )


def adapt_pi_analysis_result(
    value: Any,
    *,
    target: Optional[PiStageTarget] = None,
    integration_result: Any = None,
    attached: bool = False,
    reused: bool = False,
    pi_module: Optional[ModuleType] = None,
) -> PiStageOutput:
    """Convert a specialized pi result to the stage-output model."""

    module = _require_pi_module(pi_module)
    summary = summarize_pi_analysis_result_adapter(
        value,
        target=target,
        pi_module=module,
    )
    grouped = pi_result_interactions_by_subtype(value)
    statistics_report = pi_result_statistics_report(value)
    statistics = normalize_statistics_mapping(_pi_object_mapping(statistics_report))
    statistics.setdefault("interaction_count", summary.interaction_count)
    statistics.setdefault("subtype_counts", dict(summary.subtype_counts))
    statistics.setdefault("total_score", summary.total_score)
    statistics.setdefault("normalized_score", summary.normalized_score)
    metadata = pi_result_metadata(value)
    metadata.update(
        {
            "adapter_schema": PI_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": PI_ADAPTER_SCHEMA_VERSION,
            "dock_model_identifier": summary.dock_model_identifier,
            "pose_identifier": summary.pose_identifier,
            "analysis_identifier": summary.analysis_identifier,
        }
    )
    return PiStageOutput(
        result=value,
        summary=summary,
        interactions=pi_result_interactions(value),
        interactions_by_subtype=grouped,
        recognized_features=pi_result_recognized_features(value),
        grouping_result=pi_result_grouping(value),
        statistics_report=statistics_report,
        statistics=statistics,
        metadata=metadata,
        integration_result=integration_result,
        attached=attached,
        reused=reused,
        module_name=getattr(module, "__name__", PI_MODULE_NAME),
        module_version=get_module_version(module),
    )


def validate_pi_stage_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one integrated pi-stage output."""

    issues: List[str] = []
    if not isinstance(value, PiStageOutput):
        issues.append("Value is not a PiStageOutput.")
    else:
        issues.extend(validate_pi_analysis_result(value.result))
        if value.summary.interaction_count != len(value.interactions):
            issues.append("Pi output summary does not match the interaction collection.")
        grouped_count = sum(len(items) for items in value.interactions_by_subtype.values())
        if grouped_count != len(value.interactions):
            issues.append("Pi output subtype counts do not match all interactions.")
    result = tuple(issues)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Pi stage output validation failed.",
            stage=STAGE_PI,
            details={"issues": list(result)},
        )
    return result


# 14.5. Stage execution
# -----------------------------------------------------------------------------


def get_reusable_pi_analysis(
    target: PiStageTarget,
    config: PiAdapterConfig,
    *,
    pi_module: Optional[ModuleType] = None,
) -> Optional[Any]:
    """Return a stored live pi-analysis result, when available."""

    module = _require_pi_module(pi_module)
    candidates = (
        config.analysis_result_attribute,
        PI_DEFAULT_ANALYSIS_RESULT_ATTRIBUTE,
        "pi_result",
        "pi_analysis",
    )
    for name in candidates:
        candidate = get_object_value(target.dock_model, name, default=None, skip_none=True)
        if is_pi_analysis_result(candidate, pi_module=module):
            return candidate
        if isinstance(candidate, Mapping):
            for key in ("analysis_result", "result", "native_result"):
                nested = candidate.get(key)
                if is_pi_analysis_result(nested, pi_module=module):
                    return nested
    return None


def _pi_execution_metadata(
    context: Optional[AnalysisContext],
    target: PiStageTarget,
    config: PiAdapterConfig,
) -> Dict[str, Any]:
    """Build provenance metadata for one native pi execution."""

    metadata = dict(config.metadata)
    metadata.update(
        {
            "adapter_schema": PI_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": PI_ADAPTER_SCHEMA_VERSION,
            "dock_model_identifier": target.dock_model_identifier,
            "pose_identifier": target.pose_identifier,
            "pose_index": target.pose_index,
            "enabled_subtypes": list(config.enabled_subtypes),
        }
    )
    if context is not None:
        metadata.setdefault("request_id", context.request_id)
        metadata.setdefault("analysis_mode", context.mode)
    return metadata


def run_pi_analysis_adapter(
    target: PiStageTarget,
    config: PiAdapterConfig,
    *,
    context: Optional[AnalysisContext] = None,
    reuse_result: bool = False,
    pi_module: Optional[ModuleType] = None,
) -> PiStageOutput:
    """Run or reuse one complete pi analysis and adapt its result."""

    module = _require_pi_module(pi_module)
    if reuse_result:
        reusable = get_reusable_pi_analysis(target, config, pi_module=module)
        if reusable is not None:
            return adapt_pi_analysis_result(
                reusable,
                target=target,
                attached=True,
                reused=True,
                pi_module=module,
            )

    metadata = _pi_execution_metadata(context, target, config)
    effective_config = config.with_metadata(metadata)
    analysis_config = effective_config.native_analysis_config(module)
    if getattr(analysis_config, "analysis_id", None) is None:
        analysis_config.analysis_id = (
            f"pi:{target.dock_model_identifier}:{target.pose_identifier}"
        )
    if getattr(analysis_config, "pose_id", None) is None:
        analysis_config.pose_id = target.pose_identifier
    feature_kwargs = effective_config.feature_kwargs()

    integration_result = None
    if effective_config.attach:
        integration_config = effective_config.native_integration_config(module)
        integration_result = getattr(module, PI_DOCK_MODEL_ANALYSIS_FUNCTION)(
            target.dock_model,
            analysis_config=analysis_config,
            integration_config=integration_config,
            pose_id=target.pose_identifier,
            analysis_id=analysis_config.analysis_id,
            **feature_kwargs,
        )
        result = get_object_value(
            integration_result,
            "analysis_result",
            default=None,
            skip_none=True,
        )
        if not is_pi_analysis_result(result, pi_module=module):
            raise AnalysisIntegrationError(
                "Native pi DockModel integration did not return a compatible result.",
                stage=STAGE_PI,
            )
    else:
        result = getattr(module, PI_DIRECT_ANALYSIS_FUNCTION)(
            target.structure,
            config=analysis_config,
            analysis_id=analysis_config.analysis_id,
            pose_id=target.pose_identifier,
            **feature_kwargs,
        )

    return adapt_pi_analysis_result(
        result,
        target=target,
        integration_result=integration_result,
        attached=integration_result is not None,
        reused=False,
        pi_module=module,
    )


def _pi_stage_failure_should_raise(
    context: Optional[AnalysisContext],
    raise_on_error: Optional[bool],
) -> bool:
    """Resolve whether pi-stage failures should be raised."""

    if raise_on_error is not None:
        return bool(raise_on_error)
    if context is None:
        return True
    return context.config.runtime.failure_policy == FAILURE_POLICY_STRICT


def _record_pi_stage_context(
    context: AnalysisContext,
    stage_result: AnalysisStageResult,
) -> None:
    """Store pi output and statistics in the runtime context."""

    context.set_stage_data(PI_STAGE_DATA_KEY, stage_result)
    if isinstance(stage_result.value, PiStageOutput):
        output = stage_result.value
        context.statistics[PI_STAGE_STATISTICS_KEY] = output.summary.to_dict()
        context.metadata[PI_STAGE_METADATA_KEY] = {
            "dock_model_identifier": output.summary.dock_model_identifier,
            "pose_identifier": output.summary.pose_identifier,
            "analysis_identifier": output.summary.analysis_identifier,
            "module_version": output.module_version,
            "reused": output.reused,
            "attached": output.attached,
            "enabled_subtypes": list(output.enabled_subtypes),
        }


def execute_pi_stage(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    receptor: Any = None,
    ligand: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    pi_module: Optional[ModuleType] = None,
    raise_on_error: Optional[bool] = None,
) -> AnalysisStageResult:
    """Execute the registered pi-interaction pipeline stage."""

    integrated_config = (
        context.config
        if context is not None and config is None
        else coerce_analysis_config(config)
    )
    stage_config = integrated_config.stage_config(STAGE_PI)
    stage_result = AnalysisStageResult(
        stage=STAGE_PI,
        required=stage_config.required,
    )
    if not stage_config.enabled or not integrated_config.interactions.pi:
        stage_result.skip("Pi-interaction analysis is disabled by configuration.")
        if context is not None:
            _record_pi_stage_context(context, stage_result)
        return stage_result

    stage_result.start()
    try:
        if context is not None:
            context.raise_if_cancelled(stage=STAGE_PI)
            context.set_current_stage(STAGE_PI)
        module = _require_pi_module(pi_module)
        adapter_config = resolve_pi_adapter_config(
            integrated_config,
            overrides=overrides,
        )
        if not adapter_config.enabled:
            stage_result.skip("No pi-interaction subtype is enabled.")
            return stage_result
        target = resolve_pi_stage_target(
            context,
            dock_model=dock_model,
            receptor=receptor,
            ligand=ligand,
            pose_index=pose_index,
            adapter_config=adapter_config,
            pi_module=module,
        )
        adapter_config = adapter_config.with_metadata(
            {
                "dock_model_identifier": target.dock_model_identifier,
                "pose_identifier": target.pose_identifier,
            }
        )
        stage_result.input_summary = target.to_dict(include_objects=False)
        stage_result.metadata.update(
            {
                "adapter_schema": PI_ADAPTER_SCHEMA_NAME,
                "adapter_schema_version": PI_ADAPTER_SCHEMA_VERSION,
                "module_name": getattr(module, "__name__", PI_MODULE_NAME),
                "module_version": get_module_version(module),
                "configuration": adapter_config.to_dict(),
            }
        )
        output = run_pi_analysis_adapter(
            target,
            adapter_config,
            context=context,
            reuse_result=stage_config.reuse_result,
            pi_module=module,
        )
        if stage_config.validate_result:
            validate_pi_stage_output(output, raise_on_error=True)
        stage_result.cached = output.reused
        stage_result.statistics = dict(output.statistics)
        stage_result.output_summary = output.summary.to_dict()
        stage_result.succeed(
            output,
            message=(
                "Reused a stored live pi-interaction analysis."
                if output.reused
                else "Pi-interaction analysis completed successfully."
            ),
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisStageError(
                "Pi-interaction analysis failed.",
                stage=STAGE_PI,
                cause=exc,
                details={"exception_type": type(exc).__name__},
            )
        stage_result.fail(
            wrapped,
            include_traceback=(
                context is not None and context.config.runtime.collect_diagnostics
            ),
        )
        if _pi_stage_failure_should_raise(context, raise_on_error):
            raise wrapped from exc
    finally:
        if context is not None:
            _record_pi_stage_context(context, stage_result)
            context.set_current_stage(None)
    return stage_result


# 14.6. Convenience adapters for prepared models
# -----------------------------------------------------------------------------


def analyze_dock_model_pi_interactions(
    dock_model: Any,
    *,
    receptor: Any = None,
    ligand: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    pi_module: Optional[ModuleType] = None,
) -> PiStageOutput:
    """Analyze all selected pi interactions for one prepared DockModel."""

    stage_result = execute_pi_stage(
        None,
        dock_model=dock_model,
        receptor=receptor,
        ligand=ligand,
        pose_index=pose_index,
        config=config,
        overrides=overrides,
        pi_module=pi_module,
        raise_on_error=True,
    )
    if not isinstance(stage_result.value, PiStageOutput):
        raise AnalysisIntegrationError(
            "The pi stage did not produce a PiStageOutput.",
            stage=STAGE_PI,
        )
    return stage_result.value


def analyze_prepared_dock_models_pi(
    dock_models: Iterable[Any],
    *,
    receptor: Any = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    pi_module: Optional[ModuleType] = None,
    continue_on_error: bool = False,
) -> Tuple[AnalysisStageResult, ...]:
    """Run the pi adapter for prepared DockModel objects."""

    models = tuple(normalize_object_sequence(dock_models))
    if not models:
        return ()
    module = _require_pi_module(pi_module)
    results: List[AnalysisStageResult] = []
    for index, model in enumerate(models):
        try:
            result = execute_pi_stage(
                None,
                dock_model=model,
                receptor=receptor,
                pose_index=index,
                config=config,
                overrides=overrides,
                pi_module=module,
                raise_on_error=not continue_on_error,
            )
        except Exception as exc:
            if not continue_on_error:
                raise
            result = AnalysisStageResult(stage=STAGE_PI)
            result.start().fail(exc)
        results.append(result)
    return tuple(results)


def analyze_multiple_dock_models_pi_native(
    dock_models: Iterable[Any],
    *,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    pi_module: Optional[ModuleType] = None,
    continue_on_error: bool = True,
    run_global_multipose_analysis: bool = True,
) -> Any:
    """Run the specialized native multipose pi interface."""

    module = _require_pi_module(pi_module)
    adapter_config = resolve_pi_adapter_config(config, overrides=overrides)
    models = tuple(normalize_object_sequence(dock_models))
    analyzer = getattr(module, PI_MULTIPOSE_FUNCTION)
    return analyzer(
        models,
        analysis_config=adapter_config.native_analysis_config(module),
        integration_config=adapter_config.native_integration_config(module),
        aromatic_systems=adapter_config.aromatic_systems or None,
        positive_groups=adapter_config.positive_groups or None,
        negative_groups=adapter_config.negative_groups or None,
        amide_groups=adapter_config.amide_groups or None,
        continue_on_error=continue_on_error,
        run_global_multipose_analysis=run_global_multipose_analysis,
    )


# 14.7. Stage registry integration
# -----------------------------------------------------------------------------


def pi_stage_result_adapter(value: Any, **kwargs: Any) -> PiStageOutput:
    """Registry-compatible adapter for specialized pi results."""

    if hasattr(value, "analysis_result") and not is_pi_analysis_result(value):
        integration_result = value
        value = getattr(value, "analysis_result")
        kwargs.setdefault("integration_result", integration_result)
        kwargs.setdefault("attached", True)
    return adapt_pi_analysis_result(value, **kwargs)


def pi_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible validator for pi-stage values."""

    if isinstance(value, AnalysisStageResult):
        if value.value is None:
            return () if value.status == StageStatus.SKIPPED else (
                "Pi stage result does not contain a value.",
            )
        value = value.value
    if isinstance(value, PiStageOutput):
        return validate_pi_stage_output(value)
    return validate_pi_analysis_result(value)


def register_pi_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the pi executor, adapter and validator."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_PI)
    updated_metadata = dict(definition.metadata)
    updated_metadata.update(
        {
            "adapter_schema": PI_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": PI_ADAPTER_SCHEMA_VERSION,
            "analysis_function": PI_DOCK_MODEL_ANALYSIS_FUNCTION,
            "multipose_function": PI_MULTIPOSE_FUNCTION,
            "result_type": PI_RESULT_TYPE,
            "supported_subtypes": list(PI_INTERACTION_SUBTYPES),
        }
    )
    updated = replace(
        definition,
        executor=execute_pi_stage,
        result_adapter=pi_stage_result_adapter,
        validator=pi_stage_validator,
        metadata=updated_metadata,
    )
    target_registry.replace(updated)
    return updated


def pi_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the pi-stage adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_PI)
    return bool(
        definition is not None
        and definition.executor is execute_pi_stage
        and definition.result_adapter is pi_stage_result_adapter
        and definition.validator is pi_stage_validator
    )


# 14.8. Summaries, validation and public interface
# -----------------------------------------------------------------------------


def summarize_pi_stage_result(value: Any) -> Dict[str, Any]:
    """Return a compact summary for a pi-stage result or output."""

    if isinstance(value, AnalysisStageResult):
        result: Dict[str, Any] = {
            "stage": value.stage,
            "status": value.status.value,
            "cached": value.cached,
            "duration_seconds": value.duration_seconds,
        }
        if isinstance(value.value, PiStageOutput):
            result.update(value.value.summary.to_dict())
        return result
    if isinstance(value, PiStageOutput):
        result = value.summary.to_dict()
        result.update(
            {
                "attached": value.attached,
                "reused": value.reused,
                "module_version": value.module_version,
            }
        )
        return result
    if is_pi_analysis_result(value):
        return summarize_pi_analysis_result_adapter(value).to_dict()
    raise TypeError(
        "value must be an AnalysisStageResult, PiStageOutput or pi result."
    )


def validate_pi_adapter_conventions() -> Dict[str, Any]:
    """Validate pi-adapter constants, data structures and registration."""

    failures: List[str] = []
    if canonicalize_pi_attachment_mode("combine") != "append":
        failures.append("Pi attachment alias resolution failed.")
    if canonicalize_pi_score_mode("normalized") != "normalized":
        failures.append("Pi score-mode resolution failed.")
    config = PiAdapterConfig.from_mapping(
        {
            "stacking": True,
            "cation": False,
            "anion": True,
            "amide": False,
            "mode": "append",
            "score": "total",
        }
    )
    if config.enabled_subtypes != (PI_SUBTYPE_STACKING, PI_SUBTYPE_ANION):
        failures.append("Pi subtype selection failed.")
    if not config.append_new_interactions or config.score_mode != "total":
        failures.append("Pi integration configuration failed.")

    class FakeFeatures:
        aromatic_systems = (object(), object())
        positive_groups = (object(),)
        negative_groups = ()
        amide_groups = (object(),)

    class FakeDetected:
        pi_pi = (SimpleNamespace(interaction_type="pi_pi"),)
        cation_pi = ()
        anion_pi = (SimpleNamespace(interaction_type="anion_pi"),)
        amide_pi = ()

    class FakeResult:
        analysis_id = "analysis-1"
        analysis_mode = "single_pose"
        pose_id = "pose-1"
        recognized_features = FakeFeatures()
        detected_interactions = FakeDetected()
        consolidated_result = None
        grouping_result = SimpleNamespace(groups=(object(),), hotspots=())
        statistics_report = SimpleNamespace(
            total_score=1.25,
            normalized_total_score=0.625,
        )
        interactions = tuple(FakeDetected.pi_pi + FakeDetected.anion_pi)
        success = True
        completed_stage = "completed"
        warnings = []
        errors = []
        metadata = {}

        @property
        def total_score(self) -> float:
            return 1.25

        @property
        def normalized_score(self) -> float:
            return 0.625

    class FakeIntegrationResult:
        def __init__(self, result: Any, dock_model: Any = None) -> None:
            self.analysis_result = result
            self.dock_model = dock_model
            self.success = True

    class FakeMultipleResult:
        pass

    class FakeIntegrationConfig:
        def __init__(self, **kwargs: Any) -> None:
            for name, value in kwargs.items():
                setattr(self, name, value)

    class FakeAnalysisConfig:
        def __init__(self, **kwargs: Any) -> None:
            for name, value in kwargs.items():
                setattr(self, name, value)

    class FakePiModule(ModuleType):
        pass

    fake_module = FakePiModule("pi")
    fake_module.__version__ = "test"
    fake_module.PiAnalysisConfig = FakeAnalysisConfig
    fake_module.PiAnalysisResult = FakeResult
    fake_module.PiMultiplePoseAnalysisResult = FakeMultipleResult
    fake_module.DockModelPiIntegrationConfig = FakeIntegrationConfig
    fake_module.DockModelPiIntegrationResult = FakeIntegrationResult
    fake_module.DockModelPiMultipleIntegrationResult = FakeMultipleResult
    fake_module.create_default_pi_analysis_config = lambda: FakeAnalysisConfig(
        pi_pi_config=None,
        cation_pi_config=None,
        anion_pi_config=None,
        amide_pi_config=None,
        scoring_config=None,
        grouping_config=None,
        statistics_config=None,
    )
    fake_module.create_default_dock_model_pi_config = lambda: FakeIntegrationConfig()
    fake_module.resolve_dock_model_structure = lambda model: getattr(model, "structure", model)
    fake_module.resolve_dock_model_pose_id = lambda model, config=None, fallback=None: getattr(model, "pose_id", fallback)
    fake_module.get_dock_model_pi_interactions = lambda model, config=None: list(getattr(model, "pi", []))
    fake_module.summarize_pi_analysis_result = lambda result: {"total_interactions": len(result.interactions)}
    fake_module.attach_pi_results = lambda model, result, config=None: FakeIntegrationResult(result, model)
    fake_module.analyze_pi_interactions = lambda *args, **kwargs: FakeResult()
    fake_module.analyze_dock_model_pi = lambda model, **kwargs: FakeIntegrationResult(FakeResult(), model)
    fake_module.analyze_multiple_dock_models_pi = lambda *args, **kwargs: FakeMultipleResult()

    dock_model = SimpleNamespace(
        name="dock-1",
        pose_id="pose-1",
        structure=SimpleNamespace(name="complex-1"),
        pi=[],
        statistics={},
        metadata={},
    )
    target = resolve_pi_stage_target(
        None,
        dock_model=dock_model,
        pi_module=fake_module,
    )
    output = run_pi_analysis_adapter(
        target,
        replace(config, attach=True),
        pi_module=fake_module,
    )
    if output.interaction_count != 2:
        failures.append("Pi result adaptation produced the wrong count.")
    if output.summary.subtype_counts.get(PI_SUBTYPE_ANION) != 1:
        failures.append("Pi subtype adaptation failed.")
    if validate_pi_stage_output(output):
        failures.append("A valid pi output did not validate.")
    if not output.attached:
        failures.append("Pi result was not marked as attached.")
    if json.loads(json.dumps(output.to_dict()))["summary"]["total_score"] != 1.25:
        failures.append("Pi output JSON conversion failed.")

    integrated = AnalysisConfig(
        interactions=InteractionSelection(
            contacts=False,
            hbonds=False,
            hydrophobic=False,
            pi=True,
            saltbridge=False,
            pi_subtypes=(PI_SUBTYPE_STACKING, PI_SUBTYPE_ANION),
        ),
        stage_configs={
            STAGE_PI: AnalysisStageConfig(
                enabled=True,
                attach_results=True,
                validate_result=True,
                reuse_result=False,
                parameters={"attachment_mode": "replace"},
            )
        },
        runtime=AnalysisRuntimeConfig(
            failure_policy=FAILURE_POLICY_STRICT,
            attach_results=True,
            reuse_results=True,
        ),
    )
    request = AnalysisRequest(dock_models=(dock_model,), config=integrated)
    context = AnalysisContext(
        request=request,
        dock_models=[dock_model],
        current_pose_index=0,
    )
    stage_result = execute_pi_stage(
        context,
        pi_module=fake_module,
        raise_on_error=True,
    )
    if not stage_result.succeeded:
        failures.append("Pi stage executor did not succeed.")
    if not isinstance(stage_result.value, PiStageOutput):
        failures.append("Pi executor returned an unexpected value.")
    if context.get_stage_data(STAGE_PI) is not stage_result:
        failures.append("Pi result was not stored in the context.")

    registry = create_default_stage_registry()
    register_pi_stage_adapter(registry=registry)
    if not pi_stage_adapter_registered(registry=registry):
        failures.append("Pi adapter was not registered correctly.")

    real_module = _require_pi_module()
    missing_interface = tuple(
        name for name in PI_REQUIRED_SYMBOLS if not hasattr(real_module, name)
    )
    if missing_interface:
        failures.append(
            "The repository pi module is missing required symbols: "
            + ", ".join(missing_interface)
        )

    if failures:
        raise RuntimeError(
            "Pi adapter convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": PI_ADAPTER_SCHEMA_NAME,
        "schema_version": PI_ADAPTER_SCHEMA_VERSION,
        "required_symbols": len(PI_REQUIRED_SYMBOLS),
        "supported_parameters": len(PI_ADAPTER_FIELDS),
        "supported_subtypes": len(PI_INTERACTION_SUBTYPES),
        "validated_cases": 25,
    }


