# 15.2. Salt-bridge adapter configuration
# -----------------------------------------------------------------------------


def canonicalize_saltbridge_total_score_mode(value: Any) -> str:
    """Return a canonical total-score update mode."""

    token = normalize_identifier(
        value,
        default=SALTBRIDGE_DEFAULT_TOTAL_SCORE_MODE,
        maximum_length=64,
    )
    canonical = SALTBRIDGE_TOTAL_SCORE_MODE_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported salt-bridge total-score mode {value!r}. Supported "
            f"values: {', '.join(sorted(SALTBRIDGE_TOTAL_SCORE_MODES))}."
        )
    return canonical


def canonicalize_saltbridge_persistence_mode(value: Any) -> str:
    """Return a canonical salt-bridge persistence mode."""

    token = normalize_identifier(
        value,
        default=SALTBRIDGE_DEFAULT_PERSISTENCE_MODE,
        maximum_length=64,
    )
    canonical = SALTBRIDGE_PERSISTENCE_MODE_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported salt-bridge persistence mode {value!r}. Supported "
            f"values: {', '.join(sorted(SALTBRIDGE_PERSISTENCE_MODES))}."
        )
    return canonical


def _normalize_saltbridge_parameter_name(value: Any) -> str:
    """Normalize one salt-bridge adapter parameter name."""

    token = normalize_identifier(value, maximum_length=128)
    return SALTBRIDGE_PARAMETER_ALIASES.get(token, token)


def _saltbridge_optional_float(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
) -> Optional[float]:
    """Normalize a finite optional floating-point value."""

    if value is None:
        return None
    try:
        converted = float(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(
            f"{field_name} must be a finite number or None."
        ) from exc
    if not math.isfinite(converted):
        raise AnalysisConfigurationError(f"{field_name} must be finite.")
    if minimum is not None and converted < minimum:
        raise AnalysisConfigurationError(
            f"{field_name} must be greater than or equal to {minimum}."
        )
    if maximum is not None and converted > maximum:
        raise AnalysisConfigurationError(
            f"{field_name} must be less than or equal to {maximum}."
        )
    return converted


def _saltbridge_optional_int(
    value: Any,
    *,
    field_name: str,
    minimum: int = 0,
) -> Optional[int]:
    """Normalize a bounded optional integer."""

    if value is None:
        return None
    if isinstance(value, bool):
        raise AnalysisConfigurationError(f"{field_name} must be an integer.")
    try:
        converted = int(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise AnalysisConfigurationError(f"{field_name} must be an integer.") from exc
    if converted < minimum:
        raise AnalysisConfigurationError(
            f"{field_name} must be greater than or equal to {minimum}."
        )
    return converted


def _saltbridge_bool(value: Any, *, field_name: str) -> bool:
    """Normalize a strict boolean-like value."""

    if isinstance(value, bool):
        return value
    if isinstance(value, Real) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        token = normalize_identifier(value, maximum_length=32)
        if token in {"true", "yes", "on", "enabled", "1"}:
            return True
        if token in {"false", "no", "off", "disabled", "0"}:
            return False
    raise AnalysisConfigurationError(f"{field_name} must be boolean-like.")


def _saltbridge_mapping(value: Any, *, field_name: str) -> Mapping[str, Any]:
    """Normalize and freeze a salt-bridge adapter mapping."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        to_dict_method = getattr(value, "to_dict", None)
        if callable(to_dict_method):
            value = to_dict_method()
        elif is_dataclass(value) and not isinstance(value, type):
            value = asdict(value)
    if not isinstance(value, Mapping):
        raise AnalysisConfigurationError(f"{field_name} must be a mapping.")
    if len(value) > MAX_SALTBRIDGE_ADAPTER_MAPPING_ITEMS:
        raise AnalysisConfigurationError(
            f"{field_name} exceeds {MAX_SALTBRIDGE_ADAPTER_MAPPING_ITEMS} entries."
        )
    return MappingProxyType(copy.deepcopy(dict(value)))


def _saltbridge_runtime_preserve_existing(config: AnalysisConfig) -> bool:
    """Map the integrated attachment policy to salt-bridge preservation."""

    return config.runtime.attachment_policy != ATTACHMENT_POLICY_REPLACE


@dataclass(frozen=True)
class SaltBridgeAdapterConfig:
    """Resolved configuration for one salt-bridge stage execution."""

    native_parameters: Mapping[str, Any] = field(default_factory=dict)
    attach: bool = True
    attribute_name: str = SALTBRIDGE_DEFAULT_ATTRIBUTE
    preserve_existing: bool = True
    attach_result_object: bool = True
    attach_statistics: bool = True
    attach_summary: bool = True
    update_statistics: bool = True
    update_score: bool = True
    update_total_score: bool = False
    total_score_mode: str = SALTBRIDGE_DEFAULT_TOTAL_SCORE_MODE
    store_full_groups: Optional[bool] = None
    include_invalid_statistics: bool = False
    reuse_results: bool = True
    persistence_mode: str = SALTBRIDGE_DEFAULT_PERSISTENCE_MODE
    consensus_percentage: float = SALTBRIDGE_DEFAULT_CONSENSUS_PERCENTAGE
    minimum_consensus_poses: int = SALTBRIDGE_DEFAULT_MINIMUM_CONSENSUS_POSES
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        parameters = _saltbridge_mapping(
            self.native_parameters,
            field_name="saltbridge.native_parameters",
        )
        unknown = sorted(set(parameters).difference(SALTBRIDGE_NATIVE_CONFIG_FIELDS))
        if unknown:
            raise AnalysisConfigurationError(
                "Unsupported salt-bridge native parameters: " + ", ".join(unknown)
            )
        normalized_parameters: Dict[str, Any] = {}
        for name, value in parameters.items():
            normalized_parameters[name] = _normalize_saltbridge_native_value(
                name,
                value,
            )
        object.__setattr__(
            self,
            "native_parameters",
            MappingProxyType(normalized_parameters),
        )
        for name in (
            "attach",
            "preserve_existing",
            "attach_result_object",
            "attach_statistics",
            "attach_summary",
            "update_statistics",
            "update_score",
            "update_total_score",
            "include_invalid_statistics",
            "reuse_results",
        ):
            object.__setattr__(
                self,
                name,
                _saltbridge_bool(
                    getattr(self, name),
                    field_name=f"saltbridge.{name}",
                ),
            )
        attribute = normalize_identifier(
            self.attribute_name,
            default=SALTBRIDGE_DEFAULT_ATTRIBUTE,
            maximum_length=128,
        )
        object.__setattr__(self, "attribute_name", attribute)
        object.__setattr__(
            self,
            "total_score_mode",
            canonicalize_saltbridge_total_score_mode(self.total_score_mode),
        )
        object.__setattr__(
            self,
            "persistence_mode",
            canonicalize_saltbridge_persistence_mode(self.persistence_mode),
        )
        if self.store_full_groups is not None:
            object.__setattr__(
                self,
                "store_full_groups",
                _saltbridge_bool(
                    self.store_full_groups,
                    field_name="saltbridge.store_full_groups",
                ),
            )
        consensus = _saltbridge_optional_float(
            self.consensus_percentage,
            field_name="saltbridge.consensus_percentage",
            minimum=0.0,
            maximum=100.0,
        )
        object.__setattr__(self, "consensus_percentage", float(consensus or 0.0))
        minimum_consensus = _saltbridge_optional_int(
            self.minimum_consensus_poses,
            field_name="saltbridge.minimum_consensus_poses",
            minimum=1,
        )
        object.__setattr__(
            self,
            "minimum_consensus_poses",
            int(minimum_consensus or 1),
        )
        object.__setattr__(
            self,
            "metadata",
            _saltbridge_mapping(self.metadata, field_name="saltbridge.metadata"),
        )

    @classmethod
    def from_mapping(
        cls,
        values: Optional[Mapping[str, Any]] = None,
        *,
        strict: bool = True,
    ) -> "SaltBridgeAdapterConfig":
        """Create an adapter configuration from a flat mapping."""

        if values is None:
            return cls()
        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Salt-bridge adapter configuration must be a mapping."
            )
        native: Dict[str, Any] = {}
        controls: Dict[str, Any] = {}
        for raw_name, value in values.items():
            name = _normalize_saltbridge_parameter_name(raw_name)
            if name in SALTBRIDGE_NATIVE_CONFIG_FIELDS:
                native[name] = value
            elif name in SALTBRIDGE_ADAPTER_CONTROL_FIELDS:
                controls[name] = value
            elif strict:
                raise AnalysisConfigurationError(
                    f"Unsupported salt-bridge adapter parameter {raw_name!r}."
                )
        existing_native = controls.pop("native_parameters", None)
        if isinstance(existing_native, Mapping):
            native = {**existing_native, **native}
        return cls(native_parameters=native, **controls)

    def merged(self, updates: Optional[Mapping[str, Any]]) -> "SaltBridgeAdapterConfig":
        """Return a configuration with mapping updates applied."""

        if not updates:
            return self
        current = self.to_dict()
        native = dict(current.pop("native_parameters", {}))
        normalized_updates: Dict[str, Any] = {}
        for raw_name, value in updates.items():
            name = _normalize_saltbridge_parameter_name(raw_name)
            if name in SALTBRIDGE_NATIVE_CONFIG_FIELDS:
                native[name] = value
            else:
                normalized_updates[name] = value
        current.update(normalized_updates)
        current["native_parameters"] = native
        return type(self).from_mapping(current)

    def with_metadata(self, values: Optional[Mapping[str, Any]]) -> "SaltBridgeAdapterConfig":
        """Return a copy with merged execution metadata."""

        if not values:
            return self
        merged_metadata = dict(self.metadata)
        merged_metadata.update(copy.deepcopy(dict(values)))
        return replace(self, metadata=merged_metadata)

    def native_config(self, saltbridge_module: ModuleType) -> Any:
        """Build the specialized ``SaltBridgeConfig`` instance."""

        config_class = getattr(saltbridge_module, SALTBRIDGE_CONFIG_CLASS_NAME)
        return config_class(**dict(self.native_parameters))

    def direct_analysis_kwargs(self) -> Dict[str, Any]:
        """Return non-config arguments for direct source analysis."""

        return {
            "store_full_groups": self.store_full_groups,
            "include_invalid_statistics": self.include_invalid_statistics,
        }

    def attachment_kwargs(self) -> Dict[str, Any]:
        """Return arguments for specialized DockModel attachment."""

        return {
            "attribute_name": self.attribute_name,
            "preserve_existing": self.preserve_existing,
            "attach_result_object": self.attach_result_object,
            "attach_statistics": self.attach_statistics,
            "attach_summary": self.attach_summary,
        }

    def dock_model_kwargs(self) -> Dict[str, Any]:
        """Return arguments for native DockModel analysis."""

        return {
            "preserve_existing": self.preserve_existing,
            "attach_result_object": self.attach_result_object,
            "update_statistics": self.update_statistics,
            "update_score": self.update_score,
            "update_total_score": self.update_total_score,
            "total_score_mode": self.total_score_mode,
            "store_full_groups": self.store_full_groups,
            "include_invalid_statistics": self.include_invalid_statistics,
            "return_result": True,
        }

    def multipose_kwargs(self) -> Dict[str, Any]:
        """Return arguments for native multipose analysis."""

        return {
            "attach_to_dock_models": self.attach,
            "preserve_existing": self.preserve_existing,
            "store_full_groups": self.store_full_groups,
            "include_invalid_statistics": self.include_invalid_statistics,
            "persistence_mode": self.persistence_mode,
            "consensus_percentage": self.consensus_percentage,
            "minimum_consensus_poses": self.minimum_consensus_poses,
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible configuration mapping."""

        return {
            "native_parameters": to_json_compatible(dict(self.native_parameters)),
            "attach": self.attach,
            "attribute_name": self.attribute_name,
            "preserve_existing": self.preserve_existing,
            "attach_result_object": self.attach_result_object,
            "attach_statistics": self.attach_statistics,
            "attach_summary": self.attach_summary,
            "update_statistics": self.update_statistics,
            "update_score": self.update_score,
            "update_total_score": self.update_total_score,
            "total_score_mode": self.total_score_mode,
            "store_full_groups": self.store_full_groups,
            "include_invalid_statistics": self.include_invalid_statistics,
            "reuse_results": self.reuse_results,
            "persistence_mode": self.persistence_mode,
            "consensus_percentage": self.consensus_percentage,
            "minimum_consensus_poses": self.minimum_consensus_poses,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


def _normalize_saltbridge_native_value(name: str, value: Any) -> Any:
    """Normalize one specialized ``SaltBridgeConfig`` field."""

    boolean_fields = {
        "use_center_distance",
        "use_minimum_atom_distance",
        "calculate_all_contact_distances",
        "include_protein_groups",
        "include_ligand_groups",
        "include_nucleic_acid_groups",
        "recognize_canonical_residues",
        "recognize_formal_charges",
        "recognize_partial_charges",
        "infer_charge_from_chemistry",
        "allow_histidine_cations",
        "allow_terminal_groups",
        "allow_ambiguous_groups",
        "deduplicate_groups",
        "deduplicate_interactions",
        "scoring_enabled",
        "confidence_weighting",
        "charge_weighting",
        "preserve_invalid_candidates",
        "compact_results",
        "preserve_existing_results",
        "update_dockmodel_statistics",
        "update_dockmodel_score",
        "strict",
    }
    integer_fields = {"minimum_contact_count"}
    percentage_like_fields = {"minimum_recognition_confidence"}
    signed_fields = {
        "partial_charge_positive_threshold",
        "partial_charge_negative_threshold",
    }
    if name in boolean_fields:
        return _saltbridge_bool(value, field_name=f"saltbridge.{name}")
    if name in integer_fields:
        return _saltbridge_optional_int(
            value,
            field_name=f"saltbridge.{name}",
            minimum=0,
        )
    if name in percentage_like_fields:
        return _saltbridge_optional_float(
            value,
            field_name=f"saltbridge.{name}",
            minimum=0.0,
            maximum=1.0,
        )
    if name in signed_fields:
        return _saltbridge_optional_float(
            value,
            field_name=f"saltbridge.{name}",
        )
    return _saltbridge_optional_float(
        value,
        field_name=f"saltbridge.{name}",
        minimum=0.0,
    )


def _saltbridge_configuration_sources(config: AnalysisConfig) -> Tuple[Mapping[str, Any], ...]:
    """Return integrated salt-bridge configuration mappings by precedence."""

    sources: List[Mapping[str, Any]] = []
    module_config = config.module_config(SALTBRIDGE_MODULE_NAME, default=None)
    if isinstance(module_config, Mapping):
        sources.append(module_config)
    stage_config = config.stage_config(STAGE_SALTBRIDGE)
    if isinstance(stage_config.parameters, Mapping):
        sources.append(stage_config.parameters)
    return tuple(sources)


def resolve_saltbridge_adapter_config(
    config: Optional[AnalysisConfigLike] = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    strict: bool = True,
) -> SaltBridgeAdapterConfig:
    """Resolve the effective salt-bridge adapter configuration."""

    integrated = coerce_analysis_config(config)
    resolved = SaltBridgeAdapterConfig(
        attach=integrated.runtime.attach_results,
        preserve_existing=_saltbridge_runtime_preserve_existing(integrated),
        reuse_results=integrated.runtime.reuse_results,
    )
    for source in _saltbridge_configuration_sources(integrated):
        resolved = resolved.merged(source)
    if overrides:
        if strict:
            unknown = [
                str(name)
                for name in overrides
                if _normalize_saltbridge_parameter_name(name)
                not in SALTBRIDGE_ADAPTER_FIELDS
            ]
            if unknown:
                raise AnalysisConfigurationError(
                    "Unsupported salt-bridge overrides: " + ", ".join(unknown)
                )
        resolved = resolved.merged(overrides)
    if metadata:
        resolved = resolved.with_metadata(metadata)
    return resolved


# 15.3. Target, result and output dataclasses
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class SaltBridgeStageTarget:
    """Resolved source and identifiers for one salt-bridge analysis."""

    dock_model: Any
    source: Any
    pose_index: Optional[int]
    dock_model_identifier: str
    pose_identifier: str
    model_identifier: str

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return a serializable target description."""

        result = {
            "pose_index": self.pose_index,
            "dock_model_identifier": self.dock_model_identifier,
            "pose_identifier": self.pose_identifier,
            "model_identifier": self.model_identifier,
            "source": describe_object(self.source).to_dict(),
        }
        if include_objects:
            result["dock_model"] = self.dock_model
            result["source_object"] = self.source
        return result


@dataclass(frozen=True)
class SaltBridgeResultSummary:
    """Compact normalized summary of a native salt-bridge result."""

    dock_model_identifier: str
    pose_identifier: str
    model_identifier: str
    interaction_count: int = 0
    valid_interaction_count: int = 0
    rejected_interaction_count: int = 0
    cationic_group_count: int = 0
    anionic_group_count: int = 0
    atomic_contact_count: int = 0
    residue_count: int = 0
    cationic_residue_count: int = 0
    anionic_residue_count: int = 0
    intrachain_count: int = 0
    interchain_count: int = 0
    hotspot_count: int = 0
    total_score: float = 0.0
    mean_score: Optional[float] = None
    best_score: Optional[float] = None
    best_interaction_id: Optional[str] = None
    minimum_distance: Optional[float] = None
    mean_distance: Optional[float] = None
    maximum_distance: Optional[float] = None
    strength_counts: Mapping[str, int] = field(default_factory=dict)
    warning_count: int = 0

    def __post_init__(self) -> None:
        for name in (
            "interaction_count",
            "valid_interaction_count",
            "rejected_interaction_count",
            "cationic_group_count",
            "anionic_group_count",
            "atomic_contact_count",
            "residue_count",
            "cationic_residue_count",
            "anionic_residue_count",
            "intrachain_count",
            "interchain_count",
            "hotspot_count",
            "warning_count",
        ):
            object.__setattr__(self, name, max(0, int(getattr(self, name))))
        object.__setattr__(
            self,
            "strength_counts",
            MappingProxyType(
                {
                    str(key): max(0, int(value))
                    for key, value in dict(self.strength_counts).items()
                }
            ),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible summary mapping."""

        return to_json_compatible(
            {
                item.name: getattr(self, item.name)
                for item in fields(self)
            }
        )


@dataclass(frozen=True)
class SaltBridgeStageOutput:
    """Pipeline-level salt-bridge stage output."""

    result: Any
    summary: SaltBridgeResultSummary
    interactions: Tuple[Any, ...] = ()
    cationic_groups: Tuple[Any, ...] = ()
    anionic_groups: Tuple[Any, ...] = ()
    hotspots: Tuple[Any, ...] = ()
    groupings: Mapping[str, Any] = field(default_factory=dict)
    statistics: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    warnings: Tuple[str, ...] = ()
    attached: bool = False
    reused: bool = False
    module_name: str = SALTBRIDGE_MODULE_NAME
    module_version: Optional[str] = None
    result_type: str = SALTBRIDGE_RESULT_TYPE

    def __post_init__(self) -> None:
        object.__setattr__(self, "interactions", tuple(self.interactions))
        object.__setattr__(self, "cationic_groups", tuple(self.cationic_groups))
        object.__setattr__(self, "anionic_groups", tuple(self.anionic_groups))
        object.__setattr__(self, "hotspots", tuple(self.hotspots))
        object.__setattr__(self, "warnings", tuple(str(item) for item in self.warnings))
        object.__setattr__(
            self,
            "groupings",
            MappingProxyType(dict(self.groupings)),
        )
        object.__setattr__(
            self,
            "statistics",
            MappingProxyType(dict(self.statistics)),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(dict(self.metadata)),
        )

    @property
    def interaction_count(self) -> int:
        """Return the number of native interactions."""

        return len(self.interactions)

    @property
    def hotspot_count(self) -> int:
        """Return the number of residue hotspots."""

        return len(self.hotspots)

    @property
    def total_score(self) -> float:
        """Return the normalized total salt-bridge score."""

        return float(self.summary.total_score)

    def to_dict(self, *, include_result: bool = False) -> Dict[str, Any]:
        """Return a JSON-compatible output mapping."""

        result = {
            "result_type": self.result_type,
            "summary": self.summary.to_dict(),
            "interaction_count": self.interaction_count,
            "cationic_group_count": len(self.cationic_groups),
            "anionic_group_count": len(self.anionic_groups),
            "hotspot_count": self.hotspot_count,
            "grouping_names": sorted(str(name) for name in self.groupings),
            "statistics": to_json_compatible(dict(self.statistics)),
            "metadata": to_json_compatible(dict(self.metadata)),
            "warnings": list(self.warnings),
            "attached": self.attached,
            "reused": self.reused,
            "module_name": self.module_name,
            "module_version": self.module_version,
        }
        if include_result:
            result["result"] = to_json_compatible(self.result)
        return result


# 15.4. Module loading, target resolution and native result access
# -----------------------------------------------------------------------------


def _require_saltbridge_module(
    saltbridge_module: Optional[ModuleType] = None,
) -> ModuleType:
    """Return and validate the specialized salt-bridge module."""

    module = saltbridge_module or require_analysis_module(
        SALTBRIDGE_MODULE_NAME,
        load=True,
    )
    missing = tuple(
        name for name in SALTBRIDGE_REQUIRED_SYMBOLS if not hasattr(module, name)
    )
    if missing:
        raise AnalysisDependencyError(
            "The saltbridge module does not provide the required interface.",
            stage=STAGE_SALTBRIDGE,
            details={"missing_symbols": list(missing)},
        )
    return module


def _saltbridge_context_target(
    context: Optional[AnalysisContext],
    *,
    dock_model: Any,
    source: Any,
    pose_index: Optional[int],
) -> Tuple[Any, Any, Optional[int]]:
    """Fill missing salt-bridge target values from an analysis context."""

    if context is None:
        return dock_model, source, pose_index
    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance or None.")
    resolved_index = context.current_pose_index if pose_index is None else pose_index
    resolved_model = dock_model
    if resolved_model is None:
        if resolved_index is not None and 0 <= resolved_index < len(context.dock_models):
            resolved_model = context.dock_models[resolved_index]
        elif context.current_dock_model is not None:
            resolved_model = context.current_dock_model
        elif len(context.dock_models) == 1:
            resolved_model = context.dock_models[0]
    resolved_source = source
    if resolved_source is None and resolved_model is not None:
        resolved_source = get_object_value(
            resolved_model,
            "source",
            default=None,
            aliases=("ligand", "pose", "model", "structure"),
            skip_none=True,
        )
    if resolved_source is None:
        if resolved_index is not None and 0 <= resolved_index < len(context.poses):
            resolved_source = context.poses[resolved_index]
        elif context.current_pose is not None:
            resolved_source = context.current_pose
        elif len(context.poses) == 1:
            resolved_source = context.poses[0]
    return resolved_model, resolved_source, resolved_index


def _saltbridge_identifier(value: Any, *, default: str) -> str:
    """Return a stable normalized identifier for an arbitrary object."""

    candidate = get_object_value(
        value,
        "name",
        default=None,
        aliases=("identifier", "id", "id_string", "model_id", "pose_id"),
        skip_none=True,
    )
    if candidate is None:
        candidate = describe_object(value).identifier
    return normalize_identifier(
        candidate,
        default=default,
        maximum_length=MAX_SALTBRIDGE_ADAPTER_IDENTIFIER_LENGTH,
    )


def resolve_saltbridge_stage_target(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    source: Any = None,
    pose_index: Optional[int] = None,
    saltbridge_module: Optional[ModuleType] = None,
) -> SaltBridgeStageTarget:
    """Resolve one prepared DockModel and salt-bridge analysis source."""

    module = _require_saltbridge_module(saltbridge_module)
    dock_model, source, pose_index = _saltbridge_context_target(
        context,
        dock_model=dock_model,
        source=source,
        pose_index=pose_index,
    )
    if dock_model is None:
        raise AnalysisInputError(
            "Salt-bridge analysis requires a prepared DockModel.",
            stage=STAGE_SALTBRIDGE,
        )
    if source is None:
        try:
            source = module.resolve_dock_model_source(dock_model)
        except Exception:
            source = None
    if source is None:
        raise AnalysisInputError(
            "Salt-bridge analysis could not resolve a molecular source.",
            stage=STAGE_SALTBRIDGE,
        )
    normalized_index = None if pose_index is None else int(pose_index)
    if normalized_index is not None and normalized_index < 0:
        raise AnalysisInputError(
            "Salt-bridge pose_index cannot be negative.",
            stage=STAGE_SALTBRIDGE,
        )
    dock_identifier = _saltbridge_identifier(dock_model, default="dock_model")
    try:
        native_pose = module.resolve_dock_model_pose_id(dock_model, pose_id=None)
    except Exception:
        native_pose = None
    try:
        native_model = module.resolve_dock_model_model_id(dock_model, model_id=None)
    except Exception:
        native_model = None
    if native_pose is None and normalized_index is not None:
        native_pose = f"pose_{normalized_index + 1}"
    pose_identifier = normalize_identifier(
        native_pose,
        default="pose",
        maximum_length=MAX_SALTBRIDGE_ADAPTER_IDENTIFIER_LENGTH,
    )
    model_identifier = normalize_identifier(
        native_model,
        default=dock_identifier,
        maximum_length=MAX_SALTBRIDGE_ADAPTER_IDENTIFIER_LENGTH,
    )
    return SaltBridgeStageTarget(
        dock_model=dock_model,
        source=source,
        pose_index=normalized_index,
        dock_model_identifier=dock_identifier,
        pose_identifier=pose_identifier,
        model_identifier=model_identifier,
    )


def is_saltbridge_result(
    value: Any,
    *,
    saltbridge_module: Optional[ModuleType] = None,
) -> bool:
    """Return whether a value is a native or structurally compatible result."""

    if value is None:
        return False
    if saltbridge_module is not None:
        result_class = getattr(
            saltbridge_module,
            SALTBRIDGE_RESULT_CLASS_NAME,
            None,
        )
        if isinstance(result_class, type) and isinstance(value, result_class):
            return True
    return all(hasattr(value, name) for name in SALTBRIDGE_RESULT_REQUIRED_ATTRIBUTES)


def saltbridge_result_interactions(value: Any) -> Tuple[Any, ...]:
    """Return native salt-bridge interactions."""

    return tuple(
        normalize_object_sequence(
            get_object_value(value, "interactions", default=(), skip_none=True)
        )
    )


def saltbridge_result_cationic_groups(value: Any) -> Tuple[Any, ...]:
    """Return recognized cationic groups from a native result."""

    return tuple(
        normalize_object_sequence(
            get_object_value(value, "cationic_groups", default=(), skip_none=True)
        )
    )


def saltbridge_result_anionic_groups(value: Any) -> Tuple[Any, ...]:
    """Return recognized anionic groups from a native result."""

    return tuple(
        normalize_object_sequence(
            get_object_value(value, "anionic_groups", default=(), skip_none=True)
        )
    )


def _saltbridge_object_to_mapping(value: Any) -> Dict[str, Any]:
    """Convert a statistics-like object to a plain mapping."""

    if value is None:
        return {}
    if isinstance(value, Mapping):
        return dict(value)
    to_dict_method = getattr(value, "to_dict", None)
    if callable(to_dict_method):
        converted = to_dict_method()
        if isinstance(converted, Mapping):
            return dict(converted)
    if is_dataclass(value) and not isinstance(value, type):
        return {item.name: getattr(value, item.name) for item in fields(value)}
    if hasattr(value, "__dict__"):
        return {
            str(name): item
            for name, item in vars(value).items()
            if not str(name).startswith("_")
        }
    return {}


def saltbridge_result_statistics(value: Any) -> Dict[str, Any]:
    """Return normalized native salt-bridge statistics."""

    raw = get_object_value(value, "statistics", default={}, skip_none=True)
    return normalize_statistics_mapping(_saltbridge_object_to_mapping(raw))


def saltbridge_result_metadata(value: Any) -> Dict[str, Any]:
    """Return normalized native salt-bridge metadata."""

    raw = get_object_value(value, "metadata", default={}, skip_none=True)
    return normalize_metadata_mapping(_saltbridge_object_to_mapping(raw))


def saltbridge_result_warnings(value: Any) -> Tuple[str, ...]:
    """Return native warning messages."""

    raw = get_object_value(value, "warnings", default=(), skip_none=True)
    return tuple(str(item) for item in normalize_object_sequence(raw))


def _saltbridge_interaction_is_valid(interaction: Any) -> bool:
    """Return whether a native interaction has valid geometry."""

    geometry = get_object_value(interaction, "geometry", default=None, skip_none=True)
    valid = get_object_value(geometry, "valid", default=None, skip_none=True)
    if valid is not None:
        return bool(valid)
    strength = normalize_identifier(
        get_object_value(interaction, "strength", default="unknown"),
        default="unknown",
        maximum_length=64,
    )
    return strength != "rejected"


def _saltbridge_interaction_score(interaction: Any) -> float:
    """Return one finite interaction score."""

    value = get_object_value(interaction, "score", default=0.0, skip_none=True)
    try:
        score = float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0
    return score if math.isfinite(score) else 0.0


def _saltbridge_interaction_distance(interaction: Any) -> Optional[float]:
    """Return the preferred native interaction distance."""

    geometry = get_object_value(interaction, "geometry", default=None, skip_none=True)
    for name in ("minimum_atom_distance", "center_distance", "mean_atom_distance"):
        value = get_object_value(geometry, name, default=None, skip_none=True)
        if value is None:
            continue
        try:
            converted = float(value)
        except (TypeError, ValueError, OverflowError):
            continue
        if math.isfinite(converted):
            return converted
    return None


# 15.5. Native result validation, summary and adaptation
# -----------------------------------------------------------------------------


def validate_saltbridge_result(
    value: Any,
    *,
    saltbridge_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one native salt-bridge result structurally."""

    errors: List[str] = []
    if not is_saltbridge_result(value, saltbridge_module=saltbridge_module):
        errors.append("The value is not a compatible salt-bridge result.")
    else:
        interactions = saltbridge_result_interactions(value)
        if len(interactions) > MAX_SALTBRIDGE_ADAPTER_INTERACTIONS:
            errors.append("The salt-bridge result exceeds the interaction limit.")
        for index, interaction in enumerate(interactions):
            if get_object_value(interaction, "cation", default=None) is None:
                errors.append(f"Interaction {index} has no cationic group.")
            if get_object_value(interaction, "anion", default=None) is None:
                errors.append(f"Interaction {index} has no anionic group.")
            if get_object_value(interaction, "geometry", default=None) is None:
                errors.append(f"Interaction {index} has no geometry.")
            score = _saltbridge_interaction_score(interaction)
            if not math.isfinite(score):
                errors.append(f"Interaction {index} has a non-finite score.")
    result = tuple(errors)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Salt-bridge result validation failed.",
            stage=STAGE_SALTBRIDGE,
            details={"errors": list(result)},
        )
    return result


def _saltbridge_native_summary(
    value: Any,
    *,
    saltbridge_module: ModuleType,
) -> Dict[str, Any]:
    """Return the specialized compact summary when available."""

    try:
        summary = getattr(saltbridge_module, SALTBRIDGE_SUMMARY_FUNCTION)(value)
    except Exception:
        summary = {}
    return _saltbridge_object_to_mapping(summary)


def _saltbridge_count_mapping(value: Any) -> Dict[str, int]:
    """Normalize a count mapping."""

    if not isinstance(value, Mapping):
        return {}
    result: Dict[str, int] = {}
    for key, count in value.items():
        if isinstance(count, Real) and not isinstance(count, bool):
            result[str(key)] = max(0, int(count))
    return result


def summarize_saltbridge_result(
    value: Any,
    *,
    target: Optional[SaltBridgeStageTarget] = None,
    saltbridge_module: Optional[ModuleType] = None,
) -> SaltBridgeResultSummary:
    """Build a compact orchestration summary from a native result."""

    module = _require_saltbridge_module(saltbridge_module)
    validate_saltbridge_result(value, saltbridge_module=module, raise_on_error=True)
    native = _saltbridge_native_summary(value, saltbridge_module=module)
    interactions = saltbridge_result_interactions(value)
    valid_count = sum(1 for item in interactions if _saltbridge_interaction_is_valid(item))
    rejected_count = len(interactions) - valid_count
    strength_counts: Counter[str] = Counter()
    distances: List[float] = []
    scores: List[float] = []
    atomic_contacts = 0
    for interaction in interactions:
        strength = normalize_identifier(
            get_object_value(interaction, "strength", default="unknown"),
            default="unknown",
            maximum_length=64,
        )
        strength_counts[strength] += 1
        distance = _saltbridge_interaction_distance(interaction)
        if distance is not None:
            distances.append(distance)
        scores.append(_saltbridge_interaction_score(interaction))
        geometry = get_object_value(interaction, "geometry", default=None)
        count = get_object_value(geometry, "contact_count", default=0)
        if isinstance(count, Real) and not isinstance(count, bool):
            atomic_contacts += max(0, int(count))
    statistics = saltbridge_result_statistics(value)
    pose_identifier = (
        target.pose_identifier
        if target is not None
        else normalize_identifier(
            get_object_value(value, "pose_id", default=None),
            default="pose",
            maximum_length=MAX_SALTBRIDGE_ADAPTER_IDENTIFIER_LENGTH,
        )
    )
    model_identifier = (
        target.model_identifier
        if target is not None
        else normalize_identifier(
            get_object_value(value, "model_id", default=None),
            default="model",
            maximum_length=MAX_SALTBRIDGE_ADAPTER_IDENTIFIER_LENGTH,
        )
    )
    dock_identifier = (
        target.dock_model_identifier if target is not None else model_identifier
    )
    native_strengths = _saltbridge_count_mapping(
        native.get("strength_counts", statistics.get("strength_counts", {}))
    )
    if native_strengths:
        strength_counts = Counter(native_strengths)
    total_score = native.get("total_score", sum(scores))
    mean_score = native.get(
        "mean_score",
        (sum(scores) / len(scores)) if scores else None,
    )
    best_score = native.get("best_score", max(scores) if scores else None)
    minimum_distance = native.get(
        "minimum_distance",
        min(distances) if distances else None,
    )
    mean_distance = native.get(
        "mean_distance",
        (sum(distances) / len(distances)) if distances else None,
    )
    maximum_distance = native.get(
        "maximum_distance",
        max(distances) if distances else None,
    )
    return SaltBridgeResultSummary(
        dock_model_identifier=dock_identifier,
        pose_identifier=pose_identifier,
        model_identifier=model_identifier,
        interaction_count=int(native.get("interaction_count", len(interactions))),
        valid_interaction_count=valid_count,
        rejected_interaction_count=int(
            native.get("rejected_candidate_count", rejected_count)
        ),
        cationic_group_count=len(saltbridge_result_cationic_groups(value)),
        anionic_group_count=len(saltbridge_result_anionic_groups(value)),
        atomic_contact_count=int(native.get("atomic_contact_count", atomic_contacts)),
        residue_count=int(native.get("residue_count", 0)),
        cationic_residue_count=int(native.get("cationic_residue_count", 0)),
        anionic_residue_count=int(native.get("anionic_residue_count", 0)),
        intrachain_count=int(native.get("intrachain_count", 0)),
        interchain_count=int(native.get("interchain_count", 0)),
        hotspot_count=int(native.get("hotspot_count", 0)),
        total_score=float(total_score or 0.0),
        mean_score=(None if mean_score is None else float(mean_score)),
        best_score=(None if best_score is None else float(best_score)),
        best_interaction_id=(
            None
            if native.get("best_interaction_id") is None
            else str(native.get("best_interaction_id"))
        ),
        minimum_distance=(
            None if minimum_distance is None else float(minimum_distance)
        ),
        mean_distance=(None if mean_distance is None else float(mean_distance)),
        maximum_distance=(
            None if maximum_distance is None else float(maximum_distance)
        ),
        strength_counts=dict(strength_counts),
        warning_count=len(saltbridge_result_warnings(value)),
    )


def adapt_saltbridge_result(
    value: Any,
    *,
    target: Optional[SaltBridgeStageTarget] = None,
    attached: bool = False,
    reused: bool = False,
    saltbridge_module: Optional[ModuleType] = None,
) -> SaltBridgeStageOutput:
    """Adapt a native salt-bridge result to the common pipeline output."""

    module = _require_saltbridge_module(saltbridge_module)
    validate_saltbridge_result(value, saltbridge_module=module, raise_on_error=True)
    try:
        hotspots = tuple(getattr(module, SALTBRIDGE_HOTSPOTS_FUNCTION)(value))
    except Exception:
        hotspots = ()
    try:
        groupings = dict(getattr(module, SALTBRIDGE_GROUPINGS_FUNCTION)(value))
    except Exception:
        groupings = {}
    return SaltBridgeStageOutput(
        result=value,
        summary=summarize_saltbridge_result(
            value,
            target=target,
            saltbridge_module=module,
        ),
        interactions=saltbridge_result_interactions(value),
        cationic_groups=saltbridge_result_cationic_groups(value),
        anionic_groups=saltbridge_result_anionic_groups(value),
        hotspots=hotspots,
        groupings=groupings,
        statistics=saltbridge_result_statistics(value),
        metadata=saltbridge_result_metadata(value),
        warnings=saltbridge_result_warnings(value),
        attached=attached,
        reused=reused,
        module_name=getattr(module, "__name__", SALTBRIDGE_MODULE_NAME),
        module_version=get_module_version(module),
    )


def validate_saltbridge_stage_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one adapted salt-bridge stage output."""

    errors: List[str] = []
    if not isinstance(value, SaltBridgeStageOutput):
        errors.append("The value is not a SaltBridgeStageOutput.")
    else:
        errors.extend(validate_saltbridge_result(value.result))
        if value.summary.interaction_count != len(value.interactions):
            errors.append("The salt-bridge summary interaction count is inconsistent.")
        if value.summary.cationic_group_count != len(value.cationic_groups):
            errors.append("The cationic-group count is inconsistent.")
        if value.summary.anionic_group_count != len(value.anionic_groups):
            errors.append("The anionic-group count is inconsistent.")
        if value.summary.hotspot_count != len(value.hotspots):
            errors.append("The hotspot count is inconsistent.")
    result = tuple(errors)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Salt-bridge stage output validation failed.",
            stage=STAGE_SALTBRIDGE,
            details={"errors": list(result)},
        )
    return result


# 15.6. Execution, reuse and context integration
# -----------------------------------------------------------------------------


def get_reusable_saltbridge_result(
    target: SaltBridgeStageTarget,
    *,
    saltbridge_module: Optional[ModuleType] = None,
) -> Optional[Any]:
    """Return a stored live salt-bridge result when available."""

    module = _require_saltbridge_module(saltbridge_module)
    try:
        result = getattr(module, SALTBRIDGE_GET_RESULT_FUNCTION)(target.dock_model)
    except Exception:
        result = None
    if is_saltbridge_result(result, saltbridge_module=module):
        return result
    return None


def _saltbridge_execution_metadata(
    context: Optional[AnalysisContext],
    target: SaltBridgeStageTarget,
    config: SaltBridgeAdapterConfig,
) -> Dict[str, Any]:
    """Build execution metadata for a specialized result."""

    metadata = dict(config.metadata)
    metadata.update(
        {
            "adapter_schema": SALTBRIDGE_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": SALTBRIDGE_ADAPTER_SCHEMA_VERSION,
            "dock_model_identifier": target.dock_model_identifier,
            "pose_identifier": target.pose_identifier,
            "model_identifier": target.model_identifier,
        }
    )
    if context is not None:
        metadata.update(
            {
                "run_id": context.run_id,
                "request_id": context.request.request_id,
            }
        )
    return metadata


def _store_saltbridge_metadata(
    result: Any,
    metadata: Mapping[str, Any],
) -> None:
    """Merge adapter metadata into a mutable native result when possible."""

    current = get_object_value(result, "metadata", default=None)
    if isinstance(current, MutableMapping):
        current.update(copy.deepcopy(dict(metadata)))
        return
    try:
        setattr(result, "metadata", copy.deepcopy(dict(metadata)))
    except Exception:
        return


def run_saltbridge_analysis_adapter(
    target: SaltBridgeStageTarget,
    config: SaltBridgeAdapterConfig,
    *,
    context: Optional[AnalysisContext] = None,
    reuse_result: bool = False,
    saltbridge_module: Optional[ModuleType] = None,
) -> SaltBridgeStageOutput:
    """Run or reuse one salt-bridge analysis and adapt its result."""

    module = _require_saltbridge_module(saltbridge_module)
    effective_reuse = bool(reuse_result)
    if effective_reuse:
        reusable = get_reusable_saltbridge_result(
            target,
            saltbridge_module=module,
        )
        if reusable is not None:
            return adapt_saltbridge_result(
                reusable,
                target=target,
                attached=True,
                reused=True,
                saltbridge_module=module,
            )
    native_config = config.native_config(module)
    analyzer = getattr(module, SALTBRIDGE_DIRECT_ANALYSIS_FUNCTION)
    warnings: List[str] = []
    result = analyzer(
        target.source,
        native_config,
        pose_id=target.pose_identifier,
        model_id=target.model_identifier,
        warnings=warnings,
        **config.direct_analysis_kwargs(),
    )
    metadata = _saltbridge_execution_metadata(context, target, config)
    _store_saltbridge_metadata(result, metadata)
    attached = False
    if config.attach:
        getattr(module, SALTBRIDGE_ATTACHMENT_FUNCTION)(
            target.dock_model,
            result,
            native_config,
            **config.attachment_kwargs(),
        )
        if config.update_statistics:
            updater = getattr(module, "update_dock_model_statistics", None)
            if callable(updater):
                updater(target.dock_model, result, native_config)
        if config.update_score:
            updater = getattr(module, "update_dock_model_salt_bridge_score", None)
            if callable(updater):
                updater(
                    target.dock_model,
                    result,
                    update_total_score=config.update_total_score,
                    total_score_mode=config.total_score_mode,
                )
        attached = True
    return adapt_saltbridge_result(
        result,
        target=target,
        attached=attached,
        reused=False,
        saltbridge_module=module,
    )


def _saltbridge_stage_failure_should_raise(
    context: Optional[AnalysisContext],
    raise_on_error: Optional[bool],
) -> bool:
    """Resolve whether salt-bridge adapter failures should be raised."""

    return _stage_failure_should_raise(context, raise_on_error)


def _record_saltbridge_stage_context(
    context: AnalysisContext,
    stage_result: AnalysisStageResult,
) -> None:
    """Store salt-bridge output and statistics in the runtime context."""

    context.set_stage_data(SALTBRIDGE_STAGE_DATA_KEY, stage_result)
    if isinstance(stage_result.value, SaltBridgeStageOutput):
        output = stage_result.value
        context.statistics[SALTBRIDGE_STAGE_STATISTICS_KEY] = (
            output.summary.to_dict()
        )
        context.metadata[SALTBRIDGE_STAGE_METADATA_KEY] = {
            "dock_model_identifier": output.summary.dock_model_identifier,
            "pose_identifier": output.summary.pose_identifier,
            "model_identifier": output.summary.model_identifier,
            "module_version": output.module_version,
            "reused": output.reused,
            "attached": output.attached,
            "hotspot_count": output.hotspot_count,
        }


def execute_saltbridge_stage(
    context: Optional[AnalysisContext] = None,
    *,
    dock_model: Any = None,
    source: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    saltbridge_module: Optional[ModuleType] = None,
    raise_on_error: Optional[bool] = None,
) -> AnalysisStageResult:
    """Execute the registered salt-bridge pipeline stage."""

    integrated_config = (
        context.config
        if context is not None and config is None
        else coerce_analysis_config(config)
    )
    stage_config = integrated_config.stage_config(STAGE_SALTBRIDGE)
    stage_result = AnalysisStageResult(
        stage=STAGE_SALTBRIDGE,
        required=stage_config.required,
    )
    if not stage_config.enabled:
        stage_result.skip("Salt-bridge analysis is disabled by configuration.")
        if context is not None:
            _record_saltbridge_stage_context(context, stage_result)
        return stage_result
    stage_result.start()
    try:
        if context is not None:
            context.raise_if_cancelled(stage=STAGE_SALTBRIDGE)
            context.set_current_stage(STAGE_SALTBRIDGE)
        module = _require_saltbridge_module(saltbridge_module)
        target = resolve_saltbridge_stage_target(
            context,
            dock_model=dock_model,
            source=source,
            pose_index=pose_index,
            saltbridge_module=module,
        )
        adapter_config = resolve_saltbridge_adapter_config(
            integrated_config,
            overrides=overrides,
            metadata={
                "dock_model_identifier": target.dock_model_identifier,
                "pose_identifier": target.pose_identifier,
                "model_identifier": target.model_identifier,
            },
        )
        stage_result.input_summary = target.to_dict(include_objects=False)
        stage_result.metadata.update(
            {
                "adapter_schema": SALTBRIDGE_ADAPTER_SCHEMA_NAME,
                "adapter_schema_version": SALTBRIDGE_ADAPTER_SCHEMA_VERSION,
                "module_name": getattr(module, "__name__", SALTBRIDGE_MODULE_NAME),
                "module_version": get_module_version(module),
                "configuration": adapter_config.to_dict(),
            }
        )
        output = run_saltbridge_analysis_adapter(
            target,
            adapter_config,
            context=context,
            reuse_result=stage_config.reuse_result,
            saltbridge_module=module,
        )
        if stage_config.validate_result:
            validate_saltbridge_stage_output(output, raise_on_error=True)
        stage_result.cached = output.reused
        stage_result.statistics = dict(output.statistics)
        stage_result.output_summary = output.summary.to_dict()
        stage_result.succeed(
            output,
            message=(
                "Reused a stored live salt-bridge analysis."
                if output.reused
                else "Salt-bridge analysis completed successfully."
            ),
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisStageError(
                "Salt-bridge analysis failed.",
                stage=STAGE_SALTBRIDGE,
                cause=exc,
                details={"exception_type": type(exc).__name__},
            )
        stage_result.fail(
            wrapped,
            include_traceback=(
                context is not None and context.config.runtime.collect_diagnostics
            ),
        )
        if _saltbridge_stage_failure_should_raise(context, raise_on_error):
            raise wrapped from exc
    finally:
        if context is not None:
            _record_saltbridge_stage_context(context, stage_result)
            context.set_current_stage(None)
    return stage_result


# 15.7. Convenience and native multipose interfaces
# -----------------------------------------------------------------------------


def analyze_dock_model_saltbridge_interactions(
    dock_model: Any,
    *,
    source: Any = None,
    pose_index: Optional[int] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    saltbridge_module: Optional[ModuleType] = None,
) -> SaltBridgeStageOutput:
    """Analyze salt bridges for one prepared DockModel."""

    stage_result = execute_saltbridge_stage(
        None,
        dock_model=dock_model,
        source=source,
        pose_index=pose_index,
        config=config,
        overrides=overrides,
        saltbridge_module=saltbridge_module,
        raise_on_error=True,
    )
    if not isinstance(stage_result.value, SaltBridgeStageOutput):
        raise AnalysisIntegrationError(
            "The salt-bridge stage did not produce a SaltBridgeStageOutput.",
            stage=STAGE_SALTBRIDGE,
        )
    return stage_result.value


def analyze_prepared_dock_models_saltbridges(
    dock_models: Iterable[Any],
    *,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    saltbridge_module: Optional[ModuleType] = None,
    continue_on_error: bool = False,
) -> Tuple[AnalysisStageResult, ...]:
    """Run the salt-bridge adapter for prepared DockModel objects."""

    models = tuple(normalize_object_sequence(dock_models))
    if not models:
        return ()
    module = _require_saltbridge_module(saltbridge_module)
    results: List[AnalysisStageResult] = []
    for index, model in enumerate(models):
        try:
            result = execute_saltbridge_stage(
                None,
                dock_model=model,
                pose_index=index,
                config=config,
                overrides=overrides,
                saltbridge_module=module,
                raise_on_error=not continue_on_error,
            )
        except Exception as exc:
            if not continue_on_error:
                raise
            result = AnalysisStageResult(stage=STAGE_SALTBRIDGE)
            result.start().fail(exc)
        results.append(result)
    return tuple(results)


def analyze_multiple_dock_models_saltbridges_native(
    dock_models: Iterable[Any],
    *,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    saltbridge_module: Optional[ModuleType] = None,
    continue_on_error: bool = True,
    return_results: bool = True,
) -> Any:
    """Run the specialized multi-DockModel salt-bridge interface."""

    module = _require_saltbridge_module(saltbridge_module)
    adapter_config = resolve_saltbridge_adapter_config(config, overrides=overrides)
    models = tuple(normalize_object_sequence(dock_models))
    native_config = adapter_config.native_config(module)
    analyzer = getattr(module, SALTBRIDGE_MULTIMODEL_FUNCTION)
    return analyzer(
        models,
        native_config,
        preserve_existing=adapter_config.preserve_existing,
        attach_result_object=adapter_config.attach_result_object,
        update_statistics=adapter_config.update_statistics,
        update_score=adapter_config.update_score,
        update_total_score=adapter_config.update_total_score,
        total_score_mode=adapter_config.total_score_mode,
        store_full_groups=adapter_config.store_full_groups,
        include_invalid_statistics=adapter_config.include_invalid_statistics,
        continue_on_error=continue_on_error,
        return_results=return_results,
    )


def analyze_saltbridges_multipose_native(
    poses: Iterable[Any],
    *,
    pose_ids: Optional[Any] = None,
    model_ids: Optional[Any] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    saltbridge_module: Optional[ModuleType] = None,
    continue_on_error: bool = True,
) -> Mapping[str, Any]:
    """Run the native multipose persistence and consensus pipeline."""

    module = _require_saltbridge_module(saltbridge_module)
    adapter_config = resolve_saltbridge_adapter_config(config, overrides=overrides)
    analyzer = getattr(module, SALTBRIDGE_MULTIPOSE_FUNCTION)
    result = analyzer(
        tuple(normalize_object_sequence(poses)),
        adapter_config.native_config(module),
        pose_ids=pose_ids,
        model_ids=model_ids,
        continue_on_error=continue_on_error,
        **adapter_config.multipose_kwargs(),
    )
    if not isinstance(result, Mapping):
        raise AnalysisIntegrationError(
            "The native salt-bridge multipose interface returned an invalid value.",
            stage=STAGE_SALTBRIDGE,
        )
    return result


# 15.8. Stage registry integration and summaries
# -----------------------------------------------------------------------------


def saltbridge_stage_result_adapter(value: Any, **kwargs: Any) -> SaltBridgeStageOutput:
    """Registry-compatible adapter for specialized salt-bridge results."""

    return adapt_saltbridge_result(value, **kwargs)


def saltbridge_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible validator for salt-bridge stage values."""

    if isinstance(value, AnalysisStageResult):
        if value.value is None:
            return () if value.status == StageStatus.SKIPPED else (
                "Salt-bridge stage result does not contain a value.",
            )
        value = value.value
    if isinstance(value, SaltBridgeStageOutput):
        return validate_saltbridge_stage_output(value)
    return validate_saltbridge_result(value)


def register_saltbridge_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the salt-bridge executor, adapter and validator."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_SALTBRIDGE)
    metadata = dict(definition.metadata)
    metadata.update(
        {
            "adapter_schema": SALTBRIDGE_ADAPTER_SCHEMA_NAME,
            "adapter_schema_version": SALTBRIDGE_ADAPTER_SCHEMA_VERSION,
            "analysis_function": SALTBRIDGE_DOCK_MODEL_ANALYSIS_FUNCTION,
            "multipose_function": SALTBRIDGE_MULTIPOSE_FUNCTION,
            "result_type": SALTBRIDGE_RESULT_TYPE,
            "supports_hotspots": True,
            "supports_persistence": True,
            "supports_consensus": True,
        }
    )
    updated = replace(
        definition,
        executor=execute_saltbridge_stage,
        result_adapter=saltbridge_stage_result_adapter,
        validator=saltbridge_stage_validator,
        metadata=metadata,
    )
    target_registry.replace(updated)
    return updated


def saltbridge_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the salt-bridge stage adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_SALTBRIDGE)
    return bool(
        definition is not None
        and definition.executor is execute_saltbridge_stage
        and definition.result_adapter is saltbridge_stage_result_adapter
        and definition.validator is saltbridge_stage_validator
    )


def summarize_saltbridge_stage_result(value: Any) -> Dict[str, Any]:
    """Return a compact summary for stage or adapter output."""

    if isinstance(value, AnalysisStageResult):
        result: Dict[str, Any] = {
            "stage": value.stage,
            "status": value.status.value,
            "cached": value.cached,
            "duration_seconds": value.duration_seconds,
        }
        if isinstance(value.value, SaltBridgeStageOutput):
            result.update(value.value.summary.to_dict())
        return result
    if isinstance(value, SaltBridgeStageOutput):
        result = value.summary.to_dict()
        result.update(
            {
                "attached": value.attached,
                "reused": value.reused,
                "module_version": value.module_version,
            }
        )
        return result
    if is_saltbridge_result(value):
        return summarize_saltbridge_result(value).to_dict()
    raise TypeError(
        "value must be an AnalysisStageResult, SaltBridgeStageOutput or "
        "salt-bridge result."
    )


# 15.9. Convention validation and public interface
# -----------------------------------------------------------------------------


def validate_saltbridge_adapter_conventions() -> Dict[str, Any]:
    """Validate salt-bridge adapter constants, data and registration."""

    failures: List[str] = []
    if canonicalize_saltbridge_total_score_mode("sum") != "add":
        failures.append("Salt-bridge total-score alias resolution failed.")
    if canonicalize_saltbridge_persistence_mode("residues") != "residue_pair":
        failures.append("Salt-bridge persistence alias resolution failed.")
    config = SaltBridgeAdapterConfig.from_mapping(
        {
            "max_distance": 4.2,
            "strong_cutoff": 3.1,
            "min_contacts": 1,
            "formal_charges": True,
            "store": True,
            "preserve": False,
            "score_mode": "sum",
            "persistence": "residues",
            "consensus": 60.0,
        }
    )
    if config.native_parameters.get("distance_cutoff") != 4.2:
        failures.append("Salt-bridge distance alias was not preserved.")
    if config.preserve_existing:
        failures.append("Salt-bridge preserve alias was not applied.")
    if config.total_score_mode != "add" or config.consensus_percentage != 60.0:
        failures.append("Salt-bridge control parameters were not preserved.")

    @dataclass
    class FakeGeometry:
        minimum_atom_distance: float = 3.0
        center_distance: float = 3.1
        mean_atom_distance: float = 3.05
        contact_count: int = 2
        valid: bool = True

    @dataclass
    class FakeInteraction:
        cation: Any = field(default_factory=object)
        anion: Any = field(default_factory=object)
        geometry: Any = field(default_factory=FakeGeometry)
        strength: str = "strong"
        score: float = 1.0
        interaction_id: str = "salt_bridge_1"

    @dataclass
    class FakeResult:
        interactions: List[Any] = field(default_factory=lambda: [FakeInteraction()])
        cationic_groups: List[Any] = field(default_factory=lambda: [object()])
        anionic_groups: List[Any] = field(default_factory=lambda: [object()])
        statistics: Dict[str, Any] = field(default_factory=dict)
        warnings: List[str] = field(default_factory=list)
        pose_id: str = "pose_1"
        model_id: str = "model_1"
        metadata: Dict[str, Any] = field(default_factory=dict)

    class FakeConfig:
        def __init__(self, **values: Any) -> None:
            self.distance_cutoff = float(values.get("distance_cutoff", 4.0))
            self.strict = bool(values.get("strict", False))
            for name, value in values.items():
                setattr(self, name, value)

    class FakeSaltBridgeModule(ModuleType):
        pass

    fake_module = FakeSaltBridgeModule("saltbridge")
    fake_module.__version__ = "test"
    fake_module.SaltBridgeConfig = FakeConfig
    fake_module.SaltBridgeResult = FakeResult
    fake_module.SaltBridgeInteraction = FakeInteraction
    fake_module.analyze_salt_bridges_with_statistics = (
        lambda *args, **kwargs: FakeResult(
            pose_id=str(kwargs.get("pose_id", "pose_1")),
            model_id=str(kwargs.get("model_id", "model_1")),
            statistics={
                "interaction_count": 1,
                "total_score": 1.0,
                "strength_counts": {"strong": 1},
            },
        )
    )
    fake_module.analyze_dock_model_salt_bridges = lambda *args, **kwargs: FakeResult()
    fake_module.analyze_multiple_dock_models_salt_bridges = (
        lambda models, *args, **kwargs: [FakeResult() for _ in models]
    )
    fake_module.analyze_salt_bridges_multipose = lambda *args, **kwargs: {
        "results": [FakeResult()],
        "consensus": [],
    }
    fake_module.attach_salt_bridge_results = (
        lambda model, result, *args, **kwargs: setattr(
            model,
            kwargs.get("attribute_name", "saltbridge"),
            list(result.interactions),
        ) or model
    )
    fake_module.get_dock_model_salt_bridges = lambda model, **kwargs: list(
        getattr(model, "saltbridge", [])
    )
    fake_module.get_dock_model_salt_bridge_result = lambda model: getattr(
        model,
        "saltbridge_result",
        None,
    )
    fake_module.clear_dock_model_salt_bridges = lambda model, **kwargs: model
    fake_module.build_compact_salt_bridge_summary = lambda result, *args: {
        "interaction_count": len(result.interactions),
        "rejected_candidate_count": 0,
        "atomic_contact_count": 2,
        "total_score": 1.0,
        "mean_score": 1.0,
        "best_score": 1.0,
        "best_interaction_id": "salt_bridge_1",
        "minimum_distance": 3.0,
        "mean_distance": 3.0,
        "maximum_distance": 3.0,
        "strong_count": 1,
        "moderate_count": 0,
        "weak_count": 0,
        "residue_count": 2,
        "cationic_residue_count": 1,
        "anionic_residue_count": 1,
        "intrachain_count": 0,
        "interchain_count": 1,
        "hotspot_count": 0,
        "pose_id": result.pose_id,
        "model_id": result.model_id,
    }
    fake_module.build_salt_bridge_text_summary = lambda result, *args: "summary"
    fake_module.calculate_salt_bridge_result_statistics = lambda result, *args, **kwargs: result
    fake_module.get_result_hotspots = lambda result: []
    fake_module.get_result_groupings = lambda result: {"residue_pairs": {}}
    fake_module.resolve_dock_model_source = lambda model: model.source
    fake_module.resolve_dock_model_pose_id = lambda model, default=None: getattr(
        model,
        "pose_id",
        default,
    )
    fake_module.resolve_dock_model_model_id = lambda model, default=None: getattr(
        model,
        "model_id",
        default,
    )

    source = SimpleNamespace(name="source")
    dock_model = SimpleNamespace(
        name="dock_1",
        source=source,
        pose_id="pose_1",
        model_id="model_1",
        saltbridge=[],
        statistics={},
        metadata={},
        score=0.0,
    )
    target = resolve_saltbridge_stage_target(
        None,
        dock_model=dock_model,
        saltbridge_module=fake_module,
    )
    output = run_saltbridge_analysis_adapter(
        target,
        config,
        saltbridge_module=fake_module,
    )
    if output.interaction_count != 1 or output.summary.total_score != 1.0:
        failures.append("Salt-bridge result adaptation produced wrong values.")
    if validate_saltbridge_stage_output(output):
        failures.append("A valid salt-bridge stage output did not validate.")
    if not output.attached:
        failures.append("Salt-bridge result was not attached.")
    serialized = json.loads(json.dumps(output.to_dict()))
    if serialized["summary"]["interaction_count"] != 1:
        failures.append("Salt-bridge output JSON conversion failed.")

    integrated = AnalysisConfig(
        stage_configs={
            STAGE_SALTBRIDGE: AnalysisStageConfig(
                enabled=True,
                attach_results=True,
                validate_result=True,
                reuse_result=False,
                parameters={"max_distance": 4.2, "attach": True},
            )
        },
        runtime=AnalysisRuntimeConfig(
            failure_policy=FAILURE_POLICY_STRICT,
            attach_results=True,
            reuse_results=True,
        ),
    )
    request = AnalysisRequest(
        dock_models=(dock_model,),
        poses=(source,),
        config=integrated,
    )
    context = AnalysisContext(
        request=request,
        dock_models=[dock_model],
        poses=[source],
        current_pose_index=0,
    )
    stage_result = execute_saltbridge_stage(
        context,
        saltbridge_module=fake_module,
        raise_on_error=True,
    )
    if not stage_result.succeeded:
        failures.append("Salt-bridge stage executor did not succeed.")
    if not isinstance(stage_result.value, SaltBridgeStageOutput):
        failures.append("Salt-bridge executor returned an unexpected value.")
    if context.get_stage_data(STAGE_SALTBRIDGE) is not stage_result:
        failures.append("Salt-bridge result was not stored in the context.")

    registry = create_default_stage_registry()
    register_saltbridge_stage_adapter(registry=registry)
    if not saltbridge_stage_adapter_registered(registry=registry):
        failures.append("Salt-bridge adapter was not registered correctly.")
    definition = registry.require(STAGE_SALTBRIDGE)
    if definition.executor is not execute_saltbridge_stage:
        failures.append("Salt-bridge executor registration failed.")

    real_module = _require_saltbridge_module()
    missing_interface = tuple(
        name for name in SALTBRIDGE_REQUIRED_SYMBOLS if not hasattr(real_module, name)
    )
    if missing_interface:
        failures.append(
            "The repository saltbridge module is missing required symbols: "
            + ", ".join(missing_interface)
        )
    if failures:
        raise RuntimeError(
            "Salt-bridge adapter convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": SALTBRIDGE_ADAPTER_SCHEMA_NAME,
        "schema_version": SALTBRIDGE_ADAPTER_SCHEMA_VERSION,
        "required_symbols": len(SALTBRIDGE_REQUIRED_SYMBOLS),
        "supported_native_parameters": len(SALTBRIDGE_NATIVE_CONFIG_FIELDS),
        "supported_control_parameters": len(SALTBRIDGE_ADAPTER_CONTROL_FIELDS),
        "validated_cases": 24,
    }


