# 16.2. Canonicalization helpers and configuration
# -----------------------------------------------------------------------------


def canonicalize_deduplication_mode(value: Any) -> str:
    """Return one canonical interaction-deduplication mode."""

    return _canonicalize_convention_name(
        value,
        aliases=DEDUPLICATION_MODE_ALIASES,
        valid_names=DEDUPLICATION_MODES,
        field_name="deduplication mode",
        strict=True,
    )


def canonicalize_cross_family_policy(value: Any) -> str:
    """Return one canonical cross-family overlap policy."""

    return _canonicalize_convention_name(
        value,
        aliases=CROSS_FAMILY_POLICY_ALIASES,
        valid_names=CROSS_FAMILY_POLICIES,
        field_name="cross-family policy",
        strict=True,
    )


@dataclass(frozen=True)
class InteractionConsolidationConfig:
    """Configuration for canonical interaction consolidation."""

    families: Tuple[str, ...] = INTERACTION_FAMILY_ORDER
    deduplication_mode: str = DEDUPLICATION_MODE_CANONICAL
    cross_family_policy: str = CROSS_FAMILY_POLICY_ANNOTATE
    include_rejected: bool = False
    preserve_specialized_families: bool = True
    preserve_pi_subtypes: bool = True
    collect_residues: bool = True
    collect_hotspots: bool = True
    collect_statistics: bool = True
    collect_source_references: bool = True
    include_empty_families: bool = True
    distance_precision: int = CONSOLIDATION_DEFAULT_DISTANCE_PRECISION
    score_precision: int = CONSOLIDATION_DEFAULT_SCORE_PRECISION
    maximum_records: int = CONSOLIDATION_MAX_RECORDS
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        canonical_families = canonicalize_interaction_families(
            self.families,
            strict=True,
            unique=True,
        )
        object.__setattr__(self, "families", canonical_families)
        object.__setattr__(
            self,
            "deduplication_mode",
            canonicalize_deduplication_mode(self.deduplication_mode),
        )
        object.__setattr__(
            self,
            "cross_family_policy",
            canonicalize_cross_family_policy(self.cross_family_policy),
        )
        for name in (
            "include_rejected",
            "preserve_specialized_families",
            "preserve_pi_subtypes",
            "collect_residues",
            "collect_hotspots",
            "collect_statistics",
            "collect_source_references",
            "include_empty_families",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        if not isinstance(self.distance_precision, int) or self.distance_precision < 0:
            raise ValueError("distance_precision must be a non-negative integer.")
        if not isinstance(self.score_precision, int) or self.score_precision < 0:
            raise ValueError("score_precision must be a non-negative integer.")
        if not isinstance(self.maximum_records, int) or self.maximum_records <= 0:
            raise ValueError("maximum_records must be a positive integer.")
        if self.maximum_records > CONSOLIDATION_MAX_RECORDS:
            raise ValueError(
                f"maximum_records cannot exceed {CONSOLIDATION_MAX_RECORDS}."
            )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )

    @classmethod
    def from_mapping(cls, value: Optional[Mapping[str, Any]]) -> "InteractionConsolidationConfig":
        """Create a consolidation configuration from a mapping."""

        if value is None:
            return cls()
        if isinstance(value, cls):
            return value
        if not isinstance(value, Mapping):
            raise TypeError("Consolidation configuration must be a mapping.")
        aliases = {
            "family": "families",
            "interaction_families": "families",
            "deduplicate": "deduplication_mode",
            "deduplication": "deduplication_mode",
            "dedup_mode": "deduplication_mode",
            "cross_family": "cross_family_policy",
            "overlap_policy": "cross_family_policy",
            "rejected": "include_rejected",
            "residues": "collect_residues",
            "hotspots": "collect_hotspots",
            "statistics": "collect_statistics",
            "sources": "collect_source_references",
            "max_records": "maximum_records",
        }
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        unknown: List[str] = []
        for raw_name, item in value.items():
            token = _normalize_convention_token(raw_name, field_name="configuration field")
            name = aliases.get(token, token)
            if name not in allowed:
                unknown.append(str(raw_name))
                continue
            normalized[name] = item
        if unknown:
            raise AnalysisConfigurationError(
                "Unknown interaction-consolidation configuration fields.",
                stage=STAGE_CONSOLIDATION,
                details={"unknown_fields": sorted(unknown)},
            )
        return cls(**normalized)

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible configuration mapping."""

        return {
            "schema": CONSOLIDATION_SCHEMA_NAME,
            "schema_version": CONSOLIDATION_SCHEMA_VERSION,
            "families": list(self.families),
            "deduplication_mode": self.deduplication_mode,
            "cross_family_policy": self.cross_family_policy,
            "include_rejected": self.include_rejected,
            "preserve_specialized_families": self.preserve_specialized_families,
            "preserve_pi_subtypes": self.preserve_pi_subtypes,
            "collect_residues": self.collect_residues,
            "collect_hotspots": self.collect_hotspots,
            "collect_statistics": self.collect_statistics,
            "collect_source_references": self.collect_source_references,
            "include_empty_families": self.include_empty_families,
            "distance_precision": self.distance_precision,
            "score_precision": self.score_precision,
            "maximum_records": self.maximum_records,
            "metadata": to_json_compatible(dict(self.metadata)),
        }

    @property
    def fingerprint(self) -> str:
        """Return a stable fingerprint for this configuration."""

        payload = json.dumps(
            self.to_dict(),
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
        return sha256(payload.encode("utf-8")).hexdigest()


def resolve_interaction_consolidation_config(
    config: Optional[AnalysisConfigLike] = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
) -> InteractionConsolidationConfig:
    """Resolve the effective consolidation configuration."""

    values: Dict[str, Any] = {}
    if isinstance(config, InteractionConsolidationConfig):
        values.update(config.to_dict())
        values.pop("schema", None)
        values.pop("schema_version", None)
    elif config is not None:
        integrated = coerce_analysis_config(config)
        stage_config = integrated.stage_config(STAGE_CONSOLIDATION)
        values.update(dict(stage_config.parameters))
    if overrides:
        values.update(dict(overrides))
    return InteractionConsolidationConfig.from_mapping(values)


# 16.3. Source references and canonical records
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class InteractionSourceReference:
    """Trace one canonical interaction back to a stage output."""

    family: str
    stage: str
    source_index: int
    subtype: Optional[str] = None
    source_identifier: Optional[str] = None
    source_type: Optional[str] = None
    stage_status: Optional[str] = None
    attached: bool = False
    reused: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "family",
            canonicalize_interaction_family(self.family),
        )
        object.__setattr__(self, "stage", canonicalize_stage_name(self.stage))
        if self.subtype is not None:
            subtype = normalize_identifier(
                self.subtype,
                default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                lowercase=True,
                maximum_length=128,
            )
            object.__setattr__(self, "subtype", subtype)
        if self.source_index < 0:
            raise ValueError("source_index cannot be negative.")
        object.__setattr__(
            self,
            "source_identifier",
            normalize_optional_text(self.source_identifier, maximum_length=512),
        )
        object.__setattr__(
            self,
            "source_type",
            normalize_optional_text(self.source_type, maximum_length=256),
        )
        object.__setattr__(
            self,
            "stage_status",
            normalize_optional_text(self.stage_status, maximum_length=64),
        )
        object.__setattr__(self, "attached", bool(self.attached))
        object.__setattr__(self, "reused", bool(self.reused))
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible source reference."""

        return {
            "family": self.family,
            "stage": self.stage,
            "source_index": self.source_index,
            "subtype": self.subtype,
            "source_identifier": self.source_identifier,
            "source_type": self.source_type,
            "stage_status": self.stage_status,
            "attached": self.attached,
            "reused": self.reused,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass(frozen=True)
class CanonicalInteractionRecord:
    """Canonical orchestration view of one specialized interaction object."""

    record_id: str
    family: str
    subtype: str
    interaction: Any
    identity_key: str
    equivalence_key: str
    participant_keys: Tuple[str, ...] = ()
    receptor_residue_key: Optional[str] = None
    ligand_residue_key: Optional[str] = None
    distance: Optional[float] = None
    score: Optional[float] = None
    strength: Optional[str] = None
    accepted: bool = True
    source_references: Tuple[InteractionSourceReference, ...] = ()
    overlap_record_ids: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict)
    result_type: str = CANONICAL_INTERACTION_RESULT_TYPE

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "record_id",
            normalize_identifier(
                self.record_id,
                default="interaction",
                lowercase=True,
                maximum_length=256,
            ),
        )
        object.__setattr__(
            self,
            "family",
            canonicalize_interaction_family(self.family),
        )
        object.__setattr__(
            self,
            "subtype",
            normalize_identifier(
                self.subtype,
                default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                lowercase=True,
                maximum_length=128,
            ),
        )
        object.__setattr__(
            self,
            "participant_keys",
            tuple(str(item) for item in self.participant_keys if str(item)),
        )
        object.__setattr__(
            self,
            "source_references",
            tuple(self.source_references),
        )
        object.__setattr__(
            self,
            "overlap_record_ids",
            tuple(dict.fromkeys(str(item) for item in self.overlap_record_ids)),
        )
        if self.distance is not None and not math.isfinite(float(self.distance)):
            raise ValueError("Canonical interaction distance must be finite.")
        if self.score is not None and not math.isfinite(float(self.score)):
            raise ValueError("Canonical interaction score must be finite.")
        object.__setattr__(self, "accepted", bool(self.accepted))
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )

    @property
    def source_count(self) -> int:
        """Return the number of source references represented by this record."""

        return len(self.source_references)

    @property
    def is_duplicate_aggregate(self) -> bool:
        """Return whether multiple source objects were merged into this record."""

        return self.source_count > 1

    @property
    def has_cross_family_overlap(self) -> bool:
        """Return whether an equivalent record exists in another family."""

        return bool(self.overlap_record_ids)

    def with_source(self, source: InteractionSourceReference) -> "CanonicalInteractionRecord":
        """Return a record containing one additional source reference."""

        if source in self.source_references:
            return self
        if len(self.source_references) >= CONSOLIDATION_MAX_SOURCE_REFERENCES:
            return self
        return replace(
            self,
            source_references=(*self.source_references, source),
        )

    def with_overlaps(self, record_ids: Iterable[str]) -> "CanonicalInteractionRecord":
        """Return a record annotated with cross-family overlap identifiers."""

        merged = tuple(
            dict.fromkeys((*self.overlap_record_ids, *(str(item) for item in record_ids)))
        )
        merged = tuple(item for item in merged if item != self.record_id)
        return replace(self, overlap_record_ids=merged)

    def to_dict(
        self,
        *,
        include_interaction: bool = False,
        include_sources: bool = True,
    ) -> Dict[str, Any]:
        """Return an inspection-safe canonical record mapping."""

        result: Dict[str, Any] = {
            "result_type": self.result_type,
            "record_id": self.record_id,
            "family": self.family,
            "subtype": self.subtype,
            "identity_key": self.identity_key,
            "equivalence_key": self.equivalence_key,
            "participant_keys": list(self.participant_keys),
            "receptor_residue_key": self.receptor_residue_key,
            "ligand_residue_key": self.ligand_residue_key,
            "distance": self.distance,
            "score": self.score,
            "strength": self.strength,
            "accepted": self.accepted,
            "source_count": self.source_count,
            "overlap_record_ids": list(self.overlap_record_ids),
            "metadata": to_json_compatible(dict(self.metadata)),
        }
        if include_sources:
            result["source_references"] = [
                item.to_dict() for item in self.source_references
            ]
        if include_interaction:
            result["interaction"] = to_json_compatible(self.interaction)
        return result


@dataclass(frozen=True)
class InteractionDuplicateRecord:
    """Describe one interaction removed during consolidation."""

    retained_record_id: str
    removed_record_id: str
    family: str
    subtype: str
    reason: str
    key: str
    cross_family: bool = False

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible duplicate record."""

        return {
            "retained_record_id": self.retained_record_id,
            "removed_record_id": self.removed_record_id,
            "family": self.family,
            "subtype": self.subtype,
            "reason": self.reason,
            "key": self.key,
            "cross_family": self.cross_family,
        }


# 16.4. Native stage-output extraction
# -----------------------------------------------------------------------------


def _unwrap_interaction_stage_value(value: Any) -> Tuple[Any, Optional[AnalysisStageResult]]:
    """Return one native stage value and its optional stage wrapper."""

    if isinstance(value, AnalysisStageResult):
        return value.value, value
    return value, None


def interaction_stage_output_family(value: Any) -> Optional[str]:
    """Infer the canonical interaction family represented by one value."""

    native, wrapper = _unwrap_interaction_stage_value(value)
    if wrapper is not None and wrapper.stage in INTERACTION_STAGES:
        return canonicalize_interaction_family(wrapper.stage)
    if isinstance(native, ContactStageOutput):
        return INTERACTION_FAMILY_CONTACTS
    if isinstance(native, HydrogenBondStageOutput):
        return INTERACTION_FAMILY_HBONDS
    if isinstance(native, HydrophobicStageOutput):
        return INTERACTION_FAMILY_HYDROPHOBIC
    if isinstance(native, PiStageOutput):
        return INTERACTION_FAMILY_PI
    if isinstance(native, SaltBridgeStageOutput):
        return INTERACTION_FAMILY_SALTBRIDGE
    result_type = normalize_optional_text(
        get_object_value(native, "result_type", default=None),
        maximum_length=256,
    )
    token = "" if result_type is None else result_type.lower()
    if "hydrophobic" in token:
        return INTERACTION_FAMILY_HYDROPHOBIC
    if "hbond" in token or "hydrogen_bond" in token:
        return INTERACTION_FAMILY_HBONDS
    if "salt" in token and "bridge" in token:
        return INTERACTION_FAMILY_SALTBRIDGE
    if token.startswith("pi") or "pi_" in token:
        return INTERACTION_FAMILY_PI
    if "contact" in token:
        return INTERACTION_FAMILY_CONTACTS
    return None


def collect_interaction_stage_outputs(
    source: Any = None,
    *,
    context: Optional[AnalysisContext] = None,
) -> Dict[str, Any]:
    """Collect at most one latest stage output for each interaction family."""

    candidates: List[Tuple[Optional[str], Any]] = []
    if source is None and context is not None:
        source = context.stage_data
    if isinstance(source, Mapping):
        for key, value in source.items():
            family: Optional[str] = None
            try:
                family = canonicalize_interaction_family(key)
            except (TypeError, ValueError):
                try:
                    stage = canonicalize_stage_name(key)
                except (TypeError, ValueError):
                    stage = None
                if stage in INTERACTION_STAGES:
                    family = canonicalize_interaction_family(stage)
            candidates.append((family, value))
    elif source is not None:
        if isinstance(source, (str, bytes, bytearray)):
            candidates.append((None, source))
        else:
            try:
                values = tuple(source)
            except TypeError:
                values = (source,)
            candidates.extend((None, item) for item in values)

    collected: Dict[str, Any] = {}
    for hinted_family, value in candidates:
        family = hinted_family or interaction_stage_output_family(value)
        if family is None:
            continue
        native, wrapper = _unwrap_interaction_stage_value(value)
        if wrapper is not None and wrapper.status in {
            StageStatus.FAILED,
            StageStatus.BLOCKED,
            StageStatus.CANCELLED,
            StageStatus.SKIPPED,
        }:
            continue
        if native is None:
            continue
        collected[family] = value
    return collected


def _pi_interactions_from_output(value: Any) -> Tuple[Tuple[str, Any], ...]:
    """Return pi interactions paired with canonical subtype names."""

    native, _ = _unwrap_interaction_stage_value(value)
    if isinstance(native, PiStageOutput):
        pairs: List[Tuple[str, Any]] = []
        for subtype, interactions in native.interactions_by_subtype.items():
            try:
                canonical_subtype = canonicalize_pi_subtype(subtype)
            except ValueError:
                canonical_subtype = normalize_identifier(
                    subtype,
                    default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                    lowercase=True,
                )
            pairs.extend((canonical_subtype, item) for item in interactions)
        if pairs:
            return tuple(pairs)
        return tuple(
            (
                canonicalize_pi_result_subtype(item),
                item,
            )
            for item in native.interactions
        )
    interactions_by_subtype = get_object_value(
        native,
        "interactions_by_subtype",
        default=None,
    )
    if isinstance(interactions_by_subtype, Mapping):
        pairs = []
        for subtype, interactions in interactions_by_subtype.items():
            try:
                canonical_subtype = canonicalize_pi_subtype(subtype)
            except ValueError:
                canonical_subtype = normalize_identifier(
                    subtype,
                    default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                    lowercase=True,
                )
            pairs.extend(
                (canonical_subtype, item)
                for item in normalize_object_sequence(interactions)
            )
        return tuple(pairs)
    interactions = normalize_object_sequence(
        get_object_value(native, "interactions", default=())
    )
    return tuple(
        (
            normalize_identifier(
                get_first_object_value(
                    item,
                    ("subtype", "interaction_type", "geometry_subtype"),
                    default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                ),
                default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                lowercase=True,
            ),
            item,
        )
        for item in interactions
    )


def interaction_output_interactions(
    family: Any,
    value: Any,
) -> Tuple[Tuple[str, Any], ...]:
    """Extract native interactions and subtypes from one stage output."""

    canonical_family = canonicalize_interaction_family(family)
    native, _ = _unwrap_interaction_stage_value(value)
    if canonical_family == INTERACTION_FAMILY_PI:
        return _pi_interactions_from_output(native)
    if canonical_family == INTERACTION_FAMILY_CONTACTS:
        interactions = (
            native.contacts
            if isinstance(native, ContactStageOutput)
            else get_first_object_value(
                native,
                ("contacts", "interactions"),
                default=(),
            )
        )
    elif canonical_family == INTERACTION_FAMILY_HBONDS:
        interactions = (
            native.hydrogen_bonds
            if isinstance(native, HydrogenBondStageOutput)
            else get_first_object_value(
                native,
                ("hydrogen_bonds", "hbonds", "interactions"),
                default=(),
            )
        )
    elif canonical_family == INTERACTION_FAMILY_HYDROPHOBIC:
        interactions = (
            native.interactions
            if isinstance(native, HydrophobicStageOutput)
            else get_object_value(native, "interactions", default=())
        )
    elif canonical_family == INTERACTION_FAMILY_SALTBRIDGE:
        interactions = (
            native.interactions
            if isinstance(native, SaltBridgeStageOutput)
            else get_first_object_value(
                native,
                ("interactions", "saltbridges", "salt_bridges"),
                default=(),
            )
        )
    else:
        interactions = ()
    result: List[Tuple[str, Any]] = []
    for item in normalize_object_sequence(interactions):
        subtype = interaction_subtype(item, canonical_family)
        result.append((subtype, item))
    return tuple(result)


def interaction_output_hotspots(value: Any) -> Tuple[Any, ...]:
    """Extract hotspot objects from one stage output when available."""

    native, _ = _unwrap_interaction_stage_value(value)
    hotspots = get_object_value(native, "hotspots", default=None)
    if hotspots is not None:
        return tuple(normalize_object_sequence(hotspots))
    grouping = get_first_object_value(
        native,
        ("grouping_result", "groupings"),
        default=None,
    )
    return tuple(
        normalize_object_sequence(
            get_first_object_value(
                grouping,
                ("hotspots", "hotspot_groups"),
                default=(),
            )
        )
    )


def interaction_output_residue_groups(value: Any) -> Tuple[Any, ...]:
    """Extract residue-level groups from one stage output when available."""

    native, _ = _unwrap_interaction_stage_value(value)
    if isinstance(native, ContactStageOutput):
        return native.residue_contacts
    if isinstance(native, HydrogenBondStageOutput):
        return native.residue_hydrogen_bonds
    if isinstance(native, HydrophobicStageOutput):
        return native.residue_groups
    direct = get_first_object_value(
        native,
        (
            "residue_groups",
            "residue_contacts",
            "residue_hydrogen_bonds",
            "residue_summaries",
        ),
        default=(),
    )
    return tuple(normalize_object_sequence(direct))


# 16.5. Generic interaction inspection
# -----------------------------------------------------------------------------


def _finite_optional_number(value: Any) -> Optional[float]:
    """Return one finite float or None."""

    if isinstance(value, bool) or not isinstance(value, Real):
        return None
    converted = float(value)
    return converted if math.isfinite(converted) else None


def _first_finite_value(obj: Any, fields_to_check: Iterable[str]) -> Optional[float]:
    """Read the first finite numeric field from one object."""

    for name in fields_to_check:
        value = _finite_optional_number(
            get_object_value(obj, name, default=None, skip_none=True)
        )
        if value is not None:
            return value
    return None


def interaction_distance(value: Any) -> Optional[float]:
    """Return a representative interaction distance when available."""

    direct = _first_finite_value(value, _INTERACTION_DISTANCE_FIELDS)
    if direct is not None:
        return direct
    geometry = get_first_object_value(
        value,
        _INTERACTION_GEOMETRY_FIELDS,
        default=None,
    )
    if geometry is None:
        return None
    return _first_finite_value(geometry, _INTERACTION_DISTANCE_FIELDS)


def interaction_score(value: Any) -> Optional[float]:
    """Return a representative interaction score when available."""

    direct = _first_finite_value(value, _INTERACTION_SCORE_FIELDS)
    if direct is not None:
        return direct
    classification = get_object_value(value, "classification", default=None)
    return _first_finite_value(classification, _INTERACTION_SCORE_FIELDS)


def interaction_strength(value: Any) -> Optional[str]:
    """Return a normalized interaction-strength or classification label."""

    raw = get_first_object_value(
        value,
        _INTERACTION_STRENGTH_FIELDS,
        default=None,
    )
    if raw is not None and not isinstance(raw, str):
        raw = get_first_object_value(raw, ("value", "name", "classification"), default=raw)
    text = normalize_optional_text(raw, maximum_length=128)
    if text is None:
        return None
    return normalize_identifier(text, default="unknown", lowercase=True)


def interaction_is_accepted(value: Any) -> bool:
    """Return whether an interaction should be retained by default."""

    rejected = get_first_object_value(
        value,
        _INTERACTION_REJECTED_FIELDS,
        default=None,
    )
    if isinstance(rejected, bool) and rejected:
        return False
    accepted = get_first_object_value(
        value,
        _INTERACTION_ACCEPTED_FIELDS,
        default=None,
    )
    if isinstance(accepted, bool):
        return accepted
    strength = interaction_strength(value)
    return strength not in {"rejected", "invalid", "failed"}


def interaction_subtype(value: Any, family: Any) -> str:
    """Return a normalized subtype for one interaction family."""

    canonical_family = canonicalize_interaction_family(family)
    if canonical_family == INTERACTION_FAMILY_PI:
        raw = get_first_object_value(
            value,
            ("subtype", "interaction_type", "geometry_subtype"),
            default=PI_SUBTYPE_STACKING,
        )
        try:
            return canonicalize_pi_subtype(raw)
        except ValueError:
            return normalize_identifier(
                raw,
                default=CONSOLIDATION_UNKNOWN_SUBTYPE,
                lowercase=True,
            )
    raw = get_first_object_value(
        value,
        ("interaction_type", "classification", "type", "mode"),
        default=canonical_family,
    )
    if not isinstance(raw, str):
        raw = get_first_object_value(raw, ("value", "name"), default=canonical_family)
    return normalize_identifier(
        raw,
        default=canonical_family,
        lowercase=True,
        maximum_length=128,
    )


def _residue_from_participant(value: Any) -> Any:
    """Return an associated residue object when available."""

    return get_first_object_value(
        value,
        ("residue", "parent_residue", "receptor_residue", "ligand_residue"),
        default=None,
    )


def canonical_residue_key(value: Any) -> Optional[str]:
    """Return a stable readable key for one residue-like object."""

    if value is None:
        return None
    explicit = get_first_object_value(
        value,
        _RESIDUE_IDENTIFIER_FIELDS,
        default=None,
    )
    if explicit is not None and not isinstance(
        explicit, (Mapping, list, tuple, set, frozenset)
    ):
        text = normalize_optional_text(explicit, maximum_length=512)
        if text:
            return normalize_identifier(text, default="residue", lowercase=False)
    chain = get_first_object_value(
        value,
        ("chain_id", "chain", "chain_identifier"),
        default=None,
    )
    if chain is not None and not isinstance(chain, str):
        chain = get_first_object_value(chain, ("chain_id", "id", "name"), default=chain)
    number = get_first_object_value(
        value,
        ("number", "residue_number", "position", "index"),
        default=None,
    )
    name = get_first_object_value(
        value,
        ("name", "residue_name", "type"),
        default=None,
    )
    components = [
        normalize_optional_text(chain, maximum_length=64),
        normalize_optional_text(number, maximum_length=64),
        normalize_optional_text(name, maximum_length=64),
    ]
    components = [item for item in components if item]
    if components:
        return ":".join(components)
    return f"residue:{stable_object_fingerprint(value)[:20]}"


def canonical_participant_key(value: Any) -> str:
    """Return a stable key for one atom, ring, group or participant object."""

    if value is None:
        return CONSOLIDATION_UNKNOWN_PARTICIPANT
    explicit = get_first_object_value(
        value,
        _PARTICIPANT_IDENTIFIER_FIELDS,
        default=None,
    )
    if explicit is not None and not isinstance(
        explicit, (Mapping, list, tuple, set, frozenset)
    ):
        text = normalize_optional_text(explicit, maximum_length=512)
        if text:
            return normalize_identifier(text, default="participant", lowercase=False)
    residue = _residue_from_participant(value)
    residue_key = canonical_residue_key(residue)
    atom_name = get_first_object_value(
        value,
        ("atom_name", "name", "element_name"),
        default=None,
    )
    atom_index = get_first_object_value(
        value,
        ("atom_index", "serial_number", "serial", "index"),
        default=None,
    )
    participant_type = get_first_object_value(
        value,
        ("participant_type", "group_type", "ring_type", "element"),
        default=None,
    )
    components = [
        residue_key,
        normalize_optional_text(atom_name, maximum_length=128),
        normalize_optional_text(atom_index, maximum_length=64),
        normalize_optional_text(participant_type, maximum_length=128),
    ]
    components = [item for item in components if item]
    if components:
        return ":".join(components)
    return f"participant:{stable_object_fingerprint(value)[:24]}"


def interaction_participants(value: Any, family: Any) -> Tuple[Any, Any]:
    """Return the two primary participant objects for an interaction."""

    canonical_family = canonicalize_interaction_family(family)
    first_fields, second_fields = _FAMILY_PARTICIPANT_FIELDS[canonical_family]
    first = get_first_object_value(value, first_fields, default=None)
    second = get_first_object_value(value, second_fields, default=None)
    if canonical_family == INTERACTION_FAMILY_PI and first is second:
        alternatives = (
            get_object_value(value, "ring_2", default=None),
            get_object_value(value, "charged_group", default=None),
            get_object_value(value, "amide_group", default=None),
        )
        second = next((item for item in alternatives if item is not None and item is not first), None)
    return first, second


def interaction_residue_keys(
    value: Any,
    family: Any,
    participants: Optional[Tuple[Any, Any]] = None,
) -> Tuple[Optional[str], Optional[str]]:
    """Return receptor and ligand residue keys when they can be inferred."""

    canonical_family = canonicalize_interaction_family(family)
    receptor_residue = get_first_object_value(
        value,
        _INTERACTION_RECEPTOR_RESIDUE_FIELDS,
        default=None,
    )
    ligand_residue = get_first_object_value(
        value,
        _INTERACTION_LIGAND_RESIDUE_FIELDS,
        default=None,
    )
    first, second = participants or interaction_participants(value, canonical_family)
    if canonical_family == INTERACTION_FAMILY_HYDROPHOBIC:
        receptor_residue = receptor_residue or _residue_from_participant(first)
        ligand_residue = ligand_residue or _residue_from_participant(second)
    elif canonical_family == INTERACTION_FAMILY_HBONDS:
        direction = normalize_optional_text(
            get_object_value(value, "direction", default=None),
            maximum_length=128,
        )
        donor_residue = get_first_object_value(
            value,
            ("donor_residue", "donor_residue_key"),
            default=_residue_from_participant(first),
        )
        acceptor_residue = get_first_object_value(
            value,
            ("acceptor_residue", "acceptor_residue_key"),
            default=_residue_from_participant(second),
        )
        if direction and "ligand_donor" in direction.lower():
            ligand_residue = ligand_residue or donor_residue
            receptor_residue = receptor_residue or acceptor_residue
        elif direction and "receptor_donor" in direction.lower():
            receptor_residue = receptor_residue or donor_residue
            ligand_residue = ligand_residue or acceptor_residue
    elif canonical_family == INTERACTION_FAMILY_CONTACTS:
        receptor_residue = receptor_residue or get_object_value(value, "residue_2", default=None)
        ligand_residue = ligand_residue or get_object_value(value, "residue_1", default=None)
    elif canonical_family == INTERACTION_FAMILY_PI:
        receptor_residue = receptor_residue or _residue_from_participant(first)
        ligand_residue = ligand_residue or _residue_from_participant(second)
    elif canonical_family == INTERACTION_FAMILY_SALTBRIDGE:
        first_residue = _residue_from_participant(first)
        second_residue = _residue_from_participant(second)
        first_type = normalize_optional_text(
            get_object_value(first, "participant_type", default=None),
            maximum_length=64,
        )
        second_type = normalize_optional_text(
            get_object_value(second, "participant_type", default=None),
            maximum_length=64,
        )
        if first_type and "ligand" in first_type.lower():
            ligand_residue = ligand_residue or first_residue
            receptor_residue = receptor_residue or second_residue
        elif second_type and "ligand" in second_type.lower():
            receptor_residue = receptor_residue or first_residue
            ligand_residue = ligand_residue or second_residue
    return canonical_residue_key(receptor_residue), canonical_residue_key(ligand_residue)


def interaction_explicit_identifier(value: Any) -> Optional[str]:
    """Return a specialized interaction identifier when available."""

    raw = get_first_object_value(value, _INTERACTION_IDENTIFIER_FIELDS, default=None)
    text = normalize_optional_text(raw, maximum_length=512)
    if text is None:
        return None
    return normalize_identifier(text, default="interaction", lowercase=False)


def canonical_interaction_keys(
    value: Any,
    family: Any,
    subtype: Any,
    *,
    distance_precision: int = CONSOLIDATION_DEFAULT_DISTANCE_PRECISION,
) -> Tuple[str, str, Tuple[str, ...], Optional[str], Optional[str]]:
    """Build identity and cross-family equivalence keys for one interaction."""

    canonical_family = canonicalize_interaction_family(family)
    canonical_subtype = normalize_identifier(
        subtype,
        default=CONSOLIDATION_UNKNOWN_SUBTYPE,
        lowercase=True,
    )
    participants = interaction_participants(value, canonical_family)
    participant_keys = tuple(canonical_participant_key(item) for item in participants)
    if canonical_family in {INTERACTION_FAMILY_CONTACTS, INTERACTION_FAMILY_SALTBRIDGE}:
        structural_participants = tuple(sorted(participant_keys))
    else:
        structural_participants = participant_keys
    receptor_residue_key, ligand_residue_key = interaction_residue_keys(
        value,
        canonical_family,
        participants,
    )
    distance = interaction_distance(value)
    distance_token = "na" if distance is None else f"{round(distance, distance_precision):.{distance_precision}f}"
    explicit_id = interaction_explicit_identifier(value)
    structural = "|".join((*structural_participants, distance_token))
    if all(item == CONSOLIDATION_UNKNOWN_PARTICIPANT for item in participant_keys):
        structural = explicit_id or stable_object_fingerprint(value)
    identity = "|".join((canonical_family, canonical_subtype, structural))
    equivalence = "|".join(("pair", *tuple(sorted(participant_keys)), distance_token))
    return (
        identity,
        equivalence,
        participant_keys,
        receptor_residue_key,
        ligand_residue_key,
    )


# 16.6. Canonical record construction and ranking
# -----------------------------------------------------------------------------


def _stage_output_source_reference(
    family: str,
    subtype: str,
    source_index: int,
    stage_value: Any,
    interaction: Any,
) -> InteractionSourceReference:
    """Build one trace reference for a stage interaction object."""

    native, wrapper = _unwrap_interaction_stage_value(stage_value)
    source_identifier = interaction_explicit_identifier(interaction)
    source_type = type(interaction).__name__
    return InteractionSourceReference(
        family=family,
        stage=interaction_family_to_stage(family),
        source_index=source_index,
        subtype=subtype,
        source_identifier=source_identifier,
        source_type=source_type,
        stage_status=(wrapper.status.value if wrapper is not None else None),
        attached=bool(get_object_value(native, "attached", default=False)),
        reused=bool(get_object_value(native, "reused", default=False)),
        metadata={
            "adapter_result_type": get_object_value(native, "result_type", default=None),
        },
    )


def build_canonical_interaction_record(
    interaction: Any,
    *,
    family: Any,
    subtype: Optional[Any] = None,
    source_reference: Optional[InteractionSourceReference] = None,
    config: Optional[InteractionConsolidationConfig] = None,
    ordinal: int = 0,
) -> CanonicalInteractionRecord:
    """Create one canonical record while preserving the native object."""

    effective = config or InteractionConsolidationConfig()
    canonical_family = canonicalize_interaction_family(family)
    canonical_subtype = interaction_subtype(
        interaction,
        canonical_family,
    ) if subtype is None else normalize_identifier(
        subtype,
        default=CONSOLIDATION_UNKNOWN_SUBTYPE,
        lowercase=True,
    )
    identity_key, equivalence_key, participant_keys, receptor_key, ligand_key = (
        canonical_interaction_keys(
            interaction,
            canonical_family,
            canonical_subtype,
            distance_precision=effective.distance_precision,
        )
    )
    record_digest = sha256(
        f"{identity_key}|{ordinal}".encode("utf-8")
    ).hexdigest()[:16]
    record_id = f"{canonical_family}_{record_digest}"
    sources = () if source_reference is None else (source_reference,)
    return CanonicalInteractionRecord(
        record_id=record_id,
        family=canonical_family,
        subtype=canonical_subtype,
        interaction=interaction,
        identity_key=identity_key,
        equivalence_key=equivalence_key,
        participant_keys=participant_keys,
        receptor_residue_key=receptor_key,
        ligand_residue_key=ligand_key,
        distance=interaction_distance(interaction),
        score=interaction_score(interaction),
        strength=interaction_strength(interaction),
        accepted=interaction_is_accepted(interaction),
        source_references=sources,
        metadata={
            "native_type": type(interaction).__name__,
            "explicit_identifier": interaction_explicit_identifier(interaction),
        },
    )


def _record_preference_key(record: CanonicalInteractionRecord) -> Tuple[Any, ...]:
    """Return a deterministic ranking key for duplicate representatives."""

    return (
        0 if record.accepted else 1,
        CONSOLIDATION_FAMILY_PRIORITY.get(record.family, 99),
        -(record.score if record.score is not None else float("-inf")),
        record.distance if record.distance is not None else float("inf"),
        record.record_id,
    )


def choose_canonical_representative(
    first: CanonicalInteractionRecord,
    second: CanonicalInteractionRecord,
) -> Tuple[CanonicalInteractionRecord, CanonicalInteractionRecord]:
    """Return preferred and removed records for one duplicate pair."""

    if _record_preference_key(second) < _record_preference_key(first):
        return second, first
    return first, second


# 16.7. Consolidation result structures
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class InteractionConsolidationSummary:
    """Compact counts and measurements for one consolidation run."""

    input_count: int
    retained_count: int
    duplicate_count: int
    rejected_count: int
    overlap_group_count: int
    family_input_counts: Mapping[str, int] = field(default_factory=dict)
    family_retained_counts: Mapping[str, int] = field(default_factory=dict)
    family_duplicate_counts: Mapping[str, int] = field(default_factory=dict)
    subtype_counts: Mapping[str, Mapping[str, int]] = field(default_factory=dict)
    residue_count: int = 0
    hotspot_count: int = 0
    total_score: float = 0.0
    mean_score: Optional[float] = None
    minimum_distance: Optional[float] = None
    mean_distance: Optional[float] = None
    maximum_distance: Optional[float] = None

    def __post_init__(self) -> None:
        for name in (
            "input_count",
            "retained_count",
            "duplicate_count",
            "rejected_count",
            "overlap_group_count",
            "residue_count",
            "hotspot_count",
        ):
            if getattr(self, name) < 0:
                raise ValueError(f"{name} cannot be negative.")
        object.__setattr__(
            self,
            "family_input_counts",
            MappingProxyType(dict(self.family_input_counts)),
        )
        object.__setattr__(
            self,
            "family_retained_counts",
            MappingProxyType(dict(self.family_retained_counts)),
        )
        object.__setattr__(
            self,
            "family_duplicate_counts",
            MappingProxyType(dict(self.family_duplicate_counts)),
        )
        object.__setattr__(
            self,
            "subtype_counts",
            MappingProxyType(
                {
                    str(family): MappingProxyType(dict(counts))
                    for family, counts in self.subtype_counts.items()
                }
            ),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible summary."""

        return {
            "input_count": self.input_count,
            "retained_count": self.retained_count,
            "duplicate_count": self.duplicate_count,
            "rejected_count": self.rejected_count,
            "overlap_group_count": self.overlap_group_count,
            "family_input_counts": dict(self.family_input_counts),
            "family_retained_counts": dict(self.family_retained_counts),
            "family_duplicate_counts": dict(self.family_duplicate_counts),
            "subtype_counts": {
                family: dict(counts)
                for family, counts in self.subtype_counts.items()
            },
            "residue_count": self.residue_count,
            "hotspot_count": self.hotspot_count,
            "total_score": self.total_score,
            "mean_score": self.mean_score,
            "minimum_distance": self.minimum_distance,
            "mean_distance": self.mean_distance,
            "maximum_distance": self.maximum_distance,
        }


@dataclass(frozen=True)
class InteractionConsolidationResult:
    """Integrated canonical and native views of all interaction families."""

    bundle: InteractionAnalysisBundle
    records: Tuple[CanonicalInteractionRecord, ...]
    duplicates: Tuple[InteractionDuplicateRecord, ...]
    summary: InteractionConsolidationSummary
    records_by_family: Mapping[str, Tuple[CanonicalInteractionRecord, ...]] = field(
        default_factory=dict
    )
    overlap_groups: Mapping[str, Tuple[str, ...]] = field(default_factory=dict)
    statistics: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    warnings: Tuple[str, ...] = ()
    configuration: Optional[InteractionConsolidationConfig] = None
    result_type: str = CONSOLIDATION_RESULT_TYPE

    def __post_init__(self) -> None:
        if not isinstance(self.bundle, InteractionAnalysisBundle):
            raise TypeError("bundle must be an InteractionAnalysisBundle.")
        object.__setattr__(self, "records", tuple(self.records))
        object.__setattr__(self, "duplicates", tuple(self.duplicates))
        object.__setattr__(self, "warnings", tuple(str(item) for item in self.warnings))
        normalized_by_family: Dict[str, Tuple[CanonicalInteractionRecord, ...]] = {}
        for family, values in self.records_by_family.items():
            canonical = canonicalize_interaction_family(family)
            normalized_by_family[canonical] = tuple(values)
        object.__setattr__(
            self,
            "records_by_family",
            MappingProxyType(normalized_by_family),
        )
        object.__setattr__(
            self,
            "overlap_groups",
            MappingProxyType(
                {
                    str(key): tuple(str(item) for item in values)
                    for key, values in self.overlap_groups.items()
                }
            ),
        )
        object.__setattr__(
            self,
            "statistics",
            MappingProxyType(normalize_statistics_mapping(self.statistics)),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(normalize_metadata_mapping(self.metadata)),
        )

    @property
    def interaction_count(self) -> int:
        """Return the retained canonical interaction count."""

        return len(self.records)

    @property
    def is_empty(self) -> bool:
        """Return whether no interaction was retained."""

        return not self.records

    def family_records(self, family: Any) -> Tuple[CanonicalInteractionRecord, ...]:
        """Return canonical records for one family."""

        return self.records_by_family.get(canonicalize_interaction_family(family), ())

    def to_dict(
        self,
        *,
        include_records: bool = True,
        include_interactions: bool = False,
        include_bundle: bool = True,
    ) -> Dict[str, Any]:
        """Return a JSON-compatible consolidation representation."""

        result: Dict[str, Any] = {
            "result_type": self.result_type,
            "schema": CONSOLIDATION_SCHEMA_NAME,
            "schema_version": CONSOLIDATION_SCHEMA_VERSION,
            "summary": self.summary.to_dict(),
            "duplicates": [item.to_dict() for item in self.duplicates],
            "records_by_family": {
                family: [record.record_id for record in records]
                for family, records in self.records_by_family.items()
            },
            "overlap_groups": {
                key: list(values) for key, values in self.overlap_groups.items()
            },
            "statistics": to_json_compatible(dict(self.statistics)),
            "metadata": to_json_compatible(dict(self.metadata)),
            "warnings": list(self.warnings),
            "configuration": (
                self.configuration.to_dict()
                if self.configuration is not None
                else None
            ),
        }
        if include_records:
            result["records"] = [
                record.to_dict(include_interaction=include_interactions)
                for record in self.records
            ]
        if include_bundle:
            result["bundle"] = self.bundle.to_dict(include_objects=include_interactions)
        return result


# 16.8. Deduplication and overlap annotation
# -----------------------------------------------------------------------------


def _record_deduplication_key(
    record: CanonicalInteractionRecord,
    mode: str,
) -> Optional[str]:
    """Return the effective within-family deduplication key."""

    canonical_mode = canonicalize_deduplication_mode(mode)
    if canonical_mode == DEDUPLICATION_MODE_NONE:
        return None
    if canonical_mode == DEDUPLICATION_MODE_REFERENCE:
        return f"reference:{id(record.interaction)}"
    return record.identity_key


def deduplicate_canonical_interactions(
    records: Iterable[CanonicalInteractionRecord],
    *,
    config: Optional[InteractionConsolidationConfig] = None,
) -> Tuple[Tuple[CanonicalInteractionRecord, ...], Tuple[InteractionDuplicateRecord, ...]]:
    """Deduplicate canonical records without changing specialized chemistry."""

    effective = config or InteractionConsolidationConfig()
    retained: List[CanonicalInteractionRecord] = []
    index_by_key: Dict[Tuple[str, str], int] = {}
    duplicates: List[InteractionDuplicateRecord] = []
    for record in records:
        if not record.accepted and not effective.include_rejected:
            duplicates.append(
                InteractionDuplicateRecord(
                    retained_record_id="",
                    removed_record_id=record.record_id,
                    family=record.family,
                    subtype=record.subtype,
                    reason="rejected",
                    key=record.identity_key,
                    cross_family=False,
                )
            )
            continue
        key = _record_deduplication_key(record, effective.deduplication_mode)
        if key is None:
            retained.append(record)
            continue
        grouped_key = (record.family, key)
        previous_index = index_by_key.get(grouped_key)
        if previous_index is None:
            index_by_key[grouped_key] = len(retained)
            retained.append(record)
            continue
        current = retained[previous_index]
        winner, removed = choose_canonical_representative(current, record)
        for source in removed.source_references:
            winner = winner.with_source(source)
        retained[previous_index] = winner
        duplicates.append(
            InteractionDuplicateRecord(
                retained_record_id=winner.record_id,
                removed_record_id=removed.record_id,
                family=removed.family,
                subtype=removed.subtype,
                reason=effective.deduplication_mode,
                key=key,
                cross_family=False,
            )
        )
    return tuple(retained), tuple(duplicates)


def annotate_cross_family_overlaps(
    records: Iterable[CanonicalInteractionRecord],
    *,
    policy: Any = CROSS_FAMILY_POLICY_ANNOTATE,
) -> Tuple[
    Tuple[CanonicalInteractionRecord, ...],
    Tuple[InteractionDuplicateRecord, ...],
    Mapping[str, Tuple[str, ...]],
]:
    """Preserve, annotate or remove structurally overlapping family records."""

    canonical_policy = canonicalize_cross_family_policy(policy)
    working = list(records)
    grouped: Dict[str, List[int]] = defaultdict(list)
    for index, record in enumerate(working):
        grouped[record.equivalence_key].append(index)
    overlap_groups: Dict[str, Tuple[str, ...]] = {}
    cross_duplicates: List[InteractionDuplicateRecord] = []
    remove_indices: Set[int] = set()
    for key, indices in grouped.items():
        families = {working[index].family for index in indices}
        if len(indices) < 2 or len(families) < 2:
            continue
        record_ids = tuple(working[index].record_id for index in indices)
        overlap_groups[key] = record_ids
        if canonical_policy in {
            CROSS_FAMILY_POLICY_ANNOTATE,
            CROSS_FAMILY_POLICY_DEDUPLICATE,
        }:
            for index in indices:
                working[index] = working[index].with_overlaps(record_ids)
        if canonical_policy != CROSS_FAMILY_POLICY_DEDUPLICATE:
            continue
        representative_index = min(
            indices,
            key=lambda item: _record_preference_key(working[item]),
        )
        representative = working[representative_index]
        for index in indices:
            if index == representative_index:
                continue
            removed = working[index]
            for source in removed.source_references:
                representative = representative.with_source(source)
            remove_indices.add(index)
            cross_duplicates.append(
                InteractionDuplicateRecord(
                    retained_record_id=representative.record_id,
                    removed_record_id=removed.record_id,
                    family=removed.family,
                    subtype=removed.subtype,
                    reason="cross_family_equivalence",
                    key=key,
                    cross_family=True,
                )
            )
        working[representative_index] = representative
    retained = tuple(
        record for index, record in enumerate(working) if index not in remove_indices
    )
    return retained, tuple(cross_duplicates), MappingProxyType(overlap_groups)


# 16.9. Bundle, residue, hotspot and statistics construction
# -----------------------------------------------------------------------------


def _unique_objects_by_key(values: Iterable[Any]) -> List[Any]:
    """Deduplicate generic objects by stable canonical keys."""

    retained: List[Any] = []
    seen: Set[str] = set()
    for value in values:
        key = canonical_residue_key(value) or canonical_participant_key(value)
        if key in seen:
            continue
        retained.append(value)
        seen.add(key)
    return retained


def build_interaction_bundle_from_records(
    records: Iterable[CanonicalInteractionRecord],
    *,
    hotspots: Iterable[Any] = (),
    residues: Iterable[Any] = (),
    statistics: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> InteractionAnalysisBundle:
    """Build the native-object interaction bundle from canonical records."""

    bundle = InteractionAnalysisBundle(
        hotspots=_unique_objects_by_key(hotspots),
        residues=_unique_objects_by_key(residues),
        statistics=dict(statistics or {}),
        metadata=dict(metadata or {}),
    )
    for record in records:
        if record.family == INTERACTION_FAMILY_PI:
            bundle.add(record.family, record.interaction, subtype=record.subtype)
        else:
            bundle.add(record.family, record.interaction)
    return bundle


def _record_summary_statistics(
    records: Sequence[CanonicalInteractionRecord],
    *,
    input_counts: Mapping[str, int],
    duplicates: Sequence[InteractionDuplicateRecord],
    rejected_count: int,
    overlap_groups: Mapping[str, Tuple[str, ...]],
    residue_count: int,
    hotspot_count: int,
) -> InteractionConsolidationSummary:
    """Calculate compact consolidation statistics."""

    retained_counts = Counter(record.family for record in records)
    duplicate_counts = Counter(
        item.family for item in duplicates if item.reason != "rejected"
    )
    subtype_counts: Dict[str, Counter[str]] = defaultdict(Counter)
    distances: List[float] = []
    scores: List[float] = []
    for record in records:
        subtype_counts[record.family][record.subtype] += 1
        if record.distance is not None:
            distances.append(record.distance)
        if record.score is not None:
            scores.append(record.score)
    return InteractionConsolidationSummary(
        input_count=sum(input_counts.values()),
        retained_count=len(records),
        duplicate_count=sum(duplicate_counts.values()),
        rejected_count=rejected_count,
        overlap_group_count=len(overlap_groups),
        family_input_counts={
            family: int(input_counts.get(family, 0))
            for family in INTERACTION_FAMILY_ORDER
        },
        family_retained_counts={
            family: int(retained_counts.get(family, 0))
            for family in INTERACTION_FAMILY_ORDER
        },
        family_duplicate_counts={
            family: int(duplicate_counts.get(family, 0))
            for family in INTERACTION_FAMILY_ORDER
        },
        subtype_counts={
            family: dict(counts) for family, counts in subtype_counts.items()
        },
        residue_count=residue_count,
        hotspot_count=hotspot_count,
        total_score=sum(scores),
        mean_score=(sum(scores) / len(scores) if scores else None),
        minimum_distance=(min(distances) if distances else None),
        mean_distance=(sum(distances) / len(distances) if distances else None),
        maximum_distance=(max(distances) if distances else None),
    )


def consolidate_interaction_results(
    source: Any = None,
    *,
    context: Optional[AnalysisContext] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> InteractionConsolidationResult:
    """Consolidate all available interaction-stage outputs for one pose."""

    effective = resolve_interaction_consolidation_config(
        context.config if context is not None and config is None else config,
        overrides=overrides,
    )
    stage_outputs = collect_interaction_stage_outputs(source, context=context)
    records: List[CanonicalInteractionRecord] = []
    hotspots: List[Any] = []
    residues: List[Any] = []
    input_counts: Counter[str] = Counter()
    warnings_list: List[str] = []
    ordinal = 0
    for family in effective.families:
        stage_value = stage_outputs.get(family)
        if stage_value is None:
            if effective.include_empty_families:
                input_counts.setdefault(family, 0)
            continue
        pairs = interaction_output_interactions(family, stage_value)
        input_counts[family] += len(pairs)
        if len(records) + len(pairs) > effective.maximum_records:
            raise AnalysisValidationError(
                "Interaction consolidation exceeded the configured record limit.",
                stage=STAGE_CONSOLIDATION,
                details={
                    "maximum_records": effective.maximum_records,
                    "current_records": len(records),
                    "incoming_records": len(pairs),
                },
            )
        for source_index, (subtype, interaction) in enumerate(pairs):
            source_reference = (
                _stage_output_source_reference(
                    family,
                    subtype,
                    source_index,
                    stage_value,
                    interaction,
                )
                if effective.collect_source_references
                else None
            )
            records.append(
                build_canonical_interaction_record(
                    interaction,
                    family=family,
                    subtype=subtype,
                    source_reference=source_reference,
                    config=effective,
                    ordinal=ordinal,
                )
            )
            ordinal += 1
        if effective.collect_hotspots:
            hotspots.extend(interaction_output_hotspots(stage_value))
        if effective.collect_residues:
            residues.extend(interaction_output_residue_groups(stage_value))

    retained, duplicates = deduplicate_canonical_interactions(
        records,
        config=effective,
    )
    retained, cross_duplicates, overlap_groups = annotate_cross_family_overlaps(
        retained,
        policy=effective.cross_family_policy,
    )
    all_duplicates = (*duplicates, *cross_duplicates)
    rejected_count = sum(1 for item in duplicates if item.reason == "rejected")
    records_by_family: Dict[str, Tuple[CanonicalInteractionRecord, ...]] = {
        family: tuple(record for record in retained if record.family == family)
        for family in effective.families
    }
    unique_hotspots = _unique_objects_by_key(hotspots)
    unique_residues = _unique_objects_by_key(residues)
    summary = _record_summary_statistics(
        retained,
        input_counts=input_counts,
        duplicates=all_duplicates,
        rejected_count=rejected_count,
        overlap_groups=overlap_groups,
        residue_count=len(unique_residues),
        hotspot_count=len(unique_hotspots),
    )
    statistics = summary.to_dict() if effective.collect_statistics else {}
    metadata = {
        "schema": CONSOLIDATION_SCHEMA_NAME,
        "schema_version": CONSOLIDATION_SCHEMA_VERSION,
        "configuration_fingerprint": effective.fingerprint,
        "source_families": sorted(stage_outputs),
        "specialized_objects_preserved": True,
        "cross_family_semantics_preserved": (
            effective.cross_family_policy != CROSS_FAMILY_POLICY_DEDUPLICATE
        ),
    }
    if effective.cross_family_policy == CROSS_FAMILY_POLICY_DEDUPLICATE:
        warnings_list.append(
            "Cross-family deduplication can remove semantically distinct "
            "specialized interaction representations."
        )
    bundle = build_interaction_bundle_from_records(
        retained,
        hotspots=unique_hotspots,
        residues=unique_residues,
        statistics=statistics,
        metadata=metadata,
    )
    return InteractionConsolidationResult(
        bundle=bundle,
        records=retained,
        duplicates=all_duplicates,
        summary=summary,
        records_by_family=records_by_family,
        overlap_groups=overlap_groups,
        statistics=statistics,
        metadata=metadata,
        warnings=tuple(warnings_list),
        configuration=effective,
    )


# 16.10. DockModel fallback and context integration
# -----------------------------------------------------------------------------


def dock_model_interaction_sources(dock_model: Any) -> Dict[str, Any]:
    """Build lightweight family sources from fields attached to a DockModel."""

    if dock_model is None:
        return {}
    result: Dict[str, Any] = {}
    for family in INTERACTION_FAMILY_ORDER:
        field_name = interaction_family_to_dock_model_field(family)
        value = get_object_value(dock_model, field_name, default=None)
        if value is None:
            continue
        if family == INTERACTION_FAMILY_PI and isinstance(value, Mapping):
            result[family] = SimpleNamespace(
                interactions_by_subtype=value,
                interactions=tuple(
                    item
                    for values in value.values()
                    for item in normalize_object_sequence(values)
                ),
                result_type="dock_model_pi",
            )
        else:
            attribute = {
                INTERACTION_FAMILY_CONTACTS: "contacts",
                INTERACTION_FAMILY_HBONDS: "hydrogen_bonds",
                INTERACTION_FAMILY_HYDROPHOBIC: "interactions",
                INTERACTION_FAMILY_SALTBRIDGE: "interactions",
            }.get(family, "interactions")
            result[family] = SimpleNamespace(
                **{
                    attribute: tuple(normalize_object_sequence(value)),
                    "result_type": f"dock_model_{family}",
                }
            )
    return result


def consolidate_dock_model_interactions(
    dock_model: Any,
    *,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> InteractionConsolidationResult:
    """Consolidate interaction fields already attached to one DockModel."""

    return consolidate_interaction_results(
        dock_model_interaction_sources(dock_model),
        config=config,
        overrides=overrides,
    )


def _record_consolidation_context(
    context: AnalysisContext,
    stage_result: AnalysisStageResult,
) -> None:
    """Store consolidation outputs in the runtime context."""

    context.set_stage_data(CONSOLIDATION_STAGE_DATA_KEY, stage_result)
    if not isinstance(stage_result.value, InteractionConsolidationResult):
        return
    output = stage_result.value
    context.set_shared(CONSOLIDATION_SHARED_RESULT_KEY, output)
    context.set_shared(CONSOLIDATION_SHARED_BUNDLE_KEY, output.bundle)
    context.statistics[CONSOLIDATION_STATISTICS_KEY] = output.summary.to_dict()
    context.metadata[CONSOLIDATION_METADATA_KEY] = {
        "schema": CONSOLIDATION_SCHEMA_NAME,
        "schema_version": CONSOLIDATION_SCHEMA_VERSION,
        "configuration_fingerprint": (
            output.configuration.fingerprint
            if output.configuration is not None
            else None
        ),
        "interaction_count": output.interaction_count,
        "duplicate_count": output.summary.duplicate_count,
        "overlap_group_count": output.summary.overlap_group_count,
    }


def _consolidation_failure_should_raise(
    context: Optional[AnalysisContext],
    raise_on_error: Optional[bool],
) -> bool:
    """Resolve whether consolidation failures should propagate."""

    if raise_on_error is not None:
        return bool(raise_on_error)
    if context is None:
        return True
    return context.config.runtime.failure_policy == FAILURE_POLICY_STRICT


def execute_consolidation_stage(
    context: Optional[AnalysisContext] = None,
    *,
    source: Any = None,
    dock_model: Any = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    raise_on_error: Optional[bool] = None,
) -> AnalysisStageResult:
    """Execute the registered interaction-consolidation stage."""

    integrated_config = (
        context.config
        if context is not None and config is None
        else coerce_analysis_config(config)
    )
    stage_config = integrated_config.stage_config(STAGE_CONSOLIDATION)
    stage_result = AnalysisStageResult(
        stage=STAGE_CONSOLIDATION,
        required=stage_config.required,
    )
    if not stage_config.enabled:
        stage_result.skip("Interaction consolidation is disabled by configuration.")
        if context is not None:
            _record_consolidation_context(context, stage_result)
        return stage_result
    stage_result.start()
    try:
        if context is not None:
            context.raise_if_cancelled(stage=STAGE_CONSOLIDATION)
            context.set_current_stage(STAGE_CONSOLIDATION)
        effective_source = source
        if effective_source is None and context is not None:
            effective_source = context.stage_data
        if effective_source is None:
            effective_model = dock_model
            if effective_model is None and context is not None:
                effective_model = context.current_dock_model
            effective_source = dock_model_interaction_sources(effective_model)
        output = consolidate_interaction_results(
            effective_source,
            context=None,
            config=integrated_config,
            overrides=overrides,
        )
        if stage_config.validate_result:
            validate_interaction_consolidation_result(output, raise_on_error=True)
        stage_result.statistics = dict(output.statistics)
        stage_result.metadata.update(
            {
                "schema": CONSOLIDATION_SCHEMA_NAME,
                "schema_version": CONSOLIDATION_SCHEMA_VERSION,
                "configuration": (
                    output.configuration.to_dict()
                    if output.configuration is not None
                    else None
                ),
            }
        )
        stage_result.output_summary = output.summary.to_dict()
        stage_result.succeed(
            output,
            message="Interaction consolidation completed successfully.",
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisStageError(
                "Interaction consolidation failed.",
                stage=STAGE_CONSOLIDATION,
                cause=exc,
                details={"exception_type": type(exc).__name__},
            )
        stage_result.fail(
            wrapped,
            include_traceback=(
                context is not None
                and context.config.runtime.collect_diagnostics
            ),
        )
        if _consolidation_failure_should_raise(context, raise_on_error):
            raise wrapped from exc
    finally:
        if context is not None:
            _record_consolidation_context(context, stage_result)
            context.set_current_stage(None)
    return stage_result


# 16.11. Validation and summaries
# -----------------------------------------------------------------------------


def validate_canonical_interaction_record(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one canonical interaction record."""

    errors: List[str] = []
    if not isinstance(value, CanonicalInteractionRecord):
        errors.append("Value is not a CanonicalInteractionRecord.")
    else:
        if value.interaction is None:
            errors.append("Canonical interaction record has no native interaction.")
        if not value.identity_key:
            errors.append("Canonical interaction record has no identity key.")
        if not value.equivalence_key:
            errors.append("Canonical interaction record has no equivalence key.")
        if value.family not in INTERACTION_FAMILY_ORDER:
            errors.append("Canonical interaction record has an unknown family.")
        if value.distance is not None and not math.isfinite(value.distance):
            errors.append("Canonical interaction record has a non-finite distance.")
        if value.score is not None and not math.isfinite(value.score):
            errors.append("Canonical interaction record has a non-finite score.")
    result = tuple(errors)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Canonical interaction record validation failed.",
            stage=STAGE_CONSOLIDATION,
            details={"errors": list(result)},
        )
    return result


def validate_interaction_consolidation_result(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one complete interaction-consolidation result."""

    errors: List[str] = []
    if not isinstance(value, InteractionConsolidationResult):
        errors.append("Value is not an InteractionConsolidationResult.")
    else:
        for index, record in enumerate(value.records):
            for error in validate_canonical_interaction_record(record):
                errors.append(f"Record {index}: {error}")
        if value.summary.retained_count != len(value.records):
            errors.append("Retained summary count does not match canonical records.")
        expected_bundle_count = value.bundle.total_count
        if expected_bundle_count != len(value.records):
            errors.append("Interaction bundle count does not match canonical records.")
        known_record_ids = {record.record_id for record in value.records}
        if len(known_record_ids) != len(value.records):
            errors.append("Canonical record identifiers are not unique.")
        for family, records in value.records_by_family.items():
            if any(record.family != family for record in records):
                errors.append(f"Family record mapping is inconsistent for {family}.")
        for duplicate in value.duplicates:
            if duplicate.reason != "rejected" and not duplicate.retained_record_id:
                errors.append("A duplicate record has no retained representative.")
    result = tuple(errors)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Interaction consolidation result validation failed.",
            stage=STAGE_CONSOLIDATION,
            details={"errors": list(result)},
        )
    return result


def summarize_interaction_consolidation(value: Any) -> Dict[str, Any]:
    """Return a compact summary for consolidation or stage output."""

    if isinstance(value, AnalysisStageResult):
        result: Dict[str, Any] = {
            "stage": value.stage,
            "status": value.status.value,
            "duration_seconds": value.duration_seconds,
        }
        if isinstance(value.value, InteractionConsolidationResult):
            result.update(value.value.summary.to_dict())
        return result
    if isinstance(value, InteractionConsolidationResult):
        result = value.summary.to_dict()
        result.update(
            {
                "families": list(value.bundle.families),
                "warning_count": len(value.warnings),
                "configuration_fingerprint": (
                    value.configuration.fingerprint
                    if value.configuration is not None
                    else None
                ),
            }
        )
        return result
    if isinstance(value, InteractionAnalysisBundle):
        return {
            "families": list(value.families),
            "counts": value.counts(),
            "pi_counts": value.pi_counts(),
            "hotspot_count": len(value.hotspots),
            "residue_count": len(value.residues),
        }
    raise TypeError(
        "value must be an AnalysisStageResult, InteractionConsolidationResult "
        "or InteractionAnalysisBundle."
    )


# 16.12. Registry integration
# -----------------------------------------------------------------------------


def consolidation_stage_result_adapter(
    value: Any,
    **kwargs: Any,
) -> InteractionConsolidationResult:
    """Registry-compatible adapter for interaction-stage collections."""

    if isinstance(value, InteractionConsolidationResult):
        return value
    return consolidate_interaction_results(value, **kwargs)


def consolidation_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible validator for consolidation values."""

    if isinstance(value, AnalysisStageResult):
        if value.value is None:
            return () if value.status == StageStatus.SKIPPED else (
                "Consolidation stage result does not contain a value.",
            )
        value = value.value
    return validate_interaction_consolidation_result(value)


def register_consolidation_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the consolidation executor, adapter and validator."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_CONSOLIDATION)
    metadata = dict(definition.metadata)
    metadata.update(
        {
            "schema": CONSOLIDATION_SCHEMA_NAME,
            "schema_version": CONSOLIDATION_SCHEMA_VERSION,
            "result_type": CONSOLIDATION_RESULT_TYPE,
            "preserves_native_objects": True,
            "supports_cross_family_overlap_annotation": True,
            "supports_structural_deduplication": True,
        }
    )
    updated = replace(
        definition,
        executor=execute_consolidation_stage,
        result_adapter=consolidation_stage_result_adapter,
        validator=consolidation_stage_validator,
        metadata=metadata,
    )
    target_registry.replace(updated)
    return updated


def consolidation_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the consolidation stage adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_CONSOLIDATION)
    return bool(
        definition is not None
        and definition.executor is execute_consolidation_stage
        and definition.result_adapter is consolidation_stage_result_adapter
        and definition.validator is consolidation_stage_validator
    )


# 16.13. Convention validation
# -----------------------------------------------------------------------------


def validate_interaction_consolidation_conventions() -> Dict[str, Any]:
    """Validate consolidation configuration, records, deduplication and registry."""

    failures: List[str] = []
    if canonicalize_deduplication_mode("structural") != DEDUPLICATION_MODE_CANONICAL:
        failures.append("Canonical deduplication alias resolution failed.")
    if canonicalize_cross_family_policy("mark") != CROSS_FAMILY_POLICY_ANNOTATE:
        failures.append("Cross-family policy alias resolution failed.")
    config = InteractionConsolidationConfig.from_mapping(
        {
            "family": ("contacts", "hbond", "hydrophobic", "pi", "salt_bridge"),
            "deduplicate": "structural",
            "cross_family": "mark",
            "rejected": False,
            "distance_precision": 2,
        }
    )
    if config.families != INTERACTION_FAMILY_ORDER:
        failures.append("Interaction family canonicalization failed.")
    if len(config.fingerprint) != 64:
        failures.append("Consolidation configuration fingerprint is invalid.")

    @dataclass
    class FakeResidue:
        name: str
        number: int
        chain_id: str

    @dataclass
    class FakeAtom:
        name: str
        residue: FakeResidue
        index: int

    @dataclass
    class FakeGeometry:
        distance: float
        contact_compatible: bool = True

    @dataclass
    class FakeContact:
        atom_1: FakeAtom
        atom_2: FakeAtom
        geometry: FakeGeometry
        classification: str = "close"
        metadata: Dict[str, Any] = field(default_factory=dict)

    receptor_residue = FakeResidue("ALA", 10, "A")
    ligand_residue = FakeResidue("LIG", 1, "L")
    receptor_atom = FakeAtom("CB", receptor_residue, 1)
    ligand_atom = FakeAtom("C1", ligand_residue, 2)
    contact_1 = FakeContact(ligand_atom, receptor_atom, FakeGeometry(3.2))
    contact_2 = FakeContact(ligand_atom, receptor_atom, FakeGeometry(3.2))
    contact_output = SimpleNamespace(
        contacts=(contact_1, contact_2),
        residue_contacts=(),
        result_type="contact_stage_output",
        attached=False,
        reused=False,
    )

    @dataclass
    class FakeHydrophobic:
        receptor_atom: FakeAtom
        ligand_atom: FakeAtom
        distance: float
        interaction_type: str = "aliphatic"
        classification: str = "favorable"
        strength: str = "moderate"
        score: float = 0.8
        receptor_residue: Optional[FakeResidue] = None
        accepted: bool = True

    hydrophobic = FakeHydrophobic(
        receptor_atom,
        ligand_atom,
        3.2,
        receptor_residue=receptor_residue,
    )
    hydrophobic_output = SimpleNamespace(
        interactions=(hydrophobic,),
        residue_groups=(),
        hotspots=(),
        result_type="hydrophobic_stage_output",
        attached=False,
        reused=False,
    )
    result = consolidate_interaction_results(
        {
            INTERACTION_FAMILY_CONTACTS: contact_output,
            INTERACTION_FAMILY_HYDROPHOBIC: hydrophobic_output,
        },
        overrides={
            "deduplication_mode": "canonical",
            "cross_family_policy": "annotate",
        },
    )
    if result.summary.input_count != 3:
        failures.append("Consolidation input count is incorrect.")
    if result.summary.retained_count != 2:
        failures.append("Within-family deduplication did not retain two records.")
    if result.summary.duplicate_count != 1:
        failures.append("Within-family duplicate count is incorrect.")
    if result.bundle.count(INTERACTION_FAMILY_CONTACTS) != 1:
        failures.append("Contact bundle count is incorrect.")
    if result.bundle.count(INTERACTION_FAMILY_HYDROPHOBIC) != 1:
        failures.append("Hydrophobic bundle count is incorrect.")
    if validate_interaction_consolidation_result(result):
        failures.append("A valid consolidation result did not validate.")
    serialized = json.loads(json.dumps(result.to_dict()))
    if serialized["summary"]["retained_count"] != 2:
        failures.append("Consolidation JSON conversion failed.")

    registry = create_default_stage_registry()
    register_consolidation_stage_adapter(registry=registry)
    if not consolidation_stage_adapter_registered(registry=registry):
        failures.append("Consolidation adapter registration failed.")
    definition = registry.require(STAGE_CONSOLIDATION)
    if definition.executor is not execute_consolidation_stage:
        failures.append("Consolidation executor registration failed.")

    dock_model = SimpleNamespace(
        contacts=[contact_1],
        hbonds=[],
        hydrophobic=[hydrophobic],
        pi={},
        saltbridge=[],
    )
    dock_result = consolidate_dock_model_interactions(dock_model)
    if dock_result.interaction_count != 2:
        failures.append("DockModel fallback consolidation failed.")

    integrated = AnalysisConfig(
        stage_configs={
            STAGE_CONSOLIDATION: AnalysisStageConfig(
                enabled=True,
                required=True,
                validate_result=True,
                parameters={"deduplication_mode": "canonical"},
            )
        }
    )
    request = AnalysisRequest(config=integrated, dock_models=(dock_model,))
    context = AnalysisContext(
        request=request,
        dock_models=[dock_model],
        current_pose_index=0,
    )
    context.set_stage_data(INTERACTION_FAMILY_CONTACTS, contact_output)
    context.set_stage_data(INTERACTION_FAMILY_HYDROPHOBIC, hydrophobic_output)
    stage_result = execute_consolidation_stage(context, raise_on_error=True)
    if not stage_result.succeeded:
        failures.append("Consolidation stage executor did not succeed.")
    if context.get_shared(CONSOLIDATION_SHARED_BUNDLE_KEY) is None:
        failures.append("Consolidated interaction bundle was not stored in context.")
    if failures:
        raise RuntimeError(
            "Interaction consolidation convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": CONSOLIDATION_SCHEMA_NAME,
        "schema_version": CONSOLIDATION_SCHEMA_VERSION,
        "supported_families": len(INTERACTION_FAMILY_ORDER),
        "deduplication_modes": len(DEDUPLICATION_MODES),
        "cross_family_policies": len(CROSS_FAMILY_POLICIES),
        "validated_cases": 26,
    }


