# 17.2. Configuration normalization
# -----------------------------------------------------------------------------


def canonicalize_scoring_source(value: Any) -> str:
    """Return one canonical scoring interaction-source name."""

    token = _normalize_convention_token(value, field_name="scoring source")
    canonical = SCORING_SOURCE_ALIASES.get(token, token)
    if canonical not in SCORING_SOURCE_ORDER:
        raise AnalysisConfigurationError(
            f"Unsupported scoring interaction source: {value!r}.",
            stage=STAGE_SCORING,
            details={"supported": list(SCORING_SOURCE_ORDER)},
        )
    return canonical


def canonicalize_scoring_sources(value: Any) -> Tuple[str, ...]:
    """Normalize and deduplicate scoring interaction-source names."""

    if value is None:
        return SCORING_SOURCE_ORDER
    raw_items = _coerce_config_sequence(
        value,
        field_name="scoring.interaction_sources",
        allow_none=True,
    )
    result: List[str] = []
    seen: Set[str] = set()
    for item in raw_items:
        canonical = canonicalize_scoring_source(item)
        if canonical not in seen:
            result.append(canonical)
            seen.add(canonical)
    if not result:
        raise AnalysisConfigurationError(
            "At least one scoring interaction source must be enabled.",
            stage=STAGE_SCORING,
        )
    if len(result) > SCORING_MAX_INTERACTION_SOURCES:
        raise AnalysisConfigurationError(
            "The scoring interaction-source limit was exceeded.",
            stage=STAGE_SCORING,
        )
    return tuple(result)


def canonicalize_scoring_attachment_mode(value: Any) -> str:
    """Return a canonical DockModel scoring-attachment mode."""

    token = _normalize_convention_token(value, field_name="attachment mode")
    canonical = SCORING_ATTACHMENT_MODE_ALIASES.get(token, token)
    if canonical not in SCORING_ATTACHMENT_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported scoring attachment mode: {value!r}.",
            stage=STAGE_SCORING,
            details={"supported": list(SCORING_ATTACHMENT_MODES)},
        )
    return canonical


def canonicalize_scoring_explanation_level(value: Any) -> str:
    """Return a canonical explainability detail level."""

    token = _normalize_convention_token(value, field_name="explanation level")
    canonical = SCORING_EXPLANATION_LEVEL_ALIASES.get(token, token)
    if canonical not in SCORING_EXPLANATION_LEVELS:
        raise AnalysisConfigurationError(
            f"Unsupported scoring explanation level: {value!r}.",
            stage=STAGE_SCORING,
            details={"supported": list(SCORING_EXPLANATION_LEVELS)},
        )
    return canonical


def _scoring_config_value(value: Any) -> Any:
    """Return a defensive immutable value suitable for adapter configuration."""

    return _freeze_config_value(value)


@dataclass(frozen=True)
class ScoringIntegrationConfig:
    """Orchestration options for scoring and explainability integration."""

    attach: bool = True
    reuse_existing: bool = True
    preserve_previous: bool = True
    validate_result: bool = True
    build_explainability: bool = True
    explanation_level: str = "standard"
    include_evidence: bool = True
    include_trace: bool = True
    include_counterfactuals: bool = True
    include_limitations: bool = True
    include_zero_contributions: bool = False
    include_metadata: bool = True
    strict_explainability: bool = False
    use_consolidated_interactions: bool = True
    include_external_scores: bool = False
    external_scores: Any = None
    continue_on_error: bool = True
    history_limit: int = SCORING_DEFAULT_HISTORY_LIMIT
    rollback_on_error: bool = True
    strict_identity: bool = False
    attachment_mode: str = "replace"
    interaction_sources: Tuple[str, ...] = SCORING_SOURCE_ORDER
    profile: Any = None
    scoring_config: Any = None
    integration_options: Any = None
    explainability_options: Any = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        for name in (
            "attach",
            "reuse_existing",
            "preserve_previous",
            "validate_result",
            "build_explainability",
            "include_evidence",
            "include_trace",
            "include_counterfactuals",
            "include_limitations",
            "include_zero_contributions",
            "include_metadata",
            "strict_explainability",
            "use_consolidated_interactions",
            "include_external_scores",
            "continue_on_error",
            "rollback_on_error",
            "strict_identity",
        ):
            object.__setattr__(
                self,
                name,
                _coerce_config_bool(
                    getattr(self, name),
                    field_name=f"scoring.{name}",
                ),
            )
        object.__setattr__(
            self,
            "explanation_level",
            canonicalize_scoring_explanation_level(self.explanation_level),
        )
        object.__setattr__(
            self,
            "attachment_mode",
            canonicalize_scoring_attachment_mode(self.attachment_mode),
        )
        object.__setattr__(
            self,
            "interaction_sources",
            canonicalize_scoring_sources(self.interaction_sources),
        )
        object.__setattr__(
            self,
            "history_limit",
            _coerce_config_int(
                self.history_limit,
                field_name="scoring.history_limit",
                minimum=0,
                maximum=SCORING_MAX_HISTORY_LIMIT,
            ),
        )
        if not isinstance(self.metadata, Mapping):
            raise AnalysisConfigurationError(
                "scoring.metadata must be a mapping.",
                stage=STAGE_SCORING,
            )
        object.__setattr__(self, "metadata", _freeze_config_value(self.metadata))
        object.__setattr__(self, "external_scores", _scoring_config_value(self.external_scores))
        object.__setattr__(self, "profile", _scoring_config_value(self.profile))
        object.__setattr__(
            self,
            "scoring_config",
            _scoring_config_value(self.scoring_config),
        )
        object.__setattr__(
            self,
            "integration_options",
            _scoring_config_value(self.integration_options),
        )
        object.__setattr__(
            self,
            "explainability_options",
            _scoring_config_value(self.explainability_options),
        )

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "ScoringIntegrationConfig":
        """Create adapter configuration from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Scoring integration configuration must be a mapping.",
                stage=STAGE_SCORING,
            )
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        unknown: Dict[str, Any] = {}
        for raw_key, value in values.items():
            token = _normalize_convention_token(
                raw_key,
                field_name="scoring configuration key",
            )
            target = SCORING_CONFIG_ALIASES.get(token, token)
            if target in allowed:
                if target in normalized:
                    raise AnalysisConfigurationError(
                        f"Duplicate scoring configuration field {target!r}.",
                        stage=STAGE_SCORING,
                    )
                normalized[target] = value
            else:
                unknown[str(raw_key)] = value
        if unknown and strict:
            raise AnalysisConfigurationError(
                "Unknown scoring integration configuration fields were provided.",
                stage=STAGE_SCORING,
                details={"fields": sorted(unknown)},
            )
        if unknown:
            native = normalized.get("scoring_config")
            if native is None:
                normalized["scoring_config"] = unknown
            elif isinstance(native, Mapping):
                merged = dict(native)
                merged.update(unknown)
                normalized["scoring_config"] = merged
        return cls(**normalized)

    @property
    def fingerprint(self) -> str:
        """Return a deterministic configuration fingerprint."""

        payload = json.dumps(
            self.to_dict(include_native_objects=False),
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
        return sha256(payload).hexdigest()

    def to_dict(self, *, include_native_objects: bool = False) -> Dict[str, Any]:
        """Return a serialization-safe configuration mapping."""

        result = {
            "attach": self.attach,
            "reuse_existing": self.reuse_existing,
            "preserve_previous": self.preserve_previous,
            "validate_result": self.validate_result,
            "build_explainability": self.build_explainability,
            "explanation_level": self.explanation_level,
            "include_evidence": self.include_evidence,
            "include_trace": self.include_trace,
            "include_counterfactuals": self.include_counterfactuals,
            "include_limitations": self.include_limitations,
            "include_zero_contributions": self.include_zero_contributions,
            "include_metadata": self.include_metadata,
            "strict_explainability": self.strict_explainability,
            "use_consolidated_interactions": self.use_consolidated_interactions,
            "include_external_scores": self.include_external_scores,
            "continue_on_error": self.continue_on_error,
            "history_limit": self.history_limit,
            "rollback_on_error": self.rollback_on_error,
            "strict_identity": self.strict_identity,
            "attachment_mode": self.attachment_mode,
            "interaction_sources": list(self.interaction_sources),
            "metadata": to_json_compatible(dict(self.metadata)),
        }
        if include_native_objects:
            result.update(
                {
                    "external_scores": self.external_scores,
                    "profile": self.profile,
                    "scoring_config": self.scoring_config,
                    "integration_options": self.integration_options,
                    "explainability_options": self.explainability_options,
                }
            )
        else:
            result.update(
                {
                    "external_scores": to_json_compatible(self.external_scores),
                    "profile": to_json_compatible(self.profile),
                    "scoring_config": to_json_compatible(self.scoring_config),
                    "integration_options": to_json_compatible(
                        self.integration_options
                    ),
                    "explainability_options": to_json_compatible(
                        self.explainability_options
                    ),
                }
            )
        return result


def _scoring_mapping_copy(value: Any) -> Dict[str, Any]:
    """Return a plain mapping copy or an empty mapping."""

    if value is None:
        return {}
    if isinstance(value, Mapping):
        return dict(value)
    if is_dataclass(value) and not isinstance(value, type):
        return {item.name: getattr(value, item.name) for item in fields(value)}
    return {}


def resolve_scoring_integration_config(
    config: Optional[AnalysisConfigLike] = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
) -> ScoringIntegrationConfig:
    """Resolve scoring settings from integrated, module and stage configuration."""

    integrated = coerce_analysis_config(config)
    stage_config = integrated.stage_config(STAGE_SCORING)
    merged: Dict[str, Any] = {}
    module_config = integrated.module_config(SCORING_MODULE_NAME)
    if isinstance(module_config, ScoringIntegrationConfig):
        merged.update(module_config.to_dict(include_native_objects=True))
    elif isinstance(module_config, Mapping):
        adapter_values = module_config.get("adapter")
        if isinstance(adapter_values, Mapping):
            merged.update(adapter_values)
        merged.update(
            {
                key: value
                for key, value in module_config.items()
                if key != "adapter"
            }
        )
    elif module_config is not None:
        merged["profile"] = module_config
    merged.update(dict(stage_config.parameters))
    if overrides:
        merged.update(dict(overrides))
    merged.setdefault("attach", stage_config.attach_results)
    merged.setdefault("reuse_existing", stage_config.reuse_result)
    merged.setdefault("validate_result", stage_config.validate_result)
    merged.setdefault("preserve_previous", integrated.runtime.record_history)
    merged.setdefault("history_limit", integrated.runtime.max_history)
    merged.setdefault(
        "continue_on_error",
        integrated.runtime.failure_policy != FAILURE_POLICY_STRICT,
    )
    merged.setdefault(
        "attachment_mode",
        integrated.runtime.attachment_policy
        if integrated.runtime.attachment_policy in SCORING_ATTACHMENT_MODES
        else "replace",
    )
    return ScoringIntegrationConfig.from_mapping(merged, strict=False)


