@dataclass(frozen=True)
class ScoringStageTarget:
    """Resolved DockModel and identifiers for one scoring operation."""

    dock_model: Any
    pose_index: Optional[int]
    dock_model_identifier: str
    pose_identifier: str
    model_identifier: str
    ligand_identifier: str

    def to_dict(self, *, include_object: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe target mapping."""

        result: Dict[str, Any] = {
            "pose_index": self.pose_index,
            "dock_model_identifier": self.dock_model_identifier,
            "pose_identifier": self.pose_identifier,
            "model_identifier": self.model_identifier,
            "ligand_identifier": self.ligand_identifier,
            "dock_model": describe_object(self.dock_model).to_dict(),
        }
        if include_object:
            result["dock_model_object"] = self.dock_model
        return result


