SINGLE_POSE_RUN_RESULT_KEY: Final[str] = "single_pose_run_result"
SINGLE_POSE_STAGE_TRACE_KEY: Final[str] = "single_pose_stage_trace"
SINGLE_POSE_METADATA_KEY: Final[str] = "single_pose_orchestration"
SINGLE_POSE_STATISTICS_KEY: Final[str] = "single_pose_orchestration"

SINGLE_POSE_MANAGED_STAGES: Final[FrozenSet[str]] = frozenset(
    {
        STAGE_INPUT_RESOLUTION,
        STAGE_MODEL_PREPARATION,
        STAGE_VALIDATION,
        STAGE_FINALIZATION,
    }
)
SINGLE_POSE_NON_APPLICABLE_STAGES: Final[FrozenSet[str]] = frozenset(
    {STAGE_CONSENSUS}
)
SINGLE_POSE_DEFERRED_OUTPUT_STAGES: Final[FrozenSet[str]] = frozenset(
    OUTPUT_STAGES
)
SINGLE_POSE_DEPENDENCY_SUCCESS_STATUSES: Final[FrozenSet[StageStatus]] = frozenset(
    {StageStatus.SUCCEEDED, StageStatus.PARTIAL, StageStatus.SKIPPED}
)
SINGLE_POSE_ABORT_STATUSES: Final[FrozenSet[StageStatus]] = frozenset(
    {StageStatus.FAILED, StageStatus.CANCELLED, StageStatus.BLOCKED}
)

DEFAULT_SINGLE_POSE_INCLUDE_DEPENDENCIES: Final[bool] = True
DEFAULT_SINGLE_POSE_INCLUDE_ORDERING_PREDECESSORS: Final[bool] = True
DEFAULT_SINGLE_POSE_INSPECT_CAPABILITIES: Final[bool] = True
DEFAULT_SINGLE_POSE_LOAD_CAPABILITIES: Final[bool] = False
DEFAULT_SINGLE_POSE_DROP_UNAVAILABLE_OPTIONAL_STAGES: Final[bool] = True
DEFAULT_SINGLE_POSE_REQUIRE_REGISTERED_EXECUTORS: Final[bool] = False
DEFAULT_SINGLE_POSE_ALLOW_DEFERRED_STAGES: Final[bool] = True
DEFAULT_SINGLE_POSE_STOP_ON_REQUIRED_FAILURE: Final[bool] = True
DEFAULT_SINGLE_POSE_STOP_ON_ANY_FAILURE: Final[bool] = False
DEFAULT_SINGLE_POSE_RAISE_ON_ERROR: Final[bool] = False
DEFAULT_SINGLE_POSE_VALIDATE_INPUT: Final[bool] = True
DEFAULT_SINGLE_POSE_VALIDATE_RESULT: Final[bool] = True
DEFAULT_SINGLE_POSE_PRESERVE_CONTEXT: Final[bool] = True


class SinglePoseStageAction(str, Enum):
    """Action selected by the single-pose stage dispatcher."""

    EXECUTE = "execute"
    SKIP = "skip"
    BLOCK = "block"
    CANCEL = "cancel"
    DEFER = "defer"


# 18.2. Execution options
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class SinglePoseExecutionOptions:
    """Immutable controls for one complete single-pose pipeline run."""

    requested_stages: Tuple[str, ...] = ()
    include_dependencies: bool = DEFAULT_SINGLE_POSE_INCLUDE_DEPENDENCIES
    include_ordering_predecessors: bool = (
        DEFAULT_SINGLE_POSE_INCLUDE_ORDERING_PREDECESSORS
    )
    inspect_capabilities: bool = DEFAULT_SINGLE_POSE_INSPECT_CAPABILITIES
    load_capabilities: bool = DEFAULT_SINGLE_POSE_LOAD_CAPABILITIES
    drop_unavailable_optional_stages: bool = (
        DEFAULT_SINGLE_POSE_DROP_UNAVAILABLE_OPTIONAL_STAGES
    )
    require_registered_executors: bool = (
        DEFAULT_SINGLE_POSE_REQUIRE_REGISTERED_EXECUTORS
    )
    allow_deferred_stages: bool = DEFAULT_SINGLE_POSE_ALLOW_DEFERRED_STAGES
    stop_on_required_failure: bool = DEFAULT_SINGLE_POSE_STOP_ON_REQUIRED_FAILURE
    stop_on_any_failure: bool = DEFAULT_SINGLE_POSE_STOP_ON_ANY_FAILURE
    raise_on_error: bool = DEFAULT_SINGLE_POSE_RAISE_ON_ERROR
    validate_input: bool = DEFAULT_SINGLE_POSE_VALIDATE_INPUT
    validate_result: bool = DEFAULT_SINGLE_POSE_VALIDATE_RESULT
    preserve_context: bool = DEFAULT_SINGLE_POSE_PRESERVE_CONTEXT
    stage_overrides: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        stages = canonicalize_stage_sequence(
            self.requested_stages,
            strict=True,
            unique=True,
            sort=False,
        )
        object.__setattr__(self, "requested_stages", stages)

        for field_name in (
            "include_dependencies",
            "include_ordering_predecessors",
            "inspect_capabilities",
            "load_capabilities",
            "drop_unavailable_optional_stages",
            "require_registered_executors",
            "allow_deferred_stages",
            "stop_on_required_failure",
            "stop_on_any_failure",
            "raise_on_error",
            "validate_input",
            "validate_result",
            "preserve_context",
        ):
            object.__setattr__(self, field_name, bool(getattr(self, field_name)))

        if not isinstance(self.stage_overrides, Mapping):
            raise AnalysisConfigurationError(
                "single-pose stage_overrides must be a mapping."
            )
        normalized_overrides: Dict[str, Mapping[str, Any]] = {}
        for raw_stage, raw_values in self.stage_overrides.items():
            stage = canonicalize_stage_name(raw_stage)
            if raw_values is None:
                normalized_overrides[stage] = MappingProxyType({})
                continue
            if not isinstance(raw_values, Mapping):
                raise AnalysisConfigurationError(
                    f"Overrides for stage {stage!r} must be a mapping."
                )
            normalized_overrides[stage] = MappingProxyType(dict(raw_values))
        object.__setattr__(
            self,
            "stage_overrides",
            MappingProxyType(normalized_overrides),
        )
        if not isinstance(self.metadata, Mapping):
            raise AnalysisConfigurationError(
                "single-pose metadata must be a mapping."
            )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(dict(self.metadata)),
        )

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "SinglePoseExecutionOptions":
        """Create options from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Single-pose execution options must be a mapping."
            )
        aliases = {
            "stages": "requested_stages",
            "requested": "requested_stages",
            "dependencies": "include_dependencies",
            "ordering": "include_ordering_predecessors",
            "inspect": "inspect_capabilities",
            "load": "load_capabilities",
            "drop_unavailable": "drop_unavailable_optional_stages",
            "require_executors": "require_registered_executors",
            "allow_deferred": "allow_deferred_stages",
            "stop_required": "stop_on_required_failure",
            "stop_any": "stop_on_any_failure",
            "raise": "raise_on_error",
            "validate_inputs": "validate_input",
            "validate_results": "validate_result",
            "overrides": "stage_overrides",
        }
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        unknown: List[str] = []
        for raw_key, value in values.items():
            token = _normalize_convention_token(
                raw_key,
                field_name="single-pose option",
            )
            key = aliases.get(token, token)
            if key not in allowed:
                unknown.append(str(raw_key))
                continue
            if key in normalized:
                raise AnalysisConfigurationError(
                    f"Duplicate single-pose option {key!r}."
                )
            normalized[key] = value
        if unknown and strict:
            raise AnalysisConfigurationError(
                "Unknown single-pose options: " + ", ".join(sorted(unknown)) + "."
            )
        return cls(**normalized)

    def stage_override(self, stage: Any) -> Mapping[str, Any]:
        """Return immutable overrides for one stage."""

        canonical = canonicalize_stage_name(stage)
        return self.stage_overrides.get(canonical, MappingProxyType({}))

    @property
    def fingerprint(self) -> str:
        """Return a stable SHA-256 options fingerprint."""

        payload = json.dumps(
            self.to_dict(),
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        return sha256(payload.encode("utf-8")).hexdigest()

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready options mapping."""

        return {
            "requested_stages": list(self.requested_stages),
            "include_dependencies": self.include_dependencies,
            "include_ordering_predecessors": (
                self.include_ordering_predecessors
            ),
            "inspect_capabilities": self.inspect_capabilities,
            "load_capabilities": self.load_capabilities,
            "drop_unavailable_optional_stages": (
                self.drop_unavailable_optional_stages
            ),
            "require_registered_executors": (
                self.require_registered_executors
            ),
            "allow_deferred_stages": self.allow_deferred_stages,
            "stop_on_required_failure": self.stop_on_required_failure,
            "stop_on_any_failure": self.stop_on_any_failure,
            "raise_on_error": self.raise_on_error,
            "validate_input": self.validate_input,
            "validate_result": self.validate_result,
            "preserve_context": self.preserve_context,
            "stage_overrides": {
                stage: dict(values)
                for stage, values in self.stage_overrides.items()
            },
            "metadata": dict(self.metadata),
        }


SinglePoseExecutionOptionsLike: TypeAlias = Optional[
    Union[SinglePoseExecutionOptions, Mapping[str, Any]]
]


def coerce_single_pose_execution_options(
    value: SinglePoseExecutionOptionsLike = None,
) -> SinglePoseExecutionOptions:
    """Coerce options into :class:`SinglePoseExecutionOptions`."""

    if value is None:
        return SinglePoseExecutionOptions()
    if isinstance(value, SinglePoseExecutionOptions):
        return value
    if isinstance(value, Mapping):
        return SinglePoseExecutionOptions.from_mapping(value)
    raise AnalysisConfigurationError(
        "Single-pose options must be a mapping or SinglePoseExecutionOptions."
    )


# 18.3. Stage trace and integrated output
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class SinglePoseStageTrace:
    """Immutable trace entry for one planned stage."""

    stage: str
    action: SinglePoseStageAction
    status: StageStatus
    position: int
    wave: int
    required: bool
    requested: bool
    dependency_included: bool
    dependencies: Tuple[str, ...] = ()
    blocked_by: Tuple[str, ...] = ()
    reason: Optional[str] = None
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "stage", canonicalize_stage_name(self.stage))
        object.__setattr__(self, "action", SinglePoseStageAction(self.action))
        object.__setattr__(self, "status", canonicalize_stage_status(self.status))
        object.__setattr__(self, "position", max(0, int(self.position)))
        object.__setattr__(self, "wave", max(0, int(self.wave)))
        object.__setattr__(self, "required", bool(self.required))
        object.__setattr__(self, "requested", bool(self.requested))
        object.__setattr__(
            self,
            "dependency_included",
            bool(self.dependency_included),
        )
        object.__setattr__(
            self,
            "dependencies",
            canonicalize_stage_sequence(
                self.dependencies,
                strict=True,
                unique=True,
                sort=False,
            ),
        )
        object.__setattr__(
            self,
            "blocked_by",
            canonicalize_stage_sequence(
                self.blocked_by,
                strict=True,
                unique=True,
                sort=False,
            ),
        )

    @classmethod
    def from_result(
        cls,
        entry: StagePlanEntry,
        result: AnalysisStageResult,
        *,
        action: SinglePoseStageAction,
        reason: Optional[str] = None,
    ) -> "SinglePoseStageTrace":
        """Create one trace entry from a plan entry and stage result."""

        return cls(
            stage=entry.stage,
            action=action,
            status=result.status,
            position=entry.position,
            wave=entry.wave,
            required=entry.required,
            requested=entry.requested,
            dependency_included=entry.dependency_included,
            dependencies=entry.dependencies,
            blocked_by=entry.blocked_by,
            reason=reason or result.skipped_reason,
            started_at=result.started_at,
            finished_at=result.finished_at,
            duration_seconds=result.duration_seconds,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready trace mapping."""

        return {
            "stage": self.stage,
            "action": self.action.value,
            "status": self.status.value,
            "position": self.position,
            "wave": self.wave,
            "required": self.required,
            "requested": self.requested,
            "dependency_included": self.dependency_included,
            "dependencies": list(self.dependencies),
            "blocked_by": list(self.blocked_by),
            "reason": self.reason,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
        }


@dataclass
class SinglePoseAnalysisOutput:
    """Complete output of one single-pose orchestration run."""

    request: AnalysisRequest
    context: AnalysisContext
    plan: AnalysisExecutionPlan
    pose_result: PoseAnalysisResult
    run_result: AnalysisRunResult
    resolved_input: Optional[ResolvedAnalysisInput] = None
    preparation: Optional[ModelPreparationResult] = None
    stage_trace: List[SinglePoseStageTrace] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)
    options: SinglePoseExecutionOptions = field(
        default_factory=SinglePoseExecutionOptions
    )
    result_type: str = SINGLE_POSE_RESULT_TYPE

    def __post_init__(self) -> None:
        if not isinstance(self.request, AnalysisRequest):
            self.request = coerce_analysis_request(self.request)
        if not isinstance(self.context, AnalysisContext):
            raise TypeError("context must be an AnalysisContext instance.")
        if not isinstance(self.plan, AnalysisExecutionPlan):
            raise TypeError("plan must be an AnalysisExecutionPlan instance.")
        if not isinstance(self.pose_result, PoseAnalysisResult):
            self.pose_result = coerce_pose_analysis_result(self.pose_result)
        if not isinstance(self.run_result, AnalysisRunResult):
            raise TypeError("run_result must be an AnalysisRunResult instance.")
        self.stage_trace = list(self.stage_trace)
        self.warnings = unique_preserving_order(self.warnings)
        self.errors = unique_preserving_order(self.errors)
        self.metadata = dict(self.metadata)
        self.options = coerce_single_pose_execution_options(self.options)

    @property
    def status(self) -> AnalysisStatus:
        """Return the final pose status."""

        return self.pose_result.status

    @property
    def succeeded(self) -> bool:
        """Return whether the single-pose run succeeded."""

        return self.status == AnalysisStatus.SUCCEEDED

    @property
    def has_partial_results(self) -> bool:
        """Return whether the run completed partially."""

        return self.status == AnalysisStatus.PARTIAL

    @property
    def failed(self) -> bool:
        """Return whether the run failed."""

        return self.status == AnalysisStatus.FAILED

    @property
    def cancelled(self) -> bool:
        """Return whether the run was cancelled."""

        return self.status == AnalysisStatus.CANCELLED

    @property
    def stage_results(self) -> Mapping[str, AnalysisStageResult]:
        """Return the ordered pose stage results."""

        return self.pose_result.stage_results

    @property
    def completed_stage_count(self) -> int:
        """Return the number of terminal stage results."""

        return sum(
            1 for result in self.stage_results.values() if result.is_terminal
        )

    @property
    def failed_stages(self) -> Tuple[str, ...]:
        """Return failed, blocked or cancelled stage names."""

        return tuple(
            stage
            for stage, result in self.stage_results.items()
            if result.status in SINGLE_POSE_ABORT_STATUSES
        )

    def summary(self) -> Dict[str, Any]:
        """Return a concise orchestration summary."""

        return {
            "schema": SINGLE_POSE_SCHEMA_NAME,
            "schema_version": SINGLE_POSE_SCHEMA_VERSION,
            "run_id": self.context.run_id,
            "request_id": self.request.request_id,
            "pose_id": self.pose_result.pose_id,
            "name": self.pose_result.name,
            "status": self.status.value,
            "plan_id": self.plan.plan_id,
            "stage_count": len(self.stage_results),
            "completed_stage_count": self.completed_stage_count,
            "failed_stages": list(self.failed_stages),
            "interaction_count": self.pose_result.interaction_count,
            "warning_count": len(self.warnings),
            "error_count": len(self.errors),
            "duration_seconds": self.pose_result.duration_seconds,
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready output mapping."""

        return {
            "schema": SINGLE_POSE_SCHEMA_NAME,
            "schema_version": SINGLE_POSE_SCHEMA_VERSION,
            "result_type": self.result_type,
            "status": self.status.value,
            "request": self.request.to_dict(include_objects=include_objects),
            "context": {
                "run_id": self.context.run_id,
                "request_id": self.context.request_id,
                "mode": self.context.mode,
                "status": self.context.status.value,
                "current_stage": self.context.current_stage,
                "current_pose_index": self.context.current_pose_index,
                "pose_count": self.context.pose_count,
                "started_at": self.context.started_at,
                "cancelled": self.context.is_cancelled(),
                "config": self.context.config.to_dict(),
                "statistics": to_json_compatible(self.context.statistics),
                "files": to_json_compatible(self.context.files),
                "metadata": to_json_compatible(self.context.metadata),
            },
            "plan": self.plan.to_dict(),
            "pose_result": self.pose_result.to_dict(
                include_objects=include_objects
            ),
            "run_result": {
                "run_id": self.run_result.run_id,
                "request_id": self.run_result.request_id,
                "name": self.run_result.name,
                "mode": self.run_result.mode,
                "status": self.run_result.status.value,
                "result_type": self.run_result.result_type,
                "pose_id": self.pose_result.pose_id,
                "stage_results": {
                    stage: result.to_dict()
                    for stage, result in self.run_result.stage_results.items()
                },
                "statistics": to_json_compatible(self.run_result.statistics),
                "files": to_json_compatible(self.run_result.files),
                "metadata": to_json_compatible(self.run_result.metadata),
                "provenance": to_json_compatible(self.run_result.provenance),
                "timings": to_json_compatible(self.run_result.timings),
                "diagnostics": self.run_result.diagnostics.to_dict(),
                "started_at": self.run_result.started_at,
                "finished_at": self.run_result.finished_at,
                "duration_seconds": self.run_result.duration_seconds,
            },
            "resolved_input": (
                self.resolved_input.to_dict(include_objects=include_objects)
                if self.resolved_input is not None
                else None
            ),
            "preparation": (
                self.preparation.to_dict(include_objects=include_objects)
                if self.preparation is not None
                else None
            ),
            "stage_trace": [item.to_dict() for item in self.stage_trace],
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(self.metadata),
            "options": self.options.to_dict(),
            "summary": self.summary(),
        }


# 18.4. Request and context construction
# -----------------------------------------------------------------------------


def build_single_pose_request(
    value: Any = None,
    *,
    receptor: Any = None,
    pose: Any = None,
    dock_model: Any = None,
    session: Any = None,
    config: AnalysisConfigLike = None,
    requested_stages: Any = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisRequest:
    """Build one normalized single-pose request."""

    integrated = coerce_analysis_config(config)
    source = dock_model if dock_model is not None else value
    if isinstance(value, AnalysisContext):
        request = value.request
    elif isinstance(value, ResolvedAnalysisInput):
        request = value.request
    elif isinstance(value, AnalysisRequest):
        request = value
    else:
        request = coerce_analysis_request(source)

    updates: Dict[str, Any] = {
        "config": integrated,
        "mode": ANALYSIS_MODE_SINGLE_POSE,
    }
    if name is not None:
        updates["name"] = normalize_text(name, default=DEFAULT_RESULT_NAME)
    if receptor is not None:
        updates["receptor"] = receptor
    if pose is not None:
        updates["poses"] = (pose,)
    if dock_model is not None:
        updates["dock_models"] = (dock_model,)
        if updates.get("poses") is None:
            model_pose = get_object_value(
                dock_model,
                DOCK_MODEL_FIELD_POSE,
                default=None,
            )
            if model_pose is not None:
                updates["poses"] = (model_pose,)
        if updates.get("receptor") is None:
            model_receptor = get_object_value(
                dock_model,
                DOCK_MODEL_FIELD_RECEPTOR,
                default=None,
            )
            if model_receptor is not None:
                updates["receptor"] = model_receptor
    if session is not None:
        updates["session"] = session
    if requested_stages is not None:
        updates["requested_stages"] = canonicalize_stage_sequence(
            requested_stages,
            strict=True,
            unique=True,
            sort=False,
        )
    elif integrated.requested_stages:
        updates["requested_stages"] = tuple(integrated.requested_stages)
    if metadata:
        merged_metadata = dict(request.metadata)
        merged_metadata.update(dict(metadata))
        updates["metadata"] = merged_metadata
    return replace(request, **updates)


def create_single_pose_context(
    request: AnalysisRequestLike,
    *,
    context: Optional[AnalysisContext] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
) -> AnalysisContext:
    """Create or normalize the runtime context for one pose."""

    normalized_request = coerce_analysis_request(request)
    if context is None:
        context = create_analysis_context(
            normalized_request,
            mode=ANALYSIS_MODE_SINGLE_POSE,
        )
    elif not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance.")
    else:
        context.request = normalized_request
        context.config = normalized_request.config
        context.mode = ANALYSIS_MODE_SINGLE_POSE
        context.session = normalized_request.session
        context.receptor = normalized_request.receptor
        context.poses = list(normalized_request.poses)
        context.dock_models = list(normalized_request.dock_models)
    if progress_callback is not None:
        context.progress_callback = progress_callback
    if stage_callback is not None:
        context.stage_callback = stage_callback
    if cancellation_callback is not None:
        context.cancellation_callback = cancellation_callback
    return context


# 18.5. Plan construction and stage selection
# -----------------------------------------------------------------------------


def build_single_pose_execution_plan(
    config: AnalysisConfigLike = None,
    *,
    request: Optional[AnalysisRequest] = None,
    options: SinglePoseExecutionOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
) -> AnalysisExecutionPlan:
    """Build a deterministic execution plan for one pose."""

    integrated = coerce_analysis_config(
        request.config if request is not None and config is None else config
    )
    resolved_options = coerce_single_pose_execution_options(options)
    requested = resolved_options.requested_stages
    if not requested and request is not None and request.requested_stages:
        requested = tuple(request.requested_stages)
    if not requested:
        requested = integrated.desired_stages(mode=ANALYSIS_MODE_SINGLE_POSE)
    return build_analysis_execution_plan(
        integrated,
        registry=registry,
        capabilities=capabilities,
        requested_stages=requested,
        analysis_mode=ANALYSIS_MODE_SINGLE_POSE,
        include_dependencies=resolved_options.include_dependencies,
        include_ordering_predecessors=(
            resolved_options.include_ordering_predecessors
        ),
        inspect_capabilities=resolved_options.inspect_capabilities,
        load_capabilities=resolved_options.load_capabilities,
        drop_unavailable_optional_stages=(
            resolved_options.drop_unavailable_optional_stages
        ),
        require_registered_executors=(
            resolved_options.require_registered_executors
        ),
        strict=integrated.runtime.is_strict,
    )


def _single_pose_dependency_failures(
    entry: StagePlanEntry,
    stage_results: Mapping[str, AnalysisStageResult],
) -> Tuple[str, ...]:
    """Return failed hard dependencies for one plan entry."""

    failures: List[str] = []
    for dependency in entry.dependencies:
        result = stage_results.get(dependency)
        if result is None:
            failures.append(dependency)
        elif result.status not in SINGLE_POSE_DEPENDENCY_SUCCESS_STATUSES:
            failures.append(dependency)
    return tuple(failures)


def select_single_pose_stage_action(
    entry: StagePlanEntry,
    stage_results: Mapping[str, AnalysisStageResult],
    *,
    context: AnalysisContext,
    options: SinglePoseExecutionOptions,
    abort_requested: bool = False,
) -> Tuple[SinglePoseStageAction, Optional[str], Tuple[str, ...]]:
    """Select the action for one planned stage."""

    if context.is_cancelled():
        return (
            SinglePoseStageAction.CANCEL,
            "Analysis execution was cancelled.",
            (),
        )
    if abort_requested and entry.stage not in {
        STAGE_VALIDATION,
        STAGE_FINALIZATION,
    }:
        return (
            SinglePoseStageAction.BLOCK,
            "Execution stopped after a previous stage failure.",
            (),
        )
    failed_dependencies = _single_pose_dependency_failures(entry, stage_results)
    if failed_dependencies:
        return (
            SinglePoseStageAction.BLOCK,
            "Required dependencies did not complete successfully: "
            + ", ".join(failed_dependencies)
            + ".",
            failed_dependencies,
        )
    if entry.disposition is PlanEntryDisposition.UNAVAILABLE:
        return (
            SinglePoseStageAction.SKIP
            if not entry.required
            else SinglePoseStageAction.BLOCK,
            entry.reason or "The stage is unavailable in the current environment.",
            tuple(entry.blocked_by),
        )
    if entry.disposition is PlanEntryDisposition.BLOCKED:
        return (
            SinglePoseStageAction.BLOCK,
            entry.reason or "The stage is blocked by the execution plan.",
            tuple(entry.blocked_by),
        )
    if entry.disposition is PlanEntryDisposition.OMITTED:
        return (
            SinglePoseStageAction.SKIP,
            entry.reason or "The stage was omitted from the execution plan.",
            (),
        )
    if entry.stage in SINGLE_POSE_NON_APPLICABLE_STAGES:
        return (
            SinglePoseStageAction.SKIP,
            "Consensus analysis is not applicable to a single pose.",
            (),
        )
    if (
        entry.stage in SINGLE_POSE_DEFERRED_OUTPUT_STAGES
        and not entry.definition.executor_registered
        and options.allow_deferred_stages
    ):
        return (
            SinglePoseStageAction.DEFER,
            "The output stage is deferred until its integration section is available.",
            (),
        )
    if (
        entry.stage not in SINGLE_POSE_MANAGED_STAGES
        and not entry.definition.executor_registered
    ):
        return (
            SinglePoseStageAction.BLOCK
            if entry.required
            else SinglePoseStageAction.SKIP,
            "No executor is registered for the stage.",
            (),
        )
    return SinglePoseStageAction.EXECUTE, None, ()


# 18.6. Managed input-resolution stage
# -----------------------------------------------------------------------------


def execute_single_pose_input_resolution(
    context: AnalysisContext,
    *,
    validate_input: bool = True,
) -> Tuple[AnalysisStageResult, Optional[ResolvedAnalysisInput]]:
    """Resolve and validate exactly one pose in the runtime context."""

    result = AnalysisStageResult(stage=STAGE_INPUT_RESOLUTION, required=True)
    result.start()
    resolved: Optional[ResolvedAnalysisInput] = None
    try:
        context.raise_if_cancelled(stage=STAGE_INPUT_RESOLUTION)
        context.set_current_stage(STAGE_INPUT_RESOLUTION)
        resolved = resolve_context_input(
            context,
            strict=context.config.runtime.is_strict,
            allow_empty=False,
        )
        validation = validate_resolved_analysis_input(
            resolved,
            strict=False,
            allow_empty=False,
        )
        errors = list(validation.get("errors", ()))
        warnings_list = list(validation.get("warnings", ()))
        if resolved.mode in {ANALYSIS_MODE_MULTIPOSE, ANALYSIS_MODE_BATCH}:
            errors.append(
                "Single-pose orchestration received a multipose or batch input."
            )
        if resolved.item_count != 1:
            errors.append(
                "Single-pose orchestration requires exactly one resolved item."
            )
        for message in warnings_list:
            result.diagnostics.add_warning(message, stage=STAGE_INPUT_RESOLUTION)
        result.input_summary = {
            "request_id": context.request_id,
            "requested_mode": ANALYSIS_MODE_SINGLE_POSE,
        }
        result.output_summary = resolved.to_dict(include_objects=False)
        result.statistics = {
            "item_count": resolved.item_count,
            "pose_count": resolved.pose_count,
            "dock_model_count": len(resolved.dock_models),
            "warning_count": len(warnings_list),
            "error_count": len(errors),
        }
        result.metadata.update(
            {
                "schema": SINGLE_POSE_SCHEMA_NAME,
                "schema_version": SINGLE_POSE_SCHEMA_VERSION,
                "source_kind": resolved.source_kind.value,
                "input_mode": resolved.mode,
            }
        )
        if errors:
            error = AnalysisInputError(
                "Single-pose input resolution failed: " + " ".join(errors),
                stage=STAGE_INPUT_RESOLUTION,
                details={"errors": errors, "validation": validation},
            )
            if resolved.item_count == 1 and not validate_input:
                result.partial(
                    resolved,
                    issue=error,
                    message="Input resolution completed with validation issues.",
                )
            else:
                result.fail(error)
        else:
            result.succeed(
                resolved,
                message="Single-pose input resolved successfully.",
            )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisInputError(
                "Single-pose input resolution failed.",
                stage=STAGE_INPUT_RESOLUTION,
                cause=exc,
            )
        result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
    finally:
        context.set_stage_data(STAGE_INPUT_RESOLUTION, result)
        context.set_current_stage(None)
    return result, resolved


# 18.7. Managed model-preparation stage
# -----------------------------------------------------------------------------


def execute_single_pose_model_preparation(
    context: AnalysisContext,
    *,
    options: Optional[ModelPreparationOptions] = None,
    validate_result: bool = True,
) -> Tuple[AnalysisStageResult, Optional[ModelPreparationResult]]:
    """Prepare exactly one DockModel for single-pose analysis."""

    preparation: Optional[ModelPreparationResult] = None
    try:
        context.raise_if_cancelled(stage=STAGE_MODEL_PREPARATION)
        context.set_current_stage(STAGE_MODEL_PREPARATION)
        preparation = prepare_context_models(
            context,
            options=options,
            resolve_input=True,
        )
        result = create_model_preparation_stage_result(preparation)
        validation = validate_model_preparation_result(
            preparation,
            strict=False,
        )
        errors = list(validation.get("errors", ()))
        if preparation.prepared_count != 1:
            errors.append(
                "Single-pose orchestration requires exactly one prepared DockModel."
            )
        if validate_result and errors:
            error = AnalysisValidationError(
                "Single-pose model preparation failed validation: "
                + " ".join(errors),
                stage=STAGE_MODEL_PREPARATION,
                details={"errors": errors, "validation": validation},
            )
            if preparation.dock_models:
                result.partial(
                    preparation,
                    issue=error,
                    message="Model preparation completed with validation issues.",
                )
            else:
                result.fail(error)
        result.metadata.update(
            {
                "schema": SINGLE_POSE_SCHEMA_NAME,
                "schema_version": SINGLE_POSE_SCHEMA_VERSION,
            }
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisIntegrationError(
                "Single-pose model preparation failed.",
                stage=STAGE_MODEL_PREPARATION,
                cause=exc,
            )
        result = AnalysisStageResult(
            stage=STAGE_MODEL_PREPARATION,
            required=True,
        )
        result.start().fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
    finally:
        context.set_stage_data(STAGE_MODEL_PREPARATION, result)
        context.set_current_stage(None)
    return result, preparation


# 18.8. Pose-result initialization and synchronization
# -----------------------------------------------------------------------------


def create_single_pose_result(
    context: AnalysisContext,
    *,
    preparation: Optional[ModelPreparationResult] = None,
) -> PoseAnalysisResult:
    """Create the integrated result object for the active pose."""

    dock_model = None
    pose = None
    ligand = None
    receptor = context.receptor
    if preparation is not None and preparation.dock_models:
        dock_model = preparation.dock_models[0]
        receptor = preparation.receptor
        pose = preparation.poses[0] if preparation.poses else None
        ligand = preparation.ligands[0] if preparation.ligands else None
    elif context.dock_models:
        dock_model = context.dock_models[0]
        receptor = get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_RECEPTOR,
            default=receptor,
        )
        pose = get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_POSE,
            default=context.poses[0] if context.poses else None,
        )
        ligand = get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_LIGAND,
            default=None,
        )
    elif context.poses:
        pose = context.poses[0]

    model_name = get_preparation_model_name(
        dock_model,
        default=context.request.name or DEFAULT_POSE_RESULT_NAME,
    ) if dock_model is not None else normalize_text(
        context.request.name,
        default=DEFAULT_POSE_RESULT_NAME,
    )
    pose_id = (
        get_preparation_model_identifier(dock_model)
        if dock_model is not None
        else None
    ) or _new_result_identifier("pose")
    result = PoseAnalysisResult(
        pose_id=pose_id,
        name=model_name,
        status=AnalysisStatus.RUNNING,
        dock_model=dock_model,
        receptor=receptor,
        ligand=ligand,
        pose=pose,
        started_at=context.started_at or _utc_timestamp(),
        metadata={
            "run_id": context.run_id,
            "request_id": context.request_id,
            "analysis_mode": ANALYSIS_MODE_SINGLE_POSE,
            "configuration_fingerprint": context.config.fingerprint,
        },
    )
    context.set_current_pose(0)
    context.set_shared(SINGLE_POSE_RESULT_KEY, result)
    return result


def _single_pose_extract_interaction_bundle(value: Any) -> Optional[InteractionAnalysisBundle]:
    """Extract an integrated interaction bundle from a stage value."""

    if isinstance(value, InteractionAnalysisBundle):
        return value
    if isinstance(value, InteractionConsolidationResult):
        return value.bundle
    bundle = get_object_value(value, "bundle", default=None)
    if isinstance(bundle, InteractionAnalysisBundle):
        return bundle
    return None


def _single_pose_extract_scoring(value: Any) -> Any:
    """Extract the native scoring result from a stage value."""

    if isinstance(value, ScoringStageOutput):
        return value.scoring_result
    scoring_result = get_object_value(value, "scoring_result", default=MISSING_VALUE)
    if not is_missing_value(scoring_result):
        return scoring_result
    return value


def synchronize_single_pose_stage_result(
    context: AnalysisContext,
    pose_result: PoseAnalysisResult,
    run_result: AnalysisRunResult,
    stage_result: AnalysisStageResult,
) -> None:
    """Store one stage result across context, pose and run containers."""

    pose_result.add_stage_result(stage_result)
    run_result.add_stage_result(stage_result)
    context.set_stage_data(stage_result.stage, stage_result)
    context.notify_stage(stage_result)

    if stage_result.duration_seconds is not None:
        pose_result.timings[stage_result.stage] = stage_result.duration_seconds
        run_result.timings[stage_result.stage] = stage_result.duration_seconds
    if stage_result.statistics:
        pose_result.statistics[stage_result.stage] = dict(stage_result.statistics)
    if stage_result.files:
        pose_result.files.update(stage_result.files)
        run_result.files.update(stage_result.files)
        context.files.update(stage_result.files)
    pose_result.diagnostics.extend(stage_result.diagnostics)
    run_result.diagnostics.extend(stage_result.diagnostics)

    if stage_result.stage == STAGE_CONSOLIDATION:
        bundle = _single_pose_extract_interaction_bundle(stage_result.value)
        if bundle is not None:
            pose_result.interactions = bundle
    elif stage_result.stage == STAGE_SCORING and stage_result.value is not None:
        pose_result.scoring = _single_pose_extract_scoring(stage_result.value)
    elif stage_result.stage == STAGE_REPORT and stage_result.value is not None:
        pose_result.reports[STAGE_REPORT] = stage_result.value
    elif stage_result.stage == STAGE_EXPORT and stage_result.value is not None:
        pose_result.exports[STAGE_EXPORT] = stage_result.value
    elif stage_result.stage == STAGE_VISUALIZATION and stage_result.value is not None:
        pose_result.visualizations[STAGE_VISUALIZATION] = stage_result.value


# 18.9. Generic registered-stage invocation
# -----------------------------------------------------------------------------


def _filter_callable_keyword_arguments(
    callable_object: Callable[..., Any],
    values: Mapping[str, Any],
) -> Dict[str, Any]:
    """Filter keyword arguments according to a callable signature."""

    try:
        signature = _cached_callable_signature(callable_object)
    except (TypeError, ValueError):
        return dict(values)
    parameters = signature.parameters
    if any(
        parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in parameters.values()
    ):
        return dict(values)
    return {
        key: value
        for key, value in values.items()
        if key in parameters
        and parameters[key].kind
        in {
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        }
    }


def _invoke_single_pose_result_adapter(
    adapter: StageResultAdapter,
    value: Any,
    *,
    stage: str,
) -> Any:
    """Invoke a registered result adapter with compatible arguments."""

    kwargs = _filter_callable_keyword_arguments(
        adapter,
        {"value": value, "result": value, "stage": stage},
    )
    if kwargs:
        return adapter(**kwargs)
    return adapter(value)


def invoke_single_pose_stage_executor(
    entry: StagePlanEntry,
    *,
    context: AnalysisContext,
    pose_result: PoseAnalysisResult,
    plan: AnalysisExecutionPlan,
    options: SinglePoseExecutionOptions,
) -> AnalysisStageResult:
    """Invoke one registered stage executor with signature-safe arguments."""

    definition = entry.definition
    executor = definition.executor
    if executor is None:
        result = AnalysisStageResult(stage=entry.stage, required=entry.required)
        result.block("No executor is registered for the stage.")
        return result

    dock_model = pose_result.dock_model
    override_values = dict(options.stage_override(entry.stage))
    candidate_arguments: Dict[str, Any] = {
        "context": context,
        "dock_model": dock_model,
        "receptor": pose_result.receptor,
        "pose": pose_result.pose,
        "ligand": pose_result.ligand,
        "source": dock_model,
        "pose_index": 0,
        "config": context.config,
        "overrides": override_values,
        "analysis_result": pose_result,
        "pose_result": pose_result,
        "execution_plan": plan,
        "plan": plan,
        "raise_on_error": False,
    }
    kwargs = _filter_callable_keyword_arguments(executor, candidate_arguments)
    raw_result = executor(**kwargs)
    if isinstance(raw_result, AnalysisStageResult):
        return raw_result
    if definition.result_adapter is not None:
        raw_result = _invoke_single_pose_result_adapter(
            definition.result_adapter,
            raw_result,
            stage=entry.stage,
        )
        if isinstance(raw_result, AnalysisStageResult):
            return raw_result
    result = AnalysisStageResult(stage=entry.stage, required=entry.required)
    result.start().succeed(raw_result)
    return result


# 18.10. Validation stage
# -----------------------------------------------------------------------------


def validate_single_pose_analysis_state(
    context: AnalysisContext,
    pose_result: PoseAnalysisResult,
    *,
    preparation: Optional[ModelPreparationResult] = None,
    strict: bool = False,
) -> Dict[str, Any]:
    """Validate the accumulated state of one pose analysis."""

    errors: List[str] = []
    warnings_list: List[str] = []
    if context.mode != ANALYSIS_MODE_SINGLE_POSE:
        errors.append("The analysis context is not in single-pose mode.")
    if context.pose_count != 1:
        errors.append("The analysis context does not contain exactly one pose.")
    if pose_result.dock_model is None:
        errors.append("The pose result has no DockModel.")
    if pose_result.pose is None:
        errors.append("The pose result has no docking pose.")
    if pose_result.receptor is None:
        errors.append("The pose result has no receptor.")
    if preparation is not None:
        preparation_validation = validate_model_preparation_result(
            preparation,
            strict=False,
        )
        errors.extend(preparation_validation.get("errors", ()))
        warnings_list.extend(preparation_validation.get("warnings", ()))
    errors.extend(validate_core_result(pose_result, raise_on_error=False))

    consolidation = pose_result.get_stage_result(STAGE_CONSOLIDATION)
    if consolidation is not None and consolidation.status in STAGE_SUCCESS_STATUSES:
        bundle = _single_pose_extract_interaction_bundle(consolidation.value)
        if bundle is None:
            warnings_list.append(
                "The consolidation stage completed without an interaction bundle."
            )
        else:
            errors.extend(validate_core_result(bundle, raise_on_error=False))
    scoring_result = pose_result.get_stage_result(STAGE_SCORING)
    if scoring_result is not None and scoring_result.status in STAGE_SUCCESS_STATUSES:
        if pose_result.scoring is None:
            warnings_list.append(
                "The scoring stage completed without a native scoring payload."
            )

    required_failures = [
        stage
        for stage, result in pose_result.stage_results.items()
        if result.required and result.status in SINGLE_POSE_ABORT_STATUSES
    ]
    if required_failures:
        errors.append(
            "Required stages did not complete successfully: "
            + ", ".join(required_failures)
            + "."
        )

    result = {
        "valid": not errors,
        "errors": unique_preserving_order(errors),
        "warnings": unique_preserving_order(warnings_list),
        "required_failures": required_failures,
        "stage_count": len(pose_result.stage_results),
        "interaction_count": pose_result.interaction_count,
    }
    if strict and errors:
        raise AnalysisValidationError(
            "Single-pose analysis validation failed: " + " ".join(errors),
            stage=STAGE_VALIDATION,
            details=result,
        )
    return result


# execute_single_pose_validation_stage is implemented by the Section 27 validation layer.


# 18.11. Finalization stage
# -----------------------------------------------------------------------------


def execute_single_pose_finalization_stage(
    context: AnalysisContext,
    pose_result: PoseAnalysisResult,
    run_result: AnalysisRunResult,
    *,
    plan: AnalysisExecutionPlan,
) -> AnalysisStageResult:
    """Finalize one single-pose analysis and its run wrapper."""

    result = AnalysisStageResult(stage=STAGE_FINALIZATION, required=True)
    result.start()
    try:
        context.set_current_stage(STAGE_FINALIZATION)
        pose_result.metadata.update(
            {
                "schema": SINGLE_POSE_SCHEMA_NAME,
                "schema_version": SINGLE_POSE_SCHEMA_VERSION,
                "plan_id": plan.plan_id,
                "plan_fingerprint": execution_plan_fingerprint(plan),
                "stage_order": list(plan.stages),
            }
        )
        pose_result.statistics.setdefault(
            "stage_status_counts",
            dict(
                Counter(
                    stage_result.status.value
                    for stage_result in pose_result.stage_results.values()
                )
            ),
        )
        result.output_summary = {
            "pose_id": pose_result.pose_id,
            "name": pose_result.name,
            "interaction_count": pose_result.interaction_count,
            "completed_stages": list(pose_result.completed_stages),
            "failed_stages": list(pose_result.failed_stages),
        }
        result.statistics = {
            "interaction_count": pose_result.interaction_count,
            "stage_count": len(pose_result.stage_results),
            "failed_stage_count": len(pose_result.failed_stages),
        }
        result.succeed(
            dict(result.output_summary),
            message="Single-pose analysis finalized successfully.",
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisIntegrationError(
                "Single-pose finalization failed.",
                stage=STAGE_FINALIZATION,
                cause=exc,
            )
        result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
    finally:
        context.set_current_stage(None)
    return result


# 18.12. Stage-result factories for non-execution actions
# -----------------------------------------------------------------------------


def create_single_pose_nonexecution_result(
    entry: StagePlanEntry,
    action: SinglePoseStageAction,
    reason: str,
    *,
    blocked_by: Sequence[str] = (),
) -> AnalysisStageResult:
    """Create a skipped, blocked, deferred or cancelled stage result."""

    result = AnalysisStageResult(stage=entry.stage, required=entry.required)
    result.metadata.update(
        {
            "action": action.value,
            "plan_position": entry.position,
            "plan_wave": entry.wave,
            "blocked_by": list(blocked_by),
        }
    )
    if action in {SinglePoseStageAction.SKIP, SinglePoseStageAction.DEFER}:
        result.skip(reason)
        if action is SinglePoseStageAction.DEFER:
            result.metadata["deferred"] = True
    elif action is SinglePoseStageAction.CANCEL:
        result.cancel(reason)
    else:
        result.block(reason)
    return result


def _single_pose_should_abort(
    entry: StagePlanEntry,
    result: AnalysisStageResult,
    options: SinglePoseExecutionOptions,
) -> bool:
    """Return whether subsequent ordinary stages should be blocked."""

    if result.status not in SINGLE_POSE_ABORT_STATUSES:
        return False
    if options.stop_on_any_failure:
        return True
    return bool(options.stop_on_required_failure and entry.required)


# 18.13. Complete orchestration runner
# -----------------------------------------------------------------------------


def run_single_pose_analysis(
    value: Any = None,
    *,
    receptor: Any = None,
    pose: Any = None,
    dock_model: Any = None,
    session: Any = None,
    config: AnalysisConfigLike = None,
    options: SinglePoseExecutionOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    context: Optional[AnalysisContext] = None,
    requested_stages: Any = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
) -> SinglePoseAnalysisOutput:
    """Run the complete integrated pipeline for exactly one pose."""

    resolved_options = coerce_single_pose_execution_options(options)
    integrated = coerce_analysis_config(config)
    request = build_single_pose_request(
        value,
        receptor=receptor,
        pose=pose,
        dock_model=dock_model,
        session=session,
        config=integrated,
        requested_stages=requested_stages,
        name=name,
        metadata=metadata,
    )
    runtime_context = create_single_pose_context(
        request,
        context=context,
        progress_callback=progress_callback,
        stage_callback=stage_callback,
        cancellation_callback=cancellation_callback,
    )
    target_registry = registry or get_default_stage_registry()
    plan = build_single_pose_execution_plan(
        integrated,
        request=request,
        options=resolved_options,
        registry=target_registry,
        capabilities=capabilities,
    )
    runtime_context.set_shared(SINGLE_POSE_PLAN_KEY, plan)
    runtime_context.metadata[SINGLE_POSE_METADATA_KEY] = {
        "schema": SINGLE_POSE_SCHEMA_NAME,
        "schema_version": SINGLE_POSE_SCHEMA_VERSION,
        "plan_id": plan.plan_id,
        "options_fingerprint": resolved_options.fingerprint,
    }

    run_result = AnalysisRunResult(
        run_id=runtime_context.run_id,
        request_id=request.request_id,
        name=request.name,
        mode=ANALYSIS_MODE_SINGLE_POSE,
        status=AnalysisStatus.RUNNING,
        request=request,
        context=runtime_context if resolved_options.preserve_context else None,
        started_at=_utc_timestamp(),
        metadata={
            "schema": SINGLE_POSE_SCHEMA_NAME,
            "schema_version": SINGLE_POSE_SCHEMA_VERSION,
            "plan_id": plan.plan_id,
        },
    )
    runtime_context.start()

    stage_trace: List[SinglePoseStageTrace] = []
    warnings_list: List[str] = list(plan.warnings)
    errors: List[str] = []
    resolved_input: Optional[ResolvedAnalysisInput] = None
    preparation: Optional[ModelPreparationResult] = None
    pose_result: Optional[PoseAnalysisResult] = None
    abort_requested = False
    first_failure: Optional[BaseException] = None
    total_stages = len(plan.entries)

    for ordinal, entry in enumerate(plan.entries, start=1):
        existing_results = (
            pose_result.stage_results if pose_result is not None else run_result.stage_results
        )
        action, reason, blocked_by = select_single_pose_stage_action(
            entry,
            existing_results,
            context=runtime_context,
            options=resolved_options,
            abort_requested=abort_requested,
        )

        if action is not SinglePoseStageAction.EXECUTE:
            stage_result = create_single_pose_nonexecution_result(
                entry,
                action,
                reason or "The stage was not executed.",
                blocked_by=blocked_by,
            )
        elif entry.stage == STAGE_INPUT_RESOLUTION:
            stage_result, resolved_input = execute_single_pose_input_resolution(
                runtime_context,
                validate_input=resolved_options.validate_input,
            )
        elif entry.stage == STAGE_MODEL_PREPARATION:
            stage_result, preparation = execute_single_pose_model_preparation(
                runtime_context,
                validate_result=resolved_options.validate_result,
            )
            if preparation is not None and preparation.dock_models:
                pose_result = create_single_pose_result(
                    runtime_context,
                    preparation=preparation,
                )
                for previous in run_result.stage_results.values():
                    pose_result.add_stage_result(previous)
                    pose_result.diagnostics.extend(previous.diagnostics)
        elif entry.stage == STAGE_VALIDATION:
            if pose_result is None:
                stage_result = create_single_pose_nonexecution_result(
                    entry,
                    SinglePoseStageAction.BLOCK,
                    "Validation requires a prepared pose result.",
                )
            else:
                stage_result = execute_single_pose_validation_stage(
                    runtime_context,
                    pose_result,
                    preparation=preparation,
                )
        elif entry.stage == STAGE_FINALIZATION:
            if pose_result is None:
                stage_result = create_single_pose_nonexecution_result(
                    entry,
                    SinglePoseStageAction.BLOCK,
                    "Finalization requires a prepared pose result.",
                )
            else:
                stage_result = execute_single_pose_finalization_stage(
                    runtime_context,
                    pose_result,
                    run_result,
                    plan=plan,
                )
        else:
            if pose_result is None:
                stage_result = create_single_pose_nonexecution_result(
                    entry,
                    SinglePoseStageAction.BLOCK,
                    "The stage requires a prepared pose result.",
                )
            else:
                try:
                    runtime_context.raise_if_cancelled(stage=entry.stage)
                    runtime_context.set_current_stage(entry.stage)
                    stage_result = invoke_single_pose_stage_executor(
                        entry,
                        context=runtime_context,
                        pose_result=pose_result,
                        plan=plan,
                        options=resolved_options,
                    )
                except Exception as exc:
                    wrapped = exc
                    if not isinstance(exc, AnalysisError):
                        wrapped = AnalysisStageError(
                            f"Single-pose stage {entry.stage!r} failed.",
                            stage=entry.stage,
                            cause=exc,
                        )
                    stage_result = AnalysisStageResult(
                        stage=entry.stage,
                        required=entry.required,
                    )
                    stage_result.start().fail(
                        wrapped,
                        include_traceback=(
                            runtime_context.config.runtime.collect_diagnostics
                        ),
                    )
                finally:
                    runtime_context.set_current_stage(None)

        if pose_result is None:
            run_result.add_stage_result(stage_result)
            runtime_context.set_stage_data(entry.stage, stage_result)
            runtime_context.notify_stage(stage_result)
        else:
            synchronize_single_pose_stage_result(
                runtime_context,
                pose_result,
                run_result,
                stage_result,
            )

        stage_trace.append(
            SinglePoseStageTrace.from_result(
                entry,
                stage_result,
                action=action,
                reason=reason,
            )
        )
        runtime_context.update_progress(
            entry.stage,
            ordinal,
            total_stages,
            {
                "status": stage_result.status.value,
                "action": action.value,
                "position": entry.position,
                "wave": entry.wave,
            },
        )
        warnings_list.extend(issue.message for issue in stage_result.warnings)
        errors.extend(issue.message for issue in stage_result.errors)
        if stage_result.errors and first_failure is None:
            issue = stage_result.errors[0]
            first_failure = AnalysisStageError(
                issue.message,
                stage=entry.stage,
                details=issue.details,
            )
        if _single_pose_should_abort(entry, stage_result, resolved_options):
            abort_requested = True

    if pose_result is None:
        pose_result = PoseAnalysisResult(
            name=request.name,
            status=(
                AnalysisStatus.CANCELLED
                if runtime_context.is_cancelled()
                else AnalysisStatus.FAILED
            ),
            receptor=runtime_context.receptor,
            pose=runtime_context.poses[0] if runtime_context.poses else None,
            diagnostics=run_result.diagnostics,
            started_at=runtime_context.started_at,
            metadata={
                "run_id": runtime_context.run_id,
                "request_id": runtime_context.request_id,
                "analysis_mode": ANALYSIS_MODE_SINGLE_POSE,
            },
        )
        for stage_result in run_result.stage_results.values():
            pose_result.add_stage_result(stage_result)
        pose_result.finalize()
    elif pose_result.finished_at is None:
        pose_result.finalize(
            AnalysisStatus.CANCELLED
            if runtime_context.is_cancelled()
            else None
        )

    run_result.set_payload(pose_result)
    run_result.pose_result = pose_result
    run_result.statistics.update(pose_result.statistics)
    run_result.files.update(pose_result.files)
    run_result.provenance.update(pose_result.provenance)
    run_result.finalize(pose_result.status)
    runtime_context.set_status(pose_result.status, force=True)
    runtime_context.set_current_pose(None)
    runtime_context.set_current_stage(None)

    output = SinglePoseAnalysisOutput(
        request=request,
        context=runtime_context,
        plan=plan,
        pose_result=pose_result,
        run_result=run_result,
        resolved_input=resolved_input,
        preparation=preparation,
        stage_trace=stage_trace,
        warnings=warnings_list,
        errors=errors,
        metadata={
            "schema": SINGLE_POSE_SCHEMA_NAME,
            "schema_version": SINGLE_POSE_SCHEMA_VERSION,
            "plan_id": plan.plan_id,
            "configuration_fingerprint": integrated.fingerprint,
            "options_fingerprint": resolved_options.fingerprint,
        },
        options=resolved_options,
    )
    runtime_context.set_shared(SINGLE_POSE_OUTPUT_KEY, output)
    runtime_context.set_shared(SINGLE_POSE_RUN_RESULT_KEY, run_result)
    runtime_context.set_shared(SINGLE_POSE_STAGE_TRACE_KEY, tuple(stage_trace))
    runtime_context.statistics[SINGLE_POSE_STATISTICS_KEY] = output.summary()

    if resolved_options.validate_result:
        validation_errors = validate_single_pose_analysis_output(
            output,
            raise_on_error=False,
        )
        if validation_errors:
            errors.extend(validation_errors)
            output.errors = unique_preserving_order(errors)
    if resolved_options.raise_on_error and output.status in {
        AnalysisStatus.FAILED,
        AnalysisStatus.CANCELLED,
    }:
        if first_failure is not None:
            raise first_failure
        raise AnalysisPartialFailureError(
            "Single-pose analysis did not complete successfully.",
            details=output.summary(),
        )
    return output


# 18.14. Convenience wrappers scoped to single-pose execution
# -----------------------------------------------------------------------------


def analyze_single_pose(
    value: Any = None,
    **kwargs: Any,
) -> PoseAnalysisResult:
    """Run one pose analysis and return its integrated pose result."""

    return run_single_pose_analysis(value, **kwargs).pose_result


def analyze_single_dock_model(
    dock_model: Any,
    **kwargs: Any,
) -> PoseAnalysisResult:
    """Analyze one existing DockModel and return its pose result."""

    return run_single_pose_analysis(dock_model=dock_model, **kwargs).pose_result


def execute_single_pose_pipeline(
    value: Any = None,
    **kwargs: Any,
) -> SinglePoseAnalysisOutput:
    """Alias for :func:`run_single_pose_analysis`."""

    return run_single_pose_analysis(value, **kwargs)


# 18.15. Validation, summaries and conversion
# -----------------------------------------------------------------------------


def validate_single_pose_analysis_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one complete single-pose orchestration output."""

    errors: List[str] = []
    if not isinstance(value, SinglePoseAnalysisOutput):
        errors.append("Value is not a SinglePoseAnalysisOutput instance.")
    else:
        if value.context.mode != ANALYSIS_MODE_SINGLE_POSE:
            errors.append("Single-pose output context has an invalid mode.")
        if value.plan.analysis_mode != ANALYSIS_MODE_SINGLE_POSE:
            errors.append("Single-pose execution plan has an invalid mode.")
        if value.pose_result is not value.run_result.pose_result:
            errors.append("Pose and run results do not reference the same payload.")
        if value.run_result.payload is not value.pose_result:
            errors.append("Run-result payload is not the pose result.")
        if value.preparation is not None and value.preparation.prepared_count != 1:
            errors.append("Single-pose output does not contain one prepared model.")
        if len(value.stage_trace) != len(value.plan.entries):
            errors.append("Stage trace does not align with the execution plan.")
        trace_stages = tuple(item.stage for item in value.stage_trace)
        plan_stages = tuple(entry.stage for entry in value.plan.entries)
        if trace_stages != plan_stages:
            errors.append("Stage trace order differs from the execution plan.")
        errors.extend(validate_core_result(value.pose_result, raise_on_error=False))
        errors.extend(validate_core_result(value.run_result, raise_on_error=False))
        if value.status == AnalysisStatus.SUCCEEDED and value.failed_stages:
            errors.append("Successful single-pose output contains failed stages.")
        if value.options.fingerprint != value.metadata.get("options_fingerprint"):
            errors.append("Single-pose options fingerprint is inconsistent.")
    result = tuple(unique_preserving_order(errors))
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Single-pose output validation failed: " + " ".join(result),
            stage=STAGE_VALIDATION,
            details={"errors": list(result)},
        )
    return result


def summarize_single_pose_analysis(
    value: Any,
) -> Dict[str, Any]:
    """Return a concise summary of a single-pose result or output."""

    if isinstance(value, SinglePoseAnalysisOutput):
        return value.summary()
    pose_result = coerce_pose_analysis_result(value)
    return {
        "schema": SINGLE_POSE_SCHEMA_NAME,
        "schema_version": SINGLE_POSE_SCHEMA_VERSION,
        "pose_id": pose_result.pose_id,
        "name": pose_result.name,
        "status": pose_result.status.value,
        "stage_count": len(pose_result.stage_results),
        "interaction_count": pose_result.interaction_count,
        "failed_stages": list(pose_result.failed_stages),
        "duration_seconds": pose_result.duration_seconds,
    }


def single_pose_analysis_to_json(
    value: SinglePoseAnalysisOutput,
    *,
    include_objects: bool = False,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
    sort_keys: bool = True,
) -> str:
    """Serialize a single-pose output to JSON."""

    if not isinstance(value, SinglePoseAnalysisOutput):
        raise TypeError("value must be a SinglePoseAnalysisOutput instance.")
    return json.dumps(
        value.to_dict(include_objects=include_objects),
        indent=indent,
        sort_keys=sort_keys,
        default=str,
    )


# 18.16. Internal convention validation
# -----------------------------------------------------------------------------


def validate_single_pose_orchestration_conventions() -> Dict[str, Any]:
    """Validate the single-pose orchestration layer with synthetic executors."""

    failures: List[str] = []

    class _SyntheticAtoms(list):
        @property
        def residues(self) -> List[Any]:
            return [getattr(atom, "residue", None) for atom in self]

    receptor_residue = SimpleNamespace(name="REC", chain_id="A", number=1)
    ligand_residue = SimpleNamespace(name="LIG", chain_id="L", number=1)
    receptor_atom = SimpleNamespace(
        name="C1",
        element=SimpleNamespace(name="C"),
        coord=(0.0, 0.0, 0.0),
        residue=receptor_residue,
    )
    ligand_atom = SimpleNamespace(
        name="C2",
        element=SimpleNamespace(name="C"),
        coord=(3.5, 0.0, 0.0),
        residue=ligand_residue,
    )
    receptor_model = SimpleNamespace(
        name="section18_receptor",
        id_string="1",
        atoms=_SyntheticAtoms([receptor_atom]),
        residues=[receptor_residue],
    )
    pose_model = SimpleNamespace(
        name="section18_pose",
        id_string="2",
        atoms=_SyntheticAtoms([ligand_atom]),
        residues=[ligand_residue],
    )
    dock_model = DockModel(
        name="section18_pose",
        receptor=receptor_model,
        pose=pose_model,
        ligand=pose_model,
    )

    contact = SimpleNamespace(
        interaction_id="section18_contact",
        distance=3.5,
        score=1.0,
    )

    def _synthetic_contacts_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        stage_result = AnalysisStageResult(stage=STAGE_CONTACTS, required=True)
        stage_result.start().succeed(
            SimpleNamespace(contacts=(contact,), statistics={"total": 1})
        )
        return stage_result

    def _synthetic_consolidation_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        bundle = InteractionAnalysisBundle(contacts=[contact])
        stage_result = AnalysisStageResult(
            stage=STAGE_CONSOLIDATION,
            required=True,
        )
        stage_result.start().succeed(bundle)
        return stage_result

    def _synthetic_scoring_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        scoring = SimpleNamespace(final_score=1.0, interaction_count=1)
        stage_result = AnalysisStageResult(stage=STAGE_SCORING, required=True)
        stage_result.start().succeed(scoring)
        return stage_result

    registry = get_default_stage_registry(copy_registry=True)
    for stage, executor in (
        (STAGE_CONTACTS, _synthetic_contacts_executor),
        (STAGE_CONSOLIDATION, _synthetic_consolidation_executor),
        (STAGE_SCORING, _synthetic_scoring_executor),
    ):
        definition = registry.require(stage)
        registry.replace(
            replace(
                definition,
                executor=executor,
                result_adapter=None,
                validator=None,
                required_modules=(),
            )
        )

    integrated = AnalysisConfig(
        requested_stages=(
            STAGE_INPUT_RESOLUTION,
            STAGE_MODEL_PREPARATION,
            STAGE_CONTACTS,
            STAGE_CONSOLIDATION,
            STAGE_SCORING,
            STAGE_VALIDATION,
            STAGE_FINALIZATION,
        ),
        include_stage_dependencies=True,
        include_internal_stages=True,
    )
    options = SinglePoseExecutionOptions(
        requested_stages=integrated.requested_stages,
        include_dependencies=True,
        include_ordering_predecessors=False,
        inspect_capabilities=False,
        require_registered_executors=False,
        validate_input=True,
        validate_result=True,
    )
    output = run_single_pose_analysis(
        dock_model=dock_model,
        config=integrated,
        options=options,
        registry=registry,
    )
    if output.status != AnalysisStatus.SUCCEEDED:
        failures.append(
            f"Synthetic single-pose analysis ended as {output.status.value!r}."
        )
    if output.pose_result.interaction_count != 1:
        failures.append("Synthetic interaction consolidation count is invalid.")
    if output.pose_result.scoring is None:
        failures.append("Synthetic scoring payload was not retained.")
    expected_stages = integrated.requested_stages
    if tuple(output.pose_result.stage_results) != expected_stages:
        failures.append("Synthetic stage-result order is inconsistent.")
    output_errors = validate_single_pose_analysis_output(
        output,
        raise_on_error=False,
    )
    if output_errors:
        failures.extend(output_errors)
    json_payload = single_pose_analysis_to_json(output)
    if SINGLE_POSE_SCHEMA_NAME not in json_payload:
        failures.append("Single-pose JSON serialization omitted the schema name.")
    if len(options.fingerprint) != 64:
        failures.append("Single-pose options fingerprint is invalid.")
    if output.context.get_shared(SINGLE_POSE_OUTPUT_KEY) is not output:
        failures.append("Single-pose output was not retained in the context.")

    if failures:
        raise RuntimeError(
            "Single-pose orchestration convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": SINGLE_POSE_SCHEMA_NAME,
        "schema_version": SINGLE_POSE_SCHEMA_VERSION,
        "stage_count": len(output.pose_result.stage_results),
        "interaction_count": output.pose_result.interaction_count,
        "validated_cases": 24,
    }


