# 19.1. Schema, keys and orchestration conventions
# -----------------------------------------------------------------------------

MULTIPOSE_SCHEMA_NAME: Final[str] = "dockanalyzer.multipose_analysis"
MULTIPOSE_SCHEMA_VERSION: Final[str] = "1.0"
MULTIPOSE_OUTPUT_TYPE: Final[str] = "multipose_analysis_output"
MULTIPOSE_PLAN_KEY: Final[str] = "multipose_execution_plan"
MULTIPOSE_OUTPUT_KEY: Final[str] = "multipose_analysis_output"
MULTIPOSE_RESULT_KEY: Final[str] = "multipose_analysis_result"
MULTIPOSE_RUN_RESULT_KEY: Final[str] = "multipose_run_result"
MULTIPOSE_POSE_OUTPUTS_KEY: Final[str] = "multipose_pose_outputs"
MULTIPOSE_POSE_TRACE_KEY: Final[str] = "multipose_pose_trace"
MULTIPOSE_SCORING_OUTPUT_KEY: Final[str] = "multipose_scoring_output"
MULTIPOSE_METADATA_KEY: Final[str] = "multipose_orchestration"
MULTIPOSE_STATISTICS_KEY: Final[str] = "multipose_orchestration"

MULTIPOSE_GLOBAL_STAGES: Final[FrozenSet[str]] = frozenset(
    {
        STAGE_INPUT_RESOLUTION,
        STAGE_MODEL_PREPARATION,
        STAGE_CONSENSUS,
        STAGE_VALIDATION,
        STAGE_FINALIZATION,
    }
)
MULTIPOSE_PER_POSE_EXCLUDED_STAGES: Final[FrozenSet[str]] = frozenset(
    {STAGE_CONSENSUS, *OUTPUT_STAGES}
)
MULTIPOSE_DEFERRED_OUTPUT_STAGES: Final[FrozenSet[str]] = frozenset(OUTPUT_STAGES)
MULTIPOSE_SUCCESS_STATUSES: Final[FrozenSet[AnalysisStatus]] = frozenset(
    {AnalysisStatus.SUCCEEDED, AnalysisStatus.PARTIAL}
)

DEFAULT_MULTIPOSE_INCLUDE_DEPENDENCIES: Final[bool] = True
DEFAULT_MULTIPOSE_INCLUDE_ORDERING_PREDECESSORS: Final[bool] = True
DEFAULT_MULTIPOSE_INSPECT_CAPABILITIES: Final[bool] = True
DEFAULT_MULTIPOSE_LOAD_CAPABILITIES: Final[bool] = False
DEFAULT_MULTIPOSE_DROP_UNAVAILABLE_OPTIONAL_STAGES: Final[bool] = True
DEFAULT_MULTIPOSE_REQUIRE_REGISTERED_EXECUTORS: Final[bool] = False
DEFAULT_MULTIPOSE_CONTINUE_ON_POSE_ERROR: Final[bool] = True
DEFAULT_MULTIPOSE_STOP_ON_ANY_POSE_FAILURE: Final[bool] = False
DEFAULT_MULTIPOSE_RAISE_ON_ERROR: Final[bool] = False
DEFAULT_MULTIPOSE_VALIDATE_INPUT: Final[bool] = True
DEFAULT_MULTIPOSE_VALIDATE_RESULT: Final[bool] = True
DEFAULT_MULTIPOSE_PRESERVE_CONTEXT: Final[bool] = True
DEFAULT_MULTIPOSE_RUN_NATIVE_SCORING: Final[bool] = True
DEFAULT_MULTIPOSE_BUILD_RANKING: Final[bool] = True
DEFAULT_MULTIPOSE_BUILD_CONSENSUS: Final[bool] = True
DEFAULT_MULTIPOSE_ATTACH_GLOBAL_RESULTS: Final[bool] = True
DEFAULT_MULTIPOSE_INCLUDE_FAILED_IN_RANKING: Final[bool] = False
DEFAULT_MULTIPOSE_MINIMUM_SUCCESSFUL_POSES: Final[int] = 1


class MultiposePoseDisposition(str, Enum):
    """Terminal disposition of one pose within a multipose run."""

    SUCCEEDED = "succeeded"
    PARTIAL = "partial"
    FAILED = "failed"
    CANCELLED = "cancelled"
    SKIPPED = "skipped"


# 19.2. Execution options
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class MultiposeExecutionOptions:
    """Immutable controls for one complete multipose analysis."""

    requested_stages: Tuple[str, ...] = ()
    include_dependencies: bool = DEFAULT_MULTIPOSE_INCLUDE_DEPENDENCIES
    include_ordering_predecessors: bool = (
        DEFAULT_MULTIPOSE_INCLUDE_ORDERING_PREDECESSORS
    )
    inspect_capabilities: bool = DEFAULT_MULTIPOSE_INSPECT_CAPABILITIES
    load_capabilities: bool = DEFAULT_MULTIPOSE_LOAD_CAPABILITIES
    drop_unavailable_optional_stages: bool = (
        DEFAULT_MULTIPOSE_DROP_UNAVAILABLE_OPTIONAL_STAGES
    )
    require_registered_executors: bool = (
        DEFAULT_MULTIPOSE_REQUIRE_REGISTERED_EXECUTORS
    )
    continue_on_pose_error: bool = DEFAULT_MULTIPOSE_CONTINUE_ON_POSE_ERROR
    stop_on_any_pose_failure: bool = DEFAULT_MULTIPOSE_STOP_ON_ANY_POSE_FAILURE
    raise_on_error: bool = DEFAULT_MULTIPOSE_RAISE_ON_ERROR
    validate_input: bool = DEFAULT_MULTIPOSE_VALIDATE_INPUT
    validate_result: bool = DEFAULT_MULTIPOSE_VALIDATE_RESULT
    preserve_context: bool = DEFAULT_MULTIPOSE_PRESERVE_CONTEXT
    run_native_multipose_scoring: bool = DEFAULT_MULTIPOSE_RUN_NATIVE_SCORING
    build_ranking: bool = DEFAULT_MULTIPOSE_BUILD_RANKING
    build_consensus: bool = DEFAULT_MULTIPOSE_BUILD_CONSENSUS
    attach_global_results: bool = DEFAULT_MULTIPOSE_ATTACH_GLOBAL_RESULTS
    include_failed_in_ranking: bool = (
        DEFAULT_MULTIPOSE_INCLUDE_FAILED_IN_RANKING
    )
    minimum_successful_poses: int = DEFAULT_MULTIPOSE_MINIMUM_SUCCESSFUL_POSES
    single_pose_options: SinglePoseExecutionOptions = field(
        default_factory=SinglePoseExecutionOptions
    )
    ranking_options: Mapping[str, Any] = field(default_factory=dict)
    consensus_options: Mapping[str, Any] = field(default_factory=dict)
    stage_overrides: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "requested_stages",
            canonicalize_stage_sequence(
                self.requested_stages,
                strict=True,
                unique=True,
                sort=False,
            ),
        )
        for field_name in (
            "include_dependencies",
            "include_ordering_predecessors",
            "inspect_capabilities",
            "load_capabilities",
            "drop_unavailable_optional_stages",
            "require_registered_executors",
            "continue_on_pose_error",
            "stop_on_any_pose_failure",
            "raise_on_error",
            "validate_input",
            "validate_result",
            "preserve_context",
            "run_native_multipose_scoring",
            "build_ranking",
            "build_consensus",
            "attach_global_results",
            "include_failed_in_ranking",
        ):
            object.__setattr__(self, field_name, bool(getattr(self, field_name)))
        minimum = int(self.minimum_successful_poses)
        if minimum < 1:
            raise AnalysisConfigurationError(
                "minimum_successful_poses must be at least one."
            )
        if minimum > MAX_MULTIPOSE_ITEMS:
            raise AnalysisConfigurationError(
                "minimum_successful_poses exceeds the multipose item limit."
            )
        object.__setattr__(self, "minimum_successful_poses", minimum)
        object.__setattr__(
            self,
            "single_pose_options",
            coerce_single_pose_execution_options(self.single_pose_options),
        )
        for field_name in ("ranking_options", "consensus_options", "metadata"):
            value = getattr(self, field_name)
            if not isinstance(value, Mapping):
                raise AnalysisConfigurationError(
                    f"multipose {field_name} must be a mapping."
                )
            object.__setattr__(self, field_name, MappingProxyType(dict(value)))
        if not isinstance(self.stage_overrides, Mapping):
            raise AnalysisConfigurationError(
                "multipose stage_overrides must be a mapping."
            )
        normalized_overrides: Dict[str, Mapping[str, Any]] = {}
        for raw_stage, raw_values in self.stage_overrides.items():
            stage = canonicalize_stage_name(raw_stage)
            if raw_values is None:
                normalized_overrides[stage] = MappingProxyType({})
            elif isinstance(raw_values, Mapping):
                normalized_overrides[stage] = MappingProxyType(dict(raw_values))
            else:
                raise AnalysisConfigurationError(
                    f"Overrides for stage {stage!r} must be a mapping."
                )
        object.__setattr__(
            self,
            "stage_overrides",
            MappingProxyType(normalized_overrides),
        )

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "MultiposeExecutionOptions":
        """Create multipose options from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Multipose execution options must be a mapping."
            )
        aliases = {
            "stages": "requested_stages",
            "requested": "requested_stages",
            "dependencies": "include_dependencies",
            "ordering": "include_ordering_predecessors",
            "inspect": "inspect_capabilities",
            "load": "load_capabilities",
            "drop_unavailable": "drop_unavailable_optional_stages",
            "require_executors": "require_registered_executors",
            "continue_on_error": "continue_on_pose_error",
            "stop_on_failure": "stop_on_any_pose_failure",
            "raise": "raise_on_error",
            "validate_inputs": "validate_input",
            "validate_results": "validate_result",
            "native_scoring": "run_native_multipose_scoring",
            "ranking": "build_ranking",
            "consensus": "build_consensus",
            "attach": "attach_global_results",
            "include_failed": "include_failed_in_ranking",
            "minimum_success": "minimum_successful_poses",
            "single_pose": "single_pose_options",
            "overrides": "stage_overrides",
        }
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        unknown: List[str] = []
        for raw_key, value in values.items():
            token = _normalize_convention_token(
                raw_key,
                field_name="multipose option",
            )
            key = aliases.get(token, token)
            if key not in allowed:
                unknown.append(str(raw_key))
                continue
            if key in normalized:
                raise AnalysisConfigurationError(
                    f"Duplicate multipose option {key!r}."
                )
            normalized[key] = value
        if unknown and strict:
            raise AnalysisConfigurationError(
                "Unknown multipose options: " + ", ".join(sorted(unknown)) + "."
            )
        return cls(**normalized)

    def stage_override(self, stage: Any) -> Mapping[str, Any]:
        """Return immutable overrides for one stage."""

        canonical = canonicalize_stage_name(stage)
        return self.stage_overrides.get(canonical, MappingProxyType({}))

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready options mapping."""

        return {
            "requested_stages": list(self.requested_stages),
            "include_dependencies": self.include_dependencies,
            "include_ordering_predecessors": self.include_ordering_predecessors,
            "inspect_capabilities": self.inspect_capabilities,
            "load_capabilities": self.load_capabilities,
            "drop_unavailable_optional_stages": (
                self.drop_unavailable_optional_stages
            ),
            "require_registered_executors": self.require_registered_executors,
            "continue_on_pose_error": self.continue_on_pose_error,
            "stop_on_any_pose_failure": self.stop_on_any_pose_failure,
            "raise_on_error": self.raise_on_error,
            "validate_input": self.validate_input,
            "validate_result": self.validate_result,
            "preserve_context": self.preserve_context,
            "run_native_multipose_scoring": self.run_native_multipose_scoring,
            "build_ranking": self.build_ranking,
            "build_consensus": self.build_consensus,
            "attach_global_results": self.attach_global_results,
            "include_failed_in_ranking": self.include_failed_in_ranking,
            "minimum_successful_poses": self.minimum_successful_poses,
            "single_pose_options": self.single_pose_options.to_dict(),
            "ranking_options": to_json_compatible(dict(self.ranking_options)),
            "consensus_options": to_json_compatible(dict(self.consensus_options)),
            "stage_overrides": {
                stage: to_json_compatible(dict(values))
                for stage, values in self.stage_overrides.items()
            },
            "metadata": to_json_compatible(dict(self.metadata)),
        }

    @property
    def fingerprint(self) -> str:
        """Return a deterministic SHA-256 fingerprint."""

        payload = json.dumps(
            self.to_dict(),
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode(ANALYSIS_ENCODING)
        return sha256(payload).hexdigest()


MultiposeExecutionOptionsLike: TypeAlias = Union[
    MultiposeExecutionOptions,
    Mapping[str, Any],
    None,
]


def coerce_multipose_execution_options(
    value: MultiposeExecutionOptionsLike = None,
) -> MultiposeExecutionOptions:
    """Return normalized multipose execution options."""

    if value is None:
        return MultiposeExecutionOptions()
    if isinstance(value, MultiposeExecutionOptions):
        return value
    if isinstance(value, Mapping):
        return MultiposeExecutionOptions.from_mapping(value)
    raise AnalysisConfigurationError(
        "Multipose options must be a mapping or MultiposeExecutionOptions."
    )


# 19.3. Pose trace and complete output
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class MultiposePoseTrace:
    """Compact trace entry for one analyzed pose."""

    index: int
    pose_id: str
    name: str
    status: Union[AnalysisStatus, str]
    disposition: Union[MultiposePoseDisposition, str]
    interaction_count: int = 0
    score: Optional[float] = None
    duration_seconds: Optional[float] = None
    failed_stages: Tuple[str, ...] = ()
    warning_count: int = 0
    error_count: int = 0
    message: Optional[str] = None

    def __post_init__(self) -> None:
        if self.index < 0:
            raise ValueError("Multipose pose-trace index cannot be negative.")
        object.__setattr__(
            self,
            "pose_id",
            _normalize_result_identifier(self.pose_id, fallback="pose"),
        )
        object.__setattr__(
            self,
            "name",
            _normalize_result_name(self.name, fallback="pose"),
        )
        status = canonicalize_analysis_status(self.status)
        object.__setattr__(self, "status", status)
        disposition = self.disposition
        if not isinstance(disposition, MultiposePoseDisposition):
            disposition = MultiposePoseDisposition(
                _normalize_convention_token(
                    disposition,
                    field_name="multipose pose disposition",
                )
            )
        object.__setattr__(self, "disposition", disposition)
        object.__setattr__(self, "interaction_count", max(0, int(self.interaction_count)))
        score = self.score
        if score is not None:
            try:
                score = float(score)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError("Multipose pose-trace score must be numeric.") from exc
            if not math.isfinite(score):
                raise ValueError("Multipose pose-trace score must be finite.")
        object.__setattr__(self, "score", score)
        object.__setattr__(self, "duration_seconds", _normalize_duration(self.duration_seconds))
        object.__setattr__(self, "failed_stages", tuple(self.failed_stages))
        object.__setattr__(self, "warning_count", max(0, int(self.warning_count)))
        object.__setattr__(self, "error_count", max(0, int(self.error_count)))
        if self.message is not None:
            object.__setattr__(self, "message", str(self.message))

    @classmethod
    def from_pose_result(
        cls,
        index: int,
        result: PoseAnalysisResult,
        *,
        message: Optional[str] = None,
    ) -> "MultiposePoseTrace":
        """Create a trace entry from a pose result."""

        status = canonicalize_analysis_status(result.status)
        if status == AnalysisStatus.SUCCEEDED:
            disposition = MultiposePoseDisposition.SUCCEEDED
        elif status == AnalysisStatus.PARTIAL:
            disposition = MultiposePoseDisposition.PARTIAL
        elif status == AnalysisStatus.CANCELLED:
            disposition = MultiposePoseDisposition.CANCELLED
        elif status == AnalysisStatus.SKIPPED:
            disposition = MultiposePoseDisposition.SKIPPED
        else:
            disposition = MultiposePoseDisposition.FAILED
        return cls(
            index=index,
            pose_id=result.pose_id,
            name=result.name,
            status=status,
            disposition=disposition,
            interaction_count=result.interaction_count,
            score=_multipose_pose_numeric_score(result),
            duration_seconds=result.duration_seconds,
            failed_stages=result.failed_stages,
            warning_count=len(result.diagnostics.warnings),
            error_count=len(result.diagnostics.errors),
            message=message,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready trace mapping."""

        return {
            "index": self.index,
            "pose_id": self.pose_id,
            "name": self.name,
            "status": self.status.value,
            "disposition": self.disposition.value,
            "interaction_count": self.interaction_count,
            "score": self.score,
            "duration_seconds": self.duration_seconds,
            "failed_stages": list(self.failed_stages),
            "warning_count": self.warning_count,
            "error_count": self.error_count,
            "message": self.message,
        }


@dataclass
class MultiposeAnalysisOutput:
    """Complete output of one integrated multipose orchestration run."""

    request: AnalysisRequest
    context: AnalysisContext
    plan: AnalysisExecutionPlan
    multipose_result: MultiPoseAnalysisResult
    run_result: AnalysisRunResult
    resolved_input: Optional[ResolvedAnalysisInput] = None
    preparation: Optional[ModelPreparationResult] = None
    pose_outputs: List[SinglePoseAnalysisOutput] = field(default_factory=list)
    pose_trace: List[MultiposePoseTrace] = field(default_factory=list)
    native_scoring_output: Optional[ScoringMultiposeOutput] = None
    warnings: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)
    options: MultiposeExecutionOptions = field(
        default_factory=MultiposeExecutionOptions
    )
    result_type: str = MULTIPOSE_OUTPUT_TYPE

    def __post_init__(self) -> None:
        if not isinstance(self.request, AnalysisRequest):
            self.request = coerce_analysis_request(self.request)
        if not isinstance(self.context, AnalysisContext):
            raise TypeError("context must be an AnalysisContext instance.")
        if not isinstance(self.plan, AnalysisExecutionPlan):
            raise TypeError("plan must be an AnalysisExecutionPlan instance.")
        if not isinstance(self.multipose_result, MultiPoseAnalysisResult):
            self.multipose_result = coerce_multipose_analysis_result(
                self.multipose_result
            )
        if not isinstance(self.run_result, AnalysisRunResult):
            raise TypeError("run_result must be an AnalysisRunResult instance.")
        self.pose_outputs = list(self.pose_outputs)
        self.pose_trace = [
            item if isinstance(item, MultiposePoseTrace) else MultiposePoseTrace(**item)
            for item in self.pose_trace
        ]
        self.warnings = unique_preserving_order(self.warnings)
        self.errors = unique_preserving_order(self.errors)
        self.metadata = dict(self.metadata)
        self.options = coerce_multipose_execution_options(self.options)

    @property
    def status(self) -> AnalysisStatus:
        """Return the aggregate multipose status."""

        return self.multipose_result.status

    @property
    def succeeded(self) -> bool:
        """Return whether the run succeeded completely."""

        return self.status == AnalysisStatus.SUCCEEDED

    @property
    def partial(self) -> bool:
        """Return whether the run produced partial accepted results."""

        return self.status == AnalysisStatus.PARTIAL

    @property
    def failed(self) -> bool:
        """Return whether the run failed."""

        return self.status == AnalysisStatus.FAILED

    @property
    def cancelled(self) -> bool:
        """Return whether the run was cancelled."""

        return self.status == AnalysisStatus.CANCELLED

    @property
    def pose_results(self) -> Tuple[PoseAnalysisResult, ...]:
        """Return all integrated pose results."""

        return tuple(self.multipose_result.pose_results)

    @property
    def successful_pose_results(self) -> Tuple[PoseAnalysisResult, ...]:
        """Return successful and partial pose results."""

        return tuple(
            result
            for result in self.pose_results
            if result.status in MULTIPOSE_SUCCESS_STATUSES
        )

    @property
    def failed_pose_results(self) -> Tuple[PoseAnalysisResult, ...]:
        """Return failed or cancelled pose results."""

        return tuple(
            result
            for result in self.pose_results
            if result.status not in MULTIPOSE_SUCCESS_STATUSES
        )

    @property
    def best_pose(self) -> Optional[PoseAnalysisResult]:
        """Return the best ranked pose."""

        return self.multipose_result.best_pose

    def summary(self) -> Dict[str, Any]:
        """Return a concise orchestration summary."""

        best = self.best_pose
        scores = [
            score
            for score in (_multipose_pose_numeric_score(item) for item in self.pose_results)
            if score is not None
        ]
        return {
            "schema": MULTIPOSE_SCHEMA_NAME,
            "schema_version": MULTIPOSE_SCHEMA_VERSION,
            "run_id": self.context.run_id,
            "request_id": self.request.request_id,
            "name": self.multipose_result.name,
            "status": self.status.value,
            "plan_id": self.plan.plan_id,
            "pose_count": len(self.pose_results),
            "successful_pose_count": len(self.successful_pose_results),
            "failed_pose_count": len(self.failed_pose_results),
            "best_pose_id": best.pose_id if best is not None else None,
            "best_score": max(scores) if scores else None,
            "interaction_count": sum(item.interaction_count for item in self.pose_results),
            "ranking_generated": bool(self.multipose_result.ranking),
            "consensus_generated": self.multipose_result.consensus is not None,
            "native_scoring_used": self.native_scoring_output is not None,
            "warning_count": len(self.warnings),
            "error_count": len(self.errors),
            "duration_seconds": self.multipose_result.duration_seconds,
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready multipose output mapping."""

        return {
            "schema": MULTIPOSE_SCHEMA_NAME,
            "schema_version": MULTIPOSE_SCHEMA_VERSION,
            "result_type": self.result_type,
            "status": self.status.value,
            "request": self.request.to_dict(include_objects=include_objects),
            "context": {
                "run_id": self.context.run_id,
                "request_id": self.context.request_id,
                "mode": self.context.mode,
                "status": self.context.status.value,
                "current_stage": self.context.current_stage,
                "current_pose_index": self.context.current_pose_index,
                "pose_count": self.context.pose_count,
                "started_at": self.context.started_at,
                "cancelled": self.context.is_cancelled(),
                "config": self.context.config.to_dict(),
                "statistics": to_json_compatible(self.context.statistics),
                "files": to_json_compatible(self.context.files),
                "metadata": to_json_compatible(self.context.metadata),
            },
            "plan": self.plan.to_dict(),
            "multipose_result": self.multipose_result.to_dict(
                include_objects=include_objects
            ),
            "run_result": {
                "run_id": self.run_result.run_id,
                "request_id": self.run_result.request_id,
                "name": self.run_result.name,
                "mode": self.run_result.mode,
                "status": self.run_result.status.value,
                "result_type": self.run_result.result_type,
                "stage_results": {
                    stage: result.to_dict()
                    for stage, result in self.run_result.stage_results.items()
                },
                "statistics": to_json_compatible(self.run_result.statistics),
                "files": to_json_compatible(self.run_result.files),
                "metadata": to_json_compatible(self.run_result.metadata),
                "provenance": to_json_compatible(self.run_result.provenance),
                "timings": to_json_compatible(self.run_result.timings),
                "diagnostics": self.run_result.diagnostics.to_dict(),
                "started_at": self.run_result.started_at,
                "finished_at": self.run_result.finished_at,
                "duration_seconds": self.run_result.duration_seconds,
            },
            "resolved_input": (
                self.resolved_input.to_dict(include_objects=include_objects)
                if self.resolved_input is not None
                else None
            ),
            "preparation": (
                self.preparation.to_dict(include_objects=include_objects)
                if self.preparation is not None
                else None
            ),
            "pose_outputs": [
                output.to_dict(include_objects=include_objects)
                for output in self.pose_outputs
            ],
            "pose_trace": [item.to_dict() for item in self.pose_trace],
            "native_scoring_output": (
                self.native_scoring_output.to_dict(include_results=False)
                if self.native_scoring_output is not None
                else None
            ),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(self.metadata),
            "options": self.options.to_dict(),
            "summary": self.summary(),
        }


# 19.4. Request, context and plan construction
# -----------------------------------------------------------------------------


def _multipose_config_with_mode(
    config: AnalysisConfigLike,
    mode: str,
    *,
    requested_stages: Optional[Sequence[str]] = None,
) -> AnalysisConfig:
    """Return an analysis configuration with a selected runtime mode."""

    integrated = coerce_analysis_config(config)
    runtime = replace(integrated.runtime, analysis_mode=mode)
    updates: Dict[str, Any] = {"runtime": runtime}
    if requested_stages is not None:
        updates["requested_stages"] = tuple(requested_stages)
    return replace(integrated, **updates)


def build_multipose_request(
    value: Any = None,
    *,
    receptor: Any = None,
    poses: Any = None,
    dock_models: Any = None,
    session: Any = None,
    config: AnalysisConfigLike = None,
    requested_stages: Any = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisRequest:
    """Build one normalized multipose request."""

    integrated = _multipose_config_with_mode(config, ANALYSIS_MODE_MULTIPOSE)
    if isinstance(value, AnalysisContext):
        request = value.request
    elif isinstance(value, ResolvedAnalysisInput):
        request = value.request
    elif isinstance(value, AnalysisRequest):
        request = value
    else:
        request = create_analysis_request(value, config=integrated)

    updates: Dict[str, Any] = {
        "config": integrated,
        "mode": ANALYSIS_MODE_MULTIPOSE,
    }
    if name is not None:
        updates["name"] = normalize_text(name, default="multipose_analysis")
    if receptor is not None:
        updates["receptor"] = receptor
    if poses is not None:
        updates["poses"] = tuple(normalize_object_sequence(poses))
    if dock_models is not None:
        updates["dock_models"] = tuple(normalize_object_sequence(dock_models))
    if session is not None:
        updates["session"] = session
    if requested_stages is not None:
        updates["requested_stages"] = canonicalize_stage_sequence(
            requested_stages,
            strict=True,
            unique=True,
            sort=False,
        )
    elif integrated.requested_stages:
        updates["requested_stages"] = tuple(integrated.requested_stages)
    if metadata:
        merged_metadata = dict(request.metadata)
        merged_metadata.update(dict(metadata))
        updates["metadata"] = merged_metadata
    return replace(request, **updates)


def create_multipose_context(
    request: AnalysisRequestLike,
    *,
    context: Optional[AnalysisContext] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
) -> AnalysisContext:
    """Create or reset a runtime context for multipose execution."""

    normalized = (
        request if isinstance(request, AnalysisRequest) else coerce_analysis_request(request)
    )
    if context is None:
        return AnalysisContext(
            request=normalized,
            config=normalized.config,
            mode=ANALYSIS_MODE_MULTIPOSE,
            progress_callback=progress_callback,
            stage_callback=stage_callback,
            cancellation_callback=cancellation_callback,
        )
    context.request = normalized
    context.config = normalized.config
    context.mode = ANALYSIS_MODE_MULTIPOSE
    context.status = AnalysisStatus.PENDING
    context.current_pose_index = None
    context.current_stage = None
    context.stage_data.clear()
    context.shared_data.clear()
    context.statistics.clear()
    context.files.clear()
    context.metadata.update(dict(normalized.metadata))
    if progress_callback is not None:
        context.progress_callback = progress_callback
    if stage_callback is not None:
        context.stage_callback = stage_callback
    if cancellation_callback is not None:
        context.cancellation_callback = cancellation_callback
    return context


def build_multipose_execution_plan(
    config: AnalysisConfigLike = None,
    *,
    request: Optional[AnalysisRequest] = None,
    options: MultiposeExecutionOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
) -> AnalysisExecutionPlan:
    """Build a deterministic global plan for a multipose run."""

    resolved_options = coerce_multipose_execution_options(options)
    integrated = coerce_analysis_config(config or (request.config if request else None))
    requested = (
        resolved_options.requested_stages
        or (request.requested_stages if request is not None else ())
        or integrated.requested_stages
        or integrated.desired_stages(analysis_mode=ANALYSIS_MODE_MULTIPOSE)
    )
    return build_analysis_execution_plan(
        integrated,
        registry=registry,
        capabilities=capabilities,
        requested_stages=requested,
        analysis_mode=ANALYSIS_MODE_MULTIPOSE,
        include_dependencies=resolved_options.include_dependencies,
        include_ordering_predecessors=(
            resolved_options.include_ordering_predecessors
        ),
        inspect_capabilities=resolved_options.inspect_capabilities,
        load_capabilities=resolved_options.load_capabilities,
        drop_unavailable_optional_stages=(
            resolved_options.drop_unavailable_optional_stages
        ),
        require_registered_executors=(
            resolved_options.require_registered_executors
        ),
        strict=False,
    )


# 19.5. Input resolution and model preparation
# -----------------------------------------------------------------------------


def execute_multipose_input_resolution(
    context: AnalysisContext,
    *,
    validate_input: bool = True,
) -> Tuple[AnalysisStageResult, Optional[ResolvedAnalysisInput]]:
    """Resolve the complete multipose input once at the parent level."""

    result = AnalysisStageResult(stage=STAGE_INPUT_RESOLUTION, required=True)
    resolved: Optional[ResolvedAnalysisInput] = None
    context.set_current_stage(STAGE_INPUT_RESOLUTION)
    try:
        context.raise_if_cancelled(stage=STAGE_INPUT_RESOLUTION)
        result.start()
        resolved = resolve_analysis_input(
            context,
            strict=False,
            allow_empty=False,
        )
        if resolved.mode not in {ANALYSIS_MODE_MULTIPOSE, ANALYSIS_MODE_SINGLE_POSE}:
            raise AnalysisInputError(
                "Multipose orchestration requires molecular pose input.",
                stage=STAGE_INPUT_RESOLUTION,
                details={"resolved_mode": resolved.mode},
            )
        if validate_input:
            validation = validate_resolved_analysis_input(
                resolved,
                strict=False,
                allow_empty=False,
            )
            if validation["errors"]:
                raise AnalysisInputError(
                    "Multipose input validation failed: "
                    + " ".join(validation["errors"]),
                    stage=STAGE_INPUT_RESOLUTION,
                    details=validation,
                )
        apply_resolved_input_to_context(context, resolved)
        context.mode = ANALYSIS_MODE_MULTIPOSE
        result.statistics = {
            "resolved_pose_count": len(resolved.poses),
            "resolved_dock_model_count": len(resolved.dock_models),
            "resolved_item_count": resolved.item_count,
        }
        result.output_summary = summarize_resolved_analysis_input(resolved)
        result.succeed(resolved, message="Multipose input resolved successfully.")
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisInputError(
                "Multipose input resolution failed.",
                stage=STAGE_INPUT_RESOLUTION,
                cause=exc,
            )
        result.start().fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
    finally:
        context.set_stage_data(STAGE_INPUT_RESOLUTION, result)
        context.notify_stage(result)
        context.set_current_stage(None)
    return result, resolved


def execute_multipose_model_preparation(
    context: AnalysisContext,
    resolved: ResolvedAnalysisInput,
    *,
    validate_result: bool = True,
) -> Tuple[AnalysisStageResult, Optional[ModelPreparationResult]]:
    """Prepare all DockModel objects for a multipose run."""

    result = AnalysisStageResult(stage=STAGE_MODEL_PREPARATION, required=True)
    preparation: Optional[ModelPreparationResult] = None
    context.set_current_stage(STAGE_MODEL_PREPARATION)
    try:
        context.raise_if_cancelled(stage=STAGE_MODEL_PREPARATION)
        result.start()
        preparation = prepare_resolved_dock_models(
            resolved,
            config=context.config,
        )
        if validate_result:
            validation = validate_model_preparation_result(
                preparation,
                strict=False,
            )
            if validation["errors"]:
                raise AnalysisValidationError(
                    "Multipose model preparation validation failed: "
                    + " ".join(validation["errors"]),
                    stage=STAGE_MODEL_PREPARATION,
                    details=validation,
                )
        if not preparation.dock_models:
            raise AnalysisInputError(
                "Multipose preparation did not produce any DockModel objects.",
                stage=STAGE_MODEL_PREPARATION,
            )
        context.receptor = preparation.receptor
        if context.receptor is None and preparation.dock_models:
            context.receptor = get_object_value(
                preparation.dock_models[0],
                DOCK_MODEL_FIELD_RECEPTOR,
                default=None,
            )
        context.poses = list(preparation.poses)
        context.dock_models = list(preparation.dock_models)
        result.statistics = {
            "prepared_count": preparation.prepared_count,
            "ready_count": preparation.ready_count,
            "warning_count": len(preparation.warnings),
            "error_count": len(preparation.errors),
        }
        result.output_summary = preparation.summary()
        if preparation.errors:
            issue = AnalysisPartialResultWarning(
                "Multipose preparation completed with recoverable errors.",
                stage=STAGE_MODEL_PREPARATION,
                details={"errors": list(preparation.errors)},
            )
            result.partial(preparation, issue=issue)
        else:
            result.succeed(
                preparation,
                message="Multipose DockModel preparation completed successfully.",
            )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisIntegrationError(
                "Multipose model preparation failed.",
                stage=STAGE_MODEL_PREPARATION,
                cause=exc,
            )
        result.start().fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
    finally:
        context.set_stage_data(STAGE_MODEL_PREPARATION, result)
        context.notify_stage(result)
        context.set_current_stage(None)
    return result, preparation


# 19.6. Per-pose pipeline construction
# -----------------------------------------------------------------------------


def multipose_per_pose_stages(plan: AnalysisExecutionPlan) -> Tuple[str, ...]:
    """Return the ordered stages executed independently for every pose."""

    selected = [
        entry.stage
        for entry in plan.entries
        if entry.stage not in MULTIPOSE_PER_POSE_EXCLUDED_STAGES
    ]
    required_prefix = [STAGE_INPUT_RESOLUTION, STAGE_MODEL_PREPARATION]
    required_suffix = [STAGE_VALIDATION, STAGE_FINALIZATION]
    combined = [*required_prefix, *selected, *required_suffix]
    return tuple(
        stage
        for stage in canonicalize_stage_sequence(
            combined,
            strict=True,
            unique=True,
            sort=True,
        )
        if stage != STAGE_CONSENSUS and stage not in OUTPUT_STAGES
    )


def build_multipose_single_pose_options(
    options: MultiposeExecutionOptions,
    *,
    stages: Sequence[str],
) -> SinglePoseExecutionOptions:
    """Derive child-pipeline options for one pose."""

    base = options.single_pose_options
    return replace(
        base,
        requested_stages=tuple(stages),
        include_dependencies=True,
        include_ordering_predecessors=False,
        inspect_capabilities=options.inspect_capabilities,
        load_capabilities=options.load_capabilities,
        drop_unavailable_optional_stages=options.drop_unavailable_optional_stages,
        require_registered_executors=options.require_registered_executors,
        allow_deferred_stages=True,
        stop_on_required_failure=True,
        stop_on_any_failure=options.stop_on_any_pose_failure,
        raise_on_error=False,
        validate_input=options.validate_input,
        validate_result=options.validate_result,
        preserve_context=True,
        stage_overrides=options.stage_overrides,
        metadata={
            **dict(base.metadata),
            "parent_mode": ANALYSIS_MODE_MULTIPOSE,
            "multipose_options_fingerprint": options.fingerprint,
        },
    )


def _multipose_child_config(
    config: AnalysisConfig,
    stages: Sequence[str],
) -> AnalysisConfig:
    """Return a single-pose child configuration."""

    return _multipose_config_with_mode(
        config,
        ANALYSIS_MODE_SINGLE_POSE,
        requested_stages=stages,
    )


def _multipose_pose_numeric_score(value: Any) -> Optional[float]:
    """Extract a finite comparable score from a pose result or score payload."""

    scoring = value.scoring if isinstance(value, PoseAnalysisResult) else value
    if isinstance(scoring, Real) and not isinstance(scoring, bool):
        numeric = float(scoring)
        return numeric if math.isfinite(numeric) else None
    candidates = [
        get_object_value(scoring, "final_score", default=MISSING_VALUE),
        get_object_value(scoring, "normalized_score", default=MISSING_VALUE),
        get_object_value(scoring, "total_score", default=MISSING_VALUE),
        get_object_value(scoring, "score", default=MISSING_VALUE),
    ]
    summary = get_object_value(scoring, "summary", default=None)
    if summary is not None:
        candidates.extend(
            [
                get_object_value(summary, "final_score", default=MISSING_VALUE),
                get_object_value(summary, "normalized_score", default=MISSING_VALUE),
                get_object_value(summary, "total_score", default=MISSING_VALUE),
            ]
        )
    for candidate in candidates:
        if is_missing_value(candidate) or candidate is None or isinstance(candidate, bool):
            continue
        try:
            numeric = float(candidate)
        except (TypeError, ValueError, OverflowError):
            continue
        if math.isfinite(numeric):
            return numeric
    return None


def _failed_multipose_pose_result(
    index: int,
    dock_model: Any,
    error: BaseException,
    *,
    started_at: Optional[str] = None,
) -> PoseAnalysisResult:
    """Create a structured failed pose result after child-pipeline failure."""

    name = get_preparation_model_name(dock_model, default=f"pose_{index + 1}")
    pose_id = get_preparation_model_identifier(dock_model) or f"pose-{index + 1}"
    result = PoseAnalysisResult(
        pose_id=pose_id,
        name=name,
        status=AnalysisStatus.FAILED,
        dock_model=dock_model,
        receptor=get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_RECEPTOR,
            default=None,
        ),
        ligand=get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_LIGAND,
            default=None,
        ),
        pose=get_object_value(
            dock_model,
            DOCK_MODEL_FIELD_POSE,
            default=None,
        ),
        started_at=started_at or _utc_timestamp(),
        metadata={
            "analysis_mode": ANALYSIS_MODE_MULTIPOSE,
            "pose_index": index,
        },
    )
    result.diagnostics.add_error(error)
    stage_result = AnalysisStageResult(stage=STAGE_FINALIZATION, required=True)
    stage_result.start().fail(error)
    result.add_stage_result(stage_result)
    return result.finalize(AnalysisStatus.FAILED)


def run_multipose_pose_pipelines(
    context: AnalysisContext,
    preparation: ModelPreparationResult,
    *,
    plan: AnalysisExecutionPlan,
    options: MultiposeExecutionOptions,
    registry: AnalysisStageRegistry,
    capabilities: Optional[AnalysisCapabilities] = None,
) -> Tuple[List[SinglePoseAnalysisOutput], List[PoseAnalysisResult], List[MultiposePoseTrace]]:
    """Execute the validated single-pose pipeline for every prepared model."""

    stages = multipose_per_pose_stages(plan)
    child_options = build_multipose_single_pose_options(options, stages=stages)
    child_config = _multipose_child_config(context.config, stages)
    outputs: List[SinglePoseAnalysisOutput] = []
    results: List[PoseAnalysisResult] = []
    traces: List[MultiposePoseTrace] = []
    total = len(preparation.dock_models)

    for index, dock_model in enumerate(preparation.dock_models):
        if context.is_cancelled():
            break
        context.set_current_pose(index)
        started_at = _utc_timestamp()
        try:
            output = run_single_pose_analysis(
                dock_model=dock_model,
                config=child_config,
                options=child_options,
                registry=registry,
                capabilities=capabilities,
                name=get_preparation_model_name(
                    dock_model,
                    default=f"pose_{index + 1}",
                ),
                metadata={
                    "parent_run_id": context.run_id,
                    "parent_request_id": context.request_id,
                    "pose_index": index,
                    "pose_count": total,
                },
                stage_callback=context.stage_callback,
                cancellation_callback=context.cancellation_callback,
            )
            outputs.append(output)
            pose_result = output.pose_result
        except Exception as exc:
            wrapped = exc
            if not isinstance(exc, AnalysisError):
                wrapped = AnalysisStageError(
                    f"Multipose child pipeline failed at pose index {index}.",
                    details={"pose_index": index},
                    cause=exc,
                )
            pose_result = _failed_multipose_pose_result(
                index,
                dock_model,
                wrapped,
                started_at=started_at,
            )
            if not options.continue_on_pose_error:
                results.append(pose_result)
                traces.append(
                    MultiposePoseTrace.from_pose_result(
                        index,
                        pose_result,
                        message=str(wrapped),
                    )
                )
                break
        results.append(pose_result)
        traces.append(MultiposePoseTrace.from_pose_result(index, pose_result))
        context.update_progress(
            STAGE_FINALIZATION,
            index + 1,
            total,
            {
                "scope": ANALYSIS_MODE_MULTIPOSE,
                "pose_index": index,
                "pose_id": pose_result.pose_id,
                "pose_status": pose_result.status.value,
            },
        )
        if (
            pose_result.status not in MULTIPOSE_SUCCESS_STATUSES
            and options.stop_on_any_pose_failure
        ):
            break
    context.set_current_pose(None)
    return outputs, results, traces


# 19.7. Ranking and preliminary consensus
# -----------------------------------------------------------------------------


def build_multipose_ranking(
    pose_results: Sequence[PoseAnalysisResult],
    *,
    include_failed: bool = False,
) -> List[Dict[str, Any]]:
    """Build a stable fallback ranking from integrated pose scores."""

    candidates: List[Tuple[int, PoseAnalysisResult, Optional[float]]] = []
    for index, result in enumerate(pose_results):
        if not include_failed and result.status not in MULTIPOSE_SUCCESS_STATUSES:
            continue
        candidates.append((index, result, _multipose_pose_numeric_score(result)))
    candidates.sort(
        key=lambda item: (
            item[2] is not None,
            item[2] if item[2] is not None else float("-inf"),
            -item[0],
        ),
        reverse=True,
    )
    ranking: List[Dict[str, Any]] = []
    for rank, (index, result, score) in enumerate(candidates, start=1):
        ranking.append(
            {
                "rank": rank,
                "pose_index": index,
                "pose_id": result.pose_id,
                "name": result.name,
                "status": result.status.value,
                "score": score,
                "interaction_count": result.interaction_count,
            }
        )
    return ranking


def _multipose_family_presence(
    result: PoseAnalysisResult,
) -> Dict[str, int]:
    """Return per-family interaction counts for one pose."""

    return {
        family: result.interactions.count(family)
        for family in INTERACTION_FAMILY_ORDER
    }


def build_preliminary_multipose_consensus(
    pose_results: Sequence[PoseAnalysisResult],
) -> Dict[str, Any]:
    """Build a lightweight consensus summary before Section 21 enrichment."""

    successful = [
        result
        for result in pose_results
        if result.status in MULTIPOSE_SUCCESS_STATUSES
    ]
    pose_count = len(successful)
    family_pose_counts: Counter[str] = Counter()
    family_interaction_totals: Counter[str] = Counter()
    for result in successful:
        counts = _multipose_family_presence(result)
        for family, count in counts.items():
            family_interaction_totals[family] += count
            if count > 0:
                family_pose_counts[family] += 1
    families: Dict[str, Any] = {}
    for family in INTERACTION_FAMILY_ORDER:
        present = family_pose_counts.get(family, 0)
        total = family_interaction_totals.get(family, 0)
        families[family] = {
            "pose_count": present,
            "frequency": present / pose_count if pose_count else 0.0,
            "interaction_total": total,
            "mean_interactions_per_pose": total / pose_count if pose_count else 0.0,
        }
    return {
        "schema": MULTIPOSE_SCHEMA_NAME,
        "schema_version": MULTIPOSE_SCHEMA_VERSION,
        "scope": "preliminary_consensus",
        "pose_count": pose_count,
        "families": families,
        "persistent_families": [
            family
            for family, values in families.items()
            if pose_count and values["pose_count"] == pose_count
        ],
        "note": (
            "Detailed residue, hotspot, diversity and complementarity analysis "
            "is added by the dedicated consensus stage."
        ),
    }


def attach_multipose_global_results(
    result: MultiPoseAnalysisResult,
    *,
    ranking: Sequence[Mapping[str, Any]],
    consensus: Any,
    native_scoring: Optional[ScoringMultiposeOutput] = None,
) -> int:
    """Attach aggregate rank and consensus references to each DockModel."""

    rank_by_pose = {
        str(item.get("pose_id")): item
        for item in ranking
        if isinstance(item, Mapping) and item.get("pose_id") is not None
    }
    attached = 0
    consensus_summary = (
        consensus
        if isinstance(consensus, Mapping)
        else {"type": type(consensus).__name__} if consensus is not None else None
    )
    for pose_result in result.pose_results:
        dock_model = pose_result.dock_model
        if dock_model is None:
            continue
        metadata = normalize_metadata_mapping(
            get_object_value(
                dock_model,
                DOCK_MODEL_FIELD_METADATA,
                default={},
            ),
            copy_values=True,
        )
        multipose_metadata = normalize_metadata_mapping(
            metadata.get("multipose_analysis"),
            copy_values=True,
        )
        multipose_metadata.update(
            {
                "run_id": result.run_id,
                "request_id": result.request_id,
                "status": result.status.value,
                "pose_count": result.pose_count,
                "rank": rank_by_pose.get(pose_result.pose_id),
                "consensus": consensus_summary,
                "native_scoring_used": native_scoring is not None,
            }
        )
        metadata["multipose_analysis"] = multipose_metadata
        set_object_value(
            dock_model,
            DOCK_MODEL_FIELD_METADATA,
            metadata,
            strict=False,
        )
        statistics = normalize_statistics_mapping(
            get_object_value(
                dock_model,
                DOCK_MODEL_FIELD_STATISTICS,
                default={},
            ),
            copy_values=True,
        )
        statistics["multipose_rank"] = rank_by_pose.get(pose_result.pose_id)
        statistics["multipose_pose_count"] = result.pose_count
        set_object_value(
            dock_model,
            DOCK_MODEL_FIELD_STATISTICS,
            statistics,
            strict=False,
        )
        attached += 1
    return attached


def run_multipose_scoring_aggregation(
    pose_results: Sequence[PoseAnalysisResult],
    *,
    context: AnalysisContext,
    options: MultiposeExecutionOptions,
) -> Optional[ScoringMultiposeOutput]:
    """Run native multipose scoring, ranking and consensus when available."""

    if not options.run_native_multipose_scoring:
        return None
    dock_models = [
        result.dock_model
        for result in pose_results
        if result.dock_model is not None
        and result.status in MULTIPOSE_SUCCESS_STATUSES
    ]
    if not dock_models or not context.config.enable_scoring:
        return None
    try:
        return run_multiple_dock_models_scoring(
            dock_models,
            context=context,
            config=context.config,
            build_ranking=options.build_ranking,
            build_consensus=options.build_consensus,
            ranking_options=(
                dict(options.ranking_options) or None
            ),
            consensus_options=(
                dict(options.consensus_options) or None
            ),
        )
    except Exception as exc:
        if context.config.runtime.failure_policy == FAILURE_POLICY_STRICT:
            raise
        context.metadata.setdefault(MULTIPOSE_METADATA_KEY, {})[
            "native_scoring_error"
        ] = str(exc)
        return None


# 19.8. Global consensus, validation and finalization stages
# -----------------------------------------------------------------------------


def _execute_preliminary_multipose_consensus_stage(
    context: AnalysisContext,
    result: MultiPoseAnalysisResult,
    *,
    options: MultiposeExecutionOptions,
    native_scoring: Optional[ScoringMultiposeOutput] = None,
) -> AnalysisStageResult:
    """Create multipose ranking and consensus outputs."""

    stage_result = AnalysisStageResult(
        stage=STAGE_CONSENSUS,
        required=False,
    )
    if not context.config.enable_consensus and not options.build_consensus:
        return stage_result.skip("Multipose consensus is disabled.")
    stage_result.start()
    try:
        ranking = build_multipose_ranking(
            result.pose_results,
            include_failed=options.include_failed_in_ranking,
        ) if options.build_ranking else []
        consensus = (
            native_scoring.consensus_result
            if native_scoring is not None
            and native_scoring.consensus_result is not None
            else build_preliminary_multipose_consensus(result.pose_results)
        )
        result.ranking = ranking
        result.consensus = consensus
        if native_scoring is not None:
            result.metadata[MULTIPOSE_SCORING_OUTPUT_KEY] = {
                "pose_count": native_scoring.pose_count,
                "successful_count": native_scoring.successful_count,
                "ranking_generated": native_scoring.ranking_result is not None,
                "consensus_generated": native_scoring.consensus_result is not None,
            }
        attached_count = 0
        if options.attach_global_results:
            attached_count = attach_multipose_global_results(
                result,
                ranking=ranking,
                consensus=consensus,
                native_scoring=native_scoring,
            )
        stage_result.statistics = {
            "pose_count": result.pose_count,
            "ranked_pose_count": len(ranking),
            "successful_pose_count": len(result.successful_pose_results),
            "failed_pose_count": len(result.failed_pose_results),
            "attached_dock_model_count": attached_count,
        }
        stage_result.output_summary = {
            "ranking_generated": bool(ranking),
            "consensus_generated": consensus is not None,
            "native_scoring_used": native_scoring is not None,
            "attached_dock_model_count": attached_count,
        }
        stage_result.succeed(
            {
                "ranking": ranking,
                "consensus": consensus,
                "native_scoring": native_scoring,
            },
            message="Multipose ranking and consensus completed successfully.",
        )
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisIntegrationError(
                "Multipose ranking and consensus failed.",
                stage=STAGE_CONSENSUS,
                cause=exc,
            )
        stage_result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
    return stage_result


# execute_multipose_validation_stage is implemented by the Section 27 validation layer.


def execute_multipose_finalization_stage(
    context: AnalysisContext,
    result: MultiPoseAnalysisResult,
    run_result: AnalysisRunResult,
) -> AnalysisStageResult:
    """Finalize aggregate state and top-level run containers."""

    stage_result = AnalysisStageResult(stage=STAGE_FINALIZATION, required=True)
    stage_result.start()
    try:
        result.finalize(
            AnalysisStatus.CANCELLED if context.is_cancelled() else None
        )
        stage_result.statistics = {
            "pose_count": result.pose_count,
            "successful_pose_count": len(result.successful_pose_results),
            "failed_pose_count": len(result.failed_pose_results),
            "total_interactions": sum(
                item.interaction_count for item in result.pose_results
            ),
        }
        stage_result.succeed(
            dict(stage_result.statistics),
            message="Multipose analysis finalized successfully.",
        )
        result.add_stage_result(stage_result)
        result.finalize()
        run_result.set_payload(result)
        run_result.multipose_result = result
        run_result.statistics.update(result.statistics)
        run_result.files.update(result.files)
        run_result.provenance.update(result.provenance)
        run_result.add_stage_result(stage_result)
        run_result.finalize(result.status)
        context.set_status(result.status, force=True)
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisIntegrationError(
                "Multipose finalization failed.",
                stage=STAGE_FINALIZATION,
                cause=exc,
            )
        stage_result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
        result.add_stage_result(stage_result)
        result.finalize(AnalysisStatus.FAILED)
        run_result.set_payload(result)
        run_result.multipose_result = result
        run_result.add_stage_result(stage_result)
        run_result.finalize(AnalysisStatus.FAILED)
        context.set_status(AnalysisStatus.FAILED, force=True)
    context.set_stage_data(STAGE_FINALIZATION, stage_result)
    context.notify_stage(stage_result)
    return stage_result


# 19.9. Complete orchestration runner
# -----------------------------------------------------------------------------


def run_multipose_analysis(
    value: Any = None,
    *,
    receptor: Any = None,
    poses: Any = None,
    dock_models: Any = None,
    session: Any = None,
    config: AnalysisConfigLike = None,
    options: MultiposeExecutionOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    context: Optional[AnalysisContext] = None,
    requested_stages: Any = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
) -> MultiposeAnalysisOutput:
    """Run the complete integrated pipeline for multiple poses."""

    resolved_options = coerce_multipose_execution_options(options)
    integrated = _multipose_config_with_mode(config, ANALYSIS_MODE_MULTIPOSE)
    request = build_multipose_request(
        value,
        receptor=receptor,
        poses=poses,
        dock_models=dock_models,
        session=session,
        config=integrated,
        requested_stages=requested_stages,
        name=name,
        metadata=metadata,
    )
    runtime_context = create_multipose_context(
        request,
        context=context,
        progress_callback=progress_callback,
        stage_callback=stage_callback,
        cancellation_callback=cancellation_callback,
    )
    target_registry = registry or get_default_stage_registry()
    plan = build_multipose_execution_plan(
        integrated,
        request=request,
        options=resolved_options,
        registry=target_registry,
        capabilities=capabilities,
    )
    runtime_context.set_shared(MULTIPOSE_PLAN_KEY, plan)
    runtime_context.metadata[MULTIPOSE_METADATA_KEY] = {
        "schema": MULTIPOSE_SCHEMA_NAME,
        "schema_version": MULTIPOSE_SCHEMA_VERSION,
        "plan_id": plan.plan_id,
        "options_fingerprint": resolved_options.fingerprint,
    }
    runtime_context.start()

    run_result = AnalysisRunResult(
        run_id=runtime_context.run_id,
        request_id=request.request_id,
        name=request.name,
        mode=ANALYSIS_MODE_MULTIPOSE,
        status=AnalysisStatus.RUNNING,
        request=request,
        context=runtime_context if resolved_options.preserve_context else None,
        started_at=_utc_timestamp(),
        metadata={
            "schema": MULTIPOSE_SCHEMA_NAME,
            "schema_version": MULTIPOSE_SCHEMA_VERSION,
            "plan_id": plan.plan_id,
        },
    )
    warnings_list: List[str] = list(plan.warnings)
    errors: List[str] = []
    resolved_input: Optional[ResolvedAnalysisInput] = None
    preparation: Optional[ModelPreparationResult] = None
    pose_outputs: List[SinglePoseAnalysisOutput] = []
    pose_results: List[PoseAnalysisResult] = []
    pose_trace: List[MultiposePoseTrace] = []
    native_scoring: Optional[ScoringMultiposeOutput] = None
    first_failure: Optional[BaseException] = None

    input_stage, resolved_input = execute_multipose_input_resolution(
        runtime_context,
        validate_input=resolved_options.validate_input,
    )
    run_result.add_stage_result(input_stage)
    warnings_list.extend(issue.message for issue in input_stage.warnings)
    errors.extend(issue.message for issue in input_stage.errors)

    if input_stage.succeeded and resolved_input is not None:
        preparation_stage, preparation = execute_multipose_model_preparation(
            runtime_context,
            resolved_input,
            validate_result=resolved_options.validate_result,
        )
    else:
        preparation_stage = AnalysisStageResult(
            stage=STAGE_MODEL_PREPARATION,
            required=True,
        )
        preparation_stage.block("Input resolution did not succeed.")
        runtime_context.set_stage_data(STAGE_MODEL_PREPARATION, preparation_stage)
        runtime_context.notify_stage(preparation_stage)
    run_result.add_stage_result(preparation_stage)
    warnings_list.extend(issue.message for issue in preparation_stage.warnings)
    errors.extend(issue.message for issue in preparation_stage.errors)

    if preparation_stage.succeeded and preparation is not None:
        pose_outputs, pose_results, pose_trace = run_multipose_pose_pipelines(
            runtime_context,
            preparation,
            plan=plan,
            options=resolved_options,
            registry=target_registry,
            capabilities=capabilities,
        )
    elif preparation_stage.errors:
        issue = preparation_stage.errors[0]
        first_failure = AnalysisIntegrationError(
            issue.message,
            stage=STAGE_MODEL_PREPARATION,
            details=issue.details,
        )

    multipose_result = MultiPoseAnalysisResult(
        run_id=runtime_context.run_id,
        request_id=request.request_id,
        name=request.name,
        status=AnalysisStatus.RUNNING,
        pose_results=pose_results,
        started_at=runtime_context.started_at,
        metadata={
            "schema": MULTIPOSE_SCHEMA_NAME,
            "schema_version": MULTIPOSE_SCHEMA_VERSION,
            "plan_id": plan.plan_id,
            "configuration_fingerprint": integrated.fingerprint,
            "options_fingerprint": resolved_options.fingerprint,
        },
    )
    multipose_result.add_stage_result(input_stage)
    multipose_result.add_stage_result(preparation_stage)
    for pose_result in pose_results:
        multipose_result.diagnostics.extend(pose_result.diagnostics)
        multipose_result.files.update(pose_result.files)

    successful_count = len(multipose_result.successful_pose_results)
    if successful_count >= resolved_options.minimum_successful_poses:
        if resolved_options.run_native_multipose_scoring:
            try:
                native_scoring = run_multipose_scoring_aggregation(
                    pose_results,
                    context=runtime_context,
                    options=resolved_options,
                )
            except Exception as exc:
                first_failure = first_failure or exc
                errors.append(str(exc))
        consensus_stage = execute_multipose_consensus_stage(
            runtime_context,
            multipose_result,
            options=resolved_options,
            native_scoring=native_scoring,
        )
    else:
        consensus_stage = AnalysisStageResult(
            stage=STAGE_CONSENSUS,
            required=False,
        )
        consensus_stage.block(
            "Insufficient successful poses are available for consensus."
        )
    multipose_result.add_stage_result(consensus_stage)
    run_result.add_stage_result(consensus_stage)
    runtime_context.set_stage_data(STAGE_CONSENSUS, consensus_stage)
    runtime_context.notify_stage(consensus_stage)
    warnings_list.extend(issue.message for issue in consensus_stage.warnings)
    errors.extend(issue.message for issue in consensus_stage.errors)

    validation_stage = execute_multipose_validation_stage(
        runtime_context,
        multipose_result,
        minimum_successful_poses=resolved_options.minimum_successful_poses,
    )
    multipose_result.add_stage_result(validation_stage)
    run_result.add_stage_result(validation_stage)
    warnings_list.extend(issue.message for issue in validation_stage.warnings)
    errors.extend(issue.message for issue in validation_stage.errors)
    if validation_stage.errors and first_failure is None:
        first_failure = AnalysisValidationError(
            validation_stage.errors[0].message,
            stage=STAGE_VALIDATION,
            details=validation_stage.errors[0].details,
        )

    execute_multipose_finalization_stage(
        runtime_context,
        multipose_result,
        run_result,
    )
    runtime_context.set_current_pose(None)
    runtime_context.set_current_stage(None)

    output = MultiposeAnalysisOutput(
        request=request,
        context=runtime_context,
        plan=plan,
        multipose_result=multipose_result,
        run_result=run_result,
        resolved_input=resolved_input,
        preparation=preparation,
        pose_outputs=pose_outputs,
        pose_trace=pose_trace,
        native_scoring_output=native_scoring,
        warnings=warnings_list,
        errors=errors,
        metadata={
            "schema": MULTIPOSE_SCHEMA_NAME,
            "schema_version": MULTIPOSE_SCHEMA_VERSION,
            "plan_id": plan.plan_id,
            "configuration_fingerprint": integrated.fingerprint,
            "options_fingerprint": resolved_options.fingerprint,
            "deferred_output_stages": [
                stage
                for stage in plan.stages
                if stage in MULTIPOSE_DEFERRED_OUTPUT_STAGES
            ],
        },
        options=resolved_options,
    )
    runtime_context.set_shared(MULTIPOSE_OUTPUT_KEY, output)
    runtime_context.set_shared(MULTIPOSE_RESULT_KEY, multipose_result)
    runtime_context.set_shared(MULTIPOSE_RUN_RESULT_KEY, run_result)
    runtime_context.set_shared(MULTIPOSE_POSE_OUTPUTS_KEY, tuple(pose_outputs))
    runtime_context.set_shared(MULTIPOSE_POSE_TRACE_KEY, tuple(pose_trace))
    if native_scoring is not None:
        runtime_context.set_shared(MULTIPOSE_SCORING_OUTPUT_KEY, native_scoring)
    runtime_context.statistics[MULTIPOSE_STATISTICS_KEY] = output.summary()

    if resolved_options.validate_result:
        validation_errors = validate_multipose_analysis_output(
            output,
            raise_on_error=False,
        )
        if validation_errors:
            errors.extend(validation_errors)
            output.errors = unique_preserving_order(errors)
    if resolved_options.raise_on_error and output.status in {
        AnalysisStatus.FAILED,
        AnalysisStatus.CANCELLED,
    }:
        if first_failure is not None:
            raise first_failure
        raise AnalysisPartialFailureError(
            "Multipose analysis did not complete successfully.",
            details=output.summary(),
        )
    return output


# 19.10. Convenience wrappers
# -----------------------------------------------------------------------------


def analyze_multiple_poses(
    value: Any = None,
    **kwargs: Any,
) -> MultiPoseAnalysisResult:
    """Run multipose analysis and return the integrated aggregate result."""

    return run_multipose_analysis(value, **kwargs).multipose_result


def analyze_multiple_dock_models(
    dock_models: Iterable[Any],
    **kwargs: Any,
) -> MultiPoseAnalysisResult:
    """Analyze existing DockModel objects as one multipose set."""

    return run_multipose_analysis(
        dock_models=tuple(dock_models),
        **kwargs,
    ).multipose_result


def execute_multipose_pipeline(
    value: Any = None,
    **kwargs: Any,
) -> MultiposeAnalysisOutput:
    """Alias for :func:`run_multipose_analysis`."""

    return run_multipose_analysis(value, **kwargs)


# 19.11. Validation, summaries and conversion
# -----------------------------------------------------------------------------


def validate_multipose_analysis_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one complete multipose orchestration output."""

    errors: List[str] = []
    if not isinstance(value, MultiposeAnalysisOutput):
        errors.append("Value is not a MultiposeAnalysisOutput instance.")
    else:
        if value.context.mode != ANALYSIS_MODE_MULTIPOSE:
            errors.append("Multipose output context has an invalid mode.")
        if value.plan.analysis_mode != ANALYSIS_MODE_MULTIPOSE:
            errors.append("Multipose execution plan has an invalid mode.")
        if value.run_result.multipose_result is not value.multipose_result:
            errors.append(
                "Multipose and run results do not reference the same payload."
            )
        if value.run_result.payload is not value.multipose_result:
            errors.append("Run-result payload is not the multipose result.")
        if len(value.pose_trace) != len(value.multipose_result.pose_results):
            errors.append("Multipose pose trace does not match the pose results.")
        if value.preparation is not None:
            if len(value.multipose_result.pose_results) > value.preparation.prepared_count:
                errors.append("Multipose result count exceeds prepared models.")
        identifiers = [item.pose_id for item in value.multipose_result.pose_results]
        if len(identifiers) != len(set(identifiers)):
            errors.append("Multipose output contains duplicate pose identifiers.")
        errors.extend(
            validate_core_result(value.multipose_result, raise_on_error=False)
        )
        errors.extend(validate_core_result(value.run_result, raise_on_error=False))
        if value.options.fingerprint != value.metadata.get("options_fingerprint"):
            errors.append("Multipose options fingerprint is inconsistent.")
        if value.status == AnalysisStatus.SUCCEEDED and value.failed_pose_results:
            errors.append("Successful multipose output contains failed poses.")
        if (
            len(value.successful_pose_results)
            < value.options.minimum_successful_poses
            and value.status in MULTIPOSE_SUCCESS_STATUSES
        ):
            errors.append(
                "Accepted multipose output does not meet the minimum success count."
            )
    result = tuple(unique_preserving_order(errors))
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Multipose output validation failed: " + " ".join(result),
            stage=STAGE_VALIDATION,
            details={"errors": list(result)},
        )
    return result


def summarize_multipose_analysis(value: Any) -> Dict[str, Any]:
    """Return a concise summary of a multipose output or result."""

    if isinstance(value, MultiposeAnalysisOutput):
        return value.summary()
    result = coerce_multipose_analysis_result(value)
    best = result.best_pose
    return {
        "schema": MULTIPOSE_SCHEMA_NAME,
        "schema_version": MULTIPOSE_SCHEMA_VERSION,
        "run_id": result.run_id,
        "name": result.name,
        "status": result.status.value,
        "pose_count": result.pose_count,
        "successful_pose_count": len(result.successful_pose_results),
        "failed_pose_count": len(result.failed_pose_results),
        "best_pose_id": best.pose_id if best is not None else None,
        "ranking_generated": bool(result.ranking),
        "consensus_generated": result.consensus is not None,
        "duration_seconds": result.duration_seconds,
    }


def multipose_analysis_to_json(
    value: MultiposeAnalysisOutput,
    *,
    include_objects: bool = False,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
    sort_keys: bool = True,
) -> str:
    """Serialize a multipose output to JSON."""

    if not isinstance(value, MultiposeAnalysisOutput):
        raise TypeError("value must be a MultiposeAnalysisOutput instance.")
    return json.dumps(
        value.to_dict(include_objects=include_objects),
        indent=indent,
        sort_keys=sort_keys,
        default=str,
    )


# 19.12. Internal convention validation
# -----------------------------------------------------------------------------


def validate_multipose_orchestration_conventions() -> Dict[str, Any]:
    """Validate the multipose orchestration layer with synthetic executors."""

    failures: List[str] = []

    class _SyntheticAtoms(list):
        @property
        def residues(self) -> List[Any]:
            return [getattr(atom, "residue", None) for atom in self]

    receptor_residue = SimpleNamespace(name="REC", chain_id="A", number=1)
    receptor_atom = SimpleNamespace(
        name="C1",
        element=SimpleNamespace(name="C"),
        coord=(0.0, 0.0, 0.0),
        residue=receptor_residue,
    )
    receptor_model = SimpleNamespace(
        name="section19_receptor",
        id_string="1",
        atoms=_SyntheticAtoms([receptor_atom]),
        residues=[receptor_residue],
    )
    dock_models: List[DockModel] = []
    for index, distance in enumerate((3.5, 4.0), start=1):
        ligand_residue = SimpleNamespace(
            name="LIG",
            chain_id="L",
            number=index,
        )
        ligand_atom = SimpleNamespace(
            name=f"C{index + 1}",
            element=SimpleNamespace(name="C"),
            coord=(distance, 0.0, 0.0),
            residue=ligand_residue,
        )
        pose_model = SimpleNamespace(
            name=f"section19_pose_{index}",
            id_string=str(index + 1),
            atoms=_SyntheticAtoms([ligand_atom]),
            residues=[ligand_residue],
        )
        dock_models.append(
            DockModel(
                name=f"section19_pose_{index}",
                receptor=receptor_model,
                pose=pose_model,
                ligand=pose_model,
            )
        )

    def _synthetic_contacts_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        index = context.current_pose_index if context is not None else 0
        interaction = SimpleNamespace(
            interaction_id=f"section19_contact_{index}",
            distance=3.5 + float(index or 0),
            score=1.0,
        )
        stage_result = AnalysisStageResult(stage=STAGE_CONTACTS, required=True)
        stage_result.start().succeed(
            SimpleNamespace(contacts=(interaction,), statistics={"total": 1})
        )
        return stage_result

    def _synthetic_consolidation_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        index = context.current_pose_index if context is not None else 0
        interaction = SimpleNamespace(
            interaction_id=f"section19_contact_{index}",
            distance=3.5 + float(index or 0),
            score=1.0,
        )
        bundle = InteractionAnalysisBundle(contacts=[interaction])
        stage_result = AnalysisStageResult(
            stage=STAGE_CONSOLIDATION,
            required=True,
        )
        stage_result.start().succeed(bundle)
        return stage_result

    def _synthetic_scoring_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        dock_model = context.current_dock_model if context is not None else None
        name = get_preparation_model_name(dock_model, default="pose")
        score = 2.0 if name.endswith("_2") else 1.0
        scoring = SimpleNamespace(final_score=score, interaction_count=1)
        stage_result = AnalysisStageResult(stage=STAGE_SCORING, required=True)
        stage_result.start().succeed(scoring)
        return stage_result

    registry = get_default_stage_registry(copy_registry=True)
    for stage, executor in (
        (STAGE_CONTACTS, _synthetic_contacts_executor),
        (STAGE_CONSOLIDATION, _synthetic_consolidation_executor),
        (STAGE_SCORING, _synthetic_scoring_executor),
    ):
        definition = registry.require(stage)
        registry.replace(
            replace(
                definition,
                executor=executor,
                result_adapter=None,
                validator=None,
                required_modules=(),
            )
        )

    requested = (
        STAGE_INPUT_RESOLUTION,
        STAGE_MODEL_PREPARATION,
        STAGE_CONTACTS,
        STAGE_CONSOLIDATION,
        STAGE_SCORING,
        STAGE_CONSENSUS,
        STAGE_VALIDATION,
        STAGE_FINALIZATION,
    )
    integrated = AnalysisConfig(
        runtime=AnalysisRuntimeConfig(analysis_mode=ANALYSIS_MODE_MULTIPOSE),
        requested_stages=requested,
        include_stage_dependencies=True,
        include_internal_stages=True,
        enable_consensus=True,
    )
    options = MultiposeExecutionOptions(
        requested_stages=requested,
        include_dependencies=True,
        include_ordering_predecessors=False,
        inspect_capabilities=False,
        require_registered_executors=False,
        run_native_multipose_scoring=False,
        build_ranking=True,
        build_consensus=True,
        validate_input=True,
        validate_result=True,
    )
    output = run_multipose_analysis(
        dock_models=dock_models,
        config=integrated,
        options=options,
        registry=registry,
    )
    if output.status != AnalysisStatus.SUCCEEDED:
        failures.append(
            f"Synthetic multipose analysis ended as {output.status.value!r}."
        )
    if len(output.pose_results) != 2:
        failures.append("Synthetic multipose analysis did not retain two poses.")
    if any(item.interaction_count != 1 for item in output.pose_results):
        failures.append("Synthetic multipose interaction counts are invalid.")
    if len(output.multipose_result.ranking) != 2:
        failures.append("Synthetic multipose ranking is incomplete.")
    elif output.multipose_result.ranking[0]["name"] != "section19_pose_2":
        failures.append("Synthetic multipose ranking order is invalid.")
    if output.multipose_result.consensus is None:
        failures.append("Synthetic multipose consensus was not retained.")
    if len(output.pose_trace) != 2:
        failures.append("Synthetic multipose trace is incomplete.")
    validation_errors = validate_multipose_analysis_output(
        output,
        raise_on_error=False,
    )
    if validation_errors:
        failures.extend(validation_errors)
    json_payload = multipose_analysis_to_json(output)
    if MULTIPOSE_SCHEMA_NAME not in json_payload:
        failures.append("Multipose JSON serialization omitted the schema name.")
    if len(options.fingerprint) != 64:
        failures.append("Multipose options fingerprint is invalid.")
    if output.context.get_shared(MULTIPOSE_OUTPUT_KEY) is not output:
        failures.append("Multipose output was not retained in the context.")

    if failures:
        raise RuntimeError(
            "Multipose orchestration convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": MULTIPOSE_SCHEMA_NAME,
        "schema_version": MULTIPOSE_SCHEMA_VERSION,
        "pose_count": len(output.pose_results),
        "ranking_count": len(output.multipose_result.ranking),
        "validated_cases": 28,
    }


