class BatchItemDisposition(str, Enum):
    """Execution disposition assigned to one independent batch item."""

    PENDING = "pending"
    RUNNING = "running"
    SUCCEEDED = "succeeded"
    PARTIAL = "partial"
    FAILED = "failed"
    CANCELLED = "cancelled"
    SKIPPED = "skipped"


BATCH_TERMINAL_DISPOSITIONS: Final[FrozenSet[BatchItemDisposition]] = frozenset(
    {
        BatchItemDisposition.SUCCEEDED,
        BatchItemDisposition.PARTIAL,
        BatchItemDisposition.FAILED,
        BatchItemDisposition.CANCELLED,
        BatchItemDisposition.SKIPPED,
    }
)


# 20.2. Batch cancellation token
# -----------------------------------------------------------------------------


@dataclass
class BatchCancellationToken:
    """Thread-safe cooperative cancellation token shared by batch workers."""

    reason: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    requested_at: Optional[str] = None
    _event: threading.Event = field(
        default_factory=threading.Event,
        repr=False,
        compare=False,
    )
    _lock: threading.RLock = field(
        default_factory=threading.RLock,
        repr=False,
        compare=False,
    )

    @property
    def cancelled(self) -> bool:
        """Return whether cancellation has been requested."""

        return self._event.is_set()

    def cancel(
        self,
        reason: Any = "Batch execution was cancelled.",
        *,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> bool:
        """Request cancellation and return whether this was the first request."""

        with self._lock:
            first_request = not self._event.is_set()
            if first_request:
                normalized_reason = str(reason).strip()
                self.reason = normalized_reason or "Batch execution was cancelled."
                self.requested_at = _utc_timestamp()
                if metadata:
                    self.metadata.update(dict(metadata))
                self._event.set()
            elif metadata:
                self.metadata.update(dict(metadata))
            return first_request

    def reset(self) -> None:
        """Clear cancellation state for explicit token reuse."""

        with self._lock:
            self.reason = None
            self.requested_at = None
            self.metadata.clear()
            self._event.clear()

    def raise_if_cancelled(self) -> None:
        """Raise a structured cancellation error when cancellation is active."""

        if self.cancelled:
            raise AnalysisCancelledError(
                self.reason or "Batch execution was cancelled.",
                details={
                    "requested_at": self.requested_at,
                    "metadata": dict(self.metadata),
                },
            )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready cancellation representation."""

        return {
            "cancelled": self.cancelled,
            "reason": self.reason,
            "requested_at": self.requested_at,
            "metadata": to_json_compatible(self.metadata),
        }


# 20.3. Batch execution options
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class BatchExecutionOptions:
    """Control independent-request batch execution and failure isolation."""

    execution_mode: str = DEFAULT_BATCH_EXECUTION_MODE
    max_workers: int = DEFAULT_BATCH_MAX_WORKERS
    continue_on_item_error: bool = DEFAULT_BATCH_CONTINUE_ON_ITEM_ERROR
    stop_on_first_failure: bool = DEFAULT_BATCH_STOP_ON_FIRST_FAILURE
    cancel_pending_on_failure: bool = DEFAULT_BATCH_CANCEL_PENDING_ON_FAILURE
    raise_on_error: bool = DEFAULT_BATCH_RAISE_ON_ERROR
    validate_requests: bool = DEFAULT_BATCH_VALIDATE_REQUESTS
    validate_results: bool = DEFAULT_BATCH_VALIDATE_RESULTS
    preserve_item_outputs: bool = DEFAULT_BATCH_PRESERVE_ITEM_OUTPUTS
    preserve_context: bool = DEFAULT_BATCH_PRESERVE_CONTEXT
    allow_nested_batches: bool = DEFAULT_BATCH_ALLOW_NESTED_BATCHES
    allow_chimerax_threads: bool = DEFAULT_BATCH_ALLOW_CHIMERAX_THREADS
    emit_child_progress: bool = DEFAULT_BATCH_EMIT_CHILD_PROGRESS
    emit_child_stages: bool = DEFAULT_BATCH_EMIT_CHILD_STAGES
    progress_interval: int = DEFAULT_BATCH_PROGRESS_INTERVAL
    item_limit: int = MAX_BATCH_ITEMS
    single_pose_options: Any = None
    multipose_options: Any = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        try:
            mode = canonicalize_execution_mode(self.execution_mode)
        except (TypeError, ValueError) as exc:
            raise AnalysisConfigurationError(str(exc)) from exc
        object.__setattr__(self, "execution_mode", mode)
        object.__setattr__(
            self,
            "max_workers",
            _coerce_config_int(
                self.max_workers,
                field_name="batch.max_workers",
                minimum=1,
                maximum=1024,
            ),
        )
        for field_name in (
            "continue_on_item_error",
            "stop_on_first_failure",
            "cancel_pending_on_failure",
            "raise_on_error",
            "validate_requests",
            "validate_results",
            "preserve_item_outputs",
            "preserve_context",
            "allow_nested_batches",
            "allow_chimerax_threads",
            "emit_child_progress",
            "emit_child_stages",
        ):
            object.__setattr__(
                self,
                field_name,
                _coerce_config_bool(
                    getattr(self, field_name),
                    field_name=f"batch.{field_name}",
                ),
            )
        object.__setattr__(
            self,
            "progress_interval",
            _coerce_config_int(
                self.progress_interval,
                field_name="batch.progress_interval",
                minimum=1,
                maximum=1_000_000,
            ),
        )
        object.__setattr__(
            self,
            "item_limit",
            _coerce_config_int(
                self.item_limit,
                field_name="batch.item_limit",
                minimum=1,
                maximum=MAX_BATCH_ITEMS,
            ),
        )
        if not isinstance(self.metadata, Mapping):
            raise AnalysisConfigurationError("batch.metadata must be a mapping.")
        object.__setattr__(self, "metadata", _freeze_config_value(self.metadata))
        if self.execution_mode == EXECUTION_MODE_SEQUENTIAL:
            object.__setattr__(self, "max_workers", 1)
        if self.stop_on_first_failure:
            object.__setattr__(self, "continue_on_item_error", False)

    @property
    def fingerprint(self) -> str:
        """Return a deterministic SHA-256 fingerprint."""

        payload = json.dumps(
            self.to_dict(include_child_options=True),
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode(ANALYSIS_ENCODING)
        return sha256(payload).hexdigest()

    def effective_execution_mode(
        self,
        *,
        runtime: Optional[AnalysisRuntimeConfig] = None,
        in_chimerax: bool = False,
    ) -> str:
        """Return the safe execution mode for the selected environment."""

        mode = self.execution_mode
        if mode == EXECUTION_MODE_AUTOMATIC:
            if runtime is not None:
                mode = runtime.effective_execution_mode(in_chimerax=in_chimerax)
            else:
                mode = (
                    EXECUTION_MODE_SEQUENTIAL
                    if in_chimerax
                    else EXECUTION_MODE_THREADED
                )
        if in_chimerax and mode == EXECUTION_MODE_THREADED:
            runtime_allows = bool(
                runtime is not None and runtime.allow_chimerax_threads
            )
            if not self.allow_chimerax_threads and not runtime_allows:
                return EXECUTION_MODE_SEQUENTIAL
        if self.max_workers <= 1:
            return EXECUTION_MODE_SEQUENTIAL
        return mode

    def to_dict(self, *, include_child_options: bool = True) -> Dict[str, Any]:
        """Return a serialization-ready options mapping."""

        result = {
            "execution_mode": self.execution_mode,
            "max_workers": self.max_workers,
            "continue_on_item_error": self.continue_on_item_error,
            "stop_on_first_failure": self.stop_on_first_failure,
            "cancel_pending_on_failure": self.cancel_pending_on_failure,
            "raise_on_error": self.raise_on_error,
            "validate_requests": self.validate_requests,
            "validate_results": self.validate_results,
            "preserve_item_outputs": self.preserve_item_outputs,
            "preserve_context": self.preserve_context,
            "allow_nested_batches": self.allow_nested_batches,
            "allow_chimerax_threads": self.allow_chimerax_threads,
            "emit_child_progress": self.emit_child_progress,
            "emit_child_stages": self.emit_child_stages,
            "progress_interval": self.progress_interval,
            "item_limit": self.item_limit,
            "metadata": to_json_compatible(self.metadata),
        }
        if include_child_options:
            result["single_pose_options"] = _batch_option_value_to_data(
                self.single_pose_options
            )
            result["multipose_options"] = _batch_option_value_to_data(
                self.multipose_options
            )
        return result


BatchExecutionOptionsLike: TypeAlias = Union[
    BatchExecutionOptions,
    Mapping[str, Any],
    None,
]


def _batch_option_value_to_data(value: Any) -> Any:
    """Return a safe representation of nested orchestration options."""

    if value is None:
        return None
    if hasattr(value, "to_dict") and callable(value.to_dict):
        try:
            return value.to_dict()
        except TypeError:
            pass
    if is_dataclass(value):
        return to_json_compatible(asdict(value))
    return to_json_compatible(value)


def coerce_batch_execution_options(
    value: BatchExecutionOptionsLike = None,
    **overrides: Any,
) -> BatchExecutionOptions:
    """Coerce batch execution options from an object or mapping."""

    if value is None:
        return BatchExecutionOptions(**overrides)
    if isinstance(value, BatchExecutionOptions):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping):
        data = dict(value)
        data.update(overrides)
        known = {item.name for item in fields(BatchExecutionOptions)}
        unknown = sorted(set(data) - known)
        if unknown:
            raise AnalysisConfigurationError(
                "Unknown batch execution option(s): " + ", ".join(unknown)
            )
        return BatchExecutionOptions(**data)
    raise TypeError("Batch execution options must be a mapping or options object.")


# 20.4. Batch trace and progress structures
# -----------------------------------------------------------------------------


@dataclass
class BatchItemTrace:
    """Execution trace for one independent batch item."""

    index: int
    item_id: str
    request_id: str
    name: str
    dispatch_mode: str
    disposition: Union[BatchItemDisposition, str] = BatchItemDisposition.PENDING
    worker_name: Optional[str] = None
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    result_type: Optional[str] = None
    status: Optional[str] = None
    message: Optional[str] = None
    error_type: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.index = int(self.index)
        if self.index < 0:
            raise ValueError("Batch trace index cannot be negative.")
        self.item_id = _normalize_result_identifier(self.item_id, fallback="item")
        self.request_id = _normalize_result_identifier(
            self.request_id,
            fallback="request",
        )
        self.name = _normalize_result_name(self.name, fallback="batch_item")
        self.dispatch_mode = canonicalize_analysis_mode(self.dispatch_mode)
        if self.dispatch_mode == ANALYSIS_MODE_BATCH:
            raise AnalysisBatchError("A batch trace cannot dispatch another batch.")
        if not isinstance(self.disposition, BatchItemDisposition):
            self.disposition = BatchItemDisposition(
                str(self.disposition).strip().lower()
            )
        self.started_at = _normalize_timestamp(self.started_at, allow_none=True)
        self.finished_at = _normalize_timestamp(self.finished_at, allow_none=True)
        self.duration_seconds = _normalize_duration(self.duration_seconds)
        self.metadata = _result_mapping(self.metadata)

    @property
    def terminal(self) -> bool:
        """Return whether the trace has a terminal disposition."""

        return self.disposition in BATCH_TERMINAL_DISPOSITIONS

    def start(self) -> "BatchItemTrace":
        """Mark the trace as running."""

        self.disposition = BatchItemDisposition.RUNNING
        self.started_at = self.started_at or _utc_timestamp()
        self.worker_name = self.worker_name or threading.current_thread().name
        return self

    def finish(
        self,
        result: Any,
        *,
        status: Optional[Any] = None,
        message: Optional[str] = None,
    ) -> "BatchItemTrace":
        """Finalize the trace from an item result."""

        resolved_status = canonicalize_analysis_status(
            status if status is not None else getattr(result, "status", "succeeded")
        )
        self.status = resolved_status.value
        self.disposition = _batch_disposition_from_status(resolved_status)
        self.result_type = getattr(result, "result_type", type(result).__name__)
        self.message = message
        self.finished_at = _utc_timestamp()
        self.duration_seconds = _elapsed_timestamp_seconds(
            self.started_at,
            self.finished_at,
        )
        return self

    def fail(self, error: BaseException) -> "BatchItemTrace":
        """Finalize the trace after an execution error."""

        self.status = AnalysisStatus.FAILED.value
        self.disposition = BatchItemDisposition.FAILED
        self.error_type = type(error).__name__
        self.message = str(error)
        self.finished_at = _utc_timestamp()
        self.duration_seconds = _elapsed_timestamp_seconds(
            self.started_at,
            self.finished_at,
        )
        return self

    def cancel(self, reason: Any) -> "BatchItemTrace":
        """Finalize the trace as cancelled."""

        self.status = AnalysisStatus.CANCELLED.value
        self.disposition = BatchItemDisposition.CANCELLED
        self.message = str(reason)
        self.finished_at = _utc_timestamp()
        self.duration_seconds = _elapsed_timestamp_seconds(
            self.started_at,
            self.finished_at,
        )
        return self

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready trace mapping."""

        return {
            "index": self.index,
            "item_id": self.item_id,
            "request_id": self.request_id,
            "name": self.name,
            "dispatch_mode": self.dispatch_mode,
            "disposition": self.disposition.value,
            "worker_name": self.worker_name,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "result_type": self.result_type,
            "status": self.status,
            "message": self.message,
            "error_type": self.error_type,
            "metadata": to_json_compatible(self.metadata),
        }


@dataclass
class BatchProgressSnapshot:
    """Immutable-style snapshot of aggregate batch progress."""

    total_items: int
    completed_items: int = 0
    running_items: int = 0
    pending_items: int = 0
    succeeded_items: int = 0
    partial_items: int = 0
    failed_items: int = 0
    cancelled_items: int = 0
    skipped_items: int = 0
    updated_at: str = field(default_factory=_utc_timestamp)
    current_item_index: Optional[int] = None
    current_item_id: Optional[str] = None
    current_stage: Optional[str] = None
    child_completed: Optional[int] = None
    child_total: Optional[int] = None

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready progress mapping."""

        return {
            item.name: to_json_compatible(getattr(self, item.name))
            for item in fields(self)
        }


class BatchProgressTracker:
    """Thread-safe aggregator for item and child-stage progress updates."""

    def __init__(
        self,
        total_items: int,
        *,
        callback: Optional[ProgressCallback] = None,
        interval: int = DEFAULT_BATCH_PROGRESS_INTERVAL,
    ) -> None:
        self.total_items = max(0, int(total_items))
        self.callback = callback
        self.interval = max(1, int(interval))
        self._lock = threading.RLock()
        self._states: Dict[int, BatchItemDisposition] = {
            index: BatchItemDisposition.PENDING
            for index in range(self.total_items)
        }
        self._last_emitted_completed = -1
        self._callback_errors: List[str] = []
        self._last_snapshot = self.snapshot()

    @property
    def callback_errors(self) -> Tuple[str, ...]:
        """Return callback errors captured without interrupting execution."""

        with self._lock:
            return tuple(self._callback_errors)

    def snapshot(
        self,
        *,
        current_item_index: Optional[int] = None,
        current_item_id: Optional[str] = None,
        current_stage: Optional[str] = None,
        child_completed: Optional[int] = None,
        child_total: Optional[int] = None,
    ) -> BatchProgressSnapshot:
        """Return the current aggregate progress snapshot."""

        with self._lock:
            counts = Counter(self._states.values())
            completed = sum(
                counts[item]
                for item in BATCH_TERMINAL_DISPOSITIONS
            )
            snapshot = BatchProgressSnapshot(
                total_items=self.total_items,
                completed_items=completed,
                running_items=counts[BatchItemDisposition.RUNNING],
                pending_items=counts[BatchItemDisposition.PENDING],
                succeeded_items=counts[BatchItemDisposition.SUCCEEDED],
                partial_items=counts[BatchItemDisposition.PARTIAL],
                failed_items=counts[BatchItemDisposition.FAILED],
                cancelled_items=counts[BatchItemDisposition.CANCELLED],
                skipped_items=counts[BatchItemDisposition.SKIPPED],
                current_item_index=current_item_index,
                current_item_id=current_item_id,
                current_stage=current_stage,
                child_completed=child_completed,
                child_total=child_total,
            )
            self._last_snapshot = snapshot
            return snapshot

    def set_state(
        self,
        index: int,
        disposition: BatchItemDisposition,
        *,
        item_id: Optional[str] = None,
        force_emit: bool = False,
    ) -> BatchProgressSnapshot:
        """Update one item state and emit aggregate progress when appropriate."""

        with self._lock:
            self._states[int(index)] = disposition
            snapshot = self.snapshot(
                current_item_index=index,
                current_item_id=item_id,
            )
        should_emit = force_emit or (
            snapshot.completed_items == self.total_items
            or snapshot.completed_items - self._last_emitted_completed >= self.interval
        )
        if should_emit:
            self.emit(snapshot)
        return snapshot

    def child_callback(
        self,
        index: int,
        item_id: str,
    ) -> ProgressCallback:
        """Return a child pipeline progress callback for one item."""

        def _callback(
            stage: str,
            completed: int,
            total: int,
            metadata: Metadata,
        ) -> None:
            snapshot = self.snapshot(
                current_item_index=index,
                current_item_id=item_id,
                current_stage=stage,
                child_completed=completed,
                child_total=total,
            )
            enriched = snapshot.to_dict()
            enriched["child_metadata"] = to_json_compatible(dict(metadata or {}))
            self._invoke_callback(stage, snapshot.completed_items, self.total_items, enriched)

        return _callback

    def emit(self, snapshot: Optional[BatchProgressSnapshot] = None) -> None:
        """Emit one aggregate batch progress update."""

        current = snapshot or self.snapshot()
        self._last_emitted_completed = current.completed_items
        self._invoke_callback(
            BATCH_PROGRESS_STAGE,
            current.completed_items,
            current.total_items,
            current.to_dict(),
        )

    def _invoke_callback(
        self,
        stage: str,
        completed: int,
        total: int,
        metadata: Mapping[str, Any],
    ) -> None:
        callback = self.callback
        if callback is None:
            return
        try:
            callback(stage, completed, total, dict(metadata))
        except Exception as exc:
            with self._lock:
                self._callback_errors.append(
                    f"{type(exc).__name__}: {exc}"
                )

    def to_dict(self) -> Dict[str, Any]:
        """Return the latest aggregate progress state."""

        result = self.snapshot().to_dict()
        result["callback_errors"] = list(self.callback_errors)
        return result


# 20.5. Batch output structure
# -----------------------------------------------------------------------------


@dataclass
class BatchAnalysisOutput:
    """Complete orchestration output for independent analysis requests."""

    request: AnalysisRequest
    context: AnalysisContext
    batch_result: BatchAnalysisResult
    run_result: AnalysisRunResult
    options: BatchExecutionOptions
    item_outputs: Tuple[Any, ...] = ()
    item_traces: Tuple[BatchItemTrace, ...] = ()
    progress: Optional[BatchProgressSnapshot] = None
    cancellation: Optional[BatchCancellationToken] = None
    warnings: Tuple[str, ...] = ()
    errors: Tuple[str, ...] = ()
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = BATCH_EXECUTION_OUTPUT_TYPE

    @property
    def status(self) -> AnalysisStatus:
        """Return the aggregate batch status."""

        return self.batch_result.status

    @property
    def succeeded(self) -> bool:
        """Return whether the batch has an accepted status."""

        return is_success_analysis_status(self.status)

    @property
    def failed(self) -> bool:
        """Return whether the batch failed or was cancelled."""

        return is_failure_analysis_status(self.status)

    @property
    def item_count(self) -> int:
        """Return the number of batch items."""

        return self.batch_result.item_count

    @property
    def successful_items(self) -> Tuple[BatchAnalysisItem, ...]:
        """Return successful or partial items."""

        return self.batch_result.successful_items

    @property
    def failed_items(self) -> Tuple[BatchAnalysisItem, ...]:
        """Return failed or cancelled items."""

        return self.batch_result.failed_items

    def summary(self) -> Dict[str, Any]:
        """Return a concise execution summary."""

        disposition_counts = Counter(
            trace.disposition.value for trace in self.item_traces
        )
        return {
            "schema": BATCH_EXECUTION_SCHEMA_NAME,
            "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
            "run_id": self.run_result.run_id,
            "batch_id": self.batch_result.batch_id,
            "name": self.batch_result.name,
            "status": self.status.value,
            "item_count": self.item_count,
            "successful_item_count": len(self.successful_items),
            "failed_item_count": len(self.failed_items),
            "disposition_counts": dict(disposition_counts),
            "execution_mode": self.metadata.get("effective_execution_mode"),
            "max_workers": self.metadata.get("effective_max_workers"),
            "cancelled": bool(self.cancellation and self.cancellation.cancelled),
            "duration_seconds": self.batch_result.duration_seconds,
            "warning_count": len(self.warnings),
            "error_count": len(self.errors),
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready batch output mapping."""

        output_values: List[Any] = []
        for value in self.item_outputs:
            if value is None:
                output_values.append(None)
            elif hasattr(value, "to_dict") and callable(value.to_dict):
                try:
                    output_values.append(
                        value.to_dict(include_objects=include_objects)
                    )
                except TypeError:
                    output_values.append(value.to_dict())
            else:
                output_values.append(
                    _result_value_to_data(value, include_objects=include_objects)
                )
        return {
            RESULT_KEY_SCHEMA: BATCH_EXECUTION_SCHEMA_NAME,
            RESULT_KEY_VERSION: BATCH_EXECUTION_SCHEMA_VERSION,
            RESULT_KEY_TYPE: self.result_type,
            RESULT_KEY_STATUS: self.status.value,
            "request": self.request.to_dict(include_objects=include_objects),
            RESULT_KEY_CONTEXT: (
                {
                    "run_id": self.context.run_id,
                    "request_id": self.context.request_id,
                    "mode": self.context.mode,
                    "status": self.context.status.value,
                    "current_stage": self.context.current_stage,
                    "current_pose_index": self.context.current_pose_index,
                    "pose_count": self.context.pose_count,
                    "started_at": self.context.started_at,
                    "cancelled": self.context.is_cancelled(),
                    "config": self.context.config.to_dict(),
                    "statistics": to_json_compatible(self.context.statistics),
                    "files": to_json_compatible(self.context.files),
                    "metadata": to_json_compatible(self.context.metadata),
                }
                if self.options.preserve_context
                else None
            ),
            "batch_result": self.batch_result.to_dict(
                include_objects=include_objects
            ),
            "run_result": {
                "run_id": self.run_result.run_id,
                "request_id": self.run_result.request_id,
                "name": self.run_result.name,
                "mode": self.run_result.mode,
                "status": self.run_result.status.value,
                "result_type": self.run_result.result_type,
                "statistics": to_json_compatible(self.run_result.statistics),
                "files": to_json_compatible(self.run_result.files),
                "metadata": to_json_compatible(self.run_result.metadata),
                "provenance": to_json_compatible(self.run_result.provenance),
                "timings": to_json_compatible(self.run_result.timings),
                "diagnostics": self.run_result.diagnostics.to_dict(),
                "started_at": self.run_result.started_at,
                "finished_at": self.run_result.finished_at,
                "duration_seconds": self.run_result.duration_seconds,
            },
            "item_outputs": output_values,
            "item_traces": [item.to_dict() for item in self.item_traces],
            "progress": self.progress.to_dict() if self.progress else None,
            "cancellation": (
                self.cancellation.to_dict() if self.cancellation else None
            ),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(self.metadata),
            "options": self.options.to_dict(),
            "summary": self.summary(),
        }


# 20.6. Request normalization and dispatch-mode resolution
# -----------------------------------------------------------------------------


def _batch_item_base_config(config: AnalysisConfigLike = None) -> AnalysisConfig:
    """Return the default child configuration derived from batch settings."""

    integrated = coerce_analysis_config(config)
    runtime = replace(integrated.runtime, analysis_mode=ANALYSIS_MODE_AUTO)
    return replace(integrated, runtime=runtime)


def _is_batch_container_mapping(value: Mapping[str, Any]) -> bool:
    """Return whether a mapping represents a batch container."""

    return "requests" in value or "items" in value


def _extract_batch_source(value: Any) -> List[Any]:
    """Extract top-level batch item candidates from a supported container."""

    if value is None:
        return []
    if isinstance(value, BatchAnalysisOutput):
        return [item.request for item in value.batch_result.items]
    if isinstance(value, BatchAnalysisResult):
        return [item.request for item in value.items]
    if isinstance(value, BatchAnalysisItem):
        return [value]
    if isinstance(value, AnalysisRequest):
        if value.mode == ANALYSIS_MODE_BATCH:
            nested = value.input_data
            if nested is None:
                return []
            return _extract_batch_source(nested)
        return [value]
    if isinstance(value, Mapping):
        if "requests" in value:
            return _result_sequence(value.get("requests"))
        if "items" in value:
            return _result_sequence(value.get("items"))
        return [value]
    if isinstance(value, Sequence) and not isinstance(
        value,
        (str, bytes, bytearray),
    ):
        return list(value)
    return [value]


def _coerce_batch_child_request(
    value: Any,
    *,
    default_config: AnalysisConfig,
) -> AnalysisRequest:
    """Coerce one independent batch item into an analysis request."""

    if isinstance(value, BatchAnalysisItem):
        return value.request
    if isinstance(value, AnalysisRequest):
        return value
    if isinstance(value, Mapping):
        if "request" in value and set(value).intersection(
            {"item_id", "status", "result", "diagnostics"}
        ):
            return _coerce_batch_child_request(
                value["request"],
                default_config=default_config,
            )
        data = dict(value)
        data.setdefault("config", default_config)
        return coerce_analysis_request(data)
    return create_analysis_request(value, config=default_config)


def normalize_batch_requests(
    value: Any = None,
    *,
    requests: Any = None,
    config: AnalysisConfigLike = None,
    options: BatchExecutionOptionsLike = None,
) -> Tuple[AnalysisRequest, ...]:
    """Normalize independent batch requests while preserving input order."""

    resolved_options = coerce_batch_execution_options(options)
    source = requests if requests is not None else value
    candidates = _extract_batch_source(source)
    if len(candidates) > resolved_options.item_limit:
        raise AnalysisBatchError(
            f"Batch item limit of {resolved_options.item_limit} was exceeded.",
            details={"item_count": len(candidates)},
        )
    default_config = _batch_item_base_config(config)
    normalized: List[AnalysisRequest] = []
    for candidate in candidates:
        request = _coerce_batch_child_request(
            candidate,
            default_config=default_config,
        )
        if request.mode == ANALYSIS_MODE_BATCH:
            if not resolved_options.allow_nested_batches:
                raise AnalysisBatchError(
                    "Nested batch requests are disabled.",
                    details={"request_id": request.request_id},
                )
            nested = normalize_batch_requests(
                request.input_data,
                config=request.config,
                options=resolved_options,
            )
            normalized.extend(nested)
            continue
        normalized.append(request)
    if len(normalized) > resolved_options.item_limit:
        raise AnalysisBatchError(
            f"Expanded batch exceeds {resolved_options.item_limit} items."
        )
    return tuple(normalized)


def infer_batch_item_mode(request: AnalysisRequestLike) -> str:
    """Infer the single-pose or multipose dispatcher for one request."""

    normalized = coerce_analysis_request(request)
    mode = canonicalize_analysis_mode(normalized.mode)
    if mode == ANALYSIS_MODE_BATCH:
        raise AnalysisBatchError("A batch item cannot dispatch batch mode.")
    if mode == ANALYSIS_MODE_MULTIPOSE:
        return ANALYSIS_MODE_MULTIPOSE
    if mode == ANALYSIS_MODE_SINGLE_POSE:
        return ANALYSIS_MODE_SINGLE_POSE
    if mode == ANALYSIS_MODE_SESSION:
        return ANALYSIS_MODE_MULTIPOSE
    if max(normalized.pose_count, normalized.model_count) > 1:
        return ANALYSIS_MODE_MULTIPOSE
    input_data = normalized.input_data
    if isinstance(input_data, ResolvedAnalysisInput):
        if input_data.mode == ANALYSIS_MODE_MULTIPOSE:
            return ANALYSIS_MODE_MULTIPOSE
    if isinstance(input_data, Mapping):
        pose_values = _result_sequence(input_data.get("poses"))
        model_values = _result_sequence(input_data.get("dock_models"))
        if max(len(pose_values), len(model_values)) > 1:
            return ANALYSIS_MODE_MULTIPOSE
    if normalized.session is not None:
        return ANALYSIS_MODE_MULTIPOSE
    return ANALYSIS_MODE_SINGLE_POSE


def prepare_batch_item_request(
    request: AnalysisRequestLike,
    *,
    index: int,
    mode: Optional[str] = None,
) -> AnalysisRequest:
    """Return a child request with a concrete non-batch analysis mode."""

    normalized = coerce_analysis_request(request)
    selected_mode = mode or infer_batch_item_mode(normalized)
    selected_mode = canonicalize_analysis_mode(selected_mode)
    if selected_mode not in {
        ANALYSIS_MODE_SINGLE_POSE,
        ANALYSIS_MODE_MULTIPOSE,
    }:
        raise AnalysisBatchError(
            f"Unsupported batch child mode {selected_mode!r}."
        )
    runtime = replace(
        normalized.config.runtime,
        analysis_mode=selected_mode,
    )
    child_config = replace(normalized.config, runtime=runtime)
    metadata = dict(normalized.metadata)
    metadata.update(
        {
            "batch_item_index": int(index),
            "batch_dispatch_mode": selected_mode,
        }
    )
    return replace(
        normalized,
        config=child_config,
        mode=selected_mode,
        metadata=metadata,
    )


def build_batch_request(
    requests: Sequence[AnalysisRequest],
    *,
    config: AnalysisConfigLike = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisRequest:
    """Build the parent request representing one independent batch."""

    integrated = coerce_analysis_config(config)
    runtime = replace(integrated.runtime, analysis_mode=ANALYSIS_MODE_BATCH)
    batch_config = replace(integrated, runtime=runtime)
    batch_metadata = dict(metadata or {})
    batch_metadata.update(
        {
            "schema": BATCH_EXECUTION_SCHEMA_NAME,
            "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
            "item_count": len(requests),
            "child_request_ids": [item.request_id for item in requests],
        }
    )
    return AnalysisRequest(
        input_data=tuple(requests),
        config=batch_config,
        name=name or "batch_analysis",
        mode=ANALYSIS_MODE_BATCH,
        metadata=batch_metadata,
    )


# 20.7. Progress, stage and cancellation callback wrappers
# -----------------------------------------------------------------------------


def _batch_external_cancellation_requested(
    token: BatchCancellationToken,
    callback: Optional[CancellationCallback],
) -> bool:
    """Return whether token or external callback requests cancellation."""

    if token.cancelled:
        return True
    if callback is None:
        return False
    try:
        requested = bool(callback())
    except Exception as exc:
        raise AnalysisConcurrencyError(
            "The batch cancellation callback failed.",
            cause=exc,
        ) from exc
    if requested:
        token.cancel("Batch cancellation callback requested cancellation.")
    return requested


def _batch_child_cancellation_callback(
    token: BatchCancellationToken,
    callback: Optional[CancellationCallback],
) -> CancellationCallback:
    """Build the cooperative cancellation callback used by child pipelines."""

    def _callback() -> bool:
        return _batch_external_cancellation_requested(token, callback)

    return _callback


def _batch_child_stage_callback(
    index: int,
    item: BatchAnalysisItem,
    callback: Optional[StageCallback],
    *,
    enabled: bool,
) -> Optional[StageCallback]:
    """Wrap child stage notifications with batch-item metadata."""

    if callback is None or not enabled:
        return None

    def _callback(stage: str, result: AnalysisStageResult) -> None:
        result.metadata.setdefault("batch_item_index", index)
        result.metadata.setdefault("batch_item_id", item.item_id)
        result.metadata.setdefault("batch_request_id", item.request.request_id)
        callback(stage, result)

    return _callback


def _batch_disposition_from_status(status: Any) -> BatchItemDisposition:
    """Map an analysis status to a batch-item disposition."""

    normalized = canonicalize_analysis_status(status)
    mapping = {
        AnalysisStatus.SUCCEEDED: BatchItemDisposition.SUCCEEDED,
        AnalysisStatus.PARTIAL: BatchItemDisposition.PARTIAL,
        AnalysisStatus.FAILED: BatchItemDisposition.FAILED,
        AnalysisStatus.CANCELLED: BatchItemDisposition.CANCELLED,
        AnalysisStatus.SKIPPED: BatchItemDisposition.SKIPPED,
        AnalysisStatus.RUNNING: BatchItemDisposition.RUNNING,
        AnalysisStatus.PREPARING: BatchItemDisposition.RUNNING,
        AnalysisStatus.PENDING: BatchItemDisposition.PENDING,
    }
    return mapping[normalized]


def _elapsed_timestamp_seconds(
    started_at: Optional[str],
    finished_at: Optional[str],
) -> Optional[float]:
    """Return elapsed seconds between normalized ISO timestamps."""

    if not started_at or not finished_at:
        return None
    try:
        start = datetime.fromisoformat(started_at.replace("Z", "+00:00"))
        finish = datetime.fromisoformat(finished_at.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    return max(0.0, (finish - start).total_seconds())


# 20.8. Independent item execution
# -----------------------------------------------------------------------------


def execute_batch_item(
    index: int,
    request: AnalysisRequestLike,
    *,
    options: BatchExecutionOptions,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    progress_tracker: Optional[BatchProgressTracker] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_token: Optional[BatchCancellationToken] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    item_callback: Optional[BatchItemCallback] = None,
    trace_callback: Optional[BatchTraceCallback] = None,
) -> Tuple[BatchAnalysisItem, Any, BatchItemTrace]:
    """Execute one independent request and isolate its result or failure."""

    token = cancellation_token or BatchCancellationToken()
    child_request = prepare_batch_item_request(request, index=index)
    dispatch_mode = child_request.mode
    item = BatchAnalysisItem(
        request=child_request,
        name=child_request.name,
        metadata={
            "batch_item_index": index,
            "dispatch_mode": dispatch_mode,
        },
    )
    trace = BatchItemTrace(
        index=index,
        item_id=item.item_id,
        request_id=child_request.request_id,
        name=item.name,
        dispatch_mode=dispatch_mode,
    )
    if _batch_external_cancellation_requested(token, cancellation_callback):
        reason = token.reason or "Batch item was cancelled before execution."
        item.cancel(reason)
        trace.cancel(reason)
        if progress_tracker is not None:
            progress_tracker.set_state(
                index,
                trace.disposition,
                item_id=item.item_id,
                force_emit=True,
            )
        return item, None, trace

    item.start()
    trace.start()
    if progress_tracker is not None:
        progress_tracker.set_state(
            index,
            BatchItemDisposition.RUNNING,
            item_id=item.item_id,
        )
    if item_callback is not None:
        item_callback(index, item)

    progress_callback = None
    if progress_tracker is not None and options.emit_child_progress:
        progress_callback = progress_tracker.child_callback(index, item.item_id)
    child_stage_callback = _batch_child_stage_callback(
        index,
        item,
        stage_callback,
        enabled=options.emit_child_stages,
    )
    child_cancellation = _batch_child_cancellation_callback(
        token,
        cancellation_callback,
    )

    output: Any = None
    try:
        if dispatch_mode == ANALYSIS_MODE_MULTIPOSE:
            output = run_multipose_analysis(
                child_request,
                config=child_request.config,
                options=options.multipose_options,
                registry=registry,
                capabilities=capabilities,
                requested_stages=child_request.requested_stages or None,
                name=child_request.name,
                metadata=child_request.metadata,
                progress_callback=progress_callback,
                stage_callback=child_stage_callback,
                cancellation_callback=child_cancellation,
            )
        else:
            output = run_single_pose_analysis(
                child_request,
                config=child_request.config,
                options=options.single_pose_options,
                registry=registry,
                capabilities=capabilities,
                requested_stages=child_request.requested_stages or None,
                name=child_request.name,
                metadata=child_request.metadata,
                progress_callback=progress_callback,
                stage_callback=child_stage_callback,
                cancellation_callback=child_cancellation,
            )
        item.finish(output, status=output.status)
        trace.finish(output, status=output.status)
    except AnalysisCancelledError as exc:
        item.cancel(str(exc))
        trace.cancel(str(exc))
    except Exception as exc:
        item.fail(exc)
        trace.fail(exc)
    finally:
        if progress_tracker is not None:
            progress_tracker.set_state(
                index,
                trace.disposition,
                item_id=item.item_id,
                force_emit=True,
            )
        if item_callback is not None:
            item_callback(index, item)
        if trace_callback is not None:
            trace_callback(trace)
    return item, output, trace


# 20.9. Sequential and threaded batch schedulers
# -----------------------------------------------------------------------------


def _cancel_unexecuted_batch_item(
    index: int,
    request: AnalysisRequest,
    reason: str,
    *,
    progress_tracker: Optional[BatchProgressTracker] = None,
) -> Tuple[BatchAnalysisItem, None, BatchItemTrace]:
    """Create a cancelled result for an item that was not scheduled."""

    child_request = prepare_batch_item_request(request, index=index)
    item = BatchAnalysisItem(
        request=child_request,
        name=child_request.name,
        metadata={
            "batch_item_index": index,
            "dispatch_mode": child_request.mode,
            "not_scheduled": True,
        },
    )
    item.cancel(reason)
    trace = BatchItemTrace(
        index=index,
        item_id=item.item_id,
        request_id=child_request.request_id,
        name=item.name,
        dispatch_mode=child_request.mode,
    )
    trace.cancel(reason)
    trace.metadata["not_scheduled"] = True
    if progress_tracker is not None:
        progress_tracker.set_state(
            index,
            BatchItemDisposition.CANCELLED,
            item_id=item.item_id,
            force_emit=True,
        )
    return item, None, trace


def run_batch_sequential(
    requests: Sequence[AnalysisRequest],
    *,
    options: BatchExecutionOptions,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    progress_tracker: Optional[BatchProgressTracker] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_token: Optional[BatchCancellationToken] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    item_callback: Optional[BatchItemCallback] = None,
    trace_callback: Optional[BatchTraceCallback] = None,
) -> Tuple[List[BatchAnalysisItem], List[Any], List[BatchItemTrace]]:
    """Execute independent requests sequentially with failure isolation."""

    token = cancellation_token or BatchCancellationToken()
    items: List[BatchAnalysisItem] = []
    outputs: List[Any] = []
    traces: List[BatchItemTrace] = []
    stop_reason: Optional[str] = None

    for index, request in enumerate(requests):
        if stop_reason is not None or _batch_external_cancellation_requested(
            token,
            cancellation_callback,
        ):
            reason = stop_reason or token.reason or "Batch execution was cancelled."
            item, output, trace = _cancel_unexecuted_batch_item(
                index,
                request,
                reason,
                progress_tracker=progress_tracker,
            )
        else:
            item, output, trace = execute_batch_item(
                index,
                request,
                options=options,
                registry=registry,
                capabilities=capabilities,
                progress_tracker=progress_tracker,
                stage_callback=stage_callback,
                cancellation_token=token,
                cancellation_callback=cancellation_callback,
                item_callback=item_callback,
                trace_callback=trace_callback,
            )
            if item.status in {AnalysisStatus.FAILED, AnalysisStatus.CANCELLED}:
                if options.stop_on_first_failure or not options.continue_on_item_error:
                    stop_reason = (
                        f"Batch stopped after item {index} ended as "
                        f"{item.status.value}."
                    )
                    if options.cancel_pending_on_failure:
                        token.cancel(
                            stop_reason,
                            metadata={"failed_item_index": index},
                        )
        items.append(item)
        outputs.append(output)
        traces.append(trace)
    return items, outputs, traces


def run_batch_threaded(
    requests: Sequence[AnalysisRequest],
    *,
    options: BatchExecutionOptions,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    progress_tracker: Optional[BatchProgressTracker] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_token: Optional[BatchCancellationToken] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    item_callback: Optional[BatchItemCallback] = None,
    trace_callback: Optional[BatchTraceCallback] = None,
) -> Tuple[List[BatchAnalysisItem], List[Any], List[BatchItemTrace]]:
    """Execute independent requests in a bounded thread pool."""

    token = cancellation_token or BatchCancellationToken()
    count = len(requests)
    item_slots: List[Optional[BatchAnalysisItem]] = [None] * count
    output_slots: List[Any] = [None] * count
    trace_slots: List[Optional[BatchItemTrace]] = [None] * count
    next_index = 0
    stop_scheduling = False
    stop_reason: Optional[str] = None
    futures: Dict[Future[Any], int] = {}

    def _submit(executor: ThreadPoolExecutor, index: int) -> None:
        future = executor.submit(
            execute_batch_item,
            index,
            requests[index],
            options=options,
            registry=registry,
            capabilities=capabilities,
            progress_tracker=progress_tracker,
            stage_callback=stage_callback,
            cancellation_token=token,
            cancellation_callback=cancellation_callback,
            item_callback=item_callback,
            trace_callback=trace_callback,
        )
        futures[future] = index

    with ThreadPoolExecutor(
        max_workers=min(options.max_workers, max(1, count)),
        thread_name_prefix="dockanalyzer-batch",
    ) as executor:
        while next_index < count and len(futures) < options.max_workers:
            _submit(executor, next_index)
            next_index += 1

        while futures:
            completed_future = next(as_completed(tuple(futures)))
            index = futures.pop(completed_future)
            try:
                item, output, trace = completed_future.result()
            except Exception as exc:  # pragma: no cover - defensive boundary
                child_request = prepare_batch_item_request(requests[index], index=index)
                item = BatchAnalysisItem(request=child_request, name=child_request.name)
                item.fail(exc)
                trace = BatchItemTrace(
                    index=index,
                    item_id=item.item_id,
                    request_id=child_request.request_id,
                    name=item.name,
                    dispatch_mode=child_request.mode,
                ).fail(exc)
                output = None
            item_slots[index] = item
            output_slots[index] = output
            trace_slots[index] = trace

            if item.status in {AnalysisStatus.FAILED, AnalysisStatus.CANCELLED}:
                if options.stop_on_first_failure or not options.continue_on_item_error:
                    stop_scheduling = True
                    stop_reason = (
                        f"Batch stopped after item {index} ended as "
                        f"{item.status.value}."
                    )
            if _batch_external_cancellation_requested(
                token,
                cancellation_callback,
            ):
                stop_scheduling = True
                stop_reason = token.reason or "Batch execution was cancelled."

            while (
                not stop_scheduling
                and next_index < count
                and len(futures) < options.max_workers
            ):
                _submit(executor, next_index)
                next_index += 1

        if stop_scheduling and options.cancel_pending_on_failure:
            token.cancel(
                stop_reason or "Batch scheduling was cancelled.",
                metadata={"next_unscheduled_index": next_index},
            )

    while next_index < count:
        item, output, trace = _cancel_unexecuted_batch_item(
            next_index,
            requests[next_index],
            stop_reason or token.reason or "Batch item was not scheduled.",
            progress_tracker=progress_tracker,
        )
        item_slots[next_index] = item
        output_slots[next_index] = output
        trace_slots[next_index] = trace
        next_index += 1

    if any(item is None for item in item_slots) or any(
        trace is None for trace in trace_slots
    ):
        raise AnalysisConcurrencyError(
            "Threaded batch execution left unresolved item slots."
        )
    return (
        [item for item in item_slots if item is not None],
        output_slots,
        [trace for trace in trace_slots if trace is not None],
    )


# 20.10. Batch aggregation and finalization
# -----------------------------------------------------------------------------


def _batch_contains_session(requests: Sequence[AnalysisRequest]) -> bool:
    """Return whether any request carries a session-bound input."""

    return any(request.session is not None for request in requests)


def derive_batch_statistics(
    items: Sequence[BatchAnalysisItem],
    traces: Sequence[BatchItemTrace],
    *,
    execution_mode: str,
    max_workers: int,
) -> Dict[str, Any]:
    """Build aggregate batch execution statistics."""

    status_counts = Counter(item.status.value for item in items)
    mode_counts = Counter(trace.dispatch_mode for trace in traces)
    disposition_counts = Counter(trace.disposition.value for trace in traces)
    durations = [
        trace.duration_seconds
        for trace in traces
        if trace.duration_seconds is not None
    ]
    return {
        "item_count": len(items),
        "successful_item_count": sum(
            item.status in ANALYSIS_SUCCESS_STATUSES for item in items
        ),
        "failed_item_count": sum(
            item.status == AnalysisStatus.FAILED for item in items
        ),
        "cancelled_item_count": sum(
            item.status == AnalysisStatus.CANCELLED for item in items
        ),
        "status_counts": dict(status_counts),
        "mode_counts": dict(mode_counts),
        "disposition_counts": dict(disposition_counts),
        "execution_mode": execution_mode,
        "max_workers": max_workers,
        "mean_item_duration_seconds": (
            sum(durations) / len(durations) if durations else None
        ),
        "minimum_item_duration_seconds": min(durations) if durations else None,
        "maximum_item_duration_seconds": max(durations) if durations else None,
    }


def validate_batch_requests(
    requests: Sequence[AnalysisRequest],
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate normalized independent batch requests."""

    errors: List[str] = []
    if not requests:
        errors.append("Batch execution requires at least one request.")
    if len(requests) > MAX_BATCH_ITEMS:
        errors.append(f"Batch request count exceeds {MAX_BATCH_ITEMS} items.")
    request_ids = [request.request_id for request in requests]
    if len(request_ids) != len(set(request_ids)):
        errors.append("Batch requests contain duplicate request identifiers.")
    for index, request in enumerate(requests):
        if not isinstance(request, AnalysisRequest):
            errors.append(f"Batch item {index} is not an AnalysisRequest.")
            continue
        if request.mode == ANALYSIS_MODE_BATCH:
            errors.append(f"Batch item {index} retains nested batch mode.")
        try:
            infer_batch_item_mode(request)
        except Exception as exc:
            errors.append(f"Batch item {index} cannot be dispatched: {exc}")
    result = tuple(unique_preserving_order(errors))
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Batch request validation failed: " + " ".join(result),
            details={"errors": list(result)},
        )
    return result


def _batch_status_from_items(items: Sequence[BatchAnalysisItem]) -> AnalysisStatus:
    """Derive aggregate batch status without mutating the result object."""

    temporary = BatchAnalysisResult(items=list(items))
    return temporary.derive_status()


def run_batch_analysis(
    value: Any = None,
    *,
    requests: Any = None,
    config: AnalysisConfigLike = None,
    options: BatchExecutionOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    context: Optional[AnalysisContext] = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    cancellation_token: Optional[BatchCancellationToken] = None,
    item_callback: Optional[BatchItemCallback] = None,
    trace_callback: Optional[BatchTraceCallback] = None,
) -> BatchAnalysisOutput:
    """Run independent analysis requests sequentially or in a thread pool."""

    resolved_options = coerce_batch_execution_options(options)
    normalized_requests = normalize_batch_requests(
        value,
        requests=requests,
        config=config,
        options=resolved_options,
    )
    if resolved_options.validate_requests:
        validate_batch_requests(normalized_requests, raise_on_error=True)
    parent_request = build_batch_request(
        normalized_requests,
        config=config,
        name=name,
        metadata=metadata,
    )
    runtime_context = context or AnalysisContext(
        request=parent_request,
        mode=ANALYSIS_MODE_BATCH,
        progress_callback=progress_callback,
        stage_callback=stage_callback,
        cancellation_callback=cancellation_callback,
    )
    runtime_context.start()
    token = cancellation_token or BatchCancellationToken()
    tracker = BatchProgressTracker(
        len(normalized_requests),
        callback=progress_callback,
        interval=resolved_options.progress_interval,
    )
    tracker.emit()

    in_chimerax = _batch_contains_session(normalized_requests)
    effective_mode = resolved_options.effective_execution_mode(
        runtime=parent_request.config.runtime,
        in_chimerax=in_chimerax,
    )
    effective_workers = (
        min(resolved_options.max_workers, len(normalized_requests))
        if effective_mode == EXECUTION_MODE_THREADED
        else 1
    )
    batch_result = BatchAnalysisResult(
        name=parent_request.name,
        status=AnalysisStatus.RUNNING,
        started_at=runtime_context.started_at,
        metadata={
            "schema": BATCH_EXECUTION_SCHEMA_NAME,
            "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
            "options_fingerprint": resolved_options.fingerprint,
            "effective_execution_mode": effective_mode,
            "effective_max_workers": effective_workers,
        },
    )
    run_result = AnalysisRunResult(
        run_id=runtime_context.run_id,
        request_id=parent_request.request_id,
        name=parent_request.name,
        mode=ANALYSIS_MODE_BATCH,
        status=AnalysisStatus.RUNNING,
        request=parent_request,
        context=runtime_context if resolved_options.preserve_context else None,
        started_at=runtime_context.started_at,
        metadata={
            "schema": BATCH_EXECUTION_SCHEMA_NAME,
            "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
            "options_fingerprint": resolved_options.fingerprint,
        },
    )

    if effective_mode == EXECUTION_MODE_THREADED and effective_workers > 1:
        scheduler_options = replace(
            resolved_options,
            execution_mode=EXECUTION_MODE_THREADED,
            max_workers=effective_workers,
        )
        items, item_outputs, traces = run_batch_threaded(
            normalized_requests,
            options=scheduler_options,
            registry=registry,
            capabilities=capabilities,
            progress_tracker=tracker,
            stage_callback=stage_callback,
            cancellation_token=token,
            cancellation_callback=cancellation_callback,
            item_callback=item_callback,
            trace_callback=trace_callback,
        )
    else:
        items, item_outputs, traces = run_batch_sequential(
            normalized_requests,
            options=replace(
                resolved_options,
                execution_mode=EXECUTION_MODE_SEQUENTIAL,
                max_workers=1,
            ),
            registry=registry,
            capabilities=capabilities,
            progress_tracker=tracker,
            stage_callback=stage_callback,
            cancellation_token=token,
            cancellation_callback=cancellation_callback,
            item_callback=item_callback,
            trace_callback=trace_callback,
        )

    for item in items:
        batch_result.add_item(item)
    statistics = derive_batch_statistics(
        items,
        traces,
        execution_mode=effective_mode,
        max_workers=effective_workers,
    )
    batch_result.statistics.update(statistics)
    batch_status = _batch_status_from_items(items)
    batch_result.finalize(batch_status)
    run_result.set_payload(batch_result)
    run_result.statistics.update(statistics)
    run_result.finalize(batch_status)
    runtime_context.statistics[BATCH_STATISTICS_KEY] = dict(statistics)
    runtime_context.metadata[BATCH_METADATA_KEY] = {
        "schema": BATCH_EXECUTION_SCHEMA_NAME,
        "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
        "options_fingerprint": resolved_options.fingerprint,
        "effective_execution_mode": effective_mode,
        "effective_max_workers": effective_workers,
    }
    runtime_context.set_status(batch_status, force=True)

    warning_messages: List[str] = list(tracker.callback_errors)
    error_messages: List[str] = []
    for item in items:
        warning_messages.extend(issue.message for issue in item.diagnostics.warnings)
        error_messages.extend(issue.message for issue in item.diagnostics.errors)
    final_snapshot = tracker.snapshot()
    output = BatchAnalysisOutput(
        request=parent_request,
        context=runtime_context,
        batch_result=batch_result,
        run_result=run_result,
        options=resolved_options,
        item_outputs=(
            tuple(item_outputs)
            if resolved_options.preserve_item_outputs
            else tuple()
        ),
        item_traces=tuple(traces),
        progress=final_snapshot,
        cancellation=token,
        warnings=tuple(unique_preserving_order(warning_messages)),
        errors=tuple(unique_preserving_order(error_messages)),
        metadata={
            "schema": BATCH_EXECUTION_SCHEMA_NAME,
            "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
            "options_fingerprint": resolved_options.fingerprint,
            "effective_execution_mode": effective_mode,
            "effective_max_workers": effective_workers,
            **dict(resolved_options.metadata),
        },
    )
    runtime_context.set_shared(BATCH_CONTEXT_KEY, runtime_context)
    runtime_context.set_shared(BATCH_OUTPUT_KEY, output)
    runtime_context.set_shared(BATCH_RESULT_KEY, batch_result)
    runtime_context.set_shared(BATCH_RUN_RESULT_KEY, run_result)
    runtime_context.set_shared(BATCH_ITEM_OUTPUTS_KEY, tuple(item_outputs))
    runtime_context.set_shared(BATCH_ITEM_TRACES_KEY, tuple(traces))
    runtime_context.set_shared(BATCH_PROGRESS_KEY, final_snapshot)

    if resolved_options.validate_results:
        validation_errors = validate_batch_analysis_output(
            output,
            raise_on_error=False,
        )
        if validation_errors:
            output.errors = tuple(
                unique_preserving_order([*output.errors, *validation_errors])
            )
    if resolved_options.raise_on_error and output.status in {
        AnalysisStatus.FAILED,
        AnalysisStatus.CANCELLED,
    }:
        raise AnalysisBatchError(
            "Batch analysis did not complete successfully.",
            details=output.summary(),
        )
    return output


# 20.11. Convenience wrappers
# -----------------------------------------------------------------------------


def analyze_batch(value: Any = None, **kwargs: Any) -> BatchAnalysisResult:
    """Run independent requests and return the aggregate batch result."""

    return run_batch_analysis(value, **kwargs).batch_result


def execute_batch_pipeline(
    value: Any = None,
    **kwargs: Any,
) -> BatchAnalysisOutput:
    """Alias for :func:`run_batch_analysis`."""

    return run_batch_analysis(value, **kwargs)


def batch_map(
    values: Iterable[Any],
    *,
    config: AnalysisConfigLike = None,
    options: BatchExecutionOptionsLike = None,
    **kwargs: Any,
) -> Tuple[Any, ...]:
    """Analyze values as independent requests and return ordered item outputs."""

    output = run_batch_analysis(
        tuple(values),
        config=config,
        options=options,
        **kwargs,
    )
    return output.item_outputs


# 20.12. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_batch_analysis_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one complete batch orchestration output."""

    errors: List[str] = []
    if not isinstance(value, BatchAnalysisOutput):
        errors.append("Value is not a BatchAnalysisOutput instance.")
    else:
        if value.request.mode != ANALYSIS_MODE_BATCH:
            errors.append("Batch parent request has an invalid analysis mode.")
        if value.context.mode != ANALYSIS_MODE_BATCH:
            errors.append("Batch context has an invalid analysis mode.")
        if value.run_result.batch_result is not value.batch_result:
            errors.append("Batch run result does not reference the aggregate result.")
        if value.run_result.payload is not value.batch_result:
            errors.append("Run-result payload is not the batch result.")
        if len(value.batch_result.items) != len(value.item_traces):
            errors.append("Batch item and trace counts are inconsistent.")
        if value.options.preserve_item_outputs and (
            len(value.item_outputs) != len(value.batch_result.items)
        ):
            errors.append("Preserved batch output count is inconsistent.")
        indices = [trace.index for trace in value.item_traces]
        if indices != list(range(len(indices))):
            errors.append("Batch traces do not preserve input order.")
        item_ids = [item.item_id for item in value.batch_result.items]
        trace_ids = [trace.item_id for trace in value.item_traces]
        if item_ids != trace_ids:
            errors.append("Batch trace identifiers do not match batch items.")
        if value.progress is not None:
            if value.progress.total_items != value.batch_result.item_count:
                errors.append("Batch progress total does not match item count.")
            if value.progress.completed_items != value.batch_result.item_count:
                errors.append("Batch progress did not reach all items.")
        if value.options.fingerprint != value.metadata.get("options_fingerprint"):
            errors.append("Batch options fingerprint is inconsistent.")
        expected_status = value.batch_result.derive_status()
        if value.status != expected_status:
            errors.append("Batch aggregate status is inconsistent with its items.")
        errors.extend(validate_core_result(value.batch_result, raise_on_error=False))
        errors.extend(validate_core_result(value.run_result, raise_on_error=False))
    result = tuple(unique_preserving_order(errors))
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Batch output validation failed: " + " ".join(result),
            details={"errors": list(result)},
        )
    return result


def summarize_batch_analysis(value: Any) -> Dict[str, Any]:
    """Return a concise summary of a batch output or result."""

    if isinstance(value, BatchAnalysisOutput):
        return value.summary()
    result = coerce_batch_analysis_result(value)
    status_counts = Counter(item.status.value for item in result.items)
    return {
        "schema": BATCH_EXECUTION_SCHEMA_NAME,
        "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
        "batch_id": result.batch_id,
        "name": result.name,
        "status": result.status.value,
        "item_count": result.item_count,
        "successful_item_count": len(result.successful_items),
        "failed_item_count": len(result.failed_items),
        "status_counts": dict(status_counts),
        "duration_seconds": result.duration_seconds,
    }


def batch_analysis_to_json(
    value: BatchAnalysisOutput,
    *,
    include_objects: bool = False,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
    sort_keys: bool = True,
) -> str:
    """Serialize a complete batch output to JSON."""

    if not isinstance(value, BatchAnalysisOutput):
        raise TypeError("value must be a BatchAnalysisOutput instance.")
    return json.dumps(
        value.to_dict(include_objects=include_objects),
        indent=indent,
        sort_keys=sort_keys,
        default=str,
    )


# 20.13. Internal convention validation
# -----------------------------------------------------------------------------


def validate_batch_execution_conventions() -> Dict[str, Any]:
    """Validate sequential and threaded batch execution with synthetic stages."""

    failures: List[str] = []

    class _SyntheticAtoms(list):
        @property
        def residues(self) -> List[Any]:
            return [getattr(atom, "residue", None) for atom in self]

    receptor_residue = SimpleNamespace(name="REC", chain_id="A", number=1)
    receptor_atom = SimpleNamespace(
        name="C1",
        element=SimpleNamespace(name="C"),
        coord=(0.0, 0.0, 0.0),
        residue=receptor_residue,
    )
    receptor_model = SimpleNamespace(
        name="section20_receptor",
        id_string="1",
        atoms=_SyntheticAtoms([receptor_atom]),
        residues=[receptor_residue],
    )
    dock_models: List[DockModel] = []
    for index, distance in enumerate((3.5, 4.0), start=1):
        ligand_residue = SimpleNamespace(name="LIG", chain_id="L", number=index)
        ligand_atom = SimpleNamespace(
            name=f"C{index + 1}",
            element=SimpleNamespace(name="C"),
            coord=(distance, 0.0, 0.0),
            residue=ligand_residue,
        )
        pose_model = SimpleNamespace(
            name=f"section20_pose_{index}",
            id_string=str(index + 1),
            atoms=_SyntheticAtoms([ligand_atom]),
            residues=[ligand_residue],
        )
        dock_models.append(
            DockModel(
                name=f"section20_pose_{index}",
                receptor=receptor_model,
                pose=pose_model,
                ligand=pose_model,
            )
        )

    def _synthetic_contacts_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        index = context.current_pose_index if context is not None else 0
        interaction = SimpleNamespace(
            interaction_id=f"section20_contact_{index}",
            distance=3.5 + float(index or 0),
            score=1.0,
        )
        result = AnalysisStageResult(stage=STAGE_CONTACTS, required=True)
        result.start().succeed(
            SimpleNamespace(contacts=(interaction,), statistics={"total": 1})
        )
        return result

    def _synthetic_consolidation_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        index = context.current_pose_index if context is not None else 0
        interaction = SimpleNamespace(
            interaction_id=f"section20_contact_{index}",
            distance=3.5 + float(index or 0),
            score=1.0,
        )
        result = AnalysisStageResult(stage=STAGE_CONSOLIDATION, required=True)
        result.start().succeed(InteractionAnalysisBundle(contacts=[interaction]))
        return result

    def _synthetic_scoring_executor(
        context: Optional[AnalysisContext] = None,
        **_: Any,
    ) -> AnalysisStageResult:
        dock_model = context.current_dock_model if context is not None else None
        model_name = get_preparation_model_name(dock_model, default="pose")
        score = 2.0 if model_name.endswith("_2") else 1.0
        result = AnalysisStageResult(stage=STAGE_SCORING, required=True)
        result.start().succeed(
            SimpleNamespace(final_score=score, interaction_count=1)
        )
        return result

    registry = get_default_stage_registry(copy_registry=True)
    for stage, executor in (
        (STAGE_CONTACTS, _synthetic_contacts_executor),
        (STAGE_CONSOLIDATION, _synthetic_consolidation_executor),
        (STAGE_SCORING, _synthetic_scoring_executor),
    ):
        definition = registry.require(stage)
        registry.replace(
            replace(
                definition,
                executor=executor,
                result_adapter=None,
                validator=None,
                required_modules=(),
            )
        )

    requested_stages = (
        STAGE_INPUT_RESOLUTION,
        STAGE_MODEL_PREPARATION,
        STAGE_CONTACTS,
        STAGE_CONSOLIDATION,
        STAGE_SCORING,
        STAGE_VALIDATION,
        STAGE_FINALIZATION,
    )
    integrated = AnalysisConfig(
        requested_stages=requested_stages,
        include_stage_dependencies=True,
        include_internal_stages=True,
    )
    single_options = SinglePoseExecutionOptions(
        requested_stages=requested_stages,
        include_dependencies=True,
        include_ordering_predecessors=False,
        inspect_capabilities=False,
        require_registered_executors=False,
        validate_input=True,
        validate_result=True,
    )
    multipose_options = MultiposeExecutionOptions(
        requested_stages=requested_stages,
        include_dependencies=True,
        include_ordering_predecessors=False,
        inspect_capabilities=False,
        require_registered_executors=False,
        validate_input=True,
        validate_result=True,
        run_native_multipose_scoring=False,
        build_ranking=True,
        build_consensus=True,
    )
    requests = (
        AnalysisRequest(
            receptor=receptor_model,
            poses=(dock_models[0].pose,),
            dock_models=(dock_models[0],),
            config=integrated,
            name="section20_single",
            mode=ANALYSIS_MODE_SINGLE_POSE,
            requested_stages=requested_stages,
        ),
        AnalysisRequest(
            receptor=receptor_model,
            poses=tuple(model.pose for model in dock_models),
            dock_models=tuple(dock_models),
            config=integrated,
            name="section20_multi",
            mode=ANALYSIS_MODE_MULTIPOSE,
            requested_stages=requested_stages,
        ),
    )
    progress_events: List[Tuple[str, int, int]] = []

    def _progress(stage: str, completed: int, total: int, _: Metadata) -> None:
        progress_events.append((stage, completed, total))

    threaded_single_model = copy.deepcopy(dock_models[0])
    threaded_multi_models = tuple(copy.deepcopy(model) for model in dock_models)
    threaded_requests = (
        replace(
            requests[0],
            receptor=threaded_single_model.receptor,
            poses=(threaded_single_model.pose,),
            dock_models=(threaded_single_model,),
        ),
        replace(
            requests[1],
            receptor=threaded_multi_models[0].receptor,
            poses=tuple(model.pose for model in threaded_multi_models),
            dock_models=threaded_multi_models,
        ),
    )
    sequential = run_batch_analysis(
        requests=requests,
        config=integrated,
        options=BatchExecutionOptions(
            execution_mode=EXECUTION_MODE_SEQUENTIAL,
            max_workers=1,
            single_pose_options=single_options,
            multipose_options=multipose_options,
        ),
        registry=registry,
        progress_callback=_progress,
    )
    if sequential.status != AnalysisStatus.SUCCEEDED:
        failures.append(
            f"Sequential synthetic batch ended as {sequential.status.value!r}."
        )
    if sequential.item_count != 2:
        failures.append("Sequential synthetic batch item count is invalid.")
    if [trace.dispatch_mode for trace in sequential.item_traces] != [
        ANALYSIS_MODE_SINGLE_POSE,
        ANALYSIS_MODE_MULTIPOSE,
    ]:
        failures.append("Batch dispatcher selected incorrect child modes.")
    if not progress_events or progress_events[-1][1:] != (2, 2):
        failures.append("Batch progress did not report final completion.")
    validation_errors = validate_batch_analysis_output(
        sequential,
        raise_on_error=False,
    )
    if validation_errors:
        failures.extend(validation_errors)
    payload = batch_analysis_to_json(sequential)
    if BATCH_EXECUTION_SCHEMA_NAME not in payload:
        failures.append("Batch JSON serialization omitted the schema name.")

    threaded = run_batch_analysis(
        requests=threaded_requests,
        config=integrated,
        options=BatchExecutionOptions(
            execution_mode=EXECUTION_MODE_THREADED,
            max_workers=2,
            single_pose_options=single_options,
            multipose_options=multipose_options,
        ),
        registry=registry,
    )
    if threaded.status != AnalysisStatus.SUCCEEDED:
        failures.append(
            f"Threaded synthetic batch ended as {threaded.status.value!r}."
        )
    if [trace.index for trace in threaded.item_traces] != [0, 1]:
        failures.append("Threaded batch did not preserve input order.")
    if len(threaded.options.fingerprint) != 64:
        failures.append("Batch options fingerprint is invalid.")
    token = BatchCancellationToken()
    if not token.cancel("Synthetic cancellation") or not token.cancelled:
        failures.append("Batch cancellation token did not activate correctly.")
    token.reset()
    if token.cancelled:
        failures.append("Batch cancellation token did not reset correctly.")
    if sequential.context.get_shared(BATCH_OUTPUT_KEY) is not sequential:
        failures.append("Batch output was not retained in the context.")

    if failures:
        raise RuntimeError(
            "Batch execution convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": BATCH_EXECUTION_SCHEMA_NAME,
        "schema_version": BATCH_EXECUTION_SCHEMA_VERSION,
        "sequential_item_count": sequential.item_count,
        "threaded_item_count": threaded.item_count,
        "validated_cases": 28,
    }


