# 21.2. Configuration
# -----------------------------------------------------------------------------


def _consensus_mapping(value: Any) -> Dict[str, Any]:
    """Return a mutable mapping for one native option group."""

    if value is None:
        return {}
    if isinstance(value, Mapping):
        return {str(key): item for key, item in value.items()}
    if is_dataclass(value):
        return {
            item.name: getattr(value, item.name)
            for item in fields(value)
        }
    raise AnalysisConfigurationError(
        "Consensus option groups must be mappings, dataclasses or None.",
        stage=STAGE_CONSENSUS,
        details={"type": type(value).__name__},
    )


def _consensus_optional_positive_int(
    value: Any,
    *,
    name: str,
) -> Optional[int]:
    """Normalize one optional positive integer."""

    if value is None:
        return None
    normalized = int(value)
    if normalized < 1:
        raise AnalysisConfigurationError(
            f"{name} must be positive or None.",
            stage=STAGE_CONSENSUS,
        )
    return normalized


def _consensus_fraction(value: Any, *, name: str) -> float:
    """Normalize one finite fraction in the inclusive range zero to one."""

    normalized = float(value)
    if not math.isfinite(normalized) or not 0.0 <= normalized <= 1.0:
        raise AnalysisConfigurationError(
            f"{name} must be a finite value between zero and one.",
            stage=STAGE_CONSENSUS,
        )
    return normalized


@dataclass(frozen=True)
class AdvancedMultiposeAnalysisConfig:
    """Configuration for persistence, diversity and complementarity analysis."""

    calculate_persistence: bool = True
    calculate_diversity: bool = True
    calculate_complementarity: bool = True
    optimize_pose_set: bool = True
    generate_explainability: bool = True
    attach_results: bool = True
    reuse_existing: bool = True
    continue_on_error: bool = True
    require_multiple_poses: bool = True
    allow_degenerate_results: bool = True
    minimum_pose_count: int = CONSENSUS_ANALYSIS_MINIMUM_POSES
    maximum_pose_count: int = CONSENSUS_ANALYSIS_MAXIMUM_POSES
    representative_pose_count: Optional[int] = None
    maximum_selected_poses: Optional[int] = None
    consensus_threshold: float = CONSENSUS_ANALYSIS_DEFAULT_THRESHOLD
    core_threshold: float = CONSENSUS_ANALYSIS_DEFAULT_CORE_THRESHOLD
    supporting_threshold: float = CONSENSUS_ANALYSIS_DEFAULT_SUPPORTING_THRESHOLD
    target_coverage_fraction: float = CONSENSUS_ANALYSIS_DEFAULT_TARGET_COVERAGE
    fingerprint_options: Mapping[str, Any] = field(default_factory=dict)
    diversity_options: Mapping[str, Any] = field(default_factory=dict)
    coverage_options: Mapping[str, Any] = field(default_factory=dict)
    selection_options: Mapping[str, Any] = field(default_factory=dict)
    consensus_options: Mapping[str, Any] = field(default_factory=dict)
    explainability_options: Mapping[str, Any] = field(default_factory=dict)
    consensus_explainability_options: Mapping[str, Any] = field(default_factory=dict)
    attachment_options: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        minimum_pose_count = int(self.minimum_pose_count)
        maximum_pose_count = int(self.maximum_pose_count)
        if minimum_pose_count < 1:
            raise ValueError("minimum_pose_count must be positive.")
        if maximum_pose_count < minimum_pose_count:
            raise ValueError(
                "maximum_pose_count cannot be smaller than minimum_pose_count."
            )
        object.__setattr__(self, "minimum_pose_count", minimum_pose_count)
        object.__setattr__(self, "maximum_pose_count", maximum_pose_count)
        object.__setattr__(
            self,
            "representative_pose_count",
            _consensus_optional_positive_int(
                self.representative_pose_count,
                name="representative_pose_count",
            ),
        )
        object.__setattr__(
            self,
            "maximum_selected_poses",
            _consensus_optional_positive_int(
                self.maximum_selected_poses,
                name="maximum_selected_poses",
            ),
        )
        consensus_threshold = _consensus_fraction(
            self.consensus_threshold,
            name="consensus_threshold",
        )
        core_threshold = _consensus_fraction(
            self.core_threshold,
            name="core_threshold",
        )
        supporting_threshold = _consensus_fraction(
            self.supporting_threshold,
            name="supporting_threshold",
        )
        target_coverage_fraction = _consensus_fraction(
            self.target_coverage_fraction,
            name="target_coverage_fraction",
        )
        if supporting_threshold > consensus_threshold:
            raise ValueError(
                "supporting_threshold cannot exceed consensus_threshold."
            )
        if consensus_threshold > core_threshold:
            raise ValueError("consensus_threshold cannot exceed core_threshold.")
        object.__setattr__(self, "consensus_threshold", consensus_threshold)
        object.__setattr__(self, "core_threshold", core_threshold)
        object.__setattr__(self, "supporting_threshold", supporting_threshold)
        object.__setattr__(
            self,
            "target_coverage_fraction",
            target_coverage_fraction,
        )
        for name in (
            "fingerprint_options",
            "diversity_options",
            "coverage_options",
            "selection_options",
            "consensus_options",
            "explainability_options",
            "consensus_explainability_options",
            "attachment_options",
            "metadata",
        ):
            object.__setattr__(
                self,
                name,
                MappingProxyType(_consensus_mapping(getattr(self, name))),
            )

    @property
    def fingerprint(self) -> str:
        """Return a stable configuration fingerprint."""

        payload = json.dumps(
            self.to_dict(),
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        return sha256(payload.encode("utf-8")).hexdigest()

    @property
    def enabled_components(self) -> Tuple[str, ...]:
        """Return enabled analytical components in execution order."""

        result: List[str] = []
        if self.calculate_persistence:
            result.append(CONSENSUS_COMPONENT_PERSISTENCE)
        if self.calculate_diversity:
            result.append(CONSENSUS_COMPONENT_DIVERSITY)
        if self.calculate_complementarity:
            result.append(CONSENSUS_COMPONENT_COMPLEMENTARITY)
        if self.optimize_pose_set:
            result.append(CONSENSUS_COMPONENT_SELECTION)
        if self.generate_explainability:
            result.append(CONSENSUS_COMPONENT_EXPLAINABILITY)
        if self.attach_results:
            result.append(CONSENSUS_COMPONENT_ATTACHMENT)
        return tuple(result)

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible configuration mapping."""

        return to_json_compatible(
            {
                item.name: getattr(self, item.name)
                for item in fields(self)
            }
        )


AdvancedMultiposeAnalysisConfigLike: TypeAlias = Union[
    AdvancedMultiposeAnalysisConfig,
    Mapping[str, Any],
    None,
]


def resolve_advanced_multipose_config(
    config: AdvancedMultiposeAnalysisConfigLike = None,
    *,
    analysis_config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> AdvancedMultiposeAnalysisConfig:
    """Resolve advanced multipose settings from integrated configuration."""

    if isinstance(config, AdvancedMultiposeAnalysisConfig):
        values = config.to_dict()
    elif config is None:
        values = {}
    elif isinstance(config, Mapping):
        values = dict(config)
    else:
        raise AnalysisConfigurationError(
            "Unsupported advanced multipose configuration type.",
            stage=STAGE_CONSENSUS,
            details={"type": type(config).__name__},
        )
    if analysis_config is not None:
        integrated = coerce_analysis_config(analysis_config)
        stage_config = integrated.stage_config(STAGE_CONSENSUS)
        module_values = integrated.module_configs.get(STAGE_CONSENSUS, {})
        if isinstance(module_values, Mapping):
            values = {**dict(module_values), **values}
        if stage_config.options:
            values = {**dict(stage_config.options), **values}
        values.setdefault("attach_results", integrated.attach_results)
        values.setdefault(
            "continue_on_error",
            integrated.runtime.failure_policy != FAILURE_POLICY_STRICT,
        )
    if overrides:
        values.update(dict(overrides))
    accepted = {item.name for item in fields(AdvancedMultiposeAnalysisConfig)}
    unknown = sorted(str(key) for key in values if str(key) not in accepted)
    if unknown:
        raise AnalysisConfigurationError(
            "Unsupported advanced multipose configuration fields were provided.",
            stage=STAGE_CONSENSUS,
            details={"fields": unknown},
        )
    return AdvancedMultiposeAnalysisConfig(**values)


