@dataclass(frozen=True)
class PersistentFeatureSummary:
    """Compact representation of one persistent feature."""

    feature_id: str
    level: str
    pose_count: int
    denominator_pose_count: int
    persistence: float
    classification: str = ""
    family: str = ""
    interaction_type: str = ""
    receptor_residue: str = ""
    ligand_residue: str = ""
    representative_pose_id: str = ""
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "feature_id", str(self.feature_id))
        object.__setattr__(self, "level", str(self.level))
        object.__setattr__(self, "pose_count", max(0, int(self.pose_count)))
        object.__setattr__(
            self,
            "denominator_pose_count",
            max(0, int(self.denominator_pose_count)),
        )
        object.__setattr__(
            self,
            "persistence",
            max(0.0, min(1.0, float(self.persistence))),
        )
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready feature summary."""

        return to_json_compatible(
            {item.name: getattr(self, item.name) for item in fields(self)}
        )


@dataclass(frozen=True)
class AdvancedMultiposeSummary:
    """Compact summary of advanced multipose comparison."""

    status: str
    pose_count: int
    scored_pose_count: int
    persistent_feature_count: int = 0
    consensus_feature_count: int = 0
    core_feature_count: int = 0
    ubiquitous_feature_count: int = 0
    mean_similarity: Optional[float] = None
    mean_diversity: Optional[float] = None
    unique_fingerprint_count: int = 0
    representative_pose_ids: Tuple[str, ...] = ()
    selected_pose_ids: Tuple[str, ...] = ()
    weighted_coverage_fraction: Optional[float] = None
    residue_coverage_fraction: Optional[float] = None
    family_coverage_fraction: Optional[float] = None
    type_coverage_fraction: Optional[float] = None
    hotspot_coverage_fraction: Optional[float] = None
    target_reached: bool = False
    optimality_guaranteed: bool = False
    attached_dock_model_count: int = 0
    warning_count: int = 0
    error_count: int = 0

    def __post_init__(self) -> None:
        normalized_status = str(self.status).strip().lower()
        if normalized_status not in CONSENSUS_STATUSES:
            normalized_status = CONSENSUS_STATUS_PARTIAL
        object.__setattr__(self, "status", normalized_status)
        for name in (
            "pose_count",
            "scored_pose_count",
            "persistent_feature_count",
            "consensus_feature_count",
            "core_feature_count",
            "ubiquitous_feature_count",
            "unique_fingerprint_count",
            "attached_dock_model_count",
            "warning_count",
            "error_count",
        ):
            object.__setattr__(self, name, max(0, int(getattr(self, name))))
        object.__setattr__(
            self,
            "representative_pose_ids",
            tuple(str(item) for item in self.representative_pose_ids),
        )
        object.__setattr__(
            self,
            "selected_pose_ids",
            tuple(str(item) for item in self.selected_pose_ids),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready summary mapping."""

        return to_json_compatible(
            {item.name: getattr(self, item.name) for item in fields(self)}
        )


@dataclass(frozen=True)
class AdvancedMultiposeAnalysisOutput:
    """Complete persistence, diversity and complementarity output."""

    pose_results: Tuple[Any, ...]
    consensus_result: Any = None
    diversity_result: Any = None
    complementarity_result: Any = None
    selection_result: Any = None
    complementarity_explanation: Any = None
    consensus_explanation: Any = None
    persistent_features: Tuple[PersistentFeatureSummary, ...] = ()
    summary: AdvancedMultiposeSummary = field(
        default_factory=lambda: AdvancedMultiposeSummary(
            status=CONSENSUS_STATUS_SKIPPED,
            pose_count=0,
            scored_pose_count=0,
        )
    )
    component_statuses: Mapping[str, str] = field(default_factory=dict)
    attachment_result: Mapping[str, Any] = field(default_factory=dict)
    warnings: Tuple[str, ...] = ()
    errors: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict)
    configuration: AdvancedMultiposeAnalysisConfig = field(
        default_factory=AdvancedMultiposeAnalysisConfig
    )
    module_name: str = SCORING_MODULE_NAME
    module_version: Optional[str] = None
    schema_name: str = CONSENSUS_ANALYSIS_SCHEMA_NAME
    schema_version: str = CONSENSUS_ANALYSIS_SCHEMA_VERSION
    result_type: str = CONSENSUS_ANALYSIS_RESULT_TYPE

    def __post_init__(self) -> None:
        object.__setattr__(self, "pose_results", tuple(self.pose_results))
        object.__setattr__(
            self,
            "persistent_features",
            tuple(self.persistent_features),
        )
        object.__setattr__(
            self,
            "component_statuses",
            MappingProxyType(
                {str(key): str(value) for key, value in self.component_statuses.items()}
            ),
        )
        object.__setattr__(
            self,
            "attachment_result",
            MappingProxyType(dict(self.attachment_result)),
        )
        object.__setattr__(
            self,
            "warnings",
            tuple(unique_preserving_order(str(item) for item in self.warnings)),
        )
        object.__setattr__(
            self,
            "errors",
            tuple(unique_preserving_order(str(item) for item in self.errors)),
        )
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    @property
    def successful(self) -> bool:
        """Return whether the advanced comparison produced accepted output."""

        return self.summary.status in {
            CONSENSUS_STATUS_COMPLETE,
            CONSENSUS_STATUS_DEGENERATE,
        }

    @property
    def partial(self) -> bool:
        """Return whether only part of the requested comparison succeeded."""

        return self.summary.status == CONSENSUS_STATUS_PARTIAL

    @property
    def selected_pose_ids(self) -> Tuple[str, ...]:
        """Return the optimized pose-set identifiers."""

        return self.summary.selected_pose_ids

    @property
    def representative_pose_ids(self) -> Tuple[str, ...]:
        """Return representative pose identifiers from diversity analysis."""

        return self.summary.representative_pose_ids

    def to_dict(self, *, include_results: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready output mapping."""

        payload: Dict[str, Any] = {
            "schema": self.schema_name,
            "schema_version": self.schema_version,
            "result_type": self.result_type,
            "summary": self.summary.to_dict(),
            "persistent_features": [item.to_dict() for item in self.persistent_features],
            "component_statuses": dict(self.component_statuses),
            "attachment_result": to_json_compatible(dict(self.attachment_result)),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(dict(self.metadata)),
            "configuration": self.configuration.to_dict(),
            "configuration_fingerprint": self.configuration.fingerprint,
            "module_name": self.module_name,
            "module_version": self.module_version,
        }
        if include_results:
            payload.update(
                {
                    "pose_results": to_json_compatible(self.pose_results),
                    "consensus_result": to_json_compatible(self.consensus_result),
                    "diversity_result": to_json_compatible(self.diversity_result),
                    "complementarity_result": to_json_compatible(
                        self.complementarity_result
                    ),
                    "selection_result": to_json_compatible(self.selection_result),
                    "complementarity_explanation": to_json_compatible(
                        self.complementarity_explanation
                    ),
                    "consensus_explanation": to_json_compatible(
                        self.consensus_explanation
                    ),
                }
            )
        return payload


