def _advanced_exact_value(
    value: Any,
    name: str,
    default: Any = None,
) -> Any:
    """Read one exact field without applying project-wide aliases."""

    if value is None:
        return default
    if isinstance(value, Mapping) and name in value:
        return value[name]
    try:
        return getattr(value, name)
    except (AttributeError, TypeError):
        return default


def _advanced_scoring_result(value: Any) -> Any:
    """Extract one native PoseScoringResult from an integrated value."""

    if value is None:
        return None
    if isinstance(value, ScoringStageOutput):
        return value.scoring_result
    candidate = get_object_value(value, "scoring_result", default=None)
    if candidate is not None:
        return candidate
    if get_object_value(value, "summary", default=None) is not None and (
        get_object_value(value, "scores", default=None) is not None
        or get_object_value(value, "pose_id", default=None) is not None
    ):
        return value
    return None


def resolve_advanced_pose_scoring_results(
    source: Any,
    *,
    native_scoring_output: Optional[ScoringMultiposeOutput] = None,
) -> Tuple[Any, ...]:
    """Resolve native pose-scoring results from orchestration outputs."""

    if native_scoring_output is not None and native_scoring_output.pose_results:
        return tuple(native_scoring_output.pose_results)
    if isinstance(source, ScoringMultiposeOutput):
        return tuple(source.pose_results)
    if isinstance(source, MultiposeAnalysisOutput):
        if source.native_scoring_output is not None:
            native = tuple(source.native_scoring_output.pose_results)
            if native:
                return native
        source = source.pose_results
    elif isinstance(source, MultiPoseAnalysisResult):
        source = source.pose_results
    elif isinstance(source, AnalysisContext):
        native = source.get_shared(MULTIPOSE_SCORING_OUTPUT_KEY)
        if isinstance(native, ScoringMultiposeOutput) and native.pose_results:
            return tuple(native.pose_results)
        multipose = source.get_shared(MULTIPOSE_RESULT_KEY)
        if isinstance(multipose, MultiPoseAnalysisResult):
            source = multipose.pose_results
        else:
            source = ()
    values = normalize_object_sequence(source)
    resolved: List[Any] = []
    seen: Set[str] = set()
    for value in values:
        if isinstance(value, PoseAnalysisResult):
            candidate = _advanced_scoring_result(value.scoring)
        else:
            candidate = _advanced_scoring_result(value)
        if candidate is None:
            continue
        pose_id = str(
            _advanced_exact_value(candidate, "pose_id", "") or ""
        ).strip()
        key = pose_id or f"object:{id(candidate)}"
        if key in seen:
            continue
        seen.add(key)
        resolved.append(candidate)
    return tuple(resolved)


def _build_native_consensus_option(
    module: ModuleType,
    class_name: str,
    values: Mapping[str, Any],
) -> Any:
    """Construct one scoring-native option object."""

    factory = getattr(module, class_name, None)
    if not callable(factory):
        raise AnalysisDependencyError(
            f"The scoring module does not expose {class_name}.",
            stage=STAGE_CONSENSUS,
        )
    return _construct_scoring_native_object(
        factory,
        dict(values),
        field_name=class_name,
    )


