# 21.5. Persistence and feature summaries
# -----------------------------------------------------------------------------


def _persistent_feature_value(value: Any, *names: str, default: Any = None) -> Any:
    """Read one persistent-feature field through compatible aliases."""

    for name in names:
        candidate = get_object_value(value, name, default=None, skip_none=True)
        if candidate is not None:
            return candidate
    return default


def summarize_persistent_feature(value: Any) -> PersistentFeatureSummary:
    """Convert one native persistent feature to the integrated summary."""

    metadata = normalize_metadata_mapping(
        _persistent_feature_value(value, "metadata", default={}),
        copy_values=True,
    )
    residue_pair = normalize_object_sequence(
        _persistent_feature_value(value, "residue_pair", default=())
    )
    receptor_residue = str(
        _persistent_feature_value(
            value,
            "receptor_residue",
            "protein_residue",
            default=residue_pair[0] if residue_pair else "",
        )
    )
    ligand_residue = str(
        _persistent_feature_value(
            value,
            "ligand_residue",
            default=residue_pair[1] if len(residue_pair) > 1 else "",
        )
    )
    denominator = int(
        _persistent_feature_value(
            value,
            "denominator_pose_count",
            "eligible_pose_count",
            default=0,
        )
        or 0
    )
    pose_count = int(
        _persistent_feature_value(
            value,
            "pose_count",
            "support_pose_count",
            "observed_pose_count",
            default=0,
        )
        or 0
    )
    persistence = _persistent_feature_value(
        value,
        "persistence",
        "persistence_fraction",
        "frequency",
        default=None,
    )
    if persistence is None:
        persistence = pose_count / denominator if denominator else 0.0
    return PersistentFeatureSummary(
        feature_id=str(
            _persistent_feature_value(
                value,
                "feature_id",
                "key",
                "identifier",
                default="",
            )
        ),
        level=str(_persistent_feature_value(value, "level", default="interaction")),
        pose_count=pose_count,
        denominator_pose_count=denominator,
        persistence=float(persistence),
        classification=str(
            _persistent_feature_value(
                value,
                "classification",
                "persistence_class",
                default="",
            )
        ),
        family=str(
            _persistent_feature_value(
                value,
                "interaction_family",
                "family",
                default="",
            )
        ),
        interaction_type=str(
            _persistent_feature_value(
                value,
                "interaction_type",
                "type",
                default="",
            )
        ),
        receptor_residue=receptor_residue,
        ligand_residue=ligand_residue,
        representative_pose_id=str(
            _persistent_feature_value(
                value,
                "representative_pose_id",
                "pose_id",
                default="",
            )
        ),
        metadata=metadata,
    )


def extract_persistent_feature_summaries(
    consensus_result: Any,
    *,
    scoring_module: Optional[ModuleType] = None,
) -> Tuple[PersistentFeatureSummary, ...]:
    """Extract and sort native persistent features from all consensus groups."""

    if consensus_result is None:
        return ()
    module = _require_scoring_module(scoring_module)
    rows_function = getattr(module, "consensus_persistence_to_rows", None)
    native_features: List[Any] = []
    groups = normalize_object_sequence(
        get_object_value(consensus_result, "groups", default=(), skip_none=True)
    )
    for group in groups:
        for level_result in normalize_object_sequence(
            get_object_value(group, "levels", default=(), skip_none=True)
        ):
            native_features.extend(
                normalize_object_sequence(
                    get_object_value(
                        level_result,
                        "features",
                        default=(),
                        aliases=("records", "persistent_features"),
                        skip_none=True,
                    )
                )
            )
        native_features.extend(
            normalize_object_sequence(
                get_object_value(
                    group,
                    "features",
                    default=(),
                    aliases=("records", "persistent_features"),
                    skip_none=True,
                )
            )
        )
    if not native_features and callable(rows_function):
        try:
            native_features.extend(rows_function(consensus_result))
        except Exception:
            pass
    summaries: List[PersistentFeatureSummary] = []
    seen: Set[Tuple[str, str]] = set()
    for value in native_features:
        summary = summarize_persistent_feature(value)
        key = (summary.level, summary.feature_id)
        if key in seen:
            continue
        seen.add(key)
        summaries.append(summary)
    summaries.sort(
        key=lambda item: (
            item.persistence,
            item.pose_count,
            item.level,
            item.feature_id,
        ),
        reverse=True,
    )
    return tuple(summaries)


# 21.6. Native advanced analysis
# -----------------------------------------------------------------------------


def run_consensus_persistence_analysis(
    pose_results: Sequence[Any],
    *,
    config: AdvancedMultiposeAnalysisConfig,
    ranking: Any = None,
    scoring_module: Optional[ModuleType] = None,
) -> Any:
    """Run native consensus and persistence analysis."""

    module = _require_scoring_module(scoring_module)
    options = build_native_consensus_persistence_options(
        config,
        scoring_module=module,
    )
    function = getattr(module, "build_consensus_persistence", None)
    if not callable(function):
        raise AnalysisDependencyError(
            "The scoring module does not expose build_consensus_persistence.",
            stage=STAGE_CONSENSUS,
        )
    return function(
        tuple(pose_results),
        ranking=ranking,
        options=options,
        metadata={
            "source": _MODULE_NAME,
            "schema": CONSENSUS_ANALYSIS_SCHEMA_NAME,
            "schema_version": CONSENSUS_ANALYSIS_SCHEMA_VERSION,
            "configuration_fingerprint": config.fingerprint,
        },
    )


def run_diversity_analysis(
    pose_results: Sequence[Any],
    *,
    config: AdvancedMultiposeAnalysisConfig,
    scoring_module: Optional[ModuleType] = None,
) -> Any:
    """Run native cross-pose diversity analysis."""

    module = _require_scoring_module(scoring_module)
    fingerprint_options = build_native_fingerprint_options(
        config,
        scoring_module=module,
    )
    diversity_options = build_native_diversity_options(
        config,
        fingerprint_options=fingerprint_options,
        scoring_module=module,
    )
    function = getattr(module, "compute_pose_diversity", None)
    if not callable(function):
        raise AnalysisDependencyError(
            "The scoring module does not expose compute_pose_diversity.",
            stage=STAGE_CONSENSUS,
        )
    return function(tuple(pose_results), options=diversity_options)


def run_complementarity_analysis(
    diversity_result: Any,
    *,
    config: AdvancedMultiposeAnalysisConfig,
    scoring_module: Optional[ModuleType] = None,
) -> Tuple[Any, Any, Any, Any]:
    """Build coverage, select a pose set and generate an explanation."""

    module = _require_scoring_module(scoring_module)
    coverage_options = build_native_coverage_options(
        config,
        scoring_module=module,
    )
    selection_options = build_native_selection_options(
        config,
        scoring_module=module,
    )
    profiles_builder = getattr(module, "build_pose_coverage_profiles", None)
    universe_builder = getattr(module, "build_coverage_universe", None)
    selector = getattr(module, "select_optimal_pose_set", None)
    if not all(callable(item) for item in (profiles_builder, universe_builder, selector)):
        raise AnalysisDependencyError(
            "The scoring module lacks the complete coverage-selection API.",
            stage=STAGE_CONSENSUS,
        )
    profiles = profiles_builder(diversity_result, options=coverage_options)
    universe = universe_builder(profiles, options=coverage_options)
    if config.optimize_pose_set:
        selection_result = selector(
            profiles,
            universe=universe,
            coverage_options=coverage_options,
            selection_options=selection_options,
            diversity_result=diversity_result,
        )
        complementarity_result = get_object_value(
            selection_result,
            "selected_coverage_result",
            default=None,
        )
    else:
        selection_result = None
        selected_ids = tuple(
            str(_advanced_exact_value(item, "pose_id", "") or "")
            for item in profiles
        )
        coverage_function = getattr(module, "compute_pose_set_coverage", None)
        if not callable(coverage_function):
            raise AnalysisDependencyError(
                "The scoring module does not expose compute_pose_set_coverage.",
                stage=STAGE_CONSENSUS,
            )
        complementarity_result = coverage_function(
            profiles,
            selected_pose_ids=selected_ids,
            universe=universe,
            options=coverage_options,
        )
    if complementarity_result is None:
        coverage_function = getattr(module, "compute_pose_set_coverage", None)
        if callable(coverage_function):
            complementarity_result = coverage_function(
                profiles,
                selected_pose_ids=(),
                universe=universe,
                options=coverage_options,
            )
    explanation = None
    if config.generate_explainability and selection_result is not None:
        explainer = getattr(module, "explain_pose_set_selection", None)
        if callable(explainer):
            explanation = explainer(
                selection_result,
                options=build_native_complementarity_explainability_options(
                    config,
                    scoring_module=module,
                ),
            )
    return complementarity_result, selection_result, explanation, universe


def run_consensus_explainability(
    consensus_result: Any,
    *,
    config: AdvancedMultiposeAnalysisConfig,
    scoring_module: Optional[ModuleType] = None,
) -> Any:
    """Generate native consensus explainability when supported."""

    if consensus_result is None or not config.generate_explainability:
        return None
    module = _require_scoring_module(scoring_module)
    function = getattr(module, "explain_consensus_persistence", None)
    if not callable(function):
        return None
    return function(
        consensus_result,
        options=build_native_consensus_explainability_options(
            config,
            scoring_module=module,
        ),
    )


# 21.7. Summaries and status derivation
# -----------------------------------------------------------------------------


def _advanced_finite(value: Any) -> Optional[float]:
    """Return one finite float or None."""

    if value is None:
        return None
    try:
        normalized = float(value)
    except (TypeError, ValueError):
        return None
    return normalized if math.isfinite(normalized) else None


def _advanced_summary_value(source: Any, name: str) -> Any:
    """Read a value from a result or its nested summary."""

    value = get_object_value(source, name, default=None, skip_none=True)
    if value is not None:
        return value
    nested = get_object_value(source, "summary", default=None, skip_none=True)
    return get_object_value(nested, name, default=None, skip_none=True)


def derive_advanced_multipose_status(
    component_statuses: Mapping[str, str],
    *,
    errors: Sequence[str],
    allow_degenerate: bool,
) -> str:
    """Derive one aggregate advanced multipose status."""

    statuses = {str(value).strip().lower() for value in component_statuses.values()}
    if not statuses:
        return CONSENSUS_STATUS_SKIPPED
    if errors and not any(
        value in {CONSENSUS_STATUS_COMPLETE, CONSENSUS_STATUS_DEGENERATE}
        for value in statuses
    ):
        return CONSENSUS_STATUS_FAILED
    if CONSENSUS_STATUS_FAILED in statuses or errors:
        return CONSENSUS_STATUS_PARTIAL
    if statuses == {CONSENSUS_STATUS_SKIPPED}:
        return CONSENSUS_STATUS_SKIPPED
    if CONSENSUS_STATUS_DEGENERATE in statuses:
        return (
            CONSENSUS_STATUS_DEGENERATE
            if allow_degenerate
            else CONSENSUS_STATUS_PARTIAL
        )
    if CONSENSUS_STATUS_PARTIAL in statuses:
        return CONSENSUS_STATUS_PARTIAL
    return CONSENSUS_STATUS_COMPLETE


def build_advanced_multipose_summary(
    *,
    pose_count: int,
    scored_pose_count: int,
    consensus_result: Any,
    diversity_result: Any,
    complementarity_result: Any,
    selection_result: Any,
    persistent_features: Sequence[PersistentFeatureSummary],
    component_statuses: Mapping[str, str],
    attached_dock_model_count: int,
    warnings: Sequence[str],
    errors: Sequence[str],
    allow_degenerate: bool,
) -> AdvancedMultiposeSummary:
    """Build the compact advanced multipose summary."""

    consensus_features = sum(
        item.persistence >= CONSENSUS_ANALYSIS_DEFAULT_THRESHOLD
        for item in persistent_features
    )
    core_features = sum(
        item.persistence >= CONSENSUS_ANALYSIS_DEFAULT_CORE_THRESHOLD
        for item in persistent_features
    )
    ubiquitous_features = sum(
        math.isclose(item.persistence, 1.0, abs_tol=1e-12)
        for item in persistent_features
    )
    mean_similarity = _advanced_finite(
        _advanced_summary_value(diversity_result, "mean_similarity")
    )
    mean_diversity = _advanced_finite(
        _advanced_summary_value(diversity_result, "mean_distance")
    )
    representative_ids = tuple(
        str(item)
        for item in normalize_object_sequence(
            _advanced_summary_value(diversity_result, "representative_pose_ids")
        )
    )
    selected_ids = tuple(
        str(item)
        for item in normalize_object_sequence(
            get_object_value(
                selection_result,
                "selected_pose_ids",
                default=get_object_value(
                    complementarity_result,
                    "selected_pose_ids",
                    default=(),
                ),
            )
        )
    )
    status = derive_advanced_multipose_status(
        component_statuses,
        errors=errors,
        allow_degenerate=allow_degenerate,
    )
    return AdvancedMultiposeSummary(
        status=status,
        pose_count=pose_count,
        scored_pose_count=scored_pose_count,
        persistent_feature_count=len(persistent_features),
        consensus_feature_count=consensus_features,
        core_feature_count=core_features,
        ubiquitous_feature_count=ubiquitous_features,
        mean_similarity=mean_similarity,
        mean_diversity=mean_diversity,
        unique_fingerprint_count=int(
            _advanced_summary_value(diversity_result, "unique_fingerprint_count")
            or 0
        ),
        representative_pose_ids=representative_ids,
        selected_pose_ids=selected_ids,
        weighted_coverage_fraction=_advanced_finite(
            _advanced_summary_value(
                complementarity_result,
                "weighted_coverage_fraction",
            )
        ),
        residue_coverage_fraction=_advanced_finite(
            _advanced_summary_value(
                complementarity_result,
                "residue_coverage_fraction",
            )
        ),
        family_coverage_fraction=_advanced_finite(
            _advanced_summary_value(
                complementarity_result,
                "family_coverage_fraction",
            )
        ),
        type_coverage_fraction=_advanced_finite(
            _advanced_summary_value(
                complementarity_result,
                "type_coverage_fraction",
            )
        ),
        hotspot_coverage_fraction=_advanced_finite(
            _advanced_summary_value(
                complementarity_result,
                "hotspot_coverage_fraction",
            )
        ),
        target_reached=bool(
            get_object_value(selection_result, "target_reached", default=False)
        ),
        optimality_guaranteed=bool(
            get_object_value(
                selection_result,
                "optimality_guaranteed",
                default=False,
            )
        ),
        attached_dock_model_count=attached_dock_model_count,
        warning_count=len(warnings),
        error_count=len(errors),
    )


# 21.8. DockModel attachment
# -----------------------------------------------------------------------------


def _advanced_pose_metric_mapping(diversity_result: Any) -> Dict[str, Dict[str, Any]]:
    """Return diversity metrics indexed by pose identifier."""

    result: Dict[str, Dict[str, Any]] = {}
    for value in normalize_object_sequence(
        get_object_value(diversity_result, "pose_scores", default=(), skip_none=True)
    ):
        pose_id = str(_advanced_exact_value(value, "pose_id", "") or "").strip()
        if not pose_id:
            continue
        result[pose_id] = {
            "mean_similarity": _advanced_finite(
                get_object_value(value, "mean_similarity", default=None)
            ),
            "mean_distance": _advanced_finite(
                get_object_value(value, "mean_distance", default=None)
            ),
            "diversity_rank": get_object_value(
                value,
                "diversity_rank",
                default=None,
            ),
            "representative": bool(
                get_object_value(value, "representative", default=False)
            ),
            "representative_order": get_object_value(
                value,
                "representative_order",
                default=None,
            ),
        }
    return result


def attach_advanced_multipose_results(
    dock_models: Iterable[Any],
    output: AdvancedMultiposeAnalysisOutput,
    *,
    pose_results: Optional[Sequence[PoseAnalysisResult]] = None,
    scoring_module: Optional[ModuleType] = None,
) -> Mapping[str, Any]:
    """Attach consensus, persistence and selection metadata to DockModels."""

    models = tuple(normalize_object_sequence(dock_models))
    module = _require_scoring_module(scoring_module)
    consensus_attachment: Mapping[str, Any] = {}
    if output.consensus_result is not None:
        native_attach = getattr(module, "attach_consensus_to_dock_models", None)
        if callable(native_attach):
            try:
                native_options = None
                if output.configuration.attachment_options:
                    factory = getattr(module, "DockModelScoringIntegrationOptions", None)
                    if callable(factory):
                        native_options = _construct_scoring_native_object(
                            factory,
                            dict(output.configuration.attachment_options),
                            field_name="DockModelScoringIntegrationOptions",
                        )
                consensus_attachment = native_attach(
                    models,
                    output.consensus_result,
                    options=native_options,
                    strict=False,
                )
            except Exception as exc:
                consensus_attachment = {"native_attachment_error": str(exc)}
    metric_by_pose = _advanced_pose_metric_mapping(output.diversity_result)
    selected = set(output.selected_pose_ids)
    representative = set(output.representative_pose_ids)
    pose_id_by_model: Dict[int, str] = {}
    if pose_results:
        for item in pose_results:
            if item.dock_model is not None:
                pose_id_by_model[id(item.dock_model)] = item.pose_id
    attached = 0
    for index, model in enumerate(models):
        pose_id = pose_id_by_model.get(id(model))
        if not pose_id:
            pose_id = str(
                _advanced_exact_value(
                    model,
                    "pose_id",
                    _advanced_exact_value(model, "name", f"pose_{index + 1}"),
                )
            )
        metrics = metric_by_pose.get(pose_id, {})
        metadata = normalize_metadata_mapping(
            get_object_value(model, DOCK_MODEL_FIELD_METADATA, default={}),
            copy_values=True,
        )
        metadata[CONSENSUS_ANALYSIS_DOCK_MODEL_KEY] = {
            "schema": output.schema_name,
            "schema_version": output.schema_version,
            "configuration_fingerprint": output.configuration.fingerprint,
            "status": output.summary.status,
            "pose_id": pose_id,
            "selected": pose_id in selected,
            "representative": pose_id in representative,
            "diversity": metrics,
            "summary": output.summary.to_dict(),
        }
        set_object_value(
            model,
            DOCK_MODEL_FIELD_METADATA,
            metadata,
            strict=False,
        )
        statistics = normalize_statistics_mapping(
            get_object_value(model, DOCK_MODEL_FIELD_STATISTICS, default={}),
            copy_values=True,
        )
        statistics.update(
            {
                "consensus_selected": pose_id in selected,
                "consensus_representative": pose_id in representative,
                "consensus_feature_count": output.summary.consensus_feature_count,
                "core_feature_count": output.summary.core_feature_count,
                "weighted_coverage_fraction": (
                    output.summary.weighted_coverage_fraction
                ),
                **metrics,
            }
        )
        set_object_value(
            model,
            DOCK_MODEL_FIELD_STATISTICS,
            statistics,
            strict=False,
        )
        attached += 1
    return {
        "attached_dock_model_count": attached,
        "native_consensus_attachment": to_json_compatible(consensus_attachment),
    }


# 21.9. Main advanced multipose API
# -----------------------------------------------------------------------------


def analyze_consensus_diversity_complementarity(
    source: Any,
    *,
    config: AdvancedMultiposeAnalysisConfigLike = None,
    analysis_config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
    ranking: Any = None,
    dock_models: Optional[Iterable[Any]] = None,
    pose_analysis_results: Optional[Sequence[PoseAnalysisResult]] = None,
    native_scoring_output: Optional[ScoringMultiposeOutput] = None,
    scoring_module: Optional[ModuleType] = None,
) -> AdvancedMultiposeAnalysisOutput:
    """Run consensus, persistence, diversity and complementarity analysis."""

    module = _require_scoring_module(scoring_module)
    effective = resolve_advanced_multipose_config(
        config,
        analysis_config=analysis_config,
        overrides=overrides,
    )
    pose_results = resolve_advanced_pose_scoring_results(
        source,
        native_scoring_output=native_scoring_output,
    )
    if len(pose_results) > effective.maximum_pose_count:
        raise AnalysisInputError(
            "Advanced multipose analysis exceeds the configured pose limit.",
            stage=STAGE_CONSENSUS,
            details={
                "pose_count": len(pose_results),
                "maximum_pose_count": effective.maximum_pose_count,
            },
        )
    if effective.require_multiple_poses and len(pose_results) < effective.minimum_pose_count:
        raise AnalysisInputError(
            "Advanced multipose analysis requires multiple scored poses.",
            stage=STAGE_CONSENSUS,
            details={
                "pose_count": len(pose_results),
                "minimum_pose_count": effective.minimum_pose_count,
            },
        )
    component_statuses: Dict[str, str] = {}
    warnings_list: List[str] = []
    errors_list: List[str] = []
    consensus_result = None
    diversity_result = None
    complementarity_result = None
    selection_result = None
    complementarity_explanation = None
    consensus_explanation = None
    persistent_features: Tuple[PersistentFeatureSummary, ...] = ()
    attachment_result: Mapping[str, Any] = {}

    def _capture_failure(component: str, exc: BaseException) -> None:
        component_statuses[component] = CONSENSUS_STATUS_FAILED
        errors_list.append(f"{component}: {exc}")
        if not effective.continue_on_error:
            raise AnalysisConsensusError(
                f"Advanced multipose {component} analysis failed.",
                stage=STAGE_CONSENSUS,
                cause=exc,
            ) from exc

    if effective.calculate_persistence:
        try:
            consensus_result = run_consensus_persistence_analysis(
                pose_results,
                config=effective,
                ranking=ranking,
                scoring_module=module,
            )
            component_statuses[CONSENSUS_COMPONENT_PERSISTENCE] = str(
                get_object_value(
                    consensus_result,
                    "status",
                    default=CONSENSUS_STATUS_COMPLETE,
                )
            ).lower()
            persistent_features = extract_persistent_feature_summaries(
                consensus_result,
                scoring_module=module,
            )
            consensus_explanation = run_consensus_explainability(
                consensus_result,
                config=effective,
                scoring_module=module,
            )
        except Exception as exc:
            _capture_failure(CONSENSUS_COMPONENT_PERSISTENCE, exc)
    else:
        component_statuses[CONSENSUS_COMPONENT_PERSISTENCE] = CONSENSUS_STATUS_SKIPPED

    if effective.calculate_diversity:
        try:
            diversity_result = run_diversity_analysis(
                pose_results,
                config=effective,
                scoring_module=module,
            )
            component_statuses[CONSENSUS_COMPONENT_DIVERSITY] = str(
                get_object_value(
                    diversity_result,
                    "status",
                    default=CONSENSUS_STATUS_COMPLETE,
                )
            ).lower()
        except Exception as exc:
            _capture_failure(CONSENSUS_COMPONENT_DIVERSITY, exc)
    else:
        component_statuses[CONSENSUS_COMPONENT_DIVERSITY] = CONSENSUS_STATUS_SKIPPED

    if effective.calculate_complementarity and diversity_result is not None:
        try:
            (
                complementarity_result,
                selection_result,
                complementarity_explanation,
                _,
            ) = run_complementarity_analysis(
                diversity_result,
                config=effective,
                scoring_module=module,
            )
            component_statuses[CONSENSUS_COMPONENT_COMPLEMENTARITY] = str(
                get_object_value(
                    complementarity_result,
                    "status",
                    default=CONSENSUS_STATUS_COMPLETE,
                )
            ).lower()
            component_statuses[CONSENSUS_COMPONENT_SELECTION] = (
                str(
                    get_object_value(
                        selection_result,
                        "status",
                        default=CONSENSUS_STATUS_SKIPPED,
                    )
                ).lower()
                if selection_result is not None
                else CONSENSUS_STATUS_SKIPPED
            )
        except Exception as exc:
            _capture_failure(CONSENSUS_COMPONENT_COMPLEMENTARITY, exc)
    else:
        component_statuses[CONSENSUS_COMPONENT_COMPLEMENTARITY] = (
            CONSENSUS_STATUS_SKIPPED
        )
        component_statuses[CONSENSUS_COMPONENT_SELECTION] = CONSENSUS_STATUS_SKIPPED

    provisional = build_advanced_multipose_summary(
        pose_count=len(pose_results),
        scored_pose_count=len(pose_results),
        consensus_result=consensus_result,
        diversity_result=diversity_result,
        complementarity_result=complementarity_result,
        selection_result=selection_result,
        persistent_features=persistent_features,
        component_statuses=component_statuses,
        attached_dock_model_count=0,
        warnings=warnings_list,
        errors=errors_list,
        allow_degenerate=effective.allow_degenerate_results,
    )
    output = AdvancedMultiposeAnalysisOutput(
        pose_results=pose_results,
        consensus_result=consensus_result,
        diversity_result=diversity_result,
        complementarity_result=complementarity_result,
        selection_result=selection_result,
        complementarity_explanation=complementarity_explanation,
        consensus_explanation=consensus_explanation,
        persistent_features=persistent_features,
        summary=provisional,
        component_statuses=component_statuses,
        attachment_result={},
        warnings=tuple(warnings_list),
        errors=tuple(errors_list),
        metadata={
            "pose_count": len(pose_results),
            "enabled_components": list(effective.enabled_components),
            "configuration_fingerprint": effective.fingerprint,
        },
        configuration=effective,
        module_version=getattr(module, "__version__", None),
    )
    resolved_models = tuple(normalize_object_sequence(dock_models))
    if not resolved_models and pose_analysis_results:
        resolved_models = tuple(
            item.dock_model
            for item in pose_analysis_results
            if item.dock_model is not None
        )
    if effective.attach_results and resolved_models:
        try:
            attachment_result = attach_advanced_multipose_results(
                resolved_models,
                output,
                pose_results=pose_analysis_results,
                scoring_module=module,
            )
            component_statuses[CONSENSUS_COMPONENT_ATTACHMENT] = (
                CONSENSUS_STATUS_COMPLETE
            )
        except Exception as exc:
            component_statuses[CONSENSUS_COMPONENT_ATTACHMENT] = CONSENSUS_STATUS_FAILED
            warnings_list.append(f"attachment: {exc}")
    else:
        component_statuses[CONSENSUS_COMPONENT_ATTACHMENT] = CONSENSUS_STATUS_SKIPPED
    final_summary = build_advanced_multipose_summary(
        pose_count=len(pose_results),
        scored_pose_count=len(pose_results),
        consensus_result=consensus_result,
        diversity_result=diversity_result,
        complementarity_result=complementarity_result,
        selection_result=selection_result,
        persistent_features=persistent_features,
        component_statuses=component_statuses,
        attached_dock_model_count=int(
            attachment_result.get("attached_dock_model_count", 0)
        ),
        warnings=warnings_list,
        errors=errors_list,
        allow_degenerate=effective.allow_degenerate_results,
    )
    return replace(
        output,
        summary=final_summary,
        component_statuses=component_statuses,
        attachment_result=attachment_result,
        warnings=tuple(warnings_list),
        errors=tuple(errors_list),
    )


# 21.10. Context and multipose-orchestration integration
# -----------------------------------------------------------------------------


def _record_advanced_consensus_context(
    context: AnalysisContext,
    stage_result: AnalysisStageResult,
) -> None:
    """Store advanced multipose outputs in the shared runtime context."""

    context.set_stage_data(STAGE_CONSENSUS, stage_result)
    if not isinstance(stage_result.value, AdvancedMultiposeAnalysisOutput):
        return
    output = stage_result.value
    context.set_shared(CONSENSUS_ANALYSIS_OUTPUT_KEY, output)
    context.set_shared(CONSENSUS_ANALYSIS_SUMMARY_KEY, output.summary)
    context.statistics[CONSENSUS_ANALYSIS_STATISTICS_KEY] = output.summary.to_dict()
    context.metadata[CONSENSUS_ANALYSIS_METADATA_KEY] = {
        "schema": output.schema_name,
        "schema_version": output.schema_version,
        "configuration_fingerprint": output.configuration.fingerprint,
        "component_statuses": dict(output.component_statuses),
        "selected_pose_ids": list(output.selected_pose_ids),
        "representative_pose_ids": list(output.representative_pose_ids),
    }


def execute_advanced_consensus_stage(
    context: AnalysisContext,
    *,
    source: Any = None,
    multipose_output: Optional[MultiposeAnalysisOutput] = None,
    multipose_result: Optional[MultiPoseAnalysisResult] = None,
    native_scoring_output: Optional[ScoringMultiposeOutput] = None,
    config: AdvancedMultiposeAnalysisConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    scoring_module: Optional[ModuleType] = None,
    raise_on_error: Optional[bool] = None,
) -> AnalysisStageResult:
    """Execute the registered advanced consensus stage."""

    if not isinstance(context, AnalysisContext):
        raise TypeError("context must be an AnalysisContext instance.")
    stage_result = AnalysisStageResult(stage=STAGE_CONSENSUS, required=False)
    context.set_current_stage(STAGE_CONSENSUS)
    stage_result.start()
    try:
        resolved_output = multipose_output or context.get_shared(MULTIPOSE_OUTPUT_KEY)
        resolved_result = multipose_result or context.get_shared(MULTIPOSE_RESULT_KEY)
        resolved_native = (
            native_scoring_output
            or context.get_shared(MULTIPOSE_SCORING_OUTPUT_KEY)
        )
        resolved_source = source or resolved_output or resolved_result or context
        pose_analysis_results = None
        dock_models = tuple(context.dock_models)
        ranking = None
        if isinstance(resolved_output, MultiposeAnalysisOutput):
            pose_analysis_results = resolved_output.pose_results
            dock_models = tuple(
                item.dock_model
                for item in resolved_output.pose_results
                if item.dock_model is not None
            )
            ranking = resolved_output.multipose_result.ranking
        elif isinstance(resolved_result, MultiPoseAnalysisResult):
            pose_analysis_results = tuple(resolved_result.pose_results)
            ranking = resolved_result.ranking
        output = analyze_consensus_diversity_complementarity(
            resolved_source,
            config=config,
            analysis_config=context.config,
            overrides=overrides,
            ranking=ranking,
            dock_models=dock_models,
            pose_analysis_results=pose_analysis_results,
            native_scoring_output=(
                resolved_native
                if isinstance(resolved_native, ScoringMultiposeOutput)
                else None
            ),
            scoring_module=scoring_module,
        )
        stage_result.statistics = output.summary.to_dict()
        stage_result.output_summary = output.summary.to_dict()
        stage_result.succeed(
            output,
            message=(
                "Advanced consensus, persistence, diversity and "
                "complementarity analysis completed successfully."
            ),
        )
    except Exception as exc:
        wrapped = exc if isinstance(exc, AnalysisError) else AnalysisConsensusError(
            "Advanced multipose comparison failed.",
            stage=STAGE_CONSENSUS,
            cause=exc,
        )
        stage_result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
        should_raise = (
            bool(raise_on_error)
            if raise_on_error is not None
            else context.config.runtime.failure_policy == FAILURE_POLICY_STRICT
        )
        if should_raise:
            raise wrapped from exc
    finally:
        _record_advanced_consensus_context(context, stage_result)
        context.set_current_stage(None)
    return stage_result


def execute_multipose_consensus_stage(
    context: AnalysisContext,
    result: MultiPoseAnalysisResult,
    *,
    options: MultiposeExecutionOptions,
    native_scoring: Optional[ScoringMultiposeOutput] = None,
) -> AnalysisStageResult:
    """Run advanced multipose comparison with preliminary fallback."""

    if not context.config.enable_consensus and not options.build_consensus:
        stage_result = AnalysisStageResult(stage=STAGE_CONSENSUS, required=False)
        return stage_result.skip("Multipose consensus is disabled.")
    source: Any = native_scoring if native_scoring is not None else result
    try:
        stage_result = execute_advanced_consensus_stage(
            context,
            source=source,
            multipose_result=result,
            native_scoring_output=native_scoring,
            overrides=dict(options.consensus_options) or None,
            raise_on_error=False,
        )
        if stage_result.succeeded and isinstance(
            stage_result.value,
            AdvancedMultiposeAnalysisOutput,
        ):
            output = stage_result.value
            ranking = build_multipose_ranking(
                result.pose_results,
                include_failed=options.include_failed_in_ranking,
            ) if options.build_ranking else []
            result.ranking = ranking
            result.consensus = output
            attached_count = 0
            if options.attach_global_results:
                attached_count = attach_multipose_global_results(
                    result,
                    ranking=ranking,
                    consensus=output.summary.to_dict(),
                    native_scoring=native_scoring,
                )
            stage_result.statistics.setdefault(
                "multipose_metadata_attachment_count",
                attached_count,
            )
            stage_result.output_summary.update(
                {
                    "ranking_generated": bool(ranking),
                    "consensus_generated": True,
                    "native_scoring_used": native_scoring is not None,
                    "advanced_analysis": True,
                }
            )
            return stage_result
    except Exception as exc:
        if context.config.runtime.failure_policy == FAILURE_POLICY_STRICT:
            raise
        context.metadata.setdefault(CONSENSUS_ANALYSIS_METADATA_KEY, {})[
            "advanced_fallback_error"
        ] = str(exc)
    return _execute_preliminary_multipose_consensus_stage(
        context,
        result,
        options=options,
        native_scoring=native_scoring,
    )


# 21.11. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_advanced_multipose_output(
    value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate one advanced multipose analysis output."""

    errors: List[str] = []
    if not isinstance(value, AdvancedMultiposeAnalysisOutput):
        errors.append("Value is not an AdvancedMultiposeAnalysisOutput.")
    else:
        if value.summary.pose_count != len(value.pose_results):
            errors.append("Advanced multipose pose count is inconsistent.")
        if value.summary.scored_pose_count > value.summary.pose_count:
            errors.append("Scored pose count cannot exceed total pose count.")
        if len(value.configuration.fingerprint) != 64:
            errors.append("Advanced multipose configuration fingerprint is invalid.")
        if value.summary.selected_pose_ids and value.selection_result is None:
            errors.append("Selected pose identifiers require a selection result.")
        if value.summary.weighted_coverage_fraction is not None and not (
            0.0 <= value.summary.weighted_coverage_fraction <= 1.0
        ):
            errors.append("Weighted coverage fraction is outside zero to one.")
        for feature in value.persistent_features:
            if not 0.0 <= feature.persistence <= 1.0:
                errors.append(
                    f"Persistent feature {feature.feature_id!r} has invalid persistence."
                )
    result = tuple(errors)
    if result and raise_on_error:
        raise AnalysisValidationError(
            "Advanced multipose output validation failed.",
            stage=STAGE_CONSENSUS,
            details={"errors": list(result)},
        )
    return result


def summarize_advanced_multipose_analysis(value: Any) -> Dict[str, Any]:
    """Return a compact advanced multipose summary."""

    if isinstance(value, AnalysisStageResult):
        if isinstance(value.value, AdvancedMultiposeAnalysisOutput):
            result = value.value.summary.to_dict()
        else:
            result = {}
        result.update(
            {
                "stage": value.stage,
                "stage_status": value.status.value,
                "duration_seconds": value.duration_seconds,
            }
        )
        return result
    if isinstance(value, AdvancedMultiposeAnalysisOutput):
        result = value.summary.to_dict()
        result.update(
            {
                "component_statuses": dict(value.component_statuses),
                "configuration_fingerprint": value.configuration.fingerprint,
                "schema": value.schema_name,
                "schema_version": value.schema_version,
            }
        )
        return result
    raise TypeError(
        "value must be an AnalysisStageResult or "
        "AdvancedMultiposeAnalysisOutput."
    )


def advanced_multipose_analysis_to_json(
    value: AdvancedMultiposeAnalysisOutput,
    *,
    include_results: bool = False,
    indent: Optional[int] = 2,
    sort_keys: bool = True,
) -> str:
    """Serialize one advanced multipose output as JSON."""

    validate_advanced_multipose_output(value, raise_on_error=True)
    return json.dumps(
        value.to_dict(include_results=include_results),
        indent=indent,
        sort_keys=sort_keys,
        ensure_ascii=False,
    )


# 21.12. Registry integration
# -----------------------------------------------------------------------------


def advanced_consensus_stage_result_adapter(
    value: Any,
    **kwargs: Any,
) -> AdvancedMultiposeAnalysisOutput:
    """Registry-compatible adapter for advanced multipose comparison."""

    if isinstance(value, AdvancedMultiposeAnalysisOutput):
        return value
    return analyze_consensus_diversity_complementarity(value, **kwargs)


def advanced_consensus_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible validator for advanced consensus outputs."""

    if isinstance(value, AnalysisStageResult):
        if value.value is None:
            return () if value.status == StageStatus.SKIPPED else (
                "Consensus stage result does not contain a value.",
            )
        value = value.value
    return validate_advanced_multipose_output(value)


def register_advanced_consensus_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the advanced consensus executor, adapter and validator."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_CONSENSUS)
    metadata = dict(definition.metadata)
    metadata.update(
        {
            "schema": CONSENSUS_ANALYSIS_SCHEMA_NAME,
            "schema_version": CONSENSUS_ANALYSIS_SCHEMA_VERSION,
            "result_type": CONSENSUS_ANALYSIS_RESULT_TYPE,
            "supports_persistence": True,
            "supports_diversity": True,
            "supports_complementarity": True,
            "supports_optimal_pose_selection": True,
            "supports_explainability": True,
            "supports_dock_model_attachment": True,
        }
    )
    updated = replace(
        definition,
        executor=execute_advanced_consensus_stage,
        result_adapter=advanced_consensus_stage_result_adapter,
        validator=advanced_consensus_stage_validator,
        metadata=metadata,
    )
    target_registry.replace(updated)
    return updated


def advanced_consensus_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the advanced consensus stage adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_CONSENSUS)
    return bool(
        definition is not None
        and definition.executor is execute_advanced_consensus_stage
        and definition.result_adapter is advanced_consensus_stage_result_adapter
        and definition.validator is advanced_consensus_stage_validator
    )


# 21.13. Convention validation
# -----------------------------------------------------------------------------


def validate_advanced_multipose_conventions() -> Dict[str, Any]:
    """Validate advanced configuration, native analysis and registration."""

    failures: List[str] = []
    module = _require_scoring_module()
    config = AdvancedMultiposeAnalysisConfig(
        attach_results=False,
        representative_pose_count=2,
        maximum_selected_poses=2,
    )
    if len(config.fingerprint) != 64:
        failures.append("Advanced multipose configuration fingerprint is invalid.")
    if config.enabled_components[:2] != (
        CONSENSUS_COMPONENT_PERSISTENCE,
        CONSENSUS_COMPONENT_DIVERSITY,
    ):
        failures.append("Advanced multipose component ordering is invalid.")
    create_score = getattr(module, "create_interaction_score", None)
    calculate_pose = getattr(module, "calculate_total_pose_score", None)
    if not callable(create_score) or not callable(calculate_pose):
        failures.append("Scoring test helpers are unavailable.")
        pose_results: Tuple[Any, ...] = ()
    else:
        patterns = (
            (
                ("hydrogen_bond", "A:ASP:10", "L:LIG:1", 2.0),
                ("hydrophobic", "A:LEU:20", "L:LIG:1", 1.0),
            ),
            (
                ("hydrogen_bond", "A:ASP:10", "L:LIG:1", 1.8),
                ("pi_stacking", "A:PHE:30", "L:LIG:1", 2.0),
            ),
            (
                ("salt_bridge", "A:GLU:40", "L:LIG:1", 3.0),
                ("hydrophobic", "A:LEU:20", "L:LIG:1", 1.0),
            ),
        )
        generated: List[Any] = []
        for pose_index, interactions in enumerate(patterns, start=1):
            scores: List[Any] = []
            for interaction_index, (
                interaction_type,
                receptor_residue,
                ligand_residue,
                weight,
            ) in enumerate(interactions, start=1):
                scores.append(
                    create_score(
                        interaction_id=(
                            f"section21_pose_{pose_index}_interaction_"
                            f"{interaction_index}"
                        ),
                        interaction_type=interaction_type,
                        base_weight=weight,
                        strength="strong",
                        classification="favorable",
                        geometry_quality="optimal",
                        residue_pair=(receptor_residue, ligand_residue),
                        pose_id=f"section21_pose_{pose_index}",
                        model_id="section21_model",
                    )
                )
            generated.append(
                calculate_pose(
                    scores,
                    pose_id=f"section21_pose_{pose_index}",
                    model_id="section21_model",
                    ligand_id="section21_ligand",
                )
            )
        pose_results = tuple(generated)
    if pose_results:
        output = analyze_consensus_diversity_complementarity(
            pose_results,
            config=config,
            scoring_module=module,
        )
        validation_errors = validate_advanced_multipose_output(output)
        failures.extend(validation_errors)
        if output.summary.pose_count != 3:
            failures.append("Advanced analysis pose count is invalid.")
        if output.diversity_result is None:
            failures.append("Diversity analysis did not produce a result.")
        if output.selection_result is None:
            failures.append("Pose-set selection did not produce a result.")
        if not output.selected_pose_ids:
            failures.append("Pose-set selection returned no poses.")
        if output.summary.weighted_coverage_fraction is None:
            failures.append("Complementarity coverage was not summarized.")
        if output.consensus_result is None:
            failures.append("Consensus persistence did not produce a result.")
        if not output.persistent_features:
            failures.append("Persistent features were not extracted.")
        serialized = advanced_multipose_analysis_to_json(output)
        if CONSENSUS_ANALYSIS_SCHEMA_NAME not in serialized:
            failures.append("Advanced multipose JSON omitted the schema name.")
    register_advanced_consensus_stage_adapter()
    if not advanced_consensus_stage_adapter_registered():
        failures.append("Advanced consensus stage adapter was not registered.")
    if failures:
        raise RuntimeError(
            "Advanced multipose convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": CONSENSUS_ANALYSIS_SCHEMA_NAME,
        "schema_version": CONSENSUS_ANALYSIS_SCHEMA_VERSION,
        "validated_cases": 24,
        "pose_count": len(pose_results),
    }


