# 22.2. State and cache status enums
# -----------------------------------------------------------------------------


class DockModelStateStatus(str, Enum):
    """Current validity state of attached analysis data."""

    EMPTY = "empty"
    CURRENT = "current"
    PARTIAL = "partial"
    STALE = "stale"
    INVALID = "invalid"


class DockModelCacheLookupStatus(str, Enum):
    """Outcome of a stage-cache lookup."""

    HIT = "hit"
    MISS = "miss"
    STALE = "stale"
    INVALID = "invalid"
    DISABLED = "disabled"


class DockModelAttachmentAction(str, Enum):
    """Mutation action applied to one DockModel field."""

    CREATED = "created"
    REPLACED = "replaced"
    MERGED = "merged"
    PRESERVED = "preserved"
    REMOVED = "removed"
    SKIPPED = "skipped"


_DOCK_MODEL_STATE_STATUS_ALIASES: Final[Mapping[str, DockModelStateStatus]] = (
    MappingProxyType(
        {
            "empty": DockModelStateStatus.EMPTY,
            "none": DockModelStateStatus.EMPTY,
            "current": DockModelStateStatus.CURRENT,
            "valid": DockModelStateStatus.CURRENT,
            "fresh": DockModelStateStatus.CURRENT,
            "partial": DockModelStateStatus.PARTIAL,
            "incomplete": DockModelStateStatus.PARTIAL,
            "stale": DockModelStateStatus.STALE,
            "outdated": DockModelStateStatus.STALE,
            "invalid": DockModelStateStatus.INVALID,
            "corrupt": DockModelStateStatus.INVALID,
        }
    )
)


def canonicalize_dock_model_state_status(value: Any) -> DockModelStateStatus:
    """Return a canonical DockModel state status."""

    if isinstance(value, DockModelStateStatus):
        return value
    token = _normalize_status_token(value, field_name="DockModel state status")
    status = _DOCK_MODEL_STATE_STATUS_ALIASES.get(token)
    if status is None:
        supported = ", ".join(item.value for item in DockModelStateStatus)
        raise ValueError(
            f"Unknown DockModel state status {value!r}. Supported values: "
            f"{supported}."
        )
    return status


def canonicalize_dock_model_cache_lookup_status(
    value: Any,
) -> DockModelCacheLookupStatus:
    """Return a canonical DockModel cache lookup status."""

    if isinstance(value, DockModelCacheLookupStatus):
        return value
    token = _normalize_status_token(value, field_name="cache lookup status")
    try:
        return DockModelCacheLookupStatus(token)
    except ValueError as exc:
        supported = ", ".join(item.value for item in DockModelCacheLookupStatus)
        raise ValueError(
            f"Unknown cache lookup status {value!r}. Supported values: "
            f"{supported}."
        ) from exc


