@dataclass(frozen=True)
class DockModelStateConfig:
    """Configuration for unified DockModel mutation and cache behavior."""

    attachment_policy: str = DEFAULT_ATTACHMENT_POLICY
    copy_values: bool = False
    preserve_history: bool = True
    max_history_entries: int = DEFAULT_DOCK_MODEL_HISTORY_LIMIT
    max_attachment_records: int = DEFAULT_DOCK_MODEL_ATTACHMENT_LIMIT
    cache_enabled: bool = True
    max_cache_entries: int = DEFAULT_DOCK_MODEL_CACHE_LIMIT
    cache_ttl_seconds: Optional[float] = DEFAULT_DOCK_MODEL_CACHE_TTL_SECONDS
    store_full_result: bool = True
    store_stage_results: bool = True
    store_diagnostics: bool = True
    store_files: bool = True
    stale_on_input_change: bool = True
    stale_on_config_change: bool = True
    stale_on_pipeline_change: bool = True
    cache_failed_results: bool = False

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "attachment_policy",
            canonicalize_attachment_policy(self.attachment_policy),
        )
        object.__setattr__(self, "copy_values", bool(self.copy_values))
        object.__setattr__(self, "preserve_history", bool(self.preserve_history))
        object.__setattr__(
            self,
            "max_history_entries",
            min(
                MAX_DOCK_MODEL_HISTORY_LIMIT,
                max(0, int(self.max_history_entries)),
            ),
        )
        object.__setattr__(
            self,
            "max_attachment_records",
            min(
                MAX_DOCK_MODEL_ATTACHMENT_LIMIT,
                max(0, int(self.max_attachment_records)),
            ),
        )
        object.__setattr__(self, "cache_enabled", bool(self.cache_enabled))
        object.__setattr__(
            self,
            "max_cache_entries",
            min(MAX_DOCK_MODEL_CACHE_LIMIT, max(0, int(self.max_cache_entries))),
        )
        ttl = self.cache_ttl_seconds
        if ttl is not None:
            ttl = float(ttl)
            if not math.isfinite(ttl) or ttl < 0.0:
                raise ValueError("Cache TTL must be a finite non-negative number.")
        object.__setattr__(self, "cache_ttl_seconds", ttl)
        for name in (
            "store_full_result",
            "store_stage_results",
            "store_diagnostics",
            "store_files",
            "stale_on_input_change",
            "stale_on_config_change",
            "stale_on_pipeline_change",
            "cache_failed_results",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready configuration mapping."""

        return {
            "attachment_policy": self.attachment_policy,
            "copy_values": self.copy_values,
            "preserve_history": self.preserve_history,
            "max_history_entries": self.max_history_entries,
            "max_attachment_records": self.max_attachment_records,
            "cache_enabled": self.cache_enabled,
            "max_cache_entries": self.max_cache_entries,
            "cache_ttl_seconds": self.cache_ttl_seconds,
            "store_full_result": self.store_full_result,
            "store_stage_results": self.store_stage_results,
            "store_diagnostics": self.store_diagnostics,
            "store_files": self.store_files,
            "stale_on_input_change": self.stale_on_input_change,
            "stale_on_config_change": self.stale_on_config_change,
            "stale_on_pipeline_change": self.stale_on_pipeline_change,
            "cache_failed_results": self.cache_failed_results,
        }

    @property
    def fingerprint(self) -> str:
        """Return a deterministic configuration fingerprint."""

        payload = json.dumps(
            self.to_dict(),
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
        return sha256(payload.encode(ANALYSIS_ENCODING)).hexdigest()


DockModelStateConfigLike: TypeAlias = Union[
    DockModelStateConfig,
    AnalysisConfig,
    Mapping[str, Any],
    None,
]


def resolve_dock_model_state_config(
    value: DockModelStateConfigLike = None,
    *,
    analysis_config: AnalysisConfigLike = None,
) -> DockModelStateConfig:
    """Resolve unified state behavior from local or analysis configuration."""

    if isinstance(value, DockModelStateConfig):
        return value
    integrated: Optional[AnalysisConfig] = None
    if isinstance(value, AnalysisConfig):
        integrated = value
        value = None
    elif analysis_config is not None:
        integrated = coerce_analysis_config(analysis_config)

    data: Dict[str, Any] = {}
    if integrated is not None:
        data.update(
            {
                "attachment_policy": integrated.runtime.attachment_policy,
                "cache_enabled": any(
                    stage.cache_enabled
                    for stage in integrated.stages.values()
                ) if integrated.stages else True,
            }
        )
        metadata_options = integrated.metadata.get("dock_model_state")
        if isinstance(metadata_options, Mapping):
            data.update(metadata_options)

    if value is not None:
        if not isinstance(value, Mapping):
            raise TypeError(
                "DockModel state configuration must be a mapping, an "
                "AnalysisConfig or DockModelStateConfig."
            )
        for raw_name, raw_value in value.items():
            token = _normalize_access_token(raw_name)
            canonical = _DOCK_MODEL_STATE_CONFIG_ALIASES.get(token, token)
            if canonical not in {item.name for item in fields(DockModelStateConfig)}:
                raise ValueError(
                    f"Unknown DockModel state configuration option: {raw_name!r}."
                )
            data[canonical] = raw_value
    return DockModelStateConfig(**data)


# 22.4. Attachment, cache and snapshot records
# -----------------------------------------------------------------------------


@dataclass
class DockModelAttachmentRecord:
    """Describe one unified mutation applied to a DockModel field."""

    field_name: str
    policy: str
    action: Union[DockModelAttachmentAction, str]
    changed: bool
    stage: Optional[str] = None
    run_id: Optional[str] = None
    previous_present: bool = False
    previous_type: Optional[str] = None
    new_type: Optional[str] = None
    timestamp: str = field(default_factory=_utc_timestamp)
    fingerprint: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.field_name = str(self.field_name).strip()
        if not self.field_name:
            raise ValueError("Attachment records require a field name.")
        self.policy = canonicalize_attachment_policy(self.policy)
        if not isinstance(self.action, DockModelAttachmentAction):
            self.action = DockModelAttachmentAction(
                _normalize_status_token(self.action, field_name="attachment action")
            )
        self.changed = bool(self.changed)
        self.stage = _normalize_optional_stage(self.stage)
        self.run_id = normalize_optional_identifier(self.run_id)
        self.previous_present = bool(self.previous_present)
        self.previous_type = normalize_optional_text(self.previous_type)
        self.new_type = normalize_optional_text(self.new_type)
        self.timestamp = _normalize_timestamp(self.timestamp, allow_none=False) or _utc_timestamp()
        self.fingerprint = normalize_optional_identifier(self.fingerprint)
        self.metadata = normalize_metadata_mapping(self.metadata)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready mutation record."""

        return {
            "field_name": self.field_name,
            "policy": self.policy,
            "action": self.action.value,
            "changed": self.changed,
            "stage": self.stage,
            "run_id": self.run_id,
            "previous_present": self.previous_present,
            "previous_type": self.previous_type,
            "new_type": self.new_type,
            "timestamp": self.timestamp,
            "fingerprint": self.fingerprint,
            "metadata": to_json_compatible(self.metadata),
        }


@dataclass
class DockModelStageCacheEntry:
    """One bounded in-memory stage-result cache entry."""

    cache_key: str
    stage: str
    value: Any
    result_status: Optional[str] = None
    created_at: str = field(default_factory=_utc_timestamp)
    accessed_at: Optional[str] = None
    expires_at: Optional[str] = None
    input_fingerprint: Optional[str] = None
    config_fingerprint: Optional[str] = None
    pipeline_fingerprint: Optional[str] = None
    result_fingerprint: Optional[str] = None
    hit_count: int = 0
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.cache_key = normalize_identifier(self.cache_key, default="cache")
        self.stage = _normalize_optional_stage(self.stage) or STAGE_FINALIZATION
        self.result_status = normalize_optional_text(self.result_status)
        self.created_at = _normalize_timestamp(self.created_at, allow_none=False) or _utc_timestamp()
        self.accessed_at = _normalize_timestamp(self.accessed_at, allow_none=True)
        self.expires_at = _normalize_timestamp(self.expires_at, allow_none=True)
        self.input_fingerprint = normalize_optional_text(self.input_fingerprint)
        self.config_fingerprint = normalize_optional_text(self.config_fingerprint)
        self.pipeline_fingerprint = normalize_optional_text(self.pipeline_fingerprint)
        self.result_fingerprint = normalize_optional_text(self.result_fingerprint)
        self.hit_count = max(0, int(self.hit_count))
        self.metadata = normalize_metadata_mapping(self.metadata)

    @property
    def expired(self) -> bool:
        """Return whether this entry exceeded its explicit expiration time."""

        if self.expires_at is None:
            return False
        try:
            expiration = datetime.fromisoformat(self.expires_at)
        except (TypeError, ValueError):
            return True
        if expiration.tzinfo is None:
            expiration = expiration.replace(tzinfo=timezone.utc)
        return datetime.now(timezone.utc) >= expiration.astimezone(timezone.utc)

    def touch(self) -> None:
        """Record one successful cache access."""

        self.hit_count += 1
        self.accessed_at = _utc_timestamp()

    def to_dict(self, *, include_value: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe cache-entry representation."""

        data: Dict[str, Any] = {
            "cache_key": self.cache_key,
            "stage": self.stage,
            "result_status": self.result_status,
            "created_at": self.created_at,
            "accessed_at": self.accessed_at,
            "expires_at": self.expires_at,
            "expired": self.expired,
            "input_fingerprint": self.input_fingerprint,
            "config_fingerprint": self.config_fingerprint,
            "pipeline_fingerprint": self.pipeline_fingerprint,
            "result_fingerprint": self.result_fingerprint,
            "hit_count": self.hit_count,
            "metadata": to_json_compatible(self.metadata),
        }
        if include_value:
            data["value"] = to_json_compatible(self.value)
        else:
            data["value_type"] = type(self.value).__name__
        return data


@dataclass
class DockModelCacheLookup:
    """Result of one cache lookup."""

    status: Union[DockModelCacheLookupStatus, str]
    cache_key: Optional[str] = None
    stage: Optional[str] = None
    entry: Optional[DockModelStageCacheEntry] = None
    reason: Optional[str] = None

    def __post_init__(self) -> None:
        self.status = canonicalize_dock_model_cache_lookup_status(self.status)
        self.cache_key = normalize_optional_identifier(self.cache_key)
        self.stage = _normalize_optional_stage(self.stage)
        self.reason = normalize_optional_text(self.reason)

    @property
    def hit(self) -> bool:
        """Return whether this lookup produced a reusable value."""

        return self.status == DockModelCacheLookupStatus.HIT and self.entry is not None

    @property
    def value(self) -> Any:
        """Return the cached value or ``None``."""

        return self.entry.value if self.hit and self.entry is not None else None

    def to_dict(self, *, include_value: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe lookup representation."""

        return {
            "status": self.status.value,
            "cache_key": self.cache_key,
            "stage": self.stage,
            "reason": self.reason,
            "entry": (
                self.entry.to_dict(include_value=include_value)
                if self.entry is not None
                else None
            ),
        }


@dataclass
class DockModelStateSnapshot:
    """Restorable snapshot of orchestration-managed DockModel fields."""

    model_name: str
    model_identifier: Optional[str]
    values: Dict[str, Any]
    present_fields: Tuple[str, ...]
    created_at: str = field(default_factory=_utc_timestamp)
    fingerprint: Optional[str] = None

    def __post_init__(self) -> None:
        self.model_name = normalize_text(self.model_name, default="DockModel")
        self.model_identifier = normalize_optional_identifier(self.model_identifier)
        self.values = dict(self.values)
        self.present_fields = tuple(unique_preserving_order(self.present_fields))
        self.created_at = _normalize_timestamp(self.created_at, allow_none=False) or _utc_timestamp()
        if self.fingerprint is None:
            self.fingerprint = _state_payload_fingerprint(
                {
                    "model_name": self.model_name,
                    "model_identifier": self.model_identifier,
                    "present_fields": self.present_fields,
                    "created_at": self.created_at,
                    "value_types": {
                        key: type(value).__name__
                        for key, value in self.values.items()
                    },
                }
            )

    def to_dict(self, *, include_values: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe snapshot representation."""

        data: Dict[str, Any] = {
            "model_name": self.model_name,
            "model_identifier": self.model_identifier,
            "present_fields": list(self.present_fields),
            "created_at": self.created_at,
            "fingerprint": self.fingerprint,
            "value_types": {
                key: type(value).__name__
                for key, value in self.values.items()
            },
        }
        if include_values:
            data["values"] = to_json_compatible(self.values)
        return data


@dataclass
class DockModelStateReport:
    """Inspection report for one DockModel analysis state."""

    model_name: str
    model_identifier: Optional[str]
    status: Union[DockModelStateStatus, str]
    current_fingerprint: Optional[str] = None
    input_fingerprint: Optional[str] = None
    config_fingerprint: Optional[str] = None
    pipeline_fingerprint: Optional[str] = None
    result_fingerprint: Optional[str] = None
    stale_reasons: Tuple[str, ...] = ()
    generation: int = 0
    history_count: int = 0
    attachment_count: int = 0
    cache_entries: int = 0
    cache_hits: int = 0
    cache_misses: int = 0
    cache_stale: int = 0
    cache_evictions: int = 0
    existing_results: Tuple[str, ...] = ()
    updated_at: Optional[str] = None
    issues: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        self.model_name = normalize_text(self.model_name, default="DockModel")
        self.model_identifier = normalize_optional_identifier(self.model_identifier)
        self.status = canonicalize_dock_model_state_status(self.status)
        self.stale_reasons = tuple(
            unique_preserving_order(
                normalize_string_sequence(self.stale_reasons, skip_blank=True)
            )
        )
        self.generation = max(0, int(self.generation))
        self.history_count = max(0, int(self.history_count))
        self.attachment_count = max(0, int(self.attachment_count))
        self.cache_entries = max(0, int(self.cache_entries))
        self.cache_hits = max(0, int(self.cache_hits))
        self.cache_misses = max(0, int(self.cache_misses))
        self.cache_stale = max(0, int(self.cache_stale))
        self.cache_evictions = max(0, int(self.cache_evictions))
        self.existing_results = tuple(unique_preserving_order(self.existing_results))
        self.updated_at = _normalize_timestamp(self.updated_at, allow_none=True)
        self.issues = tuple(
            unique_preserving_order(normalize_string_sequence(self.issues, skip_blank=True))
        )

    @property
    def stale(self) -> bool:
        """Return whether attached results are stale."""

        return self.status == DockModelStateStatus.STALE

    @property
    def valid(self) -> bool:
        """Return whether the state is current or intentionally partial."""

        return self.status in {
            DockModelStateStatus.CURRENT,
            DockModelStateStatus.PARTIAL,
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready report."""

        return {
            "model_name": self.model_name,
            "model_identifier": self.model_identifier,
            "status": self.status.value,
            "valid": self.valid,
            "stale": self.stale,
            "current_fingerprint": self.current_fingerprint,
            "input_fingerprint": self.input_fingerprint,
            "config_fingerprint": self.config_fingerprint,
            "pipeline_fingerprint": self.pipeline_fingerprint,
            "result_fingerprint": self.result_fingerprint,
            "stale_reasons": list(self.stale_reasons),
            "generation": self.generation,
            "history_count": self.history_count,
            "attachment_count": self.attachment_count,
            "cache_entries": self.cache_entries,
            "cache_hits": self.cache_hits,
            "cache_misses": self.cache_misses,
            "cache_stale": self.cache_stale,
            "cache_evictions": self.cache_evictions,
            "existing_results": list(self.existing_results),
            "updated_at": self.updated_at,
            "issues": list(self.issues),
        }


# 22.5. Low-level state containers and fingerprints
# -----------------------------------------------------------------------------


def _state_payload_fingerprint(value: Any) -> str:
    """Return a deterministic SHA-256 digest for lightweight state data."""

    payload = json.dumps(
        to_json_compatible(value, maximum_depth=8),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        default=str,
    )
    return sha256(payload.encode(ANALYSIS_ENCODING)).hexdigest()


def _state_copy(value: Any, *, enabled: bool) -> Any:
    """Copy one attached value only when explicitly requested."""

    if not enabled:
        return value
    return safe_copy_object(value, deep=True, fallback_to_original=True)


def _state_value_is_empty(value: Any) -> bool:
    """Return whether one state value is absent or structurally empty."""

    if value is None or is_missing_value(value):
        return True
    if isinstance(value, (str, bytes, bytearray)):
        return len(value) == 0
    if isinstance(value, Mapping):
        return len(value) == 0
    if isinstance(value, (Sequence, Set, FrozenSet)):
        return len(value) == 0
    return False


def _ensure_dock_model_mapping_field(model: Any, field_name: str) -> Dict[str, Any]:
    """Return one mutable mapping field, creating it when necessary."""

    current = get_object_value(model, field_name, default=None)
    if isinstance(current, MutableMapping):
        return current
    if isinstance(current, Mapping):
        replacement = dict(current)
    elif current is None:
        replacement = {}
    else:
        raise AnalysisIntegrationError(
            f"DockModel field {field_name!r} must be a mapping.",
            details={"field": field_name, "type": type(current).__name__},
        )
    set_object_value(model, field_name, replacement, strict=True)
    return replacement


def ensure_dock_model_metadata(model: Any) -> Dict[str, Any]:
    """Return a mutable DockModel metadata mapping."""

    return _ensure_dock_model_mapping_field(model, DOCK_MODEL_FIELD_METADATA)


def ensure_dock_model_statistics(model: Any) -> Dict[str, Any]:
    """Return a mutable DockModel statistics mapping."""

    return _ensure_dock_model_mapping_field(model, DOCK_MODEL_FIELD_STATISTICS)


def ensure_dock_model_files(model: Any) -> Dict[str, Any]:
    """Return a mutable DockModel files mapping."""

    return _ensure_dock_model_mapping_field(model, DOCK_MODEL_FIELD_FILES)


def _new_dock_model_state_container() -> Dict[str, Any]:
    """Create an empty analysis-state container."""

    return {
        RESULT_KEY_SCHEMA: DOCK_MODEL_STATE_SCHEMA_NAME,
        RESULT_KEY_VERSION: DOCK_MODEL_STATE_SCHEMA_VERSION,
        DOCK_MODEL_STATE_STATUS_KEY: DockModelStateStatus.EMPTY.value,
        DOCK_MODEL_STATE_UPDATED_AT_KEY: _utc_timestamp(),
        DOCK_MODEL_STATE_GENERATION_KEY: 0,
        DOCK_MODEL_STATE_CURRENT_KEY: {},
        DOCK_MODEL_STATE_HISTORY_KEY: [],
        DOCK_MODEL_STATE_ATTACHMENTS_KEY: [],
        DOCK_MODEL_STATE_STALE_REASONS_KEY: [],
        DOCK_MODEL_STATE_STAGE_FINGERPRINTS_KEY: {},
    }


def ensure_dock_model_state_container(model: Any) -> Dict[str, Any]:
    """Return a normalized mutable orchestration-state container."""

    metadata = ensure_dock_model_metadata(model)
    existing = metadata.get(DOCK_MODEL_STATE_METADATA_KEY)
    if isinstance(existing, MutableMapping):
        container = existing
    elif isinstance(existing, Mapping):
        container = dict(existing)
        metadata[DOCK_MODEL_STATE_METADATA_KEY] = container
    else:
        container = _new_dock_model_state_container()
        metadata[DOCK_MODEL_STATE_METADATA_KEY] = container

    container.setdefault(RESULT_KEY_SCHEMA, DOCK_MODEL_STATE_SCHEMA_NAME)
    container.setdefault(RESULT_KEY_VERSION, DOCK_MODEL_STATE_SCHEMA_VERSION)
    container.setdefault(DOCK_MODEL_STATE_STATUS_KEY, DockModelStateStatus.EMPTY.value)
    container.setdefault(DOCK_MODEL_STATE_UPDATED_AT_KEY, _utc_timestamp())
    container.setdefault(DOCK_MODEL_STATE_GENERATION_KEY, 0)
    for key, default in (
        (DOCK_MODEL_STATE_CURRENT_KEY, {}),
        (DOCK_MODEL_STATE_HISTORY_KEY, []),
        (DOCK_MODEL_STATE_ATTACHMENTS_KEY, []),
        (DOCK_MODEL_STATE_STALE_REASONS_KEY, []),
        (DOCK_MODEL_STATE_STAGE_FINGERPRINTS_KEY, {}),
    ):
        value = container.get(key)
        if key in {
            DOCK_MODEL_STATE_CURRENT_KEY,
            DOCK_MODEL_STATE_STAGE_FINGERPRINTS_KEY,
        }:
            if not isinstance(value, MutableMapping):
                container[key] = dict(value) if isinstance(value, Mapping) else {}
        elif not isinstance(value, list):
            container[key] = list(value) if is_nonstring_iterable(value) else []
    return container


def _new_dock_model_cache_container() -> Dict[str, Any]:
    """Create an empty stage-cache container."""

    return {
        RESULT_KEY_SCHEMA: DOCK_MODEL_CACHE_SCHEMA_NAME,
        RESULT_KEY_VERSION: DOCK_MODEL_CACHE_SCHEMA_VERSION,
        DOCK_MODEL_CACHE_ENTRIES_KEY: OrderedDict(),
        DOCK_MODEL_CACHE_HITS_KEY: 0,
        DOCK_MODEL_CACHE_MISSES_KEY: 0,
        DOCK_MODEL_CACHE_STALE_KEY: 0,
        DOCK_MODEL_CACHE_EVICTIONS_KEY: 0,
        DOCK_MODEL_CACHE_UPDATED_AT_KEY: _utc_timestamp(),
    }


def ensure_dock_model_cache_container(model: Any) -> Dict[str, Any]:
    """Return a normalized mutable stage-cache container."""

    metadata = ensure_dock_model_metadata(model)
    existing = metadata.get(METADATA_KEY_CACHE)
    if isinstance(existing, MutableMapping):
        container = existing
    elif isinstance(existing, Mapping):
        container = dict(existing)
        metadata[METADATA_KEY_CACHE] = container
    else:
        container = _new_dock_model_cache_container()
        metadata[METADATA_KEY_CACHE] = container

    container.setdefault(RESULT_KEY_SCHEMA, DOCK_MODEL_CACHE_SCHEMA_NAME)
    container.setdefault(RESULT_KEY_VERSION, DOCK_MODEL_CACHE_SCHEMA_VERSION)
    entries = container.get(DOCK_MODEL_CACHE_ENTRIES_KEY)
    if not isinstance(entries, MutableMapping):
        entries = OrderedDict(entries) if isinstance(entries, Mapping) else OrderedDict()
        container[DOCK_MODEL_CACHE_ENTRIES_KEY] = entries
    for key in (
        DOCK_MODEL_CACHE_HITS_KEY,
        DOCK_MODEL_CACHE_MISSES_KEY,
        DOCK_MODEL_CACHE_STALE_KEY,
        DOCK_MODEL_CACHE_EVICTIONS_KEY,
    ):
        try:
            container[key] = max(0, int(container.get(key, 0)))
        except (TypeError, ValueError):
            container[key] = 0
    container.setdefault(DOCK_MODEL_CACHE_UPDATED_AT_KEY, _utc_timestamp())
    return container


def build_dock_model_input_fingerprint(model: Any) -> str:
    """Return the current receptor-pose-ligand preparation fingerprint."""

    metadata = ensure_dock_model_metadata(model)
    preparation = metadata.get(PREPARATION_FINGERPRINT_KEY)
    if preparation:
        return str(preparation)
    receptor = get_object_value(model, DOCK_MODEL_FIELD_RECEPTOR, default=None)
    pose = get_object_value(model, DOCK_MODEL_FIELD_POSE, default=None)
    ligand = get_object_value(model, DOCK_MODEL_FIELD_LIGAND, default=None)
    return _state_payload_fingerprint(
        {
            "receptor": stable_object_fingerprint(receptor),
            "pose": stable_object_fingerprint(pose),
            "ligand": stable_object_fingerprint(ligand),
        }
    )


def build_dock_model_result_fingerprint(model: Any) -> str:
    """Return a lightweight fingerprint of attached analytical outputs."""

    payload: Dict[str, Any] = {
        "model": resolve_object_identifier(model, default=resolve_object_name(model)),
        "counts": {},
        "score": get_object_value(model, DOCK_MODEL_FIELD_SCORE, default=None),
        "statistics_keys": sorted(ensure_dock_model_statistics(model).keys()),
        "file_keys": sorted(ensure_dock_model_files(model).keys()),
    }
    for family, field_name in DOCK_MODEL_INTERACTION_FIELDS.items():
        value = get_object_value(model, field_name, default=None)
        payload["counts"][family] = _count_result_items(value)
    return _state_payload_fingerprint(payload)


def build_dock_model_state_fingerprint(
    model: Any,
    *,
    config: AnalysisConfigLike = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    pipeline_fingerprint: Optional[str] = None,
) -> str:
    """Return the composite fingerprint for one model analysis state."""

    config_value = coerce_analysis_config(config) if config is not None else None
    config_fingerprint = config_value.fingerprint() if config_value else None
    if execution_plan is not None:
        pipeline_fingerprint = execution_plan_fingerprint(execution_plan)
    payload = {
        "input": build_dock_model_input_fingerprint(model),
        "config": config_fingerprint,
        "pipeline": pipeline_fingerprint or f"pipeline:{ANALYSIS_PIPELINE_VERSION}",
        "state_schema": DOCK_MODEL_STATE_SCHEMA_VERSION,
    }
    return _state_payload_fingerprint(payload)


# 22.6. Generic merge and attachment operations
# -----------------------------------------------------------------------------


def _state_item_marker(value: Any) -> Tuple[str, Any]:
    """Return a low-cost marker used for order-preserving sequence merge."""

    if value is None or isinstance(value, (str, int, float, bool, bytes)):
        return (type(value).__name__, value)
    if isinstance(value, Path):
        return ("path", str(value))
    explicit = get_first_object_value(
        value,
        ("interaction_id", "pose_id", "model_id", "identifier", "id", "name"),
        default=None,
        skip_none=True,
    )
    if explicit is not None and not callable(explicit):
        return (type(value).__name__, str(explicit))
    return ("identity", id(value))


def merge_dock_model_state_values(existing: Any, incoming: Any) -> Any:
    """Merge generic state values without chemistry-specific assumptions."""

    if existing is _STATE_MISSING or existing is None:
        return incoming
    if incoming is _STATE_MISSING or incoming is None:
        return existing
    if isinstance(existing, Mapping) and isinstance(incoming, Mapping):
        merged: Dict[str, Any] = dict(existing)
        for key, value in incoming.items():
            if key in merged:
                merged[key] = merge_dock_model_state_values(merged[key], value)
            else:
                merged[key] = value
        return merged
    if isinstance(existing, list) and isinstance(incoming, (list, tuple)):
        merged_list = list(existing)
        seen = {_state_item_marker(item) for item in merged_list}
        for item in incoming:
            marker = _state_item_marker(item)
            if marker not in seen:
                merged_list.append(item)
                seen.add(marker)
        return merged_list
    if isinstance(existing, tuple) and isinstance(incoming, (list, tuple)):
        return tuple(merge_dock_model_state_values(list(existing), list(incoming)))
    if isinstance(existing, set) and isinstance(incoming, (set, frozenset, list, tuple)):
        return set(existing).union(incoming)
    return incoming


def _access_dock_model_managed_value(
    model: Any,
    field_name: str,
) -> Tuple[bool, Any, Optional[str]]:
    """Read a managed value directly or from its metadata fallback."""

    access = access_object_value(model, field_name, include_aliases=False)
    if access.found:
        return True, access.value, "attribute"
    if field_name in DOCK_MODEL_MANAGED_DYNAMIC_FIELDS:
        metadata = get_object_value(
            model,
            DOCK_MODEL_FIELD_METADATA,
            default=None,
            include_aliases=False,
        )
        if isinstance(metadata, Mapping) and field_name in metadata:
            return True, metadata[field_name], "metadata"
    return False, _STATE_MISSING, None


def _set_dock_model_managed_value(
    model: Any,
    field_name: str,
    value: Any,
) -> str:
    """Store a managed value directly or in metadata for restricted objects."""

    try:
        set_object_value(
            model,
            field_name,
            value,
            include_aliases=False,
            prefer_existing=True,
            strict=True,
        )
        return "attribute"
    except (AttributeError, TypeError) as exc:
        if field_name not in DOCK_MODEL_MANAGED_DYNAMIC_FIELDS:
            raise AnalysisIntegrationError(
                f"DockModel field {field_name!r} is not writable.",
                details={"field": field_name, "model_type": type(model).__name__},
                cause=exc,
            ) from exc
        try:
            metadata = ensure_dock_model_metadata(model)
        except Exception as metadata_exc:
            raise AnalysisIntegrationError(
                f"DockModel dynamic field {field_name!r} cannot be stored.",
                details={
                    "field": field_name,
                    "model_type": type(model).__name__,
                    "fallback": "metadata",
                },
                cause=metadata_exc,
            ) from metadata_exc
        metadata[field_name] = value
        return "metadata"


def _delete_dock_model_managed_value(model: Any, field_name: str) -> bool:
    """Delete a managed direct value or its metadata fallback."""

    if delete_object_value(
        model,
        field_name,
        include_aliases=False,
        strict=False,
    ):
        return True
    if field_name in DOCK_MODEL_MANAGED_DYNAMIC_FIELDS:
        metadata = get_object_value(
            model,
            DOCK_MODEL_FIELD_METADATA,
            default=None,
            include_aliases=False,
        )
        if isinstance(metadata, MutableMapping) and field_name in metadata:
            del metadata[field_name]
            return True
    return False


def _record_dock_model_attachment(
    model: Any,
    record: DockModelAttachmentRecord,
    *,
    config: DockModelStateConfig,
) -> None:
    """Append one bounded attachment record when state storage is available."""

    if config.max_attachment_records <= 0:
        record.metadata.setdefault("recorded", False)
        record.metadata.setdefault("recording_reason", "disabled")
        return
    try:
        container = ensure_dock_model_state_container(model)
    except Exception as exc:
        record.metadata.setdefault("recorded", False)
        record.metadata.setdefault("recording_reason", "state_unavailable")
        record.metadata.setdefault("recording_error", type(exc).__name__)
        return
    records = container[DOCK_MODEL_STATE_ATTACHMENTS_KEY]
    record.metadata.setdefault("recorded", True)
    records.append(record.to_dict())
    excess = len(records) - config.max_attachment_records
    if excess > 0:
        del records[:excess]
    container[DOCK_MODEL_STATE_UPDATED_AT_KEY] = _utc_timestamp()


def attach_dock_model_field(
    model: Any,
    field_name: Any,
    value: Any,
    *,
    policy: Any = DEFAULT_ATTACHMENT_POLICY,
    stage: Optional[Any] = None,
    run_id: Optional[Any] = None,
    copy_value: bool = False,
    record: bool = True,
    state_config: DockModelStateConfigLike = None,
) -> DockModelAttachmentRecord:
    """Attach one field using replace, merge, preserve or no-op semantics."""

    if model is None:
        raise AnalysisIntegrationError("Cannot attach analysis data to None.")
    name = str(field_name).strip()
    if not name:
        raise ValueError("DockModel attachment requires a field name.")
    config_value = resolve_dock_model_state_config(state_config)
    selected_policy = canonicalize_attachment_policy(policy)
    previous_present, previous, previous_storage = (
        _access_dock_model_managed_value(model, name)
    )

    if selected_policy == ATTACHMENT_POLICY_NONE:
        action = DockModelAttachmentAction.SKIPPED
        changed = False
        attached = previous if previous_present else None
    elif selected_policy == ATTACHMENT_POLICY_PRESERVE and previous_present and not _state_value_is_empty(previous):
        action = DockModelAttachmentAction.PRESERVED
        changed = False
        attached = previous
    else:
        incoming = _state_copy(value, enabled=copy_value or config_value.copy_values)
        if selected_policy == ATTACHMENT_POLICY_MERGE and previous_present:
            attached = merge_dock_model_state_values(previous, incoming)
            action = DockModelAttachmentAction.MERGED
        else:
            attached = incoming
            action = (
                DockModelAttachmentAction.REPLACED
                if previous_present
                else DockModelAttachmentAction.CREATED
            )
        storage = _set_dock_model_managed_value(model, name, attached)
        changed = previous is _STATE_MISSING or attached is not previous or attached != previous

    record_value = DockModelAttachmentRecord(
        field_name=name,
        policy=selected_policy,
        action=action,
        changed=changed,
        stage=stage,
        run_id=run_id,
        previous_present=previous_present,
        previous_type=(type(previous).__name__ if previous_present else None),
        new_type=(type(attached).__name__ if attached is not None else None),
        fingerprint=_state_payload_fingerprint(
            {
                "field": name,
                "action": action.value,
                "new_type": type(attached).__name__ if attached is not None else None,
                "stage": _normalize_optional_stage(stage),
            }
        ),
        metadata={
            "previous_storage": previous_storage,
            "storage": locals().get("storage", previous_storage),
        },
    )
    if record:
        _record_dock_model_attachment(model, record_value, config=config_value)
    return record_value


def remove_dock_model_field(
    model: Any,
    field_name: Any,
    *,
    stage: Optional[Any] = None,
    run_id: Optional[Any] = None,
    record: bool = True,
    state_config: DockModelStateConfigLike = None,
) -> DockModelAttachmentRecord:
    """Remove one managed dynamic field or reset one core field."""

    name = str(field_name).strip()
    config_value = resolve_dock_model_state_config(state_config)
    previous_present, previous, _previous_storage = (
        _access_dock_model_managed_value(model, name)
    )
    changed = False
    if previous_present:
        if name in {
            DOCK_MODEL_FIELD_CONTACTS,
            DOCK_MODEL_FIELD_HBONDS,
            DOCK_MODEL_FIELD_HYDROPHOBIC,
        }:
            set_object_value(model, name, [], include_aliases=False)
            changed = True
        elif name == DOCK_MODEL_FIELD_PI:
            set_object_value(
                model,
                name,
                {key: [] for key in DOCK_MODEL_PI_KEYS.values()},
                include_aliases=False,
            )
            changed = True
        elif name == DOCK_MODEL_FIELD_SCORE:
            set_object_value(model, name, None, include_aliases=False)
            changed = True
        elif name in {
            DOCK_MODEL_FIELD_STATISTICS,
            DOCK_MODEL_FIELD_FILES,
        }:
            set_object_value(model, name, {}, include_aliases=False)
            changed = True
        else:
            changed = _delete_dock_model_managed_value(model, name)
    attachment = DockModelAttachmentRecord(
        field_name=name,
        policy=ATTACHMENT_POLICY_REPLACE,
        action=(
            DockModelAttachmentAction.REMOVED
            if changed
            else DockModelAttachmentAction.SKIPPED
        ),
        changed=changed,
        stage=stage,
        run_id=run_id,
        previous_present=previous_present,
        previous_type=type(previous).__name__ if previous_present else None,
        new_type=None,
    )
    if record:
        _record_dock_model_attachment(model, attachment, config=config_value)
    return attachment


def attach_interaction_bundle_to_dock_model(
    model: Any,
    bundle: Any,
    *,
    policy: Any = DEFAULT_ATTACHMENT_POLICY,
    stage: Any = STAGE_CONSOLIDATION,
    run_id: Optional[Any] = None,
    state_config: DockModelStateConfigLike = None,
) -> Tuple[DockModelAttachmentRecord, ...]:
    """Attach all canonical interaction families from one integrated bundle."""

    normalized = coerce_interaction_bundle(bundle)
    records: List[DockModelAttachmentRecord] = []
    for family in INTERACTION_FAMILY_ORDER:
        field_name = DOCK_MODEL_INTERACTION_FIELDS[family]
        family_value = normalized.get(family)
        records.append(
            attach_dock_model_field(
                model,
                field_name,
                family_value,
                policy=policy,
                stage=stage,
                run_id=run_id,
                state_config=state_config,
            )
        )
    return tuple(records)


def attach_dock_model_statistics(
    model: Any,
    statistics: Any,
    *,
    policy: Any = ATTACHMENT_POLICY_MERGE,
    stage: Optional[Any] = None,
    run_id: Optional[Any] = None,
    state_config: DockModelStateConfigLike = None,
) -> DockModelAttachmentRecord:
    """Attach normalized statistics to a DockModel."""

    return attach_dock_model_field(
        model,
        DOCK_MODEL_FIELD_STATISTICS,
        normalize_statistics_mapping(statistics),
        policy=policy,
        stage=stage,
        run_id=run_id,
        state_config=state_config,
    )


def attach_dock_model_files(
    model: Any,
    files_value: Any,
    *,
    policy: Any = ATTACHMENT_POLICY_MERGE,
    stage: Optional[Any] = None,
    run_id: Optional[Any] = None,
    state_config: DockModelStateConfigLike = None,
) -> DockModelAttachmentRecord:
    """Attach normalized output-file references to a DockModel."""

    return attach_dock_model_field(
        model,
        DOCK_MODEL_FIELD_FILES,
        normalize_file_mapping(files_value),
        policy=policy,
        stage=stage,
        run_id=run_id,
        state_config=state_config,
    )


def attach_dock_model_metadata(
    model: Any,
    metadata_value: Any,
    *,
    policy: Any = ATTACHMENT_POLICY_MERGE,
    stage: Optional[Any] = None,
    run_id: Optional[Any] = None,
    state_config: DockModelStateConfigLike = None,
) -> DockModelAttachmentRecord:
    """Attach normalized metadata while preserving the state container."""

    incoming = normalize_metadata_mapping(metadata_value)
    incoming.pop(DOCK_MODEL_STATE_METADATA_KEY, None)
    incoming.pop(METADATA_KEY_CACHE, None)
    return attach_dock_model_field(
        model,
        DOCK_MODEL_FIELD_METADATA,
        incoming,
        policy=policy,
        stage=stage,
        run_id=run_id,
        state_config=state_config,
    )


# 22.7. History, current state and staleness
# -----------------------------------------------------------------------------


def append_dock_model_analysis_history(
    model: Any,
    value: Any,
    *,
    state_config: DockModelStateConfigLike = None,
) -> int:
    """Append one bounded lightweight analysis-history entry."""

    config_value = resolve_dock_model_state_config(state_config)
    if not config_value.preserve_history or config_value.max_history_entries <= 0:
        return 0
    container = ensure_dock_model_state_container(model)
    history = container[DOCK_MODEL_STATE_HISTORY_KEY]
    if isinstance(value, PoseAnalysisResult):
        entry: Any = {
            "pose_id": value.pose_id,
            "name": value.name,
            "status": value.status.value,
            "finished_at": value.finished_at,
            "interaction_count": value.interaction_count,
            "completed_stages": list(value.completed_stages),
            "failed_stages": list(value.failed_stages),
            "score_type": type(value.scoring).__name__ if value.scoring is not None else None,
        }
    elif isinstance(value, AnalysisRunResult):
        entry = {
            "run_id": value.run_id,
            "request_id": value.request_id,
            "status": value.status.value,
            "finished_at": value.finished_at,
            "pose_count": len(value.pose_results),
        }
    elif isinstance(value, Mapping):
        entry = dict(value)
    else:
        entry = {
            "type": type(value).__name__,
            "value": to_json_compatible(value, maximum_depth=4),
        }
    entry.setdefault("recorded_at", _utc_timestamp())
    history.append(entry)
    excess = len(history) - config_value.max_history_entries
    if excess > 0:
        del history[:excess]
    container[DOCK_MODEL_STATE_UPDATED_AT_KEY] = _utc_timestamp()
    return len(history)


def update_dock_model_current_state(
    model: Any,
    *,
    status: Any = DockModelStateStatus.CURRENT,
    run_id: Optional[Any] = None,
    request_id: Optional[Any] = None,
    pose_id: Optional[Any] = None,
    input_fingerprint: Optional[str] = None,
    config_fingerprint: Optional[str] = None,
    pipeline_fingerprint: Optional[str] = None,
    result_fingerprint: Optional[str] = None,
    stage_fingerprints: Optional[Mapping[str, str]] = None,
    stale_reasons: Iterable[Any] = (),
) -> Dict[str, Any]:
    """Replace the current model-state descriptor."""

    container = ensure_dock_model_state_container(model)
    current = container[DOCK_MODEL_STATE_CURRENT_KEY]
    selected_status = canonicalize_dock_model_state_status(status)
    input_value = input_fingerprint or build_dock_model_input_fingerprint(model)
    result_value = result_fingerprint or build_dock_model_result_fingerprint(model)
    payload = {
        DOCK_MODEL_STATE_STATUS_KEY: selected_status.value,
        DOCK_MODEL_STATE_RUN_ID_KEY: normalize_optional_identifier(run_id),
        DOCK_MODEL_STATE_REQUEST_ID_KEY: normalize_optional_identifier(request_id),
        DOCK_MODEL_STATE_POSE_ID_KEY: normalize_optional_identifier(pose_id),
        DOCK_MODEL_STATE_INPUT_FINGERPRINT_KEY: input_value,
        DOCK_MODEL_STATE_CONFIG_FINGERPRINT_KEY: config_fingerprint,
        DOCK_MODEL_STATE_PIPELINE_FINGERPRINT_KEY: pipeline_fingerprint,
        DOCK_MODEL_STATE_RESULT_FINGERPRINT_KEY: result_value,
        DOCK_MODEL_STATE_UPDATED_AT_KEY: _utc_timestamp(),
    }
    current.clear()
    current.update(payload)
    reasons = list(
        unique_preserving_order(
            normalize_string_sequence(stale_reasons, skip_blank=True)
        )
    )
    container[DOCK_MODEL_STATE_STATUS_KEY] = selected_status.value
    container[DOCK_MODEL_STATE_STALE_REASONS_KEY] = reasons
    container[DOCK_MODEL_STATE_UPDATED_AT_KEY] = payload[DOCK_MODEL_STATE_UPDATED_AT_KEY]
    container[DOCK_MODEL_STATE_GENERATION_KEY] = max(
        0,
        int(container.get(DOCK_MODEL_STATE_GENERATION_KEY, 0)),
    ) + 1
    if stage_fingerprints is not None:
        container[DOCK_MODEL_STATE_STAGE_FINGERPRINTS_KEY] = dict(stage_fingerprints)
    composite = _state_payload_fingerprint(
        {
            "input": input_value,
            "config": config_fingerprint,
            "pipeline": pipeline_fingerprint,
            "result": result_value,
            "generation": container[DOCK_MODEL_STATE_GENERATION_KEY],
        }
    )
    current["current_fingerprint"] = composite
    container["current_fingerprint"] = composite
    return container


def mark_dock_model_state_stale(
    model: Any,
    *reasons: Any,
    invalidate_cache: bool = True,
) -> DockModelStateReport:
    """Mark attached analysis results as stale without deleting them."""

    container = ensure_dock_model_state_container(model)
    normalized = list(
        unique_preserving_order(
            normalize_string_sequence(reasons or ("manually invalidated",), skip_blank=True)
        )
    )
    existing = normalize_string_sequence(
        container.get(DOCK_MODEL_STATE_STALE_REASONS_KEY),
        skip_blank=True,
    )
    container[DOCK_MODEL_STATE_STALE_REASONS_KEY] = list(
        unique_preserving_order((*existing, *normalized))
    )
    container[DOCK_MODEL_STATE_STATUS_KEY] = DockModelStateStatus.STALE.value
    current = container.get(DOCK_MODEL_STATE_CURRENT_KEY)
    if isinstance(current, MutableMapping):
        current[DOCK_MODEL_STATE_STATUS_KEY] = DockModelStateStatus.STALE.value
        current[DOCK_MODEL_STATE_UPDATED_AT_KEY] = _utc_timestamp()
    container[DOCK_MODEL_STATE_UPDATED_AT_KEY] = _utc_timestamp()
    if invalidate_cache:
        clear_dock_model_stage_cache(model)
    return inspect_dock_model_state(model)


def detect_dock_model_stale_reasons(
    model: Any,
    *,
    config: AnalysisConfigLike = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    pipeline_fingerprint: Optional[str] = None,
    state_config: DockModelStateConfigLike = None,
) -> Tuple[str, ...]:
    """Compare current inputs and configuration against attached state."""

    options = resolve_dock_model_state_config(
        state_config,
        analysis_config=config,
    )
    container = ensure_dock_model_state_container(model)
    current = container.get(DOCK_MODEL_STATE_CURRENT_KEY, {})
    if not isinstance(current, Mapping) or not current:
        return ("No current analysis-state descriptor is attached.",)
    reasons: List[str] = []
    if options.stale_on_input_change:
        previous_input = current.get(DOCK_MODEL_STATE_INPUT_FINGERPRINT_KEY)
        observed_input = build_dock_model_input_fingerprint(model)
        if previous_input and previous_input != observed_input:
            reasons.append("The receptor, pose or ligand fingerprint changed.")
    if options.stale_on_config_change and config is not None:
        previous_config = current.get(DOCK_MODEL_STATE_CONFIG_FINGERPRINT_KEY)
        observed_config = coerce_analysis_config(config).fingerprint()
        if previous_config and previous_config != observed_config:
            reasons.append("The analysis configuration fingerprint changed.")
    if options.stale_on_pipeline_change:
        previous_pipeline = current.get(DOCK_MODEL_STATE_PIPELINE_FINGERPRINT_KEY)
        if execution_plan is not None:
            pipeline_fingerprint = execution_plan_fingerprint(execution_plan)
        observed_pipeline = pipeline_fingerprint or f"pipeline:{ANALYSIS_PIPELINE_VERSION}"
        if previous_pipeline and previous_pipeline != observed_pipeline:
            reasons.append("The execution-plan or pipeline fingerprint changed.")
    return tuple(unique_preserving_order(reasons))


def dock_model_state_is_stale(
    model: Any,
    **kwargs: Any,
) -> bool:
    """Return whether attached analysis data is stale."""

    container = ensure_dock_model_state_container(model)
    if container.get(DOCK_MODEL_STATE_STATUS_KEY) == DockModelStateStatus.STALE.value:
        return True
    return bool(detect_dock_model_stale_reasons(model, **kwargs))


# 22.8. Stage-result cache
# -----------------------------------------------------------------------------


def build_dock_model_stage_cache_key(
    model: Any,
    stage: Any,
    *,
    config: AnalysisConfigLike = None,
    stage_parameters: Optional[Mapping[str, Any]] = None,
    input_fingerprint: Optional[str] = None,
    config_fingerprint: Optional[str] = None,
    pipeline_fingerprint: Optional[str] = None,
) -> str:
    """Build a deterministic cache key for one model and pipeline stage."""

    stage_name = _normalize_optional_stage(stage)
    if stage_name is None:
        raise ValueError("Stage cache keys require a stage name.")
    if input_fingerprint is None:
        input_fingerprint = build_dock_model_input_fingerprint(model)
    if config_fingerprint is None and config is not None:
        config_fingerprint = coerce_analysis_config(config).fingerprint()
    payload = {
        "schema": DOCK_MODEL_CACHE_SCHEMA_VERSION,
        "stage": stage_name,
        "input": input_fingerprint,
        "config": config_fingerprint,
        "pipeline": pipeline_fingerprint or f"pipeline:{ANALYSIS_PIPELINE_VERSION}",
        "parameters": dict(stage_parameters or {}),
    }
    return _state_payload_fingerprint(payload)


def _coerce_dock_model_cache_entry(
    value: Any,
    *,
    cache_key: Optional[str] = None,
) -> Optional[DockModelStageCacheEntry]:
    """Coerce a stored cache entry object or mapping."""

    if isinstance(value, DockModelStageCacheEntry):
        return value
    if not isinstance(value, Mapping):
        return None
    data = dict(value)
    key = data.pop("cache_key", cache_key)
    stage = data.pop("stage", None)
    if key is None or stage is None or "value" not in data:
        return None
    return DockModelStageCacheEntry(
        cache_key=key,
        stage=stage,
        value=data.pop("value"),
        result_status=data.pop("result_status", None),
        created_at=data.pop("created_at", _utc_timestamp()),
        accessed_at=data.pop("accessed_at", None),
        expires_at=data.pop("expires_at", None),
        input_fingerprint=data.pop("input_fingerprint", None),
        config_fingerprint=data.pop("config_fingerprint", None),
        pipeline_fingerprint=data.pop("pipeline_fingerprint", None),
        result_fingerprint=data.pop("result_fingerprint", None),
        hit_count=data.pop("hit_count", 0),
        metadata=data.pop("metadata", data),
    )


def _cache_expiration_timestamp(ttl_seconds: Optional[float]) -> Optional[str]:
    """Return an ISO expiration timestamp for one TTL."""

    if ttl_seconds is None:
        return None
    return datetime.fromtimestamp(
        time.time() + max(0.0, float(ttl_seconds)),
        tz=timezone.utc,
    ).isoformat(timespec=DEFAULT_DATETIME_TIMESPEC)


def put_dock_model_stage_cache(
    model: Any,
    stage: Any,
    value: Any,
    *,
    cache_key: Optional[str] = None,
    config: AnalysisConfigLike = None,
    stage_parameters: Optional[Mapping[str, Any]] = None,
    input_fingerprint: Optional[str] = None,
    config_fingerprint: Optional[str] = None,
    pipeline_fingerprint: Optional[str] = None,
    result_status: Optional[Any] = None,
    result_fingerprint: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    state_config: DockModelStateConfigLike = None,
) -> Optional[DockModelStageCacheEntry]:
    """Store one bounded stage-result cache entry."""

    options = resolve_dock_model_state_config(
        state_config,
        analysis_config=config,
    )
    if not options.cache_enabled or options.max_cache_entries <= 0:
        return None
    stage_name = _normalize_optional_stage(stage)
    if stage_name is None:
        raise ValueError("Stage cache insertion requires a stage name.")
    if isinstance(value, AnalysisStageResult):
        if value.failed and not options.cache_failed_results:
            return None
        if result_status is None:
            result_status = value.status.value
    input_value = input_fingerprint or build_dock_model_input_fingerprint(model)
    config_value = config_fingerprint
    if config_value is None and config is not None:
        config_value = coerce_analysis_config(config).fingerprint()
    key = cache_key or build_dock_model_stage_cache_key(
        model,
        stage_name,
        config=config,
        stage_parameters=stage_parameters,
        input_fingerprint=input_value,
        config_fingerprint=config_value,
        pipeline_fingerprint=pipeline_fingerprint,
    )
    entry = DockModelStageCacheEntry(
        cache_key=key,
        stage=stage_name,
        value=value,
        result_status=(
            str(result_status.value)
            if isinstance(result_status, Enum)
            else normalize_optional_text(result_status)
        ),
        expires_at=_cache_expiration_timestamp(options.cache_ttl_seconds),
        input_fingerprint=input_value,
        config_fingerprint=config_value,
        pipeline_fingerprint=(
            pipeline_fingerprint or f"pipeline:{ANALYSIS_PIPELINE_VERSION}"
        ),
        result_fingerprint=(
            result_fingerprint
            or _state_payload_fingerprint(
                {
                    "stage": stage_name,
                    "type": type(value).__name__,
                    "status": str(result_status),
                }
            )
        ),
        metadata=dict(metadata or {}),
    )
    with _DOCK_MODEL_STATE_LOCK:
        container = ensure_dock_model_cache_container(model)
        entries = container[DOCK_MODEL_CACHE_ENTRIES_KEY]
        if key in entries:
            del entries[key]
        entries[key] = entry
        while len(entries) > options.max_cache_entries:
            oldest_key = next(iter(entries))
            del entries[oldest_key]
            container[DOCK_MODEL_CACHE_EVICTIONS_KEY] += 1
        container[DOCK_MODEL_CACHE_UPDATED_AT_KEY] = _utc_timestamp()
    state = ensure_dock_model_state_container(model)
    state[DOCK_MODEL_STATE_STAGE_FINGERPRINTS_KEY][stage_name] = key
    return entry


def get_dock_model_stage_cache(
    model: Any,
    stage: Any,
    *,
    cache_key: Optional[str] = None,
    config: AnalysisConfigLike = None,
    stage_parameters: Optional[Mapping[str, Any]] = None,
    input_fingerprint: Optional[str] = None,
    config_fingerprint: Optional[str] = None,
    pipeline_fingerprint: Optional[str] = None,
    state_config: DockModelStateConfigLike = None,
    remove_stale: bool = True,
) -> DockModelCacheLookup:
    """Return one reusable stage result when fingerprints still match."""

    options = resolve_dock_model_state_config(
        state_config,
        analysis_config=config,
    )
    stage_name = _normalize_optional_stage(stage)
    if stage_name is None:
        raise ValueError("Stage cache lookup requires a stage name.")
    if not options.cache_enabled:
        return DockModelCacheLookup(
            status=DockModelCacheLookupStatus.DISABLED,
            stage=stage_name,
            reason="Stage caching is disabled.",
        )
    input_value = input_fingerprint or build_dock_model_input_fingerprint(model)
    config_value = config_fingerprint
    if config_value is None and config is not None:
        config_value = coerce_analysis_config(config).fingerprint()
    key = cache_key or build_dock_model_stage_cache_key(
        model,
        stage_name,
        config=config,
        stage_parameters=stage_parameters,
        input_fingerprint=input_value,
        config_fingerprint=config_value,
        pipeline_fingerprint=pipeline_fingerprint,
    )
    with _DOCK_MODEL_STATE_LOCK:
        container = ensure_dock_model_cache_container(model)
        entries = container[DOCK_MODEL_CACHE_ENTRIES_KEY]
        raw = entries.get(key)
        entry = _coerce_dock_model_cache_entry(raw, cache_key=key)
        if entry is None:
            container[DOCK_MODEL_CACHE_MISSES_KEY] += 1
            return DockModelCacheLookup(
                status=DockModelCacheLookupStatus.MISS,
                cache_key=key,
                stage=stage_name,
                reason="No cache entry matched the requested stage fingerprint.",
            )
        stale_reason: Optional[str] = None
        observed_pipeline = pipeline_fingerprint or f"pipeline:{ANALYSIS_PIPELINE_VERSION}"
        if entry.expired:
            stale_reason = "The cache entry expired."
        elif entry.stage != stage_name:
            stale_reason = "The cached stage name does not match."
        elif entry.input_fingerprint and entry.input_fingerprint != input_value:
            stale_reason = "The input fingerprint changed."
        elif entry.config_fingerprint and entry.config_fingerprint != config_value:
            stale_reason = "The configuration fingerprint changed."
        elif entry.pipeline_fingerprint and entry.pipeline_fingerprint != observed_pipeline:
            stale_reason = "The pipeline fingerprint changed."
        if stale_reason is not None:
            container[DOCK_MODEL_CACHE_STALE_KEY] += 1
            if remove_stale:
                entries.pop(key, None)
            return DockModelCacheLookup(
                status=DockModelCacheLookupStatus.STALE,
                cache_key=key,
                stage=stage_name,
                entry=entry,
                reason=stale_reason,
            )
        entry.touch()
        entries.pop(key, None)
        entries[key] = entry
        container[DOCK_MODEL_CACHE_HITS_KEY] += 1
        container[DOCK_MODEL_CACHE_UPDATED_AT_KEY] = _utc_timestamp()
        return DockModelCacheLookup(
            status=DockModelCacheLookupStatus.HIT,
            cache_key=key,
            stage=stage_name,
            entry=entry,
        )


def clear_dock_model_stage_cache(
    model: Any,
    *,
    stages: Optional[Iterable[Any]] = None,
) -> int:
    """Remove all cache entries or only entries for selected stages."""

    container = ensure_dock_model_cache_container(model)
    entries = container[DOCK_MODEL_CACHE_ENTRIES_KEY]
    if stages is None:
        removed = len(entries)
        entries.clear()
    else:
        selected = {_normalize_optional_stage(stage) for stage in stages}
        selected.discard(None)
        keys = []
        for key, raw in list(entries.items()):
            entry = _coerce_dock_model_cache_entry(raw, cache_key=key)
            if entry is not None and entry.stage in selected:
                keys.append(key)
        for key in keys:
            entries.pop(key, None)
        removed = len(keys)
    container[DOCK_MODEL_CACHE_UPDATED_AT_KEY] = _utc_timestamp()
    return removed


def prune_dock_model_stage_cache(
    model: Any,
    *,
    max_entries: Optional[int] = None,
    remove_expired: bool = True,
) -> int:
    """Remove expired and excess cache entries."""

    container = ensure_dock_model_cache_container(model)
    entries = container[DOCK_MODEL_CACHE_ENTRIES_KEY]
    removed = 0
    if remove_expired:
        for key, raw in list(entries.items()):
            entry = _coerce_dock_model_cache_entry(raw, cache_key=key)
            if entry is None or entry.expired:
                entries.pop(key, None)
                removed += 1
                container[DOCK_MODEL_CACHE_STALE_KEY] += 1
    if max_entries is not None:
        limit = max(0, int(max_entries))
        while len(entries) > limit:
            entries.pop(next(iter(entries)), None)
            removed += 1
            container[DOCK_MODEL_CACHE_EVICTIONS_KEY] += 1
    container[DOCK_MODEL_CACHE_UPDATED_AT_KEY] = _utc_timestamp()
    return removed


# 22.9. Snapshots and transactional mutation
# -----------------------------------------------------------------------------


def snapshot_dock_model_state(
    model: Any,
    *,
    fields_to_capture: Iterable[Any] = DOCK_MODEL_SNAPSHOT_FIELDS,
    deep: bool = True,
) -> DockModelStateSnapshot:
    """Capture restorable values for orchestration-managed fields."""

    values: Dict[str, Any] = {}
    present: List[str] = []
    for raw_name in fields_to_capture:
        name = str(raw_name).strip()
        if not name:
            continue
        found, current, _storage = _access_dock_model_managed_value(model, name)
        if not found:
            continue
        present.append(name)
        values[name] = safe_copy_object(
            current,
            deep=deep,
            fallback_to_original=True,
        )
    identity = describe_object(model)
    return DockModelStateSnapshot(
        model_name=identity.name,
        model_identifier=identity.identifier,
        values=values,
        present_fields=tuple(present),
    )


def restore_dock_model_state(
    model: Any,
    snapshot: DockModelStateSnapshot,
    *,
    remove_new_fields: bool = True,
) -> None:
    """Restore one prior DockModel snapshot."""

    if not isinstance(snapshot, DockModelStateSnapshot):
        raise TypeError("DockModel state restoration requires a snapshot object.")
    expected = set(snapshot.present_fields)
    if remove_new_fields:
        for name in DOCK_MODEL_SNAPSHOT_FIELDS:
            if name in expected:
                continue
            if name in DOCK_MODEL_MANAGED_DYNAMIC_FIELDS:
                _delete_dock_model_managed_value(model, name)
    for name in snapshot.present_fields:
        _set_dock_model_managed_value(
            model,
            name,
            safe_copy_object(snapshot.values[name], deep=True, fallback_to_original=True),
        )


@contextmanager
def dock_model_state_transaction(
    model: Any,
    *,
    rollback_on_error: bool = True,
    fields_to_capture: Iterable[Any] = DOCK_MODEL_SNAPSHOT_FIELDS,
) -> Iterator[DockModelStateSnapshot]:
    """Provide transactional DockModel mutation with optional rollback."""

    snapshot = snapshot_dock_model_state(
        model,
        fields_to_capture=fields_to_capture,
        deep=True,
    )
    try:
        yield snapshot
    except Exception:
        if rollback_on_error:
            restore_dock_model_state(model, snapshot)
        raise


# 22.10. Cleanup, reset and invalidation
# -----------------------------------------------------------------------------


def clear_dock_model_analysis_results(
    model: Any,
    *,
    interactions: bool = True,
    scoring: bool = True,
    statistics: bool = True,
    files: bool = False,
    integrated_results: bool = True,
    metadata_state: bool = False,
    cache: bool = True,
    history: bool = False,
) -> Tuple[str, ...]:
    """Clear selected analysis outputs while preserving molecular inputs."""

    cleared: List[str] = []
    if interactions:
        for field_name in (
            DOCK_MODEL_FIELD_CONTACTS,
            DOCK_MODEL_FIELD_HBONDS,
            DOCK_MODEL_FIELD_HYDROPHOBIC,
            DOCK_MODEL_FIELD_PI,
            DOCK_MODEL_FIELD_SALTBRIDGE,
        ):
            if remove_dock_model_field(model, field_name, record=False).changed:
                cleared.append(field_name)
    if scoring:
        for field_name in (
            DOCK_MODEL_FIELD_SCORE,
            METADATA_KEY_SALTBRIDGE_SCORE,
            "hydrophobic_score",
            "pi_score",
            "scoring_result",
        ):
            if remove_dock_model_field(model, field_name, record=False).changed:
                cleared.append(field_name)
    if statistics:
        if remove_dock_model_field(
            model,
            DOCK_MODEL_FIELD_STATISTICS,
            record=False,
        ).changed:
            cleared.append(DOCK_MODEL_FIELD_STATISTICS)
        for field_name in (
            METADATA_KEY_SALTBRIDGE_STATISTICS,
            "hydrophobic_statistics",
            "pi_statistics",
        ):
            if remove_dock_model_field(model, field_name, record=False).changed:
                cleared.append(field_name)
    if files:
        if remove_dock_model_field(model, DOCK_MODEL_FIELD_FILES, record=False).changed:
            cleared.append(DOCK_MODEL_FIELD_FILES)
    if integrated_results:
        for field_name in (
            "analysis_result",
            "analysis_results",
            "analysis_stage_results",
            "consensus",
            "multipose_result",
        ):
            if remove_dock_model_field(model, field_name, record=False).changed:
                cleared.append(field_name)
    metadata = ensure_dock_model_metadata(model)
    if cache and METADATA_KEY_CACHE in metadata:
        metadata.pop(METADATA_KEY_CACHE, None)
        cleared.append(METADATA_KEY_CACHE)
    if metadata_state:
        if not history:
            existing = metadata.get(DOCK_MODEL_STATE_METADATA_KEY)
            retained_history = []
            if isinstance(existing, Mapping):
                retained_history = list(existing.get(DOCK_MODEL_STATE_HISTORY_KEY, []))
            metadata[DOCK_MODEL_STATE_METADATA_KEY] = _new_dock_model_state_container()
            metadata[DOCK_MODEL_STATE_METADATA_KEY][DOCK_MODEL_STATE_HISTORY_KEY] = retained_history
        else:
            metadata.pop(DOCK_MODEL_STATE_METADATA_KEY, None)
        cleared.append(DOCK_MODEL_STATE_METADATA_KEY)
    else:
        container = ensure_dock_model_state_container(model)
        container[DOCK_MODEL_STATE_STATUS_KEY] = DockModelStateStatus.EMPTY.value
        container[DOCK_MODEL_STATE_STALE_REASONS_KEY] = []
        container[DOCK_MODEL_STATE_CURRENT_KEY] = {}
        container[DOCK_MODEL_STATE_STAGE_FINGERPRINTS_KEY] = {}
        if history:
            container[DOCK_MODEL_STATE_HISTORY_KEY] = []
        container[DOCK_MODEL_STATE_UPDATED_AT_KEY] = _utc_timestamp()
    return tuple(unique_preserving_order(cleared))


def invalidate_dock_model_analysis(
    model: Any,
    *,
    reason: Any = "Analysis results were invalidated.",
    clear_cache: bool = True,
    clear_results: bool = False,
) -> DockModelStateReport:
    """Invalidate one model for reanalysis."""

    if clear_results:
        clear_dock_model_analysis_results(model, cache=clear_cache)
        return inspect_dock_model_state(model)
    return mark_dock_model_state_stale(
        model,
        reason,
        invalidate_cache=clear_cache,
    )


# 22.11. Integrated result attachment
# -----------------------------------------------------------------------------


def _pose_result_stage_fingerprints(
    result: PoseAnalysisResult,
) -> Dict[str, str]:
    """Build lightweight fingerprints for completed pose stages."""

    fingerprints: Dict[str, str] = {}
    for stage, stage_result in result.stage_results.items():
        fingerprints[stage] = _state_payload_fingerprint(
            {
                "stage": stage,
                "status": stage_result.status.value,
                "cached": stage_result.cached,
                "output_summary": stage_result.output_summary,
                "statistics": stage_result.statistics,
            }
        )
    return fingerprints


def attach_analysis_stage_result_to_dock_model(
    model: Any,
    stage_result: Any,
    *,
    config: AnalysisConfigLike = None,
    state_config: DockModelStateConfigLike = None,
    run_id: Optional[Any] = None,
) -> DockModelAttachmentRecord:
    """Store one stage result in the unified stage-result mapping and cache."""

    result = _coerce_stage_result(stage_result)
    options = resolve_dock_model_state_config(
        state_config,
        analysis_config=config,
    )
    existing = get_object_value(model, "analysis_stage_results", default={})
    stage_map = dict(existing) if isinstance(existing, Mapping) else {}
    stage_map[result.stage] = result
    record = attach_dock_model_field(
        model,
        "analysis_stage_results",
        stage_map,
        policy=ATTACHMENT_POLICY_REPLACE,
        stage=result.stage,
        run_id=run_id,
        state_config=options,
    )
    if options.cache_enabled:
        put_dock_model_stage_cache(
            model,
            result.stage,
            result,
            config=config,
            result_status=result.status,
            state_config=options,
            metadata={"run_id": normalize_optional_identifier(run_id)},
        )
    return record


def attach_pose_analysis_result_to_dock_model(
    model: Any,
    result: PoseAnalysisResult,
    *,
    config: AnalysisConfigLike = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    state_config: DockModelStateConfigLike = None,
) -> Tuple[DockModelAttachmentRecord, ...]:
    """Attach one complete pose result using a unified mutation policy."""

    if not isinstance(result, PoseAnalysisResult):
        raise TypeError("Pose-result attachment requires PoseAnalysisResult.")
    integrated = coerce_analysis_config(config) if config is not None else None
    options = resolve_dock_model_state_config(
        state_config,
        analysis_config=integrated,
    )
    policy = options.attachment_policy
    records: List[DockModelAttachmentRecord] = []
    run_id = result.metadata.get("run_id") or result.provenance.get("run_id")

    with dock_model_state_transaction(model):
        records.extend(
            attach_interaction_bundle_to_dock_model(
                model,
                result.interactions,
                policy=policy,
                stage=STAGE_CONSOLIDATION,
                run_id=run_id,
                state_config=options,
            )
        )
        if result.scoring is not None:
            records.append(
                attach_dock_model_field(
                    model,
                    "scoring_result",
                    result.scoring,
                    policy=policy,
                    stage=STAGE_SCORING,
                    run_id=run_id,
                    state_config=options,
                )
            )
            score_value = get_first_object_value(
                result.scoring,
                ("total_score", "score", "normalized_score"),
                default=None,
                skip_none=True,
            )
            if score_value is not None:
                records.append(
                    attach_dock_model_field(
                        model,
                        DOCK_MODEL_FIELD_SCORE,
                        float(score_value),
                        policy=ATTACHMENT_POLICY_REPLACE,
                        stage=STAGE_SCORING,
                        run_id=run_id,
                        state_config=options,
                    )
                )
        if result.statistics:
            records.append(
                attach_dock_model_statistics(
                    model,
                    result.statistics,
                    policy=ATTACHMENT_POLICY_MERGE,
                    stage=STAGE_FINALIZATION,
                    run_id=run_id,
                    state_config=options,
                )
            )
        if options.store_files and result.files:
            records.append(
                attach_dock_model_files(
                    model,
                    result.files,
                    policy=ATTACHMENT_POLICY_MERGE,
                    stage=STAGE_FINALIZATION,
                    run_id=run_id,
                    state_config=options,
                )
            )
        metadata_payload: Dict[str, Any] = {
            METADATA_KEY_ANALYSIS_STATUS: result.status.value,
            METADATA_KEY_ANALYSIS_ID: run_id,
            "pose_id": result.pose_id,
            METADATA_KEY_TIMINGS: result.timings,
            METADATA_KEY_PROVENANCE: result.provenance,
        }
        if options.store_diagnostics:
            metadata_payload[METADATA_KEY_DIAGNOSTICS] = result.diagnostics.to_dict()
        records.append(
            attach_dock_model_metadata(
                model,
                metadata_payload,
                policy=ATTACHMENT_POLICY_MERGE,
                stage=STAGE_FINALIZATION,
                run_id=run_id,
                state_config=options,
            )
        )
        if options.store_stage_results:
            for stage_result in result.stage_results.values():
                records.append(
                    attach_analysis_stage_result_to_dock_model(
                        model,
                        stage_result,
                        config=integrated,
                        state_config=options,
                        run_id=run_id,
                    )
                )
        if options.store_full_result:
            records.append(
                attach_dock_model_field(
                    model,
                    "analysis_result",
                    result,
                    policy=ATTACHMENT_POLICY_REPLACE,
                    stage=STAGE_FINALIZATION,
                    run_id=run_id,
                    state_config=options,
                )
            )
        append_dock_model_analysis_history(model, result, state_config=options)

        config_fingerprint = integrated.fingerprint() if integrated else None
        pipeline_value = (
            execution_plan_fingerprint(execution_plan)
            if execution_plan is not None
            else f"pipeline:{ANALYSIS_PIPELINE_VERSION}"
        )
        state_status = (
            DockModelStateStatus.CURRENT
            if result.status == AnalysisStatus.SUCCEEDED
            else DockModelStateStatus.PARTIAL
            if result.status == AnalysisStatus.PARTIAL
            else DockModelStateStatus.INVALID
        )
        update_dock_model_current_state(
            model,
            status=state_status,
            run_id=run_id,
            pose_id=result.pose_id,
            config_fingerprint=config_fingerprint,
            pipeline_fingerprint=pipeline_value,
            result_fingerprint=build_dock_model_result_fingerprint(model),
            stage_fingerprints=_pose_result_stage_fingerprints(result),
        )
    return tuple(records)


def attach_analysis_run_result_to_dock_models(
    result: AnalysisRunResult,
    *,
    config: AnalysisConfigLike = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    state_config: DockModelStateConfigLike = None,
) -> Dict[str, Tuple[DockModelAttachmentRecord, ...]]:
    """Attach all pose results from one run to their DockModel objects."""

    if not isinstance(result, AnalysisRunResult):
        raise TypeError("Run-result attachment requires AnalysisRunResult.")
    attached: Dict[str, Tuple[DockModelAttachmentRecord, ...]] = {}
    for pose_result in result.pose_results:
        model = pose_result.dock_model
        if model is None:
            continue
        pose_result.metadata.setdefault("run_id", result.run_id)
        attached[pose_result.pose_id] = attach_pose_analysis_result_to_dock_model(
            model,
            pose_result,
            config=config,
            execution_plan=execution_plan,
            state_config=state_config,
        )
    return attached


def synchronize_analysis_context_to_dock_models(
    context: AnalysisContext,
    *,
    pose_results: Optional[Iterable[PoseAnalysisResult]] = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    state_config: DockModelStateConfigLike = None,
) -> Dict[str, Tuple[DockModelAttachmentRecord, ...]]:
    """Attach context-backed pose results to their corresponding models."""

    if not isinstance(context, AnalysisContext):
        raise TypeError("Context synchronization requires AnalysisContext.")
    results = list(pose_results or context.get_shared("pose_results", []))
    attached: Dict[str, Tuple[DockModelAttachmentRecord, ...]] = {}
    by_model = {id(result.dock_model): result for result in results if result.dock_model is not None}
    for model in context.dock_models:
        result = by_model.get(id(model))
        if result is None:
            continue
        result.metadata.setdefault("run_id", context.run_id)
        attached[result.pose_id] = attach_pose_analysis_result_to_dock_model(
            model,
            result,
            config=context.config,
            execution_plan=execution_plan,
            state_config=state_config,
        )
    context.set_shared("dock_model_attachments", attached)
    return attached


# 22.12. Inspection, validation and summaries
# -----------------------------------------------------------------------------


def inspect_dock_model_state(model: Any) -> DockModelStateReport:
    """Return a comprehensive analysis-state report for one DockModel."""

    issues: List[str] = []
    identity = describe_object(model)
    try:
        state = ensure_dock_model_state_container(model)
    except Exception as exc:
        return DockModelStateReport(
            model_name=identity.name,
            model_identifier=identity.identifier,
            status=DockModelStateStatus.INVALID,
            issues=(str(exc),),
        )
    cache = ensure_dock_model_cache_container(model)
    current = state.get(DOCK_MODEL_STATE_CURRENT_KEY, {})
    if not isinstance(current, Mapping):
        current = {}
        issues.append("The current state descriptor is not a mapping.")
    try:
        status = canonicalize_dock_model_state_status(
            state.get(DOCK_MODEL_STATE_STATUS_KEY, DockModelStateStatus.EMPTY)
        )
    except ValueError:
        status = DockModelStateStatus.INVALID
        issues.append("The stored state status is invalid.")
    entries = cache.get(DOCK_MODEL_CACHE_ENTRIES_KEY, {})
    return DockModelStateReport(
        model_name=identity.name,
        model_identifier=identity.identifier,
        status=status,
        current_fingerprint=(
            current.get("current_fingerprint") or state.get("current_fingerprint")
        ),
        input_fingerprint=current.get(DOCK_MODEL_STATE_INPUT_FINGERPRINT_KEY),
        config_fingerprint=current.get(DOCK_MODEL_STATE_CONFIG_FINGERPRINT_KEY),
        pipeline_fingerprint=current.get(DOCK_MODEL_STATE_PIPELINE_FINGERPRINT_KEY),
        result_fingerprint=current.get(DOCK_MODEL_STATE_RESULT_FINGERPRINT_KEY),
        stale_reasons=tuple(
            normalize_string_sequence(
                state.get(DOCK_MODEL_STATE_STALE_REASONS_KEY),
                skip_blank=True,
            )
        ),
        generation=state.get(DOCK_MODEL_STATE_GENERATION_KEY, 0),
        history_count=len(state.get(DOCK_MODEL_STATE_HISTORY_KEY, [])),
        attachment_count=len(state.get(DOCK_MODEL_STATE_ATTACHMENTS_KEY, [])),
        cache_entries=len(entries) if isinstance(entries, Mapping) else 0,
        cache_hits=cache.get(DOCK_MODEL_CACHE_HITS_KEY, 0),
        cache_misses=cache.get(DOCK_MODEL_CACHE_MISSES_KEY, 0),
        cache_stale=cache.get(DOCK_MODEL_CACHE_STALE_KEY, 0),
        cache_evictions=cache.get(DOCK_MODEL_CACHE_EVICTIONS_KEY, 0),
        existing_results=inspect_dock_model_existing_results(model),
        updated_at=state.get(DOCK_MODEL_STATE_UPDATED_AT_KEY),
        issues=tuple(issues),
    )


def validate_dock_model_state(
    model: Any,
    *,
    config: AnalysisConfigLike = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    state_config: DockModelStateConfigLike = None,
) -> Tuple[str, ...]:
    """Return validation errors for one attached analysis state."""

    report = inspect_dock_model_state(model)
    errors = list(report.issues)
    metadata = get_object_value(model, DOCK_MODEL_FIELD_METADATA, default=None)
    statistics = get_object_value(model, DOCK_MODEL_FIELD_STATISTICS, default=None)
    files_value = get_object_value(model, DOCK_MODEL_FIELD_FILES, default=None)
    if not isinstance(metadata, Mapping):
        errors.append("DockModel metadata is not a mapping.")
    if not isinstance(statistics, Mapping):
        errors.append("DockModel statistics is not a mapping.")
    if not isinstance(files_value, Mapping):
        errors.append("DockModel files is not a mapping.")
    stale_reasons = detect_dock_model_stale_reasons(
        model,
        config=config,
        execution_plan=execution_plan,
        state_config=state_config,
    )
    if report.status == DockModelStateStatus.CURRENT and stale_reasons:
        errors.append(
            "The DockModel is marked current but its fingerprints are stale."
        )
    cache = ensure_dock_model_cache_container(model)
    entries = cache.get(DOCK_MODEL_CACHE_ENTRIES_KEY, {})
    if not isinstance(entries, Mapping):
        errors.append("The DockModel cache entries container is invalid.")
    else:
        for key, raw in entries.items():
            entry = _coerce_dock_model_cache_entry(raw, cache_key=str(key))
            if entry is None:
                errors.append(f"Cache entry {key!r} is invalid.")
    return tuple(unique_preserving_order(errors))


def summarize_dock_model_state(model: Any) -> Dict[str, Any]:
    """Return a concise state summary."""

    report = inspect_dock_model_state(model)
    return {
        "model": report.model_name,
        "status": report.status.value,
        "generation": report.generation,
        "existing_results": list(report.existing_results),
        "history_count": report.history_count,
        "attachment_count": report.attachment_count,
        "cache_entries": report.cache_entries,
        "cache_hits": report.cache_hits,
        "cache_misses": report.cache_misses,
        "stale_reasons": list(report.stale_reasons),
        "updated_at": report.updated_at,
    }


def dock_model_state_to_json(
    model: Any,
    *,
    indent: Optional[int] = 2,
) -> str:
    """Serialize one DockModel state report to JSON."""

    return json.dumps(
        inspect_dock_model_state(model).to_dict(),
        indent=indent,
        sort_keys=True,
        ensure_ascii=False,
    )


# 22.13. Internal convention validation
# -----------------------------------------------------------------------------


def validate_dock_model_state_management_conventions() -> Dict[str, Any]:
    """Validate mutation, history, staleness, cache and rollback behavior."""

    failures: List[str] = []
    model = DockModel(name="state_validation_pose")
    model.receptor = SimpleNamespace(name="receptor", atoms=[1, 2, 3])
    model.pose = SimpleNamespace(name="pose", atoms=[4, 5])
    model.ligand = SimpleNamespace(name="ligand", atoms=[4, 5])

    default_config = DockModelStateConfig()
    if len(default_config.fingerprint) != 64:
        failures.append("State configuration fingerprint is invalid.")
    if canonicalize_dock_model_state_status("fresh") != DockModelStateStatus.CURRENT:
        failures.append("DockModel state-status alias resolution failed.")

    record = attach_dock_model_field(
        model,
        "temporary_result",
        {"a": 1},
        policy="replace",
        state_config=default_config,
    )
    if not record.changed or getattr(model, "temporary_result", None) != {"a": 1}:
        failures.append("Generic DockModel field attachment failed.")
    merge_record = attach_dock_model_field(
        model,
        "temporary_result",
        {"b": 2},
        policy="merge",
        state_config=default_config,
    )
    if not merge_record.changed or getattr(model, "temporary_result", None) != {"a": 1, "b": 2}:
        failures.append("DockModel mapping merge failed.")
    preserve_record = attach_dock_model_field(
        model,
        "temporary_result",
        {"c": 3},
        policy="preserve",
        state_config=default_config,
    )
    if preserve_record.changed or getattr(model, "temporary_result", None) != {"a": 1, "b": 2}:
        failures.append("DockModel preserve policy failed.")

    snapshot = snapshot_dock_model_state(
        model,
        fields_to_capture=("temporary_result",),
    )
    try:
        with dock_model_state_transaction(
            model,
            fields_to_capture=("temporary_result",),
        ):
            model.temporary_result = {"broken": True}
            raise RuntimeError("rollback test")
    except RuntimeError:
        pass
    if model.temporary_result != snapshot.values["temporary_result"]:
        failures.append("DockModel transaction rollback failed.")

    stage_result = AnalysisStageResult(
        stage=STAGE_CONTACTS,
        status=StageStatus.SUCCEEDED,
        value={"contacts": [1]},
        started_at=_utc_timestamp(),
        finished_at=_utc_timestamp(),
    )
    cache_entry = put_dock_model_stage_cache(
        model,
        STAGE_CONTACTS,
        stage_result,
        state_config=default_config,
    )
    if cache_entry is None:
        failures.append("Stage cache insertion failed.")
    lookup = get_dock_model_stage_cache(
        model,
        STAGE_CONTACTS,
        cache_key=cache_entry.cache_key if cache_entry else None,
        state_config=default_config,
    )
    if not lookup.hit or lookup.value is not stage_result:
        failures.append("Stage cache lookup failed.")

    bundle = InteractionAnalysisBundle(contacts=[SimpleNamespace(distance=3.1)])
    pose_result = PoseAnalysisResult(
        pose_id="state_pose",
        name="state_pose",
        status=AnalysisStatus.SUCCEEDED,
        dock_model=model,
        receptor=model.receptor,
        ligand=model.ligand,
        pose=model.pose,
        interactions=bundle,
        stage_results=OrderedDict([(STAGE_CONTACTS, stage_result)]),
        scoring=SimpleNamespace(total_score=1.5),
        statistics={"example": 1},
        metadata={"run_id": "state_run"},
    )
    pose_result.finalize(AnalysisStatus.SUCCEEDED)
    attachments = attach_pose_analysis_result_to_dock_model(
        model,
        pose_result,
        state_config=default_config,
    )
    if not attachments:
        failures.append("Pose-result attachment returned no records.")
    report = inspect_dock_model_state(model)
    if report.status != DockModelStateStatus.CURRENT:
        failures.append("Attached pose result did not produce current state.")
    if report.history_count < 1:
        failures.append("Analysis history was not recorded.")
    if report.cache_entries < 1:
        failures.append("Stage cache was not retained.")
    if validate_dock_model_state(model):
        failures.append("Attached DockModel state failed validation.")

    stale = mark_dock_model_state_stale(model, "validation change", invalidate_cache=False)
    if stale.status != DockModelStateStatus.STALE:
        failures.append("DockModel stale marking failed.")
    cleared = clear_dock_model_analysis_results(
        model,
        interactions=True,
        scoring=True,
        statistics=True,
        cache=True,
    )
    if not cleared:
        failures.append("DockModel analysis cleanup reported no changes.")

    if failures:
        raise RuntimeError(
            "DockModel state-management convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": DOCK_MODEL_STATE_SCHEMA_NAME,
        "schema_version": DOCK_MODEL_STATE_SCHEMA_VERSION,
        "validated_cases": 30,
        "public_state_statuses": len(DockModelStateStatus),
        "cache_statuses": len(DockModelCacheLookupStatus),
    }


