REPORT_SHARED_DOCUMENT_KEY: Final[str] = "report_document"
REPORT_SHARED_ARTIFACTS_KEY: Final[str] = "report_artifacts"
REPORT_STATISTICS_KEY: Final[str] = "reporting"
REPORT_METADATA_KEY: Final[str] = "reporting"
REPORT_DOCK_MODEL_FIELD: Final[str] = "report"
REPORT_DOCK_MODEL_COLLECTION_FIELD: Final[str] = "reports"
REPORT_DEFAULT_BASENAME: Final[str] = "dockanalyzer_report"
