REPORT_SUPPORTED_FORMATS: Final[Tuple[str, ...]] = (
    "text",
    "markdown",
    "html",
    "json",
)
REPORT_FORMAT_SUFFIXES: Final[Mapping[str, str]] = MappingProxyType(
    {
        "text": ".txt",
        "markdown": ".md",
        "html": ".html",
        "json": ".json",
    }
)
REPORT_FORMAT_ALIASES: Final[Mapping[str, str]] = MappingProxyType(
    {
        "text": "text",
        "txt": "text",
        ".txt": "text",
        "plain": "text",
        "plain_text": "text",
        "markdown": "markdown",
        "md": "markdown",
        ".md": "markdown",
        "html": "html",
        "htm": "html",
        ".html": "html",
        ".htm": "html",
        "json": "json",
        ".json": "json",
    }
)
REPORT_REQUIRED_SYMBOLS: Final[Tuple[str, ...]] = (
    "ReportConfig",
    "ReportDocument",
    "create_report",
    "render_report",
    "validate_report",
)
REPORT_OPTIONAL_SYMBOLS: Final[Tuple[str, ...]] = (
    "create_pose_report",
    "create_multipose_report",
    "configure_report",
    "write_report",
    "write_report_formats",
    "save_dock_report",
    "save_dock_report_formats",
    "report_summary",
    "WriteConfig",
    "WriteResult",
)
REPORT_ATTACHMENT_MODES: Final[FrozenSet[str]] = frozenset(
    {ATTACHMENT_POLICY_REPLACE, ATTACHMENT_POLICY_MERGE, ATTACHMENT_POLICY_PRESERVE, ATTACHMENT_POLICY_NONE}
)
REPORT_DOCUMENT_REUSE_FIELDS: Final[Tuple[str, ...]] = (
    REPORT_DOCK_MODEL_FIELD,
    REPORT_DOCK_MODEL_COLLECTION_FIELD,
)
DEFAULT_REPORT_BUILD_DOCUMENT: Final[bool] = True
DEFAULT_REPORT_RENDER_CONTENT: Final[bool] = True
DEFAULT_REPORT_WRITE_FILES: Final[bool] = True
DEFAULT_REPORT_ATTACH_RESULT: Final[bool] = True
DEFAULT_REPORT_REUSE_RESULT: Final[bool] = True
DEFAULT_REPORT_VALIDATE_DOCUMENT: Final[bool] = True
DEFAULT_REPORT_STRICT_VALIDATION: Final[bool] = False
DEFAULT_REPORT_INCLUDE_RENDERED_CONTENT: Final[bool] = True
DEFAULT_REPORT_CALCULATE_CHECKSUM: Final[bool] = False
DEFAULT_REPORT_ENSURE_SUFFIX: Final[bool] = True
DEFAULT_REPORT_ATOMIC_WRITE: Final[bool] = True
DEFAULT_REPORT_BACKUP: Final[bool] = False
MAX_REPORT_RENDERED_CHARACTERS: Final[int] = 20_000_000
MAX_REPORT_FORMAT_COUNT: Final[int] = len(REPORT_SUPPORTED_FORMATS)


class ReportTargetKind(str, Enum):
    """Canonical source category used to build a report."""

    POSE = "pose"
    MULTIPOSE = "multipose"
    BATCH = "batch"
    RUN = "run"
    DOCK_MODEL = "dock_model"
    GENERIC = "generic"


class ReportArtifactStatus(str, Enum):
    """Lifecycle status of one rendered or written report artifact."""

    PENDING = "pending"
    RENDERED = "rendered"
    WRITTEN = "written"
    REUSED = "reused"
    SKIPPED = "skipped"
    FAILED = "failed"


# 23.2. Format and mode normalization
# -----------------------------------------------------------------------------


def canonicalize_report_format(value: Any) -> str:
    """Return a canonical report format."""

    token = normalize_text(value, default="").strip().lower().replace("-", "_")
    canonical = REPORT_FORMAT_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported report format: {value!r}.",
            stage=STAGE_REPORT,
            code="unsupported_report_format",
            details={"format": str(value), "supported": list(REPORT_SUPPORTED_FORMATS)},
        )
    return canonical


def canonicalize_report_formats(
    values: Any,
    *,
    default: Sequence[str] = (DEFAULT_REPORT_FORMAT,),
) -> Tuple[str, ...]:
    """Return unique canonical report formats in declaration order."""

    if values is None:
        values = default
    if isinstance(values, (str, bytes, os.PathLike)):
        values = (values,)
    try:
        items = tuple(values)
    except TypeError as exc:
        raise AnalysisConfigurationError(
            "Report formats must be a string or iterable of strings.",
            stage=STAGE_REPORT,
            code="invalid_report_formats",
            cause=exc,
        ) from exc
    normalized: List[str] = []
    for item in items:
        name = canonicalize_report_format(item)
        if name not in normalized:
            normalized.append(name)
    if not normalized:
        normalized = [canonicalize_report_format(item) for item in default]
    if len(normalized) > MAX_REPORT_FORMAT_COUNT:
        raise AnalysisConfigurationError(
            "Too many report formats were requested.",
            stage=STAGE_REPORT,
            code="report_format_limit_exceeded",
            details={"count": len(normalized), "limit": MAX_REPORT_FORMAT_COUNT},
        )
    return tuple(normalized)


def canonicalize_report_attachment_mode(value: Any) -> str:
    """Return a supported report attachment mode."""

    mode = canonicalize_attachment_policy(value)
    if mode not in REPORT_ATTACHMENT_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported report attachment mode: {value!r}.",
            stage=STAGE_REPORT,
            code="unsupported_report_attachment_mode",
        )
    return mode


def canonicalize_report_target_kind(value: Any) -> ReportTargetKind:
    """Return a canonical report target kind."""

    if isinstance(value, ReportTargetKind):
        return value
    token = normalize_text(value, default="generic").strip().lower().replace("-", "_")
    aliases = {
        "single": ReportTargetKind.POSE,
        "single_pose": ReportTargetKind.POSE,
        "pose": ReportTargetKind.POSE,
        "multipose": ReportTargetKind.MULTIPOSE,
        "multi_pose": ReportTargetKind.MULTIPOSE,
        "poses": ReportTargetKind.MULTIPOSE,
        "batch": ReportTargetKind.BATCH,
        "run": ReportTargetKind.RUN,
        "analysis_run": ReportTargetKind.RUN,
        "dockmodel": ReportTargetKind.DOCK_MODEL,
        "dock_model": ReportTargetKind.DOCK_MODEL,
        "model": ReportTargetKind.DOCK_MODEL,
        "generic": ReportTargetKind.GENERIC,
    }
    return aliases.get(token, ReportTargetKind.GENERIC)


# 23.3. Integration configuration
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ReportIntegrationConfig:
    """Control report construction, rendering, writing and attachment."""

    formats: Tuple[str, ...] = (DEFAULT_REPORT_FORMAT,)
    build_document: bool = DEFAULT_REPORT_BUILD_DOCUMENT
    render_content: bool = DEFAULT_REPORT_RENDER_CONTENT
    write_files: bool = DEFAULT_REPORT_WRITE_FILES
    attach_result: bool = DEFAULT_REPORT_ATTACH_RESULT
    reuse_result: bool = DEFAULT_REPORT_REUSE_RESULT
    validate_document: bool = DEFAULT_REPORT_VALIDATE_DOCUMENT
    strict_validation: bool = DEFAULT_REPORT_STRICT_VALIDATION
    include_rendered_content: bool = DEFAULT_REPORT_INCLUDE_RENDERED_CONTENT
    calculate_checksum: bool = DEFAULT_REPORT_CALCULATE_CHECKSUM
    ensure_suffix: bool = DEFAULT_REPORT_ENSURE_SUFFIX
    output_directory: Optional[Path] = None
    basename: str = REPORT_DEFAULT_BASENAME
    title: Optional[str] = None
    subtitle: Optional[str] = None
    description: Optional[str] = None
    overwrite: bool = DEFAULT_OUTPUT_OVERWRITE
    create_directories: bool = DEFAULT_OUTPUT_CREATE_DIRECTORIES
    atomic_write: bool = DEFAULT_REPORT_ATOMIC_WRITE
    backup: bool = DEFAULT_REPORT_BACKUP
    update_dock_model_files: bool = DEFAULT_UPDATE_DOCK_MODEL_FILES
    attachment_mode: str = ATTACHMENT_POLICY_REPLACE
    report_options: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "formats", canonicalize_report_formats(self.formats))
        for name in (
            "build_document",
            "render_content",
            "write_files",
            "attach_result",
            "reuse_result",
            "validate_document",
            "strict_validation",
            "include_rendered_content",
            "calculate_checksum",
            "ensure_suffix",
            "overwrite",
            "create_directories",
            "atomic_write",
            "backup",
            "update_dock_model_files",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        directory = self.output_directory
        if directory is not None:
            try:
                directory = Path(directory).expanduser()
            except (TypeError, ValueError, OSError) as exc:
                raise AnalysisConfigurationError(
                    "The report output directory is invalid.",
                    stage=STAGE_REPORT,
                    code="invalid_report_output_directory",
                    cause=exc,
                ) from exc
            object.__setattr__(self, "output_directory", directory)
        basename = normalize_text(self.basename, default=REPORT_DEFAULT_BASENAME)
        basename = re.sub(r"[^A-Za-z0-9._-]+", "_", basename).strip("._")
        object.__setattr__(self, "basename", basename or REPORT_DEFAULT_BASENAME)
        for name in ("title", "subtitle", "description"):
            value = getattr(self, name)
            object.__setattr__(self, name, None if value is None else normalize_text(value, default=""))
        object.__setattr__(
            self,
            "attachment_mode",
            canonicalize_report_attachment_mode(self.attachment_mode),
        )
        if not isinstance(self.report_options, Mapping):
            raise AnalysisConfigurationError(
                "Report options must be a mapping.",
                stage=STAGE_REPORT,
                code="invalid_report_options",
            )
        if not isinstance(self.metadata, Mapping):
            raise AnalysisConfigurationError(
                "Report metadata must be a mapping.",
                stage=STAGE_REPORT,
                code="invalid_report_metadata",
            )
        object.__setattr__(self, "report_options", MappingProxyType(dict(self.report_options)))
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))
        if self.write_files and self.output_directory is None:
            object.__setattr__(self, "write_files", False)
        if not self.build_document:
            object.__setattr__(self, "render_content", False)
            object.__setattr__(self, "write_files", False)
        if self.write_files:
            object.__setattr__(self, "render_content", True)

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "ReportIntegrationConfig":
        """Create report integration configuration from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Report integration configuration must be a mapping.",
                stage=STAGE_REPORT,
                code="invalid_report_integration_config",
            )
        aliases = {
            "format": "formats",
            "report_formats": "formats",
            "build": "build_document",
            "render": "render_content",
            "write": "write_files",
            "attach": "attach_result",
            "reuse": "reuse_result",
            "validate": "validate_document",
            "strict": "strict_validation",
            "include_content": "include_rendered_content",
            "checksum": "calculate_checksum",
            "directory": "output_directory",
            "output_dir": "output_directory",
            "prefix": "basename",
            "file_prefix": "basename",
            "atomic": "atomic_write",
            "create_parents": "create_directories",
            "update_files": "update_dock_model_files",
            "mode": "attachment_mode",
            "options": "report_options",
        }
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        for raw_name, value in values.items():
            token = str(raw_name).strip().lower().replace("-", "_")
            name = aliases.get(token, token)
            if name not in allowed:
                if strict:
                    raise AnalysisConfigurationError(
                        f"Unknown report integration option: {raw_name!r}.",
                        stage=STAGE_REPORT,
                        code="unknown_report_integration_option",
                    )
                continue
            normalized[name] = value
        return cls(**normalized)

    @property
    def fingerprint(self) -> str:
        """Return a stable configuration fingerprint."""

        payload = json.dumps(
            to_json_compatible(self.to_dict()),
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
        return sha256(payload.encode("utf-8")).hexdigest()

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready representation."""

        return {
            "formats": list(self.formats),
            "build_document": self.build_document,
            "render_content": self.render_content,
            "write_files": self.write_files,
            "attach_result": self.attach_result,
            "reuse_result": self.reuse_result,
            "validate_document": self.validate_document,
            "strict_validation": self.strict_validation,
            "include_rendered_content": self.include_rendered_content,
            "calculate_checksum": self.calculate_checksum,
            "ensure_suffix": self.ensure_suffix,
            "output_directory": str(self.output_directory) if self.output_directory is not None else None,
            "basename": self.basename,
            "title": self.title,
            "subtitle": self.subtitle,
            "description": self.description,
            "overwrite": self.overwrite,
            "create_directories": self.create_directories,
            "atomic_write": self.atomic_write,
            "backup": self.backup,
            "update_dock_model_files": self.update_dock_model_files,
            "attachment_mode": self.attachment_mode,
            "report_options": to_json_compatible(dict(self.report_options)),
            "metadata": to_json_compatible(dict(self.metadata)),
        }


ReportIntegrationConfigLike: TypeAlias = Union[
    ReportIntegrationConfig,
    AnalysisConfig,
    Mapping[str, Any],
    None,
]


def _report_stage_parameter_mapping(config: AnalysisConfig) -> Mapping[str, Any]:
    """Return report-stage parameters from an integrated configuration."""

    stage_config = config.stage_configs.get(STAGE_REPORT)
    if stage_config is None:
        return MappingProxyType({})
    return stage_config.parameters


def resolve_report_integration_config(
    config: ReportIntegrationConfigLike = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    strict: bool = False,
) -> ReportIntegrationConfig:
    """Resolve report controls from direct or integrated configuration."""

    if isinstance(config, ReportIntegrationConfig):
        base = config.to_dict()
    elif isinstance(config, AnalysisConfig):
        output = config.output
        stage = config.stage_configs.get(STAGE_REPORT)
        base = {
            "formats": output.report_formats,
            "build_document": True,
            "render_content": True,
            "write_files": bool(output.generate_report and output.output_directory is not None),
            "attach_result": True if stage is None else stage.attach_results,
            "reuse_result": True if stage is None else stage.reuse_result,
            "validate_document": True if stage is None else stage.validate_result,
            "strict_validation": config.runtime.is_strict,
            "include_rendered_content": True,
            "output_directory": output.output_directory,
            "basename": output.file_prefix or REPORT_DEFAULT_BASENAME,
            "overwrite": output.overwrite,
            "create_directories": output.create_directories,
            "update_dock_model_files": output.update_dock_model_files,
            "report_options": dict(output.report_options),
            "metadata": dict(output.metadata),
        }
        base.update(dict(_report_stage_parameter_mapping(config)))
        module_values = config.module_configs.get(REPORT_INTEGRATION_MODULE_NAME)
        if isinstance(module_values, Mapping):
            base.update(dict(module_values))
    elif isinstance(config, Mapping):
        base = dict(config)
    elif config is None:
        base = {}
    else:
        raise AnalysisConfigurationError(
            "Unsupported report integration configuration value.",
            stage=STAGE_REPORT,
            code="unsupported_report_integration_config",
            details={"type": type(config).__name__},
        )
    if overrides:
        base.update(dict(overrides))
    return ReportIntegrationConfig.from_mapping(base, strict=strict)


# 23.4. Target and artifact records
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ReportStageTarget:
    """Resolved source and model collection for report construction."""

    source: Any
    kind: ReportTargetKind = ReportTargetKind.GENERIC
    dock_models: Tuple[Any, ...] = ()
    name: str = "analysis"
    identifier: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "kind", canonicalize_report_target_kind(self.kind))
        object.__setattr__(self, "dock_models", tuple(self.dock_models))
        object.__setattr__(self, "name", normalize_text(self.name, default="analysis"))
        identifier = self.identifier
        if identifier is not None:
            identifier = normalize_text(identifier, default="") or None
        object.__setattr__(self, "identifier", identifier)
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    def to_dict(self) -> Dict[str, Any]:
        """Return a safe target description."""

        return {
            "kind": self.kind.value,
            "name": self.name,
            "identifier": self.identifier,
            "dock_model_count": len(self.dock_models),
            "source_type": type(self.source).__name__,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass
class ReportArtifact:
    """Rendered and optionally written representation of one report format."""

    format: str
    status: Union[ReportArtifactStatus, str] = ReportArtifactStatus.PENDING
    content: Optional[str] = None
    path: Optional[str] = None
    bytes_written: Optional[int] = None
    checksum: Optional[str] = None
    mime_type: Optional[str] = None
    encoding: Optional[str] = None
    backup_path: Optional[str] = None
    overwritten: bool = False
    atomic: Optional[bool] = None
    error: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.format = canonicalize_report_format(self.format)
        if not isinstance(self.status, ReportArtifactStatus):
            self.status = ReportArtifactStatus(str(self.status).strip().lower())
        if self.content is not None:
            self.content = str(self.content)
        if self.path is not None:
            self.path = str(self.path)
        if self.bytes_written is not None:
            self.bytes_written = max(0, int(self.bytes_written))
        self.overwritten = bool(self.overwritten)
        self.metadata = dict(self.metadata)

    @property
    def rendered(self) -> bool:
        """Return whether content was rendered or written."""

        return self.status in {
            ReportArtifactStatus.RENDERED,
            ReportArtifactStatus.WRITTEN,
            ReportArtifactStatus.REUSED,
        }

    @property
    def written(self) -> bool:
        """Return whether an output file exists for this artifact."""

        return self.status is ReportArtifactStatus.WRITTEN and bool(self.path)

    @property
    def character_count(self) -> int:
        """Return the rendered character count."""

        return len(self.content or "")

    def to_dict(self, *, include_content: bool = True) -> Dict[str, Any]:
        """Return a serialization-ready artifact representation."""

        data = {
            "format": self.format,
            "status": self.status.value,
            "path": self.path,
            "bytes_written": self.bytes_written,
            "checksum": self.checksum,
            "mime_type": self.mime_type,
            "encoding": self.encoding,
            "backup_path": self.backup_path,
            "overwritten": self.overwritten,
            "atomic": self.atomic,
            "error": self.error,
            "character_count": self.character_count,
            "metadata": to_json_compatible(self.metadata),
        }
        if include_content:
            data["content"] = self.content
        return data


@dataclass
class ReportStageOutput:
    """Integrated result of report construction, rendering and writing."""

    target: ReportStageTarget
    config: ReportIntegrationConfig
    document: Any = None
    artifacts: MutableMapping[str, ReportArtifact] = field(default_factory=OrderedDict)
    validation: Any = None
    attached: bool = False
    reused: bool = False
    messages: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    statistics: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    started_at: str = field(default_factory=_utc_timestamp)
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    schema_name: str = REPORT_INTEGRATION_SCHEMA_NAME
    schema_version: str = REPORT_INTEGRATION_SCHEMA_VERSION
    result_type: str = REPORT_INTEGRATION_RESULT_TYPE

    def __post_init__(self) -> None:
        if not isinstance(self.target, ReportStageTarget):
            raise TypeError("ReportStageOutput.target must be ReportStageTarget.")
        if not isinstance(self.config, ReportIntegrationConfig):
            self.config = resolve_report_integration_config(self.config)
        normalized: MutableMapping[str, ReportArtifact] = OrderedDict()
        for key, value in dict(self.artifacts).items():
            artifact = value if isinstance(value, ReportArtifact) else ReportArtifact(format=key, **dict(value))
            normalized[artifact.format] = artifact
        self.artifacts = normalized
        self.attached = bool(self.attached)
        self.reused = bool(self.reused)
        self.messages = [str(item) for item in self.messages if str(item).strip()]
        self.warnings = [str(item) for item in self.warnings if str(item).strip()]
        self.errors = [str(item) for item in self.errors if str(item).strip()]
        self.statistics = dict(self.statistics)
        self.metadata = dict(self.metadata)

    @property
    def succeeded(self) -> bool:
        """Return whether the output has a document and no errors."""

        return self.document is not None and not self.errors

    @property
    def written_files(self) -> Dict[str, str]:
        """Return format-to-path mappings for written artifacts."""

        return {
            name: artifact.path
            for name, artifact in self.artifacts.items()
            if artifact.written and artifact.path is not None
        }

    @property
    def rendered_formats(self) -> Tuple[str, ...]:
        """Return formats with rendered or written artifacts."""

        return tuple(name for name, artifact in self.artifacts.items() if artifact.rendered)

    @property
    def written_formats(self) -> Tuple[str, ...]:
        """Return formats written to disk."""

        return tuple(name for name, artifact in self.artifacts.items() if artifact.written)

    def summary(self) -> str:
        """Return a concise human-readable summary."""

        return (
            f"Report for {self.target.name}: {len(self.rendered_formats)} rendered, "
            f"{len(self.written_formats)} written, {len(self.warnings)} warnings and "
            f"{len(self.errors)} errors"
        )

    def to_dict(
        self,
        *,
        include_document: bool = True,
        include_content: Optional[bool] = None,
    ) -> Dict[str, Any]:
        """Return a serialization-ready report-stage representation."""

        if include_content is None:
            include_content = self.config.include_rendered_content
        document = None
        if include_document and self.document is not None:
            converter = getattr(self.document, "to_dict", None)
            if callable(converter):
                try:
                    document = converter()
                except Exception:
                    document = to_json_compatible(self.document)
            else:
                document = to_json_compatible(self.document)
            document = to_json_compatible(document)
        validation = self.validation
        converter = getattr(validation, "to_dict", None)
        if callable(converter):
            try:
                validation = converter()
            except Exception:
                validation = to_json_compatible(validation)
        return {
            "schema_name": self.schema_name,
            "schema_version": self.schema_version,
            "result_type": self.result_type,
            "target": self.target.to_dict(),
            "config": self.config.to_dict(),
            "document": document,
            "artifacts": {
                key: value.to_dict(include_content=bool(include_content))
                for key, value in self.artifacts.items()
            },
            "validation": to_json_compatible(validation),
            "attached": self.attached,
            "reused": self.reused,
            "messages": list(self.messages),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "statistics": to_json_compatible(self.statistics),
            "metadata": to_json_compatible(self.metadata),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "summary": self.summary(),
        }

    def to_json(self, *, indent: Optional[int] = 2) -> str:
        """Return the output as JSON."""

        return json.dumps(self.to_dict(), indent=indent, sort_keys=True, ensure_ascii=False)


# 23.5. Module loading and interface inspection
# -----------------------------------------------------------------------------


def _require_report_module(module: Optional[ModuleType] = None) -> ModuleType:
    """Return a validated report module."""

    resolved = module or load_analysis_module(REPORT_INTEGRATION_MODULE_NAME, required=True)
    if resolved is None:
        raise AnalysisDependencyError(
            "The report module is unavailable.",
            stage=STAGE_REPORT,
            code="report_module_unavailable",
        )
    missing = tuple(name for name in REPORT_REQUIRED_SYMBOLS if not hasattr(resolved, name))
    if missing:
        raise AnalysisCapabilityError(
            "The report module is missing required public symbols: " + ", ".join(missing),
            stage=STAGE_REPORT,
            code="report_interface_invalid",
            details={"missing_symbols": list(missing)},
        )
    return resolved


def inspect_report_integration_capabilities(
    module: Optional[ModuleType] = None,
) -> Dict[str, Any]:
    """Return report-module capabilities relevant to orchestration."""

    try:
        resolved = _require_report_module(module)
    except AnalysisError as exc:
        return {
            "available": False,
            "error": str(exc),
            "required_symbols": list(REPORT_REQUIRED_SYMBOLS),
            "optional_symbols": [],
            "formats": [],
        }
    optional = [name for name in REPORT_OPTIONAL_SYMBOLS if hasattr(resolved, name)]
    native_formats = getattr(resolved, "SUPPORTED_REPORT_FORMATS", REPORT_SUPPORTED_FORMATS)
    formats: List[str] = []
    for value in native_formats:
        try:
            canonical = canonicalize_report_format(getattr(value, "value", value))
        except AnalysisError:
            continue
        if canonical not in formats:
            formats.append(canonical)
    return {
        "available": True,
        "module": getattr(resolved, "__name__", REPORT_INTEGRATION_MODULE_NAME),
        "version": getattr(resolved, "__version__", None),
        "path": getattr(resolved, "__file__", None),
        "required_symbols": list(REPORT_REQUIRED_SYMBOLS),
        "optional_symbols": optional,
        "formats": formats,
        "supports_pose": hasattr(resolved, "create_pose_report"),
        "supports_multipose": hasattr(resolved, "create_multipose_report"),
        "supports_writing": hasattr(resolved, "write_report") or hasattr(resolved, "save_dock_report"),
        "supports_multi_format_writing": hasattr(resolved, "write_report_formats") or hasattr(resolved, "save_dock_report_formats"),
    }


# 23.6. Target resolution
# -----------------------------------------------------------------------------


def _report_source_name(source: Any, default: str = "analysis") -> str:
    """Return a stable report source name."""

    for key in ("name", "title", "pose_id", "run_id", "request_id"):
        value = get_object_value(source, key, default=None)
        if value is not None and str(value).strip():
            return normalize_text(value, default=default)
    return default


def _report_source_identifier(source: Any) -> Optional[str]:
    """Return a stable report source identifier when available."""

    for key in ("pose_id", "run_id", "request_id", "id", "identifier"):
        value = get_object_value(source, key, default=None)
        if value is not None and str(value).strip():
            return normalize_text(value, default="") or None
    return None


def _report_source_kind(source: Any) -> ReportTargetKind:
    """Infer the report target kind from an analysis object."""

    if isinstance(source, PoseAnalysisResult):
        return ReportTargetKind.POSE
    if isinstance(source, MultiPoseAnalysisResult):
        return ReportTargetKind.MULTIPOSE
    if isinstance(source, BatchAnalysisResult):
        return ReportTargetKind.BATCH
    if isinstance(source, AnalysisRunResult):
        return ReportTargetKind.RUN
    if isinstance(source, DockModel) or is_dock_model_like(source):
        return ReportTargetKind.DOCK_MODEL
    result_type = normalize_text(get_object_value(source, "result_type", default=""), default="").lower()
    if "multipose" in result_type:
        return ReportTargetKind.MULTIPOSE
    if "batch" in result_type:
        return ReportTargetKind.BATCH
    if "pose" in result_type:
        return ReportTargetKind.POSE
    if "run" in result_type:
        return ReportTargetKind.RUN
    return ReportTargetKind.GENERIC


def _report_source_dock_models(source: Any) -> Tuple[Any, ...]:
    """Extract DockModel objects associated with a report source."""

    models: List[Any] = []
    direct = get_object_value(source, "dock_model", default=None)
    if direct is not None:
        models.append(direct)
    collection = get_object_value(source, "dock_models", default=None)
    if collection is not None:
        models.extend(item for item in normalize_object_sequence(collection) if item is not None)
    pose_results = get_object_value(source, "pose_results", default=None)
    if pose_results is not None:
        for pose_result in normalize_object_sequence(pose_results):
            model = get_object_value(pose_result, "dock_model", default=None)
            if model is not None:
                models.append(model)
    items = get_object_value(source, "items", default=None)
    if items is not None:
        for item in normalize_object_sequence(items):
            result = get_object_value(item, "result", default=item)
            models.extend(_report_source_dock_models(result))
    unique: List[Any] = []
    identities: Set[int] = set()
    for model in models:
        marker = id(model)
        if marker not in identities:
            identities.add(marker)
            unique.append(model)
    return tuple(unique)


def resolve_report_stage_target(
    source: Any = None,
    *,
    context: Optional[AnalysisContext] = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    dock_model: Any = None,
) -> ReportStageTarget:
    """Resolve the best available report source and associated models."""

    candidates = (
        pose_result,
        multipose_result,
        batch_result,
        run_result,
        source,
    )
    selected = next((item for item in candidates if item is not None), None)
    if selected is None and context is not None:
        for key in (
            MULTIPOSE_RESULT_KEY,
            BATCH_RESULT_KEY,
            SINGLE_POSE_RESULT_KEY,
            MULTIPOSE_RUN_RESULT_KEY,
            BATCH_RUN_RESULT_KEY,
            SINGLE_POSE_RUN_RESULT_KEY,
        ):
            candidate = context.get_shared(key)
            if candidate is not None:
                selected = candidate
                break
    if selected is None and dock_model is not None:
        selected = dock_model
    if selected is None and context is not None:
        if context.dock_models:
            selected = context.dock_models[0] if len(context.dock_models) == 1 else tuple(context.dock_models)
        elif context.poses:
            selected = context.poses[0] if len(context.poses) == 1 else tuple(context.poses)
    if selected is None:
        raise AnalysisInputError(
            "No report source could be resolved.",
            stage=STAGE_REPORT,
            code="report_source_unavailable",
        )
    kind = _report_source_kind(selected)
    models = _report_source_dock_models(selected)
    if dock_model is not None and all(id(model) != id(dock_model) for model in models):
        models = (dock_model,) + models
    if context is not None:
        for model in context.dock_models:
            if all(id(existing) != id(model) for existing in models):
                models += (model,)
    return ReportStageTarget(
        source=selected,
        kind=kind,
        dock_models=models,
        name=_report_source_name(selected),
        identifier=_report_source_identifier(selected),
        metadata={
            "source_type": type(selected).__name__,
            "context_run_id": context.run_id if context is not None else None,
            "context_request_id": context.request_id if context is not None else None,
        },
    )


# 23.7. Native report configuration
# -----------------------------------------------------------------------------


def _report_supported_kwargs(function: Callable[..., Any], values: Mapping[str, Any]) -> Dict[str, Any]:
    """Filter keyword arguments for a report-module callable."""

    return _filter_callable_keyword_arguments(function, values)


def build_native_report_config(
    config: ReportIntegrationConfig,
    *,
    report_format: Optional[str] = None,
    report_module: Optional[ModuleType] = None,
) -> Any:
    """Build the native ReportConfig consumed by report.py."""

    module = _require_report_module(report_module)
    base = getattr(module, "DEFAULT_REPORT_CONFIG", None)
    configure = getattr(module, "configure_report", None)
    options = dict(config.report_options)
    values: Dict[str, Any] = {
        "base": base,
        "report_format": report_format or config.formats[0],
        "title": config.title,
        "subtitle": config.subtitle,
        "description": config.description,
        "overwrite": config.overwrite,
        "atomic_write": config.atomic_write,
        "metadata": dict(config.metadata),
    }
    values.update(options)
    values = {key: value for key, value in values.items() if value is not None}
    if callable(configure):
        native = configure(**_report_supported_kwargs(configure, values))
    elif base is not None:
        native = base
    else:
        report_config_type = getattr(module, "ReportConfig")
        native = report_config_type()

    write_config_type = getattr(module, "WriteConfig", None)
    if write_config_type is not None:
        try:
            writing = write_config_type(
                overwrite=config.overwrite,
                atomic=config.atomic_write,
                create_parents=config.create_directories,
                backup=config.backup,
            )
            if is_dataclass(native):
                native = replace(native, writing=writing)
            elif hasattr(native, "writing"):
                setattr(native, "writing", writing)
        except Exception:
            pass
    return native


# 23.8. Document construction and validation
# -----------------------------------------------------------------------------


def is_native_report_document(value: Any, report_module: Optional[ModuleType] = None) -> bool:
    """Return whether a value is a native ReportDocument."""

    module = _require_report_module(report_module)
    report_type = getattr(module, "ReportDocument", None)
    return bool(report_type is not None and isinstance(value, report_type))


def build_report_document(
    target: ReportStageTarget,
    config: ReportIntegrationConfig,
    *,
    report_module: Optional[ModuleType] = None,
) -> Any:
    """Build a native report document for one resolved target."""

    module = _require_report_module(report_module)
    native_config = build_native_report_config(config, report_module=module)
    common = {
        "config": native_config,
        "title": config.title,
        "subtitle": config.subtitle,
        "description": config.description,
        "metadata": {
            **dict(config.metadata),
            "analysis_report_schema": REPORT_INTEGRATION_SCHEMA_NAME,
            "analysis_report_schema_version": REPORT_INTEGRATION_SCHEMA_VERSION,
            "target_kind": target.kind.value,
            "target_identifier": target.identifier,
        },
        "validate": False,
        "strict_validation": config.strict_validation,
    }
    common = {key: value for key, value in common.items() if value is not None}
    if target.kind is ReportTargetKind.POSE and hasattr(module, "create_pose_report"):
        function = getattr(module, "create_pose_report")
    elif target.kind is ReportTargetKind.MULTIPOSE and hasattr(module, "create_multipose_report"):
        function = getattr(module, "create_multipose_report")
    else:
        function = getattr(module, "create_report")
    return function(target.source, **_report_supported_kwargs(function, common))


def validate_report_document_integration(
    document: Any,
    config: ReportIntegrationConfig,
    *,
    report_module: Optional[ModuleType] = None,
) -> Tuple[Any, Tuple[str, ...]]:
    """Validate a native report document and return issue messages."""

    module = _require_report_module(report_module)
    native_config = build_native_report_config(config, report_module=module)
    validator = getattr(module, "validate_report")
    validation = validator(
        document,
        **_report_supported_kwargs(
            validator,
            {"config": native_config, "strict": config.strict_validation},
        ),
    )
    issues = get_object_value(validation, "issues", default=())
    messages: List[str] = []
    for issue in normalize_object_sequence(issues):
        message = get_object_value(issue, "message", default=None)
        if message is None:
            message = str(issue)
        if str(message).strip():
            messages.append(str(message).strip())
    return validation, tuple(messages)


# 23.9. Rendering and writing
# -----------------------------------------------------------------------------


def render_report_artifact(
    document: Any,
    report_format: str,
    config: ReportIntegrationConfig,
    *,
    report_module: Optional[ModuleType] = None,
) -> ReportArtifact:
    """Render one report format through report.py."""

    module = _require_report_module(report_module)
    canonical = canonicalize_report_format(report_format)
    native_config = build_native_report_config(config, report_format=canonical, report_module=module)
    renderer = getattr(module, "render_report")
    content = renderer(
        document,
        **_report_supported_kwargs(
            renderer,
            {"report_format": canonical, "config": native_config},
        ),
    )
    content = str(content)
    if len(content) > MAX_REPORT_RENDERED_CHARACTERS:
        raise AnalysisIntegrationError(
            "Rendered report content exceeds the configured safety limit.",
            stage=STAGE_REPORT,
            code="report_content_limit_exceeded",
            details={
                "format": canonical,
                "characters": len(content),
                "limit": MAX_REPORT_RENDERED_CHARACTERS,
            },
        )
    return ReportArtifact(
        format=canonical,
        status=ReportArtifactStatus.RENDERED,
        content=content if config.include_rendered_content else None,
        metadata={"character_count": len(content)},
    )


def _report_output_path(config: ReportIntegrationConfig, report_format: str) -> Path:
    """Return the expected path for one report format."""

    if config.output_directory is None:
        raise AnalysisConfigurationError(
            "Report file writing requires an output directory.",
            stage=STAGE_REPORT,
            code="report_output_directory_required",
        )
    suffix = REPORT_FORMAT_SUFFIXES[canonicalize_report_format(report_format)]
    return config.output_directory / f"{config.basename}{suffix}"


def adapt_native_report_write_result(
    value: Any,
    *,
    report_format: str,
    content: Optional[str] = None,
) -> ReportArtifact:
    """Adapt report.py WriteResult to ReportArtifact."""

    canonical = canonicalize_report_format(report_format)
    native_format = get_object_value(value, "format", default=canonical)
    native_format = getattr(native_format, "value", native_format)
    try:
        canonical = canonicalize_report_format(native_format)
    except AnalysisError:
        pass
    return ReportArtifact(
        format=canonical,
        status=ReportArtifactStatus.WRITTEN,
        content=content,
        path=get_object_value(value, "path", default=None),
        bytes_written=get_object_value(value, "bytes_written", default=None),
        checksum=get_object_value(value, "checksum", default=None),
        mime_type=get_object_value(value, "mime_type", default=None)
        or get_nested_value(value, ("metadata", "mime_type"), default=None),
        encoding=get_object_value(value, "encoding", default=None),
        backup_path=get_object_value(value, "backup_path", default=None),
        overwritten=bool(get_object_value(value, "overwritten", default=False)),
        atomic=get_object_value(value, "atomic", default=None),
        metadata=object_to_mapping(get_object_value(value, "metadata", default={})),
    )


def write_report_artifacts(
    document: Any,
    config: ReportIntegrationConfig,
    *,
    existing_artifacts: Optional[Mapping[str, ReportArtifact]] = None,
    report_module: Optional[ModuleType] = None,
) -> MutableMapping[str, ReportArtifact]:
    """Write all configured report formats through report.py."""

    module = _require_report_module(report_module)
    if config.output_directory is None:
        raise AnalysisConfigurationError(
            "Report file writing requires an output directory.",
            stage=STAGE_REPORT,
            code="report_output_directory_required",
        )
    if config.create_directories:
        config.output_directory.mkdir(parents=True, exist_ok=True)
    native_config = build_native_report_config(config, report_module=module)
    artifacts: MutableMapping[str, ReportArtifact] = OrderedDict()
    writer_many = getattr(module, "write_report_formats", None)
    if callable(writer_many):
        native_results = writer_many(
            document,
            config.output_directory,
            **_report_supported_kwargs(
                writer_many,
                {
                    "formats": config.formats,
                    "basename": config.basename,
                    "config": native_config,
                    "calculate_checksum": config.calculate_checksum,
                },
            ),
        )
        for raw_format, result in dict(native_results).items():
            canonical = canonicalize_report_format(getattr(raw_format, "value", raw_format))
            content = None
            if existing_artifacts and canonical in existing_artifacts:
                content = existing_artifacts[canonical].content
            artifacts[canonical] = adapt_native_report_write_result(
                result,
                report_format=canonical,
                content=content,
            )
        return artifacts

    writer = getattr(module, "write_report", None) or getattr(module, "save_dock_report", None)
    if not callable(writer):
        raise AnalysisCapabilityError(
            "The report module does not expose a compatible writing function.",
            stage=STAGE_REPORT,
            code="report_writer_unavailable",
        )
    for report_format in config.formats:
        path = _report_output_path(config, report_format)
        result = writer(
            document,
            path,
            **_report_supported_kwargs(
                writer,
                {
                    "report_format": report_format,
                    "config": native_config,
                    "ensure_suffix": config.ensure_suffix,
                    "calculate_checksum": config.calculate_checksum,
                    "validate": config.validate_document,
                },
            ),
        )
        content = None
        if existing_artifacts and report_format in existing_artifacts:
            content = existing_artifacts[report_format].content
        artifacts[report_format] = adapt_native_report_write_result(
            result,
            report_format=report_format,
            content=content,
        )
    return artifacts


# 23.10. Reuse and DockModel attachment
# -----------------------------------------------------------------------------


def find_reusable_report_output(
    target: ReportStageTarget,
    config: ReportIntegrationConfig,
) -> Optional[ReportStageOutput]:
    """Return a compatible previously attached report output."""

    if not config.reuse_result:
        return None
    for model in target.dock_models:
        metadata = ensure_dock_model_metadata(model)
        state = metadata.get(REPORT_METADATA_KEY)
        if isinstance(state, Mapping):
            output = state.get("output")
            fingerprint = state.get("config_fingerprint")
            if isinstance(output, ReportStageOutput) and fingerprint == config.fingerprint:
                output.reused = True
                return output
        for field_name in REPORT_DOCUMENT_REUSE_FIELDS:
            value = get_object_value(model, field_name, default=None)
            if isinstance(value, ReportStageOutput) and value.config.fingerprint == config.fingerprint:
                value.reused = True
                return value
    return None


def attach_report_output_to_dock_models(
    output: ReportStageOutput,
    *,
    config: Optional[ReportIntegrationConfig] = None,
) -> int:
    """Attach report output, paths and metadata to associated DockModel objects."""

    active = config or output.config
    if not active.attach_result or active.attachment_mode == ATTACHMENT_POLICY_NONE:
        return 0
    count = 0
    for model in output.target.dock_models:
        existing_collection = get_object_value(model, REPORT_DOCK_MODEL_COLLECTION_FIELD, default={})
        if not isinstance(existing_collection, Mapping):
            existing_collection = {}
        collection = dict(existing_collection)
        key = output.target.identifier or output.target.name or "analysis"
        if active.attachment_mode == ATTACHMENT_POLICY_PRESERVE and key in collection:
            continue
        collection[key] = output
        set_object_value(model, REPORT_DOCK_MODEL_COLLECTION_FIELD, collection)
        if active.attachment_mode != ATTACHMENT_POLICY_PRESERVE or get_object_value(model, REPORT_DOCK_MODEL_FIELD, default=None) is None:
            set_object_value(model, REPORT_DOCK_MODEL_FIELD, output)
        metadata = ensure_dock_model_metadata(model)
        metadata[REPORT_METADATA_KEY] = {
            "schema_name": REPORT_INTEGRATION_SCHEMA_NAME,
            "schema_version": REPORT_INTEGRATION_SCHEMA_VERSION,
            "config_fingerprint": active.fingerprint,
            "formats": list(output.artifacts),
            "written_files": dict(output.written_files),
            "generated_at": output.finished_at or output.started_at,
            "output": output,
        }
        if active.update_dock_model_files and output.written_files:
            files = ensure_dock_model_files(model)
            for report_format, path in output.written_files.items():
                files[f"report_{report_format}"] = path
        count += 1
    output.attached = bool(count)
    return count


# 23.11. Integrated report execution
# -----------------------------------------------------------------------------


def run_report_analysis(
    source: Any = None,
    *,
    context: Optional[AnalysisContext] = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    dock_model: Any = None,
    config: ReportIntegrationConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    report_module: Optional[ModuleType] = None,
) -> ReportStageOutput:
    """Build, render, write and attach a report for one analysis source."""

    started = time.perf_counter()
    module = _require_report_module(report_module)
    integrated_config = context.config if context is not None and config is None else config
    active = resolve_report_integration_config(integrated_config, overrides=overrides)
    target = resolve_report_stage_target(
        source,
        context=context,
        pose_result=pose_result,
        multipose_result=multipose_result,
        batch_result=batch_result,
        run_result=run_result,
        dock_model=dock_model,
    )
    reused = find_reusable_report_output(target, active)
    if reused is not None:
        reused.reused = True
        reused.finished_at = reused.finished_at or _utc_timestamp()
        reused.duration_seconds = time.perf_counter() - started
        return reused

    output = ReportStageOutput(
        target=target,
        config=active,
        metadata={
            "module_version": getattr(module, "__version__", None),
            "config_fingerprint": active.fingerprint,
        },
    )
    if not active.build_document:
        output.messages.append("Report document construction is disabled.")
        output.finished_at = _utc_timestamp()
        output.duration_seconds = time.perf_counter() - started
        return output

    output.document = build_report_document(target, active, report_module=module)
    if active.validate_document:
        output.validation, validation_messages = validate_report_document_integration(
            output.document,
            active,
            report_module=module,
        )
        if validation_messages:
            if active.strict_validation:
                raise AnalysisValidationError(
                    "Report document validation failed.",
                    stage=STAGE_REPORT,
                    code="report_validation_failed",
                    details={"issues": list(validation_messages)},
                )
            output.warnings.extend(validation_messages)

    if active.render_content:
        for report_format in active.formats:
            output.artifacts[report_format] = render_report_artifact(
                output.document,
                report_format,
                active,
                report_module=module,
            )

    if active.write_files:
        written = write_report_artifacts(
            output.document,
            active,
            existing_artifacts=output.artifacts,
            report_module=module,
        )
        for report_format, artifact in written.items():
            output.artifacts[report_format] = artifact

    output.statistics.update(
        {
            "formats_requested": len(active.formats),
            "formats_rendered": len(output.rendered_formats),
            "formats_written": len(output.written_formats),
            "dock_models": len(target.dock_models),
            "warnings": len(output.warnings),
            "errors": len(output.errors),
        }
    )
    attach_report_output_to_dock_models(output, config=active)
    output.finished_at = _utc_timestamp()
    output.duration_seconds = time.perf_counter() - started
    return output


def run_pose_report_analysis(
    pose_result: Any,
    **kwargs: Any,
) -> ReportStageOutput:
    """Generate a report for one pose result."""

    return run_report_analysis(pose_result=pose_result, **kwargs)


def run_multipose_report_analysis(
    multipose_result: Any,
    **kwargs: Any,
) -> ReportStageOutput:
    """Generate a report for a multipose result."""

    return run_report_analysis(multipose_result=multipose_result, **kwargs)


def run_batch_report_analysis(
    batch_result: Any,
    **kwargs: Any,
) -> ReportStageOutput:
    """Generate a report for a batch result."""

    return run_report_analysis(batch_result=batch_result, **kwargs)


# 23.12. Stage execution and context integration
# -----------------------------------------------------------------------------


def report_stage_output_to_result(
    output: ReportStageOutput,
    *,
    required: bool = False,
) -> AnalysisStageResult:
    """Convert report output to the common stage-result container."""

    result = AnalysisStageResult(stage=STAGE_REPORT, required=required)
    result.start()
    for message in output.messages:
        result.add_message(message)
    for message in output.warnings:
        result.add_warning(message, code="report_warning")
    for message in output.errors:
        result.add_error(message, code="report_error")
    result.statistics.update(output.statistics)
    result.files.update(output.written_files)
    result.metadata.update(
        {
            "schema_name": output.schema_name,
            "schema_version": output.schema_version,
            "target_kind": output.target.kind.value,
            "target_identifier": output.target.identifier,
            "formats": list(output.artifacts),
            "attached": output.attached,
            "reused": output.reused,
        }
    )
    if output.errors:
        result.partial(
            value=output,
            message="Report generation completed with errors.",
        )
    else:
        result.succeed(
            value=output,
            message=output.summary(),
        )
    return result


def execute_report_stage(
    context: AnalysisContext,
    *,
    dock_model: Any = None,
    source: Any = None,
    analysis_result: Any = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    config: ReportIntegrationConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    report_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
    **_: Any,
) -> AnalysisStageResult:
    """Registry-compatible report-stage executor."""

    stage_config = context.config.stage_configs.get(STAGE_REPORT)
    required = bool(stage_config.required) if stage_config is not None else False
    result = AnalysisStageResult(stage=STAGE_REPORT, required=required)
    result.start()
    context.set_current_stage(STAGE_REPORT)
    try:
        effective_source = analysis_result if analysis_result is not None else source
        output = run_report_analysis(
            effective_source,
            context=context,
            pose_result=pose_result,
            multipose_result=multipose_result,
            batch_result=batch_result,
            run_result=run_result,
            dock_model=dock_model,
            config=config or context.config,
            overrides=overrides,
            report_module=report_module,
        )
        result = report_stage_output_to_result(output, required=required)
        context.set_shared(REPORT_SHARED_OUTPUT_KEY, output)
        context.set_shared(REPORT_SHARED_DOCUMENT_KEY, output.document)
        context.set_shared(REPORT_SHARED_ARTIFACTS_KEY, output.artifacts)
        context.files.update(output.written_files)
    except Exception as exc:
        wrapped = exc if isinstance(exc, AnalysisError) else AnalysisIntegrationError(
            "Report generation failed.",
            stage=STAGE_REPORT,
            code="report_generation_failed",
            cause=exc,
        )
        result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
        if raise_on_error or context.config.runtime.is_strict:
            context.set_stage_data(STAGE_REPORT, result)
            context.set_current_stage(None)
            raise wrapped
    finally:
        context.set_stage_data(STAGE_REPORT, result)
        context.set_current_stage(None)
    return result


# 23.13. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_report_stage_output(value: Any) -> Tuple[str, ...]:
    """Return validation messages for a report-stage output."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, ReportStageOutput):
        return ("Value is not a ReportStageOutput.",)
    failures: List[str] = []
    if value.document is None and value.config.build_document:
        failures.append("Report document is missing.")
    if value.config.render_content:
        missing = [name for name in value.config.formats if name not in value.artifacts]
        if missing:
            failures.append("Missing report artifacts: " + ", ".join(missing) + ".")
    for name, artifact in value.artifacts.items():
        if name != artifact.format:
            failures.append(f"Artifact key {name!r} does not match its format.")
        if artifact.status is ReportArtifactStatus.FAILED and not artifact.error:
            failures.append(f"Failed artifact {name!r} has no error message.")
        if artifact.written and not artifact.path:
            failures.append(f"Written artifact {name!r} has no path.")
    if value.config.write_files and len(value.written_formats) != len(value.config.formats):
        failures.append("Not all configured report formats were written.")
    return tuple(failures)


def summarize_report_stage(value: Any) -> Dict[str, Any]:
    """Return a compact report-stage summary."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, ReportStageOutput):
        return {"valid": False, "type": type(value).__name__}
    return {
        "valid": not bool(validate_report_stage_output(value)),
        "target_kind": value.target.kind.value,
        "target_name": value.target.name,
        "formats": list(value.artifacts),
        "rendered_formats": list(value.rendered_formats),
        "written_formats": list(value.written_formats),
        "written_files": dict(value.written_files),
        "attached": value.attached,
        "reused": value.reused,
        "warnings": len(value.warnings),
        "errors": len(value.errors),
        "duration_seconds": value.duration_seconds,
    }


def report_stage_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize report-stage output as JSON."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if isinstance(value, ReportStageOutput):
        return value.to_json(indent=indent)
    return json.dumps(to_json_compatible(value), indent=indent, sort_keys=True, ensure_ascii=False)


def report_stage_result_adapter(value: Any, **kwargs: Any) -> AnalysisStageResult:
    """Registry-compatible adapter for report values."""

    if isinstance(value, AnalysisStageResult):
        return value
    if isinstance(value, ReportStageOutput):
        return report_stage_output_to_result(value, required=bool(kwargs.get("required", False)))
    target = kwargs.get("target")
    if not isinstance(target, ReportStageTarget):
        target = ReportStageTarget(source=value, kind=_report_source_kind(value), name=_report_source_name(value))
    active = resolve_report_integration_config(kwargs.get("config"))
    output = ReportStageOutput(target=target, config=active, document=value)
    return report_stage_output_to_result(output, required=bool(kwargs.get("required", False)))


def report_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible report-stage validator."""

    return validate_report_stage_output(value)


# 23.14. Stage registration
# -----------------------------------------------------------------------------


def register_report_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register report execution, adaptation and validation."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_REPORT)
    metadata = dict(definition.metadata)
    metadata.update(
        {
            "schema": REPORT_INTEGRATION_SCHEMA_NAME,
            "schema_version": REPORT_INTEGRATION_SCHEMA_VERSION,
            "result_type": REPORT_INTEGRATION_RESULT_TYPE,
            "supported_formats": REPORT_SUPPORTED_FORMATS,
            "supports_pose": True,
            "supports_multipose": True,
            "supports_batch": True,
            "supports_rendering": True,
            "supports_writing": True,
            "preserves_native_document": True,
        }
    )
    updated = replace(
        definition,
        executor=execute_report_stage,
        result_adapter=report_stage_result_adapter,
        validator=report_stage_validator,
        metadata=metadata,
    )
    target_registry.replace(updated)
    return updated


def report_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the report adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_REPORT)
    return bool(
        definition is not None
        and definition.executor is execute_report_stage
        and definition.result_adapter is report_stage_result_adapter
        and definition.validator is report_stage_validator
    )


# 23.15. Convention validation
# -----------------------------------------------------------------------------


def validate_report_integration_conventions() -> Dict[str, Any]:
    """Validate report configuration, rendering, writing and attachment."""

    failures: List[str] = []
    if canonicalize_report_format("md") != "markdown":
        failures.append("Report format alias resolution failed.")
    if canonicalize_report_attachment_mode("overwrite") != ATTACHMENT_POLICY_REPLACE:
        failures.append("Report attachment-mode alias resolution failed.")
    config = ReportIntegrationConfig.from_mapping(
        {
            "formats": ("text", "md", "json"),
            "write": False,
            "attach": True,
            "reuse": True,
            "validate": True,
            "title": "Section 23 validation",
        }
    )
    if config.formats != ("text", "markdown", "json"):
        failures.append("Report format normalization failed.")
    if len(config.fingerprint) != 64:
        failures.append("Report configuration fingerprint is invalid.")
    if not report_stage_adapter_registered():
        failures.append("Report stage adapter is not registered.")
    try:
        module = _require_report_module()
    except (AnalysisDependencyError, AnalysisCapabilityError, ModuleNotFoundError):
        raise
    except Exception as exc:
        failures.append(f"The real report module could not be loaded: {exc}")
        module = None
    if module is not None:
        pose = PoseAnalysisResult(
            pose_id="section23_pose_1",
            name="section23_pose",
            status=AnalysisStatus.SUCCEEDED,
            metadata={"validation": True},
        )
        output = run_pose_report_analysis(
            pose,
            config=config,
            report_module=module,
        )
        if output.document is None:
            failures.append("Real report integration produced no document.")
        if set(output.artifacts) != {"text", "markdown", "json"}:
            failures.append("Real report rendering did not produce all formats.")
        if any(not artifact.rendered for artifact in output.artifacts.values()):
            failures.append("At least one real report artifact was not rendered.")
        if validate_report_stage_output(output):
            failures.append("Real report-stage output validation failed.")
        if not output.to_json(indent=None):
            failures.append("Report-stage JSON serialization failed.")
        with TemporaryDirectory(prefix="dockanalyzer_report_section23_") as directory:
            write_config = replace(
                config,
                formats=("text", "json"),
                output_directory=Path(directory),
                write_files=True,
                calculate_checksum=True,
            )
            written = run_pose_report_analysis(
                pose,
                config=write_config,
                report_module=module,
            )
            if set(written.written_formats) != {"text", "json"}:
                failures.append("Real report writing did not produce both files.")
            if any(not Path(path).is_file() for path in written.written_files.values()):
                failures.append("At least one real report file is missing.")
        dock_model = SimpleNamespace(
            name="section23_model",
            receptor=None,
            pose=None,
            ligand=None,
            metadata={},
            statistics={},
            files={},
        )
        attached_pose = PoseAnalysisResult(
            pose_id="section23_attached_pose",
            name="section23_attached_pose",
            status=AnalysisStatus.SUCCEEDED,
            dock_model=dock_model,
        )
        attached_output = run_pose_report_analysis(
            attached_pose,
            config=replace(config, formats=("text",)),
            report_module=module,
        )
        if not attached_output.attached:
            failures.append("Report output was not attached to the DockModel.")
        if get_object_value(dock_model, REPORT_DOCK_MODEL_FIELD, default=None) is None:
            failures.append("The active DockModel report field was not updated.")
        request = AnalysisRequest(config=AnalysisConfig(), dock_models=(dock_model,))
        context = AnalysisContext(request=request, dock_models=[dock_model], current_pose_index=0)
        stage = execute_report_stage(
            context,
            pose_result=attached_pose,
            config=replace(config, formats=("text",), reuse_result=False),
            report_module=module,
            raise_on_error=True,
        )
        if not stage.succeeded:
            failures.append("Registered report-stage execution failed.")
        if context.get_shared(REPORT_SHARED_DOCUMENT_KEY) is None:
            failures.append("Report document was not stored in the context.")
    if failures:
        raise RuntimeError(
            "Report integration convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": REPORT_INTEGRATION_SCHEMA_NAME,
        "schema_version": REPORT_INTEGRATION_SCHEMA_VERSION,
        "supported_formats": len(REPORT_SUPPORTED_FORMATS),
        "attachment_modes": len(REPORT_ATTACHMENT_MODES),
        "validated_cases": 32,
    }


