# 24.2. Canonicalization helpers
# -----------------------------------------------------------------------------


def _output_convention_token(value: Any, *, default: str = "") -> str:
    """Return a normalized lowercase output-convention token."""

    raw = getattr(value, "value", value)
    return (
        normalize_text(raw, default=default)
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
        .lstrip(".")
    )


def _export_token(value: Any, *, default: str = "") -> str:
    """Return a normalized export-format token."""

    return _output_convention_token(value, default=default)


def canonicalize_export_format(value: Any) -> str:
    """Return a supported canonical export format."""

    token = _export_token(value)
    canonical = EXPORT_FORMAT_ALIASES.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unsupported export format: {value!r}.",
            stage=STAGE_EXPORT,
            code="unsupported_export_format",
            details={"format": str(value), "supported": list(EXPORT_SUPPORTED_FORMATS)},
        )
    return canonical


def canonicalize_export_formats(
    values: Any,
    *,
    default: Sequence[str] = DEFAULT_EXPORT_FORMATS,
) -> Tuple[str, ...]:
    """Return unique canonical export formats in declaration order."""

    if values is None:
        values = default
    if isinstance(values, (str, bytes, os.PathLike)):
        values = (values,)
    try:
        items = tuple(values)
    except TypeError as exc:
        raise AnalysisConfigurationError(
            "Export formats must be a string or iterable of strings.",
            stage=STAGE_EXPORT,
            code="invalid_export_formats",
            cause=exc,
        ) from exc
    normalized: List[str] = []
    for item in items:
        name = canonicalize_export_format(item)
        if name not in normalized:
            normalized.append(name)
    if not normalized:
        normalized = [canonicalize_export_format(item) for item in default]
    if len(normalized) > MAX_EXPORT_FORMAT_COUNT:
        raise AnalysisConfigurationError(
            "Too many export formats were requested.",
            stage=STAGE_EXPORT,
            code="export_format_limit_exceeded",
            details={"count": len(normalized), "limit": MAX_EXPORT_FORMAT_COUNT},
        )
    return tuple(normalized)


def canonicalize_export_layout(value: Any) -> str:
    """Return a supported export layout."""

    token = _export_token(value, default="single_file")
    canonical = EXPORT_LAYOUT_ALIASES.get(token, token)
    if canonical not in EXPORT_SUPPORTED_LAYOUTS:
        raise AnalysisConfigurationError(
            f"Unsupported export layout: {value!r}.",
            stage=STAGE_EXPORT,
            code="unsupported_export_layout",
        )
    return canonical


def canonicalize_export_detail(value: Any) -> str:
    """Return a supported export detail level."""

    token = _export_token(value, default="standard")
    if token not in EXPORT_SUPPORTED_DETAILS:
        raise AnalysisConfigurationError(
            f"Unsupported export detail level: {value!r}.",
            stage=STAGE_EXPORT,
            code="unsupported_export_detail",
        )
    return token


def canonicalize_export_overwrite(value: Any) -> str:
    """Return a supported export overwrite mode."""

    if isinstance(value, bool):
        return "overwrite" if value else "unique"
    token = _export_token(value, default="unique")
    canonical = EXPORT_OVERWRITE_ALIASES.get(token, token)
    if canonical not in EXPORT_SUPPORTED_OVERWRITE_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported export overwrite mode: {value!r}.",
            stage=STAGE_EXPORT,
            code="unsupported_export_overwrite_mode",
        )
    return canonical


def canonicalize_export_error_mode(value: Any) -> str:
    """Return a supported export error mode."""

    token = _export_token(value, default="raise")
    if token not in EXPORT_SUPPORTED_ERROR_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported export error mode: {value!r}.",
            stage=STAGE_EXPORT,
            code="unsupported_export_error_mode",
        )
    return token


def canonicalize_export_compression(value: Any) -> str:
    """Return a supported export compression mode."""

    token = _export_token(value, default="none")
    aliases = {"": "none", "off": "none", "disabled": "none", "gz": "gzip"}
    token = aliases.get(token, token)
    if token not in EXPORT_SUPPORTED_COMPRESSION:
        raise AnalysisConfigurationError(
            f"Unsupported export compression: {value!r}.",
            stage=STAGE_EXPORT,
            code="unsupported_export_compression",
        )
    return token


def canonicalize_export_target_kind(value: Any) -> ExportTargetKind:
    """Return a canonical export target kind."""

    if isinstance(value, ExportTargetKind):
        return value
    token = _export_token(value, default="generic")
    aliases = {
        "single": ExportTargetKind.POSE,
        "single_pose": ExportTargetKind.POSE,
        "pose": ExportTargetKind.POSE,
        "multipose": ExportTargetKind.MULTIPOSE,
        "multi_pose": ExportTargetKind.MULTIPOSE,
        "poses": ExportTargetKind.MULTIPOSE,
        "batch": ExportTargetKind.BATCH,
        "run": ExportTargetKind.RUN,
        "analysis_run": ExportTargetKind.RUN,
        "dockmodel": ExportTargetKind.DOCK_MODEL,
        "dock_model": ExportTargetKind.DOCK_MODEL,
        "model": ExportTargetKind.DOCK_MODEL,
        "generic": ExportTargetKind.GENERIC,
    }
    return aliases.get(token, ExportTargetKind.GENERIC)


# 24.3. Integration configuration
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ExportIntegrationConfig:
    """Control native serialization, validation, writing and attachment."""

    formats: Tuple[str, ...] = DEFAULT_EXPORT_FORMATS
    output_directory: Optional[Path] = None
    basename: str = EXPORT_DEFAULT_BASENAME
    layout: str = "single_file"
    detail: str = "standard"
    overwrite: str = "unique"
    error_mode: str = "raise"
    compression: str = "none"
    hash_algorithm: Optional[str] = "sha256"
    encoding: str = "utf-8"
    newline: str = "\n"
    float_precision: int = 6
    create_directories: bool = True
    atomic_write: bool = True
    backup_existing: bool = False
    include_metadata: bool = True
    include_manifest: bool = True
    include_provenance: bool = True
    include_empty_tables: bool = False
    include_raw_objects: bool = False
    update_dock_model_files: bool = True
    preserve_previous_files: bool = True
    selected_tables: Tuple[str, ...] = ()
    excluded_tables: Tuple[str, ...] = ()
    attach_result: bool = DEFAULT_EXPORT_ATTACH_RESULT
    reuse_result: bool = DEFAULT_EXPORT_REUSE_RESULT
    validate_before_export: bool = DEFAULT_EXPORT_VALIDATE_BEFORE
    validate_after_export: bool = DEFAULT_EXPORT_VALIDATE_AFTER
    strict_validation: bool = DEFAULT_EXPORT_STRICT_VALIDATION
    permissive: bool = DEFAULT_EXPORT_PERMISSIVE
    include_individual_poses: bool = DEFAULT_EXPORT_INCLUDE_INDIVIDUAL_POSES
    separate_pose_directories: bool = DEFAULT_EXPORT_SEPARATE_POSE_DIRECTORIES
    include_combined_payload: bool = DEFAULT_EXPORT_INCLUDE_COMBINED_PAYLOAD
    include_ranking: bool = DEFAULT_EXPORT_INCLUDE_RANKING
    consolidate_tables: bool = DEFAULT_EXPORT_CONSOLIDATE_TABLES
    continue_on_error: bool = DEFAULT_EXPORT_CONTINUE_ON_ERROR
    max_failures: Optional[int] = None
    write_batch_manifest: bool = True
    pose_prefix: str = "pose"
    export_options: Mapping[str, Any] = field(default_factory=dict)
    validation_options: Mapping[str, Any] = field(default_factory=dict)
    permissive_options: Mapping[str, Any] = field(default_factory=dict)
    model_files_options: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "formats", canonicalize_export_formats(self.formats))
        directory = self.output_directory
        if directory is not None:
            try:
                directory = Path(directory).expanduser()
            except (TypeError, ValueError, OSError) as exc:
                raise AnalysisConfigurationError(
                    "The export output directory is invalid.",
                    stage=STAGE_EXPORT,
                    code="invalid_export_output_directory",
                    cause=exc,
                ) from exc
            object.__setattr__(self, "output_directory", directory)
        basename = normalize_text(self.basename, default=EXPORT_DEFAULT_BASENAME)
        basename = re.sub(r"[^A-Za-z0-9._-]+", "_", basename).strip("._")
        object.__setattr__(self, "basename", basename or EXPORT_DEFAULT_BASENAME)
        object.__setattr__(self, "layout", canonicalize_export_layout(self.layout))
        object.__setattr__(self, "detail", canonicalize_export_detail(self.detail))
        object.__setattr__(self, "overwrite", canonicalize_export_overwrite(self.overwrite))
        object.__setattr__(self, "error_mode", canonicalize_export_error_mode(self.error_mode))
        object.__setattr__(self, "compression", canonicalize_export_compression(self.compression))
        object.__setattr__(self, "encoding", normalize_text(self.encoding, default="utf-8"))
        object.__setattr__(self, "newline", str(self.newline))
        precision = int(self.float_precision)
        if not 0 <= precision <= 15:
            raise AnalysisConfigurationError(
                "Export float precision must be between 0 and 15.",
                stage=STAGE_EXPORT,
                code="invalid_export_float_precision",
            )
        object.__setattr__(self, "float_precision", precision)
        if self.hash_algorithm is not None:
            object.__setattr__(self, "hash_algorithm", _export_token(self.hash_algorithm))
        for name in (
            "create_directories",
            "atomic_write",
            "backup_existing",
            "include_metadata",
            "include_manifest",
            "include_provenance",
            "include_empty_tables",
            "include_raw_objects",
            "update_dock_model_files",
            "preserve_previous_files",
            "attach_result",
            "reuse_result",
            "validate_before_export",
            "validate_after_export",
            "strict_validation",
            "permissive",
            "include_individual_poses",
            "separate_pose_directories",
            "include_combined_payload",
            "include_ranking",
            "consolidate_tables",
            "continue_on_error",
            "write_batch_manifest",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        object.__setattr__(self, "selected_tables", tuple(unique_preserving_order(normalize_text(item, default="") for item in self.selected_tables if normalize_text(item, default=""))))
        object.__setattr__(self, "excluded_tables", tuple(unique_preserving_order(normalize_text(item, default="") for item in self.excluded_tables if normalize_text(item, default=""))))
        overlap = set(self.selected_tables) & set(self.excluded_tables)
        if overlap:
            raise AnalysisConfigurationError(
                "Export tables cannot be both selected and excluded.",
                stage=STAGE_EXPORT,
                code="export_table_selection_overlap",
                details={"tables": sorted(overlap)},
            )
        if self.max_failures is not None:
            maximum = int(self.max_failures)
            if maximum < 0:
                raise AnalysisConfigurationError(
                    "Maximum export failures cannot be negative.",
                    stage=STAGE_EXPORT,
                    code="invalid_export_max_failures",
                )
            object.__setattr__(self, "max_failures", maximum)
        object.__setattr__(self, "pose_prefix", normalize_text(self.pose_prefix, default="pose") or "pose")
        for name in (
            "export_options",
            "validation_options",
            "permissive_options",
            "model_files_options",
            "metadata",
        ):
            value = getattr(self, name)
            if not isinstance(value, Mapping):
                raise AnalysisConfigurationError(
                    f"Export {name.replace('_', ' ')} must be a mapping.",
                    stage=STAGE_EXPORT,
                    code=f"invalid_export_{name}",
                )
            object.__setattr__(self, name, MappingProxyType(dict(value)))

    @classmethod
    def from_mapping(
        cls,
        values: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "ExportIntegrationConfig":
        """Create export integration configuration from a mapping."""

        if not isinstance(values, Mapping):
            raise AnalysisConfigurationError(
                "Export integration configuration must be a mapping.",
                stage=STAGE_EXPORT,
                code="invalid_export_integration_config",
            )
        aliases = {
            "format": "formats",
            "export_formats": "formats",
            "directory": "output_directory",
            "output_dir": "output_directory",
            "prefix": "basename",
            "file_prefix": "basename",
            "overwrite_files": "overwrite",
            "manifest": "include_manifest",
            "provenance": "include_provenance",
            "update_files": "update_dock_model_files",
            "attach": "attach_result",
            "reuse": "reuse_result",
            "validate_before": "validate_before_export",
            "validate_after": "validate_after_export",
            "strict": "strict_validation",
            "individual": "include_individual_poses",
            "separate_directories": "separate_pose_directories",
            "combined": "include_combined_payload",
            "ranking": "include_ranking",
            "options": "export_options",
            "validation": "validation_options",
            "recovery": "permissive_options",
            "files_options": "model_files_options",
        }
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        for raw_name, value in values.items():
            token = str(raw_name).strip().lower().replace("-", "_")
            name = aliases.get(token, token)
            if name not in allowed:
                if strict:
                    raise AnalysisConfigurationError(
                        f"Unknown export integration option: {raw_name!r}.",
                        stage=STAGE_EXPORT,
                        code="unknown_export_integration_option",
                    )
                continue
            normalized[name] = value
        return cls(**normalized)

    @property
    def fingerprint(self) -> str:
        """Return a stable configuration fingerprint."""

        payload = json.dumps(
            to_json_compatible(self.to_dict()),
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
        return sha256(payload.encode("utf-8")).hexdigest()

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready representation."""

        return {
            "formats": list(self.formats),
            "output_directory": str(self.output_directory) if self.output_directory else None,
            "basename": self.basename,
            "layout": self.layout,
            "detail": self.detail,
            "overwrite": self.overwrite,
            "error_mode": self.error_mode,
            "compression": self.compression,
            "hash_algorithm": self.hash_algorithm,
            "encoding": self.encoding,
            "newline": self.newline,
            "float_precision": self.float_precision,
            "create_directories": self.create_directories,
            "atomic_write": self.atomic_write,
            "backup_existing": self.backup_existing,
            "include_metadata": self.include_metadata,
            "include_manifest": self.include_manifest,
            "include_provenance": self.include_provenance,
            "include_empty_tables": self.include_empty_tables,
            "include_raw_objects": self.include_raw_objects,
            "update_dock_model_files": self.update_dock_model_files,
            "preserve_previous_files": self.preserve_previous_files,
            "selected_tables": list(self.selected_tables),
            "excluded_tables": list(self.excluded_tables),
            "attach_result": self.attach_result,
            "reuse_result": self.reuse_result,
            "validate_before_export": self.validate_before_export,
            "validate_after_export": self.validate_after_export,
            "strict_validation": self.strict_validation,
            "permissive": self.permissive,
            "include_individual_poses": self.include_individual_poses,
            "separate_pose_directories": self.separate_pose_directories,
            "include_combined_payload": self.include_combined_payload,
            "include_ranking": self.include_ranking,
            "consolidate_tables": self.consolidate_tables,
            "continue_on_error": self.continue_on_error,
            "max_failures": self.max_failures,
            "write_batch_manifest": self.write_batch_manifest,
            "pose_prefix": self.pose_prefix,
            "export_options": to_json_compatible(dict(self.export_options)),
            "validation_options": to_json_compatible(dict(self.validation_options)),
            "permissive_options": to_json_compatible(dict(self.permissive_options)),
            "model_files_options": to_json_compatible(dict(self.model_files_options)),
            "metadata": to_json_compatible(dict(self.metadata)),
        }


ExportIntegrationConfigLike: TypeAlias = Optional[
    Union[ExportIntegrationConfig, AnalysisConfig, Mapping[str, Any]]
]


def _export_stage_parameter_mapping(config: AnalysisConfig) -> Mapping[str, Any]:
    """Return export-stage parameters from an integrated configuration."""

    stage_config = config.stage_configs.get(STAGE_EXPORT)
    if stage_config is None:
        return MappingProxyType({})
    return stage_config.parameters


def resolve_export_integration_config(
    config: ExportIntegrationConfigLike = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    strict: bool = False,
) -> ExportIntegrationConfig:
    """Resolve export controls from direct or integrated configuration."""

    if isinstance(config, ExportIntegrationConfig):
        base = config.to_dict()
    elif isinstance(config, AnalysisConfig):
        output = config.output
        stage = config.stage_configs.get(STAGE_EXPORT)
        base = {
            "formats": output.export_formats,
            "output_directory": output.output_directory,
            "basename": output.file_prefix or EXPORT_DEFAULT_BASENAME,
            "overwrite": output.overwrite,
            "create_directories": output.create_directories,
            "include_manifest": output.write_manifest,
            "update_dock_model_files": output.update_dock_model_files,
            "attach_result": True if stage is None else stage.attach_results,
            "reuse_result": True if stage is None else stage.reuse_result,
            "validate_after_export": True if stage is None else stage.validate_result,
            "strict_validation": config.runtime.is_strict,
            "permissive": not config.runtime.is_strict,
            "export_options": dict(output.export_options),
            "metadata": dict(output.metadata),
        }
        base.update(dict(_export_stage_parameter_mapping(config)))
        module_values = config.module_configs.get(EXPORT_INTEGRATION_MODULE_NAME)
        if isinstance(module_values, Mapping):
            base.update(dict(module_values))
    elif isinstance(config, Mapping):
        base = dict(config)
    elif config is None:
        base = {}
    else:
        raise AnalysisConfigurationError(
            "Unsupported export integration configuration value.",
            stage=STAGE_EXPORT,
            code="unsupported_export_integration_config",
            details={"type": type(config).__name__},
        )
    if overrides:
        base.update(dict(overrides))
    return ExportIntegrationConfig.from_mapping(base, strict=strict)


# 24.4. Target, artifact and stage-output records
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ExportStageTarget:
    """Resolved source collection and associated DockModels for export."""

    source: Any
    kind: ExportTargetKind = ExportTargetKind.GENERIC
    items: Tuple[Any, ...] = ()
    dock_models: Tuple[Any, ...] = ()
    name: str = "analysis"
    identifier: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "kind", canonicalize_export_target_kind(self.kind))
        object.__setattr__(self, "items", tuple(self.items))
        object.__setattr__(self, "dock_models", tuple(self.dock_models))
        object.__setattr__(self, "name", normalize_text(self.name, default="analysis"))
        identifier = self.identifier
        if identifier is not None:
            identifier = normalize_text(identifier, default="") or None
        object.__setattr__(self, "identifier", identifier)
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    @property
    def export_sources(self) -> Tuple[Any, ...]:
        """Return the native source sequence for the resolved target."""

        if self.items:
            return self.items
        if self.dock_models:
            return self.dock_models
        return (self.source,)

    def to_dict(self) -> Dict[str, Any]:
        """Return a safe target description."""

        return {
            "kind": self.kind.value,
            "name": self.name,
            "identifier": self.identifier,
            "item_count": len(self.export_sources),
            "dock_model_count": len(self.dock_models),
            "source_type": type(self.source).__name__,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass
class ExportArtifact:
    """Portable description of one file generated by export.py."""

    path: str
    format: str
    status: str = "success"
    table: Optional[str] = None
    sheet_names: Tuple[str, ...] = ()
    record_count: Optional[int] = None
    size_bytes: Optional[int] = None
    hash_value: Optional[str] = None
    hash_algorithm: Optional[str] = None
    created_at: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    native_file: Any = field(default=None, repr=False, compare=False)

    def __post_init__(self) -> None:
        self.path = str(self.path)
        self.format = canonicalize_export_format(self.format)
        self.status = _export_token(self.status, default="success")
        self.sheet_names = tuple(str(item) for item in self.sheet_names)
        if self.record_count is not None:
            self.record_count = max(0, int(self.record_count))
        if self.size_bytes is not None:
            self.size_bytes = max(0, int(self.size_bytes))
        self.metadata = dict(self.metadata)

    @property
    def exists(self) -> bool:
        """Return whether the artifact path currently exists."""

        try:
            return Path(self.path).is_file()
        except (TypeError, ValueError, OSError):
            return False

    @property
    def succeeded(self) -> bool:
        """Return whether the native artifact reports success."""

        return self.status in {"success", "succeeded", "written", "complete"}

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready artifact record."""

        return {
            "path": self.path,
            "format": self.format,
            "status": self.status,
            "table": self.table,
            "sheet_names": list(self.sheet_names),
            "record_count": self.record_count,
            "size_bytes": self.size_bytes,
            "hash_value": self.hash_value,
            "hash_algorithm": self.hash_algorithm,
            "created_at": self.created_at,
            "exists": self.exists,
            "metadata": to_json_compatible(self.metadata),
        }


@dataclass
class ExportStageOutput:
    """Integrated output of one export-stage operation."""

    target: ExportStageTarget
    config: ExportIntegrationConfig
    status: Union[ExportIntegrationStatus, str] = ExportIntegrationStatus.PENDING
    native_result: Any = None
    artifacts: List[ExportArtifact] = field(default_factory=list)
    manifest: Any = None
    validation_before: Any = None
    validation_after: Any = None
    model_file_updates: Dict[str, Any] = field(default_factory=dict)
    attached: bool = False
    reused: bool = False
    warnings: List[Any] = field(default_factory=list)
    errors: List[Any] = field(default_factory=list)
    started_at: str = field(default_factory=_utc_timestamp)
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not isinstance(self.status, ExportIntegrationStatus):
            token = _export_token(self.status, default="pending")
            native_aliases = {
                "success": "succeeded",
                "partial_success": "partial",
                "recovered": "partial",
                "failure": "failed",
            }
            token = native_aliases.get(token, token)
            self.status = ExportIntegrationStatus(token)
        self.artifacts = [artifact if isinstance(artifact, ExportArtifact) else adapt_exported_file(artifact) for artifact in self.artifacts]
        self.model_file_updates = dict(self.model_file_updates)
        self.warnings = list(self.warnings)
        self.errors = list(self.errors)
        self.metadata = dict(self.metadata)
        if self.finished_at is not None and self.duration_seconds is None:
            self.duration_seconds = _export_duration(self.started_at, self.finished_at)

    @property
    def succeeded(self) -> bool:
        """Return whether the operation produced an accepted export."""

        return self.status in {
            ExportIntegrationStatus.SUCCEEDED,
            ExportIntegrationStatus.REUSED,
        }

    @property
    def partial(self) -> bool:
        """Return whether the operation produced partial output."""

        return self.status is ExportIntegrationStatus.PARTIAL

    @property
    def file_count(self) -> int:
        """Return the number of generated file records."""

        return len(self.artifacts)

    @property
    def written_files(self) -> Dict[str, str]:
        """Return deterministic file-map entries for pipeline synchronization."""

        result: Dict[str, str] = {}
        counters: Counter[str] = Counter()
        for artifact in self.artifacts:
            counters[artifact.format] += 1
            suffix = "" if counters[artifact.format] == 1 else f"_{counters[artifact.format]}"
            table = f"_{artifact.table}" if artifact.table else ""
            key = f"export_{artifact.format}{table}{suffix}"
            result[key] = artifact.path
        return result

    def finish(self, status: Union[ExportIntegrationStatus, str]) -> "ExportStageOutput":
        """Finalize status and timing."""

        if not isinstance(status, ExportIntegrationStatus):
            status = ExportIntegrationStatus(_export_token(status))
        self.status = status
        self.finished_at = _utc_timestamp()
        self.duration_seconds = _export_duration(self.started_at, self.finished_at)
        return self

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready stage output."""

        return {
            "schema": EXPORT_INTEGRATION_SCHEMA_NAME,
            "schema_version": EXPORT_INTEGRATION_SCHEMA_VERSION,
            "status": self.status.value,
            "target": self.target.to_dict(),
            "config": self.config.to_dict(),
            "artifacts": [artifact.to_dict() for artifact in self.artifacts],
            "manifest": _export_native_to_data(self.manifest),
            "validation_before": _export_native_to_data(self.validation_before),
            "validation_after": _export_native_to_data(self.validation_after),
            "model_file_updates": to_json_compatible(self.model_file_updates),
            "attached": self.attached,
            "reused": self.reused,
            "warnings": to_json_compatible(self.warnings),
            "errors": to_json_compatible(self.errors),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "written_files": self.written_files,
            "metadata": to_json_compatible(self.metadata),
        }

    def to_json(self, *, indent: Optional[int] = 2) -> str:
        """Serialize the stage output as JSON."""

        return json.dumps(self.to_dict(), indent=indent, sort_keys=True, ensure_ascii=False)


def _export_duration(started_at: Optional[str], finished_at: Optional[str]) -> Optional[float]:
    """Return a non-negative duration between two ISO timestamps."""

    if not started_at or not finished_at:
        return None
    try:
        started = datetime.fromisoformat(started_at)
        finished = datetime.fromisoformat(finished_at)
    except (TypeError, ValueError):
        return None
    return max(0.0, (finished - started).total_seconds())


def _export_native_to_data(value: Any) -> Any:
    """Convert a native export object to a safe representation."""

    if value is None:
        return None
    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        try:
            return to_json_compatible(to_dict())
        except Exception:
            pass
    return to_json_compatible(value)


# 24.5. Module loading and capability inspection
# -----------------------------------------------------------------------------


def _require_export_module(module: Optional[ModuleType] = None) -> ModuleType:
    """Return a validated export module."""

    resolved = module or load_analysis_module(EXPORT_INTEGRATION_MODULE_NAME, required=True)
    if resolved is None:
        raise AnalysisDependencyError(
            "The export module is unavailable.",
            stage=STAGE_EXPORT,
            code="export_module_unavailable",
        )
    missing = tuple(name for name in EXPORT_REQUIRED_SYMBOLS if not hasattr(resolved, name))
    if missing:
        raise AnalysisCapabilityError(
            "The export module is missing required public symbols: " + ", ".join(missing),
            stage=STAGE_EXPORT,
            code="export_interface_invalid",
            details={"missing_symbols": list(missing)},
        )
    return resolved


def inspect_export_integration_capabilities(
    module: Optional[ModuleType] = None,
) -> Dict[str, Any]:
    """Return export-module capabilities relevant to orchestration."""

    try:
        resolved = _require_export_module(module)
    except AnalysisError as exc:
        return {
            "available": False,
            "error": str(exc),
            "required_symbols": list(EXPORT_REQUIRED_SYMBOLS),
            "optional_symbols": [],
            "formats": [],
        }
    optional = [name for name in EXPORT_OPTIONAL_SYMBOLS if hasattr(resolved, name)]
    formats: List[str] = []
    available = getattr(resolved, "available_export_formats")
    try:
        native_formats = available()
    except Exception:
        native_formats = getattr(resolved, "SUPPORTED_EXPORT_FORMATS", EXPORT_SUPPORTED_FORMATS)
    for value in native_formats:
        try:
            canonical = canonicalize_export_format(getattr(value, "value", value))
        except AnalysisError:
            continue
        if canonical not in formats:
            formats.append(canonical)
    capabilities: Any = None
    capability_function = getattr(resolved, "export_capabilities", None)
    if callable(capability_function):
        try:
            capabilities = _export_native_to_data(capability_function())
        except Exception:
            capabilities = None
    return {
        "available": True,
        "module": getattr(resolved, "__name__", EXPORT_INTEGRATION_MODULE_NAME),
        "version": getattr(resolved, "__version__", None),
        "path": getattr(resolved, "__file__", None),
        "formats": formats,
        "required_symbols": list(EXPORT_REQUIRED_SYMBOLS),
        "optional_symbols": optional,
        "capabilities": capabilities,
    }


# 24.6. Target resolution
# -----------------------------------------------------------------------------


def _export_source_kind(value: Any) -> ExportTargetKind:
    """Infer the target kind from one source object."""

    if isinstance(value, PoseAnalysisResult):
        return ExportTargetKind.POSE
    if isinstance(value, MultiPoseAnalysisResult):
        return ExportTargetKind.MULTIPOSE
    if isinstance(value, BatchAnalysisResult):
        return ExportTargetKind.BATCH
    if isinstance(value, AnalysisRunResult):
        mode = _export_token(get_object_value(value, "mode", default=""))
        if mode in {"multipose", "multi_pose"}:
            return ExportTargetKind.MULTIPOSE
        if mode == "batch":
            return ExportTargetKind.BATCH
        return ExportTargetKind.RUN
    if is_dock_model_like(value):
        return ExportTargetKind.DOCK_MODEL
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return ExportTargetKind.MULTIPOSE if len(value) > 1 else ExportTargetKind.POSE
    return ExportTargetKind.GENERIC


def _export_source_name(value: Any) -> str:
    """Return a stable basename candidate for one source."""

    for name in ("name", "batch_name", "run_id", "pose_id", "request_id", "identifier", "id"):
        candidate = get_object_value(value, name, default=None, include_aliases=False)
        if candidate is not None and str(candidate).strip():
            return normalize_text(candidate, default="analysis")
    return type(value).__name__ or "analysis"


def _export_source_identifier(value: Any) -> Optional[str]:
    """Return a stable source identifier when available."""

    for name in ("pose_id", "run_id", "request_id", "identifier", "id"):
        candidate = get_object_value(value, name, default=None, include_aliases=False)
        if candidate is not None and str(candidate).strip():
            return str(candidate)
    return None


def _export_collect_dock_models(value: Any, *, seen: Optional[Set[int]] = None) -> Tuple[Any, ...]:
    """Collect unique DockModel-like objects from nested results."""

    if value is None:
        return ()
    if seen is None:
        seen = set()
    marker = id(value)
    if marker in seen:
        return ()
    seen.add(marker)
    if is_dock_model_like(value):
        return (value,)
    direct = get_object_value(value, "dock_model", default=None, include_aliases=False)
    models: List[Any] = []
    if direct is not None and is_dock_model_like(direct):
        models.append(direct)
    collection = get_object_value(value, "dock_models", default=None, include_aliases=False)
    if collection is not None and not isinstance(collection, (str, bytes, bytearray)):
        try:
            for item in collection:
                if is_dock_model_like(item) and all(id(existing) != id(item) for existing in models):
                    models.append(item)
        except TypeError:
            pass
    for field_name in ("pose_results", "items", "results", "result", "value"):
        nested = get_object_value(value, field_name, default=None, include_aliases=False)
        if nested is None or nested is value:
            continue
        if isinstance(nested, Mapping):
            nested_values = tuple(nested.values())
        elif isinstance(nested, Sequence) and not isinstance(nested, (str, bytes, bytearray)):
            nested_values = tuple(nested)
        else:
            nested_values = (nested,)
        for item in nested_values:
            for model in _export_collect_dock_models(item, seen=seen):
                if all(id(existing) != id(model) for existing in models):
                    models.append(model)
    return tuple(models)


def _export_collect_items(value: Any, kind: ExportTargetKind, models: Tuple[Any, ...]) -> Tuple[Any, ...]:
    """Return native export items for the selected target."""

    if models:
        return models
    if kind is ExportTargetKind.POSE:
        return (get_object_value(value, "dock_model", default=value, include_aliases=False),)
    if kind is ExportTargetKind.MULTIPOSE:
        pose_results = get_object_value(value, "pose_results", default=None, include_aliases=False)
        if pose_results is not None:
            return tuple(pose_results)
    if kind is ExportTargetKind.BATCH:
        items = get_object_value(value, "items", default=None, include_aliases=False)
        if items is not None:
            sources: List[Any] = []
            for item in items:
                source = get_object_value(item, "result", default=None, include_aliases=False)
                if source is None:
                    source = get_object_value(item, "source", default=item, include_aliases=False)
                sources.append(source)
            return tuple(sources)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return tuple(value)
    return (value,)


def resolve_export_stage_target(
    source: Any = None,
    *,
    context: Optional[AnalysisContext] = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    dock_model: Any = None,
) -> ExportStageTarget:
    """Resolve the best available export source and associated models."""

    candidates = (pose_result, multipose_result, batch_result, run_result, source)
    selected = next((item for item in candidates if item is not None), None)
    if selected is None and context is not None:
        for key in (
            MULTIPOSE_RESULT_KEY,
            BATCH_RESULT_KEY,
            SINGLE_POSE_RESULT_KEY,
            MULTIPOSE_RUN_RESULT_KEY,
            BATCH_RUN_RESULT_KEY,
            SINGLE_POSE_RUN_RESULT_KEY,
        ):
            candidate = context.get_shared(key)
            if candidate is not None:
                selected = candidate
                break
    if selected is None and dock_model is not None:
        selected = dock_model
    if selected is None and context is not None:
        if context.dock_models:
            selected = context.dock_models[0] if len(context.dock_models) == 1 else tuple(context.dock_models)
        elif context.poses:
            selected = context.poses[0] if len(context.poses) == 1 else tuple(context.poses)
    if selected is None:
        raise AnalysisInputError(
            "No export source could be resolved.",
            stage=STAGE_EXPORT,
            code="export_source_unavailable",
        )
    kind = _export_source_kind(selected)
    models = _export_collect_dock_models(selected)
    if dock_model is not None and is_dock_model_like(dock_model) and all(id(model) != id(dock_model) for model in models):
        models = (dock_model,) + models
    if context is not None:
        for model in context.dock_models:
            if all(id(existing) != id(model) for existing in models):
                models += (model,)
    items = _export_collect_items(selected, kind, models)
    if kind in {ExportTargetKind.RUN, ExportTargetKind.GENERIC}:
        if len(items) > 1:
            kind = ExportTargetKind.MULTIPOSE
        elif len(items) == 1 and is_dock_model_like(items[0]):
            kind = ExportTargetKind.DOCK_MODEL
    return ExportStageTarget(
        source=selected,
        kind=kind,
        items=items,
        dock_models=models,
        name=_export_source_name(selected),
        identifier=_export_source_identifier(selected),
        metadata={
            "source_type": type(selected).__name__,
            "context_run_id": context.run_id if context is not None else None,
            "context_request_id": context.request_id if context is not None else None,
        },
    )


# 24.7. Native option construction
# -----------------------------------------------------------------------------


def _export_supported_kwargs(function: Callable[..., Any], values: Mapping[str, Any]) -> Dict[str, Any]:
    """Filter keyword arguments for one export-module callable."""

    return _filter_callable_keyword_arguments(function, values)


def _export_build_nested_option(module: ModuleType, class_name: str, value: Any) -> Any:
    """Build one optional native nested dataclass from a mapping."""

    option_type = getattr(module, class_name, None)
    if option_type is None or not isinstance(value, Mapping):
        return value
    try:
        return option_type(**_export_supported_kwargs(option_type, dict(value)))
    except Exception as exc:
        raise AnalysisConfigurationError(
            f"Unable to build native {class_name}.",
            stage=STAGE_EXPORT,
            code="native_export_option_invalid",
            details={"option_type": class_name},
            cause=exc,
        ) from exc


def build_native_export_options(
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Build the native ExportOptions consumed by export.py."""

    module = _require_export_module(export_module)
    option_type = getattr(module, "ExportOptions")
    values: Dict[str, Any] = {
        "output_dir": config.output_directory,
        "basename": config.basename,
        "formats": config.formats,
        "layout": config.layout,
        "detail": config.detail,
        "overwrite": config.overwrite,
        "error_mode": config.error_mode,
        "encoding": config.encoding,
        "newline": config.newline,
        "float_precision": config.float_precision,
        "compression": config.compression,
        "hash_algorithm": config.hash_algorithm,
        "create_directories": config.create_directories,
        "atomic_write": config.atomic_write,
        "backup_existing": config.backup_existing,
        "include_metadata": config.include_metadata,
        "include_manifest": config.include_manifest,
        "include_provenance": config.include_provenance,
        "include_empty_tables": config.include_empty_tables,
        "include_raw_objects": config.include_raw_objects,
        "update_model_files": config.update_dock_model_files,
        "preserve_previous_files": config.preserve_previous_files,
        "selected_tables": config.selected_tables,
        "excluded_tables": config.excluded_tables,
        "metadata": dict(config.metadata),
    }
    values.update(dict(config.export_options))
    for key, class_name in (
        ("json", "JSONExportOptions"),
        ("delimited", "DelimitedExportOptions"),
        ("excel", "ExcelExportOptions"),
    ):
        if key in values:
            values[key] = _export_build_nested_option(module, class_name, values[key])
    try:
        return option_type(**_export_supported_kwargs(option_type, values))
    except Exception as exc:
        raise AnalysisConfigurationError(
            "Unable to build native export options.",
            stage=STAGE_EXPORT,
            code="native_export_options_invalid",
            cause=exc,
        ) from exc


def build_native_multipose_export_options(
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Build native multipose export options."""

    module = _require_export_module(export_module)
    option_type = getattr(module, "MultiposeExportOptions")
    values = {
        "export": build_native_export_options(config, export_module=module),
        "include_individual_poses": config.include_individual_poses,
        "separate_pose_directories": config.separate_pose_directories,
        "include_combined_payload": config.include_combined_payload,
        "include_ranking": config.include_ranking,
        "pose_prefix": config.pose_prefix,
        "metadata": dict(config.metadata),
    }
    return option_type(**_export_supported_kwargs(option_type, values))


def build_native_batch_export_options(
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Build native batch export options."""

    module = _require_export_module(export_module)
    option_type = getattr(module, "BatchExportOptions")
    values = {
        "export": build_native_export_options(config, export_module=module),
        "separate_pose_directories": config.separate_pose_directories,
        "consolidate_tables": config.consolidate_tables,
        "continue_on_error": config.continue_on_error,
        "max_failures": config.max_failures,
        "write_batch_manifest": config.write_batch_manifest,
        "batch_name": config.basename,
        "pose_prefix": config.pose_prefix,
        "metadata": dict(config.metadata),
    }
    return option_type(**_export_supported_kwargs(option_type, values))


def build_native_export_validation_options(
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Build native export validation options when supported."""

    module = _require_export_module(export_module)
    option_type = getattr(module, "ExportValidationOptions", None)
    if option_type is None:
        return None
    values = dict(config.validation_options)
    values.setdefault("require_source", True)
    values.setdefault("require_output_dir", True)
    values.setdefault("check_output_writable", True)
    values.setdefault("check_serializable", True)
    values.setdefault("require_files_for_success", True)
    return option_type(**_export_supported_kwargs(option_type, values))


def build_native_permissive_export_options(
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Build native permissive export policies when supported."""

    module = _require_export_module(export_module)
    option_type = getattr(module, "PermissiveExportOptions", None)
    if option_type is None:
        return None
    values = dict(config.permissive_options)
    values.setdefault("enabled", config.permissive)
    values.setdefault("validate_before_export", config.validate_before_export)
    values.setdefault("continue_after_validation_errors", True)
    values.setdefault("continue_after_format_errors", True)
    values.setdefault("continue_after_manifest_error", True)
    values.setdefault("update_model_files_on_partial", config.update_dock_model_files)
    values.setdefault("fallback_formats", ("json",))
    values.setdefault("metadata", dict(config.metadata))
    return option_type(**_export_supported_kwargs(option_type, values))


def build_native_model_files_options(
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Build native DockModel.files update options when supported."""

    module = _require_export_module(export_module)
    option_type = getattr(module, "ModelFilesUpdateOptions", None)
    if option_type is None:
        return None
    values = dict(config.model_files_options)
    values.setdefault("preserve_existing", config.preserve_previous_files)
    values.setdefault("replace_matching_formats", not config.preserve_previous_files)
    values.setdefault("relative_to", config.output_directory)
    values.setdefault("deduplicate", True)
    return option_type(**_export_supported_kwargs(option_type, values))


# 24.8. Native result adaptation and attachment
# -----------------------------------------------------------------------------


def adapt_exported_file(value: Any) -> ExportArtifact:
    """Adapt one native ExportedFile-like object."""

    path = get_object_value(value, "path", default="", include_aliases=False)
    export_format = get_object_value(value, "format", default=None, include_aliases=False)
    if export_format is None and path:
        export_format = Path(str(path)).suffix.lstrip(".")
    created_at = get_object_value(value, "created_at", default=None, include_aliases=False)
    if isinstance(created_at, datetime):
        created_at = created_at.isoformat()
    return ExportArtifact(
        path=str(path),
        format=export_format or "json",
        status=get_object_value(value, "status", default="success", include_aliases=False),
        table=get_object_value(value, "table", default=None, include_aliases=False),
        sheet_names=tuple(get_object_value(value, "sheet_names", default=(), include_aliases=False) or ()),
        record_count=get_object_value(value, "record_count", default=None, include_aliases=False),
        size_bytes=get_object_value(value, "size_bytes", default=None, include_aliases=False),
        hash_value=get_object_value(value, "hash_value", default=None, include_aliases=False),
        hash_algorithm=get_object_value(value, "hash_algorithm", default=None, include_aliases=False),
        created_at=created_at,
        metadata=dict(get_object_value(value, "metadata", default={}, include_aliases=False) or {}),
        native_file=value,
    )


def _export_native_status(value: Any) -> ExportIntegrationStatus:
    """Map a native export status to the integration status."""

    token = _export_token(get_object_value(value, "status", default="pending", include_aliases=False), default="pending")
    mapping = {
        "pending": ExportIntegrationStatus.PENDING,
        "success": ExportIntegrationStatus.SUCCEEDED,
        "succeeded": ExportIntegrationStatus.SUCCEEDED,
        "partial": ExportIntegrationStatus.PARTIAL,
        "failed": ExportIntegrationStatus.FAILED,
        "failure": ExportIntegrationStatus.FAILED,
        "skipped": ExportIntegrationStatus.SKIPPED,
    }
    return mapping.get(token, ExportIntegrationStatus.PARTIAL if get_object_value(value, "files", default=(), include_aliases=False) else ExportIntegrationStatus.FAILED)


def adapt_native_export_result(
    native_result: Any,
    *,
    target: ExportStageTarget,
    config: ExportIntegrationConfig,
    validation_before: Any = None,
    validation_after: Any = None,
    reused: bool = False,
) -> ExportStageOutput:
    """Adapt one native export or permissive-export result."""

    result = native_result
    recovery_report = None
    nested = get_object_value(native_result, "result", default=None, include_aliases=False)
    if nested is not None and nested is not native_result:
        recovery_report = native_result
        result = nested
    files = list(get_object_value(result, "files", default=(), include_aliases=False) or ())
    if len(files) > MAX_EXPORT_ARTIFACTS:
        raise AnalysisValidationError(
            "The export result contains too many file records.",
            stage=STAGE_EXPORT,
            code="export_artifact_limit_exceeded",
            details={"count": len(files), "limit": MAX_EXPORT_ARTIFACTS},
        )
    artifacts = [adapt_exported_file(item) for item in files]
    warnings_value = list(get_object_value(result, "warnings", default=(), include_aliases=False) or ())
    errors_value = list(get_object_value(result, "errors", default=(), include_aliases=False) or ())
    if recovery_report is not None:
        warnings_value.extend(list(get_object_value(recovery_report, "recovered_errors", default=(), include_aliases=False) or ()))
    status = ExportIntegrationStatus.REUSED if reused else _export_native_status(result)
    output = ExportStageOutput(
        target=target,
        config=config,
        status=status,
        native_result=native_result,
        artifacts=artifacts,
        manifest=get_object_value(result, "manifest", default=None, include_aliases=False),
        validation_before=validation_before or get_object_value(recovery_report, "validation", default=None, include_aliases=False),
        validation_after=validation_after,
        reused=reused,
        warnings=warnings_value,
        errors=errors_value,
        started_at=str(get_object_value(result, "started_at", default=_utc_timestamp(), include_aliases=False)),
        finished_at=str(get_object_value(result, "finished_at", default=_utc_timestamp(), include_aliases=False)),
        metadata={
            "native_result_type": type(native_result).__name__,
            "native_status": _export_token(get_object_value(result, "status", default="", include_aliases=False)),
            "recovered": bool(get_object_value(recovery_report, "recovered", default=False, include_aliases=False)),
        },
    )
    output.duration_seconds = get_object_value(result, "duration_seconds", default=None, include_aliases=False, call=True)
    if output.duration_seconds is None:
        output.duration_seconds = _export_duration(output.started_at, output.finished_at)
    return output


def _export_reusable_output_from_value(value: Any, fingerprint: str) -> Optional[ExportStageOutput]:
    """Return a compatible reusable export output from one stored value."""

    if isinstance(value, ExportStageOutput):
        stored = value.metadata.get("config_fingerprint") or value.config.fingerprint
        if stored == fingerprint and value.succeeded:
            return value
    if isinstance(value, Mapping):
        for candidate in reversed(tuple(value.values())):
            reusable = _export_reusable_output_from_value(candidate, fingerprint)
            if reusable is not None:
                return reusable
    return None


def find_reusable_export_output(
    target: ExportStageTarget,
    config: ExportIntegrationConfig,
) -> Optional[ExportStageOutput]:
    """Find a compatible prior export output on the source or DockModels."""

    if not config.reuse_result:
        return None
    candidates = (target.source, *target.dock_models)
    for candidate in candidates:
        for field_name in EXPORT_REUSE_FIELDS:
            value = get_object_value(candidate, field_name, default=None, include_aliases=False)
            reusable = _export_reusable_output_from_value(value, config.fingerprint)
            if reusable is not None:
                reused = copy.copy(reusable)
                reused.reused = True
                reused.status = ExportIntegrationStatus.REUSED
                return reused
    return None


def _export_attach_collection(model: Any, output: ExportStageOutput) -> bool:
    """Attach one output to the model export collection."""

    current = get_object_value(model, EXPORT_DOCK_MODEL_COLLECTION_FIELD, default=None, include_aliases=False)
    if not isinstance(current, MutableMapping):
        current = {} if current is None else {"previous": current}
    else:
        current = dict(current)
    current[output.config.basename] = output
    return set_object_value(
        model,
        EXPORT_DOCK_MODEL_COLLECTION_FIELD,
        current,
        include_aliases=False,
        prefer_existing=True,
        strict=False,
    )


def attach_export_output_to_dock_models(
    output: ExportStageOutput,
    *,
    export_module: Optional[ModuleType] = None,
) -> Dict[str, Any]:
    """Attach export output and update files on associated DockModels."""

    if not output.config.attach_result and not output.config.update_dock_model_files:
        return {}
    module = _require_export_module(export_module)
    reports: Dict[str, Any] = {}
    native_result = output.native_result
    nested_result = get_object_value(native_result, "result", default=None, include_aliases=False)
    if nested_result is not None:
        native_result = nested_result
    file_options = build_native_model_files_options(output.config, export_module=module)
    for index, model in enumerate(output.target.dock_models):
        model_name = normalize_text(get_object_value(model, "name", default=f"model_{index + 1}"), default=f"model_{index + 1}")
        if output.config.attach_result:
            set_object_value(
                model,
                EXPORT_DOCK_MODEL_FIELD,
                output,
                include_aliases=False,
                prefer_existing=True,
                strict=False,
            )
            _export_attach_collection(model, output)
        if output.config.update_dock_model_files and native_result is not None:
            updater = getattr(module, "update_dock_model_files_from_result", None)
            if callable(updater):
                try:
                    report = updater(model, native_result, options=file_options)
                    reports[model_name] = _export_native_to_data(report)
                except Exception as exc:
                    reports[model_name] = {"error": str(exc)}
                    output.warnings.append(f"DockModel.files update failed for {model_name}: {exc}")
    output.model_file_updates.update(reports)
    output.attached = bool(output.target.dock_models and output.config.attach_result)
    return reports


# 24.9. Validation and native execution
# -----------------------------------------------------------------------------


def _export_validation_valid(report: Any) -> bool:
    """Return whether a native validation report is valid."""

    if report is None:
        return True
    value = get_object_value(report, "valid", default=None, include_aliases=False, call=True)
    if value is not None:
        return bool(value)
    return not bool(get_object_value(report, "errors", default=(), include_aliases=False))


def validate_export_target_preflight(
    target: ExportStageTarget,
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Run native preflight validation for the resolved target."""

    module = _require_export_module(export_module)
    if config.output_directory is None:
        raise AnalysisConfigurationError(
            "Export output_directory is required.",
            stage=STAGE_EXPORT,
            code="export_output_directory_required",
        )
    validation = build_native_export_validation_options(config, export_module=module)
    native_options = build_native_export_options(config, export_module=module)
    validator = getattr(module, "validate_export_request", None)
    if callable(validator) and target.export_sources:
        reports = []
        for source in target.export_sources:
            reports.append(validator(source, native_options, validation=validation))
        invalid = [report for report in reports if not _export_validation_valid(report)]
        if invalid and config.strict_validation:
            messages = []
            for report in invalid:
                messages.extend(str(item) for item in get_object_value(report, "issues", default=(), include_aliases=False) or ())
            raise AnalysisValidationError(
                "Export preflight validation failed." + (" " + " ".join(messages) if messages else ""),
                stage=STAGE_EXPORT,
                code="export_preflight_validation_failed",
            )
        return reports[0] if len(reports) == 1 else tuple(reports)
    option_validator = getattr(module, "validate_export_options", None)
    return option_validator(native_options, validation=validation) if callable(option_validator) else None


def validate_native_export_result(
    native_result: Any,
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Validate a native export result."""

    module = _require_export_module(export_module)
    validation = build_native_export_validation_options(config, export_module=module)
    result = get_object_value(native_result, "result", default=native_result, include_aliases=False)
    validator = getattr(module, "validate_export_result", None)
    if not callable(validator) or result is None:
        return None
    report = validator(result, validation=validation)
    if not _export_validation_valid(report) and config.strict_validation:
        raise AnalysisValidationError(
            "Export result validation failed.",
            stage=STAGE_EXPORT,
            code="export_result_validation_failed",
            details={"validation": _export_native_to_data(report)},
        )
    return report


def _run_native_export(
    target: ExportStageTarget,
    config: ExportIntegrationConfig,
    *,
    export_module: Optional[ModuleType] = None,
) -> Any:
    """Execute the appropriate native export workflow."""

    module = _require_export_module(export_module)
    sources = target.export_sources
    if not sources:
        raise AnalysisInputError(
            "The export target contains no sources.",
            stage=STAGE_EXPORT,
            code="empty_export_target",
        )
    if target.kind is ExportTargetKind.BATCH:
        options = build_native_batch_export_options(config, export_module=module)
        if config.permissive and callable(getattr(module, "export_batch_permissive", None)):
            return module.export_batch_permissive(
                sources,
                options=options,
                permissive=build_native_permissive_export_options(config, export_module=module),
                output_dir=config.output_directory,
            )
        return module.export_batch(sources, options=options, output_dir=config.output_directory)
    if target.kind is ExportTargetKind.MULTIPOSE or len(sources) > 1:
        options = build_native_multipose_export_options(config, export_module=module)
        if config.permissive and callable(getattr(module, "export_multipose_permissive", None)):
            return module.export_multipose_permissive(
                sources,
                options=options,
                permissive=build_native_permissive_export_options(config, export_module=module),
                output_dir=config.output_directory,
            )
        return module.export_multiple_poses(
            sources,
            options=options,
            output_dir=config.output_directory,
            basename=config.basename,
        )
    source = sources[0]
    options = build_native_export_options(config, export_module=module)
    if config.permissive and callable(getattr(module, "export_single_pose_permissive", None)):
        return module.export_single_pose_permissive(
            source,
            options=options,
            permissive=build_native_permissive_export_options(config, export_module=module),
            validation=build_native_export_validation_options(config, export_module=module),
            output_dir=config.output_directory,
            basename=config.basename,
            metadata=dict(config.metadata),
        )
    return module.export_single_pose(
        source,
        options=options,
        output_dir=config.output_directory,
        basename=config.basename,
        metadata=dict(config.metadata),
    )


def run_export_analysis(
    source: Any = None,
    *,
    context: Optional[AnalysisContext] = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    dock_model: Any = None,
    config: ExportIntegrationConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    export_module: Optional[ModuleType] = None,
) -> ExportStageOutput:
    """Resolve, execute, validate and attach one export operation."""

    module = _require_export_module(export_module)
    active = resolve_export_integration_config(config or (context.config if context is not None else None), overrides=overrides)
    target = resolve_export_stage_target(
        source,
        context=context,
        pose_result=pose_result,
        multipose_result=multipose_result,
        batch_result=batch_result,
        run_result=run_result,
        dock_model=dock_model,
    )
    reusable = find_reusable_export_output(target, active)
    if reusable is not None:
        reusable.metadata["config_fingerprint"] = active.fingerprint
        return reusable
    validation_before = None
    if active.validate_before_export:
        validation_before = validate_export_target_preflight(target, active, export_module=module)
    native_result = _run_native_export(target, active, export_module=module)
    validation_after = None
    if active.validate_after_export:
        validation_after = validate_native_export_result(native_result, active, export_module=module)
    output = adapt_native_export_result(
        native_result,
        target=target,
        config=active,
        validation_before=validation_before,
        validation_after=validation_after,
    )
    output.metadata.update(
        {
            "config_fingerprint": active.fingerprint,
            "schema": EXPORT_INTEGRATION_SCHEMA_NAME,
            "schema_version": EXPORT_INTEGRATION_SCHEMA_VERSION,
        }
    )
    attach_export_output_to_dock_models(output, export_module=module)
    return output


def run_pose_export_analysis(
    pose: Any,
    *,
    config: ExportIntegrationConfigLike = None,
    output_directory: Optional[PathLike] = None,
    export_module: Optional[ModuleType] = None,
) -> ExportStageOutput:
    """Export one pose or pose-analysis result."""

    overrides = {"output_directory": output_directory} if output_directory is not None else None
    return run_export_analysis(pose_result=pose, config=config, overrides=overrides, export_module=export_module)


def run_multipose_export_analysis(
    poses: Any,
    *,
    config: ExportIntegrationConfigLike = None,
    output_directory: Optional[PathLike] = None,
    export_module: Optional[ModuleType] = None,
) -> ExportStageOutput:
    """Export a multipose analysis or pose collection."""

    overrides = {"output_directory": output_directory} if output_directory is not None else None
    return run_export_analysis(multipose_result=poses, config=config, overrides=overrides, export_module=export_module)


def run_batch_export_analysis(
    batch: Any,
    *,
    config: ExportIntegrationConfigLike = None,
    output_directory: Optional[PathLike] = None,
    export_module: Optional[ModuleType] = None,
) -> ExportStageOutput:
    """Export a batch result or independent source collection."""

    overrides = {"output_directory": output_directory} if output_directory is not None else None
    return run_export_analysis(batch_result=batch, config=config, overrides=overrides, export_module=export_module)


# 24.10. Stage conversion and registry executor
# -----------------------------------------------------------------------------


def export_stage_output_to_result(
    output: ExportStageOutput,
    *,
    required: bool = False,
) -> AnalysisStageResult:
    """Convert integrated export output to AnalysisStageResult."""

    result = AnalysisStageResult(stage=STAGE_EXPORT, required=required)
    result.start()
    validation_messages = validate_export_stage_output(output)
    if output.status is ExportIntegrationStatus.FAILED:
        error = AnalysisExportError(
            "Export execution failed.",
            stage=STAGE_EXPORT,
            code="export_execution_failed",
            details={"errors": to_json_compatible(output.errors)},
        )
        result.fail(error)
    elif output.status is ExportIntegrationStatus.PARTIAL or validation_messages:
        issue = AnalysisIssue(
            severity=IssueSeverity.WARNING,
            kind=IssueKind.WARNING,
            details={"category": "output"},
            code="partial_export_output",
            message="Export produced partial output." if not validation_messages else " ".join(validation_messages),
            stage=STAGE_EXPORT,
        )
        result.partial(output, issue=issue, message="Export completed with partial output.")
    elif output.status is ExportIntegrationStatus.SKIPPED:
        result.skip("Export was skipped.")
    else:
        result.succeed(output, message="Export completed successfully.")
    result.statistics.update(
        {
            "file_count": output.file_count,
            "format_count": len({artifact.format for artifact in output.artifacts}),
            "warning_count": len(output.warnings),
            "error_count": len(output.errors),
            "attached": output.attached,
            "reused": output.reused,
        }
    )
    result.files.update(output.written_files)
    result.output_summary.update(summarize_export_stage(output))
    result.metadata.update(
        {
            "schema": EXPORT_INTEGRATION_SCHEMA_NAME,
            "schema_version": EXPORT_INTEGRATION_SCHEMA_VERSION,
            "config_fingerprint": output.config.fingerprint,
        }
    )
    result.duration_seconds = output.duration_seconds
    return result


def execute_export_stage(
    context: AnalysisContext,
    *,
    dock_model: Any = None,
    source: Any = None,
    analysis_result: Any = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    config: ExportIntegrationConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    export_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
    **_: Any,
) -> AnalysisStageResult:
    """Registry-compatible export-stage executor."""

    stage_config = context.config.stage_configs.get(STAGE_EXPORT)
    required = bool(stage_config.required) if stage_config is not None else False
    result = AnalysisStageResult(stage=STAGE_EXPORT, required=required)
    result.start()
    context.set_current_stage(STAGE_EXPORT)
    try:
        effective_source = analysis_result if analysis_result is not None else source
        output = run_export_analysis(
            effective_source,
            context=context,
            pose_result=pose_result,
            multipose_result=multipose_result,
            batch_result=batch_result,
            run_result=run_result,
            dock_model=dock_model,
            config=config or context.config,
            overrides=overrides,
            export_module=export_module,
        )
        result = export_stage_output_to_result(output, required=required)
        context.set_shared(EXPORT_SHARED_OUTPUT_KEY, output)
        context.set_shared(EXPORT_SHARED_RESULT_KEY, output.native_result)
        context.set_shared(EXPORT_SHARED_ARTIFACTS_KEY, tuple(output.artifacts))
        context.set_shared(EXPORT_SHARED_MANIFEST_KEY, output.manifest)
        context.files.update(output.written_files)
    except Exception as exc:
        wrapped = exc if isinstance(exc, AnalysisError) else AnalysisExportError(
            "Result export failed.",
            stage=STAGE_EXPORT,
            code="result_export_failed",
            cause=exc,
        )
        result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
        if raise_on_error or context.config.runtime.is_strict:
            context.set_stage_data(STAGE_EXPORT, result)
            context.set_current_stage(None)
            raise wrapped
    finally:
        context.set_stage_data(STAGE_EXPORT, result)
        context.set_current_stage(None)
    return result


# 24.11. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_export_stage_output(value: Any) -> Tuple[str, ...]:
    """Return validation messages for an export-stage output."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, ExportStageOutput):
        return ("Value is not an ExportStageOutput.",)
    failures: List[str] = []
    if value.config.output_directory is None and not value.reused:
        failures.append("Export output directory is missing.")
    if value.status in {ExportIntegrationStatus.SUCCEEDED, ExportIntegrationStatus.REUSED} and not value.artifacts:
        failures.append("Successful export contains no artifacts.")
    if len(value.artifacts) > MAX_EXPORT_ARTIFACTS:
        failures.append("Export artifact count exceeds the safety limit.")
    for artifact in value.artifacts:
        if not artifact.path:
            failures.append("An export artifact has no path.")
        if artifact.succeeded and not artifact.exists and not value.reused:
            failures.append(f"Export artifact does not exist: {artifact.path}.")
    if value.config.validate_after_export and not _export_validation_valid(value.validation_after):
        failures.append("Native export-result validation failed.")
    return tuple(unique_preserving_order(failures))


def summarize_export_stage(value: Any) -> Dict[str, Any]:
    """Return a compact export-stage summary."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, ExportStageOutput):
        return {"valid": False, "type": type(value).__name__}
    return {
        "valid": not bool(validate_export_stage_output(value)),
        "status": value.status.value,
        "target_kind": value.target.kind.value,
        "target_name": value.target.name,
        "formats": list(unique_preserving_order(artifact.format for artifact in value.artifacts)),
        "file_count": value.file_count,
        "written_files": dict(value.written_files),
        "manifest": value.manifest is not None,
        "attached": value.attached,
        "reused": value.reused,
        "warning_count": len(value.warnings),
        "error_count": len(value.errors),
        "duration_seconds": value.duration_seconds,
    }


def export_stage_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize export-stage output as JSON."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if isinstance(value, ExportStageOutput):
        return value.to_json(indent=indent)
    return json.dumps(to_json_compatible(value), indent=indent, sort_keys=True, ensure_ascii=False)


def export_stage_result_adapter(value: Any, **kwargs: Any) -> AnalysisStageResult:
    """Registry-compatible adapter for export values."""

    if isinstance(value, AnalysisStageResult):
        return value
    if isinstance(value, ExportStageOutput):
        return export_stage_output_to_result(value, required=bool(kwargs.get("required", False)))
    target = kwargs.get("target")
    if not isinstance(target, ExportStageTarget):
        target = ExportStageTarget(
            source=value,
            kind=_export_source_kind(value),
            items=_export_collect_items(value, _export_source_kind(value), _export_collect_dock_models(value)),
            dock_models=_export_collect_dock_models(value),
            name=_export_source_name(value),
        )
    active = resolve_export_integration_config(kwargs.get("config"))
    output = adapt_native_export_result(value, target=target, config=active)
    return export_stage_output_to_result(output, required=bool(kwargs.get("required", False)))


def export_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible export-stage validator."""

    return validate_export_stage_output(value)


# 24.12. Stage registration
# -----------------------------------------------------------------------------


def register_export_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register export execution, adaptation and validation."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_EXPORT)
    metadata = dict(definition.metadata)
    metadata.update(
        {
            "schema": EXPORT_INTEGRATION_SCHEMA_NAME,
            "schema_version": EXPORT_INTEGRATION_SCHEMA_VERSION,
            "result_type": EXPORT_INTEGRATION_RESULT_TYPE,
            "supported_formats": EXPORT_SUPPORTED_FORMATS,
            "supports_pose": True,
            "supports_multipose": True,
            "supports_batch": True,
            "supports_manifest": True,
            "supports_permissive_mode": True,
            "updates_dock_model_files": True,
            "preserves_native_result": True,
        }
    )
    updated = replace(
        definition,
        executor=execute_export_stage,
        result_adapter=export_stage_result_adapter,
        validator=export_stage_validator,
        metadata=metadata,
    )
    target_registry.replace(updated)
    return updated


def export_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the export adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_EXPORT)
    return bool(
        definition is not None
        and definition.executor is execute_export_stage
        and definition.result_adapter is export_stage_result_adapter
        and definition.validator is export_stage_validator
    )


# 24.13. Convention validation
# -----------------------------------------------------------------------------


def validate_export_integration_conventions() -> Dict[str, Any]:
    """Validate export configuration, execution, validation and attachment."""

    failures: List[str] = []
    if canonicalize_export_format("excel") != "xlsx":
        failures.append("Export format alias resolution failed.")
    if canonicalize_export_overwrite(True) != "overwrite":
        failures.append("Export overwrite-mode normalization failed.")
    config = ExportIntegrationConfig.from_mapping(
        {
            "formats": ("json", "csv", "text"),
            "layout": "multiple",
            "detail": "standard",
            "overwrite": True,
            "attach": True,
            "reuse": True,
            "validate_before": True,
            "validate_after": True,
            "basename": "section24_validation",
        }
    )
    if config.formats != ("json", "csv", "txt"):
        failures.append("Export format normalization failed.")
    if config.layout != "multiple_files":
        failures.append("Export layout normalization failed.")
    if len(config.fingerprint) != 64:
        failures.append("Export configuration fingerprint is invalid.")
    if not export_stage_adapter_registered():
        failures.append("Export stage adapter is not registered.")
    try:
        module = _require_export_module()
    except (AnalysisDependencyError, AnalysisCapabilityError, ModuleNotFoundError):
        raise
    except Exception as exc:
        failures.append(f"The real export module could not be loaded: {exc}")
        module = None
    if module is not None:
        dock_model = SimpleNamespace(
            name="section24_model",
            receptor=None,
            pose=None,
            ligand=None,
            interactions=[],
            hbonds=[],
            hydrophobic=[],
            pi=[],
            saltbridge=[],
            score=1.25,
            statistics={},
            metadata={},
            files={},
        )
        with TemporaryDirectory(prefix="dockanalyzer_export_section24_") as directory:
            active = replace(
                config,
                output_directory=Path(directory),
                formats=("json", "csv", "txt"),
                include_manifest=True,
                export_options={"include_empty_tables": True},
            )
            output = run_pose_export_analysis(dock_model, config=active, export_module=module)
            if not output.succeeded:
                failures.append("Real single-pose export did not succeed.")
            if not output.artifacts:
                failures.append("Real single-pose export produced no artifacts.")
            if any(not Path(artifact.path).is_file() for artifact in output.artifacts):
                failures.append("At least one real export artifact is missing.")
            if validate_export_stage_output(output):
                failures.append("Real export-stage output validation failed.")
            if not output.to_json(indent=None):
                failures.append("Export-stage JSON serialization failed.")
            if get_object_value(dock_model, EXPORT_DOCK_MODEL_FIELD, default=None, include_aliases=False) is None:
                failures.append("Export output was not attached to the DockModel.")
            if not get_object_value(dock_model, "files", default={}, include_aliases=False):
                failures.append("DockModel.files was not updated.")
            reused = run_pose_export_analysis(dock_model, config=active, export_module=module)
            if not reused.reused:
                failures.append("Compatible export result was not reused.")
            request = AnalysisRequest(
                config=AnalysisConfig(
                    output=AnalysisOutputConfig(
                        export_results=True,
                        export_formats=("json",),
                        output_directory=Path(directory),
                        file_prefix="section24_stage",
                        overwrite=True,
                    )
                ),
                dock_models=(dock_model,),
            )
            context = AnalysisContext(request=request, dock_models=[dock_model], current_pose_index=0)
            stage = execute_export_stage(
                context,
                dock_model=dock_model,
                config=replace(active, formats=("json",), basename="section24_stage", reuse_result=False),
                export_module=module,
                raise_on_error=True,
            )
            if not stage.succeeded:
                failures.append("Registered export-stage execution failed.")
            if context.get_shared(EXPORT_SHARED_OUTPUT_KEY) is None:
                failures.append("Export output was not stored in the context.")
            multipose = run_multipose_export_analysis(
                (dock_model, SimpleNamespace(**{**dock_model.__dict__, "name": "section24_model_2", "files": {}})),
                config=replace(active, formats=("json",), basename="section24_multipose", reuse_result=False),
                export_module=module,
            )
            if multipose.status is ExportIntegrationStatus.FAILED:
                failures.append("Real multipose export failed.")
    if failures:
        raise RuntimeError(
            "Export integration convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": EXPORT_INTEGRATION_SCHEMA_NAME,
        "schema_version": EXPORT_INTEGRATION_SCHEMA_VERSION,
        "supported_formats": len(EXPORT_SUPPORTED_FORMATS),
        "supported_layouts": len(EXPORT_SUPPORTED_LAYOUTS),
        "validated_cases": 38,
    }


