# 25.2. Canonicalization helpers
# -----------------------------------------------------------------------------


def _visualization_token(value: Any, *, default: str = "") -> str:
    """Return a normalized visualization token."""

    return _output_convention_token(value, default=default)


def canonicalize_visualization_profile(value: Any) -> str:
    """Return a supported visualization profile."""

    token = _visualization_token(value, default=DEFAULT_VISUALIZATION_PROFILE)
    canonical = VISUALIZATION_PROFILE_ALIASES.get(token, token)
    if canonical not in VISUALIZATION_SUPPORTED_PROFILES:
        raise AnalysisConfigurationError(
            f"Unsupported visualization profile: {value!r}.",
            stage=STAGE_VISUALIZATION,
            code="unsupported_visualization_profile",
            details={"supported": list(VISUALIZATION_SUPPORTED_PROFILES)},
        )
    return canonical


def canonicalize_visualization_execution_mode(value: Any) -> str:
    """Return a supported visualization execution mode."""

    token = _visualization_token(value, default=DEFAULT_VISUALIZATION_EXECUTION_MODE)
    canonical = VISUALIZATION_EXECUTION_ALIASES.get(token, token)
    if canonical not in VISUALIZATION_SUPPORTED_EXECUTION_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported visualization execution mode: {value!r}.",
            stage=STAGE_VISUALIZATION,
            code="unsupported_visualization_execution_mode",
            details={"supported": list(VISUALIZATION_SUPPORTED_EXECUTION_MODES)},
        )
    return canonical


def canonicalize_visualization_integration_mode(value: Any) -> str:
    """Return a supported DockModel integration mode."""

    token = _visualization_token(value, default=DEFAULT_VISUALIZATION_INTEGRATION_MODE)
    canonical = VISUALIZATION_INTEGRATION_ALIASES.get(token, token)
    if canonical not in VISUALIZATION_SUPPORTED_INTEGRATION_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported visualization integration mode: {value!r}.",
            stage=STAGE_VISUALIZATION,
            code="unsupported_visualization_integration_mode",
            details={"supported": list(VISUALIZATION_SUPPORTED_INTEGRATION_MODES)},
        )
    return canonical


def canonicalize_visualization_command_format(value: Any) -> str:
    """Return a supported command-export format."""

    token = _visualization_token(value, default="cxc")
    canonical = VISUALIZATION_COMMAND_FORMAT_ALIASES.get(token, token)
    if canonical not in VISUALIZATION_SUPPORTED_COMMAND_FORMATS:
        raise AnalysisConfigurationError(
            f"Unsupported visualization command format: {value!r}.",
            stage=STAGE_VISUALIZATION,
            code="unsupported_visualization_command_format",
        )
    return canonical


def canonicalize_visualization_image_format(value: Any) -> str:
    """Return a supported snapshot format."""

    token = _visualization_token(value, default="png")
    canonical = VISUALIZATION_IMAGE_FORMAT_ALIASES.get(token, token)
    if canonical not in VISUALIZATION_SUPPORTED_IMAGE_FORMATS:
        raise AnalysisConfigurationError(
            f"Unsupported visualization image format: {value!r}.",
            stage=STAGE_VISUALIZATION,
            code="unsupported_visualization_image_format",
        )
    return canonical


def canonicalize_visualization_target_kind(value: Any) -> VisualizationTargetKind:
    """Return a canonical visualization target kind."""

    if isinstance(value, VisualizationTargetKind):
        return value
    token = _visualization_token(value, default="generic")
    aliases = {
        "single": VisualizationTargetKind.POSE,
        "single_pose": VisualizationTargetKind.POSE,
        "pose": VisualizationTargetKind.POSE,
        "multipose": VisualizationTargetKind.MULTIPOSE,
        "multi_pose": VisualizationTargetKind.MULTIPOSE,
        "poses": VisualizationTargetKind.MULTIPOSE,
        "batch": VisualizationTargetKind.BATCH,
        "run": VisualizationTargetKind.RUN,
        "analysis_run": VisualizationTargetKind.RUN,
        "dockmodel": VisualizationTargetKind.DOCK_MODEL,
        "dock_model": VisualizationTargetKind.DOCK_MODEL,
        "model": VisualizationTargetKind.DOCK_MODEL,
        "generic": VisualizationTargetKind.GENERIC,
    }
    return aliases.get(token, VisualizationTargetKind.GENERIC)


def normalize_visualization_layers(value: Any) -> Mapping[str, bool]:
    """Return a complete immutable high-level layer mapping."""

    defaults = {
        "scene": True,
        "receptor": True,
        "ligand": True,
        "interactions": True,
        "virtual_points": False,
        "residues": True,
        "hotspots": False,
        "scoring": False,
        "multipose": True,
        "consensus": False,
        "complementarity": False,
        "annotations": False,
        "camera": True,
    }
    if value is None:
        return MappingProxyType(defaults)
    if isinstance(value, Mapping):
        unknown = set(value) - set(VISUALIZATION_LAYER_NAMES)
        if unknown:
            raise AnalysisConfigurationError(
                "Unknown visualization layer names were provided.",
                stage=STAGE_VISUALIZATION,
                code="unknown_visualization_layers",
                details={"layers": sorted(str(item) for item in unknown)},
            )
        for name, enabled in value.items():
            defaults[str(name)] = bool(enabled)
        return MappingProxyType(defaults)
    if isinstance(value, str):
        value = (value,)
    try:
        enabled_names = {
            _visualization_token(item)
            for item in value
        }
    except TypeError as exc:
        raise AnalysisConfigurationError(
            "Visualization layers must be a mapping or iterable of names.",
            stage=STAGE_VISUALIZATION,
            code="invalid_visualization_layers",
            cause=exc,
        ) from exc
    unknown = enabled_names - set(VISUALIZATION_LAYER_NAMES)
    if unknown:
        raise AnalysisConfigurationError(
            "Unknown visualization layer names were provided.",
            stage=STAGE_VISUALIZATION,
            code="unknown_visualization_layers",
            details={"layers": sorted(unknown)},
        )
    return MappingProxyType({name: name in enabled_names for name in VISUALIZATION_LAYER_NAMES})


# 25.3. Integration configuration
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class VisualizationIntegrationConfig:
    """Control planning, execution, artifacts and DockModel attachment."""

    profile: str = DEFAULT_VISUALIZATION_PROFILE
    execution_mode: str = DEFAULT_VISUALIZATION_EXECUTION_MODE
    integration_mode: str = DEFAULT_VISUALIZATION_INTEGRATION_MODE
    layers: Mapping[str, bool] = field(default_factory=dict)
    name: str = VISUALIZATION_DEFAULT_NAME
    output_directory: Optional[Path] = None
    basename: str = VISUALIZATION_DEFAULT_BASENAME
    attach_result: bool = DEFAULT_VISUALIZATION_ATTACH_RESULT
    reuse_result: bool = DEFAULT_VISUALIZATION_REUSE_RESULT
    validate: bool = DEFAULT_VISUALIZATION_VALIDATE
    strict_validation: bool = DEFAULT_VISUALIZATION_STRICT_VALIDATION
    dry_run_outside_chimerax: bool = DEFAULT_VISUALIZATION_DRY_RUN_OUTSIDE_CHIMERAX
    include_camera: bool = DEFAULT_VISUALIZATION_INCLUDE_CAMERA
    include_multipose: bool = DEFAULT_VISUALIZATION_INCLUDE_MULTIPOSE
    continue_on_error: bool = DEFAULT_VISUALIZATION_CONTINUE_ON_ERROR
    create_snapshot: bool = False
    image_format: str = "png"
    snapshot_options: Mapping[str, Any] = field(default_factory=dict)
    export_commands: bool = False
    command_format: str = "cxc"
    command_filename: Optional[Path] = None
    command_options: Mapping[str, Any] = field(default_factory=dict)
    native_config: Mapping[str, Any] = field(default_factory=dict)
    native_request_options: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "profile", canonicalize_visualization_profile(self.profile))
        object.__setattr__(self, "execution_mode", canonicalize_visualization_execution_mode(self.execution_mode))
        object.__setattr__(self, "integration_mode", canonicalize_visualization_integration_mode(self.integration_mode))
        object.__setattr__(self, "layers", normalize_visualization_layers(self.layers))
        object.__setattr__(self, "name", normalize_text(self.name, default=VISUALIZATION_DEFAULT_NAME, maximum_length=256))
        object.__setattr__(self, "basename", normalize_text(self.basename, default=VISUALIZATION_DEFAULT_BASENAME, maximum_length=256))
        object.__setattr__(self, "image_format", canonicalize_visualization_image_format(self.image_format))
        object.__setattr__(self, "command_format", canonicalize_visualization_command_format(self.command_format))
        if self.output_directory is not None:
            object.__setattr__(self, "output_directory", Path(self.output_directory).expanduser())
        if self.command_filename is not None:
            object.__setattr__(self, "command_filename", Path(self.command_filename).expanduser())
        for name in (
            "attach_result",
            "reuse_result",
            "validate",
            "strict_validation",
            "dry_run_outside_chimerax",
            "include_camera",
            "include_multipose",
            "continue_on_error",
            "create_snapshot",
            "export_commands",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        for name in (
            "snapshot_options",
            "command_options",
            "native_config",
            "native_request_options",
            "metadata",
        ):
            value = getattr(self, name)
            if value is None:
                value = {}
            if not isinstance(value, Mapping):
                raise AnalysisConfigurationError(
                    f"visualization.{name} must be a mapping.",
                    stage=STAGE_VISUALIZATION,
                    code="invalid_visualization_mapping",
                    details={"field": name},
                )
            object.__setattr__(self, name, MappingProxyType(copy.deepcopy(dict(value))))

    def resolved_execution_mode(self, *, session: Any = None) -> str:
        """Resolve automatic execution according to the available environment."""

        if self.execution_mode != "auto":
            return self.execution_mode
        if session is not None or CHIMERAX_AVAILABLE:
            return "immediate"
        if self.export_commands:
            return "export_only"
        if self.dry_run_outside_chimerax:
            return "dry_run"
        return "deferred"

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready configuration mapping."""

        return {
            "profile": self.profile,
            "execution_mode": self.execution_mode,
            "integration_mode": self.integration_mode,
            "layers": dict(self.layers),
            "name": self.name,
            "output_directory": str(self.output_directory) if self.output_directory else None,
            "basename": self.basename,
            "attach_result": self.attach_result,
            "reuse_result": self.reuse_result,
            "validate": self.validate,
            "strict_validation": self.strict_validation,
            "dry_run_outside_chimerax": self.dry_run_outside_chimerax,
            "include_camera": self.include_camera,
            "include_multipose": self.include_multipose,
            "continue_on_error": self.continue_on_error,
            "create_snapshot": self.create_snapshot,
            "image_format": self.image_format,
            "snapshot_options": to_json_compatible(dict(self.snapshot_options)),
            "export_commands": self.export_commands,
            "command_format": self.command_format,
            "command_filename": str(self.command_filename) if self.command_filename else None,
            "command_options": to_json_compatible(dict(self.command_options)),
            "native_config": to_json_compatible(dict(self.native_config)),
            "native_request_options": to_json_compatible(dict(self.native_request_options)),
            "metadata": to_json_compatible(dict(self.metadata)),
        }

    def fingerprint(self) -> str:
        """Return a stable configuration fingerprint."""

        payload = json.dumps(self.to_dict(), sort_keys=True, ensure_ascii=True, separators=(",", ":"))
        return sha256(payload.encode("utf-8")).hexdigest()


VisualizationIntegrationConfigLike: TypeAlias = Union[
    VisualizationIntegrationConfig,
    AnalysisConfig,
    Mapping[str, Any],
    None,
]


def _visualization_config_from_analysis_config(value: AnalysisConfig) -> Dict[str, Any]:
    """Extract visualization integration options from an AnalysisConfig."""

    output = value.output
    options = dict(output.visualization_options or {})
    options.setdefault("output_directory", output.output_directory)
    options.setdefault("basename", output.file_prefix or VISUALIZATION_DEFAULT_BASENAME)
    options.setdefault("create_snapshot", output.create_snapshot)
    options.setdefault("image_format", output.image_format)
    options.setdefault("export_commands", output.export_commands)
    options.setdefault("command_format", output.command_format)
    return options


def resolve_visualization_integration_config(
    config: VisualizationIntegrationConfigLike = None,
    *,
    overrides: Optional[Mapping[str, Any]] = None,
    strict: bool = False,
) -> VisualizationIntegrationConfig:
    """Resolve integration configuration from supported inputs."""

    if isinstance(config, VisualizationIntegrationConfig):
        values = config.to_dict()
    elif isinstance(config, AnalysisConfig):
        values = _visualization_config_from_analysis_config(config)
    elif config is None:
        values = {}
    elif isinstance(config, Mapping):
        values = dict(config)
    else:
        raise AnalysisConfigurationError(
            "Visualization integration configuration must be a mapping, AnalysisConfig or VisualizationIntegrationConfig.",
            stage=STAGE_VISUALIZATION,
            code="invalid_visualization_integration_config",
        )
    if overrides:
        values.update(dict(overrides))
    allowed = {item.name for item in fields(VisualizationIntegrationConfig)}
    unknown = set(values) - allowed
    if unknown:
        if strict:
            raise AnalysisConfigurationError(
                "Unknown visualization integration options were provided.",
                stage=STAGE_VISUALIZATION,
                code="unknown_visualization_options",
                details={"options": sorted(unknown)},
            )
        values = {key: item for key, item in values.items() if key in allowed}
    return VisualizationIntegrationConfig(**values)


# 25.4. Target, artifact and stage-output records
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class VisualizationStageTarget:
    """Resolved source and DockModels for one visualization operation."""

    source: Any
    kind: VisualizationTargetKind = VisualizationTargetKind.GENERIC
    dock_models: Tuple[Any, ...] = ()
    name: str = VISUALIZATION_DEFAULT_NAME
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "kind", canonicalize_visualization_target_kind(self.kind))
        object.__setattr__(self, "dock_models", tuple(self.dock_models or ()))
        object.__setattr__(self, "name", normalize_text(self.name, default=VISUALIZATION_DEFAULT_NAME, maximum_length=512))
        object.__setattr__(self, "metadata", MappingProxyType(copy.deepcopy(dict(self.metadata or {}))))
        if len(self.dock_models) > MAX_VISUALIZATION_TARGETS:
            raise AnalysisInputError(
                "Visualization target exceeds the DockModel safety limit.",
                stage=STAGE_VISUALIZATION,
                code="visualization_target_limit_exceeded",
            )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready target summary."""

        return {
            "kind": self.kind.value,
            "name": self.name,
            "dock_model_count": len(self.dock_models),
            "dock_models": [
                normalize_text(get_object_value(model, "name", default=type(model).__name__))
                for model in self.dock_models
            ],
            "source_type": type(self.source).__name__,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass(frozen=True)
class VisualizationArtifact:
    """One file or serializable artifact produced by visualization."""

    kind: str
    path: Optional[Path] = None
    format: Optional[str] = None
    exists: bool = False
    size_bytes: Optional[int] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "kind", _visualization_token(self.kind, default="artifact"))
        if self.path is not None:
            object.__setattr__(self, "path", Path(self.path))
        object.__setattr__(self, "exists", bool(self.exists))
        if self.size_bytes is not None:
            object.__setattr__(self, "size_bytes", max(0, int(self.size_bytes)))
        object.__setattr__(self, "metadata", MappingProxyType(copy.deepcopy(dict(self.metadata or {}))))

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready artifact mapping."""

        return {
            "kind": self.kind,
            "path": str(self.path) if self.path else None,
            "format": self.format,
            "exists": self.exists,
            "size_bytes": self.size_bytes,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass(frozen=True)
class VisualizationStageOutput:
    """Normalized result of one visualization-stage operation."""

    target: VisualizationStageTarget
    config: VisualizationIntegrationConfig
    status: VisualizationIntegrationStatus = VisualizationIntegrationStatus.PENDING
    outcomes: Tuple[Any, ...] = ()
    states: Tuple[Any, ...] = ()
    plans: Tuple[Any, ...] = ()
    executions: Tuple[Any, ...] = ()
    artifacts: Tuple[VisualizationArtifact, ...] = ()
    attached_models: Tuple[Any, ...] = ()
    warnings: Tuple[str, ...] = ()
    errors: Tuple[str, ...] = ()
    reused: bool = False
    duration_seconds: float = 0.0
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "status", VisualizationIntegrationStatus(self.status))
        for name in (
            "outcomes",
            "states",
            "plans",
            "executions",
            "artifacts",
            "attached_models",
            "warnings",
            "errors",
        ):
            object.__setattr__(self, name, tuple(getattr(self, name) or ()))
        object.__setattr__(self, "reused", bool(self.reused))
        object.__setattr__(self, "duration_seconds", max(0.0, float(self.duration_seconds or 0.0)))
        object.__setattr__(self, "metadata", MappingProxyType(copy.deepcopy(dict(self.metadata or {}))))

    @property
    def succeeded(self) -> bool:
        """Return whether the stage produced usable visualization data."""

        return self.status in {
            VisualizationIntegrationStatus.SUCCEEDED,
            VisualizationIntegrationStatus.PARTIAL,
            VisualizationIntegrationStatus.REUSED,
        }

    @property
    def artifact_paths(self) -> Dict[str, str]:
        """Return generated artifact paths keyed by stable labels."""

        result: Dict[str, str] = {}
        for index, artifact in enumerate(self.artifacts, start=1):
            if artifact.path is None:
                continue
            key = artifact.kind
            if key in result:
                key = f"{key}_{index}"
            result[key] = str(artifact.path)
        return result

    def to_dict(self, *, include_native: bool = False) -> Dict[str, Any]:
        """Return a serialization-ready stage output."""

        data: Dict[str, Any] = {
            "schema": VISUALIZATION_INTEGRATION_SCHEMA_NAME,
            "schema_version": VISUALIZATION_INTEGRATION_SCHEMA_VERSION,
            "status": self.status.value,
            "target": self.target.to_dict(),
            "config": self.config.to_dict(),
            "outcome_count": len(self.outcomes),
            "state_count": len(self.states),
            "plan_count": len(self.plans),
            "execution_count": len(self.executions),
            "artifacts": [item.to_dict() for item in self.artifacts],
            "attached_model_count": len(self.attached_models),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "reused": self.reused,
            "duration_seconds": self.duration_seconds,
            "metadata": to_json_compatible(dict(self.metadata)),
        }
        if include_native:
            data["outcomes"] = to_json_compatible(self.outcomes)
            data["states"] = to_json_compatible(self.states)
            data["plans"] = to_json_compatible(self.plans)
            data["executions"] = to_json_compatible(self.executions)
        return data

    def to_json(self, *, indent: Optional[int] = 2) -> str:
        """Serialize the output as JSON."""

        return json.dumps(self.to_dict(), indent=indent, sort_keys=True, ensure_ascii=False)


# 25.5. Module loading and capability inspection
# -----------------------------------------------------------------------------


def _load_visualization_integration_module(
    visualization_module: Optional[ModuleType] = None,
) -> ModuleType:
    """Return the visualization module and validate its required interface."""

    module = visualization_module or load_analysis_module(
        VISUALIZATION_INTEGRATION_MODULE_NAME,
        required=True,
    )
    missing = [name for name in VISUALIZATION_REQUIRED_SYMBOLS if not hasattr(module, name)]
    if missing:
        raise AnalysisDependencyError(
            "The visualization module does not provide the required integration API.",
            stage=STAGE_VISUALIZATION,
            code="visualization_interface_incomplete",
            details={"missing": missing},
        )
    return module


def inspect_visualization_integration_capabilities(
    *,
    visualization_module: Optional[ModuleType] = None,
    load: bool = False,
) -> Dict[str, Any]:
    """Inspect visualization integration and optional runtime capabilities."""

    capability = inspect_module_capability(
        VISUALIZATION_INTEGRATION_MODULE_NAME,
        load=load,
        validate_interface=False,
    )
    result: Dict[str, Any] = {
        "module_available": bool(capability.available),
        "module_loaded": bool(capability.loaded),
        "interface_valid": False,
        "missing_required_symbols": list(VISUALIZATION_REQUIRED_SYMBOLS),
        "optional_symbols": {},
        "chimerax_available": CHIMERAX_AVAILABLE,
        "profiles": list(VISUALIZATION_SUPPORTED_PROFILES),
        "execution_modes": list(VISUALIZATION_SUPPORTED_EXECUTION_MODES),
    }
    if not capability.available:
        return result
    module = visualization_module
    if module is None and load:
        module = _load_visualization_integration_module()
    if module is None:
        return result
    missing = [name for name in VISUALIZATION_REQUIRED_SYMBOLS if not hasattr(module, name)]
    result["missing_required_symbols"] = missing
    result["interface_valid"] = not missing
    result["optional_symbols"] = {
        name: hasattr(module, name)
        for name in VISUALIZATION_OPTIONAL_SYMBOLS
    }
    capability_function = getattr(module, "get_visualization_capabilities", None)
    if callable(capability_function):
        try:
            result["native_capabilities"] = to_json_compatible(capability_function())
        except Exception as exc:
            result["native_capability_error"] = str(exc)
    return result


# 25.6. Target resolution
# -----------------------------------------------------------------------------


def _visualization_collect_dock_models(value: Any) -> Tuple[Any, ...]:
    """Collect DockModel-like objects from common integrated results."""

    if value is None:
        return ()
    if is_dock_model_like(value):
        return (value,)
    collected: List[Any] = []
    for field_name in ("dock_models", "models", "pose_results", "items"):
        nested = get_object_value(value, field_name, default=None)
        if nested is None or isinstance(nested, (str, bytes, Mapping)):
            continue
        try:
            sequence = tuple(nested)
        except TypeError:
            continue
        for item in sequence:
            candidate = get_object_value(item, "dock_model", default=item)
            if is_dock_model_like(candidate):
                collected.append(candidate)
    direct = get_object_value(value, "dock_model", default=None)
    if is_dock_model_like(direct):
        collected.insert(0, direct)
    return tuple(unique_preserving_order(collected, key=id))


def _visualization_source_kind(value: Any) -> VisualizationTargetKind:
    """Infer a visualization target kind."""

    if isinstance(value, BatchAnalysisResult) or isinstance(value, BatchAnalysisOutput):
        return VisualizationTargetKind.BATCH
    if isinstance(value, MultiPoseAnalysisResult) or isinstance(value, MultiposeAnalysisOutput):
        return VisualizationTargetKind.MULTIPOSE
    if isinstance(value, AnalysisRunResult):
        return VisualizationTargetKind.RUN
    if isinstance(value, PoseAnalysisResult):
        return VisualizationTargetKind.POSE
    if is_dock_model_like(value):
        return VisualizationTargetKind.DOCK_MODEL
    models = _visualization_collect_dock_models(value)
    if len(models) > 1:
        return VisualizationTargetKind.MULTIPOSE
    if len(models) == 1:
        return VisualizationTargetKind.DOCK_MODEL
    return VisualizationTargetKind.GENERIC


def _visualization_source_name(value: Any) -> str:
    """Return a stable visualization target name."""

    for field_name in ("name", "run_id", "request_id", "pose_id", "batch_id"):
        candidate = get_object_value(value, field_name, default=None)
        if candidate not in (None, ""):
            return normalize_text(candidate, maximum_length=512)
    return type(value).__name__


def resolve_visualization_stage_target(
    *,
    context: Optional[AnalysisContext] = None,
    source: Any = None,
    dock_model: Any = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
) -> VisualizationStageTarget:
    """Resolve the best source for one visualization-stage execution."""

    candidates = (
        source,
        pose_result,
        multipose_result,
        batch_result,
        run_result,
        dock_model,
    )
    selected = next((item for item in candidates if item is not None), None)
    if selected is None and context is not None:
        for key in (
            CONSENSUS_ANALYSIS_OUTPUT_KEY,
            MULTIPOSE_OUTPUT_KEY,
            SINGLE_POSE_RESULT_KEY,
        ):
            selected = context.get_shared(key)
            if selected is not None:
                break
    if selected is None and context is not None:
        if context.dock_models:
            selected = context.dock_models[0] if len(context.dock_models) == 1 else tuple(context.dock_models)
    if selected is None:
        raise AnalysisInputError(
            "Visualization requires an analysis result or DockModel source.",
            stage=STAGE_VISUALIZATION,
            code="visualization_source_missing",
        )
    models = _visualization_collect_dock_models(selected)
    if not models and context is not None:
        models = tuple(context.dock_models)
    kind = _visualization_source_kind(selected)
    if isinstance(selected, (tuple, list)) and len(selected) > 1:
        kind = VisualizationTargetKind.MULTIPOSE
        models = tuple(item for item in selected if is_dock_model_like(item)) or models
    return VisualizationStageTarget(
        source=selected,
        kind=kind,
        dock_models=models,
        name=_visualization_source_name(selected),
        metadata={"resolved_from_context": source is None and dock_model is None},
    )


# 25.7. Native configuration and request construction
# -----------------------------------------------------------------------------


def build_native_visualization_config(
    config: VisualizationIntegrationConfigLike = None,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Any:
    """Build the native VisualizationConfig object."""

    active = resolve_visualization_integration_config(config)
    module = _load_visualization_integration_module(visualization_module)
    resolver = getattr(module, "resolve_visualization_config")
    native_value: Any = dict(active.native_config)
    if not native_value:
        native_value = None
    return resolver(native_value, profile=active.profile)


def build_native_visualization_layers(
    config: VisualizationIntegrationConfigLike = None,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Any:
    """Build the native VisualizationLayers object."""

    active = resolve_visualization_integration_config(config)
    module = _load_visualization_integration_module(visualization_module)
    coercer = getattr(module, "coerce_visualization_layers", None)
    if callable(coercer):
        return coercer(dict(active.layers), profile=active.profile)
    layer_class = getattr(module, "VisualizationLayers")
    return layer_class(**dict(active.layers))


def _visualization_output_path(
    active: VisualizationIntegrationConfig,
    *,
    suffix: str,
) -> Optional[Path]:
    """Resolve one optional output path."""

    if active.output_directory is None:
        return None
    active.output_directory.mkdir(parents=True, exist_ok=True)
    return active.output_directory / f"{active.basename}{suffix}"


def build_native_visualization_snapshots(
    config: VisualizationIntegrationConfigLike = None,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Any:
    """Build a native snapshot collection or None."""

    active = resolve_visualization_integration_config(config)
    if not active.create_snapshot:
        return None
    module = _load_visualization_integration_module(visualization_module)
    coercer = getattr(module, "coerce_snapshot_collection", None)
    if not callable(coercer):
        raise AnalysisDependencyError(
            "The visualization module does not support snapshot collections.",
            stage=STAGE_VISUALIZATION,
            code="snapshot_api_unavailable",
        )
    values = dict(active.snapshot_options)
    values.setdefault("format", active.image_format)
    if "filename" not in values:
        path = _visualization_output_path(active, suffix=f".{active.image_format}")
        if path is not None:
            values["filename"] = path
    directory = active.output_directory
    return coercer(values, directory=directory, name=f"{active.basename}_snapshots")


def build_native_visualization_command_export(
    config: VisualizationIntegrationConfigLike = None,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Any:
    """Build a native command-export specification or None."""

    active = resolve_visualization_integration_config(config)
    if not active.export_commands:
        return None
    module = _load_visualization_integration_module(visualization_module)
    coercer = getattr(module, "coerce_command_export_spec", None)
    if not callable(coercer):
        raise AnalysisDependencyError(
            "The visualization module does not support command export.",
            stage=STAGE_VISUALIZATION,
            code="command_export_api_unavailable",
        )
    values = dict(active.command_options)
    values.setdefault("format", active.command_format)
    filename = active.command_filename
    if filename is None:
        filename = _visualization_output_path(active, suffix=f".{active.command_format}")
    if filename is not None:
        values.setdefault("filename", filename)
    return coercer(values)


def build_native_visualization_request(
    target: VisualizationStageTarget,
    config: VisualizationIntegrationConfigLike = None,
    *,
    session: Any = None,
    visualization_module: Optional[ModuleType] = None,
) -> Any:
    """Build one normalized native VisualizationRequest."""

    active = resolve_visualization_integration_config(config)
    module = _load_visualization_integration_module(visualization_module)
    source = target.source
    if target.kind is VisualizationTargetKind.MULTIPOSE and target.dock_models:
        source = target.dock_models
    native_config = build_native_visualization_config(active, visualization_module=module)
    layers = build_native_visualization_layers(active, visualization_module=module)
    snapshots = build_native_visualization_snapshots(active, visualization_module=module)
    command_export = build_native_visualization_command_export(active, visualization_module=module)
    options = dict(active.native_request_options)
    options.update(
        {
            "config_value": native_config,
            "profile": active.profile,
            "layers": layers,
            "execution_mode": active.resolved_execution_mode(session=session),
            "integration_mode": active.integration_mode,
            "snapshots": snapshots,
            "command_export": command_export,
            "attach": active.attach_result,
            "validate": active.validate,
            "strict": active.strict_validation,
            "name": active.name,
            "metadata": {
                "schema": VISUALIZATION_INTEGRATION_SCHEMA_NAME,
                "schema_version": VISUALIZATION_INTEGRATION_SCHEMA_VERSION,
                "target_kind": target.kind.value,
                "target_name": target.name,
                **dict(active.metadata),
            },
        }
    )
    return module.build_visualization_request(source, **options)


# 25.8. Native result adaptation, reuse and attachment
# -----------------------------------------------------------------------------


def _visualization_path_artifact(kind: str, value: Any, *, format: Optional[str] = None) -> Optional[VisualizationArtifact]:
    """Adapt a path-like native artifact."""

    if value is None:
        return None
    path_value = get_object_value(value, "path", default=value)
    if path_value is None or isinstance(path_value, (Mapping, list, tuple, set)):
        return None
    try:
        path = Path(path_value)
    except (TypeError, ValueError, OSError):
        return None
    exists = path.is_file()
    size = path.stat().st_size if exists else None
    native_format = get_object_value(value, "format", default=format)
    native_format = getattr(native_format, "value", native_format)
    return VisualizationArtifact(
        kind=kind,
        path=path,
        format=str(native_format) if native_format is not None else path.suffix.lstrip(".") or None,
        exists=exists,
        size_bytes=size,
    )


def collect_visualization_artifacts(
    value: Any,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Tuple[VisualizationArtifact, ...]:
    """Collect command, snapshot and state artifact paths."""

    module = _load_visualization_integration_module(visualization_module)
    artifacts: List[VisualizationArtifact] = []
    commands = get_object_value(value, "commands", default=None)
    command_artifact = _visualization_path_artifact("commands", commands)
    if command_artifact is not None:
        artifacts.append(command_artifact)
    snapshots = get_object_value(value, "snapshots", default=None)
    results = get_object_value(snapshots, "results", default=()) if snapshots is not None else ()
    try:
        snapshot_results = tuple(results or ())
    except TypeError:
        snapshot_results = ()
    for index, result in enumerate(snapshot_results, start=1):
        artifact = _visualization_path_artifact(f"snapshot_{index}", result)
        if artifact is not None:
            artifacts.append(artifact)
    getter = getattr(module, "get_visualization_artifacts", None)
    if callable(getter):
        try:
            native_paths = getter(value)
        except Exception:
            native_paths = {}
        if isinstance(native_paths, Mapping):
            for key, path_value in native_paths.items():
                artifact = _visualization_path_artifact(str(key), path_value)
                if artifact is not None:
                    artifacts.append(artifact)
    unique: List[VisualizationArtifact] = []
    seen: Set[Tuple[str, Optional[str]]] = set()
    for item in artifacts:
        key = (item.kind, str(item.path) if item.path else None)
        if key not in seen:
            seen.add(key)
            unique.append(item)
    return tuple(unique[:MAX_VISUALIZATION_ARTIFACTS])


def _visualization_outcome_state(value: Any) -> Any:
    """Extract a native state from an outcome or state-like value."""

    return get_object_value(value, "state", default=value)


def _visualization_outcome_plan(value: Any) -> Any:
    """Extract a native plan from an outcome or state-like value."""

    state = _visualization_outcome_state(value)
    return get_object_value(state, "plan", default=None)


def _visualization_outcome_execution(value: Any) -> Any:
    """Extract a native execution result."""

    execution = get_object_value(value, "execution", default=None)
    if execution is None:
        execution = get_object_value(_visualization_outcome_state(value), "execution", default=None)
    return execution


def adapt_native_visualization_result(
    value: Any,
    *,
    target: VisualizationStageTarget,
    config: VisualizationIntegrationConfigLike = None,
    duration_seconds: float = 0.0,
    reused: bool = False,
    visualization_module: Optional[ModuleType] = None,
) -> VisualizationStageOutput:
    """Adapt one or several native visualization values."""

    active = resolve_visualization_integration_config(config)
    module = _load_visualization_integration_module(visualization_module)
    if isinstance(value, VisualizationStageOutput):
        return value
    if isinstance(value, tuple):
        outcomes = value
    elif isinstance(value, list):
        outcomes = tuple(value)
    else:
        outcomes = (value,)
    states = tuple(_visualization_outcome_state(item) for item in outcomes if item is not None)
    plans = tuple(plan for plan in (_visualization_outcome_plan(item) for item in outcomes) if plan is not None)
    executions = tuple(item for item in (_visualization_outcome_execution(item) for item in outcomes) if item is not None)
    artifacts: List[VisualizationArtifact] = []
    warnings_list: List[str] = []
    errors: List[str] = []
    attached_models: List[Any] = []
    for outcome in outcomes:
        artifacts.extend(collect_visualization_artifacts(outcome, visualization_module=module))
        warnings_value = get_object_value(outcome, "warnings", default=())
        try:
            warnings_list.extend(str(item) for item in warnings_value or ())
        except TypeError:
            if warnings_value:
                warnings_list.append(str(warnings_value))
        issues = get_object_value(outcome, "issues", default=())
        try:
            issue_values = tuple(issues or ())
        except TypeError:
            issue_values = ()
        for issue in issue_values:
            level = _visualization_token(get_object_value(issue, "level", default=""))
            message = normalize_text(get_object_value(issue, "message", default=str(issue)))
            if level in {"error", "critical", "fatal"}:
                errors.append(message)
            elif message:
                warnings_list.append(message)
        model = get_object_value(outcome, "model", default=None)
        if model is not None:
            attached_models.append(model)
    if reused:
        status = VisualizationIntegrationStatus.REUSED
    elif errors and states:
        status = VisualizationIntegrationStatus.PARTIAL
    elif errors:
        status = VisualizationIntegrationStatus.FAILED
    elif states or plans:
        status = VisualizationIntegrationStatus.SUCCEEDED
    else:
        status = VisualizationIntegrationStatus.SKIPPED
    return VisualizationStageOutput(
        target=target,
        config=active,
        status=status,
        outcomes=tuple(outcomes),
        states=states,
        plans=plans,
        executions=executions,
        artifacts=tuple(unique_preserving_order(artifacts, key=lambda item: (item.kind, str(item.path)))),
        attached_models=tuple(unique_preserving_order(attached_models, key=id)),
        warnings=tuple(unique_preserving_order(warnings_list)),
        errors=tuple(unique_preserving_order(errors)),
        reused=reused,
        duration_seconds=duration_seconds,
        metadata={
            "profile": active.profile,
            "execution_mode": active.execution_mode,
            "resolved_execution_modes": [
                _visualization_token(get_object_value(item, "execution_mode", default=""))
                for item in executions
            ],
        },
    )


def find_reusable_visualization_output(
    target: VisualizationStageTarget,
    config: VisualizationIntegrationConfigLike = None,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Optional[VisualizationStageOutput]:
    """Return a compatible attached visualization, when available."""

    active = resolve_visualization_integration_config(config)
    if not active.reuse_result:
        return None
    module = _load_visualization_integration_module(visualization_module)
    getter = getattr(module, "get_visualization_state", None)
    states: List[Any] = []
    if callable(getter):
        for model in target.dock_models:
            try:
                state = getter(model, required=False)
            except Exception:
                state = None
            if state is not None:
                states.append(state)
    if not states:
        for model in target.dock_models:
            for field_name in VISUALIZATION_REUSE_FIELDS:
                value = get_object_value(model, field_name, default=None)
                if value is not None:
                    states.append(value)
                    break
    if not states:
        return None
    return adapt_native_visualization_result(
        tuple(states),
        target=target,
        config=active,
        reused=True,
        visualization_module=module,
    )


def attach_visualization_output_to_dock_models(
    output: VisualizationStageOutput,
    *,
    visualization_module: Optional[ModuleType] = None,
) -> Tuple[Any, ...]:
    """Attach output state and artifact paths to resolved DockModels."""

    if not output.config.attach_result or not output.target.dock_models:
        return output.target.dock_models
    module = _load_visualization_integration_module(visualization_module)
    attach = getattr(module, "attach_visualization", None)
    updated: List[Any] = []
    for index, model in enumerate(output.target.dock_models):
        state = output.states[min(index, len(output.states) - 1)] if output.states else None
        current = model
        if state is not None and callable(attach):
            try:
                attachment = attach(
                    model,
                    state,
                    mode=output.config.integration_mode,
                    strict=output.config.strict_validation,
                )
                current = get_object_value(attachment, "model", default=model)
            except Exception:
                if output.config.strict_validation:
                    raise
        files = get_object_value(current, "files", default=None)
        if isinstance(files, MutableMapping):
            files.update(output.artifact_paths)
        metadata = get_object_value(current, "metadata", default=None)
        if isinstance(metadata, MutableMapping):
            metadata.setdefault(VISUALIZATION_METADATA_KEY, {})
            if isinstance(metadata[VISUALIZATION_METADATA_KEY], MutableMapping):
                metadata[VISUALIZATION_METADATA_KEY].update(
                    {
                        "schema": VISUALIZATION_INTEGRATION_SCHEMA_NAME,
                        "schema_version": VISUALIZATION_INTEGRATION_SCHEMA_VERSION,
                        "profile": output.config.profile,
                        "status": output.status.value,
                        "reused": output.reused,
                    }
                )
        updated.append(current)
    return tuple(updated)


# 25.9. Validation and native execution
# -----------------------------------------------------------------------------


def validate_visualization_target_preflight(
    target: VisualizationStageTarget,
    config: VisualizationIntegrationConfigLike = None,
) -> Tuple[str, ...]:
    """Return preflight validation failures."""

    active = resolve_visualization_integration_config(config)
    failures: List[str] = []
    if target.source is None:
        failures.append("Visualization target source is missing.")
    if active.create_snapshot and active.resolved_execution_mode() not in {"immediate", "batch"}:
        if not CHIMERAX_AVAILABLE:
            failures.append("Snapshot creation requires a ChimeraX execution session.")
    if active.export_commands and active.output_directory is None and active.command_filename is None:
        failures.append("Command export requires an output directory or command filename.")
    return tuple(failures)


def _run_native_visualization_target(
    target: VisualizationStageTarget,
    active: VisualizationIntegrationConfig,
    *,
    session: Any = None,
    backend: Any = None,
    visualization_module: Optional[ModuleType] = None,
) -> Any:
    """Execute the appropriate native visualization entry point."""

    module = _load_visualization_integration_module(visualization_module)
    request = build_native_visualization_request(
        target,
        active,
        session=session,
        visualization_module=module,
    )
    mode = active.resolved_execution_mode(session=session)
    if target.kind is VisualizationTargetKind.MULTIPOSE and target.dock_models:
        if mode in {"deferred", "dry_run", "export_only"}:
            return module.run_visualization(
                request,
                session=session,
                backend=backend,
            )
        return module.run_visualization(
            request,
            session=session,
            backend=backend,
        )
    return module.run_visualization(
        request,
        session=session,
        backend=backend,
    )


def run_visualization_analysis(
    source: Any,
    *,
    dock_models: Sequence[Any] = (),
    config: VisualizationIntegrationConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    session: Any = None,
    backend: Any = None,
    visualization_module: Optional[ModuleType] = None,
) -> VisualizationStageOutput:
    """Plan or execute visualization for a generic source."""

    active = resolve_visualization_integration_config(config, overrides=overrides)
    module = _load_visualization_integration_module(visualization_module)
    target = VisualizationStageTarget(
        source=source,
        kind=_visualization_source_kind(source),
        dock_models=tuple(dock_models) or _visualization_collect_dock_models(source),
        name=_visualization_source_name(source),
    )
    failures = validate_visualization_target_preflight(target, active)
    if failures and active.strict_validation:
        raise AnalysisValidationError(
            "Visualization preflight validation failed.",
            stage=STAGE_VISUALIZATION,
            code="visualization_preflight_failed",
            details={"failures": list(failures)},
        )
    reusable = find_reusable_visualization_output(target, active, visualization_module=module)
    if reusable is not None:
        return reusable
    started = time.perf_counter()
    try:
        native = _run_native_visualization_target(
            target,
            active,
            session=session,
            backend=backend,
            visualization_module=module,
        )
        output = adapt_native_visualization_result(
            native,
            target=target,
            config=active,
            duration_seconds=time.perf_counter() - started,
            visualization_module=module,
        )
        attached = attach_visualization_output_to_dock_models(output, visualization_module=module)
        if attached != output.attached_models:
            output = replace(output, attached_models=attached)
        return output
    except Exception as exc:
        if active.strict_validation or not active.continue_on_error:
            raise
        return VisualizationStageOutput(
            target=target,
            config=active,
            status=VisualizationIntegrationStatus.FAILED,
            warnings=tuple(failures),
            errors=(str(exc),),
            duration_seconds=time.perf_counter() - started,
            metadata={"exception_type": type(exc).__name__},
        )


def run_pose_visualization_analysis(
    value: Any,
    *,
    config: VisualizationIntegrationConfigLike = None,
    **kwargs: Any,
) -> VisualizationStageOutput:
    """Visualize one pose or DockModel."""

    models = _visualization_collect_dock_models(value)
    return run_visualization_analysis(value, dock_models=models, config=config, **kwargs)


def run_multipose_visualization_analysis(
    value: Any,
    *,
    config: VisualizationIntegrationConfigLike = None,
    **kwargs: Any,
) -> VisualizationStageOutput:
    """Visualize a multipose result or DockModel collection."""

    models = _visualization_collect_dock_models(value)
    if not models and isinstance(value, Sequence) and not isinstance(value, (str, bytes, Mapping)):
        models = tuple(item for item in value if is_dock_model_like(item))
    return run_visualization_analysis(value, dock_models=models, config=config, **kwargs)


def run_batch_visualization_analysis(
    value: Any,
    *,
    config: VisualizationIntegrationConfigLike = None,
    **kwargs: Any,
) -> VisualizationStageOutput:
    """Visualize all DockModels represented by a batch result."""

    return run_visualization_analysis(
        value,
        dock_models=_visualization_collect_dock_models(value),
        config=config,
        **kwargs,
    )


# 25.10. Stage conversion and registry executor
# -----------------------------------------------------------------------------


def visualization_stage_output_to_result(
    output: VisualizationStageOutput,
    *,
    required: bool = False,
) -> AnalysisStageResult:
    """Convert native integration output to AnalysisStageResult."""

    result = AnalysisStageResult(
        stage=STAGE_VISUALIZATION,
        required=required,
        result_type=VISUALIZATION_INTEGRATION_RESULT_TYPE,
    )
    result.start()
    result.value = output
    result.statistics.update(
        {
            "status": output.status.value,
            "outcome_count": len(output.outcomes),
            "state_count": len(output.states),
            "plan_count": len(output.plans),
            "execution_count": len(output.executions),
            "artifact_count": len(output.artifacts),
            "attached_model_count": len(output.attached_models),
            "warning_count": len(output.warnings),
            "error_count": len(output.errors),
            "reused": output.reused,
        }
    )
    result.files.update(output.artifact_paths)
    result.metadata.update(
        {
            "schema": VISUALIZATION_INTEGRATION_SCHEMA_NAME,
            "schema_version": VISUALIZATION_INTEGRATION_SCHEMA_VERSION,
            "profile": output.config.profile,
            "execution_mode": output.config.execution_mode,
            "target_kind": output.target.kind.value,
        }
    )
    result.output_summary.update(summarize_visualization_stage(output))
    for warning_text in output.warnings:
        result.messages.append(str(warning_text))
    if output.status in {VisualizationIntegrationStatus.SUCCEEDED, VisualizationIntegrationStatus.REUSED}:
        result.succeed(output, message="Visualization completed successfully.")
        result.cached = output.reused
    elif output.status is VisualizationIntegrationStatus.PARTIAL:
        result.finish(StageStatus.PARTIAL, value=output, message="Visualization completed with partial output.")
    elif output.status is VisualizationIntegrationStatus.SKIPPED:
        result.skip("Visualization produced no plan or state.")
    else:
        error = AnalysisVisualizationError(
            "Visualization failed.",
            stage=STAGE_VISUALIZATION,
            code="visualization_failed",
            details={"errors": list(output.errors)},
        )
        result.fail(error)
    return result


def execute_visualization_stage(
    context: AnalysisContext,
    *,
    dock_model: Any = None,
    source: Any = None,
    pose_result: Any = None,
    multipose_result: Any = None,
    batch_result: Any = None,
    run_result: Any = None,
    config: VisualizationIntegrationConfigLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    session: Any = None,
    backend: Any = None,
    visualization_module: Optional[ModuleType] = None,
    raise_on_error: bool = False,
    **_: Any,
) -> AnalysisStageResult:
    """Registry-compatible visualization-stage executor."""

    context.set_current_stage(STAGE_VISUALIZATION)
    result = AnalysisStageResult(
        stage=STAGE_VISUALIZATION,
        required=False,
        result_type=VISUALIZATION_INTEGRATION_RESULT_TYPE,
    )
    result.start()
    try:
        active = resolve_visualization_integration_config(
            config or context.config,
            overrides=overrides,
        )
        target = resolve_visualization_stage_target(
            context=context,
            source=source,
            dock_model=dock_model,
            pose_result=pose_result,
            multipose_result=multipose_result,
            batch_result=batch_result,
            run_result=run_result,
        )
        active_session = session if session is not None else context.session
        output = run_visualization_analysis(
            target.source,
            dock_models=target.dock_models,
            config=active,
            session=active_session,
            backend=backend,
            visualization_module=visualization_module,
        )
        result = visualization_stage_output_to_result(output)
        context.set_shared(VISUALIZATION_SHARED_OUTPUT_KEY, output)
        context.set_shared(VISUALIZATION_SHARED_RESULT_KEY, output.outcomes)
        context.set_shared(VISUALIZATION_SHARED_STATE_KEY, output.states)
        context.set_shared(VISUALIZATION_SHARED_PLAN_KEY, output.plans)
        context.set_shared(VISUALIZATION_SHARED_ARTIFACTS_KEY, output.artifacts)
        context.statistics[VISUALIZATION_STATISTICS_KEY] = dict(result.statistics)
        context.files.update(result.files)
    except Exception as exc:
        wrapped = exc if isinstance(exc, AnalysisError) else AnalysisVisualizationError(
            "Visualization-stage execution failed.",
            stage=STAGE_VISUALIZATION,
            code="visualization_stage_execution_failed",
            cause=exc,
        )
        result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
        if raise_on_error or context.config.runtime.is_strict:
            context.set_stage_data(STAGE_VISUALIZATION, result)
            context.set_current_stage(None)
            raise wrapped
    finally:
        context.set_stage_data(STAGE_VISUALIZATION, result)
        context.set_current_stage(None)
    return result


# 25.11. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_visualization_stage_output(value: Any) -> Tuple[str, ...]:
    """Return validation messages for a visualization-stage output."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, VisualizationStageOutput):
        return ("Value is not a VisualizationStageOutput.",)
    failures: List[str] = []
    if value.target.source is None:
        failures.append("Visualization target source is missing.")
    if value.status in {
        VisualizationIntegrationStatus.SUCCEEDED,
        VisualizationIntegrationStatus.REUSED,
    } and not value.states and not value.plans:
        failures.append("Successful visualization contains no state or plan.")
    if len(value.artifacts) > MAX_VISUALIZATION_ARTIFACTS:
        failures.append("Visualization artifact count exceeds the safety limit.")
    for artifact in value.artifacts:
        if artifact.path is not None and artifact.exists and not artifact.path.is_file():
            failures.append(f"Visualization artifact path is not a file: {artifact.path}.")
    if value.status is VisualizationIntegrationStatus.FAILED and not value.errors:
        failures.append("Failed visualization contains no error message.")
    return tuple(unique_preserving_order(failures))


def summarize_visualization_stage(value: Any) -> Dict[str, Any]:
    """Return a compact visualization-stage summary."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, VisualizationStageOutput):
        return {"valid": False, "type": type(value).__name__}
    return {
        "valid": not bool(validate_visualization_stage_output(value)),
        "status": value.status.value,
        "target_kind": value.target.kind.value,
        "target_name": value.target.name,
        "profile": value.config.profile,
        "execution_mode": value.config.execution_mode,
        "outcome_count": len(value.outcomes),
        "state_count": len(value.states),
        "plan_count": len(value.plans),
        "execution_count": len(value.executions),
        "artifact_count": len(value.artifacts),
        "artifact_paths": value.artifact_paths,
        "attached_model_count": len(value.attached_models),
        "reused": value.reused,
        "warning_count": len(value.warnings),
        "error_count": len(value.errors),
        "duration_seconds": value.duration_seconds,
    }


def visualization_stage_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize visualization-stage output as JSON."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if isinstance(value, VisualizationStageOutput):
        return value.to_json(indent=indent)
    return json.dumps(to_json_compatible(value), indent=indent, sort_keys=True, ensure_ascii=False)


def visualization_stage_result_adapter(value: Any, **kwargs: Any) -> AnalysisStageResult:
    """Registry-compatible adapter for visualization values."""

    if isinstance(value, AnalysisStageResult):
        return value
    if isinstance(value, VisualizationStageOutput):
        return visualization_stage_output_to_result(value, required=bool(kwargs.get("required", False)))
    target = kwargs.get("target")
    if not isinstance(target, VisualizationStageTarget):
        target = VisualizationStageTarget(
            source=value,
            kind=_visualization_source_kind(value),
            dock_models=_visualization_collect_dock_models(value),
            name=_visualization_source_name(value),
        )
    active = resolve_visualization_integration_config(kwargs.get("config"))
    output = adapt_native_visualization_result(
        value,
        target=target,
        config=active,
        visualization_module=kwargs.get("visualization_module"),
    )
    return visualization_stage_output_to_result(output, required=bool(kwargs.get("required", False)))


def visualization_stage_validator(value: Any, **_: Any) -> Tuple[str, ...]:
    """Registry-compatible visualization-stage validator."""

    return validate_visualization_stage_output(value)


# 25.12. Stage registration
# -----------------------------------------------------------------------------


def register_visualization_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register visualization execution, adaptation and validation."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.require(STAGE_VISUALIZATION)
    metadata = dict(definition.metadata)
    metadata.update(
        {
            "schema": VISUALIZATION_INTEGRATION_SCHEMA_NAME,
            "schema_version": VISUALIZATION_INTEGRATION_SCHEMA_VERSION,
            "result_type": VISUALIZATION_INTEGRATION_RESULT_TYPE,
            "profiles": VISUALIZATION_SUPPORTED_PROFILES,
            "execution_modes": VISUALIZATION_SUPPORTED_EXECUTION_MODES,
            "supports_pose": True,
            "supports_multipose": True,
            "supports_batch": True,
            "supports_dry_run": True,
            "supports_command_export": True,
            "supports_snapshots": True,
            "supports_chimerax": True,
            "preserves_native_result": True,
        }
    )
    updated = replace(
        definition,
        executor=execute_visualization_stage,
        result_adapter=visualization_stage_result_adapter,
        validator=visualization_stage_validator,
        metadata=metadata,
    )
    target_registry.replace(updated)
    return updated


def visualization_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the visualization adapter is registered."""

    target_registry = registry or get_default_stage_registry()
    definition = target_registry.get(STAGE_VISUALIZATION)
    return bool(
        definition is not None
        and definition.executor is execute_visualization_stage
        and definition.result_adapter is visualization_stage_result_adapter
        and definition.validator is visualization_stage_validator
    )


# 25.13. Convention validation
# -----------------------------------------------------------------------------


def validate_visualization_integration_conventions() -> Dict[str, Any]:
    """Validate Section 25 conventions and the real visualization interface."""

    failures: List[str] = []
    if canonicalize_visualization_profile("paper") != "publication":
        failures.append("Visualization profile aliases are inconsistent.")
    if canonicalize_visualization_execution_mode("preview") != "dry_run":
        failures.append("Visualization execution aliases are inconsistent.")
    if canonicalize_visualization_integration_mode("update") != "merge":
        failures.append("Visualization integration aliases are inconsistent.")
    config_value = VisualizationIntegrationConfig(
        profile="analysis",
        execution_mode="dry_run",
        attach_result=False,
        reuse_result=False,
        layers={"hotspots": True, "scoring": True},
    )
    if config_value.resolved_execution_mode() != "dry_run":
        failures.append("Explicit dry-run mode was not preserved.")
    if len(config_value.fingerprint()) != 64:
        failures.append("Visualization configuration fingerprint is invalid.")
    module = _load_visualization_integration_module()
    capabilities = inspect_visualization_integration_capabilities(
        visualization_module=module,
        load=True,
    )
    if not capabilities.get("interface_valid"):
        failures.append("The real visualization integration interface is invalid.")
    receptor_model = module.ModelSpec(model_id="1", name="receptor", role="receptor")
    ligand_model = module.ModelSpec(model_id="2", name="ligand", role="ligand")
    receptor_spec = module.MolecularObjectSpec(
        object_id="receptor",
        name="Receptor",
        role="receptor",
        models=(receptor_model,),
    )
    ligand_spec = module.MolecularObjectSpec(
        object_id="ligand",
        name="Ligand",
        role="ligand",
        models=(ligand_model,),
    )
    pose_spec = module.PoseSpec(
        pose_id="pose_1",
        index=0,
        rank=1,
        ligand=ligand_spec,
    )
    structure_spec = module.StructureSpec(
        structure_id="complex",
        models=(receptor_model, ligand_model),
        poses=(pose_spec,),
    )
    synthetic = module.MolecularSpecificationBundle(
        receptor=receptor_spec,
        ligands=(ligand_spec,),
        poses=(pose_spec,),
        structure=structure_spec,
    )
    active_test = replace(
        config_value,
        layers=normalize_visualization_layers(
            {
                "interactions": False,
                "residues": False,
                "hotspots": False,
                "scoring": False,
                "multipose": False,
            }
        ),
    )
    target = VisualizationStageTarget(
        source=synthetic,
        kind=VisualizationTargetKind.GENERIC,
        dock_models=(),
        name="section25_model",
    )
    try:
        native_config = build_native_visualization_config(active_test, visualization_module=module)
        if native_config is None:
            failures.append("Native visualization configuration was not built.")
        request = build_native_visualization_request(
            target,
            active_test,
            visualization_module=module,
        )
        if request is None:
            failures.append("Native visualization request was not built.")
        output = run_visualization_analysis(
            synthetic,
            config=active_test,
            visualization_module=module,
        )
        if output.status not in {
            VisualizationIntegrationStatus.SUCCEEDED,
            VisualizationIntegrationStatus.PARTIAL,
        }:
            failures.append("Real dry-run visualization did not produce usable output.")
        if not output.states or not output.plans:
            failures.append("Real dry-run visualization produced no state or plan.")
        if validate_visualization_stage_output(output):
            failures.append("Real visualization output failed integrated validation.")
        stage_result = visualization_stage_output_to_result(output)
        if not stage_result.succeeded:
            failures.append("Visualization output could not be converted to a successful stage result.")
        json.loads(visualization_stage_to_json(output))
    except Exception as exc:
        failures.append(f"Real visualization integration failed: {type(exc).__name__}: {exc}")
    if not visualization_stage_adapter_registered():
        failures.append("Visualization stage adapter is not registered.")
    if failures:
        raise RuntimeError(
            "Visualization integration convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": VISUALIZATION_INTEGRATION_SCHEMA_NAME,
        "schema_version": VISUALIZATION_INTEGRATION_SCHEMA_VERSION,
        "supported_profiles": len(VISUALIZATION_SUPPORTED_PROFILES),
        "supported_execution_modes": len(VISUALIZATION_SUPPORTED_EXECUTION_MODES),
        "validated_cases": 31,
    }


