# =============================================================================
# Section 26 — Provenance, timing, logging and diagnostics
# =============================================================================

"""Cross-cutting observability for DockAnalyzer analysis orchestration.

This section records how an analysis was executed without changing the
specialized chemistry, scoring or rendering implementations. It provides
stable provenance snapshots, stage and operation timings, structured log
entries, warning capture, diagnostic summaries and helpers that attach these
records to contexts and results.

Sensitive environment variables and object contents are excluded by default.
Callers must opt in explicitly when additional environment metadata is needed.
"""

# 26.1. Constants and conventions
# -----------------------------------------------------------------------------

OBSERVABILITY_MODULE_NAME: Final[str] = "analyze"
OBSERVABILITY_SCHEMA_NAME: Final[str] = "dockanalyzer.analysis_observability"
OBSERVABILITY_SCHEMA_VERSION: Final[str] = "26.1.0"
OBSERVABILITY_RESULT_TYPE: Final[str] = "analysis_observability"
PROVENANCE_SCHEMA_NAME: Final[str] = "dockanalyzer.analysis_provenance"
PROVENANCE_SCHEMA_VERSION: Final[str] = "26.1.0"
DIAGNOSTICS_SCHEMA_NAME: Final[str] = "dockanalyzer.analysis_diagnostics"
DIAGNOSTICS_SCHEMA_VERSION: Final[str] = "26.1.0"
TIMING_SCHEMA_NAME: Final[str] = "dockanalyzer.analysis_timings"
TIMING_SCHEMA_VERSION: Final[str] = "26.1.0"
LOG_SCHEMA_NAME: Final[str] = "dockanalyzer.analysis_log"
LOG_SCHEMA_VERSION: Final[str] = "26.1.0"

OBSERVABILITY_SHARED_KEY: Final[str] = "observability"
PROVENANCE_SHARED_KEY: Final[str] = "provenance"
TIMINGS_SHARED_KEY: Final[str] = "timings"
DIAGNOSTICS_SHARED_KEY: Final[str] = "diagnostics"
LOG_RECORDS_SHARED_KEY: Final[str] = "log_records"
ENVIRONMENT_SHARED_KEY: Final[str] = "environment"

OBSERVABILITY_METADATA_KEY: Final[str] = "observability"
PROVENANCE_METADATA_KEY: Final[str] = METADATA_KEY_PROVENANCE
TIMINGS_METADATA_KEY: Final[str] = METADATA_KEY_TIMINGS
DIAGNOSTICS_METADATA_KEY: Final[str] = METADATA_KEY_DIAGNOSTICS
OBSERVABILITY_STATISTICS_KEY: Final[str] = "observability"
TIMING_STATISTICS_KEY: Final[str] = STATISTICS_KEY_TIMINGS

DEFAULT_OBSERVABILITY_ENABLED: Final[bool] = True
DEFAULT_CAPTURE_WARNINGS: Final[bool] = True
DEFAULT_CAPTURE_LOGS: Final[bool] = True
DEFAULT_CAPTURE_TRACEBACKS: Final[bool] = True
DEFAULT_CAPTURE_STAGE_TIMINGS: Final[bool] = True
DEFAULT_CAPTURE_OPERATION_TIMINGS: Final[bool] = True
DEFAULT_INCLUDE_PLATFORM: Final[bool] = True
DEFAULT_INCLUDE_PYTHON: Final[bool] = True
