# 26.2. Normalization and redaction helpers
# -----------------------------------------------------------------------------


def canonicalize_observability_log_level(value: Any) -> str:
    """Return a canonical logging level name."""

    if isinstance(value, IntEnum):
        value = int(value)
    if isinstance(value, int) and not isinstance(value, bool):
        value = str(value)
    token = str(value or DEFAULT_LOG_LEVEL).strip().lower()
    try:
        return OBSERVABILITY_LOG_LEVEL_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown observability log level: {value!r}.") from exc


def observability_log_level_value(value: Any) -> int:
    """Return the numeric value associated with a logging level."""

    return {
        "DEBUG": 10,
        "INFO": 20,
        "WARNING": 30,
        "ERROR": 40,
        "CRITICAL": 50,
    }[canonicalize_observability_log_level(value)]


def _normalize_observability_limit(
    value: Any,
    *,
    field_name: str,
    default: int,
    maximum: int = 1_000_000,
) -> int:
    """Normalize a positive observability collection limit."""

    if value is None:
        return default
    try:
        normalized = int(value)
    except (TypeError, ValueError) as exc:
        raise AnalysisConfigurationError(
            f"{field_name} must be an integer."
        ) from exc
    if normalized < 1:
        raise AnalysisConfigurationError(f"{field_name} must be at least 1.")
    return min(normalized, maximum)


def _normalize_observability_threshold(
    value: Any,
    *,
    field_name: str,
    default: float,
) -> float:
    """Normalize a non-negative duration threshold."""

    if value is None:
        return default
    try:
        normalized = float(value)
    except (TypeError, ValueError) as exc:
        raise AnalysisConfigurationError(
            f"{field_name} must be numeric."
        ) from exc
    if not math.isfinite(normalized) or normalized < 0.0:
        raise AnalysisConfigurationError(
            f"{field_name} must be finite and non-negative."
        )
    return normalized


def _normalize_environment_names(value: Any) -> Tuple[str, ...]:
    """Normalize environment variable names while preserving order."""

    if value is None:
        return ()
    if isinstance(value, str):
        values = re.split(r"[,;\s]+", value)
    else:
        values = _result_sequence(value)
    normalized: List[str] = []
    known: Set[str] = set()
    for item in values:
        text = str(item).strip()
        if text and text not in known:
            normalized.append(text)
            known.add(text)
    return tuple(normalized)


def _observability_sensitive_key(value: Any) -> bool:
    """Return whether a key appears to reference sensitive information."""

    token = _normalize_convention_token(value, field_name="sensitive key")
    return any(
        sensitive == token or sensitive in token
        for sensitive in OBSERVABILITY_SENSITIVE_KEY_TOKENS
    )


def redact_observability_value(
    value: Any,
    *,
    key: Optional[Any] = None,
    enabled: bool = DEFAULT_REDACT_SENSITIVE_VALUES,
    replacement: str = "<redacted>",
    max_depth: int = MAX_METADATA_DEPTH,
    _depth: int = 0,
) -> Any:
    """Return a serialization-safe value with sensitive fields redacted."""

    if enabled and key is not None and _observability_sensitive_key(key):
        return replacement
    if _depth >= max_depth:
        return "<maximum depth reached>"
    if isinstance(value, Mapping):
        return {
            str(item_key): redact_observability_value(
                item_value,
                key=item_key,
                enabled=enabled,
                replacement=replacement,
                max_depth=max_depth,
                _depth=_depth + 1,
            )
            for item_key, item_value in value.items()
        }
    if isinstance(value, (list, tuple, set, frozenset, deque)):
        return [
            redact_observability_value(
                item,
                enabled=enabled,
                replacement=replacement,
                max_depth=max_depth,
                _depth=_depth + 1,
            )
            for item in value
        ]
    return _result_value_to_data(value)


def redact_observability_mapping(
    value: Optional[Mapping[str, Any]],
    *,
    enabled: bool = DEFAULT_REDACT_SENSITIVE_VALUES,
) -> Dict[str, Any]:
    """Return a redacted copy of an observability mapping."""

    if not value:
        return {}
    redacted = redact_observability_value(value, enabled=enabled)
    return dict(redacted) if isinstance(redacted, Mapping) else {}


# 26.3. Observability configuration
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisObservabilityConfig:
    """Configure provenance, timing, logging and diagnostic collection."""

    enabled: bool = DEFAULT_OBSERVABILITY_ENABLED
    capture_warnings: bool = DEFAULT_CAPTURE_WARNINGS
    capture_logs: bool = DEFAULT_CAPTURE_LOGS
    capture_tracebacks: bool = DEFAULT_CAPTURE_TRACEBACKS
    capture_stage_timings: bool = DEFAULT_CAPTURE_STAGE_TIMINGS
    capture_operation_timings: bool = DEFAULT_CAPTURE_OPERATION_TIMINGS
    include_platform: bool = DEFAULT_INCLUDE_PLATFORM
    include_python: bool = DEFAULT_INCLUDE_PYTHON
    include_process: bool = DEFAULT_INCLUDE_PROCESS
    include_chimerax: bool = DEFAULT_INCLUDE_CHIMERAX
    include_module_versions: bool = DEFAULT_INCLUDE_MODULE_VERSIONS
    include_input_fingerprints: bool = DEFAULT_INCLUDE_INPUT_FINGERPRINTS
    include_config_fingerprint: bool = DEFAULT_INCLUDE_CONFIG_FINGERPRINT
    include_environment: bool = DEFAULT_INCLUDE_ENVIRONMENT
    redact_sensitive_values: bool = DEFAULT_REDACT_SENSITIVE_VALUES
    environment_allowlist: Tuple[str, ...] = OBSERVABILITY_ENVIRONMENT_ALLOWLIST
    additional_environment_names: Tuple[str, ...] = ()
    log_level: str = DEFAULT_LOG_LEVEL
    max_log_records: int = DEFAULT_MAX_LOG_RECORDS
    max_timing_records: int = DEFAULT_MAX_TIMING_RECORDS
    max_warning_records: int = DEFAULT_MAX_WARNING_RECORDS
    max_environment_items: int = DEFAULT_MAX_ENVIRONMENT_ITEMS
    max_version_items: int = DEFAULT_MAX_VERSION_ITEMS
    timing_precision: int = DEFAULT_TIMING_PRECISION
    slow_stage_threshold_seconds: float = DEFAULT_SLOW_STAGE_THRESHOLD_SECONDS
    slow_operation_threshold_seconds: float = DEFAULT_SLOW_OPERATION_THRESHOLD_SECONDS
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        boolean_fields = (
            "enabled",
            "capture_warnings",
            "capture_logs",
            "capture_tracebacks",
            "capture_stage_timings",
            "capture_operation_timings",
            "include_platform",
            "include_python",
            "include_process",
            "include_chimerax",
            "include_module_versions",
            "include_input_fingerprints",
            "include_config_fingerprint",
            "include_environment",
            "redact_sensitive_values",
        )
        for name in boolean_fields:
            object.__setattr__(self, name, bool(getattr(self, name)))
        object.__setattr__(
            self,
            "environment_allowlist",
            _normalize_environment_names(self.environment_allowlist),
        )
        object.__setattr__(
            self,
            "additional_environment_names",
            _normalize_environment_names(self.additional_environment_names),
        )
        object.__setattr__(
            self,
            "log_level",
            canonicalize_observability_log_level(self.log_level),
        )
        object.__setattr__(
            self,
            "max_log_records",
            _normalize_observability_limit(
                self.max_log_records,
                field_name="max_log_records",
                default=DEFAULT_MAX_LOG_RECORDS,
            ),
        )
        object.__setattr__(
            self,
            "max_timing_records",
            _normalize_observability_limit(
                self.max_timing_records,
                field_name="max_timing_records",
                default=DEFAULT_MAX_TIMING_RECORDS,
            ),
        )
        object.__setattr__(
            self,
            "max_warning_records",
            _normalize_observability_limit(
                self.max_warning_records,
                field_name="max_warning_records",
                default=DEFAULT_MAX_WARNING_RECORDS,
            ),
        )
        object.__setattr__(
            self,
            "max_environment_items",
            _normalize_observability_limit(
                self.max_environment_items,
                field_name="max_environment_items",
                default=DEFAULT_MAX_ENVIRONMENT_ITEMS,
            ),
        )
        object.__setattr__(
            self,
            "max_version_items",
            _normalize_observability_limit(
                self.max_version_items,
                field_name="max_version_items",
                default=DEFAULT_MAX_VERSION_ITEMS,
            ),
        )
        precision = int(self.timing_precision)
        if precision < 0 or precision > 15:
            raise AnalysisConfigurationError(
                "timing_precision must be between 0 and 15."
            )
        object.__setattr__(self, "timing_precision", precision)
        object.__setattr__(
            self,
            "slow_stage_threshold_seconds",
            _normalize_observability_threshold(
                self.slow_stage_threshold_seconds,
                field_name="slow_stage_threshold_seconds",
                default=DEFAULT_SLOW_STAGE_THRESHOLD_SECONDS,
            ),
        )
        object.__setattr__(
            self,
            "slow_operation_threshold_seconds",
            _normalize_observability_threshold(
                self.slow_operation_threshold_seconds,
                field_name="slow_operation_threshold_seconds",
                default=DEFAULT_SLOW_OPERATION_THRESHOLD_SECONDS,
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(
                redact_observability_mapping(
                    self.metadata,
                    enabled=self.redact_sensitive_values,
                )
            ),
        )

    @classmethod
    def from_mapping(
        cls,
        value: Mapping[str, Any],
        *,
        strict: bool = True,
    ) -> "AnalysisObservabilityConfig":
        """Create observability configuration from a mapping."""

        aliases = {
            "warnings": "capture_warnings",
            "logs": "capture_logs",
            "tracebacks": "capture_tracebacks",
            "stage_timings": "capture_stage_timings",
            "operation_timings": "capture_operation_timings",
            "platform": "include_platform",
            "python": "include_python",
            "process": "include_process",
            "chimerax": "include_chimerax",
            "versions": "include_module_versions",
            "fingerprints": "include_input_fingerprints",
            "config_fingerprint": "include_config_fingerprint",
            "environment": "include_environment",
            "redact": "redact_sensitive_values",
            "env": "additional_environment_names",
            "level": "log_level",
        }
        allowed = {item.name for item in fields(cls)}
        normalized: Dict[str, Any] = {}
        for key, item in value.items():
            token = _normalize_convention_token(key, field_name="observability field")
            target = aliases.get(token, token)
            if target not in allowed:
                if strict:
                    raise AnalysisConfigurationError(
                        f"Unknown observability configuration field: {key!r}."
                    )
                continue
            normalized[target] = item
        return cls(**normalized)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready configuration mapping."""

        return {
            item.name: _result_value_to_data(getattr(self, item.name))
            for item in fields(self)
        }

    def fingerprint(self) -> str:
        """Return a stable SHA-256 fingerprint for the configuration."""

        payload = json.dumps(
            self.to_dict(),
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        return sha256(payload.encode("utf-8")).hexdigest()


AnalysisObservabilityConfigLike: TypeAlias = Union[
    AnalysisObservabilityConfig,
    Mapping[str, Any],
    None,
]


def resolve_analysis_observability_config(
    value: AnalysisObservabilityConfigLike = None,
    *,
    analysis_config: Optional[AnalysisConfigLike] = None,
    strict: bool = True,
) -> AnalysisObservabilityConfig:
    """Resolve observability configuration and runtime collection flags."""

    if isinstance(value, AnalysisObservabilityConfig):
        result = value
    elif isinstance(value, Mapping):
        result = AnalysisObservabilityConfig.from_mapping(value, strict=strict)
    elif value is None:
        result = AnalysisObservabilityConfig()
    else:
        raise TypeError(
            "Observability configuration must be a mapping, "
            "AnalysisObservabilityConfig or None."
        )
    if analysis_config is None:
        return result
    config_value = coerce_analysis_config(analysis_config)
    runtime = config_value.runtime
    updates = result.to_dict()
    updates["capture_stage_timings"] = bool(runtime.collect_timings)
    updates["capture_operation_timings"] = bool(runtime.collect_timings)
    updates["include_module_versions"] = bool(runtime.collect_provenance)
    updates["include_platform"] = bool(runtime.collect_provenance)
    updates["include_python"] = bool(runtime.collect_provenance)
    updates["capture_warnings"] = bool(runtime.collect_diagnostics)
    updates["capture_logs"] = bool(runtime.collect_diagnostics)
    runtime_environment = dict(runtime.environment)
    if runtime_environment:
        updates["metadata"] = {
            **dict(result.metadata),
            "runtime_environment": runtime_environment,
        }
    return AnalysisObservabilityConfig.from_mapping(updates)


# 26.4. Timing records
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisTimingRecord:
    """One wall-clock and monotonic timing observation."""

    name: str
    category: str = "operation"
    stage: Optional[str] = None
    pose_index: Optional[int] = None
    started_at: str = field(default_factory=_utc_timestamp)
    finished_at: Optional[str] = None
    duration_seconds: float = 0.0
    successful: bool = True
    cached: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        name = str(self.name).strip()
        if not name:
            raise ValueError("Timing record name cannot be empty.")
        object.__setattr__(self, "name", name[:MAX_IDENTIFIER_LENGTH])
        category = _normalize_convention_token(
            self.category,
            field_name="timing category",
        )
        object.__setattr__(self, "category", category)
        object.__setattr__(self, "stage", _normalize_optional_stage(self.stage))
        if self.pose_index is not None:
            pose_index = int(self.pose_index)
            if pose_index < 0:
                raise ValueError("Timing pose index cannot be negative.")
            object.__setattr__(self, "pose_index", pose_index)
        object.__setattr__(
            self,
            "started_at",
            _normalize_timestamp(self.started_at) or _utc_timestamp(),
        )
        object.__setattr__(
            self,
            "finished_at",
            _normalize_timestamp(self.finished_at, allow_none=True),
        )
        duration = _normalize_duration(self.duration_seconds) or 0.0
        object.__setattr__(self, "duration_seconds", duration)
        object.__setattr__(self, "successful", bool(self.successful))
        object.__setattr__(self, "cached", bool(self.cached))
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(redact_observability_mapping(self.metadata)),
        )

    def to_dict(self, *, precision: int = DEFAULT_TIMING_PRECISION) -> Dict[str, Any]:
        """Return a serialization-ready timing record."""

        return {
            "name": self.name,
            "category": self.category,
            "stage": self.stage,
            "pose_index": self.pose_index,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": round(self.duration_seconds, precision),
            "successful": self.successful,
            "cached": self.cached,
            "metadata": _result_value_to_data(self.metadata),
        }


@dataclass
class AnalysisTimingSummary:
    """Aggregate timing records for one analysis execution."""

    records: List[AnalysisTimingRecord] = field(default_factory=list)
    total_duration_seconds: Optional[float] = None
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def add(self, record: AnalysisTimingRecord) -> AnalysisTimingRecord:
        """Append one timing record."""

        if not isinstance(record, AnalysisTimingRecord):
            raise TypeError("Timing summary accepts AnalysisTimingRecord values.")
        self.records.append(record)
        return record

    @property
    def stage_records(self) -> Tuple[AnalysisTimingRecord, ...]:
        """Return records associated with pipeline stages."""

        return tuple(item for item in self.records if item.stage is not None)

    @property
    def operation_records(self) -> Tuple[AnalysisTimingRecord, ...]:
        """Return non-stage operation records."""

        return tuple(item for item in self.records if item.stage is None)

    def by_stage(self) -> Dict[str, float]:
        """Return cumulative duration by stage."""

        totals: Dict[str, float] = defaultdict(float)
        for record in self.stage_records:
            if record.stage:
                totals[record.stage] += record.duration_seconds
        return dict(sorted(totals.items(), key=lambda item: stage_sort_key(item[0])))

    def by_category(self) -> Dict[str, float]:
        """Return cumulative duration by timing category."""

        totals: Dict[str, float] = defaultdict(float)
        for record in self.records:
            totals[record.category] += record.duration_seconds
        return dict(sorted(totals.items()))

    def slowest(self, limit: int = 10) -> Tuple[AnalysisTimingRecord, ...]:
        """Return the slowest timing records."""

        count = max(0, int(limit))
        return tuple(
            sorted(
                self.records,
                key=lambda item: item.duration_seconds,
                reverse=True,
            )[:count]
        )

    def to_dict(self, *, precision: int = DEFAULT_TIMING_PRECISION) -> Dict[str, Any]:
        """Return a serialization-ready timing summary."""

        total = self.total_duration_seconds
        if total is None and self.records:
            total = sum(item.duration_seconds for item in self.records)
        return {
            "schema": TIMING_SCHEMA_NAME,
            "schema_version": TIMING_SCHEMA_VERSION,
            "record_count": len(self.records),
            "total_duration_seconds": (
                round(total, precision) if total is not None else None
            ),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "by_stage": {
                key: round(item, precision) for key, item in self.by_stage().items()
            },
            "by_category": {
                key: round(item, precision)
                for key, item in self.by_category().items()
            },
            "records": [item.to_dict(precision=precision) for item in self.records],
            "metadata": _result_value_to_data(self.metadata),
        }


