@dataclass(frozen=True)
class AnalysisLogRecord:
    """Serializable record emitted during analysis orchestration."""

    level: str
    message: str
    stage: Optional[str] = None
    source: Optional[str] = OBSERVABILITY_MODULE_NAME
    run_id: Optional[str] = None
    request_id: Optional[str] = None
    pose_index: Optional[int] = None
    created_at: str = field(default_factory=_utc_timestamp)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "level",
            canonicalize_observability_log_level(self.level),
        )
        message = str(self.message).strip()
        if not message:
            raise ValueError("Log record message cannot be empty.")
        object.__setattr__(self, "message", message)
        object.__setattr__(self, "stage", _normalize_optional_stage(self.stage))
        object.__setattr__(self, "source", _normalize_optional_text(self.source))
        object.__setattr__(
            self,
            "run_id",
            _normalize_optional_text(self.run_id),
        )
        object.__setattr__(
            self,
            "request_id",
            _normalize_optional_text(self.request_id),
        )
        if self.pose_index is not None:
            pose_index = int(self.pose_index)
            if pose_index < 0:
                raise ValueError("Log pose index cannot be negative.")
            object.__setattr__(self, "pose_index", pose_index)
        object.__setattr__(
            self,
            "created_at",
            _normalize_timestamp(self.created_at) or _utc_timestamp(),
        )
        object.__setattr__(
            self,
            "metadata",
            MappingProxyType(redact_observability_mapping(self.metadata)),
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready log record."""

        return {
            "level": self.level,
            "message": self.message,
            "stage": self.stage,
            "source": self.source,
            "run_id": self.run_id,
            "request_id": self.request_id,
            "pose_index": self.pose_index,
            "created_at": self.created_at,
            "metadata": _result_value_to_data(self.metadata),
        }


class AnalysisObservabilityLogger:
    """Collect structured records and forward them to :class:`DockLogger`."""

    def __init__(
        self,
        *,
        logger: Optional[DockLogger] = None,
        config: AnalysisObservabilityConfigLike = None,
        context: Optional[AnalysisContext] = None,
    ) -> None:
        self.config = resolve_analysis_observability_config(
            config,
            analysis_config=context.config if context is not None else None,
        )
        self.logger = logger or _LOGGER
        self.context = context
        self.records: List[AnalysisLogRecord] = []
        self._lock = threading.RLock()

    def _enabled_for(self, level: Any) -> bool:
        return (
            self.config.enabled
            and self.config.capture_logs
            and observability_log_level_value(level)
            >= observability_log_level_value(self.config.log_level)
        )

    def log(
        self,
        level: Any,
        message: Any,
        *,
        stage: Optional[Any] = None,
        pose_index: Optional[int] = None,
        metadata: Optional[Mapping[str, Any]] = None,
        forward: bool = True,
    ) -> Optional[AnalysisLogRecord]:
        """Record and optionally forward one log message."""

        canonical_level = canonicalize_observability_log_level(level)
        if not self._enabled_for(canonical_level):
            return None
        context = self.context
        resolved_stage = stage
        if resolved_stage is None and context is not None:
            resolved_stage = context.current_stage
        if pose_index is None and context is not None:
            pose_index = context.current_pose_index
        record = AnalysisLogRecord(
            level=canonical_level,
            message=str(message),
            stage=resolved_stage,
            run_id=context.run_id if context is not None else None,
            request_id=context.request_id if context is not None else None,
            pose_index=pose_index,
            metadata=metadata or {},
        )
        with self._lock:
            if len(self.records) < self.config.max_log_records:
                self.records.append(record)
        if forward:
            method = getattr(self.logger, canonical_level.lower(), None)
            if callable(method):
                method(record.message)
            else:
                self.logger.log(canonical_level, record.message)
        return record

    def debug(self, message: Any, **kwargs: Any) -> Optional[AnalysisLogRecord]:
        """Record a debug message."""

        return self.log("DEBUG", message, **kwargs)

    def info(self, message: Any, **kwargs: Any) -> Optional[AnalysisLogRecord]:
        """Record an informational message."""

        return self.log("INFO", message, **kwargs)

    def warning(self, message: Any, **kwargs: Any) -> Optional[AnalysisLogRecord]:
        """Record a warning message."""

        return self.log("WARNING", message, **kwargs)

    def error(self, message: Any, **kwargs: Any) -> Optional[AnalysisLogRecord]:
        """Record an error message."""

        return self.log("ERROR", message, **kwargs)

    def critical(self, message: Any, **kwargs: Any) -> Optional[AnalysisLogRecord]:
        """Record a critical message."""

        return self.log("CRITICAL", message, **kwargs)

    def to_dict(self) -> Dict[str, Any]:
        """Return all collected records."""

        return {
            "schema": LOG_SCHEMA_NAME,
            "schema_version": LOG_SCHEMA_VERSION,
            "record_count": len(self.records),
            "records": [record.to_dict() for record in self.records],
        }


# 26.6. Provenance snapshot
# -----------------------------------------------------------------------------


def _module_version(module: Any) -> Optional[str]:
    """Return a module version without requiring it to define one."""

    for attribute in ("__version__", "VERSION", "version"):
        value = getattr(module, attribute, None)
        if value is not None and not callable(value):
            text = str(value).strip()
            if text:
                return text
    return None


def collect_observability_module_versions(
    *,
    config: AnalysisObservabilityConfigLike = None,
) -> Dict[str, Any]:
    """Collect versions for DockAnalyzer modules and optional dependencies."""

    resolved = resolve_analysis_observability_config(config)
    if not resolved.enabled or not resolved.include_module_versions:
        return {}
    versions: Dict[str, Any] = {}
    for name in OBSERVABILITY_INTERNAL_MODULES:
        if len(versions) >= resolved.max_version_items:
            break
        module: Any = None
        if name == "analyze":
            module = sys.modules.get(__name__)
        elif name == "config":
            module = config
        elif name == "utils":
            module_name = getattr(DockModel, "__module__", "")
            module = sys.modules.get(module_name)
        else:
            try:
                module = load_analysis_module(name, validate=False)
            except Exception:
                module = None
        if module is None:
            versions[name] = {"available": False, "version": None}
        else:
            versions[name] = {
                "available": True,
                "version": _module_version(module),
                "module": getattr(module, "__name__", name),
                "file": str(getattr(module, "__file__", "") or "") or None,
            }
    try:
        from importlib import metadata as importlib_metadata
    except ImportError:  # pragma: no cover - supported Python always provides it
        importlib_metadata = None
    for package_name in OBSERVABILITY_EXTERNAL_PACKAGES:
        if len(versions) >= resolved.max_version_items:
            break
        distribution_name = "Pillow" if package_name == "PIL" else package_name
        version: Optional[str] = None
        if importlib_metadata is not None:
            try:
                version = importlib_metadata.version(distribution_name)
            except importlib_metadata.PackageNotFoundError:
                version = None
        versions[package_name] = {
            "available": version is not None,
            "version": version,
        }
    return versions


def collect_observability_platform() -> Dict[str, Any]:
    """Collect non-sensitive operating-system and machine metadata."""

    return {
        "system": platform.system() or None,
        "release": platform.release() or None,
        "version": platform.version() or None,
        "machine": platform.machine() or None,
        "processor": platform.processor() or None,
        "architecture": list(platform.architecture()),
        "platform": platform.platform(),
    }


def collect_observability_python() -> Dict[str, Any]:
    """Collect Python runtime metadata."""

    return {
        "version": platform.python_version(),
        "implementation": platform.python_implementation(),
        "compiler": platform.python_compiler(),
        "build": list(platform.python_build()),
        "executable_name": Path(sys.executable).name if sys.executable else None,
        "optimization_level": int(getattr(sys.flags, "optimize", 0)),
        "debug": bool(getattr(sys.flags, "debug", 0)),
        "hash_randomization": bool(getattr(sys.flags, "hash_randomization", 0)),
        "byteorder": sys.byteorder,
    }


def collect_observability_process() -> Dict[str, Any]:
    """Collect process metadata without exposing command-line arguments."""

    return {
        "pid": os.getpid(),
        "parent_pid": os.getppid() if hasattr(os, "getppid") else None,
        "cpu_count": os.cpu_count(),
        "thread_count": threading.active_count(),
        "main_thread": threading.current_thread() is threading.main_thread(),
        "current_thread": threading.current_thread().name,
        "working_directory_name": Path.cwd().name,
    }


def collect_observability_chimerax(session: Any = None) -> Dict[str, Any]:
    """Collect ChimeraX availability and session metadata."""

    result: Dict[str, Any] = {
        "available": bool(CHIMERAX_AVAILABLE),
        "session_provided": session is not None,
    }
    if _chimerax is not None:
        result["version"] = _module_version(_chimerax)
        result["module"] = getattr(_chimerax, "__name__", "chimerax")
    if session is not None:
        result["session_type"] = type(session).__name__
        models = getattr(session, "models", None)
        if models is not None:
            try:
                listed = models.list() if callable(getattr(models, "list", None)) else models
                result["model_count"] = len(list(listed))
            except Exception:
                result["model_count"] = None
    return result


def collect_observability_environment(
    *,
    config: AnalysisObservabilityConfigLike = None,
    environ: Optional[Mapping[str, str]] = None,
) -> Dict[str, Any]:
    """Collect explicitly permitted environment variables."""

    resolved = resolve_analysis_observability_config(config)
    if not resolved.enabled or not resolved.include_environment:
        return {}
    source = os.environ if environ is None else environ
    names = _normalize_environment_names(
        (*resolved.environment_allowlist, *resolved.additional_environment_names)
    )
    result: Dict[str, Any] = {}
    for name in names[: resolved.max_environment_items]:
        if name not in source:
            continue
        value: Any = source[name]
        if resolved.redact_sensitive_values and _observability_sensitive_key(name):
            value = "<redacted>"
        result[name] = value
    return result


def collect_observability_input_fingerprints(
    value: Any,
    *,
    max_items: int = 10_000,
) -> Dict[str, Any]:
    """Collect stable, content-light fingerprints for analysis inputs."""

    result: Dict[str, Any] = {}
    context = value if isinstance(value, AnalysisContext) else None
    request = context.request if context is not None else (
        value if isinstance(value, AnalysisRequest) else None
    )
    if context is not None:
        result["run_id"] = context.run_id
        result["request_id"] = context.request_id
        result["mode"] = context.mode
        result["receptor"] = stable_object_fingerprint(context.receptor)
        result["poses"] = [
            stable_object_fingerprint(item) for item in context.poses[:max_items]
        ]
        result["dock_models"] = [
            stable_object_fingerprint(item) for item in context.dock_models[:max_items]
        ]
    elif request is not None:
        result["request_id"] = request.request_id
        result["mode"] = request.mode
        result["receptor"] = stable_object_fingerprint(request.receptor)
        result["poses"] = [
            stable_object_fingerprint(item) for item in request.poses[:max_items]
        ]
        result["dock_models"] = [
            stable_object_fingerprint(item) for item in request.dock_models[:max_items]
        ]
    elif value is not None:
        result["input"] = stable_object_fingerprint(value)
    return result


@dataclass(frozen=True)
class AnalysisProvenanceSnapshot:
    """Immutable provenance snapshot for one analysis execution."""

    created_at: str = field(default_factory=_utc_timestamp)
    schema_name: str = PROVENANCE_SCHEMA_NAME
    schema_version: str = PROVENANCE_SCHEMA_VERSION
    run_id: Optional[str] = None
    request_id: Optional[str] = None
    mode: Optional[str] = None
    module: Mapping[str, Any] = field(default_factory=dict)
    platform: Mapping[str, Any] = field(default_factory=dict)
    python: Mapping[str, Any] = field(default_factory=dict)
    process: Mapping[str, Any] = field(default_factory=dict)
    chimerax: Mapping[str, Any] = field(default_factory=dict)
    module_versions: Mapping[str, Any] = field(default_factory=dict)
    environment: Mapping[str, Any] = field(default_factory=dict)
    inputs: Mapping[str, Any] = field(default_factory=dict)
    configuration: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "created_at",
            _normalize_timestamp(self.created_at) or _utc_timestamp(),
        )
        object.__setattr__(self, "run_id", _normalize_optional_text(self.run_id))
        object.__setattr__(
            self,
            "request_id",
            _normalize_optional_text(self.request_id),
        )
        if self.mode is not None:
            try:
                object.__setattr__(self, "mode", canonicalize_analysis_mode(self.mode))
            except ValueError:
                object.__setattr__(
                    self,
                    "mode",
                    _normalize_convention_token(self.mode, field_name="analysis mode"),
                )
        for name in (
            "module",
            "platform",
            "python",
            "process",
            "chimerax",
            "module_versions",
            "environment",
            "inputs",
            "configuration",
            "metadata",
        ):
            object.__setattr__(
                self,
                name,
                MappingProxyType(redact_observability_mapping(getattr(self, name))),
            )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready provenance mapping."""

        return {
            "schema": self.schema_name,
            "schema_version": self.schema_version,
            "created_at": self.created_at,
            "run_id": self.run_id,
            "request_id": self.request_id,
            "mode": self.mode,
            "module": _result_value_to_data(self.module),
            "platform": _result_value_to_data(self.platform),
            "python": _result_value_to_data(self.python),
            "process": _result_value_to_data(self.process),
            "chimerax": _result_value_to_data(self.chimerax),
            "module_versions": _result_value_to_data(self.module_versions),
            "environment": _result_value_to_data(self.environment),
            "inputs": _result_value_to_data(self.inputs),
            "configuration": _result_value_to_data(self.configuration),
            "metadata": _result_value_to_data(self.metadata),
        }


def collect_analysis_provenance(
    value: Any = None,
    *,
    config: AnalysisObservabilityConfigLike = None,
    session: Any = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisProvenanceSnapshot:
    """Collect provenance for a context, request, result or arbitrary input."""

    analysis_config: Optional[AnalysisConfig] = None
    context: Optional[AnalysisContext] = None
    request: Optional[AnalysisRequest] = None
    result: Optional[AnalysisRunResult] = None
    if isinstance(value, AnalysisRunResult):
        result = value
        context = value.context
        request = value.request or (context.request if context is not None else None)
    elif isinstance(value, AnalysisContext):
        context = value
        request = value.request
    elif isinstance(value, AnalysisRequest):
        request = value
    if context is not None:
        analysis_config = context.config
        if session is None:
            session = context.session
    elif request is not None:
        analysis_config = request.config
        if session is None:
            session = request.session
    resolved = resolve_analysis_observability_config(
        config,
        analysis_config=analysis_config,
    )
    if not resolved.enabled:
        return AnalysisProvenanceSnapshot(metadata={"enabled": False})
    run_id = result.run_id if result is not None else (
        context.run_id if context is not None else None
    )
    request_id = request.request_id if request is not None else (
        result.request_id if result is not None else None
    )
    mode = result.mode if result is not None else (
        context.mode if context is not None else (
            request.mode if request is not None else None
        )
    )
    configuration: Dict[str, Any] = {}
    if analysis_config is not None:
        configuration["effective"] = analysis_config.to_dict()
        if resolved.include_config_fingerprint:
            configuration["fingerprint"] = analysis_config.fingerprint()
    configuration["observability_fingerprint"] = resolved.fingerprint()
    inputs = (
        collect_observability_input_fingerprints(context or request or value)
        if resolved.include_input_fingerprints
        else {}
    )
    return AnalysisProvenanceSnapshot(
        run_id=run_id,
        request_id=request_id,
        mode=mode,
        module={
            "name": _MODULE_NAME,
            "description": _MODULE_DESCRIPTION,
            "version": __version__,
            "schema": ANALYSIS_SCHEMA_NAME,
            "schema_version": ANALYSIS_SCHEMA_VERSION,
        },
        platform=(collect_observability_platform() if resolved.include_platform else {}),
        python=(collect_observability_python() if resolved.include_python else {}),
        process=(collect_observability_process() if resolved.include_process else {}),
        chimerax=(
            collect_observability_chimerax(session)
            if resolved.include_chimerax
            else {}
        ),
        module_versions=collect_observability_module_versions(config=resolved),
        environment=collect_observability_environment(config=resolved),
        inputs=inputs,
        configuration=configuration,
        metadata={**dict(resolved.metadata), **dict(metadata or {})},
    )


# 26.7. Timing extraction and operation timers
# -----------------------------------------------------------------------------


def collect_stage_timing_records(
    value: Any,
    *,
    config: AnalysisObservabilityConfigLike = None,
) -> List[AnalysisTimingRecord]:
    """Extract timing records from stage results in a context or result."""

    resolved = resolve_analysis_observability_config(config)
    if not resolved.enabled or not resolved.capture_stage_timings:
        return []
    stage_results: Mapping[str, Any] = {}
    if isinstance(value, AnalysisRunResult):
        stage_results = value.stage_results
    elif isinstance(value, Mapping):
        stage_results = value
    elif hasattr(value, "stage_results"):
        stage_results = getattr(value, "stage_results", {}) or {}
    elif isinstance(value, AnalysisContext):
        stage_results = {
            key: item
            for key, item in value.stage_data.items()
            if isinstance(item, AnalysisStageResult)
        }
    records: List[AnalysisTimingRecord] = []
    for stage, item in stage_results.items():
        if len(records) >= resolved.max_timing_records:
            break
        stage_result = item
        if not isinstance(stage_result, AnalysisStageResult):
            try:
                stage_result = _coerce_stage_result(item, stage=str(stage))
            except Exception:
                continue
        duration = stage_result.duration_seconds
        if duration is None:
            duration = stage_result._calculate_duration()
        if duration is None:
            continue
        records.append(
            AnalysisTimingRecord(
                name=stage_result.stage,
                category="stage",
                stage=stage_result.stage,
                started_at=stage_result.started_at or _utc_timestamp(),
                finished_at=stage_result.finished_at,
                duration_seconds=duration,
                successful=stage_result.succeeded,
                cached=stage_result.cached,
                metadata={
                    "status": stage_result.status.value,
                    "attempt": stage_result.attempt,
                    "required": stage_result.required,
                },
            )
        )
    return records


def collect_analysis_timing_summary(
    value: Any,
    *,
    operation_records: Optional[Iterable[AnalysisTimingRecord]] = None,
    config: AnalysisObservabilityConfigLike = None,
) -> AnalysisTimingSummary:
    """Build a timing summary from run, payload and operation records."""

    analysis_config = None
    if isinstance(value, AnalysisRunResult) and value.context is not None:
        analysis_config = value.context.config
    elif isinstance(value, AnalysisContext):
        analysis_config = value.config
    resolved = resolve_analysis_observability_config(
        config,
        analysis_config=analysis_config,
    )
    records = collect_stage_timing_records(value, config=resolved)
    if resolved.capture_operation_timings and operation_records is not None:
        for record in operation_records:
            if len(records) >= resolved.max_timing_records:
                break
            if isinstance(record, AnalysisTimingRecord):
                records.append(record)
    started_at = getattr(value, "started_at", None)
    finished_at = getattr(value, "finished_at", None)
    total_duration = getattr(value, "duration_seconds", None)
    if total_duration is None and started_at and finished_at:
        try:
            total_duration = max(
                0.0,
                (
                    datetime.fromisoformat(finished_at)
                    - datetime.fromisoformat(started_at)
                ).total_seconds(),
            )
        except (TypeError, ValueError):
            total_duration = None
    summary = AnalysisTimingSummary(
        records=records,
        total_duration_seconds=total_duration,
        started_at=_normalize_timestamp(started_at, allow_none=True),
        finished_at=_normalize_timestamp(finished_at, allow_none=True),
        metadata={
            "slow_stage_threshold_seconds": resolved.slow_stage_threshold_seconds,
            "slow_operation_threshold_seconds": resolved.slow_operation_threshold_seconds,
        },
    )
    return summary


class AnalysisOperationTimer:
    """Context manager that records one orchestration operation."""

    def __init__(
        self,
        name: str,
        *,
        collector: Optional["AnalysisObservabilityCollector"] = None,
        category: str = "operation",
        stage: Optional[Any] = None,
        pose_index: Optional[int] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.name = str(name).strip()
        if not self.name:
            raise ValueError("Operation timer name cannot be empty.")
        self.collector = collector
        self.category = _normalize_convention_token(
            category,
            field_name="operation category",
        )
        self.stage = _normalize_optional_stage(stage)
        self.pose_index = pose_index
        self.metadata = dict(metadata or {})
        self.started_at: Optional[str] = None
        self.finished_at: Optional[str] = None
        self.duration_seconds: Optional[float] = None
        self.record: Optional[AnalysisTimingRecord] = None
        self._started_perf: Optional[float] = None

    def __enter__(self) -> "AnalysisOperationTimer":
        self.started_at = _utc_timestamp()
        self._started_perf = time.perf_counter()
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        finished_perf = time.perf_counter()
        self.finished_at = _utc_timestamp()
        started_perf = self._started_perf if self._started_perf is not None else finished_perf
        self.duration_seconds = max(0.0, finished_perf - started_perf)
        self.record = AnalysisTimingRecord(
            name=self.name,
            category=self.category,
            stage=self.stage,
            pose_index=self.pose_index,
            started_at=self.started_at or self.finished_at,
            finished_at=self.finished_at,
            duration_seconds=self.duration_seconds,
            successful=exc is None,
            metadata=self.metadata,
        )
        if self.collector is not None:
            self.collector.add_timing(self.record)
            if exc is not None:
                self.collector.add_exception(exc, stage=self.stage)
        return False


@contextmanager
def time_analysis_operation(
    name: str,
    *,
    collector: Optional["AnalysisObservabilityCollector"] = None,
    category: str = "operation",
    stage: Optional[Any] = None,
    pose_index: Optional[int] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Iterator[AnalysisOperationTimer]:
    """Measure one operation and optionally add it to a collector."""

    timer = AnalysisOperationTimer(
        name,
        collector=collector,
        category=category,
        stage=stage,
        pose_index=pose_index,
        metadata=metadata,
    )
    with timer:
        yield timer


# 26.8. Warning capture and diagnostic summaries
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class CapturedAnalysisWarning:
    """Serializable warning captured from Python's warning system."""

    message: str
    category: str
    filename: Optional[str] = None
    line_number: Optional[int] = None
    stage: Optional[str] = None
    created_at: str = field(default_factory=_utc_timestamp)

    def __post_init__(self) -> None:
        object.__setattr__(self, "message", str(self.message).strip())
        object.__setattr__(self, "category", str(self.category).strip() or "Warning")
        object.__setattr__(self, "filename", _normalize_optional_text(self.filename))
        if self.line_number is not None:
            object.__setattr__(self, "line_number", max(0, int(self.line_number)))
        object.__setattr__(self, "stage", _normalize_optional_stage(self.stage))
        object.__setattr__(
            self,
            "created_at",
            _normalize_timestamp(self.created_at) or _utc_timestamp(),
        )

    def to_issue(self) -> AnalysisIssue:
        """Convert the captured warning into an AnalysisIssue."""

        return AnalysisIssue(
            kind=IssueKind.WARNING,
            severity=IssueSeverity.WARNING,
            code="captured_python_warning",
            message=self.message,
            stage=self.stage,
            source=self.filename,
            warning_type=self.category,
            recoverable=True,
            action=RecoveryAction.CONTINUE_PARTIAL,
            scope=FailureScope.STAGE if self.stage else FailureScope.RUN,
            details={"line_number": self.line_number},
            created_at=self.created_at,
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready captured warning."""

        return {
            "message": self.message,
            "category": self.category,
            "filename": self.filename,
            "line_number": self.line_number,
            "stage": self.stage,
            "created_at": self.created_at,
        }


@contextmanager
def capture_analysis_warnings(
    *,
    collector: Optional["AnalysisObservabilityCollector"] = None,
    stage: Optional[Any] = None,
    enabled: bool = True,
) -> Iterator[List[CapturedAnalysisWarning]]:
    """Capture warnings and optionally add them to an observability collector."""

    captured: List[CapturedAnalysisWarning] = []
    if not enabled:
        yield captured
        return
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        yield captured
    normalized_stage = _normalize_optional_stage(stage)
    for item in caught:
        warning_record = CapturedAnalysisWarning(
            message=str(item.message),
            category=getattr(item.category, "__name__", str(item.category)),
            filename=Path(item.filename).name if item.filename else None,
            line_number=item.lineno,
            stage=normalized_stage,
        )
        captured.append(warning_record)
        if collector is not None:
            collector.add_captured_warning(warning_record)


def diagnostics_from_value(value: Any) -> AnalysisDiagnostics:
    """Collect diagnostics from a context, result, stage or mapping."""

    diagnostics = AnalysisDiagnostics()
    if value is None:
        return diagnostics
    direct = getattr(value, "diagnostics", None)
    if direct is not None:
        diagnostics.extend(direct)
    if isinstance(value, AnalysisContext):
        for item in value.stage_data.values():
            if isinstance(item, AnalysisStageResult):
                diagnostics.extend(item.diagnostics)
    stage_results = getattr(value, "stage_results", None)
    if isinstance(stage_results, Mapping):
        for item in stage_results.values():
            diagnostics.extend(getattr(item, "diagnostics", None))
    payload = getattr(value, "payload", None)
    if payload is not None and payload is not value:
        diagnostics.extend(getattr(payload, "diagnostics", None))
    if isinstance(value, Mapping):
        diagnostics.extend(value)
    return diagnostics


def summarize_analysis_diagnostics(value: Any) -> Dict[str, Any]:
    """Return grouped counts and actionable diagnostic information."""

    diagnostics = diagnostics_from_value(value)
    by_code = Counter(issue.code for issue in diagnostics.issues)
    by_stage = Counter(issue.stage or "run" for issue in diagnostics.issues)
    by_severity = Counter(issue.severity.name.lower() for issue in diagnostics.issues)
    by_kind = Counter(issue.kind.value for issue in diagnostics.issues)
    recoverable = sum(1 for issue in diagnostics.issues if issue.recoverable)
    tracebacks = sum(1 for issue in diagnostics.issues if issue.traceback_text)
    return {
        "schema": DIAGNOSTICS_SCHEMA_NAME,
        "schema_version": DIAGNOSTICS_SCHEMA_VERSION,
        "summary": diagnostics.summary(),
        "counts": diagnostics.counts(),
        "highest_severity": diagnostics.highest_severity.name.lower(),
        "recoverable_issue_count": recoverable,
        "unrecoverable_issue_count": len(diagnostics.issues) - recoverable,
        "traceback_count": tracebacks,
        "by_code": dict(sorted(by_code.items())),
        "by_stage": dict(sorted(by_stage.items(), key=lambda item: stage_sort_key(item[0]) if item[0] != "run" else (-1, "run"))),
        "by_severity": dict(sorted(by_severity.items())),
        "by_kind": dict(sorted(by_kind.items())),
        "issues": [issue.to_dict() for issue in diagnostics.issues],
        "messages": list(diagnostics.messages),
    }


# 26.9. Unified observability report
# -----------------------------------------------------------------------------


@dataclass
class AnalysisObservabilityReport:
    """Complete provenance, timing, log and diagnostic report."""

    provenance: AnalysisProvenanceSnapshot
    timings: AnalysisTimingSummary = field(default_factory=AnalysisTimingSummary)
    diagnostics: AnalysisDiagnostics = field(default_factory=AnalysisDiagnostics)
    log_records: List[AnalysisLogRecord] = field(default_factory=list)
    captured_warnings: List[CapturedAnalysisWarning] = field(default_factory=list)
    created_at: str = field(default_factory=_utc_timestamp)
    schema_name: str = OBSERVABILITY_SCHEMA_NAME
    schema_version: str = OBSERVABILITY_SCHEMA_VERSION
    result_type: str = OBSERVABILITY_RESULT_TYPE
    statistics: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not isinstance(self.provenance, AnalysisProvenanceSnapshot):
            raise TypeError("Observability report requires a provenance snapshot.")
        if not isinstance(self.timings, AnalysisTimingSummary):
            raise TypeError("Observability report requires a timing summary.")
        if not isinstance(self.diagnostics, AnalysisDiagnostics):
            diagnostics = AnalysisDiagnostics()
            diagnostics.extend(self.diagnostics)
            self.diagnostics = diagnostics
        self.log_records = [
            item for item in self.log_records if isinstance(item, AnalysisLogRecord)
        ]
        self.captured_warnings = [
            item
            for item in self.captured_warnings
            if isinstance(item, CapturedAnalysisWarning)
        ]
        self.created_at = _normalize_timestamp(self.created_at) or _utc_timestamp()
        self.statistics = _result_mapping(self.statistics)
        self.metadata = redact_observability_mapping(self.metadata)
        self.refresh_statistics()

    @property
    def warning_count(self) -> int:
        """Return the total diagnostic and captured warning count."""

        return len(self.diagnostics.warnings) + len(self.captured_warnings)

    @property
    def error_count(self) -> int:
        """Return the diagnostic error count."""

        return len(self.diagnostics.errors)

    @property
    def has_errors(self) -> bool:
        """Return whether unrecovered errors were recorded."""

        return bool(self.diagnostics.errors)

    def refresh_statistics(self) -> Dict[str, Any]:
        """Refresh aggregate observability statistics."""

        self.statistics.update(
            {
                "timing_record_count": len(self.timings.records),
                "log_record_count": len(self.log_records),
                "captured_warning_count": len(self.captured_warnings),
                "diagnostic_issue_count": len(self.diagnostics.issues),
                "warning_count": self.warning_count,
                "error_count": self.error_count,
                "stage_timing_count": len(self.timings.stage_records),
                "operation_timing_count": len(self.timings.operation_records),
            }
        )
        return self.statistics

    def summary(self) -> str:
        """Return a concise report summary."""

        total = self.timings.total_duration_seconds
        duration = f", {total:.6f} s" if total is not None else ""
        return (
            f"{len(self.timings.records)} timings, "
            f"{len(self.log_records)} logs, {self.warning_count} warnings, "
            f"{self.error_count} errors{duration}"
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready observability report."""

        self.refresh_statistics()
        return {
            "schema": self.schema_name,
            "schema_version": self.schema_version,
            "result_type": self.result_type,
            "created_at": self.created_at,
            "summary": self.summary(),
            "provenance": self.provenance.to_dict(),
            "timings": self.timings.to_dict(),
            "diagnostics": summarize_analysis_diagnostics(self.diagnostics),
            "logs": {
                "schema": LOG_SCHEMA_NAME,
                "schema_version": LOG_SCHEMA_VERSION,
                "record_count": len(self.log_records),
                "records": [item.to_dict() for item in self.log_records],
            },
            "captured_warnings": [
                item.to_dict() for item in self.captured_warnings
            ],
            "statistics": _result_value_to_data(self.statistics),
            "metadata": _result_value_to_data(self.metadata),
        }

    def to_json(self, *, indent: int = DEFAULT_JSON_INDENT) -> str:
        """Return the report as JSON text."""

        return json.dumps(self.to_dict(), indent=indent, sort_keys=True)


# 26.10. Thread-safe observability collector
# -----------------------------------------------------------------------------


class AnalysisObservabilityCollector:
    """Collect timings, logs, warnings and diagnostics during one run."""

    def __init__(
        self,
        value: Any = None,
        *,
        config: AnalysisObservabilityConfigLike = None,
        logger: Optional[DockLogger] = None,
        session: Any = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        analysis_config = None
        context = value if isinstance(value, AnalysisContext) else None
        if isinstance(value, AnalysisRunResult):
            context = value.context
        if context is not None:
            analysis_config = context.config
            if session is None:
                session = context.session
        self.config = resolve_analysis_observability_config(
            config,
            analysis_config=analysis_config,
        )
        self.value = value
        self.session = session
        self.metadata = redact_observability_mapping(metadata)
        self.provenance: Optional[AnalysisProvenanceSnapshot] = None
        self.timings: List[AnalysisTimingRecord] = []
        self.diagnostics = AnalysisDiagnostics()
        self.captured_warnings: List[CapturedAnalysisWarning] = []
        self.logger = AnalysisObservabilityLogger(
            logger=logger,
            config=self.config,
            context=context,
        )
        self.started_at: Optional[str] = None
        self.finished_at: Optional[str] = None
        self._started_perf: Optional[float] = None
        self._lock = threading.RLock()

    @property
    def log_records(self) -> List[AnalysisLogRecord]:
        """Return collected structured log records."""

        return self.logger.records

    def start(self) -> "AnalysisObservabilityCollector":
        """Start total-run timing and collect initial provenance."""

        with self._lock:
            if self.started_at is None:
                self.started_at = _utc_timestamp()
                self._started_perf = time.perf_counter()
            if self.provenance is None:
                self.provenance = collect_analysis_provenance(
                    self.value,
                    config=self.config,
                    session=self.session,
                    metadata=self.metadata,
                )
        return self

    def stop(self) -> "AnalysisObservabilityCollector":
        """Stop total-run timing."""

        with self._lock:
            if self.finished_at is None:
                self.finished_at = _utc_timestamp()
                finished_perf = time.perf_counter()
                started_perf = (
                    self._started_perf
                    if self._started_perf is not None
                    else finished_perf
                )
                self.add_timing(
                    AnalysisTimingRecord(
                        name="analysis_total",
                        category="run",
                        started_at=self.started_at or self.finished_at,
                        finished_at=self.finished_at,
                        duration_seconds=max(0.0, finished_perf - started_perf),
                        successful=not self.diagnostics.has_errors,
                    )
                )
        return self

    def add_timing(self, value: AnalysisTimingRecord) -> Optional[AnalysisTimingRecord]:
        """Append a timing record subject to configured limits."""

        if not self.config.enabled:
            return None
        if not isinstance(value, AnalysisTimingRecord):
            raise TypeError("Collector timing must be an AnalysisTimingRecord.")
        with self._lock:
            if len(self.timings) >= self.config.max_timing_records:
                return None
            self.timings.append(value)
        return value

    def add_issue(self, value: Any) -> AnalysisIssue:
        """Append one issue to the collector diagnostics."""

        issue = value if isinstance(value, AnalysisIssue) else _coerce_analysis_issues(value)[0]
        return self.diagnostics.add_issue(issue)

    def add_exception(
        self,
        exc: BaseException,
        *,
        stage: Optional[Any] = None,
        recoverable: Optional[bool] = None,
    ) -> AnalysisIssue:
        """Append an exception-derived issue."""

        issue = exception_to_issue(
            exc,
            stage=_normalize_optional_stage(stage),
            include_traceback=self.config.capture_tracebacks,
        )
        if recoverable is not None and issue.recoverable != bool(recoverable):
            issue = replace(issue, recoverable=bool(recoverable))
        return self.diagnostics.add_issue(issue)

    def add_captured_warning(
        self,
        value: CapturedAnalysisWarning,
    ) -> Optional[CapturedAnalysisWarning]:
        """Append one captured warning and its diagnostic issue."""

        if not self.config.enabled or not self.config.capture_warnings:
            return None
        if not isinstance(value, CapturedAnalysisWarning):
            raise TypeError("Captured warning has an unsupported type.")
        with self._lock:
            if len(self.captured_warnings) >= self.config.max_warning_records:
                return None
            self.captured_warnings.append(value)
            self.diagnostics.add_issue(value.to_issue())
        return value

    def collect_from(self, value: Any) -> "AnalysisObservabilityCollector":
        """Collect diagnostics and stage timings from an existing result."""

        self.diagnostics.extend(diagnostics_from_value(value))
        existing_keys = {
            (
                item.name,
                item.stage,
                item.started_at,
                item.finished_at,
                item.duration_seconds,
            )
            for item in self.timings
        }
        for record in collect_stage_timing_records(value, config=self.config):
            key = (
                record.name,
                record.stage,
                record.started_at,
                record.finished_at,
                record.duration_seconds,
            )
            if key not in existing_keys:
                self.add_timing(record)
                existing_keys.add(key)
        return self

    def timer(
        self,
        name: str,
        *,
        category: str = "operation",
        stage: Optional[Any] = None,
        pose_index: Optional[int] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> AnalysisOperationTimer:
        """Create an operation timer linked to this collector."""

        return AnalysisOperationTimer(
            name,
            collector=self,
            category=category,
            stage=stage,
            pose_index=pose_index,
            metadata=metadata,
        )

    def report(self) -> AnalysisObservabilityReport:
        """Build the current immutable observability report."""

        if self.provenance is None:
            self.start()
        timing_summary = collect_analysis_timing_summary(
            self.value,
            operation_records=self.timings,
            config=self.config,
        )
        if timing_summary.started_at is None:
            timing_summary.started_at = self.started_at
        if timing_summary.finished_at is None:
            timing_summary.finished_at = self.finished_at
        if timing_summary.total_duration_seconds is None:
            run_records = [
                item for item in self.timings if item.category == "run"
            ]
            if run_records:
                timing_summary.total_duration_seconds = run_records[-1].duration_seconds
        return AnalysisObservabilityReport(
            provenance=self.provenance or collect_analysis_provenance(
                self.value,
                config=self.config,
                session=self.session,
                metadata=self.metadata,
            ),
            timings=timing_summary,
            diagnostics=AnalysisDiagnostics(
                issues=list(self.diagnostics.issues),
                messages=list(self.diagnostics.messages),
                metadata=dict(self.diagnostics.metadata),
            ),
            log_records=list(self.log_records),
            captured_warnings=list(self.captured_warnings),
            metadata={
                **self.metadata,
                "config_fingerprint": self.config.fingerprint(),
            },
        )

    def __enter__(self) -> "AnalysisObservabilityCollector":
        return self.start()

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        if exc is not None:
            self.add_exception(exc)
        self.stop()
        return False


# 26.11. Result and context attachment
# -----------------------------------------------------------------------------


def attach_observability_to_context(
    context: AnalysisContext,
    report: AnalysisObservabilityReport,
    *,
    replace_existing: bool = True,
) -> AnalysisContext:
    """Attach observability data to an AnalysisContext."""

    if not isinstance(context, AnalysisContext):
        raise TypeError("Observability context attachment requires AnalysisContext.")
    if not isinstance(report, AnalysisObservabilityReport):
        raise TypeError("Observability context attachment requires a report.")
    report_data = report.to_dict()
    if replace_existing or context.get_shared(OBSERVABILITY_SHARED_KEY) is None:
        context.set_shared(OBSERVABILITY_SHARED_KEY, report)
    context.set_shared(PROVENANCE_SHARED_KEY, report.provenance)
    context.set_shared(TIMINGS_SHARED_KEY, report.timings)
    context.set_shared(DIAGNOSTICS_SHARED_KEY, report.diagnostics)
    context.set_shared(LOG_RECORDS_SHARED_KEY, list(report.log_records))
    context.metadata[OBSERVABILITY_METADATA_KEY] = report_data
    context.metadata[PROVENANCE_METADATA_KEY] = report.provenance.to_dict()
    context.metadata[TIMINGS_METADATA_KEY] = report.timings.to_dict()
    context.metadata[DIAGNOSTICS_METADATA_KEY] = summarize_analysis_diagnostics(
        report.diagnostics
    )
    context.statistics[OBSERVABILITY_STATISTICS_KEY] = dict(report.statistics)
    context.statistics[TIMING_STATISTICS_KEY] = report.timings.to_dict()
    return context


def attach_observability_to_result(
    result: Any,
    report: AnalysisObservabilityReport,
    *,
    replace_existing: bool = True,
) -> Any:
    """Attach observability data to a run or mode-specific result."""

    if not isinstance(report, AnalysisObservabilityReport):
        raise TypeError("Result attachment requires AnalysisObservabilityReport.")
    if result is None:
        return result
    report_data = report.to_dict()
    metadata = getattr(result, "metadata", None)
    if isinstance(metadata, MutableMapping):
        if replace_existing or OBSERVABILITY_METADATA_KEY not in metadata:
            metadata[OBSERVABILITY_METADATA_KEY] = report_data
    provenance = getattr(result, "provenance", None)
    if isinstance(provenance, MutableMapping):
        provenance.update(report.provenance.to_dict())
    timings = getattr(result, "timings", None)
    if isinstance(timings, MutableMapping):
        timings.clear()
        timings.update(report.timings.by_stage())
        timings["summary"] = report.timings.to_dict()
    diagnostics = getattr(result, "diagnostics", None)
    if isinstance(diagnostics, AnalysisDiagnostics):
        diagnostics.extend(report.diagnostics)
    statistics = getattr(result, "statistics", None)
    if isinstance(statistics, MutableMapping):
        statistics[OBSERVABILITY_STATISTICS_KEY] = dict(report.statistics)
        statistics[TIMING_STATISTICS_KEY] = report.timings.to_dict()
    context = getattr(result, "context", None)
    if isinstance(context, AnalysisContext):
        attach_observability_to_context(
            context,
            report,
            replace_existing=replace_existing,
        )
    payload = getattr(result, "payload", None)
    if payload is not None and payload is not result:
        payload_metadata = getattr(payload, "metadata", None)
        if isinstance(payload_metadata, MutableMapping):
            payload_metadata[OBSERVABILITY_METADATA_KEY] = report_data
        payload_provenance = getattr(payload, "provenance", None)
        if isinstance(payload_provenance, MutableMapping):
            payload_provenance.update(report.provenance.to_dict())
        payload_timings = getattr(payload, "timings", None)
        if isinstance(payload_timings, MutableMapping):
            payload_timings.update(report.timings.by_stage())
    return result


def build_analysis_observability_report(
    value: Any,
    *,
    config: AnalysisObservabilityConfigLike = None,
    logger: Optional[DockLogger] = None,
    operation_records: Optional[Iterable[AnalysisTimingRecord]] = None,
    log_records: Optional[Iterable[AnalysisLogRecord]] = None,
    captured_warnings: Optional[Iterable[CapturedAnalysisWarning]] = None,
    diagnostics: Any = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisObservabilityReport:
    """Build an observability report from an existing analysis value."""

    analysis_config = None
    context = value.context if isinstance(value, AnalysisRunResult) else (
        value if isinstance(value, AnalysisContext) else None
    )
    if context is not None:
        analysis_config = context.config
    resolved = resolve_analysis_observability_config(
        config,
        analysis_config=analysis_config,
    )
    provenance = collect_analysis_provenance(
        value,
        config=resolved,
        session=context.session if context is not None else None,
        metadata=metadata,
    )
    timing_summary = collect_analysis_timing_summary(
        value,
        operation_records=operation_records,
        config=resolved,
    )
    collected_diagnostics = diagnostics_from_value(value)
    collected_diagnostics.extend(diagnostics)
    normalized_logs = [
        item for item in (log_records or ()) if isinstance(item, AnalysisLogRecord)
    ][: resolved.max_log_records]
    normalized_warnings = [
        item
        for item in (captured_warnings or ())
        if isinstance(item, CapturedAnalysisWarning)
    ][: resolved.max_warning_records]
    for item in normalized_warnings:
        collected_diagnostics.add_issue(item.to_issue())
    return AnalysisObservabilityReport(
        provenance=provenance,
        timings=timing_summary,
        diagnostics=collected_diagnostics,
        log_records=normalized_logs,
        captured_warnings=normalized_warnings,
        metadata=metadata or {},
    )


def enrich_analysis_observability(
    value: Any,
    *,
    config: AnalysisObservabilityConfigLike = None,
    replace_existing: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisObservabilityReport:
    """Build and attach observability information to a context or result."""

    report = build_analysis_observability_report(
        value,
        config=config,
        metadata=metadata,
    )
    if isinstance(value, AnalysisContext):
        attach_observability_to_context(
            value,
            report,
            replace_existing=replace_existing,
        )
    else:
        attach_observability_to_result(
            value,
            report,
            replace_existing=replace_existing,
        )
    return report


@contextmanager
def observe_analysis_execution(
    value: Any = None,
    *,
    config: AnalysisObservabilityConfigLike = None,
    logger: Optional[DockLogger] = None,
    session: Any = None,
    attach: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Iterator[AnalysisObservabilityCollector]:
    """Collect observability around an analysis execution block."""

    collector = AnalysisObservabilityCollector(
        value,
        config=config,
        logger=logger,
        session=session,
        metadata=metadata,
    )
    collector.start()
    try:
        with capture_analysis_warnings(
            collector=collector,
            stage=(value.current_stage if isinstance(value, AnalysisContext) else None),
            enabled=collector.config.capture_warnings,
        ):
            yield collector
    except BaseException as exc:
        collector.add_exception(exc)
        raise
    finally:
        collector.stop()
        collector.collect_from(value)
        if attach and value is not None:
            report = collector.report()
            if isinstance(value, AnalysisContext):
                attach_observability_to_context(value, report)
            else:
                attach_observability_to_result(value, report)


# 26.12. Slow-stage and health diagnostics
# -----------------------------------------------------------------------------


def identify_slow_analysis_timings(
    value: Union[AnalysisTimingSummary, Iterable[AnalysisTimingRecord]],
    *,
    config: AnalysisObservabilityConfigLike = None,
) -> Tuple[AnalysisTimingRecord, ...]:
    """Return timings that exceed configured stage or operation thresholds."""

    resolved = resolve_analysis_observability_config(config)
    records = value.records if isinstance(value, AnalysisTimingSummary) else list(value)
    slow: List[AnalysisTimingRecord] = []
    for record in records:
        threshold = (
            resolved.slow_stage_threshold_seconds
            if record.stage is not None or record.category == "stage"
            else resolved.slow_operation_threshold_seconds
        )
        if record.duration_seconds >= threshold:
            slow.append(record)
    return tuple(
        sorted(slow, key=lambda item: item.duration_seconds, reverse=True)
    )


def build_analysis_health_summary(
    value: Any,
    *,
    config: AnalysisObservabilityConfigLike = None,
) -> Dict[str, Any]:
    """Build an actionable execution-health summary."""

    report = (
        value
        if isinstance(value, AnalysisObservabilityReport)
        else build_analysis_observability_report(value, config=config)
    )
    slow = identify_slow_analysis_timings(report.timings, config=config)
    failed_stages: List[str] = []
    cached_stages: List[str] = []
    for record in report.timings.stage_records:
        if not record.successful and record.stage:
            failed_stages.append(record.stage)
        if record.cached and record.stage:
            cached_stages.append(record.stage)
    status = "healthy"
    if report.error_count:
        status = "failed"
    elif report.warning_count or failed_stages:
        status = "degraded"
    return {
        "status": status,
        "summary": report.summary(),
        "error_count": report.error_count,
        "warning_count": report.warning_count,
        "failed_stages": list(dict.fromkeys(failed_stages)),
        "cached_stages": list(dict.fromkeys(cached_stages)),
        "slow_record_count": len(slow),
        "slow_records": [item.to_dict() for item in slow[:20]],
        "total_duration_seconds": report.timings.total_duration_seconds,
        "highest_severity": report.diagnostics.highest_severity.name.lower(),
    }


def observability_report_to_json(
    value: AnalysisObservabilityReport,
    *,
    indent: int = DEFAULT_JSON_INDENT,
) -> str:
    """Serialize an observability report to JSON."""

    if not isinstance(value, AnalysisObservabilityReport):
        raise TypeError("Expected AnalysisObservabilityReport.")
    return value.to_json(indent=indent)


def summarize_analysis_observability(value: Any) -> Dict[str, Any]:
    """Return a compact summary for a report, context or result."""

    report = (
        value
        if isinstance(value, AnalysisObservabilityReport)
        else build_analysis_observability_report(value)
    )
    return {
        "schema": report.schema_name,
        "schema_version": report.schema_version,
        "summary": report.summary(),
        "created_at": report.created_at,
        "run_id": report.provenance.run_id,
        "request_id": report.provenance.request_id,
        "mode": report.provenance.mode,
        "timing_record_count": len(report.timings.records),
        "log_record_count": len(report.log_records),
        "warning_count": report.warning_count,
        "error_count": report.error_count,
        "total_duration_seconds": report.timings.total_duration_seconds,
        "health": build_analysis_health_summary(report),
    }


# 26.13. Validation and self-checks
# -----------------------------------------------------------------------------


def validate_analysis_observability_report(
    value: Any,
    *,
    strict: bool = True,
) -> Tuple[str, ...]:
    """Validate an observability report and return issue messages."""

    issues: List[str] = []
    if not isinstance(value, AnalysisObservabilityReport):
        issues.append("Value is not an AnalysisObservabilityReport.")
    else:
        data = value.to_dict()
        for key in OBSERVABILITY_REQUIRED_FIELDS:
            if key not in data:
                issues.append(f"Observability report is missing {key!r}.")
        if data.get("schema") != OBSERVABILITY_SCHEMA_NAME:
            issues.append("Observability schema name is invalid.")
        if data.get("schema_version") != OBSERVABILITY_SCHEMA_VERSION:
            issues.append("Observability schema version is invalid.")
        if not isinstance(value.provenance, AnalysisProvenanceSnapshot):
            issues.append("Provenance snapshot has an invalid type.")
        if not isinstance(value.timings, AnalysisTimingSummary):
            issues.append("Timing summary has an invalid type.")
        if not isinstance(value.diagnostics, AnalysisDiagnostics):
            issues.append("Diagnostics have an invalid type.")
        if any(item.duration_seconds < 0.0 for item in value.timings.records):
            issues.append("Timing records contain negative durations.")
        try:
            json.loads(value.to_json())
        except (TypeError, ValueError) as exc:
            issues.append(f"Observability JSON serialization failed: {exc}")
    if issues and strict:
        raise AnalysisValidationError(" ".join(issues))
    return tuple(issues)


def validate_observability_conventions() -> Dict[str, Any]:
    """Validate Section 26 conventions and representative workflows."""

    failures: List[str] = []
    try:
        config_value = AnalysisObservabilityConfig(
            include_environment=True,
            additional_environment_names=("DOCKANALYZER_TEST_VALUE",),
            capture_logs=True,
            log_level="DEBUG",
        )
        if config_value.log_level != "DEBUG":
            failures.append("Log-level canonicalization failed.")
        redacted = redact_observability_mapping(
            {"api_token": "secret", "safe": "value"}
        )
        if redacted.get("api_token") != "<redacted>":
            failures.append("Sensitive-value redaction failed.")
        request = AnalysisRequest(
            input_data={"name": "synthetic"},
            mode=ANALYSIS_MODE_SINGLE_POSE,
            config=AnalysisConfig(),
            name="Observability self-check",
        )
        context = AnalysisContext(request=request)
        context.start()
        stage_result = AnalysisStageResult(stage=STAGE_CONTACTS)
        stage_result.start()
        stage_result.finish(StageStatus.SUCCEEDED, value={"contacts": 1})
        context.set_stage_data(STAGE_CONTACTS, stage_result)
        run_result = AnalysisRunResult(
            request=request,
            context=context,
            mode=ANALYSIS_MODE_SINGLE_POSE,
            status=AnalysisStatus.SUCCEEDED,
            stage_results=OrderedDict([(STAGE_CONTACTS, stage_result)]),
            started_at=context.started_at,
        )
        run_result.finalize(AnalysisStatus.SUCCEEDED)
        collector = AnalysisObservabilityCollector(
            run_result,
            config=config_value,
            logger=_LOGGER,
        )
        collector.start()
        collector.logger.debug("Observability self-check log.", forward=False)
        with collector.timer("self_check", category="validation"):
            sum(range(100))
        with capture_analysis_warnings(
            collector=collector,
            stage=STAGE_CONTACTS,
        ):
            warnings.warn("Synthetic observability warning.", UserWarning)
        collector.collect_from(run_result)
        collector.stop()
        report = collector.report()
        validate_analysis_observability_report(report)
        attach_observability_to_result(run_result, report)
        if OBSERVABILITY_METADATA_KEY not in run_result.metadata:
            failures.append("Result observability attachment failed.")
        if PROVENANCE_SHARED_KEY not in context.shared_data:
            failures.append("Context provenance attachment failed.")
        if not report.timings.records:
            failures.append("Timing collection produced no records.")
        if not report.log_records:
            failures.append("Structured log collection produced no records.")
        if not report.captured_warnings:
            failures.append("Warning capture produced no records.")
        if not report.diagnostics.warnings:
            failures.append("Captured warning was not added to diagnostics.")
        if json.loads(report.to_json()).get("schema") != OBSERVABILITY_SCHEMA_NAME:
            failures.append("Observability JSON schema is invalid.")
        health = build_analysis_health_summary(report)
        if health.get("status") not in {"healthy", "degraded", "failed"}:
            failures.append("Health summary status is invalid.")
        provenance = collect_analysis_provenance(context, config=config_value)
        if provenance.run_id != context.run_id:
            failures.append("Provenance run identifier is incorrect.")
        if provenance.configuration.get("fingerprint") is None:
            failures.append("Configuration fingerprint was not recorded.")
        summary = summarize_analysis_observability(report)
        if summary.get("timing_record_count", 0) < 1:
            failures.append("Observability summary timing count is invalid.")
    except Exception as exc:
        failures.append(
            f"Observability integration failed: {type(exc).__name__}: {exc}"
        )
    if failures:
        raise RuntimeError(
            "Observability convention validation failed: " + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": OBSERVABILITY_SCHEMA_NAME,
        "schema_version": OBSERVABILITY_SCHEMA_VERSION,
        "validated_cases": 36,
        "supported_log_levels": len(OBSERVABILITY_LOG_LEVELS),
        "internal_modules": len(OBSERVABILITY_INTERNAL_MODULES),
    }


