class ValidationDisposition(str, Enum):
    """Final action selected after validation."""

    ACCEPT = VALIDATION_DISPOSITION_ACCEPT
    ACCEPT_PARTIAL = VALIDATION_DISPOSITION_ACCEPT_PARTIAL
    SKIP = VALIDATION_DISPOSITION_SKIP
    REJECT = VALIDATION_DISPOSITION_REJECT


# 27.2. Canonicalization helpers
# -----------------------------------------------------------------------------


def canonicalize_validation_phase(value: Any) -> str:
    """Return a canonical validation phase name."""

    token = _normalize_convention_token(value, field_name="validation phase")
    if token in VALIDATION_PHASE_ORDER:
        return token
    try:
        return VALIDATION_PHASE_ALIASES[token]
    except KeyError as exc:
        raise ValueError(f"Unknown validation phase: {value!r}.") from exc


def canonicalize_validation_phases(values: Any) -> Tuple[str, ...]:
    """Return unique validation phases in canonical order."""

    if values is None:
        return VALIDATION_PHASE_ORDER
    raw_values = (values,) if isinstance(values, str) else tuple(values)
    selected = {canonicalize_validation_phase(value) for value in raw_values}
    return tuple(phase for phase in VALIDATION_PHASE_ORDER if phase in selected)


def canonicalize_validation_category(value: Any) -> str:
    """Return a canonical validation category."""

    token = _normalize_convention_token(value, field_name="validation category")
    if token not in VALIDATION_CATEGORIES:
        raise ValueError(f"Unknown validation category: {value!r}.")
    return token


def canonicalize_validation_disposition(value: Any) -> ValidationDisposition:
    """Return a canonical validation disposition."""

    if isinstance(value, ValidationDisposition):
        return value
    token = _normalize_convention_token(value, field_name="validation disposition")
    aliases = {
        "accept": ValidationDisposition.ACCEPT,
        "valid": ValidationDisposition.ACCEPT,
        "success": ValidationDisposition.ACCEPT,
        "accept_partial": ValidationDisposition.ACCEPT_PARTIAL,
        "partial": ValidationDisposition.ACCEPT_PARTIAL,
        "continue": ValidationDisposition.ACCEPT_PARTIAL,
        "skip": ValidationDisposition.SKIP,
        "ignore": ValidationDisposition.SKIP,
        "reject": ValidationDisposition.REJECT,
        "invalid": ValidationDisposition.REJECT,
        "fail": ValidationDisposition.REJECT,
    }
    try:
        return aliases[token]
    except KeyError as exc:
        raise ValueError(f"Unknown validation disposition: {value!r}.") from exc


# 27.3. Validation policy
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisValidationPolicy:
    """Immutable policy controlling integrated validation behavior."""

    failure_policy: str = DEFAULT_FAILURE_POLICY
    enabled: bool = DEFAULT_VALIDATION_ENABLED
    phases: Tuple[str, ...] = VALIDATION_PHASE_ORDER
    validate_configuration: bool = DEFAULT_VALIDATION_VALIDATE_CONFIGURATION
    validate_input: bool = DEFAULT_VALIDATION_VALIDATE_INPUT
    validate_preparation: bool = DEFAULT_VALIDATION_VALIDATE_PREPARATION
    validate_plan: bool = DEFAULT_VALIDATION_VALIDATE_PLAN
    validate_stage_results: bool = DEFAULT_VALIDATION_VALIDATE_STAGE_RESULTS
    validate_interactions: bool = DEFAULT_VALIDATION_VALIDATE_INTERACTIONS
    validate_scoring: bool = DEFAULT_VALIDATION_VALIDATE_SCORING
    validate_outputs: bool = DEFAULT_VALIDATION_VALIDATE_OUTPUTS
    validate_files: bool = DEFAULT_VALIDATION_VALIDATE_FILES
    validate_serialization: bool = DEFAULT_VALIDATION_VALIDATE_SERIALIZATION
    require_terminal_results: bool = DEFAULT_VALIDATION_REQUIRE_TERMINAL_RESULTS
    require_existing_files: bool = DEFAULT_VALIDATION_REQUIRE_EXISTING_FILES
    require_nonempty_results: bool = DEFAULT_VALIDATION_REQUIRE_NONEMPTY_RESULTS
    treat_warnings_as_errors: bool = DEFAULT_VALIDATION_TREAT_WARNINGS_AS_ERRORS
    optional_failures_are_warnings: bool = (
        DEFAULT_VALIDATION_OPTIONAL_FAILURES_ARE_WARNINGS
    )
    required_failures_are_errors: bool = (
        DEFAULT_VALIDATION_REQUIRED_FAILURES_ARE_ERRORS
    )
    allow_partial_results: bool = DEFAULT_VALIDATION_ALLOW_PARTIAL_RESULTS
    attach_report: bool = DEFAULT_VALIDATION_ATTACH_REPORT
    max_findings: int = DEFAULT_VALIDATION_MAX_FINDINGS
    max_serialized_characters: int = DEFAULT_VALIDATION_MAX_SERIALIZED_CHARACTERS

    def __post_init__(self) -> None:
        policy = canonicalize_failure_policy(self.failure_policy)
        phases = canonicalize_validation_phases(self.phases)
        max_findings = int(self.max_findings)
        max_serialized_characters = int(self.max_serialized_characters)
        if max_findings < 1:
            raise AnalysisConfigurationError("Validation max_findings must be positive.")
        if max_serialized_characters < 1024:
            raise AnalysisConfigurationError(
                "Validation max_serialized_characters must be at least 1024."
            )
        object.__setattr__(self, "failure_policy", policy)
        object.__setattr__(self, "phases", phases)
        object.__setattr__(self, "enabled", bool(self.enabled))
        for name in (
            "validate_configuration",
            "validate_input",
            "validate_preparation",
            "validate_plan",
            "validate_stage_results",
            "validate_interactions",
            "validate_scoring",
            "validate_outputs",
            "validate_files",
            "validate_serialization",
            "require_terminal_results",
            "require_existing_files",
            "require_nonempty_results",
            "treat_warnings_as_errors",
            "optional_failures_are_warnings",
            "required_failures_are_errors",
            "allow_partial_results",
            "attach_report",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        object.__setattr__(self, "max_findings", max_findings)
        object.__setattr__(
            self,
            "max_serialized_characters",
            max_serialized_characters,
        )
        if policy == FAILURE_POLICY_STRICT and self.allow_partial_results:
            object.__setattr__(self, "allow_partial_results", False)

    @property
    def strict(self) -> bool:
        """Return whether validation must reject any error."""

        return self.failure_policy == FAILURE_POLICY_STRICT

    @property
    def permissive(self) -> bool:
        """Return whether recoverable validation errors may be accepted."""

        return self.failure_policy == FAILURE_POLICY_PERMISSIVE

    @property
    def partial(self) -> bool:
        """Return whether useful partial results are preferred."""

        return self.failure_policy == FAILURE_POLICY_PARTIAL

    @property
    def skip_failures(self) -> bool:
        """Return whether optional invalid components should be skipped."""

        return self.failure_policy == FAILURE_POLICY_SKIP

    def phase_enabled(self, phase: Any) -> bool:
        """Return whether one validation phase is enabled."""

        return canonicalize_validation_phase(phase) in self.phases

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready policy mapping."""

        return {
            "failure_policy": self.failure_policy,
            "enabled": self.enabled,
            "phases": list(self.phases),
            "validate_configuration": self.validate_configuration,
            "validate_input": self.validate_input,
            "validate_preparation": self.validate_preparation,
            "validate_plan": self.validate_plan,
            "validate_stage_results": self.validate_stage_results,
            "validate_interactions": self.validate_interactions,
            "validate_scoring": self.validate_scoring,
            "validate_outputs": self.validate_outputs,
            "validate_files": self.validate_files,
            "validate_serialization": self.validate_serialization,
            "require_terminal_results": self.require_terminal_results,
            "require_existing_files": self.require_existing_files,
            "require_nonempty_results": self.require_nonempty_results,
            "treat_warnings_as_errors": self.treat_warnings_as_errors,
            "optional_failures_are_warnings": self.optional_failures_are_warnings,
            "required_failures_are_errors": self.required_failures_are_errors,
            "allow_partial_results": self.allow_partial_results,
            "attach_report": self.attach_report,
            "max_findings": self.max_findings,
            "max_serialized_characters": self.max_serialized_characters,
        }


AnalysisValidationPolicyLike: TypeAlias = Union[
    AnalysisValidationPolicy,
    AnalysisConfig,
    Mapping[str, Any],
    None,
]


def resolve_analysis_validation_policy(
    value: AnalysisValidationPolicyLike = None,
    *,
    context: Optional[AnalysisContext] = None,
    config: Optional[AnalysisConfigLike] = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> AnalysisValidationPolicy:
    """Resolve validation controls from policy, context or analysis config."""

    if isinstance(value, AnalysisValidationPolicy):
        base = value
    else:
        config_value: Optional[AnalysisConfig] = None
        raw: Dict[str, Any] = {}
        if isinstance(value, AnalysisConfig):
            config_value = value
        elif isinstance(value, Mapping):
            raw.update(dict(value))
        elif value is not None:
            raise AnalysisConfigurationError(
                "Validation policy must be a policy, AnalysisConfig, mapping or None."
            )
        if config_value is None and config is not None:
            config_value = coerce_analysis_config(config)
        if config_value is None and context is not None:
            config_value = context.config
        if config_value is not None:
            raw.setdefault("failure_policy", config_value.runtime.failure_policy)
            raw.setdefault(
                "allow_partial_results",
                config_value.runtime.allow_partial_results,
            )
            stage_config = config_value.stage_config(STAGE_VALIDATION)
            raw.setdefault("enabled", stage_config.enabled)
            if stage_config.parameters:
                raw.update(dict(stage_config.parameters))
        allowed = {field_info.name for field_info in fields(AnalysisValidationPolicy)}
        base = AnalysisValidationPolicy(
            **{key: raw[key] for key in raw if key in allowed}
        )
    if not overrides:
        return base
    data = base.to_dict()
    data.update(dict(overrides))
    allowed = {field_info.name for field_info in fields(AnalysisValidationPolicy)}
    return AnalysisValidationPolicy(
        **{key: data[key] for key in data if key in allowed}
    )


# 27.4. Findings and reports
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisValidationFinding:
    """One structured finding emitted by an integrated validator."""

    code: str
    message: str
    phase: str = VALIDATION_PHASE_FINAL_RESULT
    category: str = VALIDATION_CATEGORY_CONTENT
    severity: Union[IssueSeverity, str, int] = IssueSeverity.ERROR
    stage: Optional[str] = None
    path: Optional[str] = None
    recoverable: bool = True
    details: Mapping[str, Any] = field(default_factory=dict)
    source: Optional[str] = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "code", _normalize_issue_code(self.code))
        object.__setattr__(self, "message", str(self.message).strip())
        object.__setattr__(self, "phase", canonicalize_validation_phase(self.phase))
        object.__setattr__(
            self,
            "category",
            canonicalize_validation_category(self.category),
        )
        object.__setattr__(
            self,
            "severity",
            canonicalize_issue_severity(self.severity),
        )
        object.__setattr__(self, "stage", _normalize_optional_stage(self.stage))
        object.__setattr__(self, "path", _normalize_optional_text(self.path))
        object.__setattr__(self, "recoverable", bool(self.recoverable))
        object.__setattr__(self, "details", MappingProxyType(dict(self.details)))
        object.__setattr__(self, "source", _normalize_optional_text(self.source))
        if not self.message:
            raise ValueError("Validation finding message cannot be empty.")

    @property
    def is_error(self) -> bool:
        """Return whether the finding has error severity or greater."""

        return self.severity >= IssueSeverity.ERROR

    @property
    def is_warning(self) -> bool:
        """Return whether the finding has warning severity."""

        return self.severity == IssueSeverity.WARNING

    @property
    def is_critical(self) -> bool:
        """Return whether the finding is critical."""

        return self.severity >= IssueSeverity.CRITICAL

    def to_issue(self) -> AnalysisIssue:
        """Convert this finding to a standard analysis issue."""

        kind = IssueKind.ERROR if self.is_error else (
            IssueKind.WARNING if self.is_warning else IssueKind.MESSAGE
        )
        if self.is_critical or not self.recoverable:
            action = RecoveryAction.ABORT_RUN
        elif self.is_error:
            action = RecoveryAction.CONTINUE_PARTIAL
        else:
            action = RecoveryAction.NONE
        return AnalysisIssue(
            kind=kind,
            severity=self.severity,
            code=self.code,
            message=self.message,
            stage=self.stage or STAGE_VALIDATION,
            source=self.source or "validation",
            recoverable=self.recoverable,
            action=action,
            scope=FailureScope.STAGE,
            details={
                "phase": self.phase,
                "category": self.category,
                "path": self.path,
                **dict(self.details),
            },
        )

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready finding mapping."""

        return {
            "code": self.code,
            "message": self.message,
            "phase": self.phase,
            "category": self.category,
            "severity": self.severity.name.lower(),
            "severity_level": int(self.severity),
            "stage": self.stage,
            "path": self.path,
            "recoverable": self.recoverable,
            "details": to_json_compatible(dict(self.details)),
            "source": self.source,
        }


@dataclass
class AnalysisValidationReport:
    """Integrated validation report for one pipeline scope."""

    target_type: str = "analysis"
    target_id: Optional[str] = None
    policy: AnalysisValidationPolicy = field(default_factory=AnalysisValidationPolicy)
    findings: List[AnalysisValidationFinding] = field(default_factory=list)
    checks: Dict[str, int] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    started_at: str = field(default_factory=lambda: _utc_timestamp())
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    disposition: Union[ValidationDisposition, str] = ValidationDisposition.ACCEPT
    result_type: str = VALIDATION_RESULT_TYPE

    def __post_init__(self) -> None:
        self.target_type = _normalize_convention_token(
            self.target_type,
            field_name="validation target type",
        )
        self.target_id = _normalize_optional_text(self.target_id)
        if not isinstance(self.policy, AnalysisValidationPolicy):
            self.policy = resolve_analysis_validation_policy(self.policy)
        normalized: List[AnalysisValidationFinding] = []
        for finding in self.findings:
            normalized.append(
                finding
                if isinstance(finding, AnalysisValidationFinding)
                else validation_finding_from_value(finding)
            )
        self.findings = normalized[: self.policy.max_findings]
        self.checks = {str(key): max(0, int(value)) for key, value in self.checks.items()}
        self.metadata = dict(self.metadata)
        self.disposition = canonicalize_validation_disposition(self.disposition)
        self.result_type = str(self.result_type or VALIDATION_RESULT_TYPE)

    @property
    def errors(self) -> Tuple[AnalysisValidationFinding, ...]:
        """Return error and critical findings."""

        return tuple(finding for finding in self.findings if finding.is_error)

    @property
    def warnings(self) -> Tuple[AnalysisValidationFinding, ...]:
        """Return warning findings."""

        return tuple(finding for finding in self.findings if finding.is_warning)

    @property
    def notices(self) -> Tuple[AnalysisValidationFinding, ...]:
        """Return informational findings."""

        return tuple(
            finding
            for finding in self.findings
            if finding.severity < IssueSeverity.WARNING
        )

    @property
    def valid(self) -> bool:
        """Return whether no effective error remains."""

        if self.policy.treat_warnings_as_errors and self.warnings:
            return False
        return not self.errors

    @property
    def accepted(self) -> bool:
        """Return whether policy accepts the validation outcome."""

        return self.disposition in {
            ValidationDisposition.ACCEPT,
            ValidationDisposition.ACCEPT_PARTIAL,
            ValidationDisposition.SKIP,
        }

    @property
    def completed(self) -> bool:
        """Return whether validation has been finalized."""

        return self.finished_at is not None

    def add_finding(self, finding: AnalysisValidationFinding) -> bool:
        """Append one finding unless the report limit was reached."""

        if len(self.findings) >= self.policy.max_findings:
            return False
        self.findings.append(finding)
        return True

    def add(
        self,
        code: str,
        message: str,
        *,
        phase: str,
        category: str = VALIDATION_CATEGORY_CONTENT,
        severity: Union[IssueSeverity, str, int] = IssueSeverity.ERROR,
        stage: Optional[str] = None,
        path: Optional[str] = None,
        recoverable: bool = True,
        details: Optional[Mapping[str, Any]] = None,
        source: Optional[str] = None,
    ) -> bool:
        """Construct and append one validation finding."""

        return self.add_finding(
            AnalysisValidationFinding(
                code=code,
                message=message,
                phase=phase,
                category=category,
                severity=severity,
                stage=stage,
                path=path,
                recoverable=recoverable,
                details=details or {},
                source=source,
            )
        )

    def mark_check(self, phase: Any, count: int = 1) -> None:
        """Increment the completed-check count for one phase."""

        canonical = canonicalize_validation_phase(phase)
        self.checks[canonical] = self.checks.get(canonical, 0) + max(0, int(count))

    def finalize(self) -> "AnalysisValidationReport":
        """Select policy disposition and finalize timing."""

        effective_errors = len(self.errors)
        if self.policy.treat_warnings_as_errors:
            effective_errors += len(self.warnings)
        unrecoverable = any(
            finding.is_error and not finding.recoverable
            for finding in self.findings
        )
        if effective_errors == 0:
            disposition = ValidationDisposition.ACCEPT
        elif self.policy.skip_failures and not unrecoverable:
            disposition = ValidationDisposition.SKIP
        elif (
            not self.policy.strict
            and self.policy.allow_partial_results
            and not unrecoverable
        ):
            disposition = ValidationDisposition.ACCEPT_PARTIAL
        else:
            disposition = ValidationDisposition.REJECT
        self.disposition = disposition
        self.finished_at = _utc_timestamp()
        try:
            started = datetime.fromisoformat(self.started_at)
            finished = datetime.fromisoformat(self.finished_at)
            self.duration_seconds = max(0.0, (finished - started).total_seconds())
        except (TypeError, ValueError):
            self.duration_seconds = None
        return self

    def raise_for_invalid(self) -> None:
        """Raise a structured validation error when the report is rejected."""

        if self.accepted:
            return
        messages = [finding.message for finding in self.errors]
        if self.policy.treat_warnings_as_errors:
            messages.extend(finding.message for finding in self.warnings)
        raise AnalysisValidationError(
            "Integrated analysis validation failed: " + " ".join(messages),
            stage=STAGE_VALIDATION,
            details=self.to_dict(),
        )

    def summary(self) -> Dict[str, Any]:
        """Return a concise report summary."""

        return {
            "target_type": self.target_type,
            "target_id": self.target_id,
            "valid": self.valid,
            "accepted": self.accepted,
            "disposition": self.disposition.value,
            "finding_count": len(self.findings),
            "error_count": len(self.errors),
            "warning_count": len(self.warnings),
            "notice_count": len(self.notices),
            "check_count": sum(self.checks.values()),
            "duration_seconds": self.duration_seconds,
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a serialization-ready validation report."""

        return {
            "schema": VALIDATION_SCHEMA_NAME,
            "schema_version": VALIDATION_SCHEMA_VERSION,
            "result_type": self.result_type,
            **self.summary(),
            "policy": self.policy.to_dict(),
            "checks": dict(self.checks),
            "findings": [finding.to_dict() for finding in self.findings],
            "metadata": to_json_compatible(self.metadata),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
        }


def validation_finding_from_value(
    value: Any,
    *,
    phase: str = VALIDATION_PHASE_FINAL_RESULT,
    category: str = VALIDATION_CATEGORY_CONTENT,
    severity: Union[IssueSeverity, str, int] = IssueSeverity.ERROR,
    stage: Optional[str] = None,
    source: Optional[str] = None,
) -> AnalysisValidationFinding:
    """Coerce a string, exception, issue or mapping to a finding."""

    if isinstance(value, AnalysisValidationFinding):
        return value
    if isinstance(value, AnalysisIssue):
        return AnalysisValidationFinding(
            code=value.code,
            message=value.message,
            phase=phase,
            category=category,
            severity=value.severity,
            stage=value.stage or stage,
            recoverable=value.recoverable,
            details=value.details,
            source=value.source or source,
        )
    if isinstance(value, BaseException):
        return AnalysisValidationFinding(
            code="validation_exception",
            message=str(value) or type(value).__name__,
            phase=phase,
            category=category,
            severity=severity,
            stage=stage,
            recoverable=is_recoverable_analysis_error(value),
            details={"exception_type": type(value).__name__},
            source=source,
        )
    if isinstance(value, Mapping):
        data = dict(value)
        return AnalysisValidationFinding(
            code=data.get("code", "validation_finding"),
            message=data.get("message", str(data)),
            phase=data.get("phase", phase),
            category=data.get("category", category),
            severity=data.get("severity", severity),
            stage=data.get("stage", stage),
            path=data.get("path"),
            recoverable=data.get("recoverable", True),
            details=data.get("details", {}),
            source=data.get("source", source),
        )
    return AnalysisValidationFinding(
        code="validation_finding",
        message=str(value),
        phase=phase,
        category=category,
        severity=severity,
        stage=stage,
        source=source,
    )


# 27.5. Validator registry
# -----------------------------------------------------------------------------

ValidationCallable: TypeAlias = Callable[..., Any]


@dataclass(frozen=True)
class AnalysisValidatorDefinition:
    """One named validator registered for an integrated validation phase."""

    name: str
    phase: str
    validator: ValidationCallable
    description: str = ""
    optional: bool = False
    order: int = 0
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        name = _normalize_convention_token(self.name, field_name="validator name")
        phase = canonicalize_validation_phase(self.phase)
        if not callable(self.validator):
            raise AnalysisConfigurationError("Registered validator must be callable.")
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "phase", phase)
        object.__setattr__(self, "description", str(self.description).strip())
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "order", int(self.order))
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))


class AnalysisValidatorRegistry:
    """Thread-safe registry of integrated validators."""

    def __init__(self) -> None:
        self._definitions: "OrderedDict[str, AnalysisValidatorDefinition]" = OrderedDict()
        self._lock = threading.RLock()

    def register(
        self,
        definition: AnalysisValidatorDefinition,
        *,
        replace_existing: bool = False,
    ) -> AnalysisValidatorDefinition:
        """Register one validator definition."""

        if not isinstance(definition, AnalysisValidatorDefinition):
            raise TypeError("definition must be AnalysisValidatorDefinition.")
        with self._lock:
            if definition.name in self._definitions and not replace_existing:
                raise AnalysisConfigurationError(
                    f"Validator {definition.name!r} is already registered."
                )
            self._definitions[definition.name] = definition
        return definition

    def unregister(self, name: Any, *, missing_ok: bool = False) -> Optional[AnalysisValidatorDefinition]:
        """Remove and return one registered validator."""

        canonical = _normalize_convention_token(name, field_name="validator name")
        with self._lock:
            if canonical not in self._definitions:
                if missing_ok:
                    return None
                raise KeyError(canonical)
            return self._definitions.pop(canonical)

    def definitions(self, phase: Optional[Any] = None) -> Tuple[AnalysisValidatorDefinition, ...]:
        """Return registered definitions, optionally filtered by phase."""

        with self._lock:
            values = tuple(self._definitions.values())
        if phase is not None:
            canonical = canonicalize_validation_phase(phase)
            values = tuple(value for value in values if value.phase == canonical)
        return tuple(sorted(values, key=lambda value: (VALIDATION_PHASE_ORDER.index(value.phase), value.order, value.name)))

    def names(self) -> Tuple[str, ...]:
        """Return registered validator names."""

        with self._lock:
            return tuple(self._definitions)

    def clone(self) -> "AnalysisValidatorRegistry":
        """Return an independent registry copy."""

        result = AnalysisValidatorRegistry()
        for definition in self.definitions():
            result.register(definition)
        return result


_DEFAULT_VALIDATOR_REGISTRY: Final[AnalysisValidatorRegistry] = AnalysisValidatorRegistry()


def get_default_validator_registry(*, copy_registry: bool = False) -> AnalysisValidatorRegistry:
    """Return the process-wide validator registry or a copy."""

    return _DEFAULT_VALIDATOR_REGISTRY.clone() if copy_registry else _DEFAULT_VALIDATOR_REGISTRY


def register_analysis_validator(
    definition: AnalysisValidatorDefinition,
    *,
    registry: Optional[AnalysisValidatorRegistry] = None,
    replace_existing: bool = False,
) -> AnalysisValidatorDefinition:
    """Register one integrated validator."""

    return (registry or get_default_validator_registry()).register(
        definition,
        replace_existing=replace_existing,
    )


def unregister_analysis_validator(
    name: Any,
    *,
    registry: Optional[AnalysisValidatorRegistry] = None,
    missing_ok: bool = False,
) -> Optional[AnalysisValidatorDefinition]:
    """Unregister one integrated validator."""

    return (registry or get_default_validator_registry()).unregister(
        name,
        missing_ok=missing_ok,
    )


def registered_analysis_validators(
    phase: Optional[Any] = None,
    *,
    registry: Optional[AnalysisValidatorRegistry] = None,
) -> Tuple[AnalysisValidatorDefinition, ...]:
    """Return integrated validator definitions."""

    return (registry or get_default_validator_registry()).definitions(phase)


# 27.6. Validation-target discovery
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class AnalysisValidationTarget:
    """Normalized objects available to integrated validators."""

    context: Optional[AnalysisContext] = None
    config: Optional[AnalysisConfig] = None
    request: Optional[AnalysisRequest] = None
    resolved_input: Optional[ResolvedAnalysisInput] = None
    preparation: Optional[ModelPreparationResult] = None
    execution_plan: Optional[AnalysisExecutionPlan] = None
    stage_results: Mapping[str, AnalysisStageResult] = field(default_factory=dict)
    pose_result: Optional[PoseAnalysisResult] = None
    multipose_result: Optional[MultiPoseAnalysisResult] = None
    batch_result: Optional[BatchAnalysisResult] = None
    run_result: Optional[AnalysisRunResult] = None
    result: Any = None

    @property
    def primary_result(self) -> Any:
        """Return the most specific available result object."""

        return (
            self.pose_result
            or self.multipose_result
            or self.batch_result
            or self.run_result
            or self.result
        )

    @property
    def target_type(self) -> str:
        """Return a canonical target type."""

        value = self.primary_result
        if isinstance(value, PoseAnalysisResult):
            return "pose"
        if isinstance(value, MultiPoseAnalysisResult):
            return "multipose"
        if isinstance(value, BatchAnalysisResult):
            return "batch"
        if isinstance(value, AnalysisRunResult):
            return "run"
        return "analysis"

    @property
    def target_id(self) -> Optional[str]:
        """Return the best available target identifier."""

        value = self.primary_result
        for name in ("pose_id", "run_id", "batch_id", "request_id", "id"):
            candidate = get_object_value(value, name, None)
            if candidate is not None:
                text = str(candidate).strip()
                if text:
                    return text
        return None


def resolve_analysis_validation_target(
    *,
    context: Optional[AnalysisContext] = None,
    config: Optional[AnalysisConfigLike] = None,
    request: Optional[AnalysisRequest] = None,
    resolved_input: Optional[ResolvedAnalysisInput] = None,
    preparation: Optional[ModelPreparationResult] = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    plan: Optional[AnalysisExecutionPlan] = None,
    analysis_result: Any = None,
    pose_result: Optional[PoseAnalysisResult] = None,
    multipose_result: Optional[MultiPoseAnalysisResult] = None,
    batch_result: Optional[BatchAnalysisResult] = None,
    run_result: Optional[AnalysisRunResult] = None,
) -> AnalysisValidationTarget:
    """Resolve all available validation objects into one immutable target."""

    result = analysis_result
    if isinstance(result, PoseAnalysisResult) and pose_result is None:
        pose_result = result
    elif isinstance(result, MultiPoseAnalysisResult) and multipose_result is None:
        multipose_result = result
    elif isinstance(result, BatchAnalysisResult) and batch_result is None:
        batch_result = result
    elif isinstance(result, AnalysisRunResult) and run_result is None:
        run_result = result
    if run_result is not None:
        pose_result = pose_result or run_result.pose_result
        multipose_result = multipose_result or run_result.multipose_result
        batch_result = batch_result or run_result.batch_result
        request = request or run_result.request
        context = context or run_result.context
    config_value = coerce_analysis_config(config or (context.config if context else None))
    request = request or (context.request if context else None)
    stage_results: Mapping[str, AnalysisStageResult] = {}
    for candidate in (pose_result, multipose_result, run_result):
        if candidate is not None and getattr(candidate, "stage_results", None):
            stage_results = candidate.stage_results
            break
    if not stage_results and context is not None:
        stage_results = {
            stage: value
            for stage, value in context.stage_data.items()
            if isinstance(value, AnalysisStageResult)
        }
    return AnalysisValidationTarget(
        context=context,
        config=config_value,
        request=request,
        resolved_input=resolved_input,
        preparation=preparation,
        execution_plan=execution_plan or plan,
        stage_results=MappingProxyType(dict(stage_results)),
        pose_result=pose_result,
        multipose_result=multipose_result,
        batch_result=batch_result,
        run_result=run_result,
        result=result,
    )


# 27.7. Finding helpers
# -----------------------------------------------------------------------------


def _validation_add_messages(
    report: AnalysisValidationReport,
    messages: Iterable[Any],
    *,
    phase: str,
    category: str,
    severity: Union[IssueSeverity, str, int] = IssueSeverity.ERROR,
    stage: Optional[str] = None,
    code: str = "validation_issue",
    source: Optional[str] = None,
    recoverable: bool = True,
) -> None:
    """Append normalized validator messages to a report."""

    for index, message in enumerate(messages):
        report.add(
            f"{code}_{index + 1}",
            str(message),
            phase=phase,
            category=category,
            severity=severity,
            stage=stage,
            source=source,
            recoverable=recoverable,
        )


def _validation_result_has_useful_content(value: Any) -> bool:
    """Return whether a result contains a meaningful payload."""

    if value is None:
        return False
    if isinstance(value, PoseAnalysisResult):
        return bool(value.stage_results or value.interaction_count or value.scoring)
    if isinstance(value, MultiPoseAnalysisResult):
        return bool(value.pose_results)
    if isinstance(value, BatchAnalysisResult):
        return bool(value.items)
    if isinstance(value, AnalysisRunResult):
        return value.result is not None or bool(value.stage_results)
    if isinstance(value, Mapping):
        return bool(value)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return bool(value)
    return True


def _validation_iter_file_values(value: Any, prefix: str = "files") -> Iterator[Tuple[str, Any]]:
    """Yield nested file values with stable dotted paths."""

    if isinstance(value, Mapping):
        for key, item in value.items():
            path = f"{prefix}.{key}"
            if isinstance(item, Mapping):
                yield from _validation_iter_file_values(item, path)
            elif isinstance(item, Sequence) and not isinstance(item, (str, bytes, bytearray, Path)):
                for index, nested in enumerate(item):
                    yield from _validation_iter_file_values(nested, f"{path}[{index}]")
            else:
                yield path, item
    elif isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray, Path)):
        for index, item in enumerate(value):
            yield from _validation_iter_file_values(item, f"{prefix}[{index}]")
    else:
        yield prefix, value


# 27.8. Built-in phase validators
# -----------------------------------------------------------------------------


def validate_analysis_configuration_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate integrated configuration and stage-level controls."""

    if not report.policy.validate_configuration:
        return
    issues = validate_analysis_config(target.config, raise_on_error=False)
    _validation_add_messages(
        report,
        issues,
        phase=VALIDATION_PHASE_CONFIGURATION,
        category=VALIDATION_CATEGORY_CONFIGURATION,
        code="configuration",
        source="validate_analysis_config",
        recoverable=False,
    )
    report.mark_check(VALIDATION_PHASE_CONFIGURATION)


def validate_analysis_input_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate request and resolved-input structures."""

    if not report.policy.validate_input:
        return
    if target.request is None:
        report.add(
            "missing_analysis_request",
            "No AnalysisRequest is available for validation.",
            phase=VALIDATION_PHASE_INPUT,
            category=VALIDATION_CATEGORY_STRUCTURE,
            severity=IssueSeverity.WARNING,
            recoverable=True,
        )
    else:
        _validation_add_messages(
            report,
            validate_core_result(target.request, raise_on_error=False),
            phase=VALIDATION_PHASE_INPUT,
            category=VALIDATION_CATEGORY_STRUCTURE,
            code="request",
            source="validate_core_result",
        )
    if target.resolved_input is not None:
        try:
            details = validate_resolved_analysis_input(
                target.resolved_input,
                strict=False,
            )
            if isinstance(details, Mapping):
                _validation_add_messages(
                    report,
                    details.get("errors", ()),
                    phase=VALIDATION_PHASE_INPUT,
                    category=VALIDATION_CATEGORY_CONTENT,
                    code="resolved_input",
                    source="validate_resolved_analysis_input",
                )
                _validation_add_messages(
                    report,
                    details.get("warnings", ()),
                    phase=VALIDATION_PHASE_INPUT,
                    category=VALIDATION_CATEGORY_CONTENT,
                    severity=IssueSeverity.WARNING,
                    code="resolved_input_warning",
                    source="validate_resolved_analysis_input",
                )
            else:
                _validation_add_messages(
                    report,
                    details or (),
                    phase=VALIDATION_PHASE_INPUT,
                    category=VALIDATION_CATEGORY_CONTENT,
                    code="resolved_input",
                    source="validate_resolved_analysis_input",
                )
        except Exception as exc:
            report.add(
                "resolved_input_validation_exception",
                str(exc),
                phase=VALIDATION_PHASE_INPUT,
                category=VALIDATION_CATEGORY_CONTENT,
                recoverable=False,
                details={"exception_type": type(exc).__name__},
            )
    report.mark_check(VALIDATION_PHASE_INPUT)


def validate_analysis_preparation_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate model preparation output when available."""

    if not report.policy.validate_preparation or target.preparation is None:
        return
    details = validate_model_preparation_result(target.preparation, strict=False)
    if isinstance(details, Mapping):
        _validation_add_messages(
            report,
            details.get("errors", ()),
            phase=VALIDATION_PHASE_PREPARATION,
            category=VALIDATION_CATEGORY_CONTENT,
            code="preparation",
            source="validate_model_preparation_result",
            recoverable=False,
        )
        _validation_add_messages(
            report,
            details.get("warnings", ()),
            phase=VALIDATION_PHASE_PREPARATION,
            category=VALIDATION_CATEGORY_CONTENT,
            severity=IssueSeverity.WARNING,
            code="preparation_warning",
            source="validate_model_preparation_result",
        )
    else:
        _validation_add_messages(
            report,
            details or (),
            phase=VALIDATION_PHASE_PREPARATION,
            category=VALIDATION_CATEGORY_CONTENT,
            code="preparation",
            source="validate_model_preparation_result",
        )
    report.mark_check(VALIDATION_PHASE_PREPARATION)


def validate_analysis_plan_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate the execution plan and registered dependencies."""

    if not report.policy.validate_plan or target.execution_plan is None:
        return
    issues = validate_analysis_execution_plan(
        target.execution_plan,
        raise_on_error=False,
    )
    _validation_add_messages(
        report,
        issues,
        phase=VALIDATION_PHASE_PLAN,
        category=VALIDATION_CATEGORY_DEPENDENCY,
        code="execution_plan",
        source="validate_analysis_execution_plan",
        recoverable=False,
    )
    report.mark_check(VALIDATION_PHASE_PLAN)


def validate_analysis_stage_result(
    value: Any,
    *,
    policy: Optional[AnalysisValidationPolicy] = None,
    registry: Optional[AnalysisStageRegistry] = None,
) -> Tuple[AnalysisValidationFinding, ...]:
    """Validate one stage result and its optional registered validator."""

    resolved_policy = policy or AnalysisValidationPolicy()
    findings: List[AnalysisValidationFinding] = []
    if not isinstance(value, AnalysisStageResult):
        return (
            AnalysisValidationFinding(
                code="invalid_stage_result_type",
                message="Stage result must be AnalysisStageResult.",
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_STRUCTURE,
                recoverable=False,
            ),
        )
    if resolved_policy.require_terminal_results and not value.is_terminal:
        findings.append(
            AnalysisValidationFinding(
                code="nonterminal_stage_result",
                message=f"Stage {value.stage!r} has not reached a terminal status.",
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_STATE,
                stage=value.stage,
                recoverable=False,
            )
        )
    if value.required and value.status in STAGE_FAILURE_STATUSES:
        severity = (
            IssueSeverity.ERROR
            if resolved_policy.required_failures_are_errors
            else IssueSeverity.WARNING
        )
        findings.append(
            AnalysisValidationFinding(
                code="required_stage_failure",
                message=(
                    f"Required stage {value.stage!r} ended with status "
                    f"{value.status.value!r}."
                ),
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_STATE,
                severity=severity,
                stage=value.stage,
                recoverable=False,
            )
        )
    elif not value.required and value.status in STAGE_FAILURE_STATUSES:
        severity = (
            IssueSeverity.WARNING
            if resolved_policy.optional_failures_are_warnings
            else IssueSeverity.ERROR
        )
        findings.append(
            AnalysisValidationFinding(
                code="optional_stage_failure",
                message=(
                    f"Optional stage {value.stage!r} ended with status "
                    f"{value.status.value!r}."
                ),
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_STATE,
                severity=severity,
                stage=value.stage,
                recoverable=True,
            )
        )
    if value.status in STAGE_SUCCESS_STATUSES and value.value is None:
        findings.append(
            AnalysisValidationFinding(
                code="successful_stage_without_value",
                message=f"Stage {value.stage!r} succeeded without a result value.",
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_CONTENT,
                severity=IssueSeverity.WARNING,
                stage=value.stage,
                recoverable=True,
            )
        )
    if value.duration_seconds is not None and value.duration_seconds < 0:
        findings.append(
            AnalysisValidationFinding(
                code="negative_stage_duration",
                message=f"Stage {value.stage!r} has a negative duration.",
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_CONSISTENCY,
                stage=value.stage,
                recoverable=False,
            )
        )
    try:
        definition = get_analysis_stage_definition(
            value.stage,
            registry=registry,
        )
    except Exception:
        definition = None
    if definition is not None and definition.validator is not None and value.value is not None:
        try:
            kwargs = _filter_callable_keyword_arguments(
                definition.validator,
                {
                    "value": value.value,
                    "result": value.value,
                    "stage_result": value,
                    "raise_on_error": False,
                },
            )
            native = definition.validator(**kwargs)
            if native is None or native is True:
                native_messages: Tuple[Any, ...] = ()
            elif native is False:
                native_messages = ("The registered stage validator rejected the result.",)
            elif isinstance(native, Mapping):
                native_messages = tuple(native.get("errors", ()))
            elif isinstance(native, str):
                native_messages = (native,)
            else:
                native_messages = tuple(native)
            for index, message in enumerate(native_messages):
                findings.append(
                    AnalysisValidationFinding(
                        code=f"native_stage_validation_{index + 1}",
                        message=str(message),
                        phase=VALIDATION_PHASE_STAGE_RESULTS,
                        category=VALIDATION_CATEGORY_CONTENT,
                        severity=IssueSeverity.WARNING,
                        stage=value.stage,
                        recoverable=True,
                        source=_callable_identity(definition.validator),
                    )
                )
        except Exception as exc:
            findings.append(
                AnalysisValidationFinding(
                    code="native_stage_validator_exception",
                    message=(
                        f"Registered validator for stage {value.stage!r} raised: {exc}"
                    ),
                    phase=VALIDATION_PHASE_STAGE_RESULTS,
                    category=VALIDATION_CATEGORY_CONTENT,
                    stage=value.stage,
                    recoverable=False,
                    details={"exception_type": type(exc).__name__},
                )
            )
    return tuple(findings)


def validate_analysis_stage_results_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate every accumulated stage result."""

    if not report.policy.validate_stage_results:
        return
    for stage, stage_result in target.stage_results.items():
        if stage_result.stage != stage:
            report.add(
                "stage_result_key_mismatch",
                f"Stage-result key {stage!r} does not match {stage_result.stage!r}.",
                phase=VALIDATION_PHASE_STAGE_RESULTS,
                category=VALIDATION_CATEGORY_CONSISTENCY,
                stage=stage,
                recoverable=False,
            )
        for finding in validate_analysis_stage_result(stage_result, policy=report.policy):
            report.add_finding(finding)
        report.mark_check(VALIDATION_PHASE_STAGE_RESULTS)


def validate_analysis_interactions_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate consolidated interaction structures."""

    if not report.policy.validate_interactions:
        return
    pose_results: List[PoseAnalysisResult] = []
    if target.pose_result is not None:
        pose_results.append(target.pose_result)
    if target.multipose_result is not None:
        pose_results.extend(target.multipose_result.pose_results)
    for index, pose_result in enumerate(pose_results):
        bundle = pose_result.interactions
        issues = validate_core_result(bundle, raise_on_error=False)
        _validation_add_messages(
            report,
            issues,
            phase=VALIDATION_PHASE_INTERACTIONS,
            category=VALIDATION_CATEGORY_STRUCTURE,
            code=f"interaction_bundle_{index + 1}",
            source="validate_core_result",
        )
        if report.policy.require_nonempty_results and bundle.total_interactions == 0:
            report.add(
                "empty_interaction_bundle",
                f"Pose {pose_result.pose_id!r} contains no accepted interactions.",
                phase=VALIDATION_PHASE_INTERACTIONS,
                category=VALIDATION_CATEGORY_CONTENT,
                severity=IssueSeverity.WARNING,
                path=f"pose_results[{index}].interactions",
                recoverable=True,
            )
        report.mark_check(VALIDATION_PHASE_INTERACTIONS)


def validate_analysis_scoring_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate scoring payloads when present."""

    if not report.policy.validate_scoring:
        return
    pose_results: List[PoseAnalysisResult] = []
    if target.pose_result is not None:
        pose_results.append(target.pose_result)
    if target.multipose_result is not None:
        pose_results.extend(target.multipose_result.pose_results)
    for index, pose_result in enumerate(pose_results):
        scoring_value = pose_result.scoring
        stage_result = pose_result.get_stage_result(STAGE_SCORING)
        if stage_result is not None and stage_result.status in STAGE_SUCCESS_STATUSES:
            if scoring_value is None:
                report.add(
                    "missing_scoring_payload",
                    f"Scoring succeeded for pose {pose_result.pose_id!r} without a payload.",
                    phase=VALIDATION_PHASE_SCORING,
                    category=VALIDATION_CATEGORY_CONSISTENCY,
                    stage=STAGE_SCORING,
                    path=f"pose_results[{index}].scoring",
                    recoverable=True,
                )
            else:
                if isinstance(scoring_value, ScoringStageOutput):
                    issues = validate_scoring_stage_output(scoring_value)
                    source_name = "validate_scoring_stage_output"
                elif is_scoring_integration_result(scoring_value):
                    issues = validate_scoring_native_result(scoring_value)
                    source_name = "validate_scoring_native_result"
                else:
                    issues = ()
                    final_score = get_object_value(
                        scoring_value,
                        "final_score",
                        default=None,
                    )
                    if final_score is not None:
                        try:
                            numeric_score = float(final_score)
                            if not math.isfinite(numeric_score):
                                issues = ("Scoring payload has a non-finite final score.",)
                        except (TypeError, ValueError, OverflowError):
                            issues = ("Scoring payload has a non-numeric final score.",)
                    source_name = "generic_scoring_validation"
                _validation_add_messages(
                    report,
                    issues,
                    phase=VALIDATION_PHASE_SCORING,
                    category=VALIDATION_CATEGORY_CONTENT,
                    stage=STAGE_SCORING,
                    code=f"scoring_{index + 1}",
                    source=source_name,
                )
        report.mark_check(VALIDATION_PHASE_SCORING)


def validate_analysis_multipose_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate multipose aggregation, ranking and identifiers."""

    value = target.multipose_result
    if value is None:
        return
    if value.pose_count == 0:
        report.add(
            "empty_multipose_result",
            "Multipose analysis contains no pose results.",
            phase=VALIDATION_PHASE_MULTIPOSE,
            category=VALIDATION_CATEGORY_CONTENT,
            recoverable=False,
        )
    identifiers = [item.pose_id for item in value.pose_results]
    if len(identifiers) != len(set(identifiers)):
        report.add(
            "duplicate_multipose_pose_ids",
            "Multipose pose identifiers must be unique.",
            phase=VALIDATION_PHASE_MULTIPOSE,
            category=VALIDATION_CATEGORY_CONSISTENCY,
            recoverable=False,
        )
    ranked_ids: List[str] = []
    for entry in value.ranking:
        candidate = get_object_value(entry, "pose_id", None)
        if candidate is None and isinstance(entry, Mapping):
            candidate = entry.get("id") or entry.get("name")
        if candidate is not None:
            ranked_ids.append(str(candidate))
    unknown_ranked = set(ranked_ids).difference(identifiers)
    if unknown_ranked:
        report.add(
            "unknown_ranked_pose_ids",
            f"Ranking references unknown poses: {sorted(unknown_ranked)!r}.",
            phase=VALIDATION_PHASE_MULTIPOSE,
            category=VALIDATION_CATEGORY_CONSISTENCY,
            recoverable=True,
        )
    for index, pose_result in enumerate(value.pose_results):
        _validation_add_messages(
            report,
            validate_core_result(pose_result, raise_on_error=False),
            phase=VALIDATION_PHASE_MULTIPOSE,
            category=VALIDATION_CATEGORY_STRUCTURE,
            code=f"multipose_pose_{index + 1}",
            source="validate_core_result",
        )
    report.mark_check(VALIDATION_PHASE_MULTIPOSE, max(1, value.pose_count))


def validate_analysis_batch_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate batch items, order and item-level results."""

    value = target.batch_result
    if value is None:
        return
    if not value.items:
        report.add(
            "empty_batch_result",
            "Batch analysis contains no items.",
            phase=VALIDATION_PHASE_BATCH,
            category=VALIDATION_CATEGORY_CONTENT,
            recoverable=False,
        )
    identifiers = [item.item_id for item in value.items]
    if len(identifiers) != len(set(identifiers)):
        report.add(
            "duplicate_batch_item_ids",
            "Batch item identifiers must be unique.",
            phase=VALIDATION_PHASE_BATCH,
            category=VALIDATION_CATEGORY_CONSISTENCY,
            recoverable=False,
        )
    for index, item in enumerate(value.items):
        if item.result is None and item.status in ANALYSIS_SUCCESS_STATUSES:
            report.add(
                "successful_batch_item_without_result",
                f"Batch item {item.item_id!r} succeeded without a result.",
                phase=VALIDATION_PHASE_BATCH,
                category=VALIDATION_CATEGORY_CONTENT,
                path=f"items[{index}].result",
                recoverable=True,
            )
    report.mark_check(VALIDATION_PHASE_BATCH, max(1, len(value.items)))


def validate_analysis_outputs_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate report, export and visualization stage outputs."""

    if not report.policy.validate_outputs:
        return
    validator_map: Mapping[str, Callable[[Any], Tuple[str, ...]]] = {
        STAGE_REPORT: validate_report_stage_output,
        STAGE_EXPORT: validate_export_stage_output,
        STAGE_VISUALIZATION: validate_visualization_stage_output,
    }
    for stage, validator in validator_map.items():
        stage_result = target.stage_results.get(stage)
        if stage_result is None or stage_result.value is None:
            continue
        try:
            issues = validator(stage_result.value)
        except Exception as exc:
            issues = (f"Output validator raised {type(exc).__name__}: {exc}",)
        _validation_add_messages(
            report,
            issues,
            phase=VALIDATION_PHASE_OUTPUTS,
            category=VALIDATION_CATEGORY_CONTENT,
            stage=stage,
            code=f"{stage}_output",
            source=_callable_identity(validator),
        )
        report.mark_check(VALIDATION_PHASE_OUTPUTS)


def validate_analysis_files_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate paths referenced by integrated results."""

    if not report.policy.validate_files:
        return
    file_mappings: List[Tuple[str, Any]] = []
    for label, value in (
        ("pose", target.pose_result),
        ("multipose", target.multipose_result),
        ("batch", target.batch_result),
        ("run", target.run_result),
    ):
        if value is not None and getattr(value, "files", None):
            file_mappings.append((label, value.files))
    for label, mapping in file_mappings:
        for path, raw_value in _validation_iter_file_values(mapping, label):
            if raw_value is None or isinstance(raw_value, bool):
                continue
            candidate = raw_value
            if isinstance(raw_value, Mapping):
                candidate = raw_value.get("path") or raw_value.get("file")
            if candidate is None:
                continue
            try:
                file_path = Path(os.fspath(candidate)).expanduser()
            except (TypeError, ValueError):
                report.add(
                    "invalid_file_reference",
                    f"Invalid file reference at {path!r}.",
                    phase=VALIDATION_PHASE_FILES,
                    category=VALIDATION_CATEGORY_FILE,
                    path=path,
                    recoverable=True,
                )
                continue
            if report.policy.require_existing_files and not file_path.exists():
                report.add(
                    "missing_output_file",
                    f"Referenced output file does not exist: {file_path}.",
                    phase=VALIDATION_PHASE_FILES,
                    category=VALIDATION_CATEGORY_FILE,
                    path=path,
                    recoverable=True,
                )
            report.mark_check(VALIDATION_PHASE_FILES)


def validate_analysis_serialization_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate conversion of the integrated result to JSON."""

    if not report.policy.validate_serialization:
        return
    value = target.primary_result
    if value is None:
        return
    try:
        payload = json.dumps(
            to_json_compatible(value),
            ensure_ascii=False,
            sort_keys=True,
        )
        if len(payload) > report.policy.max_serialized_characters:
            report.add(
                "serialized_result_too_large",
                "Serialized validation target exceeds the configured character limit.",
                phase=VALIDATION_PHASE_SERIALIZATION,
                category=VALIDATION_CATEGORY_SERIALIZATION,
                severity=IssueSeverity.WARNING,
                recoverable=True,
                details={
                    "characters": len(payload),
                    "limit": report.policy.max_serialized_characters,
                },
            )
    except Exception as exc:
        report.add(
            "result_serialization_failed",
            f"Analysis result is not JSON serializable: {exc}",
            phase=VALIDATION_PHASE_SERIALIZATION,
            category=VALIDATION_CATEGORY_SERIALIZATION,
            recoverable=False,
            details={"exception_type": type(exc).__name__},
        )
    report.mark_check(VALIDATION_PHASE_SERIALIZATION)


def validate_analysis_final_result_phase(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Validate final result status and cross-container consistency."""

    value = target.primary_result
    if value is None:
        report.add(
            "missing_final_result",
            "No final analysis result is available.",
            phase=VALIDATION_PHASE_FINAL_RESULT,
            category=VALIDATION_CATEGORY_STRUCTURE,
            recoverable=False,
        )
        report.mark_check(VALIDATION_PHASE_FINAL_RESULT)
        return
    _validation_add_messages(
        report,
        validate_core_result(value, raise_on_error=False),
        phase=VALIDATION_PHASE_FINAL_RESULT,
        category=VALIDATION_CATEGORY_STRUCTURE,
        code="final_result",
        source="validate_core_result",
    )
    if isinstance(value, PoseAnalysisResult):
        for field_name, label in (
            ("dock_model", "DockModel"),
            ("receptor", "receptor"),
            ("pose", "pose"),
        ):
            if getattr(value, field_name, None) is None:
                report.add(
                    f"missing_pose_{field_name}",
                    f"Pose analysis result has no {label}.",
                    phase=VALIDATION_PHASE_FINAL_RESULT,
                    category=VALIDATION_CATEGORY_STRUCTURE,
                    path=field_name,
                    recoverable=True,
                )
    if report.policy.require_nonempty_results and not _validation_result_has_useful_content(value):
        report.add(
            "empty_final_result",
            "The final result contains no useful analysis content.",
            phase=VALIDATION_PHASE_FINAL_RESULT,
            category=VALIDATION_CATEGORY_CONTENT,
            recoverable=False,
        )
    status = get_object_value(value, "status", None)
    if status is not None:
        try:
            canonical = canonicalize_analysis_status(status)
            if report.policy.require_terminal_results and canonical not in ANALYSIS_TERMINAL_STATUSES:
                report.add(
                    "nonterminal_final_result",
                    f"Final result has nonterminal status {canonical.value!r}.",
                    phase=VALIDATION_PHASE_FINAL_RESULT,
                    category=VALIDATION_CATEGORY_STATE,
                    recoverable=False,
                )
        except Exception as exc:
            report.add(
                "invalid_final_status",
                f"Final result status is invalid: {exc}",
                phase=VALIDATION_PHASE_FINAL_RESULT,
                category=VALIDATION_CATEGORY_STATE,
                recoverable=False,
            )
    if target.run_result is not None:
        run = target.run_result
        nested = run.pose_result or run.multipose_result or run.batch_result
        if run.result is not None and nested is not None and run.result is not nested:
            report.add(
                "run_result_reference_mismatch",
                "AnalysisRunResult.result does not reference its specific result container.",
                phase=VALIDATION_PHASE_FINAL_RESULT,
                category=VALIDATION_CATEGORY_CONSISTENCY,
                severity=IssueSeverity.WARNING,
                recoverable=True,
            )
    report.mark_check(VALIDATION_PHASE_FINAL_RESULT)


_BUILTIN_VALIDATION_PHASE_FUNCTIONS: Final[Mapping[str, ValidationCallable]] = MappingProxyType(
    {
        VALIDATION_PHASE_CONFIGURATION: validate_analysis_configuration_phase,
        VALIDATION_PHASE_INPUT: validate_analysis_input_phase,
        VALIDATION_PHASE_PREPARATION: validate_analysis_preparation_phase,
        VALIDATION_PHASE_PLAN: validate_analysis_plan_phase,
        VALIDATION_PHASE_STAGE_RESULTS: validate_analysis_stage_results_phase,
        VALIDATION_PHASE_INTERACTIONS: validate_analysis_interactions_phase,
        VALIDATION_PHASE_SCORING: validate_analysis_scoring_phase,
        VALIDATION_PHASE_MULTIPOSE: validate_analysis_multipose_phase,
        VALIDATION_PHASE_BATCH: validate_analysis_batch_phase,
        VALIDATION_PHASE_OUTPUTS: validate_analysis_outputs_phase,
        VALIDATION_PHASE_FILES: validate_analysis_files_phase,
        VALIDATION_PHASE_SERIALIZATION: validate_analysis_serialization_phase,
        VALIDATION_PHASE_FINAL_RESULT: validate_analysis_final_result_phase,
    }
)


# 27.9. Integrated validation execution
# -----------------------------------------------------------------------------


def _invoke_registered_analysis_validator(
    definition: AnalysisValidatorDefinition,
    *,
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> None:
    """Invoke one registered validator and normalize its output."""

    kwargs = _filter_callable_keyword_arguments(
        definition.validator,
        {
            "target": target,
            "report": report,
            "context": target.context,
            "config": target.config,
            "request": target.request,
            "resolved_input": target.resolved_input,
            "preparation": target.preparation,
            "execution_plan": target.execution_plan,
            "stage_results": target.stage_results,
            "pose_result": target.pose_result,
            "multipose_result": target.multipose_result,
            "batch_result": target.batch_result,
            "run_result": target.run_result,
            "result": target.primary_result,
            "policy": report.policy,
        },
    )
    returned = definition.validator(**kwargs)
    if returned is None or returned is True:
        return
    if returned is False:
        returned = ("The validator rejected the target.",)
    if isinstance(returned, (AnalysisValidationFinding, AnalysisIssue, str, BaseException, Mapping)):
        returned = (returned,)
    for value in returned:
        report.add_finding(
            validation_finding_from_value(
                value,
                phase=definition.phase,
                category=VALIDATION_CATEGORY_CONTENT,
                source=definition.name,
                severity=(
                    IssueSeverity.WARNING if definition.optional else IssueSeverity.ERROR
                ),
            )
        )


def run_integrated_analysis_validation(
    target: Optional[AnalysisValidationTarget] = None,
    *,
    policy: AnalysisValidationPolicyLike = None,
    context: Optional[AnalysisContext] = None,
    config: Optional[AnalysisConfigLike] = None,
    request: Optional[AnalysisRequest] = None,
    resolved_input: Optional[ResolvedAnalysisInput] = None,
    preparation: Optional[ModelPreparationResult] = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    plan: Optional[AnalysisExecutionPlan] = None,
    analysis_result: Any = None,
    pose_result: Optional[PoseAnalysisResult] = None,
    multipose_result: Optional[MultiPoseAnalysisResult] = None,
    batch_result: Optional[BatchAnalysisResult] = None,
    run_result: Optional[AnalysisRunResult] = None,
    registry: Optional[AnalysisValidatorRegistry] = None,
    raise_on_error: bool = False,
) -> AnalysisValidationReport:
    """Run built-in and registered validators for one analysis scope."""

    resolved_target = target or resolve_analysis_validation_target(
        context=context,
        config=config,
        request=request,
        resolved_input=resolved_input,
        preparation=preparation,
        execution_plan=execution_plan,
        plan=plan,
        analysis_result=analysis_result,
        pose_result=pose_result,
        multipose_result=multipose_result,
        batch_result=batch_result,
        run_result=run_result,
    )
    resolved_policy = resolve_analysis_validation_policy(
        policy,
        context=resolved_target.context,
        config=resolved_target.config,
    )
    report = AnalysisValidationReport(
        target_type=resolved_target.target_type,
        target_id=resolved_target.target_id,
        policy=resolved_policy,
        metadata={
            "mode": get_object_value(resolved_target.context, "mode", None),
            "stage_result_count": len(resolved_target.stage_results),
        },
    )
    if not resolved_policy.enabled:
        report.disposition = ValidationDisposition.SKIP
        report.finished_at = _utc_timestamp()
        return report
    selected_registry = registry or get_default_validator_registry()
    for phase in resolved_policy.phases:
        builtin = _BUILTIN_VALIDATION_PHASE_FUNCTIONS.get(phase)
        if builtin is not None:
            try:
                builtin(resolved_target, report)
            except Exception as exc:
                report.add(
                    "builtin_validator_exception",
                    f"Built-in {phase!r} validation raised: {exc}",
                    phase=phase,
                    category=VALIDATION_CATEGORY_CONTENT,
                    recoverable=False,
                    details={"exception_type": type(exc).__name__},
                    source=_callable_identity(builtin),
                )
        for definition in selected_registry.definitions(phase):
            try:
                _invoke_registered_analysis_validator(
                    definition,
                    target=resolved_target,
                    report=report,
                )
            except Exception as exc:
                report.add(
                    "registered_validator_exception",
                    f"Validator {definition.name!r} raised: {exc}",
                    phase=phase,
                    category=VALIDATION_CATEGORY_CONTENT,
                    severity=(
                        IssueSeverity.WARNING if definition.optional else IssueSeverity.ERROR
                    ),
                    recoverable=definition.optional,
                    details={"exception_type": type(exc).__name__},
                    source=definition.name,
                )
    report.finalize()
    if resolved_policy.attach_report:
        attach_analysis_validation_report(resolved_target, report)
    if raise_on_error:
        report.raise_for_invalid()
    return report


# 27.10. Report attachment and diagnostics
# -----------------------------------------------------------------------------


def attach_analysis_validation_report(
    target: AnalysisValidationTarget,
    report: AnalysisValidationReport,
) -> int:
    """Attach one validation report to available result containers."""

    attached = 0
    report_data = report.to_dict()
    containers: List[Any] = []
    for value in (
        target.pose_result,
        target.multipose_result,
        target.batch_result,
        target.run_result,
    ):
        if value is not None and all(value is not existing for existing in containers):
            containers.append(value)
    for value in containers:
        metadata = getattr(value, "metadata", None)
        if isinstance(metadata, MutableMapping):
            metadata[VALIDATION_METADATA_KEY] = report_data
            attached += 1
        statistics = getattr(value, "statistics", None)
        if isinstance(statistics, MutableMapping):
            statistics[VALIDATION_STATISTICS_KEY] = report.summary()
        diagnostics = getattr(value, "diagnostics", None)
        if isinstance(diagnostics, AnalysisDiagnostics):
            for finding in report.findings:
                diagnostics.add_issue(finding.to_issue())
    if target.context is not None:
        target.context.set_shared(VALIDATION_SHARED_REPORT_KEY, report)
        target.context.set_stage_data(VALIDATION_STAGE_DATA_KEY, report)
    return attached


def validation_report_to_diagnostics(
    report: AnalysisValidationReport,
) -> AnalysisDiagnostics:
    """Convert a validation report to AnalysisDiagnostics."""

    diagnostics = AnalysisDiagnostics()
    for finding in report.findings:
        diagnostics.add_issue(finding.to_issue())
    diagnostics.metadata[VALIDATION_METADATA_KEY] = report.summary()
    return diagnostics


def validation_report_to_json(
    report: AnalysisValidationReport,
    *,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
) -> str:
    """Serialize a validation report to JSON."""

    return json.dumps(
        report.to_dict(),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


def summarize_analysis_validation(
    value: Any,
) -> Dict[str, Any]:
    """Return a concise validation summary."""

    if isinstance(value, AnalysisValidationReport):
        return value.summary()
    if isinstance(value, AnalysisStageResult):
        report = value.value if isinstance(value.value, AnalysisValidationReport) else None
        return {
            "stage": value.stage,
            "status": value.status.value,
            "valid": report.valid if report else value.succeeded,
            "report": report.summary() if report else None,
        }
    raise TypeError("Expected AnalysisValidationReport or AnalysisStageResult.")


# 27.11. Strict, permissive, partial and skip decisions
# -----------------------------------------------------------------------------


def validation_disposition_for_policy(
    report: AnalysisValidationReport,
    policy: AnalysisValidationPolicyLike = None,
) -> ValidationDisposition:
    """Return the disposition selected for a report under one policy."""

    resolved = resolve_analysis_validation_policy(policy or report.policy)
    clone = AnalysisValidationReport(
        target_type=report.target_type,
        target_id=report.target_id,
        policy=resolved,
        findings=list(report.findings),
        checks=dict(report.checks),
        metadata=dict(report.metadata),
    )
    clone.finalize()
    return clone.disposition


def apply_validation_policy_to_stage_result(
    stage_result: AnalysisStageResult,
    report: AnalysisValidationReport,
) -> AnalysisStageResult:
    """Finalize a validation-stage result according to report disposition."""

    stage_result.statistics = report.summary()
    stage_result.output_summary = report.summary()
    stage_result.metadata[VALIDATION_METADATA_KEY] = report.to_dict()
    stage_result.diagnostics.extend(validation_report_to_diagnostics(report))
    if report.disposition is ValidationDisposition.ACCEPT:
        return stage_result.succeed(
            report,
            message="Integrated analysis validation succeeded.",
        )
    if report.disposition is ValidationDisposition.SKIP:
        stage_result.value = report
        return stage_result.skip(
            "Validation findings were skipped by policy."
        )
    if report.disposition is ValidationDisposition.ACCEPT_PARTIAL:
        issue = AnalysisPartialResultWarning(
            "Integrated validation accepted a partial result.",
            stage=STAGE_VALIDATION,
            details=report.summary(),
        )
        return stage_result.partial(
            report,
            issue=issue,
            message="Integrated validation completed with accepted findings.",
        )
    error = AnalysisValidationError(
        "Integrated validation rejected the analysis result.",
        stage=STAGE_VALIDATION,
        details=report.to_dict(),
    )
    return stage_result.fail(error)


# 27.12. Validation-stage execution and orchestration overrides
# -----------------------------------------------------------------------------


def execute_analysis_validation_stage(
    context: AnalysisContext,
    *,
    analysis_result: Any = None,
    pose_result: Optional[PoseAnalysisResult] = None,
    multipose_result: Optional[MultiPoseAnalysisResult] = None,
    batch_result: Optional[BatchAnalysisResult] = None,
    run_result: Optional[AnalysisRunResult] = None,
    preparation: Optional[ModelPreparationResult] = None,
    resolved_input: Optional[ResolvedAnalysisInput] = None,
    execution_plan: Optional[AnalysisExecutionPlan] = None,
    plan: Optional[AnalysisExecutionPlan] = None,
    policy: AnalysisValidationPolicyLike = None,
    overrides: Optional[Mapping[str, Any]] = None,
    raise_on_error: bool = False,
) -> AnalysisStageResult:
    """Execute integrated validation as the canonical validation stage."""

    stage_result = AnalysisStageResult(stage=STAGE_VALIDATION, required=True)
    stage_result.start()
    try:
        context.raise_if_cancelled(stage=STAGE_VALIDATION)
        context.set_current_stage(STAGE_VALIDATION)
        resolved_policy = resolve_analysis_validation_policy(
            policy,
            context=context,
            overrides=overrides,
        )
        report = run_integrated_analysis_validation(
            policy=resolved_policy,
            context=context,
            resolved_input=resolved_input,
            preparation=preparation,
            execution_plan=execution_plan,
            plan=plan,
            analysis_result=analysis_result,
            pose_result=pose_result,
            multipose_result=multipose_result,
            batch_result=batch_result,
            run_result=run_result,
            raise_on_error=False,
        )
        apply_validation_policy_to_stage_result(stage_result, report)
        context.set_stage_data(STAGE_VALIDATION, stage_result)
        context.set_shared(VALIDATION_SHARED_REPORT_KEY, report)
        context.notify_stage(stage_result)
        if raise_on_error and not report.accepted:
            report.raise_for_invalid()
    except Exception as exc:
        wrapped = exc
        if not isinstance(exc, AnalysisError):
            wrapped = AnalysisValidationError(
                "Integrated validation failed unexpectedly.",
                stage=STAGE_VALIDATION,
                cause=exc,
            )
        stage_result.fail(
            wrapped,
            include_traceback=context.config.runtime.collect_diagnostics,
        )
        context.set_stage_data(STAGE_VALIDATION, stage_result)
        if raise_on_error:
            raise wrapped
    finally:
        context.set_current_stage(None)
    return stage_result


def execute_single_pose_validation_stage(
    context: AnalysisContext,
    pose_result: PoseAnalysisResult,
    *,
    preparation: Optional[ModelPreparationResult] = None,
) -> AnalysisStageResult:
    """Execute the Section 27 validator for one pose pipeline."""

    return execute_analysis_validation_stage(
        context,
        pose_result=pose_result,
        preparation=preparation,
        policy=context.config,
        raise_on_error=False,
    )


def execute_multipose_validation_stage(
    context: AnalysisContext,
    result: MultiPoseAnalysisResult,
    *,
    minimum_successful_poses: int = 1,
) -> AnalysisStageResult:
    """Execute the Section 27 validator for one multipose pipeline."""

    overrides: Dict[str, Any] = {}
    if len(result.successful_pose_results) < max(0, int(minimum_successful_poses)):
        overrides["require_nonempty_results"] = True
    return execute_analysis_validation_stage(
        context,
        multipose_result=result,
        policy=context.config,
        overrides=overrides,
        raise_on_error=False,
    )


def validation_stage_result_adapter(value: Any) -> AnalysisStageResult:
    """Adapt a validation report or compatible mapping to a stage result."""

    if isinstance(value, AnalysisStageResult):
        return value
    result = AnalysisStageResult(stage=STAGE_VALIDATION, required=True)
    result.start()
    if isinstance(value, AnalysisValidationReport):
        return apply_validation_policy_to_stage_result(result, value)
    if isinstance(value, Mapping):
        findings = [
            validation_finding_from_value(item)
            for item in value.get("findings", ())
        ]
        report = AnalysisValidationReport(
            target_type=value.get("target_type", "analysis"),
            target_id=value.get("target_id"),
            findings=findings,
        ).finalize()
        return apply_validation_policy_to_stage_result(result, report)
    raise TypeError("Validation stage result must be a report, mapping or stage result.")


def validation_stage_validator(value: Any) -> Tuple[str, ...]:
    """Validate a validation-stage payload."""

    if isinstance(value, AnalysisStageResult):
        value = value.value
    if not isinstance(value, AnalysisValidationReport):
        return ("Validation stage payload must be AnalysisValidationReport.",)
    issues: List[str] = []
    if not value.completed:
        issues.append("Validation report has not been finalized.")
    if value.disposition not in set(ValidationDisposition):
        issues.append("Validation report has an invalid disposition.")
    if len(value.findings) > value.policy.max_findings:
        issues.append("Validation report exceeds its finding limit.")
    return tuple(issues)


def register_validation_stage_adapter(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> AnalysisStageDefinition:
    """Register the integrated validation executor in the stage registry."""

    target = registry or get_default_stage_registry()
    current = target.require(STAGE_VALIDATION)
    definition = current.with_executor(
        execute_analysis_validation_stage,
        result_adapter=validation_stage_result_adapter,
        validator=validation_stage_validator,
    )
    return target.register(definition, replace_existing=True)


def validation_stage_adapter_registered(
    *,
    registry: Optional[AnalysisStageRegistry] = None,
) -> bool:
    """Return whether the Section 27 validation executor is registered."""

    definition = (registry or get_default_stage_registry()).require(STAGE_VALIDATION)
    return definition.executor is execute_analysis_validation_stage


