# 27.14. Convention validation
# -----------------------------------------------------------------------------


def validate_integrated_validation_conventions() -> Dict[str, Any]:
    """Validate Section 27 types, policies, registry and execution behavior."""

    failures: List[str] = []
    if len(VALIDATION_PHASE_ORDER) != len(set(VALIDATION_PHASE_ORDER)):
        failures.append("Validation phases are not unique.")
    if set(VALIDATION_DISPOSITIONS) != {item.value for item in ValidationDisposition}:
        failures.append("Validation disposition constants are inconsistent.")
    strict_policy = AnalysisValidationPolicy(
        failure_policy=FAILURE_POLICY_STRICT,
        phases=(VALIDATION_PHASE_FINAL_RESULT,),
        validate_files=False,
        validate_serialization=False,
    )
    permissive_policy = replace(
        strict_policy,
        failure_policy=FAILURE_POLICY_PERMISSIVE,
        allow_partial_results=True,
    )
    valid_pose = PoseAnalysisResult(
        pose_id="section27_pose",
        name="section27_pose",
        status=AnalysisStatus.SUCCEEDED,
        dock_model=SimpleNamespace(name="section27_model"),
        receptor=SimpleNamespace(name="section27_receptor"),
        pose=SimpleNamespace(name="section27_pose"),
    )
    valid_report = validate_pose_analysis_result(
        valid_pose,
        policy=strict_policy,
    )
    if not valid_report.accepted:
        failures.append("A structurally valid pose result was rejected.")
    invalid_pose = PoseAnalysisResult(
        pose_id="section27_invalid",
        name="section27_invalid",
        status=AnalysisStatus.SUCCEEDED,
    )
    strict_report = validate_pose_analysis_result(
        invalid_pose,
        policy=strict_policy,
    )
    if strict_report.disposition is not ValidationDisposition.REJECT:
        failures.append("Strict validation did not reject an invalid pose result.")
    permissive_report = validate_pose_analysis_result(
        invalid_pose,
        policy=permissive_policy,
    )
    if permissive_report.disposition is not ValidationDisposition.ACCEPT_PARTIAL:
        failures.append("Permissive validation did not accept a partial result.")
    stage_result = validation_stage_result_adapter(valid_report)
    if stage_result.status is not StageStatus.SUCCEEDED:
        failures.append("Validation report adaptation did not succeed.")
    if validation_stage_validator(stage_result):
        failures.append("Validation-stage payload validator rejected a valid report.")
    if not validation_stage_adapter_registered():
        failures.append("Validation-stage adapter is not registered.")
    payload = validation_report_to_json(valid_report)
    if VALIDATION_SCHEMA_NAME not in payload:
        failures.append("Validation JSON does not include the schema name.")
    if failures:
        raise RuntimeError(
            "Integrated validation convention validation failed: "
            + " ".join(failures)
        )
    return {
        "valid": True,
        "schema": VALIDATION_SCHEMA_NAME,
        "schema_version": VALIDATION_SCHEMA_VERSION,
        "phase_count": len(VALIDATION_PHASE_ORDER),
        "category_count": len(VALIDATION_CATEGORIES),
        "registered_validator_count": len(registered_analysis_validators()),
        "validated_cases": 18,
    }


