def _chimerax_token(value: Any, *, default: str = "") -> str:
    """Return a normalized ChimeraX integration token."""

    raw = getattr(value, "value", value)
    return (
        normalize_text(raw, default=default)
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )


def canonicalize_chimerax_analysis_mode(value: Any) -> str:
    """Return a supported ChimeraX analysis mode."""

    token = _chimerax_token(value, default=CHIMERAX_DEFAULT_MODE)
    canonical = CHIMERAX_ANALYSIS_MODE_ALIASES.get(token, token)
    if canonical not in CHIMERAX_SUPPORTED_ANALYSIS_MODES:
        raise AnalysisConfigurationError(
            f"Unsupported ChimeraX analysis mode: {value!r}.",
            code="unsupported_chimerax_analysis_mode",
            details={"supported": list(CHIMERAX_SUPPORTED_ANALYSIS_MODES)},
        )
    return canonical


def canonicalize_chimerax_message_level(value: Any) -> str:
    """Return a supported ChimeraX message level."""

    token = _chimerax_token(value, default="info")
    canonical = CHIMERAX_MESSAGE_LEVEL_ALIASES.get(token, token)
    if canonical not in CHIMERAX_SUPPORTED_MESSAGE_LEVELS:
        raise AnalysisConfigurationError(
            f"Unsupported ChimeraX message level: {value!r}.",
            code="unsupported_chimerax_message_level",
            details={"supported": list(CHIMERAX_SUPPORTED_MESSAGE_LEVELS)},
        )
    return canonical


def normalize_chimerax_stage_names(value: Any) -> Tuple[str, ...]:
    """Return canonical pipeline stage names from command input."""

    if value is None or value == "":
        return ()
    if isinstance(value, str):
        raw = [item for item in re.split(r"[,;\s]+", value) if item]
    else:
        raw = normalize_object_sequence(value, maximum_items=MAX_PIPELINE_STAGES)
    return canonicalize_stage_sequence(raw, strict=True)


def quote_chimerax_argument(value: Any, *, always: bool = False) -> str:
    """Return one safely quoted ChimeraX command argument."""

    text = str(value)
    if not always and text and re.fullmatch(r"[A-Za-z0-9_#@.:/+\-=]+", text):
        return text
    escaped = text.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def normalize_chimerax_output_path(
    value: Any,
    *,
    default_name: Optional[str] = None,
    suffix: Optional[str] = None,
) -> Optional[Path]:
    """Return a normalized output path for a ChimeraX operation."""

    if value in (None, ""):
        if default_name is None:
            return None
        path = Path(default_name)
    else:
        path = normalize_path(value)
    if suffix:
        normalized_suffix = suffix if str(suffix).startswith(".") else f".{suffix}"
        if path.suffix.lower() != normalized_suffix.lower():
            path = path.with_suffix(normalized_suffix)
    return path


def chimerax_model_atomspec(value: Any) -> Optional[str]:
    """Return a model atom-specifier without importing ChimeraX classes."""

    if value is None:
        return None
    for field_name in ("atomspec", "atom_spec", "specifier"):
        candidate = get_object_value(value, field_name, default=None)
        if candidate:
            text = normalize_text(candidate)
            if text:
                return text if text.startswith("#") else f"#{text}"
    identifier = get_object_value(value, "id_string", default=None)
    if not identifier:
        identifier = get_object_value(value, "id", default=None)
    if identifier is None:
        return None
    if isinstance(identifier, (tuple, list)):
        text = ".".join(str(item) for item in identifier)
    else:
        text = str(identifier).lstrip("#")
    return f"#{text}" if text else None


def chimerax_command_text(command: Any) -> str:
    """Return command text from strings or command-like objects."""

    if isinstance(command, str):
        return command.strip()
    text = get_object_value(command, "text", default=None)
    if text is None:
        text = get_object_value(command, "command", default=None)
    return normalize_text(text if text is not None else command).strip()


# 28.3. Session discovery and backend information
# -----------------------------------------------------------------------------


def resolve_chimerax_session(value: Any = None, *, required: bool = True) -> Any:
    """Resolve an active ChimeraX session without hard backend imports."""

    session_value = value
    if isinstance(session_value, AnalysisContext):
        session_value = session_value.session or session_value.request.session
    elif isinstance(session_value, AnalysisRequest):
        session_value = session_value.session
    if session_value is None:
        session_value = globals().get("session")
    if session_value is None and _chimerax is not None:
        session_value = getattr(_chimerax, "session", None)
    if session_value is None:
        try:
            import builtins

            session_value = getattr(builtins, "session", None)
        except Exception:
            session_value = None
    if session_value is not None and is_session_like(session_value):
        return session_value
    if required:
        raise ChimeraXUnavailableAnalysisError(
            "A usable ChimeraX session could not be resolved.",
            code="chimerax_session_unavailable",
            recoverable=True,
            action=RecoveryAction.SKIP_STAGE,
        )
    return None


def validate_chimerax_session(value: Any) -> Tuple[str, ...]:
    """Return structural issues for a ChimeraX-like session."""

    issues: List[str] = []
    if value is None:
        return ("A ChimeraX session is not available.",)
    if not is_session_like(value):
        issues.append("The object does not expose a ChimeraX-compatible model manager.")
    manager = getattr(value, "models", None)
    if manager is None:
        issues.append("The session does not expose a model manager.")
    elif not (
        callable(getattr(manager, "list", None))
        or callable(getattr(manager, "list_models", None))
        or is_nonstring_iterable(manager)
    ):
        issues.append("The session model manager cannot enumerate open models.")
    logger = getattr(value, "logger", None)
    if logger is not None and not any(
        callable(getattr(logger, name, None))
        for name in ("info", "status", "warning", "error")
    ):
        issues.append("The session logger does not expose standard logging methods.")
    return tuple(issues)


def resolve_chimerax_command_runner(
    value: Any = None,
    *,
    required: bool = True,
) -> Optional[ChimeraXCommandRunner]:
    """Resolve the native ChimeraX command runner."""

    if value is not None:
        if callable(value):
            return value
        if required:
            raise ChimeraXAnalysisError(
                "The ChimeraX command runner must be callable.",
                code="invalid_chimerax_command_runner",
            )
        return None

    visualization_module = load_analysis_module("visualization", required=False)
    resolver = (
        getattr(visualization_module, "resolve_chimerax_runner", None)
        if visualization_module is not None
        else None
    )
    if callable(resolver):
        try:
            runner = resolver(None, required=False)
            if callable(runner):
                return runner
        except Exception:
            pass

    try:
        from chimerax.core.commands import run as runner

        return runner
    except Exception as exc:
        if required:
            raise ChimeraXUnavailableAnalysisError(
                "The ChimeraX command runner is unavailable.",
                code="chimerax_runner_unavailable",
                recoverable=True,
                action=RecoveryAction.SKIP_STAGE,
                cause=exc,
            ) from exc
    return None


@dataclass(frozen=True)
class ChimeraXSessionInfo:
    """Inspection-safe description of a ChimeraX session."""

    available: bool
    backend_state: ChimeraXBackendState
    session_name: Optional[str] = None
    session_type: Optional[str] = None
    model_count: int = 0
    atomic_model_count: int = 0
    has_logger: bool = False
    has_gui: Optional[bool] = None
    chimerax_version: Optional[str] = None
    runner_name: Optional[str] = None
    issues: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict)
    result_type: str = CHIMERAX_SESSION_INFO_RESULT_TYPE

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible representation."""

        return {
            "result_type": self.result_type,
            "available": self.available,
            "backend_state": self.backend_state.value,
            "session_name": self.session_name,
            "session_type": self.session_type,
            "model_count": self.model_count,
            "atomic_model_count": self.atomic_model_count,
            "has_logger": self.has_logger,
            "has_gui": self.has_gui,
            "chimerax_version": self.chimerax_version,
            "runner_name": self.runner_name,
            "issues": list(self.issues),
            "metadata": to_json_compatible(self.metadata),
        }


def inspect_chimerax_session(
    session: Any = None,
    *,
    runner: Any = None,
) -> ChimeraXSessionInfo:
    """Inspect session, model and runner availability."""

    session_value = resolve_chimerax_session(session, required=False)
    runner_value = resolve_chimerax_command_runner(runner, required=False)
    issues = list(validate_chimerax_session(session_value)) if session_value is not None else [
        "A ChimeraX session is not available."
    ]
    models: List[Any] = []
    atomic_models: List[Any] = []
    if session_value is not None:
        try:
            models = get_session_models(session_value, atomic_only=False, strict=False)
            atomic_models = get_session_models(session_value, atomic_only=True, strict=False)
        except Exception as exc:
            issues.append(f"Session models could not be inspected: {exc}")
    if session_value is not None and runner_value is not None and not issues:
        state = ChimeraXBackendState.AVAILABLE
    elif session_value is not None:
        state = ChimeraXBackendState.SESSION_ONLY
    elif runner_value is not None:
        state = ChimeraXBackendState.RUNNER_ONLY
    else:
        state = ChimeraXBackendState.UNAVAILABLE
    session_type = (
        None
        if session_value is None
        else f"{type(session_value).__module__}.{type(session_value).__name__}"
    )
    session_name = None
    if session_value is not None:
        session_name = normalize_text(
            get_object_value(session_value, "name", default=""),
            default="",
        ) or None
    has_gui: Optional[bool] = None
    if session_value is not None:
        ui = getattr(session_value, "ui", None)
        if ui is not None:
            has_gui = bool(getattr(ui, "is_gui", True))
    version = None
    if _chimerax is not None:
        version = normalize_text(getattr(_chimerax, "__version__", "")) or None
    return ChimeraXSessionInfo(
        available=state is ChimeraXBackendState.AVAILABLE,
        backend_state=state,
        session_name=session_name,
        session_type=session_type,
        model_count=len(models),
        atomic_model_count=len(atomic_models),
        has_logger=bool(session_value is not None and getattr(session_value, "logger", None)),
        has_gui=has_gui,
        chimerax_version=version,
        runner_name=(
            None
            if runner_value is None
            else getattr(runner_value, "__qualname__", getattr(runner_value, "__name__", type(runner_value).__name__))
        ),
        issues=tuple(unique_preserving_order(issues)),
        metadata={"chimerax_import_available": CHIMERAX_AVAILABLE},
    )


def chimerax_available(session: Any = None, *, require_runner: bool = True) -> bool:
    """Return whether the requested ChimeraX integration level is available."""

    info = inspect_chimerax_session(session)
    if require_runner:
        return info.backend_state is ChimeraXBackendState.AVAILABLE
    return info.backend_state in {
        ChimeraXBackendState.AVAILABLE,
        ChimeraXBackendState.SESSION_ONLY,
    }


# 28.4. ChimeraX logging and progress reporting
# -----------------------------------------------------------------------------


def resolve_chimerax_logger(session: Any = None) -> Any:
    """Return the session logger when available."""

    session_value = resolve_chimerax_session(session, required=False)
    return getattr(session_value, "logger", None) if session_value is not None else None


def emit_chimerax_message(
    message: Any,
    *,
    session: Any = None,
    level: Any = "info",
    prefix: bool = True,
    fallback_logger: Any = None,
) -> str:
    """Emit one message to the ChimeraX logger with a Python fallback."""

    text = normalize_text(message)
    if prefix and text and not text.startswith(f"{CHIMERAX_LOG_PREFIX}:"):
        text = f"{CHIMERAX_LOG_PREFIX}: {text}"
    level_name = canonicalize_chimerax_message_level(level)
    logger = resolve_chimerax_logger(session)
    sent = False
    if logger is not None:
        method_names = (level_name, "info") if level_name == "status" else (level_name,)
        for method_name in method_names:
            method = getattr(logger, method_name, None)
            if callable(method):
                try:
                    method(text)
                    sent = True
                    break
                except Exception:
                    continue
    fallback = fallback_logger if fallback_logger is not None else _LOGGER
    if not sent and fallback is not None:
        method = getattr(fallback, "warning" if level_name == "status" else level_name, None)
        if not callable(method):
            method = getattr(fallback, "info", None)
        if callable(method):
            try:
                method(text)
            except Exception:
                pass
    return text


@dataclass
class ChimeraXProgressReporter:
    """Progress callback that writes compact updates to a ChimeraX session."""

    session: Any = None
    minimum_interval_seconds: float = 0.1
    include_metadata: bool = False
    prefix: str = CHIMERAX_LOG_PREFIX
    _last_update: float = field(default=0.0, init=False, repr=False)
    _last_stage: Optional[str] = field(default=None, init=False, repr=False)

    def __call__(
        self,
        stage: str,
        completed: int,
        total: int,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        """Emit one bounded progress update."""

        now = time.monotonic()
        if (
            stage == self._last_stage
            and completed < total
            and now - self._last_update < max(0.0, self.minimum_interval_seconds)
        ):
            return
        self._last_update = now
        self._last_stage = stage
        total_value = max(0, int(total))
        completed_value = max(0, min(int(completed), total_value or int(completed)))
        if total_value:
            percent = 100.0 * completed_value / total_value
            text = f"{stage}: {completed_value}/{total_value} ({percent:.1f}%)"
        else:
            text = f"{stage}: {completed_value}"
        if self.include_metadata and metadata:
            compact = ", ".join(
                f"{key}={value}"
                for key, value in list(metadata.items())[:4]
            )
            if compact:
                text = f"{text}; {compact}"
        emit_chimerax_message(
            text,
            session=self.session,
            level="status",
            prefix=False,
        )


def make_chimerax_progress_callback(
    session: Any = None,
    *,
    minimum_interval_seconds: float = 0.1,
    include_metadata: bool = False,
) -> ChimeraXProgressReporter:
    """Create a ChimeraX progress callback."""

    return ChimeraXProgressReporter(
        session=resolve_chimerax_session(session, required=False),
        minimum_interval_seconds=minimum_interval_seconds,
        include_metadata=include_metadata,
    )


# 28.5. Model selection from the active session
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ChimeraXModelSelection:
    """Resolved receptor and poses from one ChimeraX session."""

    session: Any
    models: Tuple[Any, ...]
    receptor: Any
    poses: Tuple[Any, ...]
    ligands: Tuple[Any, ...] = ()
    mode: str = ANALYSIS_MODE_AUTO
    discovery: Optional[ModelDiscoveryResult] = None
    warnings: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict)
    result_type: str = CHIMERAX_MODEL_SELECTION_RESULT_TYPE

    @property
    def pose_count(self) -> int:
        """Return the number of resolved pose models."""

        return len(self.poses)

    @property
    def ready(self) -> bool:
        """Return whether receptor and at least one pose are available."""

        return self.receptor is not None and bool(self.poses)

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return an inspection-safe representation."""

        def encode(value: Any) -> Any:
            if include_objects:
                return value
            return None if value is None else describe_object(value).to_dict()

        return {
            "result_type": self.result_type,
            "session": encode(self.session),
            "models": [encode(item) for item in self.models],
            "receptor": encode(self.receptor),
            "poses": [encode(item) for item in self.poses],
            "ligands": [encode(item) for item in self.ligands],
            "mode": self.mode,
            "pose_count": self.pose_count,
            "ready": self.ready,
            "warnings": list(self.warnings),
            "metadata": to_json_compatible(self.metadata),
            "discovery": (
                self.discovery.to_dict(include_objects=include_objects)
                if self.discovery is not None
                else None
            ),
        }


def _selection_mode(mode: Any, pose_count: int) -> str:
    """Resolve the final single-pose or multipose mode."""

    canonical = canonicalize_chimerax_analysis_mode(mode)
    if canonical == ANALYSIS_MODE_AUTO:
        return (
            ANALYSIS_MODE_SINGLE_POSE
            if pose_count <= 1
            else ANALYSIS_MODE_MULTIPOSE
        )
    if canonical == ANALYSIS_MODE_SINGLE_POSE and pose_count != 1:
        raise AnalysisInputError(
            "Single-pose ChimeraX analysis requires exactly one pose.",
            code="invalid_chimerax_single_pose_count",
            details={"pose_count": pose_count},
        )
    if canonical == ANALYSIS_MODE_MULTIPOSE and pose_count < 2:
        raise AnalysisInputError(
            "Multipose ChimeraX analysis requires at least two poses.",
            code="invalid_chimerax_multipose_count",
            details={"pose_count": pose_count},
        )
    return canonical


def resolve_chimerax_model_selection(
    session: Any = None,
    *,
    models: Any = None,
    receptor: Any = None,
    poses: Any = None,
    mode: Any = ANALYSIS_MODE_AUTO,
    include_unknown_poses: bool = CHIMERAX_DEFAULT_INCLUDE_UNKNOWN_POSES,
    strict: bool = CHIMERAX_DEFAULT_STRICT,
) -> ChimeraXModelSelection:
    """Resolve receptor and docking poses from a ChimeraX session."""

    session_value = resolve_chimerax_session(session, required=strict)
    if models is None:
        model_values = get_session_models(
            session_value,
            atomic_only=True,
            strict=strict,
        )
    else:
        model_values = normalize_model_collection(
            models,
            atomic_only=True,
            maximum=CHIMERAX_MAX_OPEN_MODELS,
        )
    discovery = discover_models(
        model_values,
        receptor=receptor,
        poses=poses,
        session=session_value,
        strict=strict,
        include_unknown_poses=include_unknown_poses,
        resolve_references=True,
        discover_ligands=True,
        source_kind=InputSourceKind.SESSION,
    )
    selected_poses = tuple(discovery.poses)
    final_mode = _selection_mode(mode, len(selected_poses)) if selected_poses else canonicalize_chimerax_analysis_mode(mode)
    warnings_list = list(discovery.warnings)
    if not selected_poses:
        warnings_list.append("No docking poses were selected from the ChimeraX session.")
    if discovery.receptor is None:
        warnings_list.append("No receptor was selected from the ChimeraX session.")
    selection = ChimeraXModelSelection(
        session=session_value,
        models=tuple(model_values),
        receptor=discovery.receptor,
        poses=selected_poses,
        ligands=tuple(discovery.ligands),
        mode=final_mode,
        discovery=discovery,
        warnings=tuple(unique_preserving_order(warnings_list)),
        metadata={
            "include_unknown_poses": bool(include_unknown_poses),
            "strict": bool(strict),
            "explicit_receptor": receptor is not None,
            "explicit_poses": poses is not None,
        },
    )
    if strict and not selection.ready:
        raise AnalysisInputError(
            "The ChimeraX model selection is not ready for analysis.",
            code="incomplete_chimerax_model_selection",
            details=selection.to_dict(include_objects=False),
        )
    return selection


# 28.6. Command options and analysis configuration
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ChimeraXCommandOptions:
    """Normalized options accepted by the ChimeraX command interface."""

    mode: str = CHIMERAX_DEFAULT_MODE
    stages: Tuple[str, ...] = ()
    strict: bool = CHIMERAX_DEFAULT_STRICT
    generate_report: bool = False
    export_results: bool = False
    visualize_results: bool = CHIMERAX_DEFAULT_VISUALIZE
    output_directory: Optional[Path] = None
    snapshot_path: Optional[Path] = None
    save_session_path: Optional[Path] = None
    include_unknown_poses: bool = CHIMERAX_DEFAULT_INCLUDE_UNKNOWN_POSES
    reuse_results: bool = CHIMERAX_DEFAULT_REUSE_RESULTS
    attach_results: bool = CHIMERAX_DEFAULT_ATTACH_RESULTS
    dry_run: bool = False
    log_commands: bool = CHIMERAX_DEFAULT_LOG_COMMANDS
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        """Normalize command options."""

        object.__setattr__(self, "mode", canonicalize_chimerax_analysis_mode(self.mode))
        object.__setattr__(self, "stages", normalize_chimerax_stage_names(self.stages))
        for name in (
            "strict",
            "generate_report",
            "export_results",
            "visualize_results",
            "include_unknown_poses",
            "reuse_results",
            "attach_results",
            "dry_run",
            "log_commands",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        output_directory = (
            None
            if self.output_directory in (None, "")
            else normalize_path(self.output_directory)
        )
        object.__setattr__(self, "output_directory", output_directory)
        snapshot = (
            None
            if self.snapshot_path in (None, "")
            else normalize_chimerax_output_path(
                self.snapshot_path,
                suffix=CHIMERAX_DEFAULT_IMAGE_FORMAT,
            )
        )
        session_path = (
            None
            if self.save_session_path in (None, "")
            else normalize_chimerax_output_path(
                self.save_session_path,
                suffix=CHIMERAX_DEFAULT_SESSION_FORMAT,
            )
        )
        object.__setattr__(self, "snapshot_path", snapshot)
        object.__setattr__(self, "save_session_path", session_path)
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    @property
    def failure_policy(self) -> str:
        """Return the pipeline failure policy implied by strictness."""

        return FAILURE_POLICY_STRICT if self.strict else FAILURE_POLICY_PERMISSIVE

    @property
    def post_actions(self) -> Tuple[str, ...]:
        """Return requested post-analysis actions."""

        actions: List[str] = []
        if self.visualize_results:
            actions.append("visualize")
        if self.snapshot_path is not None:
            actions.append("snapshot")
        if self.save_session_path is not None:
            actions.append("save_session")
        return tuple(actions)

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible representation."""

        return {
            "mode": self.mode,
            "stages": list(self.stages),
            "strict": self.strict,
            "generate_report": self.generate_report,
            "export_results": self.export_results,
            "visualize_results": self.visualize_results,
            "output_directory": str(self.output_directory) if self.output_directory else None,
            "snapshot_path": str(self.snapshot_path) if self.snapshot_path else None,
            "save_session_path": str(self.save_session_path) if self.save_session_path else None,
            "include_unknown_poses": self.include_unknown_poses,
            "reuse_results": self.reuse_results,
            "attach_results": self.attach_results,
            "dry_run": self.dry_run,
            "log_commands": self.log_commands,
            "failure_policy": self.failure_policy,
            "post_actions": list(self.post_actions),
            "metadata": to_json_compatible(self.metadata),
        }


ChimeraXCommandOptionsLike: TypeAlias = Union[
    ChimeraXCommandOptions,
    Mapping[str, Any],
    None,
]


def coerce_chimerax_command_options(
    value: ChimeraXCommandOptionsLike = None,
    **overrides: Any,
) -> ChimeraXCommandOptions:
    """Return normalized ChimeraX command options."""

    if isinstance(value, ChimeraXCommandOptions):
        data = {
            field_info.name: getattr(value, field_info.name)
            for field_info in fields(ChimeraXCommandOptions)
        }
    elif value is None:
        data = {}
    elif isinstance(value, Mapping):
        data = dict(value)
    else:
        raise AnalysisConfigurationError(
            "ChimeraX command options must be a mapping or ChimeraXCommandOptions.",
            code="invalid_chimerax_command_options",
        )
    aliases = {
        "report": "generate_report",
        "export": "export_results",
        "visualize": "visualize_results",
        "output": "output_directory",
        "snapshot": "snapshot_path",
        "save_session": "save_session_path",
        "unknown_poses": "include_unknown_poses",
        "reuse": "reuse_results",
        "attach": "attach_results",
    }
    normalized: Dict[str, Any] = {}
    for key, item in data.items():
        normalized[aliases.get(str(key), str(key))] = item
    for key, item in overrides.items():
        if item is not None:
            normalized[aliases.get(str(key), str(key))] = item
    return ChimeraXCommandOptions(**normalized)


def build_chimerax_analysis_config(
    config: AnalysisConfigLike = None,
    *,
    options: ChimeraXCommandOptionsLike = None,
) -> AnalysisConfig:
    """Build an analysis configuration for native ChimeraX execution."""

    command_options = coerce_chimerax_command_options(options)
    base = coerce_analysis_config(config)
    runtime = replace(
        base.runtime,
        analysis_mode=command_options.mode,
        failure_policy=command_options.failure_policy,
        attachment_policy=(
            ATTACHMENT_POLICY_MERGE
            if command_options.attach_results
            else ATTACHMENT_POLICY_NONE
        ),
        attach_results=command_options.attach_results,
        reuse_results=command_options.reuse_results,
        dry_run=command_options.dry_run,
        allow_chimerax_threads=False,
    )
    output = replace(
        base.output,
        generate_report=command_options.generate_report,
        export_results=command_options.export_results,
        visualize_results=command_options.visualize_results,
        output_directory=command_options.output_directory,
        create_snapshot=command_options.snapshot_path is not None,
        save_session=command_options.save_session_path is not None,
    )
    requested = command_options.stages or base.requested_stages
    return replace(
        base,
        runtime=runtime,
        output=output,
        requested_stages=tuple(requested),
        metadata=MappingProxyType(
            {
                **dict(base.metadata),
                "chimerax": True,
                "chimerax_command_options": command_options.to_dict(),
            }
        ),
    )


def build_chimerax_analysis_request(
    selection: ChimeraXModelSelection,
    *,
    config: AnalysisConfigLike = None,
    options: ChimeraXCommandOptionsLike = None,
    name: str = "ChimeraX analysis",
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnalysisRequest:
    """Build an analysis request from a ChimeraX model selection."""

    command_options = coerce_chimerax_command_options(options, mode=selection.mode)
    config_value = build_chimerax_analysis_config(config, options=command_options)
    request_metadata = {
        "source": "chimerax_session",
        "session_info": inspect_chimerax_session(selection.session).to_dict(),
        "selection": selection.to_dict(include_objects=False),
        **dict(metadata or {}),
    }
    return AnalysisRequest(
        input_data={
            "session": selection.session,
            "receptor": selection.receptor,
            "poses": list(selection.poses),
            "models": list(selection.models),
        },
        config=config_value,
        name=normalize_text(name, default="ChimeraX analysis"),
        mode=selection.mode,
        receptor=selection.receptor,
        poses=selection.poses,
        session=selection.session,
        requested_stages=config_value.requested_stages,
        metadata=request_metadata,
    )


# 28.7. Native command execution and post-analysis actions
# -----------------------------------------------------------------------------


@dataclass
class ChimeraXCommandExecution:
    """Result of one native ChimeraX command invocation."""

    command: str
    status: ChimeraXCommandStatus = ChimeraXCommandStatus.PENDING
    return_value: Any = None
    error: Optional[str] = None
    started_at: str = field(default_factory=_utc_timestamp)
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = CHIMERAX_COMMAND_EXECUTION_RESULT_TYPE

    @property
    def succeeded(self) -> bool:
        """Return whether the command completed successfully."""

        return self.status in {
            ChimeraXCommandStatus.SUCCEEDED,
            ChimeraXCommandStatus.VALIDATED,
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible representation."""

        return {
            "result_type": self.result_type,
            "command": self.command,
            "status": self.status.value,
            "return_value": to_json_compatible(self.return_value),
            "error": self.error,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "metadata": to_json_compatible(self.metadata),
        }


def execute_chimerax_native_command(
    command: Any,
    *,
    session: Any = None,
    runner: Any = None,
    dry_run: bool = False,
    log_command: bool = CHIMERAX_DEFAULT_LOG_COMMANDS,
    raise_on_error: bool = False,
) -> ChimeraXCommandExecution:
    """Execute or validate one native ChimeraX command."""

    text = chimerax_command_text(command)
    if not text:
        raise AnalysisConfigurationError(
            "A non-empty ChimeraX command is required.",
            code="empty_chimerax_command",
        )
    result = ChimeraXCommandExecution(command=text)
    started = time.perf_counter()
    try:
        if dry_run:
            result.status = ChimeraXCommandStatus.VALIDATED
            result.metadata["dry_run"] = True
        else:
            session_value = resolve_chimerax_session(session, required=True)
            runner_value = resolve_chimerax_command_runner(runner, required=True)
            if log_command:
                emit_chimerax_message(
                    f"Executing command: {text}",
                    session=session_value,
                    level="debug",
                )
            try:
                return_value = runner_value(session_value, text, log=log_command)
            except TypeError:
                return_value = runner_value(session_value, text)
            result.return_value = return_value
            result.status = ChimeraXCommandStatus.SUCCEEDED
    except Exception as exc:
        result.status = ChimeraXCommandStatus.FAILED
        result.error = f"{type(exc).__name__}: {exc}"
        if raise_on_error:
            raise ChimeraXAnalysisError(
                f"ChimeraX command failed: {text}",
                code="chimerax_command_failed",
                cause=exc,
                details={"command": text},
            ) from exc
    finally:
        result.finished_at = _utc_timestamp()
        result.duration_seconds = max(0.0, time.perf_counter() - started)
    return result


def create_chimerax_snapshot(
    filename: Any,
    *,
    session: Any = None,
    runner: Any = None,
    width: Optional[int] = None,
    height: Optional[int] = None,
    supersample: Optional[int] = None,
    transparent_background: Optional[bool] = None,
    dry_run: bool = False,
    raise_on_error: bool = False,
) -> ChimeraXCommandExecution:
    """Create a ChimeraX scene snapshot through the native command runner."""

    path = normalize_chimerax_output_path(
        filename,
        default_name=f"{CHIMERAX_DEFAULT_SNAPSHOT_BASENAME}.{CHIMERAX_DEFAULT_IMAGE_FORMAT}",
        suffix=Path(str(filename)).suffix.lstrip(".") if filename not in (None, "") and Path(str(filename)).suffix else CHIMERAX_DEFAULT_IMAGE_FORMAT,
    )
    assert path is not None
    path.parent.mkdir(parents=True, exist_ok=True)
    parts = ["save", quote_chimerax_argument(path, always=True)]
    if width is not None:
        parts.extend(("width", str(max(1, int(width)))))
    if height is not None:
        parts.extend(("height", str(max(1, int(height)))))
    if supersample is not None:
        parts.extend(("supersample", str(max(1, int(supersample)))))
    if transparent_background is not None:
        parts.extend(("transparentBackground", "true" if transparent_background else "false"))
    result = execute_chimerax_native_command(
        " ".join(parts),
        session=session,
        runner=runner,
        dry_run=dry_run,
        raise_on_error=raise_on_error,
    )
    result.metadata.update({"action": "snapshot", "path": str(path)})
    return result


def save_chimerax_session(
    filename: Any,
    *,
    session: Any = None,
    runner: Any = None,
    dry_run: bool = False,
    raise_on_error: bool = False,
) -> ChimeraXCommandExecution:
    """Save the current ChimeraX session."""

    path = normalize_chimerax_output_path(
        filename,
        default_name=f"{CHIMERAX_DEFAULT_SESSION_BASENAME}.{CHIMERAX_DEFAULT_SESSION_FORMAT}",
        suffix=CHIMERAX_DEFAULT_SESSION_FORMAT,
    )
    assert path is not None
    path.parent.mkdir(parents=True, exist_ok=True)
    result = execute_chimerax_native_command(
        f"save {quote_chimerax_argument(path, always=True)}",
        session=session,
        runner=runner,
        dry_run=dry_run,
        raise_on_error=raise_on_error,
    )
    result.metadata.update({"action": "save_session", "path": str(path)})
    return result


def focus_chimerax_models(
    models: Any,
    *,
    session: Any = None,
    runner: Any = None,
    dry_run: bool = False,
    raise_on_error: bool = False,
) -> ChimeraXCommandExecution:
    """Focus the ChimeraX camera on selected models."""

    atomspecs = [
        spec
        for spec in (chimerax_model_atomspec(item) for item in normalize_object_sequence(models))
        if spec
    ]
    target = " ".join(atomspecs) if atomspecs else "all"
    return execute_chimerax_native_command(
        f"view {target}",
        session=session,
        runner=runner,
        dry_run=dry_run,
        raise_on_error=raise_on_error,
    )


# 28.8. Session analysis orchestration
# -----------------------------------------------------------------------------


@dataclass
class ChimeraXAnalysisOutput:
    """Integrated result returned by native ChimeraX analysis."""

    selection: ChimeraXModelSelection
    request: AnalysisRequest
    analysis_output: Any
    command_options: ChimeraXCommandOptions
    session_info: ChimeraXSessionInfo
    post_actions: List[ChimeraXCommandExecution] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    started_at: str = field(default_factory=_utc_timestamp)
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = CHIMERAX_INTEGRATION_RESULT_TYPE

    @property
    def status(self) -> str:
        """Return the normalized analysis status."""

        value = getattr(self.analysis_output, "status", AnalysisStatus.FAILED)
        return getattr(value, "value", str(value))

    @property
    def succeeded(self) -> bool:
        """Return whether analysis and required post-actions succeeded."""

        analysis_success = bool(getattr(self.analysis_output, "succeeded", False))
        return analysis_success and not self.errors and all(
            action.succeeded for action in self.post_actions
        )

    @property
    def dock_models(self) -> Tuple[Any, ...]:
        """Return DockModel objects produced by the analysis."""

        preparation = getattr(self.analysis_output, "preparation", None)
        models = getattr(preparation, "dock_models", ()) if preparation is not None else ()
        return tuple(normalize_object_sequence(models))

    def summary(self) -> Dict[str, Any]:
        """Return a compact result summary."""

        return {
            "status": self.status,
            "succeeded": self.succeeded,
            "mode": self.selection.mode,
            "pose_count": self.selection.pose_count,
            "dock_model_count": len(self.dock_models),
            "post_action_count": len(self.post_actions),
            "failed_post_actions": sum(not item.succeeded for item in self.post_actions),
            "warning_count": len(self.warnings),
            "error_count": len(self.errors),
            "duration_seconds": self.duration_seconds,
        }

    def to_dict(self, *, include_objects: bool = False) -> Dict[str, Any]:
        """Return a JSON-compatible representation."""

        analysis_data = (
            self.analysis_output.to_dict(include_objects=include_objects)
            if callable(getattr(self.analysis_output, "to_dict", None))
            else to_json_compatible(self.analysis_output)
        )
        return {
            "result_type": self.result_type,
            "status": self.status,
            "succeeded": self.succeeded,
            "selection": self.selection.to_dict(include_objects=include_objects),
            "request": self.request.to_dict(include_objects=include_objects),
            "analysis_output": analysis_data,
            "command_options": self.command_options.to_dict(),
            "session_info": self.session_info.to_dict(),
            "post_actions": [item.to_dict() for item in self.post_actions],
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "metadata": to_json_compatible(self.metadata),
            "summary": self.summary(),
        }


def dispatch_chimerax_analysis(
    selection: ChimeraXModelSelection,
    *,
    request: Optional[AnalysisRequest] = None,
    config: AnalysisConfigLike = None,
    options: ChimeraXCommandOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    dispatcher: Optional[ChimeraXAnalysisDispatcher] = None,
) -> Any:
    """Dispatch a ChimeraX model selection to the correct orchestrator."""

    command_options = coerce_chimerax_command_options(options, mode=selection.mode)
    request_value = request or build_chimerax_analysis_request(
        selection,
        config=config,
        options=command_options,
    )
    if dispatcher is not None:
        return dispatcher(
            selection=selection,
            request=request_value,
            config=request_value.config,
            options=command_options,
        )
    common = {
        "session": selection.session,
        "config": request_value.config,
        "registry": registry,
        "capabilities": capabilities,
        "requested_stages": request_value.requested_stages,
        "name": request_value.name,
        "metadata": request_value.metadata,
        "progress_callback": progress_callback,
        "stage_callback": stage_callback,
        "cancellation_callback": cancellation_callback,
    }
    if selection.mode == ANALYSIS_MODE_SINGLE_POSE:
        return run_single_pose_analysis(
            receptor=selection.receptor,
            pose=selection.poses[0],
            **common,
        )
    if selection.mode == ANALYSIS_MODE_MULTIPOSE:
        return run_multipose_analysis(
            receptor=selection.receptor,
            poses=selection.poses,
            **common,
        )
    raise AnalysisInputError(
        f"Unsupported resolved ChimeraX mode: {selection.mode!r}.",
        code="unsupported_resolved_chimerax_mode",
    )


def _run_chimerax_post_actions(
    output: ChimeraXAnalysisOutput,
    *,
    runner: Any = None,
) -> None:
    """Execute requested visualization-adjacent post-actions."""

    options = output.command_options
    session = output.selection.session
    if options.snapshot_path is not None:
        action = create_chimerax_snapshot(
            options.snapshot_path,
            session=session,
            runner=runner,
            dry_run=options.dry_run,
            raise_on_error=False,
        )
        output.post_actions.append(action)
        if not action.succeeded:
            output.errors.append(action.error or "Snapshot creation failed.")
    if options.save_session_path is not None:
        action = save_chimerax_session(
            options.save_session_path,
            session=session,
            runner=runner,
            dry_run=options.dry_run,
            raise_on_error=False,
        )
        output.post_actions.append(action)
        if not action.succeeded:
            output.errors.append(action.error or "Session saving failed.")


def analyze_chimerax_session(
    session: Any = None,
    *,
    models: Any = None,
    receptor: Any = None,
    poses: Any = None,
    config: AnalysisConfigLike = None,
    options: ChimeraXCommandOptionsLike = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    runner: Any = None,
    dispatcher: Optional[ChimeraXAnalysisDispatcher] = None,
    name: str = "ChimeraX analysis",
    metadata: Optional[Mapping[str, Any]] = None,
) -> ChimeraXAnalysisOutput:
    """Analyze receptor and pose models from an active ChimeraX session."""

    command_options = coerce_chimerax_command_options(options)
    started = time.perf_counter()
    session_value = resolve_chimerax_session(session, required=command_options.strict)
    selection = resolve_chimerax_model_selection(
        session_value,
        models=models,
        receptor=receptor,
        poses=poses,
        mode=command_options.mode,
        include_unknown_poses=command_options.include_unknown_poses,
        strict=command_options.strict,
    )
    request = build_chimerax_analysis_request(
        selection,
        config=config,
        options=command_options,
        name=name,
        metadata=metadata,
    )
    callback = progress_callback
    if callback is None and session_value is not None:
        callback = make_chimerax_progress_callback(session_value)
    emit_chimerax_message(
        f"Starting {selection.mode} analysis for {selection.pose_count} pose(s).",
        session=session_value,
        level="status",
    )
    try:
        analysis_output = dispatch_chimerax_analysis(
            selection,
            request=request,
            options=command_options,
            registry=registry,
            capabilities=capabilities,
            progress_callback=callback,
            stage_callback=stage_callback,
            cancellation_callback=cancellation_callback,
            dispatcher=dispatcher,
        )
        output = ChimeraXAnalysisOutput(
            selection=selection,
            request=request,
            analysis_output=analysis_output,
            command_options=command_options,
            session_info=inspect_chimerax_session(session_value, runner=runner),
            warnings=list(selection.warnings),
            metadata={"name": name, **dict(metadata or {})},
        )
        _run_chimerax_post_actions(output, runner=runner)
    except Exception as exc:
        if command_options.strict:
            raise
        fallback = SimpleNamespace(
            status=AnalysisStatus.FAILED,
            succeeded=False,
            to_dict=lambda **_: {"status": AnalysisStatus.FAILED.value},
        )
        output = ChimeraXAnalysisOutput(
            selection=selection,
            request=request,
            analysis_output=fallback,
            command_options=command_options,
            session_info=inspect_chimerax_session(session_value, runner=runner),
            warnings=list(selection.warnings),
            errors=[f"{type(exc).__name__}: {exc}"],
            metadata={"name": name, **dict(metadata or {})},
        )
    output.finished_at = _utc_timestamp()
    output.duration_seconds = max(0.0, time.perf_counter() - started)
    emit_chimerax_message(
        (
            f"Analysis finished with status {output.status}; "
            f"{selection.pose_count} pose(s) processed."
        ),
        session=session_value,
        level="info" if output.succeeded else "warning",
    )
    return output


def analyze_open_models(
    session: Any = None,
    **kwargs: Any,
) -> ChimeraXAnalysisOutput:
    """Analyze compatible molecular models currently open in ChimeraX."""

    return analyze_chimerax_session(session, models=None, **kwargs)


def analyze_selected_chimerax_models(
    session: Any,
    models: Any,
    **kwargs: Any,
) -> ChimeraXAnalysisOutput:
    """Analyze an explicit collection of selected ChimeraX models."""

    return analyze_chimerax_session(session, models=models, **kwargs)


# 28.9. ChimeraX command callback
# -----------------------------------------------------------------------------


def chimerax_analyze_command(
    session: Any,
    models: Any = None,
    *,
    receptor: Any = None,
    poses: Any = None,
    mode: str = CHIMERAX_DEFAULT_MODE,
    stages: Any = None,
    strict: bool = CHIMERAX_DEFAULT_STRICT,
    report: bool = False,
    export: bool = False,
    visualize: bool = CHIMERAX_DEFAULT_VISUALIZE,
    output_directory: Any = None,
    snapshot: Any = None,
    save_session: Any = None,
    include_unknown_poses: bool = CHIMERAX_DEFAULT_INCLUDE_UNKNOWN_POSES,
    reuse_results: bool = CHIMERAX_DEFAULT_REUSE_RESULTS,
    attach_results: bool = CHIMERAX_DEFAULT_ATTACH_RESULTS,
    dry_run: bool = False,
    log_commands: bool = CHIMERAX_DEFAULT_LOG_COMMANDS,
) -> ChimeraXAnalysisOutput:
    """Native ChimeraX callback for the ``dockanalyzer analyze`` command."""

    options = ChimeraXCommandOptions(
        mode=mode,
        stages=normalize_chimerax_stage_names(stages),
        strict=strict,
        generate_report=report,
        export_results=export,
        visualize_results=visualize,
        output_directory=output_directory,
        snapshot_path=snapshot,
        save_session_path=save_session,
        include_unknown_poses=include_unknown_poses,
        reuse_results=reuse_results,
        attach_results=attach_results,
        dry_run=dry_run,
        log_commands=log_commands,
        metadata={"invoked_as_command": True},
    )
    return analyze_chimerax_session(
        session,
        models=models,
        receptor=receptor,
        poses=poses,
        options=options,
        name=CHIMERAX_COMMAND_NAME,
        metadata={"command_name": CHIMERAX_COMMAND_NAME},
    )


# 28.10. Command registration
# -----------------------------------------------------------------------------


@dataclass(frozen=True)
class ChimeraXCommandRegistration:
    """Result of registering or deregistering a ChimeraX command."""

    command_name: str
    status: ChimeraXRegistrationStatus
    alias: Optional[str] = None
    descriptor: Any = None
    error: Optional[str] = None
    registered_at: str = field(default_factory=_utc_timestamp)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    result_type: str = CHIMERAX_COMMAND_REGISTRATION_RESULT_TYPE

    @property
    def succeeded(self) -> bool:
        """Return whether the registration operation succeeded."""

        return self.status in {
            ChimeraXRegistrationStatus.REGISTERED,
            ChimeraXRegistrationStatus.ALREADY_REGISTERED,
            ChimeraXRegistrationStatus.DEREGISTERED,
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a JSON-compatible representation."""

        return {
            "result_type": self.result_type,
            "command_name": self.command_name,
            "alias": self.alias,
            "status": self.status.value,
            "error": self.error,
            "registered_at": self.registered_at,
            "metadata": to_json_compatible(self.metadata),
        }


_CHIMERAX_COMMAND_REGISTRY_LOCK: Final[threading.RLock] = threading.RLock()
_CHIMERAX_COMMAND_REGISTRATIONS: Dict[str, ChimeraXCommandRegistration] = {}


def _load_chimerax_command_api() -> Dict[str, Any]:
    """Load ChimeraX command registration symbols lazily."""

    try:
        commands = importlib.import_module("chimerax.core.commands")
    except Exception as exc:
        raise ChimeraXUnavailableAnalysisError(
            "The ChimeraX command registration API is unavailable.",
            code="chimerax_command_api_unavailable",
            recoverable=True,
            action=RecoveryAction.SKIP_STAGE,
            cause=exc,
        ) from exc
    symbols = {
        name: getattr(commands, name, None)
        for name in (
            "CmdDesc",
            "register",
            "deregister",
            "BoolArg",
            "StringArg",
            "ModelsArg",
            "ModelArg",
            "OpenFolderNameArg",
            "SaveFileNameArg",
            "EnumOf",
        )
    }
    if not callable(symbols.get("register")) or symbols.get("CmdDesc") is None:
        raise ChimeraXUnavailableAnalysisError(
            "The ChimeraX command API does not expose CmdDesc and register.",
            code="incomplete_chimerax_command_api",
        )
    return symbols


def build_chimerax_command_descriptor() -> Any:
    """Build the native command descriptor when ChimeraX is available."""

    api = _load_chimerax_command_api()
    CmdDesc = api["CmdDesc"]
    StringArg = api.get("StringArg")
    BoolArg = api.get("BoolArg")
    ModelsArg = api.get("ModelsArg") or StringArg
    ModelArg = api.get("ModelArg") or StringArg
    FolderArg = api.get("OpenFolderNameArg") or StringArg
    FileArg = api.get("SaveFileNameArg") or StringArg
    EnumOf = api.get("EnumOf")
    mode_arg = StringArg
    if callable(EnumOf):
        try:
            mode_arg = EnumOf(CHIMERAX_SUPPORTED_ANALYSIS_MODES)
        except Exception:
            mode_arg = StringArg
    keyword = []
    for name, arg in (
        ("receptor", ModelArg),
        ("poses", ModelsArg),
        ("mode", mode_arg),
        ("stages", StringArg),
        ("strict", BoolArg),
        ("report", BoolArg),
        ("export", BoolArg),
        ("visualize", BoolArg),
        ("output_directory", FolderArg),
        ("snapshot", FileArg),
        ("save_session", FileArg),
        ("include_unknown_poses", BoolArg),
        ("reuse_results", BoolArg),
        ("attach_results", BoolArg),
        ("dry_run", BoolArg),
        ("log_commands", BoolArg),
    ):
        if arg is not None:
            keyword.append((name, arg))
    required = [("models", ModelsArg)] if ModelsArg is not None else []
    try:
        return CmdDesc(
            optional=required,
            keyword=keyword,
            synopsis=CHIMERAX_COMMAND_SYNOPSIS,
        )
    except TypeError:
        return CmdDesc(
            required=[],
            optional=required,
            keyword=keyword,
            synopsis=CHIMERAX_COMMAND_SYNOPSIS,
        )


def register_chimerax_command(
    session: Any = None,
    *,
    command_name: str = CHIMERAX_COMMAND_NAME,
    alias: Optional[str] = CHIMERAX_COMMAND_ALIAS,
    replace_existing: bool = False,
    registrar: Optional[ChimeraXCommandRegistrar] = None,
) -> ChimeraXCommandRegistration:
    """Register the DockAnalyzer command in ChimeraX."""

    name = normalize_text(command_name, default=CHIMERAX_COMMAND_NAME).strip()
    if not name:
        raise AnalysisConfigurationError(
            "A non-empty ChimeraX command name is required.",
            code="empty_chimerax_command_name",
        )
    with _CHIMERAX_COMMAND_REGISTRY_LOCK:
        existing = _CHIMERAX_COMMAND_REGISTRATIONS.get(name)
        if existing is not None and not replace_existing:
            return ChimeraXCommandRegistration(
                command_name=name,
                alias=existing.alias,
                status=ChimeraXRegistrationStatus.ALREADY_REGISTERED,
                descriptor=existing.descriptor,
                metadata={"reused": True},
            )
    try:
        api = _load_chimerax_command_api()
        register_function = registrar or api["register"]
        descriptor = build_chimerax_command_descriptor()
        logger = resolve_chimerax_logger(session)
        try:
            register_function(
                name,
                descriptor,
                chimerax_analyze_command,
                logger=logger,
            )
        except TypeError:
            register_function(name, descriptor, chimerax_analyze_command)
        registration = ChimeraXCommandRegistration(
            command_name=name,
            alias=alias,
            status=ChimeraXRegistrationStatus.REGISTERED,
            descriptor=descriptor,
            metadata={"category": CHIMERAX_COMMAND_CATEGORY},
        )
        with _CHIMERAX_COMMAND_REGISTRY_LOCK:
            _CHIMERAX_COMMAND_REGISTRATIONS[name] = registration
        return registration
    except ChimeraXUnavailableAnalysisError:
        raise
    except Exception as exc:
        return ChimeraXCommandRegistration(
            command_name=name,
            alias=alias,
            status=ChimeraXRegistrationStatus.FAILED,
            error=f"{type(exc).__name__}: {exc}",
        )


def deregister_chimerax_command(
    command_name: str = CHIMERAX_COMMAND_NAME,
    *,
    deregistrar: Optional[ChimeraXCommandDeregistrar] = None,
) -> ChimeraXCommandRegistration:
    """Deregister the DockAnalyzer ChimeraX command."""

    name = normalize_text(command_name, default=CHIMERAX_COMMAND_NAME).strip()
    try:
        api = _load_chimerax_command_api()
        deregister_function = deregistrar or api.get("deregister")
        if not callable(deregister_function):
            raise ChimeraXUnavailableAnalysisError(
                "The ChimeraX command deregistration API is unavailable.",
                code="chimerax_deregister_unavailable",
            )
        deregister_function(name)
        with _CHIMERAX_COMMAND_REGISTRY_LOCK:
            _CHIMERAX_COMMAND_REGISTRATIONS.pop(name, None)
        return ChimeraXCommandRegistration(
            command_name=name,
            status=ChimeraXRegistrationStatus.DEREGISTERED,
        )
    except ChimeraXUnavailableAnalysisError:
        raise
    except Exception as exc:
        return ChimeraXCommandRegistration(
            command_name=name,
            status=ChimeraXRegistrationStatus.FAILED,
            error=f"{type(exc).__name__}: {exc}",
        )


def registered_chimerax_commands() -> Tuple[ChimeraXCommandRegistration, ...]:
    """Return locally tracked command registrations."""

    with _CHIMERAX_COMMAND_REGISTRY_LOCK:
        return tuple(_CHIMERAX_COMMAND_REGISTRATIONS.values())


def chimerax_command_registered(command_name: str = CHIMERAX_COMMAND_NAME) -> bool:
    """Return whether a command is tracked as registered."""

    name = normalize_text(command_name, default=CHIMERAX_COMMAND_NAME).strip()
    with _CHIMERAX_COMMAND_REGISTRY_LOCK:
        return name in _CHIMERAX_COMMAND_REGISTRATIONS


# 28.11. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_chimerax_model_selection(
    value: ChimeraXModelSelection,
) -> Tuple[str, ...]:
    """Return validation issues for a model selection."""

    issues: List[str] = []
    if not isinstance(value, ChimeraXModelSelection):
        return ("The value is not a ChimeraXModelSelection.",)
    issues.extend(validate_chimerax_session(value.session))
    if value.receptor is None:
        issues.append("A receptor model is required.")
    if not value.poses:
        issues.append("At least one docking pose is required.")
    if value.mode == ANALYSIS_MODE_SINGLE_POSE and len(value.poses) != 1:
        issues.append("Single-pose mode requires exactly one pose.")
    if value.mode == ANALYSIS_MODE_MULTIPOSE and len(value.poses) < 2:
        issues.append("Multipose mode requires at least two poses.")
    if len({id(item) for item in value.poses}) != len(value.poses):
        issues.append("The selected poses contain duplicate object references.")
    if value.receptor is not None and any(item is value.receptor for item in value.poses):
        issues.append("The receptor cannot also be a docking pose.")
    return tuple(unique_preserving_order(issues))


def validate_chimerax_analysis_output(
    value: ChimeraXAnalysisOutput,
) -> Tuple[str, ...]:
    """Return validation issues for a ChimeraX analysis output."""

    issues: List[str] = []
    if not isinstance(value, ChimeraXAnalysisOutput):
        return ("The value is not a ChimeraXAnalysisOutput.",)
    issues.extend(validate_chimerax_model_selection(value.selection))
    if value.analysis_output is None:
        issues.append("The analysis output is missing.")
    if value.finished_at is not None and value.duration_seconds is None:
        issues.append("A finished ChimeraX analysis must record its duration.")
    for action in value.post_actions:
        if not isinstance(action, ChimeraXCommandExecution):
            issues.append("A post-action is not a ChimeraXCommandExecution.")
    try:
        json.dumps(value.to_dict(include_objects=False), sort_keys=True)
    except Exception as exc:
        issues.append(f"The ChimeraX output is not JSON serializable: {exc}")
    return tuple(unique_preserving_order(issues))


def summarize_chimerax_session(session: Any = None) -> Dict[str, Any]:
    """Return a compact ChimeraX session summary."""

    return inspect_chimerax_session(session).to_dict()


def summarize_chimerax_analysis(value: ChimeraXAnalysisOutput) -> Dict[str, Any]:
    """Return a compact ChimeraX analysis summary."""

    return value.summary()


def chimerax_analysis_to_json(
    value: ChimeraXAnalysisOutput,
    *,
    indent: Optional[int] = 2,
) -> str:
    """Serialize a ChimeraX analysis output as JSON."""

    return json.dumps(
        value.to_dict(include_objects=False),
        indent=indent,
        sort_keys=True,
        ensure_ascii=False,
    )


# 28.12. Internal validation
# -----------------------------------------------------------------------------


def validate_chimerax_integration_conventions() -> Dict[str, Any]:
    """Validate the ChimeraX compatibility and command interface."""

    class _Logger:
        def __init__(self) -> None:
            self.messages: List[Tuple[str, str]] = []

        def _record(self, level: str, message: str) -> None:
            self.messages.append((level, message))

        def debug(self, message: str) -> None:
            self._record("debug", message)

        def info(self, message: str) -> None:
            self._record("info", message)

        def status(self, message: str) -> None:
            self._record("status", message)

        def warning(self, message: str) -> None:
            self._record("warning", message)

        def error(self, message: str) -> None:
            self._record("error", message)

    class _Models:
        def __init__(self, values: Sequence[Any]) -> None:
            self._values = list(values)

        def list(self, *args: Any, **kwargs: Any) -> List[Any]:
            return list(self._values)

    receptor = SimpleNamespace(
        id=(1,),
        id_string="1",
        name="Receptor",
        atoms=(SimpleNamespace(coord=(0.0, 0.0, 0.0)),),
        residues=(SimpleNamespace(name="ALA", polymer_type="amino"),),
    )
    ligand = SimpleNamespace(
        name="LIG",
        atoms=(SimpleNamespace(coord=(1.0, 0.0, 0.0)),),
    )
    pose = SimpleNamespace(
        id=(2,),
        id_string="2",
        name="pose_1",
        atoms=ligand.atoms,
        residues=(SimpleNamespace(name="LIG", polymer_type="none"),),
        ligand=ligand,
    )
    session = SimpleNamespace(
        name="self-test-session",
        models=_Models((receptor, pose)),
        logger=_Logger(),
        ui=SimpleNamespace(is_gui=False),
    )
    commands: List[str] = []

    def runner(session_value: Any, command: str, **_: Any) -> str:
        if session_value is not session:
            raise AssertionError("Unexpected session passed to command runner.")
        commands.append(command)
        return command

    info = inspect_chimerax_session(session, runner=runner)
    if info.backend_state is not ChimeraXBackendState.AVAILABLE:
        raise AssertionError("A complete synthetic backend was not recognized.")
    selection = resolve_chimerax_model_selection(
        session,
        models=(receptor, pose),
        receptor=receptor,
        poses=(pose,),
        strict=True,
    )
    if not selection.ready or selection.mode != ANALYSIS_MODE_SINGLE_POSE:
        raise AssertionError("The synthetic single-pose selection is invalid.")
    if validate_chimerax_model_selection(selection):
        raise AssertionError("The synthetic model selection did not validate.")
    options = ChimeraXCommandOptions(
        mode="single",
        stages=(STAGE_INPUT_RESOLUTION, STAGE_MODEL_PREPARATION),
        strict=True,
        dry_run=True,
    )
    request = build_chimerax_analysis_request(
        selection,
        options=options,
    )
    if request.mode != ANALYSIS_MODE_SINGLE_POSE:
        raise AssertionError("The ChimeraX request mode was not preserved.")

    class _SyntheticOutput:
        status = AnalysisStatus.SUCCEEDED
        succeeded = True
        preparation = SimpleNamespace(dock_models=())

        def to_dict(self, **_: Any) -> Dict[str, Any]:
            return {"status": "succeeded"}

    dispatched = dispatch_chimerax_analysis(
        selection,
        request=request,
        options=options,
        dispatcher=lambda **_: _SyntheticOutput(),
    )
    output = ChimeraXAnalysisOutput(
        selection=selection,
        request=request,
        analysis_output=dispatched,
        command_options=options,
        session_info=info,
        finished_at=_utc_timestamp(),
        duration_seconds=0.0,
    )
    if not output.succeeded:
        raise AssertionError("The synthetic ChimeraX analysis output failed.")
    if validate_chimerax_analysis_output(output):
        raise AssertionError("The synthetic ChimeraX analysis output did not validate.")
    command_result = execute_chimerax_native_command(
        "view #1 #2",
        session=session,
        runner=runner,
    )
    if not command_result.succeeded or commands != ["view #1 #2"]:
        raise AssertionError("Native command execution failed.")
    dry_result = create_chimerax_snapshot(
        "/tmp/dockanalyzer_section28_test.png",
        session=session,
        runner=runner,
        dry_run=True,
    )
    if dry_result.status is not ChimeraXCommandStatus.VALIDATED:
        raise AssertionError("Snapshot dry-run validation failed.")
    if canonicalize_chimerax_analysis_mode("multi-pose") != ANALYSIS_MODE_MULTIPOSE:
        raise AssertionError("ChimeraX analysis-mode aliases are inconsistent.")
    if normalize_chimerax_stage_names("contacts, scoring") != (
        STAGE_CONTACTS,
        STAGE_SCORING,
    ):
        raise AssertionError("ChimeraX stage parsing is inconsistent.")
    json.loads(chimerax_analysis_to_json(output))
    return {
        "valid": True,
        "schema": CHIMERAX_INTEGRATION_SCHEMA_NAME,
        "schema_version": CHIMERAX_INTEGRATION_SCHEMA_VERSION,
        "session_state": info.backend_state.value,
        "model_count": len(selection.models),
        "pose_count": selection.pose_count,
        "validated_cases": 14,
    }


