# 29.2. Dispatch kinds and normalization
# -----------------------------------------------------------------------------

class AnalysisDispatchKind(str, Enum):
    """Canonical destination selected by the unified dispatcher."""

    AUTO = ANALYSIS_DISPATCH_AUTO
    SINGLE_POSE = ANALYSIS_DISPATCH_SINGLE_POSE
    MULTIPOSE = ANALYSIS_DISPATCH_MULTIPOSE
    BATCH = ANALYSIS_DISPATCH_BATCH
    CHIMERAX = ANALYSIS_DISPATCH_CHIMERAX


class AnalysisIntrospectionDetail(str, Enum):
    """Detail level used by API-inspection helpers."""

    SUMMARY = "summary"
    STANDARD = "standard"
    FULL = "full"


class AnalysisCLIOutputFormat(str, Enum):
    """Output format supported by the command-line interface."""

    TEXT = "text"
    JSON = "json"


def canonicalize_analysis_dispatch_kind(
    value: Any,
    *,
    default: str = ANALYSIS_DISPATCH_AUTO,
) -> str:
    """Return one canonical unified-dispatch mode."""

    if isinstance(value, AnalysisDispatchKind):
        return value.value
    if value is None:
        return default
    token = normalize_text(value).strip().lower().replace(" ", "_")
    canonical = ANALYSIS_DISPATCH_ALIASES.get(token)
    if canonical is None:
        canonical = ANALYSIS_DISPATCH_ALIASES.get(token.replace("-", "_"))
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unknown analysis dispatch mode: {value!r}.",
            details={"supported_modes": list(ANALYSIS_DISPATCH_MODES)},
        )
    return canonical


def canonicalize_analysis_introspection_detail(
    value: Any,
    *,
    default: str = ANALYSIS_INTROSPECTION_DEFAULT_DETAIL,
) -> str:
    """Return a canonical API-introspection detail level."""

    if isinstance(value, AnalysisIntrospectionDetail):
        return value.value
    token = normalize_text(value or default).strip().lower()
    aliases = {
        "brief": "summary",
        "short": "summary",
        "summary": "summary",
        "normal": "standard",
        "standard": "standard",
        "default": "standard",
        "full": "full",
        "detailed": "full",
        "verbose": "full",
    }
    canonical = aliases.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unknown introspection detail level: {value!r}.",
            details={"supported_levels": list(ANALYSIS_INTROSPECTION_DETAILS)},
        )
    return canonical


def canonicalize_analysis_cli_output_format(
    value: Any,
    *,
    default: str = "text",
) -> str:
    """Return a supported command-line output format."""

    if isinstance(value, AnalysisCLIOutputFormat):
        return value.value
    token = normalize_text(value or default).strip().lower()
    aliases = {
        "text": "text",
        "txt": "text",
        "plain": "text",
        "json": "json",
    }
    canonical = aliases.get(token)
    if canonical is None:
        raise AnalysisConfigurationError(
            f"Unknown CLI output format: {value!r}.",
            details={"supported_formats": list(ANALYSIS_CLI_OUTPUT_FORMATS)},
        )
    return canonical


# 29.3. Unified dispatch decision
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class AnalysisDispatchDecision:
    """Explain how the unified API selected one execution workflow."""

    kind: str
    reason: str
    explicit: bool = False
    input_kind: str = InputSourceKind.UNKNOWN.value
    pose_count: int = 0
    request_count: int = 0
    has_session: bool = False
    requested_stages: Tuple[str, ...] = ()
    configuration_fingerprint: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict)
    schema: str = CONVENIENCE_API_SCHEMA_NAME
    schema_version: str = CONVENIENCE_API_SCHEMA_VERSION

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "kind",
            canonicalize_analysis_dispatch_kind(self.kind),
        )
        object.__setattr__(self, "reason", normalize_text(self.reason).strip())
        object.__setattr__(self, "pose_count", max(0, int(self.pose_count)))
        object.__setattr__(self, "request_count", max(0, int(self.request_count)))
        object.__setattr__(
            self,
            "requested_stages",
            canonicalize_stage_sequence(self.requested_stages),
        )
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    @property
    def is_single_pose(self) -> bool:
        return self.kind == ANALYSIS_DISPATCH_SINGLE_POSE

    @property
    def is_multipose(self) -> bool:
        return self.kind == ANALYSIS_DISPATCH_MULTIPOSE

    @property
    def is_batch(self) -> bool:
        return self.kind == ANALYSIS_DISPATCH_BATCH

    @property
    def is_chimerax(self) -> bool:
        return self.kind == ANALYSIS_DISPATCH_CHIMERAX

    def to_dict(self) -> Dict[str, Any]:
        return {
            "schema": self.schema,
            "schema_version": self.schema_version,
            "kind": self.kind,
            "reason": self.reason,
            "explicit": self.explicit,
            "input_kind": self.input_kind,
            "pose_count": self.pose_count,
            "request_count": self.request_count,
            "has_session": self.has_session,
            "requested_stages": list(self.requested_stages),
            "configuration_fingerprint": self.configuration_fingerprint,
            "metadata": to_json_compatible(self.metadata),
        }

    def summary(self) -> Dict[str, Any]:
        return {
            "kind": self.kind,
            "reason": self.reason,
            "explicit": self.explicit,
            "input_kind": self.input_kind,
            "pose_count": self.pose_count,
            "request_count": self.request_count,
        }


def _analysis_request_mode(value: Any) -> Optional[str]:
    """Return an explicit mode carried by a request-like object."""

    if isinstance(value, AnalysisContext):
        mode = value.mode
    elif isinstance(value, AnalysisRequest):
        mode = value.mode
    elif isinstance(value, Mapping):
        mode = get_input_mapping_value(value, "mode")
        if is_missing_value(mode):
            mode = get_input_mapping_value(value, "analysis_mode")
        if is_missing_value(mode):
            return None
    else:
        return None
    try:
        canonical = canonicalize_analysis_mode(mode)
    except Exception:
        return None
    return None if canonical == ANALYSIS_MODE_AUTO else canonical


def _bounded_sequence_count(value: Any, *, maximum: int) -> int:
    """Return a bounded collection count without consuming excessive input."""

    if value is None:
        return 0
    if isinstance(value, (str, bytes, bytearray, Mapping)):
        return 0
    if isinstance(value, Sequence):
        try:
            return min(len(value), maximum)
        except Exception:
            pass
    if is_nonstring_iterable(value):
        return len(normalize_object_sequence(value, maximum_items=maximum))
    return 0


def infer_analysis_dispatch(
    value: Any = None,
    *,
    mode: Any = None,
    receptor: Any = None,
    pose: Any = None,
    poses: Any = None,
    dock_model: Any = None,
    dock_models: Any = None,
    requests: Any = None,
    session: Any = None,
    config: AnalysisConfigLike = None,
    requested_stages: Any = None,
) -> AnalysisDispatchDecision:
    """Infer the safest execution workflow for arbitrary analysis inputs."""

    integrated = coerce_analysis_config(config)
    explicit_mode = mode
    if explicit_mode is None:
        explicit_mode = _analysis_request_mode(value)
    if explicit_mode is None and integrated.runtime.analysis_mode != ANALYSIS_MODE_AUTO:
        explicit_mode = integrated.runtime.analysis_mode

    input_kind_enum = classify_analysis_input(value)
    input_kind = input_kind_enum.value
    normalized_stages = canonicalize_stage_sequence(
        requested_stages if requested_stages is not None else integrated.requested_stages
    )
    config_fingerprint = analysis_config_fingerprint(integrated)

    pose_count = _bounded_sequence_count(poses, maximum=integrated.runtime.max_multipose_items)
    dock_model_count = _bounded_sequence_count(
        dock_models,
        maximum=integrated.runtime.max_multipose_items,
    )
    request_count = _bounded_sequence_count(
        requests,
        maximum=integrated.runtime.max_batch_items,
    )
    has_session = session is not None or input_kind_enum is InputSourceKind.SESSION

    if explicit_mode is not None:
        canonical = canonicalize_analysis_dispatch_kind(explicit_mode)
        if canonical != ANALYSIS_DISPATCH_AUTO:
            return AnalysisDispatchDecision(
                kind=canonical,
                reason="The execution mode was selected explicitly.",
                explicit=True,
                input_kind=input_kind,
                pose_count=max(pose_count, dock_model_count),
                request_count=request_count,
                has_session=has_session,
                requested_stages=normalized_stages,
                configuration_fingerprint=config_fingerprint,
            )

    if has_session:
        return AnalysisDispatchDecision(
            kind=ANALYSIS_DISPATCH_CHIMERAX,
            reason="A ChimeraX-like session was supplied or discovered.",
            input_kind=input_kind,
            pose_count=max(pose_count, dock_model_count),
            request_count=request_count,
            has_session=True,
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if requests is not None or input_kind_enum is InputSourceKind.BATCH:
        if request_count == 0 and requests is None and is_batch_request_collection(value):
            request_count = _bounded_sequence_count(
                value,
                maximum=integrated.runtime.max_batch_items,
            )
        return AnalysisDispatchDecision(
            kind=ANALYSIS_DISPATCH_BATCH,
            reason="A collection of independent analysis requests was supplied.",
            input_kind=input_kind,
            pose_count=max(pose_count, dock_model_count),
            request_count=request_count,
            has_session=False,
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if dock_model_count > 1 or pose_count > 1:
        return AnalysisDispatchDecision(
            kind=ANALYSIS_DISPATCH_MULTIPOSE,
            reason="More than one pose or DockModel was supplied.",
            input_kind=input_kind,
            pose_count=max(pose_count, dock_model_count),
            request_count=0,
            has_session=False,
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if input_kind_enum is InputSourceKind.DOCK_MODELS:
        count = _bounded_sequence_count(
            value,
            maximum=integrated.runtime.max_multipose_items,
        )
        kind = (
            ANALYSIS_DISPATCH_MULTIPOSE
            if count > 1
            else ANALYSIS_DISPATCH_SINGLE_POSE
        )
        return AnalysisDispatchDecision(
            kind=kind,
            reason=(
                "A collection of DockModel objects was supplied."
                if count > 1
                else "A one-item DockModel collection was supplied."
            ),
            input_kind=input_kind,
            pose_count=count,
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if input_kind_enum is InputSourceKind.MODELS:
        count = _bounded_sequence_count(
            value,
            maximum=integrated.runtime.max_multipose_items + 1,
        )
        if receptor is not None:
            count = max(0, count)
        elif count > 1:
            count -= 1
        kind = (
            ANALYSIS_DISPATCH_MULTIPOSE
            if count > 1
            else ANALYSIS_DISPATCH_SINGLE_POSE
        )
        return AnalysisDispatchDecision(
            kind=kind,
            reason="A molecular model collection was supplied.",
            input_kind=input_kind,
            pose_count=max(0, count),
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if input_kind_enum is InputSourceKind.RECEPTOR_POSES:
        source_items = normalize_object_sequence(value, maximum_items=2)
        count = 0
        if len(source_items) == 2:
            count = _bounded_sequence_count(
                source_items[1],
                maximum=integrated.runtime.max_multipose_items,
            )
            if count == 0 and source_items[1] is not None:
                count = 1
        kind = (
            ANALYSIS_DISPATCH_MULTIPOSE
            if count > 1
            else ANALYSIS_DISPATCH_SINGLE_POSE
        )
        return AnalysisDispatchDecision(
            kind=kind,
            reason="A receptor and pose input pair was supplied.",
            input_kind=input_kind,
            pose_count=count,
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if pose is not None or dock_model is not None:
        return AnalysisDispatchDecision(
            kind=ANALYSIS_DISPATCH_SINGLE_POSE,
            reason="One explicit pose or DockModel was supplied.",
            input_kind=input_kind,
            pose_count=1,
            requested_stages=normalized_stages,
            configuration_fingerprint=config_fingerprint,
        )

    if isinstance(value, AnalysisRequest):
        if value.is_batch:
            selected = ANALYSIS_DISPATCH_BATCH
        elif value.is_multipose:
            selected = ANALYSIS_DISPATCH_MULTIPOSE
        elif value.is_session:
            selected = ANALYSIS_DISPATCH_CHIMERAX
        else:
            selected = ANALYSIS_DISPATCH_SINGLE_POSE
        return AnalysisDispatchDecision(
            kind=selected,
            reason="The workflow was inferred from the AnalysisRequest.",
            input_kind=input_kind,
            pose_count=value.pose_count,
            request_count=value.item_count,
            has_session=value.session is not None,
            requested_stages=(value.requested_stages or normalized_stages),
            configuration_fingerprint=analysis_config_fingerprint(value.config),
        )

    if isinstance(value, AnalysisContext):
        selected = canonicalize_analysis_dispatch_kind(value.mode)
        if selected == ANALYSIS_DISPATCH_AUTO:
            selected = ANALYSIS_DISPATCH_SINGLE_POSE
        return AnalysisDispatchDecision(
            kind=selected,
            reason="The workflow was inferred from the AnalysisContext.",
            input_kind=input_kind,
            pose_count=value.request.pose_count,
            request_count=value.request.item_count,
            has_session=value.session is not None,
            requested_stages=(value.request.requested_stages or normalized_stages),
            configuration_fingerprint=analysis_config_fingerprint(value.config),
        )

    return AnalysisDispatchDecision(
        kind=ANALYSIS_DISPATCH_SINGLE_POSE,
        reason="The input does not require a multipose, batch or session workflow.",
        input_kind=input_kind,
        pose_count=1 if value is not None or receptor is not None else 0,
        requested_stages=normalized_stages,
        configuration_fingerprint=config_fingerprint,
    )


# 29.4. Unified output envelope
# -----------------------------------------------------------------------------

@dataclass
class UnifiedAnalysisOutput:
    """Uniform envelope returned by :func:`run_analysis`."""

    dispatch: AnalysisDispatchDecision
    output: Any
    config: AnalysisConfig
    request: Optional[AnalysisRequest] = None
    started_at: str = field(default_factory=_utc_timestamp)
    finished_at: Optional[str] = None
    duration_seconds: Optional[float] = None
    warnings: List[str] = field(default_factory=list)
    errors: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = CONVENIENCE_API_RESULT_TYPE

    def __post_init__(self) -> None:
        self.config = coerce_analysis_config(self.config)
        if self.request is None:
            candidate = safe_getattr(self.output, "request", None)
            if isinstance(candidate, AnalysisRequest):
                self.request = candidate
        if self.finished_at is None:
            self.finished_at = _utc_timestamp()
        if self.duration_seconds is not None:
            self.duration_seconds = max(0.0, float(self.duration_seconds))
        self.warnings = list(unique_preserving_order(self.warnings))
        self.errors = list(unique_preserving_order(self.errors))
        self.metadata.setdefault("schema", CONVENIENCE_API_SCHEMA_NAME)
        self.metadata.setdefault(
            "schema_version",
            CONVENIENCE_API_SCHEMA_VERSION,
        )
        self.metadata.setdefault("dispatch_kind", self.dispatch.kind)

    @property
    def status(self) -> AnalysisStatus:
        candidate = safe_getattr(self.output, "status", AnalysisStatus.PENDING)
        try:
            return canonicalize_analysis_status(candidate)
        except Exception:
            return AnalysisStatus.PENDING

    @property
    def succeeded(self) -> bool:
        candidate = safe_getattr(self.output, "succeeded", None)
        if isinstance(candidate, bool):
            return candidate
        return is_success_analysis_status(self.status)

    @property
    def failed(self) -> bool:
        candidate = safe_getattr(self.output, "failed", None)
        if isinstance(candidate, bool):
            return candidate
        return is_failure_analysis_status(self.status)

    @property
    def cancelled(self) -> bool:
        candidate = safe_getattr(self.output, "cancelled", None)
        if isinstance(candidate, bool):
            return candidate
        return self.status is AnalysisStatus.CANCELLED

    @property
    def result(self) -> Any:
        if isinstance(self.output, SinglePoseAnalysisOutput):
            return self.output.pose_result
        if isinstance(self.output, MultiposeAnalysisOutput):
            return self.output.multipose_result
        if isinstance(self.output, BatchAnalysisOutput):
            return self.output.batch_result
        if isinstance(self.output, ChimeraXAnalysisOutput):
            nested = self.output.analysis_output
            if isinstance(nested, SinglePoseAnalysisOutput):
                return nested.pose_result
            if isinstance(nested, MultiposeAnalysisOutput):
                return nested.multipose_result
            if isinstance(nested, BatchAnalysisOutput):
                return nested.batch_result
            return safe_getattr(nested, "result", nested)
        return safe_getattr(self.output, "result", self.output)

    @property
    def run_result(self) -> Optional[AnalysisRunResult]:
        candidate = safe_getattr(self.output, "run_result", None)
        if isinstance(candidate, AnalysisRunResult):
            return candidate
        if isinstance(self.output, ChimeraXAnalysisOutput):
            nested = safe_getattr(self.output, "analysis_output", None)
            candidate = safe_getattr(nested, "run_result", None)
            if isinstance(candidate, AnalysisRunResult):
                return candidate
        return None

    @property
    def context(self) -> Optional[AnalysisContext]:
        candidate = safe_getattr(self.output, "context", None)
        if isinstance(candidate, AnalysisContext):
            return candidate
        if isinstance(self.output, ChimeraXAnalysisOutput):
            nested = safe_getattr(self.output, "analysis_output", None)
            candidate = safe_getattr(nested, "context", None)
            if isinstance(candidate, AnalysisContext):
                return candidate
        return None

    def summary(self) -> Dict[str, Any]:
        output_summary = safe_getattr(self.output, "summary", None)
        if callable(output_summary):
            try:
                output_data = output_summary()
            except Exception:
                output_data = summarize_core_result(self.result)
        else:
            output_data = summarize_core_result(self.result)
        return {
            "result_type": self.result_type,
            "dispatch": self.dispatch.summary(),
            "status": self.status.value,
            "succeeded": self.succeeded,
            "duration_seconds": self.duration_seconds,
            "warning_count": len(self.warnings),
            "error_count": len(self.errors),
            "output": to_json_compatible(output_data),
        }

    def to_dict(
        self,
        *,
        include_output: bool = True,
        include_objects: bool = False,
    ) -> Dict[str, Any]:
        data: Dict[str, Any] = {
            "result_type": self.result_type,
            "dispatch": self.dispatch.to_dict(),
            "config": self.config.to_dict(),
            "request": (
                self.request.to_dict(include_objects=include_objects)
                if self.request is not None
                else None
            ),
            "status": self.status.value,
            "succeeded": self.succeeded,
            "failed": self.failed,
            "cancelled": self.cancelled,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "metadata": to_json_compatible(self.metadata),
        }
        if include_output:
            data["output"] = to_json_compatible(
                self.output,
                include_objects=include_objects,
            )
            data["result"] = to_json_compatible(
                self.result,
                include_objects=include_objects,
            )
        return data


# 29.5. Unified dispatcher and convenience functions
# -----------------------------------------------------------------------------

def _analysis_output_messages(output: Any) -> Tuple[List[str], List[str]]:
    """Collect warnings and errors from any orchestration output."""

    warnings_list: List[str] = []
    errors_list: List[str] = []
    for name, target in (("warnings", warnings_list), ("errors", errors_list)):
        value = safe_getattr(output, name, None)
        if value is not None:
            target.extend(normalize_string_sequence(value))
    if isinstance(output, ChimeraXAnalysisOutput):
        nested_warnings, nested_errors = _analysis_output_messages(
            output.analysis_output
        )
        warnings_list.extend(nested_warnings)
        errors_list.extend(nested_errors)
    return (
        list(unique_preserving_order(warnings_list)),
        list(unique_preserving_order(errors_list)),
    )


def _prepare_unified_config(
    config: AnalysisConfigLike,
    *,
    decision: AnalysisDispatchDecision,
    requested_stages: Any = None,
) -> AnalysisConfig:
    """Return a configuration aligned with one dispatch decision."""

    integrated = coerce_analysis_config(config)
    runtime = replace(integrated.runtime, analysis_mode=decision.kind)
    stages = (
        canonicalize_stage_sequence(requested_stages)
        if requested_stages is not None
        else integrated.requested_stages
    )
    return replace(integrated, runtime=runtime, requested_stages=stages)


def _unified_analysis_input_is_empty(
    value: Any,
    *,
    receptor: Any = None,
    pose: Any = None,
    poses: Any = None,
    dock_model: Any = None,
    dock_models: Any = None,
    requests: Any = None,
    session: Any = None,
    models: Any = None,
    context: Optional[AnalysisContext] = None,
) -> bool:
    """Return whether no explicit or contextual analysis input is available."""

    explicit = (
        value, receptor, pose, poses, dock_model, dock_models, requests, session, models
    )
    if any(item is not None for item in explicit):
        return False
    if context is not None:
        return not any(
            (context.request.input_data, context.receptor, context.poses, context.dock_models, context.session)
        )
    return True


def run_analysis(
    value: Any = None,
    *,
    mode: Any = None,
    receptor: Any = None,
    pose: Any = None,
    poses: Any = None,
    dock_model: Any = None,
    dock_models: Any = None,
    requests: Any = None,
    session: Any = None,
    models: Any = None,
    config: AnalysisConfigLike = None,
    requested_stages: Any = None,
    options: Any = None,
    registry: Optional[AnalysisStageRegistry] = None,
    capabilities: Optional[AnalysisCapabilities] = None,
    context: Optional[AnalysisContext] = None,
    name: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    progress_callback: Optional[ProgressCallback] = None,
    stage_callback: Optional[StageCallback] = None,
    cancellation_callback: Optional[CancellationCallback] = None,
    **workflow_options: Any,
) -> UnifiedAnalysisOutput:
    """Dispatch arbitrary input to the appropriate integrated workflow."""

    started_at = _utc_timestamp()
    started_clock = time.perf_counter()
    if _unified_analysis_input_is_empty(
        value,
        receptor=receptor,
        pose=pose,
        poses=poses,
        dock_model=dock_model,
        dock_models=dock_models,
        requests=requests,
        session=session,
        models=models,
        context=context,
    ):
        requested_mode = mode
        if requested_mode is None and isinstance(config, AnalysisConfig):
            requested_mode = config.runtime.analysis_mode
        session_mode = False
        if requested_mode is not None:
            try:
                session_mode = (
                    canonicalize_analysis_dispatch_mode(requested_mode)
                    == ANALYSIS_DISPATCH_CHIMERAX
                )
            except (TypeError, ValueError):
                session_mode = False
        if not session_mode or resolve_chimerax_session(None, required=False) is None:
            raise AnalysisInputError(
                "Analysis requires a pose, DockModel, molecular model collection, "
                "batch request or ChimeraX session.",
                code="missing_analysis_input",
                stage=STAGE_INPUT_RESOLUTION,
                recoverable=False,
            )
    decision = infer_analysis_dispatch(
        value,
        mode=mode,
        receptor=receptor,
        pose=pose,
        poses=poses,
        dock_model=dock_model,
        dock_models=dock_models,
        requests=requests,
        session=session,
        config=config,
        requested_stages=requested_stages,
    )
    integrated = _prepare_unified_config(
        config,
        decision=decision,
        requested_stages=requested_stages,
    )
    common: Dict[str, Any] = {
        "config": integrated,
        "registry": registry,
        "capabilities": capabilities,
        "progress_callback": progress_callback,
        "stage_callback": stage_callback,
        "cancellation_callback": cancellation_callback,
        "name": name,
        "metadata": metadata,
    }
    if context is not None:
        common["context"] = context
    common.update(workflow_options)

    if decision.kind == ANALYSIS_DISPATCH_SINGLE_POSE:
        output = run_single_pose_analysis(
            value,
            receptor=receptor,
            pose=pose,
            dock_model=dock_model,
            session=session,
            options=options,
            requested_stages=requested_stages,
            **common,
        )
    elif decision.kind == ANALYSIS_DISPATCH_MULTIPOSE:
        output = run_multipose_analysis(
            value,
            receptor=receptor,
            poses=poses,
            dock_models=dock_models,
            session=session,
            options=options,
            requested_stages=requested_stages,
            **common,
        )
    elif decision.kind == ANALYSIS_DISPATCH_BATCH:
        batch_common = dict(common)
        batch_common.pop("context", None)
        output = run_batch_analysis(
            value,
            requests=requests,
            options=options,
            context=context,
            **batch_common,
        )
    elif decision.kind == ANALYSIS_DISPATCH_CHIMERAX:
        chimerax_common = dict(common)
        chimerax_common.pop("context", None)
        chimerax_common.pop("name", None)
        chimerax_common.pop("metadata", None)
        output = analyze_chimerax_session(
            session=(session if session is not None else value),
            models=models,
            receptor=receptor,
            poses=poses,
            options=options,
            name=(name or "ChimeraX analysis"),
            metadata=metadata,
            **chimerax_common,
        )
    else:  # pragma: no cover - protected by canonicalization
        raise AnalysisConfigurationError(
            f"Unsupported unified dispatch kind: {decision.kind!r}."
        )

    warnings_list, errors_list = _analysis_output_messages(output)
    duration = max(0.0, time.perf_counter() - started_clock)
    unified = UnifiedAnalysisOutput(
        dispatch=decision,
        output=output,
        config=integrated,
        request=safe_getattr(output, "request", None),
        started_at=started_at,
        finished_at=_utc_timestamp(),
        duration_seconds=duration,
        warnings=warnings_list,
        errors=errors_list,
        metadata={
            "schema": CONVENIENCE_API_SCHEMA_NAME,
            "schema_version": CONVENIENCE_API_SCHEMA_VERSION,
            "dispatch_reason": decision.reason,
        },
    )
    return unified


def analyze(
    value: Any = None,
    *,
    return_output: bool = ANALYSIS_FACADE_DEFAULT_RETURN_OUTPUT,
    **kwargs: Any,
) -> Any:
    """Analyze arbitrary input and return its primary result by default."""

    unified = run_analysis(value, **kwargs)
    return unified if return_output else unified.result


def execute_analysis(value: Any = None, **kwargs: Any) -> UnifiedAnalysisOutput:
    """Alias for :func:`run_analysis`."""

    return run_analysis(value, **kwargs)


def analyze_pose(value: Any = None, **kwargs: Any) -> PoseAnalysisResult:
    """Convenience alias for one pose analysis."""

    return analyze_single_pose(value, **kwargs)


def analyze_poses(value: Any = None, **kwargs: Any) -> MultiPoseAnalysisResult:
    """Convenience alias for one receptor with multiple poses."""

    return analyze_multiple_poses(value, **kwargs)


def analyze_dock_model(
    dock_model: Any,
    **kwargs: Any,
) -> PoseAnalysisResult:
    """Analyze one existing DockModel."""

    return analyze_single_dock_model(dock_model, **kwargs)


def analyze_dock_models(
    dock_models: Iterable[Any],
    **kwargs: Any,
) -> MultiPoseAnalysisResult:
    """Analyze existing DockModel objects as one multipose collection."""

    return analyze_multiple_dock_models(dock_models, **kwargs)


def analyze_session(session: Any = None, **kwargs: Any) -> Any:
    """Analyze models available in one ChimeraX session."""

    return analyze_chimerax_session(session=session, **kwargs)


def unified_analysis_to_json(
    value: Any,
    *,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
    sort_keys: bool = True,
) -> str:
    """Serialize a unified output or any supported result to JSON."""

    if isinstance(value, UnifiedAnalysisOutput):
        payload = value.to_dict()
    else:
        payload = to_json_compatible(value)
    try:
        return json.dumps(
            payload,
            indent=indent,
            sort_keys=sort_keys,
            ensure_ascii=False,
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise AnalysisSerializationError(
            "Unified analysis output could not be encoded as JSON.",
            cause=exc,
        ) from exc


def summarize_analysis_result(value: Any) -> Dict[str, Any]:
    """Return a compact summary for any public analysis output or result."""

    if isinstance(value, UnifiedAnalysisOutput):
        return value.summary()
    summary = safe_getattr(value, "summary", None)
    if callable(summary):
        try:
            data = summary()
            if isinstance(data, Mapping):
                return dict(data)
        except Exception:
            pass
    return summarize_core_result(value)


# 29.6. Object-oriented facade
# -----------------------------------------------------------------------------

@dataclass
class DockAnalyzer:
    """Reusable object-oriented facade for the analysis pipeline."""

    config: AnalysisConfig = field(default_factory=AnalysisConfig)
    registry: Optional[AnalysisStageRegistry] = None
    capabilities: Optional[AnalysisCapabilities] = None
    name: str = "DockAnalyzer"
    metadata: Mapping[str, Any] = field(default_factory=dict)
    validate_results: bool = ANALYSIS_FACADE_DEFAULT_VALIDATE

    def __post_init__(self) -> None:
        self.config = coerce_analysis_config(self.config)
        if self.registry is None:
            self.registry = get_default_stage_registry()
        self.name = normalize_text(self.name).strip() or "DockAnalyzer"
        self.metadata = MappingProxyType(dict(self.metadata))

    def with_config(self, value: AnalysisConfigLike) -> "DockAnalyzer":
        """Return a new facade with a replacement configuration."""

        return replace(self, config=coerce_analysis_config(value))

    def update_config(self, updates: Mapping[str, Any]) -> "DockAnalyzer":
        """Return a new facade with merged configuration updates."""

        return replace(self, config=merge_analysis_config(self.config, updates))

    def inspect_capabilities(
        self,
        *,
        refresh: bool = False,
        load_modules: bool = False,
        load_dependencies: bool = False,
    ) -> AnalysisCapabilities:
        """Inspect and cache runtime capabilities for this facade."""

        self.capabilities = inspect_analysis_capabilities(
            load_modules=load_modules,
            load_dependencies=load_dependencies,
            refresh=refresh,
        )
        return self.capabilities

    def plan(
        self,
        *,
        requested_stages: Any = None,
        mode: Any = None,
        strict: Optional[bool] = None,
    ) -> AnalysisExecutionPlan:
        """Build an execution plan without running the analysis."""

        selected_mode = canonicalize_analysis_dispatch_kind(
            mode or self.config.runtime.analysis_mode
        )
        return build_analysis_execution_plan(
            self.config,
            registry=self.registry,
            capabilities=self.capabilities,
            requested_stages=requested_stages,
            analysis_mode=selected_mode,
            strict=(self.config.runtime.is_strict if strict is None else strict),
        )

    def run(self, value: Any = None, **kwargs: Any) -> UnifiedAnalysisOutput:
        """Run the automatically selected analysis workflow."""

        kwargs.setdefault("config", self.config)
        kwargs.setdefault("registry", self.registry)
        kwargs.setdefault("capabilities", self.capabilities)
        kwargs.setdefault("name", self.name)
        if self.metadata:
            supplied = dict(kwargs.get("metadata") or {})
            kwargs["metadata"] = {**dict(self.metadata), **supplied}
        output = run_analysis(value, **kwargs)
        if self.validate_results:
            validation = validate_analysis_result(output.result, raise_on_error=False)
            output.metadata["facade_validation"] = validation.to_dict()
            if not validation.valid:
                output.warnings.append(
                    "The facade validation report contains one or more findings."
                )
        return output

    def analyze(self, value: Any = None, **kwargs: Any) -> Any:
        """Run analysis and return the primary integrated result."""

        return self.run(value, **kwargs).result

    def analyze_pose(self, value: Any = None, **kwargs: Any) -> PoseAnalysisResult:
        """Run one pose analysis with facade defaults."""

        kwargs.setdefault("config", self.config)
        kwargs.setdefault("registry", self.registry)
        kwargs.setdefault("capabilities", self.capabilities)
        return analyze_single_pose(value, **kwargs)

    def analyze_poses(
        self,
        value: Any = None,
        **kwargs: Any,
    ) -> MultiPoseAnalysisResult:
        """Run one multipose analysis with facade defaults."""

        kwargs.setdefault("config", self.config)
        kwargs.setdefault("registry", self.registry)
        kwargs.setdefault("capabilities", self.capabilities)
        return analyze_multiple_poses(value, **kwargs)

    def analyze_batch(self, value: Any = None, **kwargs: Any) -> BatchAnalysisResult:
        """Run one batch analysis with facade defaults."""

        kwargs.setdefault("config", self.config)
        kwargs.setdefault("registry", self.registry)
        kwargs.setdefault("capabilities", self.capabilities)
        return analyze_batch(value, **kwargs)

    def analyze_session(self, session: Any = None, **kwargs: Any) -> Any:
        """Run one ChimeraX-session analysis with facade defaults."""

        kwargs.setdefault("config", self.config)
        kwargs.setdefault("registry", self.registry)
        kwargs.setdefault("capabilities", self.capabilities)
        return analyze_chimerax_session(session=session, **kwargs)

    def validate(self, value: Any, **kwargs: Any) -> AnalysisValidationReport:
        """Validate any supported analysis object."""

        kwargs.setdefault("config", self.config)
        return validate_analysis_result(value, **kwargs)

    def inspect_api(
        self,
        *,
        detail: Any = ANALYSIS_INTROSPECTION_DEFAULT_DETAIL,
    ) -> "AnalysisAPISnapshot":
        """Return the current public-API snapshot."""

        return inspect_analysis_api(
            detail=detail,
            capabilities=self.capabilities,
        )

    def summary(self) -> Dict[str, Any]:
        """Return a compact description of this facade."""

        return {
            "name": self.name,
            "configuration_fingerprint": analysis_config_fingerprint(self.config),
            "requested_stages": list(self.config.requested_stages),
            "registered_stage_count": len(registered_analysis_stages()),
            "capabilities_inspected": self.capabilities is not None,
            "validate_results": self.validate_results,
            "metadata": to_json_compatible(self.metadata),
        }


# 29.7. Public-symbol and API introspection
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class AnalysisAPISymbol:
    """Structured description of one exported module symbol."""

    name: str
    kind: str
    section: Optional[int] = None
    signature: Optional[str] = None
    module: Optional[str] = None
    qualified_name: Optional[str] = None
    summary: Optional[str] = None
    available: bool = True
    deprecated: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict)
    result_type: str = ANALYSIS_API_SYMBOL_TYPE

    def to_dict(self) -> Dict[str, Any]:
        return {
            "result_type": self.result_type,
            "name": self.name,
            "kind": self.kind,
            "section": self.section,
            "signature": self.signature,
            "module": self.module,
            "qualified_name": self.qualified_name,
            "summary": self.summary,
            "available": self.available,
            "deprecated": self.deprecated,
            "metadata": to_json_compatible(self.metadata),
        }


@dataclass
class AnalysisAPISnapshot:
    """Snapshot of the exported API, stages, schemas and capabilities."""

    module_name: str
    module_version: str
    generated_at: str
    detail: str
    symbols: Tuple[AnalysisAPISymbol, ...]
    stages: Tuple[Mapping[str, Any], ...]
    capabilities: Optional[AnalysisCapabilities] = None
    schemas: Mapping[str, Any] = field(default_factory=dict)
    aliases: Mapping[str, Any] = field(default_factory=dict)
    metadata: Mapping[str, Any] = field(default_factory=dict)
    result_type: str = ANALYSIS_API_MANIFEST_TYPE

    @property
    def symbol_count(self) -> int:
        return len(self.symbols)

    @property
    def function_count(self) -> int:
        return sum(symbol.kind == "function" for symbol in self.symbols)

    @property
    def class_count(self) -> int:
        return sum(symbol.kind == "class" for symbol in self.symbols)

    @property
    def constant_count(self) -> int:
        return sum(symbol.kind == "constant" for symbol in self.symbols)

    def find(self, name: str) -> Optional[AnalysisAPISymbol]:
        """Return one symbol by exact public name."""

        token = normalize_text(name).strip()
        return next((item for item in self.symbols if item.name == token), None)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "result_type": self.result_type,
            "module_name": self.module_name,
            "module_version": self.module_version,
            "generated_at": self.generated_at,
            "detail": self.detail,
            "symbol_count": self.symbol_count,
            "function_count": self.function_count,
            "class_count": self.class_count,
            "constant_count": self.constant_count,
            "symbols": [symbol.to_dict() for symbol in self.symbols],
            "stages": [to_json_compatible(item) for item in self.stages],
            "capabilities": (
                self.capabilities.to_dict() if self.capabilities is not None else None
            ),
            "schemas": to_json_compatible(self.schemas),
            "aliases": to_json_compatible(self.aliases),
            "metadata": to_json_compatible(self.metadata),
        }

    def summary(self) -> Dict[str, Any]:
        return {
            "module_name": self.module_name,
            "module_version": self.module_version,
            "detail": self.detail,
            "symbol_count": self.symbol_count,
            "function_count": self.function_count,
            "class_count": self.class_count,
            "constant_count": self.constant_count,
            "stage_count": len(self.stages),
            "capabilities_included": self.capabilities is not None,
        }


def _iter_analysis_public_sections() -> Iterator[Tuple[int, Tuple[str, ...]]]:
    """Yield every numbered public-name declaration in section order."""

    for section in range(1, 31):
        names = globals().get(f"_SECTION_{section}_PUBLIC_NAMES", ())
        yield section, tuple(names)


@lru_cache(maxsize=1)
def _analysis_public_section_map() -> Dict[str, int]:
    """Return the section that declares each public name."""

    mapping: Dict[str, int] = {}
    for section, names in _iter_analysis_public_sections():
        for name in names:
            mapping.setdefault(str(name), section)
    return mapping


@lru_cache(maxsize=1)
def _analysis_public_registration_order() -> Tuple[str, ...]:
    """Reconstruct the ordered public registration sequence."""

    ordered: List[str] = []
    known: Set[str] = set()
    for section, names in _iter_analysis_public_sections():
        registration_names = globals().get(
            f"_SECTION_{section}_PUBLIC_REGISTRATION_NAMES",
            names,
        )
        for name in tuple(registration_names):
            if not isinstance(name, str):
                continue
            if name not in known:
                ordered.append(name)
                known.add(name)
    return tuple(ordered)


def _analysis_symbol_kind(value: Any) -> str:
    """Return a stable kind label for one public symbol."""

    if inspect.isclass(value):
        return "class"
    if inspect.isroutine(value):
        return "function"
    if isinstance(value, ModuleType):
        return "module"
    if isinstance(value, (str, int, float, bool, tuple, frozenset, Mapping, Enum)):
        return "constant"
    return "object"


def _analysis_symbol_signature(value: Any) -> Optional[str]:
    """Return a safe callable signature string."""

    if not callable(value):
        return None
    try:
        return str(inspect.signature(value))
    except (TypeError, ValueError):
        return None


def _analysis_symbol_summary(value: Any) -> Optional[str]:
    """Return the first non-empty line of a symbol docstring."""

    documentation = inspect.getdoc(value)
    if not documentation:
        return None
    return next(
        (line.strip() for line in documentation.splitlines() if line.strip()),
        None,
    )


def describe_analysis_symbol(
    name: str,
    *,
    detail: Any = ANALYSIS_INTROSPECTION_DEFAULT_DETAIL,
) -> AnalysisAPISymbol:
    """Describe one exported module symbol."""

    level = canonicalize_analysis_introspection_detail(detail)
    token = normalize_text(name).strip()
    available = token in globals()
    value = globals().get(token)
    sections = _analysis_public_section_map()
    metadata: Dict[str, Any] = {}
    if level == "full" and available:
        metadata = {
            "type_name": type(value).__name__,
            "source_file": inspect.getsourcefile(value)
            if inspect.isroutine(value) or inspect.isclass(value)
            else None,
            "is_callable": callable(value),
        }
        if inspect.isroutine(value) or inspect.isclass(value):
            try:
                metadata["source_line"] = inspect.getsourcelines(value)[1]
            except (OSError, TypeError):
                metadata["source_line"] = None
    return AnalysisAPISymbol(
        name=token,
        kind=_analysis_symbol_kind(value) if available else "missing",
        section=sections.get(token),
        signature=(
            _analysis_symbol_signature(value)
            if level in {"standard", "full"} and available
            else None
        ),
        module=safe_getattr(value, "__module__", None) if available else None,
        qualified_name=(
            safe_getattr(value, "__qualname__", None) if available else None
        ),
        summary=(
            _analysis_symbol_summary(value)
            if level in {"standard", "full"} and available
            else None
        ),
        available=available,
        metadata=metadata,
    )


def public_analysis_symbols(
    *,
    kind: Optional[str] = None,
    section: Optional[int] = None,
) -> Tuple[str, ...]:
    """Return public names optionally filtered by kind or section."""

    names: List[str] = []
    section_map = _analysis_public_section_map()
    kind_token = normalize_text(kind).strip().lower() if kind else None
    for name in __all__:
        if section is not None and section_map.get(name) != int(section):
            continue
        value = globals().get(name)
        if kind_token and _analysis_symbol_kind(value) != kind_token:
            continue
        names.append(name)
    return tuple(names)


def describe_analysis_stage(stage: Any) -> Dict[str, Any]:
    """Return a structured description of one registered pipeline stage."""

    canonical = canonicalize_registry_stage_name(stage)
    definition = get_analysis_stage_definition(canonical)
    dependencies = tuple(definition.dependencies)
    ordering_after = tuple(definition.ordering_predecessors)
    capability = None
    try:
        capability = inspect_analysis_capabilities().supports_stage(canonical)
    except Exception:
        capability = None
    return {
        "stage": canonical,
        "description": definition.description,
        "required": not definition.optional,
        "optional": definition.optional,
        "dependencies": list(dependencies),
        "ordering_after": list(ordering_after),
        "required_modules": list(definition.required_modules),
        "required_features": list(definition.metadata.get("required_features", ())),
        "requires_chimerax": definition.requires_chimerax,
        "has_executor": callable(definition.executor),
        "has_adapter": callable(definition.result_adapter),
        "has_validator": callable(definition.validator),
        "available": capability,
        "metadata": to_json_compatible(definition.metadata),
    }


def describe_analysis_pipeline(
    *,
    stages: Any = None,
    config: AnalysisConfigLike = None,
    mode: Any = None,
) -> Dict[str, Any]:
    """Describe registered stages and optionally build an execution plan."""

    selected = (
        canonicalize_stage_sequence(stages)
        if stages is not None
        else registered_analysis_stages()
    )
    descriptions = [describe_analysis_stage(stage) for stage in selected]
    payload: Dict[str, Any] = {
        "stage_count": len(descriptions),
        "stages": descriptions,
    }
    if config is not None or stages is not None or mode is not None:
        plan = build_analysis_execution_plan(
            config,
            requested_stages=selected if stages is not None else None,
            analysis_mode=(
                canonicalize_analysis_dispatch_kind(mode)
                if mode is not None
                else None
            ),
            strict=False,
        )
        payload["plan"] = plan.to_dict()
    return payload


def inspect_analysis_api(
    *,
    detail: Any = ANALYSIS_INTROSPECTION_DEFAULT_DETAIL,
    capabilities: Optional[AnalysisCapabilities] = None,
    include_capabilities: bool = False,
    refresh_capabilities: bool = False,
) -> AnalysisAPISnapshot:
    """Inspect exported symbols, registered stages and schema conventions."""

    level = canonicalize_analysis_introspection_detail(detail)
    symbols = tuple(
        describe_analysis_symbol(name, detail=level)
        for name in __all__[:ANALYSIS_INTROSPECTION_MAX_SYMBOLS]
    )
    stage_details = tuple(
        describe_analysis_stage(stage)
        for stage in registered_analysis_stages()
    )
    resolved_capabilities = capabilities
    if include_capabilities and resolved_capabilities is None:
        resolved_capabilities = inspect_analysis_capabilities(
            refresh=refresh_capabilities,
            load_modules=(level == "full"),
            load_dependencies=(level == "full"),
        )
    schemas = {
        "module": ANALYSIS_SCHEMA_NAME,
        "module_version": ANALYSIS_SCHEMA_VERSION,
        "configuration": ANALYSIS_SCHEMA_NAME,
        "results": ANALYSIS_SCHEMA_NAME,
        "capabilities": ANALYSIS_SCHEMA_NAME,
        "registry": STAGE_REGISTRY_SCHEMA_NAME,
        "execution_plan": EXECUTION_PLAN_SCHEMA_NAME,
        "single_pose": SINGLE_POSE_SCHEMA_NAME,
        "multipose": MULTIPOSE_SCHEMA_NAME,
        "batch": BATCH_EXECUTION_SCHEMA_NAME,
        "chimerax": CHIMERAX_INTEGRATION_SCHEMA_NAME,
        "convenience": CONVENIENCE_API_SCHEMA_NAME,
    }
    aliases = {
        "analysis_modes": dict(ANALYSIS_MODE_ALIASES),
        "dispatch_modes": dict(ANALYSIS_DISPATCH_ALIASES),
        "stages": dict(STAGE_ALIASES),
        "interaction_families": dict(INTERACTION_FAMILY_ALIASES),
    }
    return AnalysisAPISnapshot(
        module_name=_MODULE_NAME,
        module_version=__version__,
        generated_at=_utc_timestamp(),
        detail=level,
        symbols=symbols,
        stages=stage_details,
        capabilities=resolved_capabilities,
        schemas=MappingProxyType(schemas),
        aliases=MappingProxyType(aliases),
        metadata=MappingProxyType(
            {
                "description": _MODULE_DESCRIPTION,
                "python_version": platform.python_version(),
                "public_name_count": len(__all__),
                "registered_stage_count": len(stage_details),
            }
        ),
    )


def analysis_api_manifest(
    *,
    detail: Any = ANALYSIS_INTROSPECTION_DEFAULT_DETAIL,
    include_capabilities: bool = False,
) -> Dict[str, Any]:
    """Return the public API manifest as a JSON-compatible mapping."""

    return inspect_analysis_api(
        detail=detail,
        include_capabilities=include_capabilities,
    ).to_dict()


def analysis_api_to_json(
    value: Optional[AnalysisAPISnapshot] = None,
    *,
    indent: Optional[int] = DEFAULT_JSON_INDENT,
) -> str:
    """Serialize an API snapshot to JSON."""

    snapshot = value or inspect_analysis_api()
    return json.dumps(
        snapshot.to_dict(),
        indent=indent,
        sort_keys=True,
        ensure_ascii=False,
    )


def analysis_module_info() -> Dict[str, Any]:
    """Return stable module metadata and integration status."""

    return {
        "name": _MODULE_NAME,
        "description": _MODULE_DESCRIPTION,
        "version": __version__,
        "author": __author__,
        "license": __license__,
        "status": __status__,
        "python_version": platform.python_version(),
        "numpy_available": NUMPY_AVAILABLE,
        "chimerax_available": CHIMERAX_AVAILABLE,
        "public_name_count": len(__all__),
        "registered_stage_count": len(registered_analysis_stages()),
        "schemas": {
            "module": ANALYSIS_SCHEMA_NAME,
            "configuration": ANALYSIS_SCHEMA_NAME,
            "results": ANALYSIS_SCHEMA_NAME,
            "convenience": CONVENIENCE_API_SCHEMA_NAME,
        },
    }


def validate_analysis_public_api(
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate public declarations, registration order and core signatures."""

    errors: List[str] = []
    _analysis_public_section_map.cache_clear()
    _analysis_public_registration_order.cache_clear()

    def format_names(values: Iterable[Any]) -> str:
        return ", ".join(sorted(repr(value) for value in values))

    if not isinstance(__all__, list):
        errors.append("__all__ must remain a list.")

    invalid_entries = [
        repr(name)
        for name in __all__
        if not isinstance(name, str) or not name.strip()
    ]
    if invalid_entries:
        errors.append(
            "Invalid public-name entries: " + ", ".join(invalid_entries) + "."
        )

    duplicates = [
        name
        for name, count in Counter(
            name for name in __all__ if isinstance(name, str)
        ).items()
        if count > 1
    ]
    if duplicates:
        errors.append(
            "Duplicate public names: " + format_names(duplicates) + "."
        )

    private_names = [
        name for name in __all__
        if isinstance(name, str) and name.startswith("_")
    ]
    if private_names:
        errors.append(
            "Private names exported through __all__: "
            + format_names(private_names)
            + "."
        )

    missing = [
        name for name in __all__
        if isinstance(name, str) and name not in globals()
    ]
    if missing:
        errors.append(
            "Missing public names: " + format_names(missing) + "."
        )

    declared_sections: Dict[str, int] = {}
    for section, names in _iter_analysis_public_sections():
        declaration_name = f"_SECTION_{section}_PUBLIC_NAMES"
        raw_names = globals().get(declaration_name)
        if not isinstance(raw_names, tuple):
            errors.append(f"{declaration_name} must be a tuple.")
            continue
        invalid = [
            repr(name)
            for name in names
            if not isinstance(name, str) or not name.strip()
        ]
        if invalid:
            errors.append(
                f"{declaration_name} contains invalid entries: "
                + ", ".join(invalid)
                + "."
            )
        repeated = [
            name
            for name, count in Counter(
                name for name in names if isinstance(name, str)
            ).items()
            if count > 1
        ]
        if repeated:
            errors.append(
                f"{declaration_name} contains duplicates: "
                + format_names(repeated)
                + "."
            )
        for name in names:
            if not isinstance(name, str):
                continue
            previous = declared_sections.get(name)
            if previous is not None:
                errors.append(
                    f"Public name {name!r} is declared by Sections "
                    f"{previous} and {section}."
                )
            else:
                declared_sections[name] = section

        forward_name = f"_SECTION_{section}_FORWARD_PUBLIC_NAMES"
        forward_names = globals().get(forward_name, ())
        if not isinstance(forward_names, tuple):
            errors.append(f"{forward_name} must be a tuple when present.")
            continue
        forward_repeated = [
            name
            for name, count in Counter(
                name for name in forward_names if isinstance(name, str)
            ).items()
            if count > 1
        ]
        if forward_repeated:
            errors.append(
                f"{forward_name} contains duplicates: "
                + format_names(forward_repeated)
                + "."
            )
        overlap = {name for name in names if isinstance(name, str)}.intersection(
            name for name in forward_names if isinstance(name, str)
        )
        if overlap:
            errors.append(
                f"{forward_name} repeats names declared in the same section: "
                + format_names(overlap)
                + "."
            )

        registration_name = f"_SECTION_{section}_PUBLIC_REGISTRATION_NAMES"
        registration_names = globals().get(registration_name, names)
        if not isinstance(registration_names, tuple):
            errors.append(f"{registration_name} must be a tuple when present.")
        elif Counter(map(repr, registration_names)) != Counter(
            map(repr, (*names, *forward_names))
        ):
            errors.append(
                f"{registration_name} does not match its declared and forward names."
            )

    for section, _names in _iter_analysis_public_sections():
        forward_names = globals().get(
            f"_SECTION_{section}_FORWARD_PUBLIC_NAMES",
            (),
        )
        for name in forward_names:
            if not isinstance(name, str):
                continue
            declaration_section = declared_sections.get(name)
            if declaration_section is None:
                errors.append(
                    f"Forward public name {name!r} is never declared."
                )
            elif declaration_section <= section:
                errors.append(
                    f"Forward public name {name!r} must be declared after "
                    f"Section {section}."
                )

    expected_order = _analysis_public_registration_order()
    if tuple(__all__) != expected_order:
        errors.append(
            "__all__ does not match the section registration order."
        )

    undeclared = [
        name for name in __all__
        if isinstance(name, str) and name not in declared_sections
    ]
    if undeclared:
        errors.append(
            "Public names without a section declaration: "
            + format_names(undeclared)
            + "."
        )

    section_map = _analysis_public_section_map()
    section_30_names = globals().get("_SECTION_30_PUBLIC_NAMES", ())
    unmapped_section_30 = [
        name for name in section_30_names
        if isinstance(name, str) and name not in section_map
    ]
    if unmapped_section_30:
        errors.append(
            "Section 30 public names are absent from API introspection: "
            + format_names(unmapped_section_30)
            + "."
        )

    for required in ANALYSIS_CORE_CONVENIENCE_NAMES:
        value = globals().get(required)
        if value is None:
            errors.append(f"Required convenience API name is missing: {required}.")
        elif not callable(value):
            errors.append(
                f"Required convenience API name is not callable: {required}."
            )

    required_parameters: Mapping[str, Tuple[str, ...]] = {
        "analyze": ("value", "return_output", "kwargs"),
        "run_analysis": ("value", "mode", "config", "requested_stages"),
        "execute_analysis": ("value", "kwargs"),
        "analyze_pose": ("value", "kwargs"),
        "analyze_poses": ("value", "kwargs"),
        "analyze_dock_model": ("dock_model", "kwargs"),
        "analyze_dock_models": ("dock_models", "kwargs"),
        "analyze_session": ("session", "kwargs"),
        "analyze_single_pose": ("value", "kwargs"),
        "analyze_single_dock_model": ("dock_model", "kwargs"),
        "analyze_multiple_poses": ("value", "kwargs"),
        "analyze_multiple_dock_models": ("dock_models", "kwargs"),
        "analyze_batch": ("value", "kwargs"),
        "analyze_chimerax_session": ("session", "config", "options"),
        "validate_analysis_result": ("value", "config", "policy", "raise_on_error"),
        "inspect_analysis_api": ("detail", "include_capabilities"),
    }
    for function_name, parameters in required_parameters.items():
        value = globals().get(function_name)
        if not callable(value):
            errors.append(f"Required public callable is missing: {function_name}.")
            continue
        try:
            signature = inspect.signature(value)
        except (TypeError, ValueError) as exc:
            errors.append(
                f"{function_name}() signature could not be inspected: {exc}."
            )
            continue
        for parameter in parameters:
            if parameter not in signature.parameters:
                errors.append(
                    f"{function_name}() is missing parameter {parameter!r}."
                )

    try:
        analyze_signature = inspect.signature(analyze)
        return_output = analyze_signature.parameters.get("return_output")
        if return_output is None:
            errors.append("analyze() does not expose return_output.")
        elif return_output.kind is not inspect.Parameter.KEYWORD_ONLY:
            errors.append("analyze().return_output must remain keyword-only.")
    except (TypeError, ValueError) as exc:
        errors.append(f"analyze() signature could not be inspected: {exc}.")

    if raise_on_error and errors:
        raise AnalysisValidationError(
            "The public analysis API is invalid.",
            details={"errors": errors},
        )
    return tuple(errors)


# 29.8. Command-line JSON and configuration helpers
# -----------------------------------------------------------------------------

def _read_analysis_cli_text(value: str, *, stdin: Optional[TextIO] = None) -> str:
    """Read JSON text from a path, inline value or standard input."""

    token = normalize_text(value).strip()
    if not token:
        return ""
    if token == "-":
        stream = stdin or sys.stdin
        return stream.read()
    path = Path(token).expanduser()
    if path.is_file():
        return path.read_text(encoding="utf-8")
    return token


def parse_analysis_cli_json(
    value: Optional[str],
    *,
    stdin: Optional[TextIO] = None,
    default: Any = None,
) -> Any:
    """Parse a CLI JSON source from inline text, a file or standard input."""

    if value is None:
        return default
    text = _read_analysis_cli_text(value, stdin=stdin)
    if not text.strip():
        return default
    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        raise AnalysisConfigurationError(
            "A command-line JSON value is invalid.",
            details={
                "source": value,
                "line": exc.lineno,
                "column": exc.colno,
                "message": exc.msg,
            },
        ) from exc


def load_analysis_cli_config(
    value: Optional[str],
    *,
    stdin: Optional[TextIO] = None,
) -> AnalysisConfig:
    """Load an integrated configuration from a CLI JSON source."""

    data = parse_analysis_cli_json(value, stdin=stdin, default={})
    if data is None:
        data = {}
    if not isinstance(data, Mapping):
        raise AnalysisConfigurationError(
            "CLI configuration JSON must contain an object."
        )
    return coerce_analysis_config(data)


def load_analysis_cli_request(
    value: Optional[str],
    *,
    stdin: Optional[TextIO] = None,
    config: AnalysisConfigLike = None,
) -> AnalysisRequest:
    """Load an AnalysisRequest from a CLI JSON source."""

    data = parse_analysis_cli_json(value, stdin=stdin, default={})
    if data is None:
        data = {}
    if not isinstance(data, Mapping):
        raise AnalysisInputError("CLI request JSON must contain an object.")
    payload = dict(data)
    if config is not None and "config" not in payload:
        payload["config"] = coerce_analysis_config(config)
    return coerce_analysis_request(payload)


def write_analysis_cli_output(
    text: str,
    *,
    path: Optional[PathLike] = None,
    stream: Optional[TextIO] = None,
) -> Optional[Path]:
    """Write CLI output to a stream or UTF-8 file."""

    if path is None:
        target = stream or sys.stdout
        target.write(text)
        if not text.endswith("\n"):
            target.write("\n")
        return None
    output_path = Path(path).expanduser()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(
        text if text.endswith("\n") else text + "\n",
        encoding="utf-8",
    )
    return output_path


def render_analysis_cli_payload(
    payload: Any,
    *,
    output_format: Any = "text",
    indent: int = ANALYSIS_CLI_DEFAULT_INDENT,
) -> str:
    """Render one command-line payload as text or JSON."""

    selected = canonicalize_analysis_cli_output_format(output_format)
    if selected == "json":
        return json.dumps(
            to_json_compatible(payload),
            indent=max(0, int(indent)),
            sort_keys=True,
            ensure_ascii=False,
        )
    if isinstance(payload, str):
        return payload
    if isinstance(payload, Mapping):
        lines: List[str] = []
        for key, value in payload.items():
            if isinstance(value, (Mapping, list, tuple)):
                rendered = json.dumps(
                    to_json_compatible(value),
                    indent=max(0, int(indent)),
                    sort_keys=True,
                    ensure_ascii=False,
                )
                lines.append(f"{key}: {rendered}")
            else:
                lines.append(f"{key}: {value}")
        return "\n".join(lines)
    return normalize_text(payload)


# 29.9. Command-line parser
# -----------------------------------------------------------------------------

def _add_analysis_cli_output_arguments(parser: argparse.ArgumentParser) -> None:
    """Add common output arguments to one CLI subparser."""

    parser.add_argument(
        "--format",
        choices=ANALYSIS_CLI_OUTPUT_FORMATS,
        default="text",
        help="Output format.",
    )
    parser.add_argument(
        "--output",
        help="Optional output path. Standard output is used by default.",
    )
    parser.add_argument(
        "--indent",
        type=int,
        default=ANALYSIS_CLI_DEFAULT_INDENT,
        help="JSON indentation level.",
    )


def build_analysis_argument_parser() -> argparse.ArgumentParser:
    """Build the DockAnalyzer analysis command-line parser."""

    parser = argparse.ArgumentParser(
        prog=ANALYSIS_CLI_PROGRAM_NAME,
        description=ANALYSIS_CLI_DESCRIPTION,
        epilog=ANALYSIS_CLI_EPILOG,
    )
    parser.add_argument(
        "--version",
        action="version",
        version=f"%(prog)s {__version__}",
    )
    subparsers = parser.add_subparsers(dest="command", metavar="COMMAND")

    analyze_parser = subparsers.add_parser(
        "analyze",
        help="Run an analysis from a JSON request descriptor.",
    )
    analyze_parser.add_argument(
        "--request",
        help="Request JSON text, JSON path or '-' for standard input.",
    )
    analyze_parser.add_argument(
        "--config",
        help="Configuration JSON text, JSON path or '-' for standard input.",
    )
    analyze_parser.add_argument(
        "--mode",
        choices=ANALYSIS_DISPATCH_MODES,
        default=ANALYSIS_DISPATCH_AUTO,
        help="Execution workflow. Auto dispatch is used by default.",
    )
    analyze_parser.add_argument(
        "--stages",
        help="Comma-separated stage names.",
    )
    analyze_parser.add_argument(
        "--full-output",
        action="store_true",
        help="Return the unified execution envelope instead of the primary result.",
    )
    analyze_parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Enable runtime dry-run mode.",
    )
    analyze_parser.add_argument(
        "--strict",
        action="store_true",
        help="Use the strict failure policy.",
    )
    analyze_parser.add_argument(
        "--permissive",
        action="store_true",
        help="Use the permissive failure policy.",
    )
    _add_analysis_cli_output_arguments(analyze_parser)

    capabilities_parser = subparsers.add_parser(
        "capabilities",
        help="Inspect modules, dependencies and runtime features.",
    )
    capabilities_parser.add_argument(
        "--load-modules",
        action="store_true",
        help="Import specialized modules during inspection.",
    )
    capabilities_parser.add_argument(
        "--load-dependencies",
        action="store_true",
        help="Import optional dependencies during inspection.",
    )
    capabilities_parser.add_argument(
        "--refresh",
        action="store_true",
        help="Ignore cached capability results.",
    )
    _add_analysis_cli_output_arguments(capabilities_parser)

    stages_parser = subparsers.add_parser(
        "stages",
        help="List or describe registered pipeline stages.",
    )
    stages_parser.add_argument(
        "names",
        nargs="*",
        help="Optional stage names. All stages are shown by default.",
    )
    stages_parser.add_argument(
        "--config",
        help="Optional configuration JSON used to build a plan.",
    )
    stages_parser.add_argument(
        "--mode",
        choices=ANALYSIS_DISPATCH_MODES,
        default=None,
        help="Optional analysis mode for plan inspection.",
    )
    _add_analysis_cli_output_arguments(stages_parser)

    plan_parser = subparsers.add_parser(
        "plan",
        help="Build an execution plan without running analysis.",
    )
    plan_parser.add_argument(
        "--config",
        help="Configuration JSON text or path.",
    )
    plan_parser.add_argument(
        "--mode",
        choices=ANALYSIS_DISPATCH_MODES,
        default=ANALYSIS_DISPATCH_SINGLE_POSE,
        help="Analysis mode used by the planner.",
    )
    plan_parser.add_argument(
        "--stages",
        help="Comma-separated stage names.",
    )
    plan_parser.add_argument(
        "--strict",
        action="store_true",
        help="Reject unavailable or invalid stages.",
    )
    _add_analysis_cli_output_arguments(plan_parser)

    api_parser = subparsers.add_parser(
        "api",
        help="Inspect the public API and schema manifest.",
    )
    api_parser.add_argument(
        "--detail",
        choices=ANALYSIS_INTROSPECTION_DETAILS,
        default=ANALYSIS_INTROSPECTION_DEFAULT_DETAIL,
        help="Introspection detail level.",
    )
    api_parser.add_argument(
        "--capabilities",
        action="store_true",
        help="Include a capability snapshot.",
    )
    _add_analysis_cli_output_arguments(api_parser)

    validate_parser = subparsers.add_parser(
        "validate",
        help="Validate a JSON request descriptor or configuration.",
    )
    validate_parser.add_argument(
        "--request",
        help="Optional request JSON text or path.",
    )
    validate_parser.add_argument(
        "--config",
        help="Optional configuration JSON text or path.",
    )
    validate_parser.add_argument(
        "--api",
        action="store_true",
        help="Validate the exported API instead of a request.",
    )
    _add_analysis_cli_output_arguments(validate_parser)
    return parser


# 29.10. Command-line execution
# -----------------------------------------------------------------------------

def _analysis_cli_requested_stages(value: Optional[str]) -> Tuple[str, ...]:
    """Parse comma-separated CLI stage names."""

    if value is None:
        return ()
    return canonicalize_stage_sequence(
        item.strip() for item in value.split(",") if item.strip()
    )


def _analysis_cli_config_with_overrides(
    config: AnalysisConfig,
    arguments: argparse.Namespace,
) -> AnalysisConfig:
    """Apply shared command-line overrides to an integrated configuration."""

    runtime = config.runtime
    mode = safe_getattr(arguments, "mode", None)
    if mode:
        runtime = replace(
            runtime,
            analysis_mode=canonicalize_analysis_dispatch_kind(mode),
        )
    if safe_getattr(arguments, "dry_run", False):
        runtime = replace(runtime, dry_run=True)
    if safe_getattr(arguments, "strict", False):
        runtime = replace(runtime, failure_policy=FAILURE_POLICY_STRICT)
    if safe_getattr(arguments, "permissive", False):
        runtime = replace(runtime, failure_policy=FAILURE_POLICY_PERMISSIVE)
    stages = _analysis_cli_requested_stages(
        safe_getattr(arguments, "stages", None)
    )
    return replace(
        config,
        runtime=runtime,
        requested_stages=(stages or config.requested_stages),
    )


def _analysis_cli_exit_code(value: Any) -> int:
    """Return a stable process exit code for an analysis result."""

    status = safe_getattr(value, "status", AnalysisStatus.SUCCEEDED)
    try:
        canonical = canonicalize_analysis_status(status)
    except Exception:
        canonical = AnalysisStatus.SUCCEEDED
    if canonical is AnalysisStatus.CANCELLED:
        return ANALYSIS_CLI_CANCELLED
    if canonical in {AnalysisStatus.FAILED, AnalysisStatus.PARTIAL}:
        return ANALYSIS_CLI_FAILURE
    return ANALYSIS_CLI_SUCCESS


def analysis_cli(
    argv: Optional[Sequence[str]] = None,
    *,
    stdin: Optional[TextIO] = None,
    stdout: Optional[TextIO] = None,
    stderr: Optional[TextIO] = None,
) -> int:
    """Execute the analysis command-line interface and return an exit code."""

    output_stream = stdout or sys.stdout
    error_stream = stderr or sys.stderr
    parser = build_analysis_argument_parser()
    arguments = parser.parse_args(list(argv) if argv is not None else None)
    if not arguments.command:
        parser.print_help(file=output_stream)
        return ANALYSIS_CLI_SUCCESS

    try:
        if arguments.command == "capabilities":
            capabilities = inspect_analysis_capabilities(
                load_modules=arguments.load_modules,
                load_dependencies=arguments.load_dependencies,
                refresh=arguments.refresh,
            )
            payload = (
                capabilities.to_dict()
                if arguments.format == "json"
                else capabilities.summary()
            )
            code = ANALYSIS_CLI_SUCCESS if capabilities.ready else ANALYSIS_CLI_FAILURE

        elif arguments.command == "stages":
            selected = arguments.names or None
            config = (
                load_analysis_cli_config(arguments.config, stdin=stdin)
                if arguments.config
                else None
            )
            payload = describe_analysis_pipeline(
                stages=selected,
                config=config,
                mode=arguments.mode,
            )
            code = ANALYSIS_CLI_SUCCESS

        elif arguments.command == "plan":
            config = load_analysis_cli_config(arguments.config, stdin=stdin)
            config = _analysis_cli_config_with_overrides(config, arguments)
            stages = _analysis_cli_requested_stages(arguments.stages)
            plan = build_analysis_execution_plan(
                config,
                requested_stages=(stages or None),
                analysis_mode=arguments.mode,
                strict=arguments.strict,
            )
            payload = plan.to_dict() if arguments.format == "json" else plan.summary()
            code = (
                ANALYSIS_CLI_SUCCESS
                if plan.structurally_ready
                else ANALYSIS_CLI_VALIDATION_FAILURE
            )

        elif arguments.command == "api":
            snapshot = inspect_analysis_api(
                detail=arguments.detail,
                include_capabilities=arguments.capabilities,
            )
            payload = (
                snapshot.to_dict()
                if arguments.format == "json"
                else snapshot.summary()
            )
            code = ANALYSIS_CLI_SUCCESS

        elif arguments.command == "validate":
            if arguments.api:
                errors = validate_analysis_public_api(raise_on_error=False)
                payload = {
                    "valid": not errors,
                    "errors": list(errors),
                    "public_name_count": len(__all__),
                }
                code = (
                    ANALYSIS_CLI_SUCCESS
                    if not errors
                    else ANALYSIS_CLI_VALIDATION_FAILURE
                )
            else:
                config = load_analysis_cli_config(arguments.config, stdin=stdin)
                if arguments.request:
                    request = load_analysis_cli_request(
                        arguments.request,
                        stdin=stdin,
                        config=config,
                    )
                    errors = list(validate_analysis_config(request.config))
                    if (
                        request.input_data is None
                        and request.receptor is None
                        and not request.poses
                        and not request.dock_models
                        and request.session is None
                    ):
                        errors.append(
                            "The request descriptor does not contain an analysis input."
                        )
                    payload = {
                        "valid": not errors,
                        "request": request.to_dict(),
                        "errors": errors,
                    }
                else:
                    errors = list(validate_analysis_config(config))
                    payload = {
                        "valid": not errors,
                        "config": config.to_dict(),
                        "errors": errors,
                    }
                code = (
                    ANALYSIS_CLI_SUCCESS
                    if not errors
                    else ANALYSIS_CLI_VALIDATION_FAILURE
                )

        elif arguments.command == "analyze":
            config = load_analysis_cli_config(arguments.config, stdin=stdin)
            config = _analysis_cli_config_with_overrides(config, arguments)
            request = load_analysis_cli_request(
                arguments.request,
                stdin=stdin,
                config=config,
            )
            stages = _analysis_cli_requested_stages(arguments.stages)
            unified = run_analysis(
                request,
                mode=arguments.mode,
                config=config,
                requested_stages=(stages or None),
            )
            payload = (
                unified.to_dict()
                if arguments.full_output or arguments.format == "json"
                else unified.summary()
            )
            code = _analysis_cli_exit_code(unified)

        else:  # pragma: no cover - protected by argparse
            raise AnalysisConfigurationError(
                f"Unsupported CLI command: {arguments.command!r}."
            )

        rendered = render_analysis_cli_payload(
            payload,
            output_format=arguments.format,
            indent=arguments.indent,
        )
        write_analysis_cli_output(
            rendered,
            path=arguments.output,
            stream=output_stream,
        )
        return code

    except AnalysisCancelledError as exc:
        error_stream.write(f"Analysis cancelled: {exc}\n")
        return ANALYSIS_CLI_CANCELLED
    except (AnalysisError, ValueError, TypeError, OSError) as exc:
        error_stream.write(f"Analysis command failed: {exc}\n")
        return ANALYSIS_CLI_FAILURE


def main(argv: Optional[Sequence[str]] = None) -> int:
    """Command-line entry point for the analysis module."""

    return analysis_cli(argv)


# 29.11. Validation and self-check
# -----------------------------------------------------------------------------

def validate_convenience_api_conventions() -> Dict[str, Any]:
    """Validate dispatch, facade, introspection and CLI conventions."""

    single = infer_analysis_dispatch(
        dock_model=DockModel(name="single"),
        config={"requested_stages": [STAGE_INPUT_RESOLUTION]},
    )
    if single.kind != ANALYSIS_DISPATCH_SINGLE_POSE:
        raise AssertionError("Single-pose dispatch inference failed.")

    multi = infer_analysis_dispatch(
        dock_models=(DockModel(name="a"), DockModel(name="b")),
    )
    if multi.kind != ANALYSIS_DISPATCH_MULTIPOSE or multi.pose_count != 2:
        raise AssertionError("Multipose dispatch inference failed.")

    request_a = create_analysis_request(input_data={"name": "a"})
    request_b = create_analysis_request(input_data={"name": "b"})
    batch = infer_analysis_dispatch(requests=(request_a, request_b))
    if batch.kind != ANALYSIS_DISPATCH_BATCH or batch.request_count != 2:
        raise AssertionError("Batch dispatch inference failed.")

    session = SimpleNamespace(models=SimpleNamespace(list=lambda: []))
    session_decision = infer_analysis_dispatch(session=session)
    if session_decision.kind != ANALYSIS_DISPATCH_CHIMERAX:
        raise AssertionError("ChimeraX dispatch inference failed.")

    parser = build_analysis_argument_parser()
    parsed = parser.parse_args(["api", "--detail", "summary", "--format", "json"])
    if parsed.command != "api" or parsed.detail != "summary":
        raise AssertionError("CLI argument parsing failed.")

    snapshot = inspect_analysis_api(detail="summary")
    if snapshot.find("analyze") is None:
        raise AssertionError("API introspection did not include analyze().")
    if snapshot.symbol_count != len(__all__):
        raise AssertionError("API snapshot has an inconsistent symbol count.")

    facade = DockAnalyzer(
        config={
            "requested_stages": [STAGE_INPUT_RESOLUTION],
            "runtime": {"failure_policy": FAILURE_POLICY_PERMISSIVE},
        },
        validate_results=False,
    )
    if facade.summary()["registered_stage_count"] <= 0:
        raise AssertionError("DockAnalyzer facade did not resolve the registry.")

    public_errors = validate_analysis_public_api(raise_on_error=False)
    if public_errors:
        raise AssertionError("; ".join(public_errors))

    encoded = unified_analysis_to_json(
        {
            "dispatch": single.to_dict(),
            "api": snapshot.summary(),
        }
    )
    json.loads(encoded)

    return {
        "valid": True,
        "schema": CONVENIENCE_API_SCHEMA_NAME,
        "schema_version": CONVENIENCE_API_SCHEMA_VERSION,
        "public_name_count": len(__all__),
        "registered_stage_count": len(registered_analysis_stages()),
        "dispatch_modes": list(ANALYSIS_DISPATCH_MODES),
        "cli_commands": list(ANALYSIS_CLI_COMMANDS),
        "validated_cases": 10,
    }


