# =============================================================================
# Section 30 — Self-tests
# =============================================================================

"""Built-in validation and regression tests for the analysis orchestrator.

The self-test framework is intentionally independent of pytest and unittest so
that it can run inside ordinary Python, optimized interpreters and constrained
ChimeraX environments. Tests are grouped by the architectural areas defined in
Sections 30.1 through 30.8 and may be selected by group, tag or name pattern.

Environmental limitations are reported separately from code failures. This
allows the final runner to distinguish an unavailable ChimeraX installation or
optional writer from an actual defect in the orchestration layer.
"""

# 30.1. Self-test infrastructure
# -----------------------------------------------------------------------------

SELF_TEST_SCHEMA_NAME: Final[str] = "dockanalyzer.analyze.self_test"
SELF_TEST_SCHEMA_VERSION: Final[str] = "1.0"
SELF_TEST_RESULT_TYPE: Final[str] = "analysis_self_test_result"
SELF_TEST_GROUP_RESULT_TYPE: Final[str] = "analysis_self_test_group_result"
SELF_TEST_REPORT_TYPE: Final[str] = "analysis_self_test_report"
SELF_TEST_DEFAULT_PATTERN: Final[str] = "*"
SELF_TEST_DEFAULT_INDENT: Final[int] = 2
SELF_TEST_MAX_TRACEBACK_LINES: Final[int] = 80
SELF_TEST_DEFAULT_FAIL_FAST: Final[bool] = False
SELF_TEST_DEFAULT_INCLUDE_ENVIRONMENTAL: Final[bool] = True
SELF_TEST_DEFAULT_STRICT_LIMITATIONS: Final[bool] = False
SELF_TEST_DEFAULT_FAST_MODE: Final[bool] = False
SELF_TEST_EXIT_SUCCESS: Final[int] = 0
SELF_TEST_EXIT_FAILURE: Final[int] = 1
SELF_TEST_EXIT_USAGE_ERROR: Final[int] = 2
SELF_TEST_EXIT_LIMITED: Final[int] = 3

SELF_TEST_GROUP_INFRASTRUCTURE: Final[str] = "30.1"
SELF_TEST_GROUP_CONFIGURATION: Final[str] = "30.2"
SELF_TEST_GROUP_REGISTRY_ADAPTERS: Final[str] = "30.3"
SELF_TEST_GROUP_SINGLE_POSE: Final[str] = "30.4"
SELF_TEST_GROUP_MULTIPOSE: Final[str] = "30.5"
SELF_TEST_GROUP_OUTPUTS: Final[str] = "30.6"
SELF_TEST_GROUP_VALIDATION_ENVIRONMENT: Final[str] = "30.7"
SELF_TEST_GROUP_FINAL_RUNNER: Final[str] = "30.8"

SELF_TEST_GROUPS: Final[Tuple[str, ...]] = (
    SELF_TEST_GROUP_INFRASTRUCTURE,
    SELF_TEST_GROUP_CONFIGURATION,
    SELF_TEST_GROUP_REGISTRY_ADAPTERS,
    SELF_TEST_GROUP_SINGLE_POSE,
    SELF_TEST_GROUP_MULTIPOSE,
    SELF_TEST_GROUP_OUTPUTS,
    SELF_TEST_GROUP_VALIDATION_ENVIRONMENT,
    SELF_TEST_GROUP_FINAL_RUNNER,
)

SELF_TEST_GROUP_TITLES: Final[Mapping[str, str]] = MappingProxyType(
    {
        SELF_TEST_GROUP_INFRASTRUCTURE: "Self-test infrastructure",
        SELF_TEST_GROUP_CONFIGURATION: (
            "Configuration, dependencies and input resolution"
        ),
        SELF_TEST_GROUP_REGISTRY_ADAPTERS: (
            "Registry and interaction adapters"
        ),
        SELF_TEST_GROUP_SINGLE_POSE: "Single-pose pipeline",
        SELF_TEST_GROUP_MULTIPOSE: "Multipose, batch and consensus",
        SELF_TEST_GROUP_OUTPUTS: (
            "Report, export and visualization integration"
        ),
        SELF_TEST_GROUP_VALIDATION_ENVIRONMENT: (
            "Validation, errors and environment compatibility"
        ),
        SELF_TEST_GROUP_FINAL_RUNNER: "Final runner",
    }
)

SELF_TEST_TAG_UNIT: Final[str] = "unit"
SELF_TEST_TAG_INTEGRATION: Final[str] = "integration"
SELF_TEST_TAG_REGRESSION: Final[str] = "regression"
SELF_TEST_TAG_ENVIRONMENT: Final[str] = "environment"
SELF_TEST_TAG_SERIALIZATION: Final[str] = "serialization"
SELF_TEST_TAG_PUBLIC_API: Final[str] = "public_api"
SELF_TEST_TAG_LANGUAGE: Final[str] = "language"
SELF_TEST_TAG_OPTIMIZED: Final[str] = "optimized"
SELF_TEST_TAG_FILESYSTEM: Final[str] = "filesystem"
SELF_TEST_TAG_CHIMERAX: Final[str] = "chimerax"

SELF_TEST_KNOWN_TAGS: Final[FrozenSet[str]] = frozenset(
    {
        SELF_TEST_TAG_UNIT,
        SELF_TEST_TAG_INTEGRATION,
        SELF_TEST_TAG_REGRESSION,
        SELF_TEST_TAG_ENVIRONMENT,
        SELF_TEST_TAG_SERIALIZATION,
        SELF_TEST_TAG_PUBLIC_API,
        SELF_TEST_TAG_LANGUAGE,
        SELF_TEST_TAG_OPTIMIZED,
        SELF_TEST_TAG_FILESYSTEM,
        SELF_TEST_TAG_CHIMERAX,
    }
)


class SelfTestStatus(str, Enum):
    """Outcome assigned to one self-test case."""

    PENDING = "pending"
    RUNNING = "running"
    PASSED = "passed"
    FAILED = "failed"
    ERROR = "error"
    SKIPPED = "skipped"
    LIMITED = "limited"


SELF_TEST_TERMINAL_STATUSES: Final[FrozenSet[SelfTestStatus]] = frozenset(
    {
        SelfTestStatus.PASSED,
        SelfTestStatus.FAILED,
        SelfTestStatus.ERROR,
        SelfTestStatus.SKIPPED,
        SelfTestStatus.LIMITED,
    }
)

SELF_TEST_FAILURE_STATUSES: Final[FrozenSet[SelfTestStatus]] = frozenset(
    {SelfTestStatus.FAILED, SelfTestStatus.ERROR}
)


class SelfTestError(AnalysisError):
    """Base exception raised by the built-in self-test framework."""


class SelfTestAssertionError(SelfTestError, AssertionError):
    """A self-test expectation was not satisfied."""


class SelfTestSkip(SelfTestError):
    """The selected self-test is not applicable to the current run."""


class SelfTestEnvironmentalLimitation(SelfTestError):
    """An external capability required by a test is unavailable."""


class SelfTestRegistrationError(SelfTestError):
    """A self-test case could not be registered consistently."""


SelfTestFunction: TypeAlias = Callable[["SelfTestContext"], Any]
SelfTestPredicate: TypeAlias = Callable[["SelfTestCase"], bool]


def canonicalize_self_test_group(value: Any) -> str:
    """Return a canonical Section 30 self-test group identifier."""

    text = str(value).strip().lower().replace("section", "").strip()
    text = text.replace("group", "").strip()
    if text in SELF_TEST_GROUPS:
        return text
    normalized_titles = {
        title.lower(): group for group, title in SELF_TEST_GROUP_TITLES.items()
    }
    if text in normalized_titles:
        return normalized_titles[text]
    if text.startswith("30.") and text[:4] in SELF_TEST_GROUPS:
        return text[:4]
    raise ValueError(f"Unknown self-test group: {value!r}.")


def canonicalize_self_test_status(value: Any) -> SelfTestStatus:
    """Return a canonical self-test status."""

    if isinstance(value, SelfTestStatus):
        return value
    text = str(value).strip().lower()
    aliases = {
        "pass": SelfTestStatus.PASSED,
        "success": SelfTestStatus.PASSED,
        "fail": SelfTestStatus.FAILED,
        "failure": SelfTestStatus.FAILED,
        "exception": SelfTestStatus.ERROR,
        "skip": SelfTestStatus.SKIPPED,
        "unavailable": SelfTestStatus.LIMITED,
        "environmental": SelfTestStatus.LIMITED,
    }
    if text in aliases:
        return aliases[text]
    try:
        return SelfTestStatus(text)
    except ValueError as exc:
        raise ValueError(f"Unknown self-test status: {value!r}.") from exc


def _self_test_glob_match(value: str, pattern: str) -> bool:
    """Match a test name using a small shell-style pattern subset."""

    escaped = re.escape(str(pattern or SELF_TEST_DEFAULT_PATTERN))
    expression = "^" + escaped.replace(r"\*", ".*").replace(r"\?", ".") + "$"
    return re.match(expression, str(value), flags=re.IGNORECASE) is not None


def _truncate_self_test_traceback(text: str) -> str:
    """Limit traceback output while preserving the most relevant tail."""

    lines = str(text or "").splitlines()
    if len(lines) <= SELF_TEST_MAX_TRACEBACK_LINES:
        return "\n".join(lines)
    omitted = len(lines) - SELF_TEST_MAX_TRACEBACK_LINES
    tail = lines[-SELF_TEST_MAX_TRACEBACK_LINES:]
    return "\n".join([f"... {omitted} traceback lines omitted ...", *tail])


@dataclass(frozen=True)
class SelfTestCase:
    """Declarative definition of one built-in self-test."""

    name: str
    group: str
    function: SelfTestFunction = field(repr=False, compare=False)
    description: str = ""
    order: int = 100
    tags: FrozenSet[str] = field(default_factory=frozenset)
    enabled: bool = True
    environmental: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        normalized_name = normalize_identifier(self.name, default="self_test")
        object.__setattr__(self, "name", normalized_name)
        object.__setattr__(self, "group", canonicalize_self_test_group(self.group))
        object.__setattr__(self, "description", normalize_text(self.description))
        object.__setattr__(self, "order", int(self.order))
        object.__setattr__(
            self,
            "tags",
            frozenset(normalize_identifier(tag) for tag in self.tags if str(tag).strip()),
        )
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))
        if not callable(self.function):
            raise TypeError("A self-test case requires a callable function.")

    @property
    def qualified_name(self) -> str:
        """Return the stable group-qualified name."""

        return f"{self.group}:{self.name}"

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable test definition."""

        return {
            "name": self.name,
            "qualified_name": self.qualified_name,
            "group": self.group,
            "group_title": SELF_TEST_GROUP_TITLES[self.group],
            "description": self.description,
            "order": self.order,
            "tags": sorted(self.tags),
            "enabled": self.enabled,
            "environmental": self.environmental,
            "metadata": to_json_compatible(dict(self.metadata)),
        }


@dataclass
class SelfTestContext:
    """Mutable execution context shared by selected self-tests."""

    run_id: str = field(default_factory=lambda: f"selftest-{time.time_ns():x}")
    fast: bool = SELF_TEST_DEFAULT_FAST_MODE
    strict_limitations: bool = SELF_TEST_DEFAULT_STRICT_LIMITATIONS
    include_environmental: bool = SELF_TEST_DEFAULT_INCLUDE_ENVIRONMENTAL
    fail_fast: bool = SELF_TEST_DEFAULT_FAIL_FAST
    root_directory: Optional[Path] = None
    selected_groups: Tuple[str, ...] = SELF_TEST_GROUPS
    selected_tags: FrozenSet[str] = field(default_factory=frozenset)
    name_pattern: str = SELF_TEST_DEFAULT_PATTERN
    metadata: Dict[str, Any] = field(default_factory=dict)
    shared: Dict[str, Any] = field(default_factory=dict)
    started_at: str = field(default_factory=_utc_timestamp)

    def __post_init__(self) -> None:
        self.selected_groups = tuple(
            canonicalize_self_test_group(group) for group in self.selected_groups
        )
        self.selected_tags = frozenset(
            normalize_identifier(tag) for tag in self.selected_tags if str(tag).strip()
        )
        self.name_pattern = str(self.name_pattern or SELF_TEST_DEFAULT_PATTERN)
        if self.root_directory is not None:
            self.root_directory = Path(self.root_directory)

    def group_directory(self, group: str) -> Optional[Path]:
        """Return and create the working directory for one group."""

        if self.root_directory is None:
            return None
        path = self.root_directory / canonicalize_self_test_group(group).replace(".", "_")
        path.mkdir(parents=True, exist_ok=True)
        return path

    def case_directory(self, case: SelfTestCase) -> Optional[Path]:
        """Return and create the working directory for one test case."""

        group_directory = self.group_directory(case.group)
        if group_directory is None:
            return None
        path = group_directory / case.name
        path.mkdir(parents=True, exist_ok=True)
        return path

    def to_dict(self) -> Dict[str, Any]:
        """Return serializable execution settings."""

        return {
            "run_id": self.run_id,
            "fast": self.fast,
            "strict_limitations": self.strict_limitations,
            "include_environmental": self.include_environmental,
            "fail_fast": self.fail_fast,
            "root_directory": str(self.root_directory) if self.root_directory else None,
            "selected_groups": list(self.selected_groups),
            "selected_tags": sorted(self.selected_tags),
            "name_pattern": self.name_pattern,
            "metadata": to_json_compatible(self.metadata),
            "started_at": self.started_at,
        }


@dataclass
class SelfTestResult:
    """Recorded outcome of one self-test case."""

    name: str
    group: str
    status: Union[SelfTestStatus, str]
    description: str = ""
    message: str = ""
    details: Dict[str, Any] = field(default_factory=dict)
    warnings: List[str] = field(default_factory=list)
    traceback_text: Optional[str] = None
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: float = 0.0
    tags: Tuple[str, ...] = ()
    environmental: bool = False
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = SELF_TEST_RESULT_TYPE

    def __post_init__(self) -> None:
        self.name = normalize_identifier(self.name, default="self_test")
        self.group = canonicalize_self_test_group(self.group)
        self.status = canonicalize_self_test_status(self.status)
        self.description = normalize_text(self.description)
        self.message = normalize_text(self.message)
        self.duration_seconds = max(0.0, float(self.duration_seconds or 0.0))
        self.tags = tuple(sorted({normalize_identifier(tag) for tag in self.tags}))
        if self.traceback_text:
            self.traceback_text = _truncate_self_test_traceback(self.traceback_text)

    @property
    def passed(self) -> bool:
        """Return whether the case passed."""

        return self.status is SelfTestStatus.PASSED

    @property
    def failed(self) -> bool:
        """Return whether the case represents a code failure."""

        return self.status in SELF_TEST_FAILURE_STATUSES

    @property
    def limited(self) -> bool:
        """Return whether the case was limited by the environment."""

        return self.status is SelfTestStatus.LIMITED

    @property
    def terminal(self) -> bool:
        """Return whether execution reached a terminal state."""

        return self.status in SELF_TEST_TERMINAL_STATUSES

    @property
    def qualified_name(self) -> str:
        """Return the stable group-qualified test name."""

        return f"{self.group}:{self.name}"

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable result."""

        return {
            "result_type": self.result_type,
            "name": self.name,
            "qualified_name": self.qualified_name,
            "group": self.group,
            "group_title": SELF_TEST_GROUP_TITLES[self.group],
            "status": self.status.value,
            "description": self.description,
            "message": self.message,
            "details": to_json_compatible(self.details),
            "warnings": list(self.warnings),
            "traceback": self.traceback_text,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "tags": list(self.tags),
            "environmental": self.environmental,
            "metadata": to_json_compatible(self.metadata),
        }


@dataclass
class SelfTestGroupResult:
    """Aggregate outcome for one Section 30 test group."""

    group: str
    results: List[SelfTestResult] = field(default_factory=list)
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: float = 0.0
    result_type: str = SELF_TEST_GROUP_RESULT_TYPE

    def __post_init__(self) -> None:
        self.group = canonicalize_self_test_group(self.group)
        self.duration_seconds = max(0.0, float(self.duration_seconds or 0.0))

    @property
    def counts(self) -> Dict[str, int]:
        """Return counts by status."""

        counts = Counter(result.status.value for result in self.results)
        return {status.value: int(counts.get(status.value, 0)) for status in SelfTestStatus}

    @property
    def passed(self) -> bool:
        """Return whether the group has no code failures."""

        return not any(result.failed for result in self.results)

    @property
    def limited(self) -> bool:
        """Return whether any test was environmentally limited."""

        return any(result.limited for result in self.results)

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable group result."""

        return {
            "result_type": self.result_type,
            "group": self.group,
            "title": SELF_TEST_GROUP_TITLES[self.group],
            "passed": self.passed,
            "limited": self.limited,
            "counts": self.counts,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "results": [result.to_dict() for result in self.results],
        }


@dataclass
class SelfTestReport:
    """Complete report returned by the final self-test runner."""

    run_id: str
    groups: List[SelfTestGroupResult] = field(default_factory=list)
    selected_case_count: int = 0
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_seconds: float = 0.0
    configuration: Dict[str, Any] = field(default_factory=dict)
    environment: Dict[str, Any] = field(default_factory=dict)
    metadata: Dict[str, Any] = field(default_factory=dict)
    result_type: str = SELF_TEST_REPORT_TYPE

    @property
    def results(self) -> List[SelfTestResult]:
        """Return all case results in execution order."""

        return [result for group in self.groups for result in group.results]

    @property
    def counts(self) -> Dict[str, int]:
        """Return aggregate counts by status."""

        counts = Counter(result.status.value for result in self.results)
        return {status.value: int(counts.get(status.value, 0)) for status in SelfTestStatus}

    @property
    def failed(self) -> bool:
        """Return whether any code failure occurred."""

        return any(result.failed for result in self.results)

    @property
    def limited(self) -> bool:
        """Return whether any environmental limitation occurred."""

        return any(result.limited for result in self.results)

    @property
    def passed(self) -> bool:
        """Return whether the report has no code failures."""

        return not self.failed

    def exit_code(self, *, strict_limitations: bool = False) -> int:
        """Return a process exit code for the report."""

        if self.failed:
            return SELF_TEST_EXIT_FAILURE
        if strict_limitations and self.limited:
            return SELF_TEST_EXIT_LIMITED
        return SELF_TEST_EXIT_SUCCESS

    def summary(self) -> Dict[str, Any]:
        """Return a compact report summary."""

        return {
            "run_id": self.run_id,
            "passed": self.passed,
            "failed": self.failed,
            "limited": self.limited,
            "selected_case_count": self.selected_case_count,
            "executed_case_count": len(self.results),
            "counts": self.counts,
            "duration_seconds": self.duration_seconds,
            "group_count": len(self.groups),
        }

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable report."""

        return {
            "result_type": self.result_type,
            "schema": SELF_TEST_SCHEMA_NAME,
            "schema_version": SELF_TEST_SCHEMA_VERSION,
            **self.summary(),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "configuration": to_json_compatible(self.configuration),
            "environment": to_json_compatible(self.environment),
            "metadata": to_json_compatible(self.metadata),
            "groups": [group.to_dict() for group in self.groups],
        }

    def to_json(self, *, indent: Optional[int] = SELF_TEST_DEFAULT_INDENT) -> str:
        """Return the complete report as JSON."""

        return json.dumps(self.to_dict(), indent=indent, sort_keys=True)


class SelfTestRegistry:
    """Thread-safe ordered registry of built-in self-test cases."""

    def __init__(self) -> None:
        self._cases: Dict[str, SelfTestCase] = {}
        self._generation = 0
        self._lock = threading.RLock()

    @property
    def generation(self) -> int:
        """Return the registry generation."""

        with self._lock:
            return self._generation

    def register(self, case: SelfTestCase, *, replace_existing: bool = False) -> None:
        """Register one case."""

        key = case.qualified_name
        with self._lock:
            if key in self._cases and not replace_existing:
                raise SelfTestRegistrationError(
                    f"Self-test case {key!r} is already registered."
                )
            self._cases[key] = case
            self._generation += 1

    def unregister(self, name: str, *, group: Optional[str] = None) -> bool:
        """Remove one registered case."""

        normalized_name = normalize_identifier(name, default="self_test")
        with self._lock:
            if group is not None:
                key = f"{canonicalize_self_test_group(group)}:{normalized_name}"
                removed = self._cases.pop(key, None) is not None
            else:
                matches = [
                    key for key, case in self._cases.items()
                    if case.name == normalized_name
                ]
                if len(matches) > 1:
                    raise SelfTestRegistrationError(
                        f"Self-test name {normalized_name!r} exists in multiple groups."
                    )
                removed = bool(matches and self._cases.pop(matches[0], None))
            if removed:
                self._generation += 1
            return removed

    def clear(self) -> None:
        """Remove all registered cases."""

        with self._lock:
            self._cases.clear()
            self._generation += 1

    def get(self, name: str, *, group: Optional[str] = None) -> SelfTestCase:
        """Return one registered case."""

        normalized_name = normalize_identifier(name, default="self_test")
        with self._lock:
            if group is not None:
                key = f"{canonicalize_self_test_group(group)}:{normalized_name}"
                try:
                    return self._cases[key]
                except KeyError as exc:
                    raise KeyError(f"Unknown self-test case: {key!r}.") from exc
            matches = [case for case in self._cases.values() if case.name == normalized_name]
            if not matches:
                raise KeyError(f"Unknown self-test case: {normalized_name!r}.")
            if len(matches) > 1:
                raise KeyError(
                    f"Self-test name {normalized_name!r} is ambiguous; provide a group."
                )
            return matches[0]

    def cases(self) -> Tuple[SelfTestCase, ...]:
        """Return all cases in deterministic execution order."""

        with self._lock:
            return tuple(
                sorted(
                    self._cases.values(),
                    key=lambda case: (
                        SELF_TEST_GROUPS.index(case.group),
                        case.order,
                        case.name,
                    ),
                )
            )

    def select(
        self,
        *,
        groups: Optional[Iterable[str]] = None,
        tags: Optional[Iterable[str]] = None,
        pattern: str = SELF_TEST_DEFAULT_PATTERN,
        include_disabled: bool = False,
        include_environmental: bool = True,
        predicate: Optional[SelfTestPredicate] = None,
    ) -> Tuple[SelfTestCase, ...]:
        """Select cases by group, tags, pattern and predicate."""

        selected_groups = (
            frozenset(canonicalize_self_test_group(group) for group in groups)
            if groups is not None
            else frozenset(SELF_TEST_GROUPS)
        )
        selected_tags = frozenset(
            normalize_identifier(tag) for tag in (tags or ()) if str(tag).strip()
        )
        cases: List[SelfTestCase] = []
        for case in self.cases():
            if case.group not in selected_groups:
                continue
            if not include_disabled and not case.enabled:
                continue
            if not include_environmental and case.environmental:
                continue
            if selected_tags and not selected_tags.issubset(case.tags):
                continue
            if not (
                _self_test_glob_match(case.name, pattern)
                or _self_test_glob_match(case.qualified_name, pattern)
            ):
                continue
            if predicate is not None and not predicate(case):
                continue
            cases.append(case)
        return tuple(cases)

    def snapshot(self) -> Dict[str, Any]:
        """Return a serializable registry snapshot."""

        cases = self.cases()
        return {
            "schema": SELF_TEST_SCHEMA_NAME,
            "schema_version": SELF_TEST_SCHEMA_VERSION,
            "generation": self.generation,
            "case_count": len(cases),
            "groups": {
                group: sum(case.group == group for case in cases)
                for group in SELF_TEST_GROUPS
            },
            "cases": [case.to_dict() for case in cases],
        }


_DEFAULT_SELF_TEST_REGISTRY = SelfTestRegistry()


def get_self_test_registry() -> SelfTestRegistry:
    """Return the process-wide built-in self-test registry."""

    return _DEFAULT_SELF_TEST_REGISTRY


def register_self_test(
    name: str,
    *,
    group: str,
    description: str = "",
    order: int = 100,
    tags: Iterable[str] = (),
    enabled: bool = True,
    environmental: bool = False,
    registry: Optional[SelfTestRegistry] = None,
    replace_existing: bool = False,
) -> Callable[[SelfTestFunction], SelfTestFunction]:
    """Decorate and register a built-in self-test function."""

    target_registry = registry or get_self_test_registry()

    def decorator(function: SelfTestFunction) -> SelfTestFunction:
        case = SelfTestCase(
            name=name,
            group=group,
            function=function,
            description=description,
            order=order,
            tags=frozenset(tags),
            enabled=enabled,
            environmental=environmental,
        )
        target_registry.register(case, replace_existing=replace_existing)
        return function

    return decorator


def assert_self_test(condition: Any, message: str = "Self-test assertion failed.") -> None:
    """Raise a structured self-test assertion when a condition is false."""

    if not condition:
        raise SelfTestAssertionError(message)


def assert_self_test_equal(actual: Any, expected: Any, message: str = "") -> None:
    """Assert equality with a readable failure message."""

    if actual != expected:
        suffix = f" {message}" if message else ""
        raise SelfTestAssertionError(
            f"Expected {expected!r}, received {actual!r}.{suffix}"
        )


def assert_self_test_in(member: Any, container_value: Any, message: str = "") -> None:
    """Assert membership with a readable failure message."""

    if member not in container_value:
        suffix = f" {message}" if message else ""
        raise SelfTestAssertionError(
            f"Expected {member!r} to be present in {container_value!r}.{suffix}"
        )


def assert_self_test_raises(
    exception_types: Union[type[BaseException], Tuple[type[BaseException], ...]],
    function: Callable[..., Any],
    *args: Any,
    **kwargs: Any,
) -> BaseException:
    """Assert that a callable raises one of the expected exception types."""

    try:
        function(*args, **kwargs)
    except exception_types as exc:
        return exc
    except BaseException as exc:
        raise SelfTestAssertionError(
            f"Expected {exception_types!r}, received {type(exc).__name__}."
        ) from exc
    raise SelfTestAssertionError(
        f"Expected {exception_types!r}, but no exception was raised."
    )


def skip_self_test(reason: str) -> None:
    """Skip the current self-test."""

    raise SelfTestSkip(reason)


def limit_self_test(reason: str) -> None:
    """Mark the current self-test as environmentally limited."""

    raise SelfTestEnvironmentalLimitation(reason)


def _normalize_self_test_details(value: Any) -> Dict[str, Any]:
    """Normalize a test return value into result details."""

    if value is None:
        return {}
    if isinstance(value, Mapping):
        return dict(value)
    if is_dataclass(value):
        return dict(asdict(value))
    return {"value": to_json_compatible(value)}


def run_self_test_case(case: SelfTestCase, context: SelfTestContext) -> SelfTestResult:
    """Execute one self-test case and classify its outcome."""

    started_at = _utc_timestamp()
    started_clock = time.perf_counter()
    status = SelfTestStatus.PASSED
    message = "Passed."
    details: Dict[str, Any] = {}
    captured_warning_messages: List[str] = []
    traceback_text: Optional[str] = None

    if not case.enabled:
        status = SelfTestStatus.SKIPPED
        message = "The self-test case is disabled."
    elif case.environmental and not context.include_environmental:
        status = SelfTestStatus.SKIPPED
        message = "Environmental tests were excluded from this run."
    else:
        try:
            case_directory = context.case_directory(case)
            context.shared["current_case"] = case.qualified_name
            context.shared["current_case_directory"] = case_directory
            with warnings.catch_warnings(record=True) as captured:
                warnings.simplefilter("always")
                details = _normalize_self_test_details(case.function(context))
            captured_warning_messages = [
                f"{item.category.__name__}: {item.message}" for item in captured
            ]
        except SelfTestSkip as exc:
            status = SelfTestStatus.SKIPPED
            message = str(exc) or "Skipped."
        except SelfTestEnvironmentalLimitation as exc:
            status = SelfTestStatus.LIMITED
            message = str(exc) or "Environmentally limited."
            details = dict(getattr(exc, "details", {}) or {})
        except (SelfTestAssertionError, AssertionError) as exc:
            status = SelfTestStatus.FAILED
            message = str(exc) or "Assertion failed."
            traceback_text = traceback.format_exc()
        except BaseException as exc:
            status = SelfTestStatus.ERROR
            message = f"{type(exc).__name__}: {exc}"
            traceback_text = traceback.format_exc()

    finished_at = _utc_timestamp()
    duration_seconds = max(0.0, time.perf_counter() - started_clock)
    return SelfTestResult(
        name=case.name,
        group=case.group,
        status=status,
        description=case.description,
        message=message,
        details=details,
        warnings=captured_warning_messages,
        traceback_text=traceback_text,
        started_at=started_at,
        finished_at=finished_at,
        duration_seconds=duration_seconds,
        tags=tuple(case.tags),
        environmental=case.environmental,
        metadata={"order": case.order, **dict(case.metadata)},
    )


def run_self_test_group(
    group: str,
    *,
    context: Optional[SelfTestContext] = None,
    registry: Optional[SelfTestRegistry] = None,
    tags: Optional[Iterable[str]] = None,
    pattern: str = SELF_TEST_DEFAULT_PATTERN,
) -> SelfTestGroupResult:
    """Execute one Section 30 self-test group."""

    canonical_group = canonicalize_self_test_group(group)
    active_context = context or SelfTestContext(selected_groups=(canonical_group,))
    active_registry = registry or get_self_test_registry()
    cases = active_registry.select(
        groups=(canonical_group,),
        tags=tags,
        pattern=pattern,
        include_environmental=active_context.include_environmental,
    )
    started_at = _utc_timestamp()
    started_clock = time.perf_counter()
    results: List[SelfTestResult] = []
    for case in cases:
        result = run_self_test_case(case, active_context)
        results.append(result)
        if active_context.fail_fast and result.failed:
            break
    return SelfTestGroupResult(
        group=canonical_group,
        results=results,
        started_at=started_at,
        finished_at=_utc_timestamp(),
        duration_seconds=time.perf_counter() - started_clock,
    )


def _self_test_environment_summary() -> Dict[str, Any]:
    """Return stable runtime details for the self-test report."""

    return {
        "python_version": platform.python_version(),
        "python_implementation": platform.python_implementation(),
        "optimize_level": int(getattr(sys.flags, "optimize", 0)),
        "platform": platform.platform(),
        "module_version": __version__,
        "numpy_available": NUMPY_AVAILABLE,
        "chimerax_available": CHIMERAX_AVAILABLE,
        "registered_stage_count": len(registered_analysis_stages()),
        "public_name_count": len(__all__),
    }


def run_analyze_self_tests(
    *,
    groups: Optional[Iterable[str]] = None,
    tags: Optional[Iterable[str]] = None,
    pattern: str = SELF_TEST_DEFAULT_PATTERN,
    fast: bool = SELF_TEST_DEFAULT_FAST_MODE,
    fail_fast: bool = SELF_TEST_DEFAULT_FAIL_FAST,
    include_environmental: bool = SELF_TEST_DEFAULT_INCLUDE_ENVIRONMENTAL,
    strict_limitations: bool = SELF_TEST_DEFAULT_STRICT_LIMITATIONS,
    registry: Optional[SelfTestRegistry] = None,
    root_directory: Optional[PathLike] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> SelfTestReport:
    """Execute selected built-in self-tests and return a complete report."""

    active_registry = registry or get_self_test_registry()
    selected_groups = tuple(
        canonicalize_self_test_group(group) for group in (groups or SELF_TEST_GROUPS)
    )
    selected_tags = frozenset(tags or ())
    selected_cases = active_registry.select(
        groups=selected_groups,
        tags=selected_tags,
        pattern=pattern,
        include_environmental=include_environmental,
    )
    started_at = _utc_timestamp()
    started_clock = time.perf_counter()

    def execute(root: Path) -> SelfTestReport:
        context = SelfTestContext(
            fast=fast,
            strict_limitations=strict_limitations,
            include_environmental=include_environmental,
            fail_fast=fail_fast,
            root_directory=root,
            selected_groups=selected_groups,
            selected_tags=selected_tags,
            name_pattern=pattern,
            metadata=dict(metadata or {}),
        )
        group_results: List[SelfTestGroupResult] = []
        for group in selected_groups:
            group_result = run_self_test_group(
                group,
                context=context,
                registry=active_registry,
                tags=selected_tags,
                pattern=pattern,
            )
            group_results.append(group_result)
            if fail_fast and not group_result.passed:
                break
        return SelfTestReport(
            run_id=context.run_id,
            groups=group_results,
            selected_case_count=len(selected_cases),
            started_at=started_at,
            finished_at=_utc_timestamp(),
            duration_seconds=time.perf_counter() - started_clock,
            configuration=context.to_dict(),
            environment=_self_test_environment_summary(),
            metadata=dict(metadata or {}),
        )

    if root_directory is not None:
        root = Path(root_directory)
        root.mkdir(parents=True, exist_ok=True)
        return execute(root)
    with TemporaryDirectory(prefix="dockanalyzer-analyze-selftest-") as temporary:
        return execute(Path(temporary))


def render_self_test_report(
    report: SelfTestReport,
    *,
    verbose: bool = False,
) -> str:
    """Render a readable plain-text self-test report."""

    lines = [
        "DockAnalyzer analyze.py self-test report",
        f"Run ID: {report.run_id}",
        f"Status: {'PASSED' if report.passed else 'FAILED'}",
        f"Duration: {report.duration_seconds:.3f} s",
        f"Cases: {len(report.results)} / {report.selected_case_count}",
    ]
    counts = report.counts
    lines.append(
        "Results: "
        + ", ".join(
            f"{status.value}={counts[status.value]}" for status in SelfTestStatus
            if counts[status.value]
        )
    )
    for group in report.groups:
        marker = "PASS" if group.passed else "FAIL"
        if group.passed and group.limited:
            marker = "LIMITED"
        lines.append(
            f"[{marker}] {group.group} {SELF_TEST_GROUP_TITLES[group.group]} "
            f"({len(group.results)} cases, {group.duration_seconds:.3f} s)"
        )
        if verbose:
            for result in group.results:
                lines.append(
                    f"  - {result.status.value.upper():7s} "
                    f"{result.name} ({result.duration_seconds:.3f} s)"
                )
                if result.message and result.message != "Passed.":
                    lines.append(f"      {result.message}")
    return "\n".join(lines)


def self_test_report_to_json(
    report: SelfTestReport,
    *,
    indent: Optional[int] = SELF_TEST_DEFAULT_INDENT,
) -> str:
    """Serialize a self-test report as JSON."""

    return report.to_json(indent=indent)



@register_self_test(
    "framework_primitives",
    group=SELF_TEST_GROUP_INFRASTRUCTURE,
    description="Validate registry, assertions, case execution and report primitives.",
    order=10,
    tags=(SELF_TEST_TAG_UNIT, SELF_TEST_TAG_SERIALIZATION),
)
def _self_test_framework_primitives(
    context: SelfTestContext,
) -> Dict[str, Any]:
    registry = SelfTestRegistry()

    def probe(_context: SelfTestContext) -> Dict[str, Any]:
        return {"probe": True}

    case = SelfTestCase(
        name="probe",
        group=SELF_TEST_GROUP_INFRASTRUCTURE,
        function=probe,
        tags=frozenset({SELF_TEST_TAG_UNIT}),
    )
    registry.register(case)
    selected = registry.select(groups=(SELF_TEST_GROUP_INFRASTRUCTURE,))
    assert_self_test_equal(len(selected), 1)
    result = run_self_test_case(case, context)
    assert_self_test(result.passed, result.message)
    report = SelfTestReport(
        run_id="framework-probe",
        groups=[
            SelfTestGroupResult(
                group=SELF_TEST_GROUP_INFRASTRUCTURE,
                results=[result],
            )
        ],
        selected_case_count=1,
    )
    json.loads(report.to_json())
    assert_self_test_in("framework-probe", render_self_test_report(report))
    assert_self_test(registry.unregister("probe"))
    return {
        "registry_generation": registry.generation,
        "result_status": result.status.value,
        "report_passed": report.passed,
    }

