def _execute_named_convention_validator(
    validator_name: str,
) -> Dict[str, Any]:
    """Execute one existing section convention validator by name."""

    validator = globals().get(validator_name)
    if not callable(validator):
        raise SelfTestAssertionError(
            f"Convention validator {validator_name!r} is not available."
        )
    signature = inspect.signature(validator)
    required = [
        parameter
        for parameter in signature.parameters.values()
        if parameter.default is inspect.Parameter.empty
        and parameter.kind
        in {inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD}
    ]
    if required:
        raise SelfTestAssertionError(
            f"Convention validator {validator_name!r} requires unsupported arguments."
        )
    try:
        value = validator()
    except (AnalysisDependencyError, AnalysisCapabilityError) as exc:
        raise SelfTestEnvironmentalLimitation(
            f"{validator_name} requires an unavailable DockAnalyzer component: {exc}",
            details={
                "validator": validator_name,
                "dependency_error": type(exc).__name__,
                "dependency_message": str(exc),
            },
            cause=exc,
        ) from exc
    except ModuleNotFoundError as exc:
        missing_root = str(exc.name or "").split(".", 1)[0]
        internal_modules = set(KNOWN_ANALYSIS_MODULES) | {"config", "utils"}
        if missing_root in internal_modules:
            raise SelfTestEnvironmentalLimitation(
                f"{validator_name} requires unavailable module {exc.name!r}.",
                details={
                    "validator": validator_name,
                    "missing_module": exc.name,
                },
                cause=exc,
            ) from exc
        raise
    details = _normalize_self_test_details(value)
    details.setdefault("validator", validator_name)
    details.setdefault("valid", True)
    return details


def _make_convention_self_test(validator_name: str) -> SelfTestFunction:
    """Create a self-test wrapper for one convention validator."""

    def test(_context: SelfTestContext) -> Dict[str, Any]:
        return _execute_named_convention_validator(validator_name)

    test.__name__ = f"self_test_{validator_name}"
    test.__doc__ = f"Execute {validator_name}."
    return test


for _self_test_group, _validator_names in _SELF_TEST_VALIDATOR_GROUPS.items():
    for _validator_index, _validator_name in enumerate(_validator_names, start=1):
        get_self_test_registry().register(
            SelfTestCase(
                name=_validator_name.removeprefix("validate_").removesuffix(
                    "_conventions"
                ),
                group=_self_test_group,
                function=_make_convention_self_test(_validator_name),
                description=f"Run the cumulative checks defined by {_validator_name}.",
                order=100 + _validator_index,
                tags=frozenset(
                    {
                        SELF_TEST_TAG_REGRESSION,
                        SELF_TEST_TAG_INTEGRATION,
                        *(
                            (SELF_TEST_TAG_ENVIRONMENT,)
                            if _validator_name in _SELF_TEST_ENVIRONMENTAL_VALIDATORS
                            else ()
                        ),
                    }
                ),
                environmental=(
                    _validator_name in _SELF_TEST_ENVIRONMENTAL_VALIDATORS
                ),
            )
        )


