@register_self_test(
    "stage_registry_integrity",
    group=SELF_TEST_GROUP_REGISTRY_ADAPTERS,
    description="Verify canonical stages, executors and dependency ordering.",
    order=10,
    tags=(SELF_TEST_TAG_UNIT, SELF_TEST_TAG_PUBLIC_API),
)
def _self_test_stage_registry_integrity(
    _context: SelfTestContext,
) -> Dict[str, Any]:
    registry = get_default_stage_registry()
    stages = registry.names()
    assert_self_test_equal(tuple(stages), registered_analysis_stages())
    executor_optional_stages = {
        STAGE_INPUT_RESOLUTION,
        STAGE_MODEL_PREPARATION,
        STAGE_FINALIZATION,
    }
    for stage in PIPELINE_STAGE_ORDER:
        assert_self_test_in(stage, stages)
        definition = registry.get(stage)
        if stage not in executor_optional_stages:
            assert_self_test(
                definition.executor is not None,
                f"Stage {stage!r} has no registered executor.",
            )
    plan = build_analysis_execution_plan(
        AnalysisConfig(
            requested_stages=(STAGE_SCORING,),
            enable_scoring=True,
            include_internal_stages=True,
        ),
        registry=registry,
        analysis_mode=ANALYSIS_MODE_SINGLE_POSE,
        inspect_capabilities=False,
        require_registered_executors=False,
        strict=False,
    )
    assert_self_test_in(STAGE_SCORING, plan.stages)
    assert_self_test_in(STAGE_CONSOLIDATION, plan.stages)
    return {
        "registered_stage_count": len(stages),
        "planned_stages": list(plan.stages),
        "waves": [list(wave) for wave in plan.waves],
    }


