@register_self_test(
    "single_pose_result_lifecycle",
    group=SELF_TEST_GROUP_SINGLE_POSE,
    description="Validate lifecycle, serialization and diagnostics for one pose.",
    order=10,
    tags=(SELF_TEST_TAG_UNIT, SELF_TEST_TAG_SERIALIZATION),
)
def _self_test_single_pose_result_lifecycle(
    _context: SelfTestContext,
) -> Dict[str, Any]:
    model = DockModel(name="self_test_pose")
    result = PoseAnalysisResult(
        name="self_test_pose",
        dock_model=model,
        status=AnalysisStatus.RUNNING,
    )
    stage = AnalysisStageResult(stage=STAGE_CONTACTS)
    stage.start()
    stage.statistics["contact_count"] = 0
    stage.succeed(value=[])
    result.add_stage_result(stage)
    result.finalize(status=AnalysisStatus.SUCCEEDED)
    payload = result.to_dict()
    json.dumps(to_json_compatible(payload), sort_keys=True)
