@register_self_test(
    "section_continuity",
    group=SELF_TEST_GROUP_FINAL_RUNNER,
    description="Verify all thirty section boundaries are present and ordered.",
    order=20,
    tags=(SELF_TEST_TAG_REGRESSION, SELF_TEST_TAG_PUBLIC_API),
)
def _self_test_section_continuity(
    _context: SelfTestContext,
) -> Dict[str, Any]:
    source_text = Path(__file__).read_text(encoding="utf-8")
    starts: List[int] = []
    ends: List[int] = []
    for section_number in range(1, 31):
        start_marker = f"# Section {section_number} —"
        end_marker = f"# End of Section {section_number}"
        start_index = source_text.find(start_marker)
        end_index = source_text.find(end_marker)
        assert_self_test(start_index >= 0, f"Missing {start_marker!r}.")
        assert_self_test(end_index >= 0, f"Missing {end_marker!r}.")
        assert_self_test(start_index < end_index, f"Invalid boundary for Section {section_number}.")
        starts.append(start_index)
        ends.append(end_index)
    assert_self_test_equal(starts, sorted(starts), "Section starts are not ordered.")
    assert_self_test_equal(ends, sorted(ends), "Section ends are not ordered.")
    return {"section_count": 30, "first_offset": starts[0], "last_offset": ends[-1]}


