def validate_self_test_conventions() -> Dict[str, Any]:
    """Validate the Section 30 framework without running all integration tests."""

    registry = get_self_test_registry()
    cases = registry.cases()
    assert_self_test(cases, "No built-in self-tests are registered.")
    qualified_names = [case.qualified_name for case in cases]
    assert_self_test_equal(
        len(qualified_names),
        len(set(qualified_names)),
        "Self-test registry contains duplicate qualified names.",
    )
    present_groups = {case.group for case in cases}
    assert_self_test_equal(
        present_groups,
        set(SELF_TEST_GROUPS),
        "At least one Section 30 self-test group has no registered cases.",
    )
    for case in cases:
        assert_self_test(case.group in SELF_TEST_GROUPS)
        assert_self_test(callable(case.function))
        assert_self_test(case.tags.issubset(SELF_TEST_KNOWN_TAGS))

    probe_registry = SelfTestRegistry()

    def probe(_context: SelfTestContext) -> Dict[str, Any]:
        return {"valid": True}

    probe_case = SelfTestCase(
        name="probe",
        group=SELF_TEST_GROUP_INFRASTRUCTURE,
        function=probe,
        tags=frozenset({SELF_TEST_TAG_UNIT}),
    )
    probe_registry.register(probe_case)
    assert_self_test_equal(len(probe_registry.cases()), 1)
    assert_self_test_equal(probe_registry.get("probe").name, "probe")
    assert_self_test(probe_registry.unregister("probe"))
    assert_self_test_equal(len(probe_registry.cases()), 0)

    with TemporaryDirectory(prefix="dockanalyzer-selftest-framework-") as temporary:
        context = SelfTestContext(
            root_directory=Path(temporary),
            selected_groups=(SELF_TEST_GROUP_INFRASTRUCTURE,),
        )
        result = run_self_test_case(probe_case, context)
        assert_self_test(result.passed, result.message)
        json.loads(json.dumps(result.to_dict()))

    return {
        "valid": True,
        "schema": SELF_TEST_SCHEMA_NAME,
        "schema_version": SELF_TEST_SCHEMA_VERSION,
        "registered_case_count": len(cases),
        "group_counts": {
            group: sum(case.group == group for case in cases)
            for group in SELF_TEST_GROUPS
        },
        "registry_generation": registry.generation,
    }


def build_self_test_argument_parser() -> argparse.ArgumentParser:
    """Create the command-line parser for the final self-test runner."""

    parser = argparse.ArgumentParser(
        prog=f"{ANALYSIS_CLI_PROGRAM_NAME} self-test",
        description="Run the built-in analyze.py self-tests.",
    )
    parser.add_argument(
        "--group",
        action="append",
        choices=SELF_TEST_GROUPS,
        dest="groups",
        help="Run only the selected Section 30 group. May be repeated.",
    )
    parser.add_argument(
        "--tag",
        action="append",
        choices=sorted(SELF_TEST_KNOWN_TAGS),
        dest="tags",
        help="Require a self-test tag. May be repeated.",
    )
    parser.add_argument(
        "--pattern",
        default=SELF_TEST_DEFAULT_PATTERN,
        help="Shell-style pattern applied to case names.",
    )
    parser.add_argument("--fast", action="store_true", help="Enable fast mode.")
    parser.add_argument(
        "--fail-fast",
        action="store_true",
        help="Stop after the first code failure.",
    )
    parser.add_argument(
        "--exclude-environmental",
        action="store_true",
        help="Exclude tests that depend on environment capabilities.",
    )
    parser.add_argument(
        "--strict-limitations",
        action="store_true",
        help="Return a distinct nonzero code for environmental limitations.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        dest="json_output",
        help="Render the complete report as JSON.",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="Show each individual case in text output.",
    )
    parser.add_argument(
        "--output",
        type=Path,
        help="Write the rendered report to this path.",
    )
    parser.add_argument(
        "--list",
        action="store_true",
        dest="list_cases",
        help="List selected self-test cases without executing them.",
    )
    return parser


def analysis_self_test_cli(
    argv: Optional[Sequence[str]] = None,
    *,
    stream: Optional[TextIO] = None,
) -> int:
    """Run the Section 30 self-test command-line interface."""

    parser = build_self_test_argument_parser()
    namespace = parser.parse_args(list(argv) if argv is not None else None)
    output_stream = stream or sys.stdout
    registry = get_self_test_registry()
    selected = registry.select(
        groups=namespace.groups,
        tags=namespace.tags,
        pattern=namespace.pattern,
        include_environmental=not namespace.exclude_environmental,
    )
    if namespace.list_cases:
        payload = [case.to_dict() for case in selected]
        rendered = (
            json.dumps(payload, indent=SELF_TEST_DEFAULT_INDENT, sort_keys=True)
            if namespace.json_output
            else "\n".join(
                f"{case.qualified_name} — {case.description}" for case in selected
            )
        )
        output_stream.write(rendered + ("" if rendered.endswith("\n") else "\n"))
        return SELF_TEST_EXIT_SUCCESS

    report = run_analyze_self_tests(
        groups=namespace.groups,
        tags=namespace.tags,
        pattern=namespace.pattern,
        fast=namespace.fast,
        fail_fast=namespace.fail_fast,
        include_environmental=not namespace.exclude_environmental,
        strict_limitations=namespace.strict_limitations,
    )
    rendered = (
        self_test_report_to_json(report)
        if namespace.json_output
        else render_self_test_report(report, verbose=namespace.verbose)
    )
    if namespace.output is not None:
        namespace.output.parent.mkdir(parents=True, exist_ok=True)
        namespace.output.write_text(rendered + "\n", encoding="utf-8")
    output_stream.write(rendered + ("" if rendered.endswith("\n") else "\n"))
    return report.exit_code(strict_limitations=namespace.strict_limitations)


def run_final_self_test_runner(
    *,
    fast: bool = False,
    include_environmental: bool = True,
    fail_fast: bool = False,
) -> SelfTestReport:
    """Execute all Section 30 self-test groups."""

    return run_analyze_self_tests(
        groups=SELF_TEST_GROUPS,
        fast=fast,
        include_environmental=include_environmental,
        fail_fast=fail_fast,
    )


